# Los nombres de la tabla y de las columnas que se estan leyendo: lo unico de la
# consulta que el mensaje del motor puede citar en claro, porque el resto de la
# salida ya los publica. Los fija `perfilar_dbi()` mientras corre -y
# `perfilar_coleccion()`, los de sus tablas- y los devuelve al salir.
.CONTEXTO_MOTOR <- new.env(parent = emptyenv())

.identificadores_motor <- function() {
  identificadores <- .CONTEXTO_MOTOR$identificadores
  if (is.null(identificadores)) character() else identificadores
}

.fijar_identificadores_motor <- function(identificadores) {
  previos <- .CONTEXTO_MOTOR$identificadores
  .CONTEXTO_MOTOR$identificadores <- identificadores
  invisible(previos)
}

# Los centros que la corrida escribio en el SQL: la media de una columna como
# literal, para restarla en el desvio centrado y en las sumas exactas de un
# decimal. Salen de los datos, y con `incluir_valores = FALSE` el SQL que se
# publica los lleva tapados (`.tapar_centros_sql_dbi()`). Los junta
# `perfilar_dbi()` mientras corre; fuera de una corrida no se guarda nada.
.activar_centros_motor <- function() {
  previos <- .CONTEXTO_MOTOR$centros
  .CONTEXTO_MOTOR$centros <- character()
  invisible(previos)
}

.fijar_centros_motor <- function(centros) {
  .CONTEXTO_MOTOR$centros <- centros
  invisible(NULL)
}

.sumar_centro_motor <- function(literal) {
  if (is.null(.CONTEXTO_MOTOR$centros) || !length(literal)) {
    return(invisible(NULL))
  }
  literal <- as.character(literal)
  literal <- literal[!is.na(literal) & nzchar(literal)]
  if (length(literal)) {
    .CONTEXTO_MOTOR$centros <- unique(c(.CONTEXTO_MOTOR$centros, literal))
  }
  invisible(NULL)
}

# El SQL con cada centro tapado, en las formas en que se resta: `x - c)`,
# `x - (c)` y `x - (c / NULLIF(`. Una constante del SQL que no sea un centro no
# cambia.
.tapar_centros_sql_dbi <- function(sql, centros = .CONTEXTO_MOTOR$centros) {
  if (!length(centros) || !length(sql)) return(sql)
  centros <- centros[.orden_por_bytes(-nchar(centros, type = "bytes"))]
  tapado <- .LITERAL_MOTOR_OMITIDO
  for (literal in centros) {
    for (forma in c(" - %s)", " - (%s)", " - (%s / NULLIF(")) {
      sql <- gsub(sprintf(forma, literal), sprintf(forma, tapado), sql,
                  fixed = TRUE, useBytes = TRUE)
    }
  }
  sql
}

# Suma `nuevos` a los que ya hay y devuelve los de antes, para reponerlos con
# `.fijar_identificadores_motor()` en `on.exit()`.
.sumar_identificadores_motor <- function(nuevos) {
  previos <- .CONTEXTO_MOTOR$identificadores
  nuevos <- tryCatch(as.character(unlist(nuevos, use.names = FALSE)),
                     error = function(e) character())
  partes <- unlist(strsplit(nuevos[!is.na(nuevos)], ".", fixed = TRUE),
                   use.names = FALSE)
  todos <- unique(c(previos, nuevos, partes))
  .CONTEXTO_MOTOR$identificadores <- todos[!is.na(todos) & nzchar(todos)]
  invisible(previos)
}

# Y si la llamada PROTEGE. El cometido principal del paquete es el diagnostico
# de la calidad de los datos, y una proteccion que cuesta diagnostico
# importante no va por omision. El
# mensaje del motor cita la celda que hizo fallar la lectura -`Conversion
# failed when converting the nvarchar value 'N/D' to data type int`, un
# faltante disfrazado: el diagnostico mismo- y el SQL que la leia, y los dos se
# omitian con o sin proteccion. Sin proteccion el paquete ya publica valores de
# todas las columnas -modas, ejemplos, patrones-: omitirlos ahi no protegia
# nada y quitaba el diagnostico. Ahora, sin proteccion, el mensaje se publica
# entero, como lo dijo el motor (`.texto_condicion_motor()`: sin las vinetas ni
# los cortes que agrega cli). Con proteccion nada cambia.
#
# La decision se toma en la ENTRADA y llega a la lectura del mensaje por un
# solo camino: la fijan `perfilar_dbi()` y `perfilar_coleccion()` -las dos
# exportadas que reciben `proteger_datos_personales`- al entrar, antes de la
# primera lectura, y la devuelven al salir, tambien en error, como
# `.fijar_numerica_c()` con `LC_NUMERIC`. Los sitios que publican un mensaje
# del motor -unos treinta, en cuatro archivos- no la reciben y no la pueden
# olvidar: la lee `.mensaje_motor()`. Las otras cuatro exportadas que leen por
# DBI no tienen la bandera y no la fijan: heredan la de quien las llama
# -`perfilar_dbi()` llama a `plan_perfilado_dbi()`- y, solas, no protegen: desde
# el 2026-10-25 la proteccion es un complemento que se pide, y sin nadie que la
# fije el mensaje del motor se publica como llega.
#
# Salvo con `incluir_valores = FALSE`, que promete una salida sin valores de
# celda, motivos incluidos. El mensaje del motor es texto ajeno y cita la celda:
# `invalid input syntax for type bigint: "..."` en PostgreSQL 16 y 9.3,
# `Conversion failed when converting the varchar value '...'` en SQL Server,
# `Could not convert string '...'` y el desborde de un `DECIMAL(38,30)` con el
# valor entero en DuckDB. Sin proteccion se publicaban enteros en
# `resumen_tabla$sql$motivo`, `meta$consultas$fallas`, la muestra, el spool y la
# fuente por bloques (medido en las cinco vias). Pide lo mismo que la
# proteccion -el mensaje pasa por el piso- y se decide aca, una vez: quien fija
# la bandera pasa las dos cosas, y lo que lee el mensaje no cambia.
.protege_mensaje_motor <- function() isTRUE(.CONTEXTO_MOTOR$proteger)

.fijar_proteccion_motor <- function(proteger, marco = parent.frame(),
                                    incluir_valores = TRUE) {
  previa <- .CONTEXTO_MOTOR$proteger
  .CONTEXTO_MOTOR$proteger <- isTRUE(proteger) || isFALSE(incluir_valores)
  volver <- substitute(.reponer_proteccion_motor(previa),
                       list(previa = previa))
  do.call(on.exit, list(volver, add = TRUE), envir = marco)
  invisible(previa)
}

.reponer_proteccion_motor <- function(previa) {
  .CONTEXTO_MOTOR$proteger <- previa
  invisible(NULL)
}

# Y los VALORES protegidos que la llamada ya leyo. La segunda pasada
# publica solo lo permitido, y un valor hecho de lo permitido -los apellidos
# `Campos Cadena`, dos palabras del vocabulario castellano- o igual al nombre de
# una columna -la docente `Florencia` en la planilla pivoteada por docente- es
# la celda citada, y salia entero: en la coleccion sin perfiles, el mensaje del
# motor de una vista citaba la celda de la tabla base, que la coleccion habia
# leido. Ahora el mensaje pasa tambien por el piso con los valores que la
# llamada conoce, y un nombre igual a uno de ellos deja de ser un nombre
# permitido, con la comparacion del piso (`.nombres_iguales_a_valores()`): la
# del mensaje no puede ser mas estricta. Los junta `perfilar_coleccion()`: cada
# `perfilar_dbi()` de sus tablas suma lo que leyo. Se guardan solo los que el
# mensaje puede llevar despues de la segunda pasada
# (`.valores_que_lleva_el_motor()`): los demas -el documento, el celular, la
# tarjeta: un numero que se lee como uno de seis cifras o mas- el mensaje ya los
# omite. Un valor con letras se guarda siempre: cualquier
# palabra puede ser el nombre de una columna de otra tabla.
#
# Se guardaba el TEXTO de cada uno, y con todo valor con letras la memoria
# crecia con los nombres que la coleccion leia: +66 MB y +8 % de tiempo sobre
# 800.000 filas con nombres. Ahora se guarda una
# HUELLA por valor (`.huellas_claves_motor()`): un numero de 52 bits de su
# forma plegada y sin separadores -la de la regla de variantes del piso-, ocho
# bytes en lugar del texto, y los largos de esas formas. El mensaje se compara
# tramo por tramo (`.valores_conocidos_en()`): un tramo de su forma plegada con
# la huella de un valor guardado es ese valor, y se devuelve como esta escrito
# en el mensaje, que es lo que el piso tapa. Dos formas distintas con la misma
# huella -una en 2^52- solo pueden tapar de mas: nunca se deja de encontrar un
# valor guardado.
.activar_valores_motor <- function() {
  previos <- .CONTEXTO_MOTOR$valores
  .CONTEXTO_MOTOR$valores <- .indice_valores_motor(character())
  invisible(previos)
}

.fijar_valores_motor <- function(valores) {
  .CONTEXTO_MOTOR$valores <- valores
  invisible(NULL)
}

# Suma valores leidos -con el piso de `.valores_identificantes()`- si alguien
# los esta juntando; si no, no hace nada.
.sumar_valores_motor <- function(valores, fechas = character()) {
  actual <- .CONTEXTO_MOTOR$valores
  if (is.null(actual) || !length(valores)) return(invisible(NULL))
  nuevos <- tryCatch({
    identificantes <- .valores_identificantes(unique(as.character(valores)),
                                              fechas)
    .indice_valores_motor(.valores_que_lleva_el_motor(identificantes))
  }, error = function(e) NULL)
  if (!is.null(nuevos) && length(nuevos$huellas)) {
    sumadas <- nuevos$huellas[!nuevos$huellas %in% actual$huellas]
    .CONTEXTO_MOTOR$valores <- list(
      huellas = c(actual$huellas, sumadas),
      largos = .sort_por_bytes(unique(c(actual$largos, nuevos$largos)))
    )
  }
  invisible(NULL)
}

# Y el mensaje CRUDO de cada error del motor que se publica
# mientras una coleccion junta valores. El piso del mensaje corre al armarlo
# (`.sin_literales_motor()`), con los valores que se conocen en ese momento, y
# con una vista leida antes que su tabla base no conoce los de la base: la
# segunda pasada omitia lo que no es una palabra permitida y dejaba el RESTO del
# nombre -"De Los Campos" de "Maria De Los Campos" en SQL Server en sueco,
# "Campos Cadena" despues de un apodo entre comillas en ingles-, que el piso
# final ya no reconocia, porque la huella es la del valor entero. Ahora la
# coleccion guarda cada mensaje como llego, lo que se publico de el y los
# nombres que estaban permitidos, y al final vuelve a leer cada uno con todo lo
# que leyo y cambia lo publicado (`.repasar_mensajes_motor()`): el piso corre
# sobre el valor entero, sin depender del orden de las tablas. Los crudos viven
# en memoria mientras dura la coleccion y nunca entran a un objeto; fuera de
# una coleccion no se guarda nada.
.activar_mensajes_motor <- function() {
  previos <- .CONTEXTO_MOTOR$mensajes
  registro <- new.env(parent = emptyenv())
  registro$crudos <- character()
  registro$publicados <- character()
  registro$conjunto <- integer()
  registro$conjuntos <- list()
  registro$claves <- character()
  .CONTEXTO_MOTOR$mensajes <- registro
  invisible(previos)
}

.fijar_mensajes_motor <- function(mensajes) {
  .CONTEXTO_MOTOR$mensajes <- mensajes
  invisible(NULL)
}

.registrar_mensajes_motor <- function(crudos, publicados,
                                      identificadores = .identificadores_motor()) {
  registro <- .CONTEXTO_MOTOR$mensajes
  if (!is.environment(registro)) return(invisible(NULL))
  crudos <- as.character(crudos)
  publicados <- as.character(publicados)
  validos <- !is.na(crudos) & !is.na(publicados)
  if (!any(validos)) return(invisible(NULL))
  identificadores <- as.character(identificadores)
  # Los nombres permitidos al armarlo: al volver a leerlo se permiten los
  # mismos, ni uno mas.
  cual <- Position(function(c) identical(c, identificadores), registro$conjuntos)
  if (is.na(cual)) {
    registro$conjuntos[[length(registro$conjuntos) + 1L]] <- identificadores
    cual <- length(registro$conjuntos)
  }
  crudos <- crudos[validos]
  publicados <- publicados[validos]
  claves <- paste(cual, crudos, publicados, sep = "\001")
  nuevas <- !duplicated(claves) & !claves %in% registro$claves
  if (!any(nuevas)) return(invisible(NULL))
  registro$claves <- c(registro$claves, claves[nuevas])
  registro$crudos <- c(registro$crudos, crudos[nuevas])
  registro$publicados <- c(registro$publicados, publicados[nuevas])
  registro$conjunto <- c(registro$conjunto, rep(cual, sum(nuevas)))
  invisible(NULL)
}

.crudos_mensajes_motor <- function() {
  registro <- .CONTEXTO_MOTOR$mensajes
  if (!is.environment(registro)) return(character())
  unique(registro$crudos)
}

.publicados_mensajes_motor <- function() {
  registro <- .CONTEXTO_MOTOR$mensajes
  if (!is.environment(registro)) return(character())
  unique(registro$publicados)
}

# Las letras y cifras que un texto publica fuera de los marcadores.
.alfanumericos_publicados_motor <- function(texto) {
  texto <- as.character(texto)
  sin_marcas <- gsub(.LITERAL_MOTOR_OMITIDO, "", texto, fixed = TRUE,
                     useBytes = TRUE)
  sin_marcas <- gsub(.VALOR_PROTEGIDO_MOTOR, "", sin_marcas, fixed = TRUE,
                     useBytes = TRUE)
  # Por bytes: una letra fuera de ASCII cuenta por cada uno de sus bytes, en
  # cualquier codificacion y sin abortar.
  ascii <- nchar(gsub("[^A-Za-z0-9]", "", sin_marcas, useBytes = TRUE),
                 type = "bytes")
  otros <- vapply(sin_marcas, function(t) {
    if (is.na(t)) return(NA_integer_)
    sum(as.integer(charToRaw(t)) >= 128L)
  }, integer(1L), USE.NAMES = FALSE)
  salida <- as.integer(ascii + otros)
  salida[is.na(texto)] <- NA_integer_
  salida
}

# Lo publicado de cada mensaje guardado y lo que se publica ahora, con todo lo
# que la llamada conoce y los nombres de entonces: solo los que cambian, del
# publicado mas largo al mas corto -uno que esta dentro de otro va despues-.
# Lo de ahora reemplaza a lo de antes solo si publica menos letras y cifras: un
# mensaje vuelto a leer nunca abre lo que antes se omitio. Y no un publicado
# sin letras ni cifras -todo el mensaje omitido-: esta en cualquier texto. Si
# dos crudos publicaron lo mismo y ahora publican distinto, gana el que tapa
# mas: el lado cerrado.
.pares_mensajes_motor <- function() {
  vacio <- data.frame(publicado = character(), nuevo = character(),
                      stringsAsFactors = FALSE)
  registro <- .CONTEXTO_MOTOR$mensajes
  if (!is.environment(registro) || !length(registro$crudos)) return(vacio)
  nuevos <- rep(NA_character_, length(registro$crudos))
  for (k in unique(registro$conjunto)) {
    cuales <- which(registro$conjunto == k)
    nuevos[cuales] <- tryCatch(
      .sin_literales_motor(registro$crudos[cuales],
                           identificadores = registro$conjuntos[[k]]),
      error = function(e) rep(.LITERAL_MOTOR_OMITIDO, length(cuales))
    )
  }
  antes <- .alfanumericos_publicados_motor(registro$publicados)
  ahora <- .alfanumericos_publicados_motor(nuevos)
  cambia <- !is.na(nuevos) & nuevos != registro$publicados & antes > 0L &
    ahora < antes
  cambia <- cambia & !is.na(cambia)
  if (!any(cambia)) return(vacio)
  pares <- data.frame(publicado = registro$publicados[cambia],
                      nuevo = nuevos[cambia], ahora = ahora[cambia],
                      stringsAsFactors = FALSE)
  pares <- pares[.orden_por_bytes(pares$ahora), , drop = FALSE]
  pares <- pares[!duplicated(pares$publicado), , drop = FALSE]
  pares <- pares[.orden_por_bytes(-nchar(pares$publicado, type = "bytes")), ,
                 drop = FALSE]
  rownames(pares) <- NULL
  pares[, c("publicado", "nuevo")]
}

# Cada texto de `x` que lleva lo publicado de un mensaje guardado pasa a llevar
# lo que se publica ahora (`.pares_mensajes_motor()`). Si el reemplazo falla, el
# texto que lo lleva no se publica.
.repasar_mensajes_motor <- function(x, pares = .pares_mensajes_motor()) {
  if (is.null(x) || !nrow(pares)) return(x)
  .recorrer_textos_salida(x, function(hoja, campo) {
    for (k in seq_len(nrow(pares))) {
      viejo <- pares$publicado[[k]]
      hoja <- tryCatch(
        gsub(viejo, pares$nuevo[[k]], hoja, fixed = TRUE),
        error = function(e) {
          dentro <- !is.na(hoja) &
            grepl(viejo, hoja, fixed = TRUE, useBytes = TRUE)
          hoja[dentro] <- .LITERAL_MOTOR_OMITIDO
          hoja
        }
      )
    }
    hoja
  })
}

# La forma con que se compara: plegada y sin separadores, como la regla de
# variantes del piso.
.claves_motor <- function(valores) {
  valores <- as.character(valores)
  if (!length(valores)) return(character())
  plegados <- tryCatch(.plegar_para_comparar(valores),
                       error = function(e) valores)
  claves <- tryCatch(gsub("[^\\p{L}\\p{N}]", "", plegados, perl = TRUE),
                     error = function(e) gsub("[^[:alnum:]]", "", plegados,
                                              useBytes = TRUE))
  # Lo que no se pudo leer como UTF-8 se lee como latin1, igual de los dos
  # lados: las huellas solo se comparan entre si.
  rotas <- !is.na(claves) & !validUTF8(claves)
  if (any(rotas)) claves[rotas] <- iconv(claves[rotas], "latin1", "UTF-8")
  claves
}

# Las dos bases y los dos modulos de la huella: dos primos menores que 2^26,
# para que cada producto y cada suma de la cuenta sean exactos en un `double` y
# la huella -la primera por el segundo modulo mas la segunda- quepa en 52 bits.
.HUELLA_MOTOR <- list(bases = c(1315423, 2654435),
                      modulos = c(67108859, 67108837))

.potencias_huella_motor <- function(maximo) {
  lapply(1:2, function(k) {
    base <- .HUELLA_MOTOR$bases[[k]]
    modulo <- .HUELLA_MOTOR$modulos[[k]]
    potencias <- numeric(maximo + 1L)
    potencias[[1L]] <- 1
    for (e in seq_len(maximo)) {
      potencias[[e + 1L]] <- (potencias[[e]] * base) %% modulo
    }
    potencias
  })
}

# La huella de cada clave: el polinomio de sus puntos de codigo en cada base,
# modulo cada primo. En lote, sin un bucle por clave: los puntos de todas las
# claves de un tramo -de a 250.000 caracteres, para que lo transitorio sea
# chico- de una vez (`utf8ToInt()`), su exponente por la posicion
# en su clave y una suma por clave (`rowsum()`). `NA` para una clave vacia.
.huellas_claves_motor <- function(claves) {
  salida <- rep(NA_real_, length(claves))
  largos <- .nchar_texto_seguro(claves)
  cuales <- which(!is.na(claves) & !is.na(largos) & largos > 0L)
  if (!length(cuales)) return(salida)
  potencias <- .potencias_huella_motor(max(largos[cuales]))
  tramos <- split(cuales, ceiling(cumsum(largos[cuales]) / 2.5e5))
  for (tramo in tramos) {
    puntos <- utf8ToInt(paste(claves[tramo], collapse = ""))
    if (anyNA(puntos) || length(puntos) != sum(largos[tramo])) {
      puntos <- unlist(lapply(claves[tramo], function(clave) {
        p <- utf8ToInt(clave)
        largo_clave <- .nchar_texto_seguro(clave)[[1L]]
        if (is.na(largo_clave)) {
          as.integer(charToRaw(clave))
        } else if (anyNA(p) || length(p) != largo_clave) {
          as.integer(charToRaw(clave))[seq_len(largo_clave)]
        } else p
      }), use.names = FALSE)
    }
    grupo <- rep.int(seq_along(tramo), largos[tramo])
    exponente <- rep.int(largos[tramo], largos[tramo]) - sequence(largos[tramo])
    h <- lapply(1:2, function(k) {
      modulo <- .HUELLA_MOTOR$modulos[[k]]
      terminos <- (puntos * potencias[[k]][exponente + 1L]) %% modulo
      as.vector(rowsum(terminos, grupo, reorder = FALSE)) %% modulo
    })
    salida[tramo] <- h[[1L]] * .HUELLA_MOTOR$modulos[[2L]] + h[[2L]]
  }
  salida
}

.indice_valores_motor <- function(valores) {
  claves <- .claves_motor(valores)
  huellas <- .huellas_claves_motor(claves)
  validas <- !is.na(huellas)
  list(huellas = unique(huellas[validas]),
       largos = .sort_por_bytes(unique(.nchar_texto_seguro(claves[validas]))))
}

# Los valores conocidos que estan en `textos`, como estan escritos ahi: cada
# tramo de la forma plegada de un texto cuya huella es la de un valor guardado,
# devuelto con los caracteres del texto que lo forman. Para eso cada caracter se
# pliega solo y se sabe de que caracter sale cada letra de la forma; si esa
# forma no es la del texto entero -un pliegue que mira al vecino- o algo no se
# puede leer, el texto entero es el valor conocido, y el piso lo tapa entero:
# el lado cerrado. Nunca descarta un valor que este.
.valores_conocidos_en <- function(textos) {
  indice <- .CONTEXTO_MOTOR$valores
  if (is.null(indice) || !length(indice$huellas)) return(character())
  textos <- as.character(textos)
  textos <- unique(textos[!is.na(textos)])
  if (!length(textos)) return(character())
  claves <- tryCatch(.claves_motor(textos), error = function(e) NULL)
  if (is.null(claves)) return(textos)
  largos <- .nchar_texto_seguro(claves)
  maximo <- suppressWarnings(max(largos, na.rm = TRUE))
  if (!is.finite(maximo) || maximo < 1L) return(character())
  potencias <- .potencias_huella_motor(maximo)
  modulos <- .HUELLA_MOTOR$modulos
  bases <- .HUELLA_MOTOR$bases
  salida <- character()
  # Las huellas de todos los tramos de todos los textos, y UNA sola comparacion
  # con las guardadas: `%in%` arma la tabla de las guardadas -pueden ser
  # millones- en cada llamada, y por largo costaba una tabla por largo.
  candidatos <- list()
  for (i in seq_along(textos)) {
    l <- largos[[i]]
    if (is.na(l)) {
      salida <- c(salida, textos[[i]])
      next
    }
    if (!l) next
    puntos <- utf8ToInt(claves[[i]])
    if (anyNA(puntos) || length(puntos) != l) {
      salida <- c(salida, textos[[i]])
      next
    }
    # Las huellas de los prefijos, y de ahi la de cada tramo de cada largo
    # guardado: `h(i, j) = H(j) - H(i - 1) * base^(j - i + 1)`.
    prefijos <- lapply(1:2, function(k) {
      h <- numeric(l + 1L)
      for (j in seq_len(l)) {
        h[[j + 1L]] <- (h[[j]] * bases[[k]] + puntos[[j]]) %% modulos[[k]]
      }
      h
    })
    for (largo in indice$largos[indice$largos <= l]) {
      inicio <- seq_len(l - largo + 1L)
      h <- lapply(1:2, function(k) {
        (prefijos[[k]][inicio + largo] -
           prefijos[[k]][inicio] * potencias[[k]][[largo + 1L]]) %% modulos[[k]]
      })
      candidatos[[length(candidatos) + 1L]] <- list(
        texto = i, inicio = inicio, fin = inicio + largo - 1L,
        huella = h[[1L]] * modulos[[2L]] + h[[2L]]
      )
    }
  }
  if (length(candidatos)) {
    huellas <- unlist(lapply(candidatos, `[[`, "huella"), use.names = FALSE)
    dentro <- huellas %in% indice$huellas
    if (any(dentro)) {
      cuantos <- lengths(lapply(candidatos, `[[`, "huella"))
      cual <- rep.int(vapply(candidatos, `[[`, integer(1L), "texto"), cuantos)
      inicios <- unlist(lapply(candidatos, `[[`, "inicio"), use.names = FALSE)
      fines <- unlist(lapply(candidatos, `[[`, "fin"), use.names = FALSE)
      for (i in unique(cual[dentro])) {
        de_i <- dentro & cual == i
        tramos <- cbind(inicios[de_i], fines[de_i])
        escritos <- tryCatch({
          caracteres <- strsplit(textos[[i]], "")[[1L]]
          piezas <- .claves_motor(caracteres)
          piezas[is.na(piezas)] <- ""
          if (!identical(paste0(piezas, collapse = ""), claves[[i]])) {
            .detener("pliegue")
          }
          dueno <- rep.int(seq_along(caracteres), .nchar_texto_seguro(piezas))
          vapply(seq_len(nrow(tramos)), function(k) {
            paste0(caracteres[dueno[[tramos[k, 1L]]]:dueno[[tramos[k, 2L]]]],
                   collapse = "")
          }, character(1L))
        }, error = function(e) textos[[i]])
        salida <- c(salida, escritos)
      }
    }
  }
  unique(salida)
}

# Que valores protegidos puede llevar el mensaje despues de la segunda pasada.
# Lo decide la MISMA funcion que publica: un valor se guarda si
# `.publicar_lo_permitido_motor()`, corrida sobre el valor, deja pasar algo de
# el -una letra o una cifra- con los identificadores que cualquier tabla de la
# coleccion puede permitir. Y cualquier palabra puede ser el nombre de una
# columna de una tabla que todavia no se leyo -`Florencia.Martinez`, el nombre
# que deja `make.names()` al pivotear, se parte por puntos-: se corre con toda
# palabra permitida (`toda_palabra = TRUE`). Lo que queda afuera es lo que la
# segunda pasada omite entero: un numero que se lee como uno de seis cifras o
# mas, con sus signos.
#
# La seleccion tenia su propia lectura -"un numero de seis cifras con
# hasta tres signos entre las cifras" y "a lo sumo una palabra fuera de lo
# permitido"- y descartaba valores que el mensaje lleva: `099;123;456`, con un
# signo que no une, la segunda pasada lo lee como tres numeros de tres cifras y
# los publica; y "Florencia Martinez", con dos columnas de otra tabla que son
# sus palabras, salia entero.
#
# Se pregunta por la FORMA del valor y no valor por valor: la segunda pasada
# cuesta cerca de dos milisegundos por texto, y una tabla tiene millones. Cada
# cifra va como `0` -la segunda pasada las lee asi: `.numeros_del_texto()`- y
# cada tramo de letras como `a`: con toda palabra permitida, una palabra pasa
# sea cual sea. Lo unico que esa forma puede cambiar es una letra que el
# pliegue lleva a un signo que une cifras, y ahi la forma deja pasar MAS que el
# valor: guarda de mas, que es el lado cerrado.
#
# El valor se lee SOLO y el mensaje lo lleva con lo que lo rodea. La
# unica regla de la segunda pasada que mira eso -la linea que el motor repite
# sobre un `^`- omitia entero el valor que termina en `\n^`, y no se guardaba;
# en el mensaje sueco de SQL Server la linea del `^` sigue con `till datatypen
# int`, la regla no corre, y `099;123;456\n^` o `Florencia Martinez\n^` se
# publicaban en la coleccion sin perfiles. Ahora la seleccion pregunta con la
# lectura del peor contexto (`toda_palabra = TRUE`), que no aplica esa regla:
# guarda todo lo que algun mensaje puede llevar. Las letras ya no se guardan
# tal cual cuando hay un `^`: era para esa regla, que lee la linea `LINE n:`.
.valores_que_lleva_el_motor <- function(valores,
                                        identificadores = .identificadores_motor()) {
  valores <- unique(as.character(valores[!is.na(valores)]))
  if (!length(valores)) return(character())
  textos <- valores
  rotos <- !validUTF8(textos) | Encoding(textos) == "latin1"
  if (any(rotos)) textos[rotos] <- .plegar_para_comparar(textos[rotos])
  formas <- gsub("\\p{N}", "0", textos, perl = TRUE)
  formas <- gsub("\\p{L}+", "a", formas, perl = TRUE)
  distintas <- unique(formas)
  identificadores <- as.character(identificadores)
  publicadas <- .publicar_lo_permitido_motor(
    distintas, identificadores[!is.na(identificadores)], toda_palabra = TRUE
  )
  restos <- gsub(.LITERAL_MOTOR_OMITIDO, "", publicadas, fixed = TRUE)
  lleva <- is.na(restos) | grepl("[\\p{L}\\p{N}]", restos, perl = TRUE)
  valores[lleva[match(formas, distintas)]]
}

.sin_literales_motor <- function(texto,
                                 identificadores = .identificadores_motor(),
                                 solo_comillas = FALSE) {
  if (!length(texto)) return(character())
  texto <- as.character(texto)
  identificadores <- as.character(identificadores)
  # Los valores que la llamada conoce y que pueden estar en el mensaje: un
  # nombre igual a uno de ellos no es un nombre permitido, y el mensaje pasa por
  # el piso con ellos. Ver `.activar_valores_motor()`.
  conocidos <- if (isTRUE(solo_comillas)) character() else {
    tryCatch(.valores_conocidos_en(texto), error = function(e) character())
  }
  nombres <- identificadores
  if (length(conocidos) && length(identificadores)) {
    identificadores <- setdiff(identificadores, tryCatch(
      .nombres_iguales_a_valores(identificadores, conocidos),
      error = function(e) identificadores
    ))
  }
  # Cada par: la comilla que abre y la clase de las que cierran. Todas en UNA
  # expresion, de izquierda a derecha, para que una comilla se lea una sola
  # vez: par por par, la comilla baja que abre el polaco volvia a abrir con el
  # otro cierre, no lo encontraba y tapaba hasta el fin de la linea.
  pares <- list(
    c("\"", "\""), c("'", "'"), c("\u2018", "\u2019"), c("\u201c", "\u201d"),
    c("\u00ab", "\u00bb"), c("\u00bb", "\u00ab"),
    c("\u201e", "[\u201d\u201c]"), c("\u201a", "[\u2019\u2018]"),
    c("\u2039", "\u203a"), c("\u203a", "\u2039"), c("\u300c", "\u300d"),
    c("\u300e", "\u300f"), c("\uff02", "\uff02"), c("\uff07", "\uff07")
  )
  tapar <- function(texto, pares, antes, despues, bytes = FALSE) {
    con_texto <- which(!is.na(texto))
    alternativas <- vapply(pares, function(par) {
      paste0(par[[1L]], "(?:[\\s\\S]*?", par[[2L]], despues, "|[^\\n]*)")
    }, character(1L))
    patron <- paste0(antes, "(?:", paste(alternativas, collapse = "|"), ")")
    partes <- texto[con_texto]
    coincidencias <- gregexpr(patron, partes, perl = TRUE, useBytes = bytes)
    regmatches(partes, coincidencias) <- lapply(
      regmatches(partes, coincidencias), function(trozos) {
        if (!length(trozos)) return(trozos)
        vapply(trozos, function(trozo) {
          cual <- which(vapply(pares, function(par) {
            grepl(paste0("^", par[[1L]]), trozo, perl = TRUE, useBytes = bytes)
          }, logical(1L)))[[1L]]
          par <- pares[[cual]]
          cerrado <- grepl(paste0("^", par[[1L]], "[\\s\\S]*", par[[2L]], "$"),
                           trozo, perl = TRUE, useBytes = bytes)
          interior <- sub(paste0("^", par[[1L]]), "", trozo, perl = TRUE,
                          useBytes = bytes)
          if (cerrado) {
            interior <- sub(paste0(par[[2L]], "$"), "", interior, perl = TRUE,
                            useBytes = bytes)
          }
          palabra <- grepl("^[A-Za-z_]+$", interior, useBytes = TRUE) &&
            .mayusculas_ascii(interior) %in% .PALABRAS_SQL_MOTOR
          queda <- cerrado &&
            (palabra || !grepl("[[:alnum:]]", interior, useBytes = TRUE) ||
               interior %in% identificadores)
          if (queda) return(trozo)
          cierre <- if (cerrado) {
            regmatches(trozo, regexpr(paste0(par[[2L]], "$"), trozo,
                                      perl = TRUE, useBytes = bytes))
          } else sub("^\\[(.).*\\]$", "\\1", par[[2L]])
          paste0(par[[1L]], .LITERAL_MOTOR_OMITIDO, cierre)
        }, character(1L), USE.NAMES = FALSE)
      }
    )
    texto[con_texto] <- partes
    texto
  }
  # El piso con los valores conocidos va PRIMERO, sobre el mensaje como llega,
  # con el valor entero a la vista: cada pasada omite una parte -la primera,
  # lo que esta entre comillas; la segunda, la palabra que no esta permitida- y
  # el resto -"Florencia Martinez" de "Ana Florencia Martinez", con dos
  # columnas de otra tabla que son esas palabras; "099" y "456" de
  # "099 ' 123 ' 456"- ya no es el valor que el piso busca. Las dos
  # pasadas dejan el marcador como esta, y el piso vuelve a pasar al final.
  entrada <- texto
  if (length(conocidos)) {
    entrada <- tryCatch(
      .reemplazar_valores_protegidos(texto, conocidos, exigir_limites = FALSE,
                                     intocables = nombres),
      error = function(e) rep(.LITERAL_MOTOR_OMITIDO, length(texto))
    )
  }
  salida <- tryCatch(
    tapar(entrada, pares, "(?<![\\p{L}\\p{N}])", "(?![\\p{L}\\p{N}])"),
    error = function(e) NULL, warning = function(w) NULL
  )
  if (is.null(salida)) {
    # Un texto que no es UTF-8 valido no se puede leer por caracteres: se tapa
    # por bytes, con las comillas ASCII.
    salida <- tryCatch(
      tapar(entrada, pares[1:2], "(?<![A-Za-z0-9])", "(?![A-Za-z0-9])",
            bytes = TRUE),
      error = function(e) rep(.LITERAL_MOTOR_OMITIDO, length(texto))
    )
  }
  salida <- tryCatch(
    gsub("(JSON data, line [0-9]+:)[^\n]*",
         paste0("\\1 ", .LITERAL_MOTOR_OMITIDO), salida, perl = TRUE),
    error = function(e) salida
  )
  if (!isTRUE(solo_comillas)) {
    salida <- .publicar_lo_permitido_motor(salida, identificadores)
  }
  if (length(conocidos)) {
    # Como el piso trata un valor del usuario y no la prosa del paquete: el
    # mensaje es texto ajeno que cita una celda, y un apellido que es tambien
    # una palabra del paquete -`Campos`- se busca igual. Con los nombres de la
    # tabla y de sus columnas apartados, salvo los que son un valor. Si falla,
    # el mensaje no se publica.
    salida <- tryCatch(
      .reemplazar_valores_protegidos(salida, conocidos, exigir_limites = FALSE,
                                     intocables = nombres),
      error = function(e) rep(.LITERAL_MOTOR_OMITIDO, length(salida))
    )
  }
  salida[is.na(texto)] <- NA_character_
  salida
}

# La segunda pasada: ver arriba. Lo que no se puede leer por caracteres se lee
# como latin1, y si aun asi falla el mensaje entero se omite. `toda_palabra`:
# la lectura del peor contexto, la que usa la seleccion de
# `.valores_que_lleva_el_motor()`, que lee el valor solo y tiene que contestar
# por cualquier mensaje que lo lleve. Toda palabra cuenta como un nombre
# permitido -el de una columna de cualquier tabla-, y la linea sobre un `^` no
# se omite: dentro del mensaje, el `^` en que termina el valor sigue con el
# texto del motor -`099;123;456\n^ till datatypen int`- y la linea no se
# omite. Con esa regla, la seleccion leia `099;123;456\n^` como una
# linea que el motor repite, no lo guardaba, y el mensaje lo publicaba. Las dos
# reglas que miran el contexto se contestan del lado que guarda de mas.
.publicar_lo_permitido_motor <- function(texto, identificadores = character(),
                                         toda_palabra = FALSE) {
  toda_palabra <- isTRUE(toda_palabra)
  marca <- "\001"
  marca_valor <- "\002"
  permitidas <- unique(c(
    .VOCABULARIO_MENSAJE_MOTOR, .minusculas_ascii(.PALABRAS_SQL_MOTOR),
    .minusculas_ascii(.TIPOS_MOTOR)
  ))
  identificadores <- identificadores[!is.na(identificadores)]
  token <- paste0(
    "(?<![\\p{L}\\p{N}_])\\p{N}+(?:[.,:/ -]\\p{N}+)*(?![\\p{L}\\p{N}_])|",
    "[\\p{L}\\p{M}\\p{N}_]+(?:['\u2019][\\p{L}\\p{M}]+)*"
  )
  decidir <- function(trozos) {
    if (!length(trozos)) return(trozos)
    numero <- grepl("^[\\p{N}.,:/ -]+$", trozos, perl = TRUE)
    cifras <- nchar(gsub("[^\\p{N}]", "", trozos, perl = TRUE))
    # Las palabras del mensaje y los nombres de columna se pliegan con el mapa
    # del paquete: con `tolower()`, bajo `C` un nombre con una mayuscula
    # acentuada no casaba con la misma palabra del mensaje, y se tapaba lo que
    # en una sesion UTF-8 se publicaba.
    minusculas <- .minusculas_para_comparar(trozos, recortar = FALSE)
    # Un numero con menos cifras de las que identifican -el piso de la
    # proteccion, `.MIN_LARGO_VALOR_IDENTIFICANTE`- no es el dato de nadie: la
    # linea, la posicion, un codigo. Y un codigo SQLSTATE -cinco signos, letras
    # mayusculas y cifras: `22P02`, `HY000`-.
    queda <- ifelse(
      numero, cifras < .MIN_LARGO_VALOR_IDENTIFICANTE,
      toda_palabra | minusculas %in% permitidas | trozos %in% identificadores |
        minusculas %in% .minusculas_para_comparar(identificadores, recortar = FALSE) |
        nchar(trozos) == 1L | grepl("^rapi_[a-z_]+$", trozos) |
        grepl("^(?=[A-Z]*[0-9])[0-9A-Z]{5}$", trozos, perl = TRUE)
    )
    ifelse(queda, trozos, marca)
  }
  uno <- function(t) {
    if (is.na(t)) return(t)
    if (!validUTF8(t)) t <- iconv(t, "latin1", "UTF-8")
    if (is.na(t)) return(.LITERAL_MOTOR_OMITIDO)
    t <- gsub(marca, " ", t, fixed = TRUE)
    t <- gsub(marca_valor, " ", t, fixed = TRUE)
    t <- gsub(.LITERAL_MOTOR_OMITIDO, marca, t, fixed = TRUE)
    # El marcador del piso -que ya paso, ver `.sin_literales_motor()`- queda.
    t <- gsub(.VALOR_PROTEGIDO_MOTOR, marca_valor, t, fixed = TRUE)
    # La linea que el motor repite sobre un `^`, salvo la de la consulta. Es la
    # unica regla de esta pasada que mira lo que rodea al valor: la linea del
    # `^` tiene que estar sola. Por eso la seleccion (`toda_palabra`) no la
    # aplica: ver abajo.
    if (!toda_palabra) {
      t <- gsub(
        "(^|\n)(?![ \t]*LINE [0-9]+:)[^\n]*[^\n \t^][^\n]*(?=\n[ \t]*\\^[ \t]*(?:\n|$))",
        paste0("\\1", marca), t, perl = TRUE
      )
    }
    # Un numero se lee como lo lee el piso, con la regla de digitos: ver
    # `.numeros_del_texto()`. El de seis cifras o mas se omite entero; el token
    # de abajo decide lo demas, y une tambien con dos puntos.
    numeros <- .numeros_del_texto(t, barreras = c(marca, marca_valor))
    numeros <- numeros[numeros$cifras >= .MIN_LARGO_VALOR_IDENTIFICANTE, ,
                       drop = FALSE]
    if (nrow(numeros)) {
      caracteres <- intToUtf8(utf8ToInt(t), multiple = TRUE)
      for (k in seq_len(nrow(numeros))) {
        caracteres[numeros$inicio[[k]]:numeros$fin[[k]]] <- ""
        caracteres[[numeros$inicio[[k]]]] <- marca
      }
      t <- paste0(caracteres, collapse = "")
    }
    m <- gregexpr(token, t, perl = TRUE)
    regmatches(t, m) <- lapply(regmatches(t, m), decidir)
    t <- gsub(paste0(marca, "(?:[ \t.,'/@_-]*", marca, ")+"), marca, t,
              perl = TRUE)
    t <- gsub(marca, .LITERAL_MOTOR_OMITIDO, t, fixed = TRUE)
    gsub(marca_valor, .VALOR_PROTEGIDO_MOTOR, t, fixed = TRUE)
  }
  vapply(texto, function(t) {
    tryCatch(uno(t), error = function(e) .LITERAL_MOTOR_OMITIDO)
  }, character(1L), USE.NAMES = FALSE)
}

# El motivo de una muestra que se leyo y no se pudo perfilar. El
# error de `perfilar()` pasaba por el piso entero, como un mensaje del motor, y
# con la proteccion activa un error del propio paquete salia ilegible: "`fecha`
# debe [literal omitido] una fecha y hora valida", "`[literal omitido]` debe ser
# un entero [literal omitido] de al [literal omitido] 2." -no se sabia que
# argumento fallo-. Pero el texto de un error puede citar una celda, y por eso
# el piso. El criterio: se vuelve a llamar a `perfilar()` con los mismos
# argumentos sobre la muestra SIN FILAS; si da el mismo error, el error no sale
# de ninguna celda -es de los argumentos- y se trata como una condicion propia
# de la via: solo la primera pasada, que tapa lo citado entre comillas salvo los
# nombres de la tabla y sus columnas. Si no se repite, el piso entero. Solo
# corre cuando el perfilado ya fallo.
.motivo_perfilado_muestra_dbi <- function(error, datos, argumentos) {
  sin_filas <- tryCatch({
    suppressWarnings(suppressMessages(do.call(
      perfilar, c(list(datos = datos[0L, , drop = FALSE]), argumentos)
    )))
    NULL
  }, error = function(e) e)
  if (inherits(sin_filas, "error") &&
      identical(conditionMessage(sin_filas), conditionMessage(error))) {
    error <- .condicion_dbi(
      "lupa_error_argumento_dbi", .texto_condicion_motor(error)
    )
  }
  .mensaje_motor(error)
}

# El mensaje de una condicion del PAQUETE atrapada en la via -no del motor-: se
# publica como lo escribio el paquete, y solo sus literales entre comillas, que
# podrian citar un valor, siguen la regla de la proteccion. Es lo que hace
# `.mensaje_motor()` con una condicion propia de la via DBI.
.mensaje_propio_dbi <- function(condicion) {
  texto <- .texto_condicion_motor(condicion)
  if (!.protege_mensaje_motor()) return(.texto_motor_legible(texto))
  .sin_literales_motor(texto, solo_comillas = TRUE)
}

.mensaje_motor <- function(condicion) {
  texto <- .texto_condicion_motor(condicion)
  # Sin proteccion, entero: ver `.protege_mensaje_motor()`. Tambien el de una
  # condicion propia de la via DBI, que ya lo trae entero.
  if (!.protege_mensaje_motor()) return(.texto_motor_legible(texto))
  propia <- inherits(condicion, c("lupa_error_dbi", "lupa_aviso_dbi"))
  salida <- .sin_literales_motor(texto, solo_comillas = propia)
  # En una coleccion se guarda como llego, para volver a leerlo al final con
  # todo lo que la coleccion leyo: ver `.activar_mensajes_motor()`.
  if (!propia) .registrar_mensajes_motor(texto, salida)
  salida
}

# El mensaje entero, legible en cualquier locale: lo que ya es UTF-8 valido se
# declara UTF-8 -sin cambiar sus bytes-, y lo que no -o lo marcado `latin1`- se
# lee como latin1, como lo lee la segunda pasada
# (`.publicar_lo_permitido_motor()`). Un texto que no es UTF-8 valido aborta
# despues en `nchar()` o en la impresion.
.texto_motor_legible <- function(texto) {
  texto <- as.character(texto)
  tryCatch({
    leer <- !is.na(texto) &
      (Encoding(texto) == "latin1" | !validUTF8(texto))
    if (any(leer)) texto[leer] <- iconv(texto[leer], "latin1", "UTF-8")
    .declarar_utf8_valido(texto)
  }, error = function(e) texto)
}

# El mensaje, como lo dijo el motor. odbc arma su error con cli
# (`cli::cli_abort()`): guarda cada linea del mensaje del motor como un elemento
# de `body`, y `conditionMessage()` las une con una vineta -`\n` y U+2022-,
# junta los blancos y corta las lineas al ancho de la consola. Un numero partido
# en dos lineas -`2901\n1234`, que la regla de digitos lee como uno de ocho
# cifras- llegaba partido por la vineta, que la regla lee como un punto medio
# que no une: dos numeros de cuatro cifras, que la segunda pasada publicaba y
# el piso con los valores conocidos no reconocia, en SQL Server con la sesion
# en sueco o neerlandes, con y sin perfiles retenidos. Y una consola de 48 a 52
# columnas cortaba `2901 1234` en dos lineas, con dos espacios delante de la
# segunda. Si el dato entra deformado, el arreglo va en la entrada: de una
# condicion de rlang se toman sus partes -`message`, `body`, `footer`, y las de
# la condicion que la causo-, unidas por el salto de linea que el motor puso y
# sin lo que agrega cli; la barra con que el molde de cli parte una linea larga
# no es del motor. De las demas -RPostgres, RSQLite- y de duckdb, que guarda el
# mensaje entero en `message`, sale el mismo texto que da `conditionMessage()`.
# Si las partes no son texto, o no queda nada que leer, `conditionMessage()`.
.texto_condicion_motor <- function(condicion, profundidad = 0L) {
  crudo <- tryCatch({
    partes <- if (inherits(condicion, c("rlang_error", "rlang_warning",
                                        "rlang_message"))) {
      lapply(c("message", "body", "footer"), function(campo) {
        condicion[[campo]]
      })
    }
    texto <- all(vapply(partes, function(parte) {
      is.null(parte) || is.character(parte)
    }, logical(1L)))
    if (!length(partes) || !texto) {
      NULL
    } else {
      lineas <- unlist(partes, use.names = FALSE)
      lineas <- .sin_ansi_motor(lineas[!is.na(lineas)])
      if (isTRUE(condicion[["use_cli_format"]])) {
        lineas <- gsub("\\\\\n[ \t]*", "", lineas)
      }
      padre <- condicion[["parent"]]
      if (inherits(padre, "condition") && profundidad < 10L) {
        lineas <- c(lineas, .texto_condicion_motor(padre, profundidad + 1L))
      }
      unido <- paste(lineas, collapse = "\n")
      if (grepl("[[:alnum:]]", unido, useBytes = TRUE)) unido
    }
  }, error = function(e) NULL)
  if (is.character(crudo) && length(crudo) == 1L) crudo else {
    .sin_ansi_motor(conditionMessage(condicion))
  }
}

# Y sin los colores de cli. En una consola a color -la de
# RStudio, `cli.num_colors = 256`- cli formatea las partes al senalar el error
# (`cli_abort()` aplica `format_inline()`): `message` y `body` traen las
# secuencias ANSI -`\033[32m[FreeTDS][SQL Server]\033[39m`, el enlace de
# `{.file}`- y el motivo se guardaba con ellas, con y sin proteccion; con
# proteccion la segunda pasada las mezclaba con marcadores
# (`[[literal omitido][FreeTDS]`). No son del motor: se quitan en la misma
# lectura que quita las vinetas. Si `ansi_strip()` falla, las de color a mano.
.sin_ansi_motor <- function(texto) {
  if (!is.character(texto) || !length(texto)) return(texto)
  con <- !is.na(texto) & grepl("\033", texto, fixed = TRUE, useBytes = TRUE)
  if (!any(con)) return(texto)
  texto[con] <- tryCatch(
    as.character(cli::ansi_strip(texto[con])),
    error = function(e) {
      gsub("\033\\[[0-9;]*[A-Za-z]", "", texto[con], useBytes = TRUE)
    }
  )
  texto
}

# ---- Presupuesto de consultas -------------------------------------------
#
# Los agregados de una tabla ancha se emiten por lotes y `muestra` cambia
# exactamente una cosa: acota lo que se trae a R, no el trabajo del motor.
# `max_consultas` tambien lo acota, y lo que no entra en el presupuesto se
# declara no disponible en vez de quedar en un cero silencioso.

# Resolver la forma del desvio cuesta siempre dos sondas, se acierte en la
# primera o no. Podria cortarse al primer acierto y ahorrar una, pero entonces
# el costo dependeria del motor y el plan dejaria de decir exactamente cuantas
# consultas va a emitir. La exactitud del plan vale mas que una consulta.
.PEAJE_FORMA_DESVIO <- 2L

# Veinte columnas dejan el bloque de cinco agregados en unas cien expresiones;
# es un limite conservador para motores con topes de expresiones y sigue dando
# tres consultas sobre una tabla de sesenta columnas.
.TAMANO_LOTE_PLANOS_DBI <- 20L
# Una cardinalidad exacta puede derramar mucho mas que un bloque de agregados
# planos, y por eso tiene su propio lote. Cuanto conviene agrupar se midio sobre
# un PostgreSQL real, con una tabla de 4,5 M filas y `work_mem` de 32 MB:
#
#   lote  exec total  exec/columna  Temp Written  Shared Read
#      1      27,6 s        27,6 s         7.200       90.384
#      2      30,4 s        15,2 s        13.764       90.320
#      4      60,2 s        15,0 s        18.291       90.256
#      8       194 s        24,3 s        43.694       90.192
#
# El `Shared Read` es CONSTANTE entre 1 y 8: el motor hace una sola pasada por la
# tabla y la amortiza entre todos los agregados del mismo SELECT. Lo que crece es
# el derrame, porque los hashes compiten por `work_mem`. Por eso el optimo esta
# en el medio y no en ningun extremo: para ocho conteos, el lote 1 cuesta ~221 s
# y el lote 4 cuesta ~120 s.
#
# Va 2 y no 4 porque dan el mismo tiempo por columna -15,2 contra 15,0- pero el 2
# derrama un 25 % menos, y el optimo depende de `work_mem`, que cambia por
# servidor: el 2 se degrada mejor donde hay poca memoria y rinde casi igual donde
# hay mucha. No lo cambies por una corazonada; si lo cambias, medi de nuevo.
.TAMANO_LOTE_DISTINTOS_DBI <- 2L
# Alias interno y de compatibilidad para codigo que aun menciona el nombre
# anterior. Las dos familias no usan este valor como tamano comun.
.TAMANO_LOTE_DBI <- .TAMANO_LOTE_PLANOS_DBI

# Registro cerrado de los metodos que publican las filas SQL. Las claves tienen
# que coincidir textualmente con `metodo`: no se infiere la clase por la
# metrica, porque una misma metrica puede tener metodos con memoria distinta.
.REGISTRO_MEMORIA_TRABAJO_DBI <- c(
  "COUNT(DISTINCT)" = "creciente",
  "APPROX_COUNT_DISTINCT" = "acotado",
  "approx_count_distinct" = "acotado",
  "approx_count_distinct_generico" = "acotado",
  "ventana_agregado" = "creciente",
  "consulta_actual_sin_guardian" = "creciente",
  "subconsulta_escalar" = "creciente",
  # La CTE de ventanas ordena las filas no nulas. Con un tope real el
  # clasificador de muestras la reduce a R2; cuando la muestra satura el
  # universo, el sort vuelve a crecer con las filas y cae a R3. Las dos
  # etiquetas de fuente son aliases deliberados para que una futura variante
  # pueda publicar el origen sin quedar sin clasificar.
  "cte_ventana" = "creciente",
  "cte_ventana_tablesample_system" = "creciente",
  "cte_ventana_newid" = "creciente",
  "dos_consultas" = "creciente",
  # La media y el desvio de un decimal de sus sumas exactas: `SUM()` de piezas
  # de largo fijo, sin ordenar ni agrupar.
  "sumas_exactas_decimal" = "acotado",
  "PERCENTILE_CONT" = "creciente",
  "PERCENTILE_CONT_OVER" = "creciente",
  "approx_percentile" = "acotado",
  "approx_quantile" = "acotado",
  "percentile_approx" = "acotado",
  "quantile" = "acotado",
  # El spool saturado recorre la tabla completa y su trabajo crece con las filas.
  "spool_sesion_cliente" = "creciente",
  # La lectura por bloques libera cada bloque antes de pedir el siguiente. El estado de los
  # acumuladores queda acotado por `E_distintos` y `P_estado`, no por `n`.
  "dbfetch_bloques" = "acotado",
  "tabla_completa" = "acotado",
  "conteo_universo" = "acotado",
  "pg_stats.n_distinct" = "acotado"
)

# Las capacidades nuevas se sondean una vez por corrida. Todas sus formas
# candidatas se prueban aunque una ya haya acertado: el costo no puede depender
# de que el primer candidato sea aceptado por el motor.

# Las sondas van sobre una constante, no sobre la tabla: lo unico que se prueba
# es si el motor conoce la funcion.
.sondar_forma_desvio <- function(conexion, presupuesto, alias) {
  if (!is.null(presupuesto$forma_desvio)) return(invisible(NULL))
  nativas <- c("STDDEV_SAMP", "STDEV")
  elegida <- NULL
  for (i in seq_along(nativas)) {
    sql <- paste0(
      "SELECT ", nativas[[i]], "(1.0) AS ", alias("desvio"),
      if (.es_oracle_dbi(conexion)) " FROM DUAL" else ""
    )
    intento <- .escalar_dbi(
      conexion, sql, "desvio", presupuesto, etapa = "sonda_desvio"
    )
    if (is.null(elegida) && isTRUE(intento$ok)) elegida <- i
  }
  # Sin ninguna nativa queda el calculo de dos pasadas, que es la ultima forma.
  presupuesto$forma_desvio <- if (is.null(elegida)) 3L else elegida
  invisible(NULL)
}

.presupuesto_dbi <- function(max_consultas = Inf, instrumentar = TRUE) {
  estado <- new.env(parent = emptyenv())
  estado$max <- max_consultas
  estado$usadas <- 0
  estado$reserva <- 0
  estado$agotado <- FALSE
  # La instrumentacion se puede apagar porque medir tambien es trabajo. Los
  # identificadores siguen avanzando cuando esta apagada: identifican el
  # intento de consulta, no afirman que su duracion se haya medido.
  estado$instrumentar <- isTRUE(instrumentar)
  estado$siguiente_consulta <- 0L
  estado$fallas_consultas <- list()
  estado$fallas_sondas <- list()
  estado$fallas_lotes <- list()
  # La forma de calcular el desvio se resuelve una vez por corrida y se recuerda:
  # probarla por columna gastaria hasta tres consultas cada vez y romperia la
  # promesa del plan, que dice exactamente cuantas va a emitir.
  estado$forma_desvio <- NULL
  # Este valor vive en el presupuesto de la corrida y muere con el: sirve para
  # recordar un lote aceptado sin guardar estado global asociado a una conexion.
  estado$tamano_lote_funciono <- NULL
  estado$tamano_lote_planos_funciono <- NULL
  estado$tamano_lote_distintos_funciono <- NULL
  # La referencia temporal de distintos se llena con el primer lote distinto.
  # No se usan estadisticas del catalogo ni agregados planos para proyectar ese
  # costo: son unidades diferentes.
  estado$referencias_distintos <- list()
  estado$proyeccion_distintos <- NULL
  # La moda y la mediana tienen sus propios relojes de referencia: agrupar se
  # proyecta por distinto y ordenar por fila. Las referencias mueren con esta
  # corrida, igual que la de `COUNT(DISTINCT)`.
  estado$referencias_moda <- list()
  estado$proyeccion_moda <- NULL
  estado$referencias_mediana <- list()
  estado$proyeccion_mediana <- NULL
  estado$medianas_pendientes <- NULL
  # La consulta que deja disponible el conteo puede servir como cota de la
  # lectura de cada mediana. No es una tasa de mediana y nunca reemplaza la
  # referencia local o bancaria; solo evita que una referencia bancaria corta
  # deje silencioso un ordenamiento que ya sabemos que debe recorrer las filas.
  estado$duracion_lectura_mediana <- NA_real_
  estado$aviso_moda_emitido <- FALSE
  estado$aviso_mediana_emitido <- FALSE
  estado$aviso_derrame_moda_emitido <- FALSE
  estado$aviso_derrame_mediana_emitido <- FALSE
  # Los avisos se controlan por separado porque hablan de magnitudes y de
  # familias de trabajo incompatibles: segundos de servidor para distintos,
  # moda y mediana, y bytes para memoria. No hay un porton comun que permita
  # silenciar uno sin ocultar el otro.
  estado$avisar_costo_distintos <- TRUE
  estado$umbral_segundos_aviso_distintos <- .UMBRAL_SEGUNDOS_AVISO_DISTINTOS_DBI
  estado$avisar_derrame_estimado <- TRUE
  estado$umbral_bytes_aviso_derrame_estimado <-
    .UMBRAL_BYTES_AVISO_DERRAME_ESTIMADO_DBI
  # La memoria del hash se estima con estadisticas del catalogo, pero nunca se
  # guarda como si fuera una medicion del derrame. Vive en el presupuesto para
  # que el plan y la corrida conserven el mismo diagnostico sin consultar dos
  # veces el catalogo.
  estado$estimacion_derrame <- list(
    estado = "no_solicitado", disponible = FALSE, es_estimacion = TRUE,
    fuente = NA_character_, motivo = paste(
      "No se solicit\u00f3 una estimaci\u00f3n de derrame porque no se pidi\u00f3",
      "COUNT(DISTINCT) exacto."
    ), work_mem = NA_character_, work_mem_bytes = NA_real_,
    hash_mem_multiplier = NA_real_, hash_mem_multiplier_disponible = FALSE,
    memoria_efectiva_bytes = NA_real_, memoria_efectiva = NA_character_,
    columnas = data.frame(), lotes = data.frame(),
    lotes_sobre_memoria = integer()
  )
  estado$estimacion_derrame_moda <- .estimacion_derrame_familia_vacia_dbi(
    "moda", "No se solicit\u00f3 una estimaci\u00f3n de derrame para la moda."
  )
  estado$estimacion_derrame_mediana <- .estimacion_derrame_familia_vacia_dbi(
    "mediana", "No se solicit\u00f3 una estimaci\u00f3n de derrame para la mediana."
  )
  # La lectura de pg_stat_statements es opcional: si el servidor no la expone,
  # el informe conserva la incertidumbre y no deduce un derrame del reloj.
  estado$derrame <- list(
    estado = "no_solicitado", disponible = FALSE,
    fuente = NA_character_, motivo = paste(
      "No se solicit\u00f3 una medici\u00f3n de derrame porque no se pidi\u00f3",
      "COUNT(DISTINCT) exacto."
    ), consultas = NULL
  )
  # Cuantas consultas espera emitir la corrida y la barra que lo muestra. Van
  # aca porque el presupuesto es el unico objeto que ve pasar TODAS las
  # consultas: colgarlo de otro lado obligaria a enhebrarlo por cada camino.
  estado$previstas <- NA_real_
  estado$barra <- NULL
  estado
}

.registrar_referencia_distintos_dbi <- function(presupuesto, consulta) {
  if (is.null(presupuesto) || !isTRUE(consulta$ok) ||
      is.null(consulta$consulta_id) || length(consulta$consulta_id) != 1L ||
      is.na(consulta$consulta_id) || is.null(consulta$duracion_ms) ||
      length(consulta$duracion_ms) != 1L || is.na(consulta$duracion_ms) ||
      !is.finite(consulta$duracion_ms) || consulta$duracion_ms <= 0) {
    return(invisible(NULL))
  }
  id <- as.character(consulta$consulta_id)
  referencias <- presupuesto$referencias_distintos
  referencias[[id]] <- list(
    consulta_id = as.integer(consulta$consulta_id),
    duracion_ms = as.numeric(consulta$duracion_ms)
  )
  presupuesto$referencias_distintos <- referencias
  invisible(NULL)
}

.proyeccion_distintos_vacia_dbi <- function(n_lotes, motivo = paste(
    "No hay una duraci\u00f3n medida del primer lote de distintos en esta corrida;",
    "no se publica una proyecci\u00f3n temporal."
  )) {
  list(
    disponible = FALSE, duracion_estimada_ms = NA_real_,
    duracion_referencia_ms = NA_real_, n_lotes = as.integer(n_lotes),
    n_referencias = 0L, fuente = NA_character_, motivo = motivo
  )
}

.proyectar_costo_distintos_dbi <- function(presupuesto, n_lotes) {
  vacia <- .proyeccion_distintos_vacia_dbi(n_lotes)
  if (!is.numeric(n_lotes) || length(n_lotes) != 1L || is.na(n_lotes) ||
      !is.finite(n_lotes) || n_lotes < 1) {
    return(vacia)
  }
  if (n_lotes == 1) {
    return(.proyeccion_distintos_vacia_dbi(
      n_lotes,
      paste(
        "Hay un solo lote de distintos: el costo ya se pag\u00f3 y no hay nada",
        "que proyectar ni que evitar."
      )
    ))
  }
  if (is.null(presupuesto) || !length(presupuesto$referencias_distintos)) {
    return(vacia)
  }
  duraciones <- vapply(
    presupuesto$referencias_distintos,
    function(x) as.numeric(x$duracion_ms), numeric(1L)
  )
  duraciones <- duraciones[is.finite(duraciones) & duraciones > 0]
  if (!length(duraciones)) return(vacia)
  referencia <- stats::median(duraciones)
  estimada <- referencia * as.numeric(n_lotes)
  if (!is.finite(estimada)) return(vacia)
  list(
    disponible = TRUE,
    duracion_estimada_ms = estimada,
    duracion_referencia_ms = referencia,
    n_lotes = as.integer(n_lotes),
    n_referencias = as.integer(length(duraciones)),
    fuente = paste(
      "mediana de", length(duraciones),
      if (length(duraciones) == 1L) {
        "consulta del primer lote de distintos medido en esta corrida"
      } else {
        "consultas del primer lote de distintos medidas en esta corrida"
      }
    ),
    motivo = paste(
      "La proyecci\u00f3n usa la mediana del primer lote de `COUNT(DISTINCT)`",
      "medido en esta corrida y la multiplica por la cantidad de lotes; es",
      "una estimaci\u00f3n, no una medici\u00f3n del agregado exacto total."
    )
  )
}

.registrar_referencia_moda_dbi <- function(
    presupuesto, consulta, n_distintos, columna = NA_character_) {
  if (is.null(presupuesto) || !isTRUE(consulta$ok) ||
      is.null(consulta$consulta_id) || length(consulta$consulta_id) != 1L ||
      is.na(consulta$consulta_id) || is.null(consulta$duracion_ms) ||
      length(consulta$duracion_ms) != 1L || is.na(consulta$duracion_ms) ||
      !is.finite(consulta$duracion_ms) || consulta$duracion_ms <= 0) {
    return(invisible(NULL))
  }
  distintos <- .numero_dbi(n_distintos)
  if (length(distintos) != 1L || is.na(distintos) || !is.finite(distintos) ||
      distintos <= 0) {
    return(invisible(NULL))
  }
  id <- as.character(consulta$consulta_id)
  referencias <- presupuesto$referencias_moda
  referencias[[id]] <- list(
    consulta_id = as.integer(consulta$consulta_id),
    columna = as.character(columna),
    duracion_ms = as.numeric(consulta$duracion_ms),
    n_distintos = distintos,
    ms_por_distinto = as.numeric(consulta$duracion_ms) / distintos
  )
  presupuesto$referencias_moda <- referencias
  invisible(NULL)
}

.proyeccion_moda_vacia_dbi <- function(
    motivo = paste(
      "No hay una duraci\u00f3n medida de una moda y una cardinalidad utilizable",
      "en esta corrida; no se publica una proyecci\u00f3n temporal."
    ), columnas_sin_cardinalidad = character()) {
  list(
    disponible = FALSE, duracion_estimada_ms = NA_real_,
    duracion_referencia_ms = NA_real_, n_distintos_proyectados = NA_real_,
    n_columnas = 0L, n_referencias = 0L, fuente = NA_character_,
    columnas_sin_cardinalidad = as.character(columnas_sin_cardinalidad),
    fuentes_cardinalidad = character(),
    motivo = motivo
  )
}

.proyectar_costo_moda_dbi <- function(presupuesto, cardinalidades) {
  if (is.null(cardinalidades)) {
    return(.proyeccion_moda_vacia_dbi(
      "No se recibi\u00f3 la cardinalidad de las columnas pendientes; no se puede proyectar la moda."
    ))
  }
  if (is.numeric(cardinalidades)) {
    cardinalidades <- lapply(cardinalidades, function(valor) list(
      disponible = is.finite(valor) && valor >= 0,
      n_distintos = as.numeric(valor), fuente = "medicion"
    ))
  }
  if (!is.list(cardinalidades) || !length(cardinalidades)) {
    return(.proyeccion_moda_vacia_dbi(
      "No hay modas pendientes con cardinalidad; no se publica una proyecci\u00f3n."
    ))
  }
  nombres <- names(cardinalidades)
  if (is.null(nombres)) nombres <- rep(NA_character_, length(cardinalidades))
  cardinalidad <- vapply(cardinalidades, function(x) {
    if (!is.list(x)) return(NA_real_)
    if (!is.null(x$disponible) && !isTRUE(x$disponible)) return(NA_real_)
    valor <- .numero_dbi(x$n_distintos)
    if (length(valor) != 1L || is.na(valor) || !is.finite(valor) || valor < 0) {
      NA_real_
    } else valor
  }, numeric(1L))
  disponibles <- is.finite(cardinalidad) & cardinalidad >= 0
  sin_cardinalidad <- nombres[!disponibles]
  if (!any(disponibles)) {
    return(.proyeccion_moda_vacia_dbi(
      paste(
        "No se puede proyectar el costo de la moda porque falta la cardinalidad",
        "de todas las columnas pendientes.",
        if (length(sin_cardinalidad)) paste(
          "Columnas:", paste(sin_cardinalidad, collapse = ", ")
        ) else ""
      ),
      columnas_sin_cardinalidad = sin_cardinalidad
    ))
  }
  referencias <- if (is.null(presupuesto)) list() else presupuesto$referencias_moda
  if (is.null(referencias) || !length(referencias)) {
    return(.proyeccion_moda_vacia_dbi(
      paste(
        "No hay una primera moda medida en esta corrida para convertir la",
        "cardinalidad en tiempo; no se puede proyectar la moda.",
        if (length(sin_cardinalidad)) paste(
          "Tambi\u00e9n falta cardinalidad para:", paste(sin_cardinalidad, collapse = ", ")
        ) else ""
      ),
      columnas_sin_cardinalidad = sin_cardinalidad
    ))
  }
  tasas <- vapply(referencias, function(x) {
    valor <- .numero_dbi(x$ms_por_distinto)
    if (length(valor) != 1L || is.na(valor) || !is.finite(valor) || valor <= 0) {
      duracion <- .numero_dbi(x$duracion_ms)
      distintos <- .numero_dbi(x$n_distintos)
      if (length(duracion) == 1L && is.finite(duracion) &&
          length(distintos) == 1L && is.finite(distintos) && distintos > 0) {
        valor <- duracion / distintos
      }
    }
    if (length(valor) != 1L || is.na(valor) || !is.finite(valor) || valor <= 0) {
      NA_real_
    } else valor
  }, numeric(1L))
  tasas <- tasas[is.finite(tasas) & tasas > 0]
  if (!length(tasas)) {
    return(.proyeccion_moda_vacia_dbi(
      "Las modas ya medidas no tienen una duraci\u00f3n utilizable para convertir la cardinalidad.",
      columnas_sin_cardinalidad = sin_cardinalidad
    ))
  }
  referencia <- stats::median(tasas)
  unidades <- sum(cardinalidad[disponibles])
  estimada <- referencia * unidades
  if (!is.finite(estimada)) {
    return(.proyeccion_moda_vacia_dbi(
      "La proyecci\u00f3n de la moda no es finita; no se publica un n\u00famero.",
      columnas_sin_cardinalidad = sin_cardinalidad
    ))
  }
  fuentes_disponibles <- vapply(cardinalidades[disponibles], function(x) {
    if (is.list(x) && !is.null(x$fuente) && length(x$fuente) &&
        !is.na(x$fuente[[1L]])) {
      as.character(x$fuente[[1L]])
    } else {
      "fuente no declarada"
    }
  }, character(1L))
  motivo <- paste(
    "La proyecci\u00f3n usa la mediana de las tasas ms por distinto de las modas",
    "medidas en esta corrida y la multiplica por la cardinalidad disponible",
    "de las columnas pendientes. Fuentes de cardinalidad:",
    paste0(paste(unique(fuentes_disponibles), collapse = ", "), "."),
    if (length(sin_cardinalidad)) paste(
      "No incluye las columnas sin cardinalidad:", paste(sin_cardinalidad, collapse = ", "),
      "por lo que es parcial."
    ) else ""
  )
  list(
    disponible = TRUE, duracion_estimada_ms = estimada,
    duracion_referencia_ms = referencia,
    n_distintos_proyectados = unidades,
    n_columnas = as.integer(sum(disponibles)),
    n_referencias = as.integer(length(tasas)),
    fuente = paste(
      "mediana de", length(tasas),
      if (length(tasas) == 1L) {
        "moda medida en esta corrida (ms por distinto)"
      } else {
        "modas medidas en esta corrida (ms por distinto)"
      }
    ),
    columnas_sin_cardinalidad = as.character(sin_cardinalidad),
    fuentes_cardinalidad = unique(fuentes_disponibles),
    motivo = motivo
  )
}

.avisar_costo_moda_dbi <- function(
    proyeccion, habilitado = TRUE,
    umbral_segundos = .UMBRAL_SEGUNDOS_AVISO_MODA_DBI) {
  habilitado <- .validar_interruptor_aviso_dbi(habilitado, "habilitado")
  umbral_segundos <- .validar_umbral_aviso_dbi(
    umbral_segundos, "umbral_segundos"
  )
  if (is.null(proyeccion) || !isTRUE(proyeccion$disponible) ||
      !isTRUE(habilitado) || !is.finite(umbral_segundos) ||
      is.na(proyeccion$duracion_estimada_ms) ||
      proyeccion$duracion_estimada_ms < umbral_segundos * 1000) {
    return(invisible(FALSE))
  }
  detalle <- if (length(proyeccion$columnas_sin_cardinalidad)) paste(
    " La proyecci\u00f3n es parcial porque no hay cardinalidad para:",
    paste0(paste(proyeccion$columnas_sin_cardinalidad, collapse = ", "), ".")
  ) else ""
  detalle_fuente <- if (length(proyeccion$fuentes_cardinalidad)) paste(
    " Fuentes de cardinalidad:",
    paste0(paste(proyeccion$fuentes_cardinalidad, collapse = ", "), ".")
  ) else ""
  cli::cli_alert_warning(.cli_literal(.marcar_para_exhibir(paste0(
    "Costo estimado de la moda: ~",
    .segundos_dbi(proyeccion$duracion_estimada_ms), " s para ",
    proyeccion$n_columnas,
    if (proyeccion$n_columnas == 1L) " columna. Fuente: " else " columnas. Fuente: ",
    proyeccion$fuente,
      ". Es una estimaci\u00f3n, no una medici\u00f3n.", detalle_fuente, detalle
  ))))
  invisible(TRUE)
}

.cardinalidad_aviso_moda_dbi <- function(
    columna, agregados, fuentes = NULL, n_total = NA_real_) {
  fuente <- if (is.null(fuentes)) NULL else fuentes[[columna]]
  valor_fuente <- if (is.null(fuente)) NA_real_ else {
    .numero_dbi(fuente$n_distintos)
  }
  total <- .numero_dbi(n_total)
  if (length(valor_fuente) != 1L || is.na(valor_fuente) ||
      !is.finite(valor_fuente) || valor_fuente < 0) {
    proporcion <- if (is.null(fuente)) NA_real_ else
      .numero_dbi(fuente$proporcion_distintos)
    if (!is.null(fuente) && isTRUE(fuente$exacta) &&
        is.finite(proporcion) && proporcion == 1 &&
        length(total) == 1L && is.finite(total) && !is.na(total)) {
      valor_fuente <- total
    }
  }
  if (length(valor_fuente) == 1L && is.finite(valor_fuente) &&
      !is.na(valor_fuente) && valor_fuente >= 0) {
    return(list(
      disponible = TRUE, n_distintos = valor_fuente,
      fuente = if (is.null(fuente) || is.null(fuente$nombre)) {
        "fuente estructural"
      } else fuente$nombre,
      motivo = if (is.null(fuente) || is.null(fuente$motivo)) {
        NA_character_
      } else fuente$motivo
    ))
  }
  conteo <- if (!is.null(agregados) && !is.null(agregados$conteos)) {
    agregados$conteos[[columna]]
  } else NULL
  valor <- if (!is.null(conteo) && !is.null(conteo$distintos)) {
    .numero_dbi(conteo$distintos$valor)
  } else NA_real_
  if (length(valor) == 1L && is.finite(valor) && !is.na(valor) && valor >= 0) {
    return(list(
      disponible = TRUE, n_distintos = valor, fuente = "medici\u00f3n de la corrida",
      motivo = "La cardinalidad sale del agregado disponible antes de la moda."
    ))
  }
  valor <- if (is.null(fuente)) NA_real_ else .numero_dbi(fuente$n_distintos)
  if (length(valor) != 1L || is.na(valor) || !is.finite(valor) || valor < 0) {
    proporcion <- if (is.null(fuente)) NA_real_ else
      .numero_dbi(fuente$proporcion_distintos)
    if (!is.null(fuente) && isTRUE(fuente$exacta) &&
        is.finite(proporcion) && proporcion == 1 &&
        length(total) == 1L && is.finite(total) && !is.na(total)) {
      valor <- total
    }
  }
  if (length(valor) == 1L && is.finite(valor) && !is.na(valor) && valor >= 0) {
    return(list(
      disponible = TRUE, n_distintos = valor,
      fuente = if (is.null(fuente$nombre)) "fuente estructural" else fuente$nombre,
      motivo = if (is.null(fuente$motivo)) NA_character_ else fuente$motivo
    ))
  }
  motivo <- if (is.null(fuente) || is.null(fuente$motivo)) {
    "No hay cardinalidad medida, estructural ni de cat\u00e1logo para esta columna."
  } else {
    as.character(fuente$motivo)
  }
  list(
    disponible = FALSE, n_distintos = NA_real_,
    fuente = if (is.null(fuente) || is.null(fuente$nombre)) {
      "desconocida"
    } else fuente$nombre,
    motivo = paste(
      "No se puede proyectar el costo de la moda porque falta la cardinalidad;",
      motivo
    )
  )
}

.registrar_referencia_mediana_dbi <- function(
    presupuesto, consulta, n_filas, n_medianas = 1L) {
  if (is.null(presupuesto) || !isTRUE(consulta$ok) ||
      is.null(consulta$consulta_id) || length(consulta$consulta_id) != 1L ||
      is.na(consulta$consulta_id) || is.null(consulta$duracion_ms) ||
      length(consulta$duracion_ms) != 1L || is.na(consulta$duracion_ms) ||
      !is.finite(consulta$duracion_ms) || consulta$duracion_ms <= 0) {
    return(invisible(NULL))
  }
  filas <- .numero_dbi(n_filas)
  medianas <- .numero_dbi(n_medianas)
  if (length(filas) != 1L || is.na(filas) || !is.finite(filas) || filas <= 0 ||
      length(medianas) != 1L || is.na(medianas) || !is.finite(medianas) ||
      medianas <= 0) {
    return(invisible(NULL))
  }
  id <- as.character(consulta$consulta_id)
  referencias <- presupuesto$referencias_mediana
  referencias[[id]] <- list(
    consulta_id = as.integer(consulta$consulta_id),
    n_filas = filas, n_medianas = as.integer(medianas),
    duracion_ms = as.numeric(consulta$duracion_ms),
    ms_por_fila = as.numeric(consulta$duracion_ms) / (filas * medianas)
  )
  presupuesto$referencias_mediana <- referencias
  invisible(NULL)
}

.proyeccion_mediana_vacia_dbi <- function(
    motivo = paste(
      "No hay una duraci\u00f3n medida de mediana en esta corrida y no se",
      "publica una proyecci\u00f3n temporal."
    )) {
  list(
    disponible = FALSE, duracion_estimada_ms = NA_real_,
    duracion_referencia_ms = NA_real_, ms_por_fila = NA_real_,
    n_filas = NA_real_, n_medianas = 0L, n_referencias = 0L,
    fuente = NA_character_, referencia_declarada = FALSE,
    cota_lectura_ms = NA_real_, motivo = motivo
  )
}

.proyectar_costo_mediana_dbi <- function(
    presupuesto, n_filas, n_medianas, usar_referencia_banco = FALSE) {
  filas <- .numero_dbi(n_filas)
  medianas <- .numero_dbi(n_medianas)
  vacia <- .proyeccion_mediana_vacia_dbi()
  if (length(filas) != 1L || is.na(filas) || !is.finite(filas) || filas <= 0 ||
      length(medianas) != 1L || is.na(medianas) || !is.finite(medianas) ||
      medianas < 1) {
    vacia$motivo <- "No hay un n\u00famero utilizable de filas o medianas pendientes; no se puede proyectar la mediana."
    return(vacia)
  }
  referencias <- if (is.null(presupuesto)) list() else presupuesto$referencias_mediana
  tasas <- if (length(referencias)) vapply(referencias, function(x) {
    valor <- .numero_dbi(x$ms_por_fila)
    if (length(valor) != 1L || is.na(valor) || !is.finite(valor) || valor <= 0) {
      duracion <- .numero_dbi(x$duracion_ms)
      filas_referencia <- .numero_dbi(x$n_filas)
      medianas_referencia <- .numero_dbi(x$n_medianas)
      if (length(duracion) == 1L && is.finite(duracion) &&
          length(filas_referencia) == 1L && is.finite(filas_referencia) &&
          filas_referencia > 0 && length(medianas_referencia) == 1L &&
          is.finite(medianas_referencia) && medianas_referencia > 0) {
        valor <- duracion / (filas_referencia * medianas_referencia)
      }
    }
    if (length(valor) != 1L || is.na(valor) || !is.finite(valor) || valor <= 0) {
      NA_real_
    } else valor
  }, numeric(1L)) else numeric()
  tasas <- tasas[is.finite(tasas) & tasas > 0]
  declarada <- FALSE
  if (length(tasas)) {
    referencia <- stats::median(tasas)
    fuente <- paste(
      "mediana de", length(tasas),
      if (length(tasas) == 1L) {
        "consulta de mediana medida en esta corrida (ms por fila)"
      } else {
        "consultas de medianas medidas en esta corrida (ms por fila)"
      }
    )
    motivo <- paste(
      "La proyecci\u00f3n usa la mediana de las tasas ms por fila de las",
      "medianas medidas en esta corrida y la multiplica por las filas y",
      "medianas pendientes."
    )
  } else if (isTRUE(usar_referencia_banco)) {
    referencia <- .REFERENCIA_BANCO_MEDIANA_MS_POR_MILLON_FILAS_DBI / 1e6
    # Con la escritura publicada: `paste()` del doble decia "6.8e+01" con
    # `scipen = -9`.
    fuente <- paste(
      "referencia de banco de otra corrida:",
      .formatear_numero_publicado(
        .REFERENCIA_BANCO_MEDIANA_MS_POR_MILLON_FILAS_DBI
      ),
      "ms por mill\u00f3n de filas"
    )
    motivo <- paste(
      "No hubo una primera medici\u00f3n local de mediana en esta corrida; se",
      "usa la referencia de banco declarada de otra corrida, no como una",
      "medici\u00f3n local."
    )
    declarada <- TRUE
  } else {
    vacia$motivo <- paste(
      "Todav\u00eda no hay una primera medici\u00f3n local de mediana para convertir",
      "las filas en tiempo; la referencia de banco s\u00f3lo se usa cuando no hay",
      "una mediana total local que pueda proyectarse."
    )
    return(vacia)
  }
  estimada <- referencia * filas * medianas
  cota_lectura <- NA_real_
  if (isTRUE(declarada) && !is.null(presupuesto)) {
    lectura <- .numero_dbi(presupuesto$duracion_lectura_mediana)
    if (length(lectura) == 1L && is.finite(lectura) && lectura > 0) {
      cota_lectura <- lectura * medianas
      if (is.finite(cota_lectura) && cota_lectura > estimada) {
        estimada <- cota_lectura
        fuente <- paste(
          fuente,
          paste0(
            "cota de lectura observada en la consulta inicial (",
            .segundos_dbi(lectura), " s)"
          ),
          sep = "; "
        )
        motivo <- paste(
          motivo,
          "La proyecci\u00f3n no baja de la cota observada de lectura de la consulta que obtuvo las filas; esa cota no es una medici\u00f3n de mediana.",
          sep = " "
        )
      }
    }
  }
  if (!is.finite(estimada)) {
    vacia$motivo <- "La proyecci\u00f3n de la mediana no es finita; no se publica un n\u00famero."
    return(vacia)
  }
  list(
    disponible = TRUE, duracion_estimada_ms = estimada,
    duracion_referencia_ms = referencia * filas * medianas,
    ms_por_fila = referencia, n_filas = filas,
    n_medianas = as.integer(medianas), n_referencias = as.integer(length(tasas)),
    fuente = fuente, referencia_declarada = declarada,
    cota_lectura_ms = cota_lectura, motivo = motivo
  )
}

.avisar_costo_mediana_dbi <- function(
    proyeccion, habilitado = TRUE,
    umbral_segundos = .UMBRAL_SEGUNDOS_AVISO_MEDIANA_DBI) {
  habilitado <- .validar_interruptor_aviso_dbi(habilitado, "habilitado")
  umbral_segundos <- .validar_umbral_aviso_dbi(
    umbral_segundos, "umbral_segundos"
  )
  if (is.null(proyeccion) || !isTRUE(proyeccion$disponible) ||
      !isTRUE(habilitado) || !is.finite(umbral_segundos) ||
      is.na(proyeccion$duracion_estimada_ms) ||
      proyeccion$duracion_estimada_ms < umbral_segundos * 1000) {
    return(invisible(FALSE))
  }
  cli::cli_alert_warning(.cli_literal(.marcar_para_exhibir(paste0(
    "Costo estimado de la mediana: ~",
    .segundos_dbi(proyeccion$duracion_estimada_ms), " s para ",
    proyeccion$n_medianas,
    if (proyeccion$n_medianas == 1L) " mediana sobre " else " medianas sobre ",
    .entero_sql_dbi(proyeccion$n_filas),
    if (proyeccion$n_filas == 1L) " fila. Fuente: " else " filas. Fuente: ",
    proyeccion$fuente, ". ", proyeccion$motivo
  ))))
  invisible(TRUE)
}

.segundos_dbi <- function(milisegundos) {
  if (is.null(milisegundos) || length(milisegundos) != 1L ||
      is.na(milisegundos) || !is.finite(milisegundos)) return("sin dato")
  formatC(milisegundos / 1000, format = "f", digits = 1,
          decimal.mark = ",")
}

.UMBRAL_SEGUNDOS_AVISO_DISTINTOS_DBI <- 30
.UMBRAL_SEGUNDOS_AVISO_MODA_DBI <- 30
.UMBRAL_SEGUNDOS_AVISO_MEDIANA_DBI <- 30
.REFERENCIA_BANCO_MEDIANA_MS_POR_MILLON_FILAS_DBI <- 68
.TASA_NEWID_MS_POR_MILLON_DBI <- 650
.MAX_FILAS_NEWID_DBI <- 100000
.MIN_FRACCION_NEWID_DBI <- 0.20
.MAX_PROYECCION_NEWID_MS_DBI <- 1000
.UMBRAL_BYTES_AVISO_DERRAME_ESTIMADO_DBI <- 0
.UMBRAL_FILAS_AVISO_AGREGADOS_DBI <- 100000000
# Nombre interno historico, expresado en milisegundos como lo estaba antes de
# que el umbral publico pasara a declarar su unidad en segundos.
.UMBRAL_AVISO_DISTINTOS_DBI <- .UMBRAL_SEGUNDOS_AVISO_DISTINTOS_DBI * 1000

.aviso_costo_agregados_dbi <- function(conexion, tabla, preparacion) {
  if (!identical(preparacion$universo, "tabla_completa")) return(NULL)
  estimacion <- tryCatch(
    # Es una consulta interna del aviso previo y no pasa por el presupuesto:
    # `max_consultas` no la deja afuera. Pero viaja al motor, y se cuenta en
    # las emitidas; el plan la anticipa con la misma pregunta
    # (`.consultas_catalogo_aviso_dbi()`), asi que un `max_consultas` igual al
    # total del plan sigue alcanzando para todas las metricas.
    .estimar_bytes_fila_muestra_dbi(
      conexion, tabla, NULL, contar_en = preparacion$presupuesto
    ),
    error = function(e) NULL
  )
  if (is.null(estimacion) || !isTRUE(estimacion$disponible) ||
      !is.finite(estimacion$filas_catalogo) ||
      estimacion$filas_catalogo < .UMBRAL_FILAS_AVISO_AGREGADOS_DBI) {
    return(NULL)
  }
  list(
    filas = estimacion$filas_catalogo,
    umbral = .UMBRAL_FILAS_AVISO_AGREGADOS_DBI,
    fuente = estimacion$fuente,
    sugerencia = "universo = \"muestra_motor\""
  )
}

.evaluar_guardia_newid_dbi <- function(n_total, tamano_muestra,
                                       medianas_pendientes = 1L) {
  total <- .numero_dbi(n_total)
  muestra <- .numero_dbi(tamano_muestra)
  pendientes <- .numero_dbi(medianas_pendientes)
  fraccion <- if (length(total) == 1L && is.finite(total) && total > 0 &&
                  length(muestra) == 1L && is.finite(muestra)) {
    muestra / total
  } else {
    NA_real_
  }
  proyeccion <- if (length(total) == 1L && is.finite(total) && total >= 0 &&
                    length(pendientes) == 1L && is.finite(pendientes) &&
                    pendientes >= 1) {
    .TASA_NEWID_MS_POR_MILLON_DBI / 1e6 * total * pendientes
  } else {
    NA_real_
  }
  condiciones <- c(
    total_valido = length(total) == 1L && is.finite(total) && total >= 0,
    limite_filas = length(total) == 1L && is.finite(total) &&
      total <= .MAX_FILAS_NEWID_DBI,
    fraccion_valida = length(fraccion) == 1L && is.finite(fraccion),
    fraccion_minima = length(fraccion) == 1L && is.finite(fraccion) &&
      fraccion >= .MIN_FRACCION_NEWID_DBI,
    proyeccion_valida = length(proyeccion) == 1L && is.finite(proyeccion),
    proyeccion_maxima = length(proyeccion) == 1L && is.finite(proyeccion) &&
      proyeccion <= .MAX_PROYECCION_NEWID_MS_DBI
  )
  aceptado <- all(condiciones)
  list(
    aceptado = aceptado,
    motivo = if (aceptado) {
      "sesgo_muestreo:random_limit_newid_por_fila"
    } else {
      "capacidad_no_aceptada:newid_costo_excede_presupuesto"
    },
    n_total = total,
    tamano_muestra = muestra,
    fraccion = fraccion,
    medianas_pendientes = as.integer(pendientes),
    proyeccion_newid_ms = proyeccion,
    tasa_ms_por_millon = .TASA_NEWID_MS_POR_MILLON_DBI,
    umbral_n_total = .MAX_FILAS_NEWID_DBI,
    umbral_fraccion = .MIN_FRACCION_NEWID_DBI,
    umbral_proyeccion_ms = .MAX_PROYECCION_NEWID_MS_DBI,
    condiciones = condiciones,
    razon = if (aceptado) {
      "NEWID fue aceptado dentro de los tres l\u00edmites de la pol\u00edtica de costo."
    } else {
      paste(
        "NEWID no se ejecuta: la proyecci\u00f3n conservadora o el tama\u00f1o y la",
        "fracci\u00f3n de la muestra quedan fuera de la pol\u00edtica."
      )
    }
  )
}

.evaluar_guardia_aleatorio_dbi <- function(n_total, tamano_muestra,
                                           funcion = "newid",
                                           medianas_pendientes = 1L) {
  guardia <- .evaluar_guardia_newid_dbi(
    n_total, tamano_muestra, medianas_pendientes
  )
  funcion <- as.character(funcion)[[1L]]
  guardia$funcion <- funcion
  if (!identical(funcion, "newid")) {
    guardia$motivo <- if (isTRUE(guardia$aceptado)) {
      paste0("sesgo_muestreo:random_limit_", funcion, "_por_fila")
    } else {
      paste0(
        "capacidad_no_aceptada:", funcion,
        "_costo_excede_presupuesto"
      )
    }
    guardia$razon <- if (isTRUE(guardia$aceptado)) {
      paste0(
        funcion, " fue aceptado dentro de los tres l\u00edmites de la pol\u00edtica de",
        " costo."
      )
    } else {
      paste(
        funcion, "no se ejecuta: la proyecci\u00f3n conservadora o el tama\u00f1o y la",
        "fracci\u00f3n de la muestra quedan fuera de la pol\u00edtica."
      )
    }
  }
  guardia
}

.validar_interruptor_aviso_dbi <- function(valor, nombre) {
  if (!is.logical(valor) || length(valor) != 1L || is.na(valor)) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      paste0("`", nombre, "` debe ser TRUE o FALSE.")
    )
  }
  valor
}

.validar_umbral_aviso_dbi <- function(valor, nombre) {
  if (!is.numeric(valor) || length(valor) != 1L || is.na(valor) || valor < 0 ||
      (!is.infinite(valor) && !is.finite(valor))) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      paste0("`", nombre, "` debe ser un n\u00famero no negativo o Inf.")
    )
  }
  as.numeric(valor)
}

.avisar_costo_distintos_dbi <- function(
    proyeccion, habilitado = TRUE,
    umbral_segundos = .UMBRAL_SEGUNDOS_AVISO_DISTINTOS_DBI) {
  habilitado <- .validar_interruptor_aviso_dbi(habilitado, "habilitado")
  umbral_segundos <- .validar_umbral_aviso_dbi(
    umbral_segundos, "umbral_segundos"
  )
  if (is.null(proyeccion) || !isTRUE(proyeccion$disponible) ||
      !isTRUE(habilitado) || !is.finite(umbral_segundos) ||
      is.na(proyeccion$duracion_estimada_ms) ||
      proyeccion$duracion_estimada_ms < umbral_segundos * 1000) {
    return(invisible(NULL))
  }
  cli::cli_alert_warning(.cli_literal(.marcar_para_exhibir(paste0(
    "Costo estimado de `COUNT(DISTINCT)`: ~",
    .segundos_dbi(proyeccion$duracion_estimada_ms), " s para ",
    proyeccion$n_lotes,
    if (proyeccion$n_lotes == 1L) " lote. Fuente: " else " lotes. Fuente: ",
    proyeccion$fuente,
    ". Es una estimaci\u00f3n, no una medici\u00f3n; el derrame real se informa",
    " despu\u00e9s si la instrumentaci\u00f3n del servidor lo permite."
  ))))
  invisible(NULL)
}

# PostgreSQL cuenta la memoria de las operaciones hash en unidades de 1024.
# `avg_width` esta expresado en bytes, asi que la cifra que sigue es una
# aproximacion deliberadamente simple: el ancho medio de la clave mas un
# margen fijo para la entrada y el enlace de la tabla hash. No pretende
# reproducir el planificador ni afirmar que hubo derrame.
.TAMANO_BASE_ENTRADA_HASH_POSTGRESQL_DBI <- 64

# La huella de un `SortTuple` no desaparece cuando el valor es corto. Estos
# pisos gobiernan solo la decision de memoria; el tamano del tape queda como
# una magnitud informativa aparte.
.TAMANO_BASE_SORT_POSTGRESQL_DBI <- 24
.PISO_SORT_FIJOS_POSTGRESQL_DBI <- 32
.PISO_SORT_NUMERIC_POSTGRESQL_DBI <- 42

.memoria_dbi <- function(bytes) {
  if (is.null(bytes) || length(bytes) != 1L || is.na(bytes) ||
      !is.finite(bytes) || bytes < 0) return("sin dato")
  unidades <- c("B", "KB", "MB", "GB", "TB")
  indice <- if (bytes == 0) 1L else min(
    floor(log(bytes, base = 1024)) + 1L, length(unidades)
  )
  valor <- bytes / 1024^(indice - 1L)
  paste0(formatC(valor, format = "f", digits = 1L, decimal.mark = ","),
         " ", unidades[[indice]])
}

.parsear_memoria_postgresql_dbi <- function(valor) {
  if (is.null(valor) || length(valor) != 1L || is.na(valor)) {
    return(NA_real_)
  }
  texto <- .minusculas_ascii(trimws(as.character(valor)))
  partes <- regexec(
    "^([0-9]+(?:\\.[0-9]+)?)\\s*(b|kb|kib|mb|mib|gb|gib|tb|tib)?$",
    texto, perl = TRUE
  )[[1L]]
  if (identical(partes[[1L]], -1L)) return(NA_real_)
  capturas <- regmatches(texto, list(partes))[[1L]]
  numero <- suppressWarnings(as.numeric(capturas[[2L]]))
  unidad <- if (length(capturas) < 3L || is.na(capturas[[3L]])) {
    ""
  } else capturas[[3L]]
  multiplicador <- c(
    b = 1, kb = 1024, kib = 1024, mb = 1024^2, mib = 1024^2,
    gb = 1024^3, gib = 1024^3, tb = 1024^4, tib = 1024^4
  )
  if (!length(unidad) || is.na(unidad) || !nzchar(unidad)) unidad <- "b"
  resultado <- numero * unname(multiplicador[[unidad]])
  if (!is.finite(resultado) || resultado < 0) NA_real_ else resultado
}

.estimacion_derrame_vacia_postgresql_dbi <- function(
    estado = "no_disponible", motivo = "No se pudo estimar el derrame.",
    memoria = NULL) {
  if (is.null(memoria)) memoria <- list()
  list(
    estado = estado, disponible = FALSE, es_estimacion = TRUE,
    fuente = NA_character_, motivo = motivo,
    work_mem = if (is.null(memoria$work_mem)) NA_character_ else memoria$work_mem,
    work_mem_bytes = if (is.null(memoria$work_mem_bytes)) NA_real_ else {
      memoria$work_mem_bytes
    },
    hash_mem_multiplier = if (is.null(memoria$hash_mem_multiplier)) NA_real_ else {
      memoria$hash_mem_multiplier
    },
    hash_mem_multiplier_disponible = isTRUE(memoria$hash_mem_multiplier_disponible),
    memoria_efectiva_bytes = if (is.null(memoria$memoria_efectiva_bytes)) {
      NA_real_
    } else memoria$memoria_efectiva_bytes,
    memoria_efectiva = if (is.null(memoria$memoria_efectiva)) {
      NA_character_
    } else memoria$memoria_efectiva,
    columnas = data.frame(
      columna = character(), n_distintos_estimados = numeric(),
      avg_width = numeric(), tamano_estimado_bytes = numeric(),
      n_relaciones = integer(), stringsAsFactors = FALSE
    ),
    columnas_no_estimadas = data.frame(
      columna = character(), motivo = character(), stringsAsFactors = FALSE
    ),
    lotes = data.frame(
      lote = integer(), columnas = character(),
      n_distintos_estimados = numeric(), tamano_estimado_bytes = numeric(),
      supera_memoria = logical(), stringsAsFactors = FALSE
    ),
    lotes_sobre_memoria = integer(),
    filas_catalogo = .denominador_catalogo_vacio_dbi(motivo)
  )
}

.denominador_catalogo_vacio_dbi <- function(
    motivo = "No hay una estimaci\u00f3n utilizable de `pg_class.reltuples`.") {
  list(
    disponible = FALSE, estado = "no_disponible", filas = NA_real_,
    fuente = NA_character_, n_relaciones = 0L, motivo = motivo
  )
}

# La consulta de estadisticas ya recorre la jerarquia y devuelve solo las hojas;
# aca se aplica el mismo denominador que usa `catalogo`, sin inventar otra
# consulta ni volver a sumar una relacion padre particionada.
.denominador_catalogo_dbi <- function(datos) {
  vacio <- .denominador_catalogo_vacio_dbi()
  if (!is.data.frame(datos) || !all(c(
    "relacion_oid", "reltuples", "hoja"
  ) %in% names(datos))) {
    vacio$motivo <- paste(
      "La respuesta del cat\u00e1logo no trae la jerarqu\u00eda y `reltuples` necesarios;",
      "se conserva `sin dato filas`."
    )
    return(vacio)
  }
  relaciones <- unique(datos[c("relacion_oid", "reltuples", "hoja")])
  hojas <- .logico_catalogo_dbi(relaciones$hoja)
  relaciones <- relaciones[!is.na(relaciones$relacion_oid) & hojas %in% TRUE,
                            , drop = FALSE]
  if (!nrow(relaciones)) {
    vacio$motivo <- paste(
      "El cat\u00e1logo no devolvi\u00f3 relaciones hoja visibles; no hay una",
      "estimaci\u00f3n utilizable de `pg_class.reltuples`."
    )
    return(vacio)
  }
  reltuples <- suppressWarnings(as.numeric(relaciones$reltuples))
  if (any(!is.finite(reltuples) | reltuples <= 0)) {
    vacio$motivo <- paste(
      "`pg_class.reltuples` tiene al menos un valor cero, negativo o no",
      "utilizable; puede no haberse ejecutado ANALYZE. Se conserva `sin dato",
      "filas` y no se supone cero."
    )
    return(vacio)
  }
  filas <- sum(reltuples)
  if (!is.finite(filas) || filas <= 0) {
    vacio$motivo <- paste(
      "La suma de `pg_class.reltuples` no es utilizable; se conserva `sin",
      "dato filas` y no se supone cero."
    )
    return(vacio)
  }
  list(
    disponible = TRUE, estado = "estimado_catalogo", filas = filas,
    fuente = "pg_class.reltuples", n_relaciones = as.integer(nrow(relaciones)),
    motivo = paste(
      "Las filas se estiman como la suma de `pg_class.reltuples` de las",
      "relaciones hoja de la jerarqu\u00eda ya le\u00edda. Es una estimaci\u00f3n de cat\u00e1logo,",
      "no una medici\u00f3n del universo de la tabla."
    )
  )
}

.leer_memoria_postgresql_dbi <- function(conexion, presupuesto) {
  if (!is.null(presupuesto) && !is.null(presupuesto$memoria_derrame)) {
    return(presupuesto$memoria_derrame)
  }
  sql <- paste0(
    "SELECT name, setting FROM pg_settings WHERE name IN ",
    "('work_mem', 'hash_mem_multiplier')"
  )
  consulta <- .consultar_dbi(
    conexion, sql, presupuesto, etapa = "estimacion_derrame"
  )
  if (!isTRUE(consulta$ok) || !is.data.frame(consulta$datos) ||
      !all(c("name", "setting") %in% names(consulta$datos))) {
    return(list(
      ok = FALSE, motivo = paste(
        "No se pudo estimar el derrame: no se pudieron leer los parametros",
        "de memoria.", consulta$motivo %||% "respuesta sin columnas esperadas."
      )
    ))
  }
  nombres <- .minusculas_ascii(as.character(consulta$datos$name))
  posicion_work <- which(nombres == "work_mem")
  if (!length(posicion_work)) {
    return(list(
      ok = FALSE, motivo = paste(
        "No se pudo estimar el derrame: `pg_settings` no devolvi\u00f3 `work_mem`."
      )
    ))
  }
  work_texto <- as.character(consulta$datos$setting[[posicion_work[[1L]]]])
  work_bytes <- .parsear_memoria_postgresql_dbi(work_texto)
  if (!is.finite(work_bytes)) {
    return(list(
      ok = FALSE, motivo = paste0(
        "No se pudo estimar el derrame: `SHOW work_mem` devolvi\u00f3 un valor",
        " no interpretable (", work_texto, ")."
      )
    ))
  }

  hash_disponible <- FALSE
  multiplicador <- 1
  motivo_hash <- character()
  posicion_hash <- which(nombres == "hash_mem_multiplier")
  if (length(posicion_hash)) {
    multiplicador <- suppressWarnings(as.numeric(
      consulta$datos$setting[[posicion_hash[[1L]]]]
    ))
    hash_disponible <- is.finite(multiplicador) && multiplicador > 0
    if (!hash_disponible) {
      multiplicador <- 1
      motivo_hash <- "`SHOW hash_mem_multiplier` devolvi\u00f3 un valor no utilizable."
    }
  } else {
    motivo_hash <- paste(
      "El servidor no expone `hash_mem_multiplier`; se usa 1, como en",
      "PostgreSQL anterior a 13."
    )
  }
  efectiva <- work_bytes * multiplicador
  list(
    ok = is.finite(efectiva) && efectiva >= 0,
    motivo = motivo_hash, work_mem = work_texto,
    work_mem_bytes = work_bytes, hash_mem_multiplier = multiplicador,
    hash_mem_multiplier_disponible = hash_disponible,
    memoria_efectiva_bytes = efectiva, memoria_efectiva = .memoria_dbi(efectiva)
  )
}

.estadisticas_hash_postgresql_dbi <- function(conexion, tabla, columnas,
                                              presupuesto) {
  if (!is.null(presupuesto) && !is.null(presupuesto$estadisticas_derrame)) {
    return(presupuesto$estadisticas_derrame)
  }
  piezas <- .piezas_tabla_cardinalidad_dbi(tabla)
  if (is.null(piezas$tabla) || length(piezas$tabla) != 1L ||
      is.na(piezas$tabla) || !nzchar(piezas$tabla)) {
    return(list(
      ok = FALSE, motivo = "No se pudo identificar la relaci\u00f3n para consultar `pg_stats`."
    ))
  }
  citar <- function(valor) as.character(DBI::dbQuoteString(conexion, valor))
  tabla_literal <- citar(piezas$tabla)
  esquema <- piezas$esquema
  filtro_esquema <- if (!is.null(esquema) && length(esquema) == 1L &&
                        !is.na(esquema) && nzchar(esquema)) {
    paste0("n.nspname = ", citar(esquema))
  } else {
    # `pg_table_is_visible()` existe en las versiones antiguas y evita tomar
    # una tabla homonima que no seria la que resolvio el search_path.
    "pg_catalog.pg_table_is_visible(c.oid)"
  }
  columnas_literal <- paste(vapply(columnas, citar, character(1L)), collapse = ", ")
  sql <- paste(
    "WITH RECURSIVE relaciones AS (",
    "SELECT c.oid, n.nspname AS schemaname, c.relname AS tablename,",
    "c.reltuples, TRUE AS es_raiz,",
    "NOT EXISTS (SELECT 1 FROM pg_catalog.pg_inherits h",
    "WHERE h.inhparent = c.oid) AS hoja",
    "FROM pg_catalog.pg_class c",
    "JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace",
    "WHERE c.relname =", tabla_literal, "AND", filtro_esquema,
    "UNION ALL",
    "SELECT hija.oid, ns.nspname AS schemaname, hija.relname AS tablename,",
    "hija.reltuples, FALSE AS es_raiz,",
    "NOT EXISTS (SELECT 1 FROM pg_catalog.pg_inherits h2",
    "WHERE h2.inhparent = hija.oid) AS hoja",
    "FROM pg_catalog.pg_inherits herencia",
    "JOIN relaciones padre ON padre.oid = herencia.inhparent",
    "JOIN pg_catalog.pg_class hija ON hija.oid = herencia.inhrelid",
    "JOIN pg_catalog.pg_namespace ns ON ns.oid = hija.relnamespace",
    ")",
    "SELECT r.oid::text AS relacion_oid, r.schemaname, r.tablename,",
    "r.reltuples, r.es_raiz, r.hoja, s.attname, s.n_distinct, s.avg_width,",
    "s.null_frac, format_type(a.atttypid, a.atttypmod) AS tipo",
    "FROM relaciones r",
    "LEFT JOIN pg_catalog.pg_stats s ON",
    "s.schemaname = r.schemaname AND s.tablename = r.tablename",
    "AND s.attname IN (", columnas_literal, ")",
    "LEFT JOIN pg_catalog.pg_attribute a ON a.attrelid = r.oid",
    "AND a.attname = s.attname AND a.attnum > 0 AND NOT a.attisdropped",
    "WHERE r.hoja",
    "ORDER BY r.oid, s.attname"
  )
  consulta <- .consultar_dbi(
    conexion, sql, presupuesto, etapa = "estimacion_derrame"
  )
  if (!isTRUE(consulta$ok)) {
    salida <- list(
      ok = FALSE, sql = sql, motivo = paste(
        "No se pudo estimar el derrame: no se pudo leer `pg_stats` y",
        "`pg_class`.", consulta$motivo
      )
    )
    if (!is.null(presupuesto)) presupuesto$estadisticas_derrame <- salida
    return(salida)
  }
  esperadas <- c(
    "relacion_oid", "schemaname", "tablename", "reltuples", "es_raiz",
    "hoja", "attname", "n_distinct", "avg_width"
  )
  if (!all(esperadas %in% names(consulta$datos))) {
    salida <- list(
      ok = FALSE, sql = sql, motivo = paste(
        "No se pudo estimar el derrame: la respuesta de `pg_stats` no",
        "contiene las columnas esperadas."
      )
    )
    if (!is.null(presupuesto)) presupuesto$estadisticas_derrame <- salida
    return(salida)
  }
  salida <- list(
    ok = TRUE, sql = sql, datos = consulta$datos,
    filas_catalogo = .denominador_catalogo_dbi(consulta$datos)
  )
  if (!is.null(presupuesto)) presupuesto$estadisticas_derrame <- salida
  salida
}

.estimar_derrame_postgresql_dbi <- function(conexion, tabla, columnas,
                                            presupuesto,
                                            exacto = TRUE,
                                            universo = "tabla_completa",
                                            tamano_lote = .TAMANO_LOTE_DISTINTOS_DBI,
                                            columnas_stats = NULL) {
  if (!isTRUE(exacto)) {
    return(.estimacion_derrame_vacia_postgresql_dbi(
      "no_solicitado", paste(
        "No se solicit\u00f3 una estimaci\u00f3n de derrame porque la estrategia de",
        "distintos no emite `COUNT(DISTINCT)` exacto."
      )
    ))
  }
  if (identical(universo, "muestra_motor")) {
    return(.estimacion_derrame_vacia_postgresql_dbi(
      motivo = paste(
        "No se pudo estimar el derrame de una muestra con las estad\u00edsticas",
        "de la tabla completa; no se inventa una equivalencia."
      )
    ))
  }
  if (!length(columnas)) {
    return(.estimacion_derrame_vacia_postgresql_dbi(
      "no_solicitado", paste(
        "No se solicit\u00f3 una estimaci\u00f3n de derrame porque no hay columnas",
        "que vayan a pasar por `COUNT(DISTINCT)`."
      )
    ))
  }
  if (!grepl(.regex_sin_caja("postgres|pqconnection"),
             .senas_conexion_dbi(conexion), perl = TRUE)) {
    return(.estimacion_derrame_vacia_postgresql_dbi(
      motivo = paste(
        "No se pudo estimar el derrame: la conexi\u00f3n no fue reconocida como",
        "PostgreSQL y no hay un `pg_stats` portable."
      )
    ))
  }
  memoria <- .leer_memoria_postgresql_dbi(conexion, presupuesto)
  if (!isTRUE(memoria$ok)) {
    return(.estimacion_derrame_vacia_postgresql_dbi(
      motivo = memoria$motivo, memoria = memoria
    ))
  }
  if (!is.null(presupuesto)) presupuesto$memoria_derrame <- memoria
  columnas_stats <- if (is.null(columnas_stats)) columnas else columnas_stats
  estadisticas <- .estadisticas_hash_postgresql_dbi(
    conexion, tabla, columnas_stats, presupuesto
  )
  if (!isTRUE(estadisticas$ok)) {
    return(.estimacion_derrame_vacia_postgresql_dbi(
      motivo = estadisticas$motivo, memoria = memoria
    ))
  }
  datos <- estadisticas$datos
  filas_catalogo <- estadisticas$filas_catalogo
  relaciones <- unique(datos[c(
    "relacion_oid", "schemaname", "tablename", "reltuples", "es_raiz", "hoja"
  )])
  relaciones <- relaciones[!is.na(relaciones$relacion_oid) &
                             relaciones$hoja %in% TRUE, , drop = FALSE]
  nombres_stats <- as.character(datos$attname)
  columnas_estimadas <- list()
  columnas_no_estimadas <- list()
  for (columna in columnas) {
    filas <- datos[!is.na(datos$attname) &
                     .nombres_para_operar(nombres_stats) %in%
                       .nombres_para_operar(columna), , drop = FALSE]
    ids_relaciones <- as.character(relaciones$relacion_oid)
    ids_stats <- if (nrow(filas)) unique(as.character(filas$relacion_oid)) else {
      character()
    }
    faltantes <- setdiff(ids_relaciones, ids_stats)
    motivo <- NULL
    if (!nrow(relaciones)) {
      motivo <- paste(
        "`pg_stats` no devolvi\u00f3 ninguna relaci\u00f3n visible; la tabla puede no",
        "haber sido `ANALYZE` o la credencial puede no tener privilegios sobre",
        "sus columnas."
      )
    } else if (!length(filas)) {
      motivo <- paste(
        "`pg_stats` no devolvi\u00f3 una fila para esta columna; puede no haber",
        "`ANALYZE` o la credencial puede no tener privilegio sobre la columna."
      )
    } else if (length(faltantes)) {
      motivo <- paste(
        "No hay una estad\u00edstica visible para todas las relaciones que se",
        "leen; faltan particiones o columnas sin `ANALYZE`/permiso."
      )
    }
    if (!is.null(motivo)) {
      columnas_no_estimadas[[length(columnas_no_estimadas) + 1L]] <- data.frame(
        columna = columna, motivo = motivo, stringsAsFactors = FALSE
      )
      next
    }
    filas <- filas[!duplicated(as.character(filas$relacion_oid)), , drop = FALSE]
    n_distintos <- numeric(nrow(filas))
    tamanos <- numeric(nrow(filas))
    anchos <- numeric(nrow(filas))
    invalidos <- character()
    for (i in seq_len(nrow(filas))) {
      nd <- suppressWarnings(as.numeric(filas$n_distinct[[i]]))
      ancho <- suppressWarnings(as.numeric(filas$avg_width[[i]]))
      reltuples <- suppressWarnings(as.numeric(filas$reltuples[[i]]))
      if (!is.finite(nd) || !is.finite(ancho) || ancho < 0) {
        invalidos <- c(invalidos, "`n_distinct` o `avg_width` no utilizable")
        next
      }
      if (nd < 0) {
        # Un `n_distinct` negativo es una proporcion del universo. `-1` es
        # unico por fila; `reltuples = -1` significa desconocido, no cero.
        if (!is.finite(reltuples) || reltuples < 0) {
          invalidos <- c(
            invalidos,
            "`n_distinct` negativo requiere `pg_class.reltuples`; `reltuples = -1` es desconocido"
          )
          next
        }
        nd <- ceiling(abs(nd) * reltuples)
      } else {
        nd <- ceiling(nd)
      }
      n_distintos[[i]] <- nd
      anchos[[i]] <- ancho
      tamanos[[i]] <- nd * (ancho + .TAMANO_BASE_ENTRADA_HASH_POSTGRESQL_DBI)
    }
    if (length(invalidos) || any(!is.finite(n_distintos)) ||
        any(!is.finite(tamanos))) {
      columnas_no_estimadas[[length(columnas_no_estimadas) + 1L]] <- data.frame(
        columna = columna,
        motivo = paste(unique(invalidos), collapse = "; "),
        stringsAsFactors = FALSE
      )
      next
    }
    total_distintos <- sum(n_distintos)
    columnas_estimadas[[length(columnas_estimadas) + 1L]] <- data.frame(
      columna = columna,
      n_distintos_estimados = total_distintos,
      avg_width = if (total_distintos > 0) {
        sum(n_distintos * anchos) / total_distintos
      } else mean(anchos),
      tamano_estimado_bytes = sum(tamanos),
      n_relaciones = as.integer(nrow(filas)),
      stringsAsFactors = FALSE
    )
  }
  columnas_df <- if (length(columnas_estimadas)) {
    do.call(rbind, columnas_estimadas)
  } else {
    .estimacion_derrame_vacia_postgresql_dbi(memoria = memoria)$columnas
  }
  no_estimadas_df <- if (length(columnas_no_estimadas)) {
    do.call(rbind, columnas_no_estimadas)
  } else {
    .estimacion_derrame_vacia_postgresql_dbi(memoria = memoria)$columnas_no_estimadas
  }
  lotes_indices <- split(
    seq_along(columnas), ceiling(seq_along(columnas) / tamano_lote)
  )
  lotes <- lapply(seq_along(lotes_indices), function(numero) {
    indices <- lotes_indices[[numero]]
    nombres <- columnas[indices]
    conocidos <- !is.na(.indice_nombre(nombres, columnas_df$columna))
    tamano <- if (all(conocidos)) {
      sum(columnas_df$tamano_estimado_bytes[
        .indice_nombre(nombres, columnas_df$columna)
      ])
    } else NA_real_
    cantidad <- if (all(conocidos)) {
      sum(columnas_df$n_distintos_estimados[
        .indice_nombre(nombres, columnas_df$columna)
      ])
    } else NA_real_
    data.frame(
      lote = as.integer(numero), columnas = paste(nombres, collapse = ", "),
      n_distintos_estimados = cantidad, tamano_estimado_bytes = tamano,
      supera_memoria = if (is.finite(tamano)) {
        tamano > memoria$memoria_efectiva_bytes
      } else NA,
      stringsAsFactors = FALSE
    )
  })
  lotes_df <- do.call(rbind, lotes)
  columnas_internas <- lapply(
    lotes_indices, function(indices) as.character(columnas[indices])
  )
  if (any(vapply(columnas_internas, function(x) {
    length(x) > 1L && any(grepl(",", x, fixed = TRUE, useBytes = TRUE))
  }, logical(1L)))) {
    attr(lotes_df, "columnas_internas") <- columnas_internas
  }
  sobre <- which(!is.na(lotes_df$supera_memoria) & lotes_df$supera_memoria)
  n_estimadas <- nrow(columnas_df)
  if (!n_estimadas) {
    estado <- "no_disponible"
    motivo <- paste(
      "No se pudo estimar el derrame: `pg_stats` no devolvi\u00f3 estad\u00edsticas",
      "utilizables para las columnas de `COUNT(DISTINCT)`."
    )
  } else if (n_estimadas < length(columnas)) {
    estado <- "parcial"
    motivo <- paste(
      "La estimaci\u00f3n de derrame es parcial: no se pudo estimar al menos una",
      "columna. No se afirma que el hash quede dentro o fuera del l\u00edmite para",
      "los lotes incompletos."
    )
  } else {
    estado <- "estimado"
    motivo <- paste(
      "El tama\u00f1o del hash se estima con `pg_stats.n_distinct`,",
      "`pg_stats.avg_width` y `pg_class.reltuples`. `n_distinct` viene de una",
      "muestra y puede quedar corto: esto es una estimaci\u00f3n, no una medici\u00f3n.",
      "Que el tama\u00f1o estimado quede dentro del l\u00edmite no demuestra que no haya",
      "derrame; si se mide despu\u00e9s, manda `pg_stat_statements`."
    )
  }
  if (length(no_estimadas_df)) {
    motivo <- paste(
      motivo, paste(no_estimadas_df$columna, no_estimadas_df$motivo,
                    sep = ": ", collapse = " ")
    )
  }
  fuente <- paste(
    "pg_stats.n_distinct + pg_stats.avg_width + pg_class.reltuples + SHOW work_mem"
  )
  if (isTRUE(memoria$hash_mem_multiplier_disponible)) {
    fuente <- paste0(fuente, " + SHOW hash_mem_multiplier")
  }
  list(
    estado = estado, disponible = n_estimadas > 0L, es_estimacion = TRUE,
    fuente = fuente, motivo = motivo,
    work_mem = memoria$work_mem, work_mem_bytes = memoria$work_mem_bytes,
    hash_mem_multiplier = memoria$hash_mem_multiplier,
    hash_mem_multiplier_disponible = memoria$hash_mem_multiplier_disponible,
    memoria_efectiva_bytes = memoria$memoria_efectiva_bytes,
    memoria_efectiva = memoria$memoria_efectiva,
    columnas = columnas_df, columnas_no_estimadas = no_estimadas_df,
    lotes = lotes_df, lotes_sobre_memoria = as.integer(sobre),
    n_columnas_solicitadas = as.integer(length(columnas)),
    n_columnas_estimadas = as.integer(n_estimadas),
    filas_catalogo = filas_catalogo,
    supera_memoria = if (length(sobre)) TRUE else if (all(
      !is.na(lotes_df$supera_memoria)
    )) FALSE else NA
  )
}

.limite_decision_derrame_dbi <- function(estimacion, familia = NULL) {
  if (is.null(estimacion)) return("no resoluble: falta la estimaci\u00f3n")
  if (identical(estimacion$metodo, "por_columna")) {
    return("no resoluble: las columnas usan m\u00e9todos de memoria distintos")
  }
  valor <- if (identical(estimacion$metodo, "sort") ||
               identical(familia, "mediana")) {
    estimacion$work_mem
  } else estimacion$memoria_efectiva
  if (is.null(valor) || length(valor) != 1L || is.na(valor) ||
      !nzchar(as.character(valor))) {
    return("no resoluble: el l\u00edmite del motor no estuvo disponible")
  }
  as.character(valor)
}

.denominador_derrame_dbi <- function(estimacion) {
  fuente <- estimacion$fuente_denominador
  if (is.null(fuente) || length(fuente) != 1L || is.na(fuente) ||
      !nzchar(fuente)) {
    fuente <- "estimaci\u00f3n de cat\u00e1logo"
  }
  as.character(fuente)
}

.avisar_derrame_estimado_postgresql_dbi <- function(
    estimacion, habilitado = TRUE,
    umbral_bytes = .UMBRAL_BYTES_AVISO_DERRAME_ESTIMADO_DBI,
    familia = "COUNT(DISTINCT)") {
  habilitado <- .validar_interruptor_aviso_dbi(habilitado, "habilitado")
  umbral_bytes <- .validar_umbral_aviso_dbi(umbral_bytes, "umbral_bytes")
  if (is.null(estimacion)) return(invisible(FALSE))
  if (identical(familia, "COUNT(DISTINCT)") &&
      identical(estimacion$familia, "moda")) familia <- "la moda"
  if (identical(familia, "COUNT(DISTINCT)") &&
      identical(estimacion$familia, "mediana")) familia <- "la mediana"
  if (is.null(estimacion) || !isTRUE(estimacion$es_estimacion) ||
      !isTRUE(habilitado) || !is.finite(umbral_bytes) ||
      !length(estimacion$lotes_sobre_memoria)) return(invisible(FALSE))
  lotes <- estimacion$lotes
  indices <- estimacion$lotes_sobre_memoria
  indices <- indices[is.finite(indices) & indices >= 1L &
    indices <= nrow(lotes)]
  indices <- indices[vapply(
    indices, function(i) is.finite(lotes$tamano_estimado_bytes[[i]]) &&
      lotes$tamano_estimado_bytes[[i]] >= umbral_bytes, logical(1L)
  )]
  if (!length(indices)) return(invisible(FALSE))
  detalle <- paste(vapply(indices, function(i) paste0(
    "lote de ", lotes$columnas[[i]], ": ~",
    .memoria_dbi(lotes$tamano_estimado_bytes[[i]])
  ), character(1L)), collapse = "; ")
  limite <- .limite_decision_derrame_dbi(estimacion, estimacion$familia)
  work_mem <- estimacion$work_mem
  if (is.null(work_mem) || length(work_mem) != 1L || is.na(work_mem) ||
      !nzchar(as.character(work_mem))) work_mem <- "no disponible"
  etiqueta <- if (identical(familia, "COUNT(DISTINCT)")) "" else {
    paste0(" para ", familia)
  }
  # En la moda y la mediana el metodo puede ser solo de cada lote: el campo de la
  # estimacion llegaba vacio y el aviso decia "Metodo: ." -medido siete
  # veces-. Manda el de la estimacion cuando lo hay
  # -`por_columna` dice algo que ningun lote dice-, y si falta, el de los lotes
  # que avisan.
  sin_valor <- function(v) {
    is.null(v) || !length(v) || is.na(v[[1L]]) || !nzchar(v[[1L]])
  }
  metodo <- estimacion$metodo
  if (sin_valor(metodo) && "metodo" %in% names(lotes)) {
    de_lotes <- unique(as.character(lotes$metodo[indices]))
    de_lotes <- de_lotes[!is.na(de_lotes) & nzchar(de_lotes)]
    if (length(de_lotes)) metodo <- paste(de_lotes, collapse = ", ")
  }
  if (sin_valor(metodo)) metodo <- "no determinado"
  cli::cli_alert_warning(.cli_literal(.marcar_para_exhibir(paste0(
    "Derrame potencial estimado", etiqueta,
    " (es una estimaci\u00f3n, no una medici\u00f3n): ",
    detalle, " supera el `work_mem` vigente de ", work_mem,
    ". M\u00e9todo: ", metodo, ". L\u00edmite de decisi\u00f3n: ", limite,
    ". Denominador: con ",
    .denominador_derrame_dbi(estimacion), ". ",
    "Subir `work_mem` en esta sesi\u00f3n por encima de ese tama\u00f1o puede evitar el",
    " derrame; lupa no modifica la configuraci\u00f3n. El derrame real, si ocurre,",
    " se informa despu\u00e9s mediante `pg_stat_statements`."
  ))))
  invisible(TRUE)
}

# ---- Estimaciones de moda y mediana -------------------------------------

.estimacion_derrame_familia_vacia_dbi <- function(
    familia, motivo = paste("No se pudo estimar el derrame de", familia, "."),
    estado = "no_disponible", memoria = NULL, forma = NA_character_) {
  if (is.null(memoria)) memoria <- list()
  work_bytes <- if (is.null(memoria$work_mem_bytes)) NA_real_ else
    memoria$work_mem_bytes
  list(
    estado = estado, disponible = FALSE, es_estimacion = TRUE,
    familia = familia, metodo = NA_character_, forma = forma,
    fuente = NA_character_, motivo = motivo,
    work_mem = if (is.null(memoria$work_mem)) NA_character_ else memoria$work_mem,
    work_mem_bytes = work_bytes,
    hash_mem_multiplier = if (is.null(memoria$hash_mem_multiplier)) NA_real_ else
      memoria$hash_mem_multiplier,
    hash_mem_multiplier_disponible = isTRUE(memoria$hash_mem_multiplier_disponible),
    memoria_efectiva_bytes = if (is.null(memoria$memoria_efectiva_bytes)) {
      work_bytes
    } else memoria$memoria_efectiva_bytes,
    memoria_efectiva = if (is.null(memoria$memoria_efectiva)) {
      .memoria_dbi(work_bytes)
    } else memoria$memoria_efectiva,
    columnas = data.frame(
      columna = character(), metodo = character(), forma = character(),
      tipo_familia = character(), n_distintos_estimados = numeric(),
      n_validos_catalogo = numeric(), n_validos_medido = numeric(),
      avg_width = numeric(), estado_hash_bytes = numeric(),
      estado_sort_bytes = numeric(), estado_memoria_bytes = numeric(),
      estado_io_total_bytes = numeric(), tamano_estimado_bytes = numeric(),
      supera_memoria = logical(), stringsAsFactors = FALSE
    ),
    columnas_no_estimadas = data.frame(
      columna = character(), motivo = character(), stringsAsFactors = FALSE
    ),
    lotes = data.frame(
      lote = integer(), columnas = character(), metodo = character(),
      forma = character(), estado_hash_bytes = numeric(),
      estado_sort_bytes = numeric(), estado_memoria_bytes = numeric(),
      estado_io_total_bytes = numeric(), tamano_estimado_bytes = numeric(),
      supera_memoria = logical(), stringsAsFactors = FALSE
    ),
    lotes_sobre_memoria = integer(), filas_catalogo =
      .denominador_catalogo_vacio_dbi(motivo),
    n_columnas_solicitadas = 0L, n_columnas_estimadas = 0L,
    supera_memoria = NA
  )
}

.familia_tipo_derrame_dbi <- function(tipo, prototipo = NULL) {
  texto <- if (length(tipo) && !is.na(tipo[[1L]])) {
    as.character(tipo[[1L]])
  } else ""
  if (!nzchar(texto) && !is.null(prototipo) && length(prototipo)) {
    if (inherits(prototipo, c("numeric", "integer64"))) texto <- "numeric"
  }
  if (grepl("numeric|decimal|number", .minusculas_ascii(texto), perl = TRUE)) {
    "numeric"
  } else {
    "fijos"
  }
}

.plan_moda_derrame_dbi <- function(conexion, sql, presupuesto) {
  explicacion <- .consultar_dbi(
    conexion, paste0("EXPLAIN (FORMAT JSON, COSTS OFF) ", sql), presupuesto,
    etapa = "explain_moda"
  )
  if (!isTRUE(explicacion$ok) || is.null(explicacion$datos) ||
      !nrow(explicacion$datos)) {
    return(list(
      ok = FALSE, metodo = NA_character_, motivo = paste(
        "No se pudo derivar el m\u00e9todo de la moda desde `EXPLAIN (FORMAT JSON,",
        "COSTS OFF)`.", if (is.null(explicacion$motivo)) "" else explicacion$motivo
      )
    ))
  }
  texto <- paste(unlist(explicacion$datos, use.names = FALSE), collapse = " ")
  # Primero se recorre el arbol JSON, desde el nodo raiz (normalmente
  # `Limit`) hasta el primer `Aggregate`. El regex de abajo queda como
  # compatibilidad para drivers que entregan el JSON como una columna opaca.
  arbol <- tryCatch(
    jsonlite::fromJSON(texto, simplifyVector = FALSE),
    error = function(e) NULL
  )
  buscar <- function(nodo) {
    if (!is.list(nodo)) return(NULL)
    tipo_nodo <- nodo[["Node Type"]]
    if (length(tipo_nodo) && identical(as.character(tipo_nodo[[1L]]), "Aggregate")) {
      estrategia <- nodo[["Strategy"]]
      if (length(estrategia)) return(as.character(estrategia[[1L]]))
    }
    planes <- nodo[["Plans"]]
    if (is.list(planes)) {
      for (hijo in planes) {
        encontrado <- buscar(hijo)
        if (!is.null(encontrado)) return(encontrado)
      }
    }
    for (nombre in setdiff(names(nodo), c("Plans", "Node Type", "Strategy"))) {
      encontrado <- buscar(nodo[[nombre]])
      if (!is.null(encontrado)) return(encontrado)
    }
    NULL
  }
  estrategia_arbol <- if (is.list(arbol)) buscar(arbol) else NULL
  if (identical(estrategia_arbol, "Hashed")) {
    return(list(ok = TRUE, metodo = "hash", motivo = NA_character_))
  }
  if (identical(estrategia_arbol, "Sorted")) {
    return(list(ok = TRUE, metodo = "sort", motivo = NA_character_))
  }
  estrategia <- regmatches(
    texto,
    regexpr('"Strategy"[[:space:]]*:[[:space:]]*"[A-Za-z]+"', texto,
            perl = TRUE)
  )
  if (length(estrategia) && nzchar(estrategia)) {
    if (grepl('"Hashed"', estrategia, fixed = TRUE, useBytes = TRUE)) {
      return(list(ok = TRUE, metodo = "hash", motivo = NA_character_))
    }
    if (grepl('"Sorted"', estrategia, fixed = TRUE, useBytes = TRUE)) {
      return(list(ok = TRUE, metodo = "sort", motivo = NA_character_))
    }
  }
  if (grepl('"Strategy"[[:space:]]*:[[:space:]]*"Hashed"', texto,
            perl = TRUE)) {
    return(list(ok = TRUE, metodo = "hash", motivo = NA_character_))
  }
  if (grepl('"Strategy"[[:space:]]*:[[:space:]]*"Sorted"', texto,
            perl = TRUE)) {
    return(list(ok = TRUE, metodo = "sort", motivo = NA_character_))
  }
  list(
    ok = FALSE, metodo = NA_character_, motivo = paste(
      "`EXPLAIN` no devolvi\u00f3 una estrategia `Hashed` o `Sorted` para el",
      "nodo Aggregate de la moda."
    )
  )
}

.sql_moda_columna_dbi <- function(conexion, tabla_sql, columna_sql, dialecto,
                                  moda_guardian = NULL,
                                  valor_sql = columna_sql,
                                  orden_sql = columna_sql) {
  alias <- function(nombre) {
    .citar_identificador_dbi(conexion, nombre)
  }
  sin_limite <- paste0(
    "SELECT ", valor_sql, " AS ", alias("valor"), ", ",
    .conteo_sql_dbi("COUNT(*)", .senas_conexion_dbi(conexion)), " AS ",
    alias("frecuencia"), " FROM ", tabla_sql, " WHERE ", columna_sql,
    " IS NOT NULL GROUP BY ", columna_sql, " ORDER BY COUNT(*)",
    " DESC, ", orden_sql, " ASC"
  )
  acotada <- dialecto$limitar(sin_limite, 1L, 0)
  list(
    sql = if (is.null(moda_guardian)) {
      if (is.null(acotada)) sin_limite else acotada
    } else moda_guardian$construir(
      columna_sql, tabla_sql, valor_sql, orden_sql
    ),
    filas = if (is.null(acotada)) 1L else -1L
  )
}

.estadisticas_familia_derrame_dbi <- function(datos, columna) {
  if (!is.data.frame(datos) || !all(c(
    "relacion_oid", "reltuples", "hoja", "attname", "n_distinct",
    "avg_width", "null_frac"
  ) %in% names(datos))) {
    return(list(ok = FALSE, motivo = paste(
      "La respuesta del cat\u00e1logo no contiene `null_frac`, `avg_width` y",
      "`reltuples` para estimar la salida."
    )))
  }
  relaciones <- unique(datos[c("relacion_oid", "reltuples", "hoja")])
  relaciones <- relaciones[
    !is.na(relaciones$relacion_oid) &
      .logico_catalogo_dbi(relaciones$hoja) %in% TRUE, , drop = FALSE
  ]
  filas <- datos[!is.na(datos$attname) &
                   .nombres_para_operar(as.character(datos$attname)) %in%
                     .nombres_para_operar(columna),
                 , drop = FALSE]
  if (!nrow(relaciones) || !nrow(filas)) {
    return(list(ok = FALSE, motivo = paste(
      "No hay estad\u00edsticas visibles para todas las relaciones hoja de la",
      "columna; puede faltar `ANALYZE` o permiso de lectura."
    )))
  }
  filas <- filas[!duplicated(as.character(filas$relacion_oid)), , drop = FALSE]
  faltantes <- setdiff(
    as.character(relaciones$relacion_oid), as.character(filas$relacion_oid)
  )
  if (length(faltantes)) {
    return(list(ok = FALSE, motivo = paste(
      "No hay una estad\u00edstica para todas las relaciones hoja de la columna."
    )))
  }
  n_validos <- numeric(nrow(filas))
  n_distintos <- numeric(nrow(filas))
  anchos <- numeric(nrow(filas))
  tipos <- character(nrow(filas))
  for (i in seq_len(nrow(filas))) {
    reltuples <- suppressWarnings(as.numeric(filas$reltuples[[i]]))
    null_frac <- suppressWarnings(as.numeric(filas$null_frac[[i]]))
    nd <- suppressWarnings(as.numeric(filas$n_distinct[[i]]))
    ancho <- suppressWarnings(as.numeric(filas$avg_width[[i]]))
    if (!is.finite(reltuples) || reltuples < 0 || !is.finite(null_frac) ||
        null_frac < 0 || null_frac > 1 || !is.finite(nd) ||
        !is.finite(ancho) || ancho < 0) {
      return(list(ok = FALSE, motivo = paste(
        "`reltuples`, `null_frac`, `n_distinct` o `avg_width` no es utilizable."
      )))
    }
    n_validos[[i]] <- reltuples * (1 - null_frac)
    n_distintos[[i]] <- if (nd < 0) ceiling(abs(nd) * reltuples) else ceiling(nd)
    anchos[[i]] <- ancho
    if ("tipo" %in% names(filas)) tipos[[i]] <- as.character(filas$tipo[[i]])
  }
  validos <- sum(n_validos)
  distintos <- sum(n_distintos)
  ancho <- if (validos > 0) sum(n_validos * anchos) / validos else mean(anchos)
  if (!is.finite(validos) || !is.finite(distintos) || !is.finite(ancho)) {
    return(list(ok = FALSE, motivo = "La suma de las estad\u00edsticas no es utilizable."))
  }
  tipo <- tipos[!is.na(tipos) & nzchar(tipos)]
  list(
    ok = TRUE, n_validos = validos, n_distintos = distintos,
    avg_width = ancho, n_relaciones = nrow(filas),
    tipo = if (length(tipo)) tipo[[1L]] else NA_character_
  )
}

.estimar_derrame_familia_postgresql_dbi <- function(
    conexion, tabla, columnas, presupuesto, familia,
    universo = "tabla_completa", tamano_lote = .TAMANO_LOTE_PLANOS_DBI,
    forma = NA_character_, dialecto = NULL, moda_guardian = NULL,
    tipos = NULL, prototipo = NULL, tabla_sql = NULL) {
  vacia <- function(estado = "no_disponible", motivo = paste(
      "No se pudo estimar el derrame de", familia, ".")) {
    .estimacion_derrame_familia_vacia_dbi(
      familia, motivo, estado = estado, forma = forma
    )
  }
  if (identical(universo, "muestra_motor")) {
    return(vacia(motivo = paste(
      "No se pudo estimar el derrame de", familia,
      "sobre `muestra_motor` con estad\u00edsticas de la tabla completa; no se",
      "inventa una equivalencia."
    )))
  }
  if (!length(columnas)) {
    return(vacia("no_solicitado", paste(
      "No se solicit\u00f3 una estimaci\u00f3n de derrame porque no hay columnas que",
      "vayan a emitir", familia, "."
    )))
  }
  if (!grepl(.regex_sin_caja("postgres|pqconnection"),
             .senas_conexion_dbi(conexion), perl = TRUE)) {
    return(vacia(motivo = paste(
      "No se pudo estimar el derrame de", familia, ": la conexi\u00f3n no fue",
      "reconocida como PostgreSQL y no hay un `pg_stats` portable."
    )))
  }
  memoria <- .leer_memoria_postgresql_dbi(conexion, presupuesto)
  if (!isTRUE(memoria$ok)) return(.estimacion_derrame_familia_vacia_dbi(
    familia, memoria$motivo, memoria = memoria, forma = forma
  ))
  if (!is.null(presupuesto)) presupuesto$memoria_derrame <- memoria
  estadisticas <- .estadisticas_hash_postgresql_dbi(
    conexion, tabla, columnas, presupuesto
  )
  if (!isTRUE(estadisticas$ok)) return(.estimacion_derrame_familia_vacia_dbi(
    familia, estadisticas$motivo, memoria = memoria, forma = forma
  ))
  datos <- estadisticas$datos
  filas_catalogo <- estadisticas$filas_catalogo
  columnas_estimadas <- list()
  columnas_no_estimadas <- list()
  for (i in seq_along(columnas)) {
    columna <- columnas[[i]]
    estadistica <- .estadisticas_familia_derrame_dbi(datos, columna)
    if (!isTRUE(estadistica$ok)) {
      columnas_no_estimadas[[length(columnas_no_estimadas) + 1L]] <- data.frame(
        columna = columna, motivo = estadistica$motivo,
        stringsAsFactors = FALSE
      )
      next
    }
    tipo_declarado <- .atributo_columna_dbi(tipos, columna, i) %||%
      NA_character_
    prototipo_columna <- .atributo_columna_dbi(prototipo, columna, i)
    tipo <- .familia_tipo_derrame_dbi(
      if (is.na(estadistica$tipo)) tipo_declarado else estadistica$tipo,
      prototipo_columna
    )
    nvalid <- estadistica$n_validos
    nd <- estadistica$n_distintos
    ancho <- estadistica$avg_width
    metodo <- if (identical(familia, "moda")) {
      if (is.null(dialecto)) dialecto <- .dialectos_dbi()$limit
      consulta <- .sql_moda_columna_dbi(
        conexion, if (is.null(tabla_sql)) .texto_tabla_dbi(tabla) else tabla_sql,
        .citar_identificador_dbi(conexion, columna), dialecto,
        moda_guardian
      )
      plan <- .plan_moda_derrame_dbi(conexion, consulta$sql, presupuesto)
      if (!isTRUE(plan$ok)) {
        columnas_no_estimadas[[length(columnas_no_estimadas) + 1L]] <- data.frame(
          columna = columna, motivo = plan$motivo, stringsAsFactors = FALSE
        )
        next
      }
      plan$metodo
    } else {
      "sort"
    }
    hash <- if (identical(metodo, "hash")) {
      nd * (ancho + .TAMANO_BASE_ENTRADA_HASH_POSTGRESQL_DBI)
    } else NA_real_
    tape <- nvalid * (ancho + 8)
    piso <- if (identical(tipo, "numeric")) {
      .PISO_SORT_NUMERIC_POSTGRESQL_DBI
    } else .PISO_SORT_FIJOS_POSTGRESQL_DBI
    memoria_sort <- max(
      nvalid * (ancho + .TAMANO_BASE_SORT_POSTGRESQL_DBI), nvalid * piso
    )
    decision <- if (identical(metodo, "hash")) hash else memoria_sort
    limite <- if (identical(metodo, "hash")) {
      memoria$memoria_efectiva_bytes
    } else memoria$work_mem_bytes
    columnas_estimadas[[length(columnas_estimadas) + 1L]] <- data.frame(
      columna = columna, metodo = metodo, forma = forma,
      tipo_familia = tipo, n_distintos_estimados = nd,
      n_validos_catalogo = nvalid, n_validos_medido = NA_real_,
      avg_width = ancho,
      estado_hash_bytes = hash,
      estado_sort_bytes = if (identical(metodo, "sort")) tape else NA_real_,
      estado_memoria_bytes = if (identical(metodo, "sort")) memoria_sort else NA_real_,
      estado_io_total_bytes = NA_real_, tamano_estimado_bytes = decision,
      supera_memoria = if (is.finite(limite)) decision > limite else NA,
      stringsAsFactors = FALSE
    )
  }
  columnas_df <- if (length(columnas_estimadas)) do.call(rbind, columnas_estimadas)
    else .estimacion_derrame_familia_vacia_dbi(familia)$columnas
  no_estimadas_df <- if (length(columnas_no_estimadas)) {
    do.call(rbind, columnas_no_estimadas)
  } else .estimacion_derrame_familia_vacia_dbi(familia)$columnas_no_estimadas
  if (identical(familia, "moda") || !identical(forma, "consolidada")) {
    grupos <- lapply(seq_len(nrow(columnas_df)), function(i) i)
  } else {
    grupos <- split(seq_len(nrow(columnas_df)), ceiling(
      seq_len(nrow(columnas_df)) / max(1L, as.integer(tamano_lote))
    ))
  }
  lotes <- if (length(grupos)) do.call(rbind, lapply(seq_along(grupos), function(i) {
    filas <- columnas_df[grupos[[i]], , drop = FALSE]
    metodo <- unique(filas$metodo)
    metodo <- if (length(metodo) == 1L) metodo else "por_columna"
    decision <- if (all(is.na(filas$estado_memoria_bytes))) {
      max(filas$estado_hash_bytes, na.rm = TRUE)
    } else max(filas$estado_memoria_bytes, na.rm = TRUE)
    limite <- if (identical(metodo, "hash")) memoria$memoria_efectiva_bytes
      else memoria$work_mem_bytes
    data.frame(
      lote = as.integer(i), columnas = paste(filas$columna, collapse = ", "),
      metodo = metodo, forma = forma,
      estado_hash_bytes = if (all(is.na(filas$estado_hash_bytes))) NA_real_
        else max(filas$estado_hash_bytes, na.rm = TRUE),
      estado_sort_bytes = if (all(is.na(filas$estado_sort_bytes))) NA_real_
        else max(filas$estado_sort_bytes, na.rm = TRUE),
      estado_memoria_bytes = if (all(is.na(filas$estado_memoria_bytes))) NA_real_
        else max(filas$estado_memoria_bytes, na.rm = TRUE),
      estado_io_total_bytes = if (identical(familia, "mediana") &&
                                  identical(forma, "consolidada") &&
                                  !all(is.na(filas$estado_sort_bytes))) {
        sum(filas$estado_sort_bytes, na.rm = TRUE)
      } else NA_real_,
      tamano_estimado_bytes = decision,
      supera_memoria = if (is.finite(limite)) decision > limite else NA,
      stringsAsFactors = FALSE
    )
  })) else .estimacion_derrame_familia_vacia_dbi(familia)$lotes
  if (is.data.frame(lotes) && nrow(lotes) && length(grupos)) {
    columnas_internas <- lapply(
      grupos, function(indices) as.character(columnas_df$columna[indices])
    )
    if (any(vapply(columnas_internas, function(x) {
      length(x) > 1L && any(grepl(",", x, fixed = TRUE, useBytes = TRUE))
    }, logical(1L)))) {
      attr(lotes, "columnas_internas") <- columnas_internas
    }
  }
  if (identical(familia, "mediana") && identical(forma, "consolidada") &&
      nrow(lotes)) {
    for (i in seq_along(grupos)) {
      columnas_df$estado_io_total_bytes[grupos[[i]]] <-
        lotes$estado_io_total_bytes[[i]]
    }
  }
  sobre <- which(!is.na(lotes$supera_memoria) & lotes$supera_memoria)
  n_estimadas <- nrow(columnas_df)
  estado <- if (!n_estimadas) "no_disponible" else if (
    n_estimadas < length(columnas)
  ) "parcial" else "estimado"
  motivo <- if (identical(familia, "moda")) paste(
    "El m\u00e9todo de la moda sale del nodo Aggregate de la consulta exacta",
    "mediante `EXPLAIN (FORMAT JSON, COSTS OFF)` sin ANALYZE. El estado hash",
    "usa `n_distinct * (avg_width + 64)`; el estado sort usa la huella de",
    "decisi\u00f3n y el tape declarados por familia. Las estad\u00edsticas pueden estar",
    "viejas: un margen no demuestra que no haya derrame."
  ) else paste(
    "La mediana se estima como un sort de los valores no nulos. La huella de",
    "decisi\u00f3n usa `n_validos * (avg_width + 24)` con piso por familia y el",
    "tape `n_validos * (avg_width + 8)` es informativo; el tape nunca decide.",
    "El l\u00edmite de la mediana es `work_mem`, sin multiplicador."
  )
  if (length(no_estimadas_df)) motivo <- paste(
    motivo, paste(no_estimadas_df$columna, no_estimadas_df$motivo,
                  sep = ": ", collapse = " ")
  )
  fuente <- if (identical(familia, "moda")) paste(
    "EXPLAIN (FORMAT JSON, COSTS OFF) de la consulta exacta + pg_stats.n_distinct",
    "+ pg_stats.avg_width + pg_class.reltuples + SHOW work_mem"
  ) else paste(
    "pg_stats.null_frac + pg_stats.avg_width + pg_class.reltuples + SHOW work_mem"
  )
  if (identical(familia, "moda") && isTRUE(memoria$hash_mem_multiplier_disponible)) {
    fuente <- paste0(fuente, " + SHOW hash_mem_multiplier")
  }
  metodo <- unique(columnas_df$metodo)
  metodo <- if (length(metodo) == 1L) metodo[[1L]] else if (length(metodo)) {
    "por_columna"
  } else NA_character_
  limite_general <- if (identical(familia, "mediana") ||
                        identical(metodo, "sort")) {
    memoria$work_mem_bytes
  } else if (identical(metodo, "hash")) {
    memoria$memoria_efectiva_bytes
  } else NA_real_
  memoria_general <- if (is.finite(limite_general)) {
    .memoria_dbi(limite_general)
  } else NA_character_
  list(
    estado = estado, disponible = n_estimadas > 0L, es_estimacion = TRUE,
    familia = familia, metodo = metodo, forma = forma, fuente = fuente,
    motivo = motivo, work_mem = memoria$work_mem,
    work_mem_bytes = memoria$work_mem_bytes,
    hash_mem_multiplier = memoria$hash_mem_multiplier,
    hash_mem_multiplier_disponible = memoria$hash_mem_multiplier_disponible,
    memoria_efectiva_bytes = limite_general,
    memoria_efectiva = memoria_general,
    columnas = columnas_df, columnas_no_estimadas = no_estimadas_df,
    lotes = lotes, lotes_sobre_memoria = as.integer(sobre),
    n_columnas_solicitadas = as.integer(length(columnas)),
    n_columnas_estimadas = as.integer(n_estimadas), filas_catalogo = filas_catalogo,
    supera_memoria = if (length(sobre)) TRUE else if (nrow(lotes) &&
      all(!is.na(lotes$supera_memoria))) FALSE else NA
  )
}

.actualizar_n_validos_estimacion_dbi <- function(estimacion, agregados,
                                                  metricas, salida) {
  if (is.null(estimacion) || !is.data.frame(estimacion$columnas) ||
      !nrow(estimacion$columnas)) return(estimacion)
  pidio <- "validos" %in% metricas
  valores <- vapply(estimacion$columnas$columna, function(columna) {
    resultado <- if (isTRUE(pidio) && !is.null(agregados$conteos[[columna]])) {
      agregados$conteos[[columna]]$validos
    } else NULL
    if (is.list(resultado) && isTRUE(resultado$ok)) {
      .numero_dbi(resultado$valor)
    } else NA_real_
  }, numeric(1L))
  estimacion$columnas$n_validos_medido <- valores
  tiene_medido <- isTRUE(pidio) && any(is.finite(valores))
  estimacion$fuente_denominador <- if (tiene_medido) {
    "n_validos medido"
  } else {
    "estimaci\u00f3n de cat\u00e1logo"
  }
  if (tiene_medido) {
    for (i in seq_len(nrow(estimacion$columnas))) {
      medido <- valores[[i]]
      if (!is.finite(medido)) next
      tipo <- estimacion$columnas$tipo_familia[[i]]
      ancho <- estimacion$columnas$avg_width[[i]]
      piso <- if (identical(tipo, "numeric")) .PISO_SORT_NUMERIC_POSTGRESQL_DBI
        else .PISO_SORT_FIJOS_POSTGRESQL_DBI
      memoria_sort <- max(
        medido * (ancho + .TAMANO_BASE_SORT_POSTGRESQL_DBI), medido * piso
      )
      if (identical(estimacion$columnas$metodo[[i]], "hash")) {
        decision <- estimacion$columnas$estado_hash_bytes[[i]]
        limite <- estimacion$hash_mem_multiplier * estimacion$work_mem_bytes
      } else {
        decision <- memoria_sort
        limite <- estimacion$work_mem_bytes
        estimacion$columnas$estado_memoria_bytes[[i]] <- memoria_sort
        estimacion$columnas$estado_sort_bytes[[i]] <- medido * (ancho + 8)
      }
      estimacion$columnas$tamano_estimado_bytes[[i]] <- decision
      estimacion$columnas$supera_memoria[[i]] <- is.finite(limite) && decision > limite
    }
    if (identical(salida, "meta")) {
      estimacion$fuente <- paste(
        estimacion$fuente,
        "n_validos medido por los agregados planos de esta corrida cuando la",
        "familia `validos` fue solicitada; avg_width y el resto vienen del cat\u00e1logo."
      )
      estimacion$motivo <- paste(
        estimacion$motivo, "Para esta salida se us\u00f3 `n_validos` medido cuando",
        "estuvo disponible; las columnas sin medici\u00f3n conservan el cat\u00e1logo."
      )
    }
  } else if (identical(salida, "meta")) {
    estimacion$motivo <- paste(
      estimacion$motivo, "No se midi\u00f3 `n_validos` para esta salida porque",
      "la familia `validos` no fue solicitada o su consulta no fue utilizable;",
      "se conserva el `n_validos_catalogo` del plan."
    )
  }
  if (is.data.frame(estimacion$lotes) && nrow(estimacion$lotes)) {
    columnas_internas <- attr(
      estimacion$lotes, "columnas_internas", exact = TRUE
    )
    for (i in seq_len(nrow(estimacion$lotes))) {
      columnas <- if (is.list(columnas_internas) &&
                      length(columnas_internas) >= i) {
        as.character(columnas_internas[[i]])
      } else {
        .separar_nombres_columnas(
          estimacion$lotes$columnas[[i]],
          estimacion$columnas$columna, sep = ", "
        )
      }
      filas <- estimacion$columnas[
        .nombres_para_operar(estimacion$columnas$columna) %in%
          .nombres_para_operar(columnas), , drop = FALSE
      ]
      decision <- if (all(is.na(filas$estado_memoria_bytes))) {
        max(filas$estado_hash_bytes, na.rm = TRUE)
      } else max(filas$estado_memoria_bytes, na.rm = TRUE)
      estimacion$lotes$tamano_estimado_bytes[[i]] <- decision
      estimacion$lotes$estado_memoria_bytes[[i]] <- if (all(
        is.na(filas$estado_memoria_bytes)
      )) NA_real_ else max(filas$estado_memoria_bytes, na.rm = TRUE)
      estimacion$lotes$estado_sort_bytes[[i]] <- if (all(
        is.na(filas$estado_sort_bytes)
      )) NA_real_ else max(filas$estado_sort_bytes, na.rm = TRUE)
      estimacion$lotes$estado_io_total_bytes[[i]] <- if (
        identical(estimacion$familia, "mediana") &&
        identical(estimacion$forma, "consolidada") &&
        !all(is.na(filas$estado_sort_bytes))
      ) sum(filas$estado_sort_bytes, na.rm = TRUE) else NA_real_
      limite <- if (identical(estimacion$metodo, "hash")) {
        estimacion$work_mem_bytes * estimacion$hash_mem_multiplier
      } else estimacion$work_mem_bytes
      estimacion$lotes$supera_memoria[[i]] <- is.finite(limite) && decision > limite
    }
    estimacion$lotes_sobre_memoria <- which(estimacion$lotes$supera_memoria %in% TRUE)
    estimacion$supera_memoria <- if (length(estimacion$lotes_sobre_memoria)) TRUE
      else if (all(!is.na(estimacion$lotes$supera_memoria))) FALSE else NA
  }
  estimacion
}

.filtrar_estimacion_derrame_dbi <- function(estimacion, columnas) {
  if (is.null(estimacion) || !is.data.frame(estimacion$columnas) ||
      !nrow(estimacion$columnas)) return(estimacion)
  indices <- .indice_nombre(as.character(columnas), estimacion$columnas$columna)
  columnas <- estimacion$columnas$columna[unique(indices[!is.na(indices)])]
  estimacion$columnas <- estimacion$columnas[
    .indice_nombre(columnas, estimacion$columnas$columna), , drop = FALSE
  ]
  if (!is.data.frame(estimacion$lotes) || !nrow(estimacion$lotes)) {
    estimacion$lotes_sobre_memoria <- integer()
    estimacion$supera_memoria <- NA
    return(estimacion)
  }
  lotes <- lapply(seq_len(nrow(estimacion$lotes)), function(i) {
    nombres <- trimws(strsplit(
      estimacion$lotes$columnas[[i]], ",", fixed = TRUE
    )[[1L]])
    indices_nombres <- .indice_nombre(nombres, columnas)
    nombres <- columnas[unique(indices_nombres[!is.na(indices_nombres)])]
    if (!length(nombres)) return(NULL)
    filas <- estimacion$columnas[
      !is.na(.indice_nombre(estimacion$columnas$columna, nombres)), , drop = FALSE
    ]
    metodo <- unique(filas$metodo)
    metodo <- if (length(metodo) == 1L) metodo[[1L]] else "por_columna"
    es_sort <- !all(is.na(filas$estado_memoria_bytes))
    decision <- if (es_sort) max(filas$estado_memoria_bytes, na.rm = TRUE) else
      max(filas$estado_hash_bytes, na.rm = TRUE)
    limite <- if (identical(metodo, "hash")) {
      estimacion$memoria_efectiva_bytes
    } else estimacion$work_mem_bytes
    data.frame(
      lote = estimacion$lotes$lote[[i]],
      columnas = paste(nombres, collapse = ", "), metodo = metodo,
      forma = estimacion$lotes$forma[[i]],
      estado_hash_bytes = if (all(is.na(filas$estado_hash_bytes))) NA_real_
        else max(filas$estado_hash_bytes, na.rm = TRUE),
      estado_sort_bytes = if (all(is.na(filas$estado_sort_bytes))) NA_real_
        else max(filas$estado_sort_bytes, na.rm = TRUE),
      estado_memoria_bytes = if (all(is.na(filas$estado_memoria_bytes))) NA_real_
        else max(filas$estado_memoria_bytes, na.rm = TRUE),
      estado_io_total_bytes = if (
        identical(estimacion$familia, "mediana") &&
        identical(estimacion$forma, "consolidada") &&
        !all(is.na(filas$estado_sort_bytes))
      ) sum(filas$estado_sort_bytes, na.rm = TRUE) else NA_real_,
      tamano_estimado_bytes = decision,
      supera_memoria = if (is.finite(limite)) decision > limite else NA,
      stringsAsFactors = FALSE
    )
  })
  lotes <- Filter(Negate(is.null), lotes)
  estimacion$lotes <- if (length(lotes)) do.call(rbind, lotes) else {
    estimacion$lotes[0L, , drop = FALSE]
  }
  estimacion$lotes_sobre_memoria <- which(
    estimacion$lotes$supera_memoria %in% TRUE
  )
  estimacion$supera_memoria <- if (length(estimacion$lotes_sobre_memoria)) TRUE
    else if (nrow(estimacion$lotes) &&
             all(!is.na(estimacion$lotes$supera_memoria))) FALSE else NA
  estimacion$n_columnas_solicitadas <- as.integer(length(columnas))
  estimacion$n_columnas_estimadas <- as.integer(nrow(estimacion$columnas))
  estimacion
}

# ---- Reloj e instrumentacion --------------------------------------------

# `Sys.time()` puede devolver el mismo instante para dos lecturas. En ese caso
# una duracion cero seria una precision inventada, no una consulta instantanea:
# se publica `NA` y la metadata declara que el reloj no pudo resolver el
# intervalo.
.ahora_dbi <- function() {
  tryCatch(Sys.time(), error = function(e) NULL)
}

.duracion_ms_dbi <- function(inicio, fin) {
  if (is.null(inicio) || is.null(fin)) return(NA_real_)
  segundos <- tryCatch(
    as.numeric(difftime(fin, inicio, units = "secs")),
    error = function(e) NA_real_
  )
  if (!length(segundos) || is.na(segundos) || !is.finite(segundos) ||
      segundos <= 0) {
    return(NA_real_)
  }
  segundos * 1000
}

# `proc.time()` separa el tiempo que el proceso trabajo del que paso esperando
# al motor, a la red o a un bloqueo. Se guardan solo `user.self` y `sys.self`:
# el tiempo de los procesos hijos no pertenece al cliente que esta perfilando.
# A diferencia del reloj transcurrido, cero es una medicion valida aca: una
# consulta puede terminar sin consumir una centesima de CPU. Lo que no se pudo
# leer queda en `NA`, nunca se reemplaza por cero.
.ahora_cpu_dbi <- function() {
  tryCatch({
    tiempo <- proc.time()
    campos <- c("user.self", "sys.self")
    if (!all(campos %in% names(tiempo))) return(NULL)
    valor <- sum(as.numeric(tiempo[campos]))
    if (!length(valor) || is.na(valor) || !is.finite(valor)) NULL else valor
  }, error = function(e) NULL)
}

.duracion_cpu_ms_dbi <- function(inicio, fin) {
  if (is.null(inicio) || is.null(fin) || length(inicio) != 1L ||
      length(fin) != 1L) {
    return(NA_real_)
  }
  diferencia <- suppressWarnings(as.numeric(fin) - as.numeric(inicio))
  if (!length(diferencia) || is.na(diferencia) || !is.finite(diferencia) ||
      diferencia < 0) {
    return(NA_real_)
  }
  diferencia * 1000
}

.medicion_consulta_vacia_dbi <- function(etapa = NA_character_) {
  list(
    consulta_id = NA_integer_, etapa = as.character(etapa),
    duracion_ms = NA_real_, n_filas_resultado = NA_real_,
    bytes_resultado_r = NA_real_, cpu_ms = NA_real_, instrumentar = FALSE
  )
}

.iniciar_consulta_dbi <- function(presupuesto, etapa) {
  if (is.null(presupuesto)) return(.medicion_consulta_vacia_dbi(etapa))
  presupuesto$siguiente_consulta <- presupuesto$siguiente_consulta + 1L
  list(
    consulta_id = as.integer(presupuesto$siguiente_consulta),
    etapa = as.character(etapa),
    instrumentar = isTRUE(presupuesto$instrumentar),
    inicio = if (isTRUE(presupuesto$instrumentar)) .ahora_dbi() else NULL,
    inicio_cpu = if (isTRUE(presupuesto$instrumentar)) .ahora_cpu_dbi() else NULL
  )
}

.terminar_consulta_dbi <- function(medicion, datos = NULL) {
  resultado <- .medicion_consulta_vacia_dbi(medicion$etapa)
  resultado$consulta_id <- medicion$consulta_id
  if (isTRUE(medicion$instrumentar)) {
    resultado$duracion_ms <- .duracion_ms_dbi(medicion$inicio, .ahora_dbi())
    resultado$cpu_ms <- .duracion_cpu_ms_dbi(
      medicion$inicio_cpu, .ahora_cpu_dbi()
    )
    if (is.null(datos)) {
      resultado$n_filas_resultado <- NA_real_
      resultado$bytes_resultado_r <- NA_real_
    } else {
      resultado$n_filas_resultado <- tryCatch(
        as.numeric(nrow(datos)), error = function(e) NA_real_
      )
      resultado$bytes_resultado_r <- tryCatch(
        as.numeric(utils::object.size(datos)), error = function(e) NA_real_
      )
    }
  }
  resultado
}

.adjuntar_medicion_dbi <- function(resultado, medicion) {
  if (is.null(medicion)) return(resultado)
  for (nombre in c(
    "consulta_id", "etapa", "duracion_ms", "n_filas_resultado",
    "bytes_resultado_r", "cpu_ms"
  )) {
    if (!is.null(medicion[[nombre]])) resultado[[nombre]] <- medicion[[nombre]]
  }
  resultado
}

.trazador_tiempos_dbi <- function(activo = TRUE) {
  estado <- new.env(parent = emptyenv())
  estado$activo <- isTRUE(activo)
  estado$etapas <- list()
  # Las etapas se anidan -`perfilado_muestra` envuelve al perfilado por columna,
  # a las dependencias y a los casi-duplicados-, asi que sus duraciones NO se
  # pueden sumar. Eso estaba dicho en la vineta y en el `Rd`, y no en el objeto:
  # quien lo mira en la consola ve siete filas sin nada que lo advierta. El
  # trazador lleva la profundidad para que el objeto lo diga solo, en vez de
  # depender de una tabla de jerarquia escrita a mano que se desactualiza en
  # cuanto alguien agregue una etapa en otro archivo.
  estado$profundidad <- 0L
  estado
}

.registrar_etapa_dbi <- function(trazador, etapa, inicio = NULL, fin = NULL,
                                 estado = NULL, nivel = NULL,
                                 cpu_inicio = NULL, cpu_fin = NULL) {
  if (is.null(trazador)) return(invisible(NULL))
  medido <- isTRUE(trazador$activo)
  if (is.null(estado)) estado <- if (medido) "medido" else "no_medido"
  if (is.null(nivel)) nivel <- trazador$profundidad + 1L
  trazador$etapas[[length(trazador$etapas) + 1L]] <- list(
    etapa = as.character(etapa),
    duracion_ms = if (medido) .duracion_ms_dbi(inicio, fin) else NA_real_,
    cpu_ms = if (medido) .duracion_cpu_ms_dbi(cpu_inicio, cpu_fin) else NA_real_,
    estado = as.character(estado),
    nivel = as.integer(nivel)
  )
  invisible(NULL)
}

.medir_etapa_dbi <- function(trazador, etapa, expresion, activa = TRUE) {
  if (is.null(trazador)) return(force(expresion))
  if (!isTRUE(activa)) {
    .registrar_etapa_dbi(trazador, etapa, estado = "no_solicitado")
    return(force(expresion))
  }
  inicio <- if (isTRUE(trazador$activo)) .ahora_dbi() else NULL
  cpu_inicio <- if (isTRUE(trazador$activo)) .ahora_cpu_dbi() else NULL
  nivel <- trazador$profundidad + 1L
  trazador$profundidad <- nivel
  # El descuento va por `on.exit` para que un error dentro de la etapa no deje
  # la profundidad corrida y todo lo que venga despues mal clasificado.
  on.exit(trazador$profundidad <- nivel - 1L, add = TRUE)
  valor <- tryCatch(
    list(ok = TRUE, valor = force(expresion)),
    error = function(e) list(ok = FALSE, error = e)
  )
  .registrar_etapa_dbi(
    trazador, etapa, inicio, .ahora_dbi(), nivel = nivel,
    cpu_inicio = cpu_inicio, cpu_fin = .ahora_cpu_dbi()
  )
  if (!isTRUE(valor$ok)) .detener(valor$error)
  valor$valor
}

.resumen_tiempos_dbi <- function(trazador) {
  vacio <- data.frame(
    etapa = character(), duracion_ms = numeric(), cpu_ms = numeric(),
    estado = character(),
    nivel = integer(), n_ejecuciones = integer(), stringsAsFactors = FALSE
  )
  if (is.null(trazador) || !length(trazador$etapas)) return(vacio)
  datos <- do.call(rbind, lapply(trazador$etapas, function(x) {
    data.frame(
      etapa = x$etapa, duracion_ms = x$duracion_ms, estado = x$estado,
      cpu_ms = if (is.null(x$cpu_ms)) NA_real_ else x$cpu_ms,
      nivel = if (is.null(x$nivel)) 1L else x$nivel,
      n_ejecuciones = 1L, stringsAsFactors = FALSE
    )
  }))
  grupos <- .dividir_por_bytes(seq_len(nrow(datos)), datos$etapa)
  salida <- do.call(rbind, lapply(names(grupos), function(etapa) {
    filas <- datos[grupos[[etapa]], , drop = FALSE]
    duraciones <- filas$duracion_ms
    cpu <- filas$cpu_ms
    data.frame(
      etapa = etapa,
      duracion_ms = if (all(!is.na(duraciones))) sum(duraciones) else NA_real_,
      cpu_ms = if (all(!is.na(cpu))) sum(cpu) else NA_real_,
      estado = if (any(filas$estado == "no_solicitado")) {
        "no_solicitado"
      } else if (any(filas$estado == "no_medido")) {
        "no_medido"
      } else {
        "medido"
      },
      # Solo las de nivel 1 se pueden sumar entre si; las demas estan
      # contenidas en alguna de ellas.
      nivel = min(filas$nivel),
      n_ejecuciones = nrow(filas), stringsAsFactors = FALSE
    )
  }))
  rownames(salida) <- NULL
  salida
}

# Perfilar la tabla entera -lo que viene por omision- puede tardar minutos sobre
# una tabla grande, y una corrida callada no se distingue de una colgada. La
# barra avanza contra las consultas que el plan dice que se van a emitir, que es
# un total conocido y no una estimacion.
#
# No se abre sola en pruebas ni en guiones: `interactive()` decide, y
# `options(lupa.progreso = )` manda sobre eso en los dos sentidos. Una barra que
# aparece en la salida de un guion es ruido que despues hay que filtrar.
.abrir_progreso_dbi <- function(presupuesto, previstas, envir) {
  if (is.null(presupuesto)) return(invisible(NULL))
  # Debajo de una docena de consultas la corrida termina antes de que la barra
  # sirva para algo.
  if (!.progreso_activo(previstas, 12)) return(invisible(NULL))
  presupuesto$previstas <- previstas
  presupuesto$barra <- cli::cli_progress_bar(
    "Perfilando", total = previstas, .envir = envir, clear = TRUE
  )
  invisible(presupuesto$barra)
}

.saldo_dbi <- function(presupuesto) {
  presupuesto$max - presupuesto$usadas - presupuesto$reserva
}

.gastar_dbi <- function(presupuesto) {
  if (is.null(presupuesto)) return(TRUE)
  if (.saldo_dbi(presupuesto) < 1) {
    presupuesto$agotado <- TRUE
    return(FALSE)
  }
  presupuesto$usadas <- presupuesto$usadas + 1
  if (!is.null(presupuesto$barra)) {
    # `set` y no `inc`: la cuenta que manda es la del presupuesto, que ya
    # incluye las consultas-porton emitidas antes de abrir la barra.
    try(
      cli::cli_progress_update(
        id = presupuesto$barra,
        set = min(presupuesto$usadas, presupuesto$previstas)
      ),
      silent = TRUE
    )
  }
  TRUE
}

# Las llamadas de metadatos -`dbExistsTable()`, `dbListFields()`- tambien
# viajan a la base. Se cuentan aunque no se puedan rechazar: el numero que se
# informa tiene que ser el numero real de viajes.
.contar_dbi <- function(presupuesto, n = 1) {
  if (is.null(presupuesto)) return(invisible(NULL))
  presupuesto$usadas <- presupuesto$usadas + n
  invisible(NULL)
}

.motivo_presupuesto_dbi <- function(presupuesto) {
  paste0(
    "Se agot\u00f3 el presupuesto declarado en `max_consultas` (",
    format(presupuesto$max, scientific = FALSE),
    if (presupuesto$max == 1L) " consulta)." else " consultas)."
  )
}

# Estas etapas comprueban capacidades, catalogos, configuracion o metadatos
# auxiliares. No forman parte de una metrica que la llamada haya solicitado.
# Las consultas de capacidades que empiecen con `sonda_` se incluyen tambien
# por prefijo en `.consulta_publica_dbi()` para que una capacidad nueva no se
# registre por accidente como una falla solicitada.
.ETAPAS_INTERNAS_DBI <- c(
  "consulta", "clave_primaria", "proteccion_coleccion", "sonda_collation_dbi",
  "sonda_fuente_bloques", "sonda_desvio", "estimacion_derrame",
  "explain_moda", "sonda_muestreo", "sonda_mediana_escalar",
  "sonda_mediana_cte_ventana", "sonda_mediana_cte_ventana_control_negativo",
  "sonda_moda_guardian", "sonda_mediana_consolidada", "sonda_aproximacion",
  "sonda_dialecto", "cardinalidad_catalogo", "tipos_guardados",
  "sonda_infinitos", "sonda_magnitud", "esquema", "sonda_lectura_muestra",
  "sonda_bytes_muestra", "proteccion_fuera_de_muestra", "porton_tabla",
  "catalogo_bytes_muestra"
)

.consulta_publica_dbi <- function(etapa) {
  if (length(etapa) != 1L || is.na(etapa)) return(FALSE)
  texto <- as.character(etapa)
  if (texto %in% .ETAPAS_INTERNAS_DBI || startsWith(texto, "sonda_")) {
    return(FALSE)
  }
  !grepl("^(porton_|catalogo_|esquema_|clave_|metadatos_|proteccion_)", texto,
         perl = TRUE)
}

.sqlstate_dbi <- function(error) {
  campos <- c("sqlstate", "SQLSTATE", "sqlState", "state")
  for (campo in campos) {
    valor <- tryCatch(error[[campo]], error = function(e) NULL)
    if (!is.null(valor) && length(valor) && !is.na(valor[[1L]])) {
      return(as.character(valor[[1L]]))
    }
  }
  texto <- tryCatch(conditionMessage(error), error = function(e) "")
  captura <- regmatches(
    texto, regexpr("(^|[^0-9])57014([^0-9]|$)", texto, perl = TRUE)
  )
  if (length(captura) && nzchar(captura[[1L]])) "57014" else NA_character_
}

.clasificar_falla_consulta_dbi <- function(sqlstate = NA_character_,
                                           motivo = NA_character_) {
  estado <- .minusculas_ascii(paste(c(sqlstate, motivo), collapse = " "))
  if (grepl("(^|[^0-9])57014([^0-9]|$)|cancel|timeout|timed out",
            estado, perl = TRUE)) {
    "cancelada"
  } else {
    "rechazada"
  }
}

.guardar_falla_consulta_dbi <- function(falla, presupuesto) {
  nombre <- if (.consulta_publica_dbi(falla$etapa)) {
    "fallas_consultas"
  } else {
    "fallas_sondas"
  }
  presupuesto[[nombre]][[length(presupuesto[[nombre]]) + 1L]] <- falla
  invisible(NULL)
}

.registrar_falla_consulta_dbi <- function(resultado, presupuesto) {
  if (is.null(presupuesto) || isTRUE(resultado$ok)) {
    return(invisible(NULL))
  }
  motivo <- resultado$motivo %||% NA_character_
  sqlstate <- resultado$sqlstate %||% NA_character_
  clase <- if (length(motivo) == 1L && !is.na(motivo) &&
               identical(as.character(motivo), .motivo_presupuesto_dbi(presupuesto))) {
    "presupuesto_agotado"
  } else {
    .clasificar_falla_consulta_dbi(sqlstate, motivo)
  }
  falla <- list(
    etapa = as.character(resultado$etapa),
    consulta_id = suppressWarnings(as.integer(resultado$consulta_id)),
    motivo = as.character(motivo), sqlstate = as.character(sqlstate),
    tipo = clase
  )
  if (isTRUE(presupuesto$posponer_fallas_lotes) &&
      as.character(resultado$etapa) %in% c("basicos", "desvio", "conteos")) {
    presupuesto$fallas_lotes[[length(presupuesto$fallas_lotes) + 1L]] <- falla
  } else {
    .guardar_falla_consulta_dbi(falla, presupuesto)
  }
  invisible(NULL)
}

.publicar_fallas_dbi <- function(fallas) {
  vacia <- data.frame(
    etapa = character(), consulta_id = integer(), motivo = character(),
    sqlstate = character(), tipo = character(), stringsAsFactors = FALSE
  )
  if (is.null(fallas) || !length(fallas)) return(vacia)
  salida <- do.call(rbind, lapply(fallas, function(x) {
    data.frame(
      etapa = as.character(x$etapa), consulta_id = as.integer(x$consulta_id),
      motivo = as.character(x$motivo), sqlstate = as.character(x$sqlstate),
      tipo = as.character(x$tipo), stringsAsFactors = FALSE
    )
  }))
  rownames(salida) <- NULL
  salida
}

.avisar_muestra_motor_dbi <- function(mensaje, datos = list(),
                                      conserva_clase_vieja = FALSE) {
  clase <- if (isTRUE(conserva_clase_vieja)) {
    c("lupa_muestra_dbi_no_disponible", "lupa_aviso_muestra_motor")
  } else {
    "lupa_aviso_muestra_motor"
  }
  .avisar_dbi(clase, mensaje, datos = datos)
}

.publicar_fallas_consultas_dbi <- function(presupuesto) {
  if (is.null(presupuesto)) return(.publicar_fallas_dbi(NULL))
  .publicar_fallas_dbi(presupuesto$fallas_consultas)
}

.publicar_fallas_sondas_dbi <- function(presupuesto) {
  if (is.null(presupuesto)) return(.publicar_fallas_dbi(NULL))
  .publicar_fallas_dbi(presupuesto$fallas_sondas)
}

# Una sonda puede fallar por el motor o no haberse emitido por falta de saldo.
# Se conserva esta causa desde la consulta bloqueada para no publicarla luego
# como una incapacidad que el motor nunca informo.
.consulta_bloqueada_por_presupuesto_dbi <- function(resultado, presupuesto) {
  if (isTRUE(resultado$ok) || is.null(presupuesto)) return(FALSE)
  motivo <- resultado$motivo
  length(motivo) == 1L && !is.na(motivo) &&
    identical(as.character(motivo), .motivo_presupuesto_dbi(presupuesto))
}

# ---- Adaptador de dialecto ----------------------------------------------
#
# Acotar filas no es SQL estandar. `LIMIT` no existe en SQL Server ni en
# Oracle anterior a 12c, y `TOP (n)` no existe en ningun otro lado. En vez de
# suponer un dialecto se declara una capacidad -acotar filas- con varias
# implementaciones, se sondea cual acepta el motor con una consulta de cero
# filas, y si ninguna anda queda la via portable: `dbSendQuery()` mas
# `dbFetch(n)`, que no necesita clausula ninguna.
#
# `limitar()` devuelve NULL cuando el dialecto no puede expresar ese recorte;
# quien llama decide entonces si acota en el cliente o si degrada la metrica.

.entero_sql_dbi <- function(n) {
  if (inherits(n, "integer64") && .bit64_disponible_dbi()) {
    return(as.character(n[[1L]]))
  }
  format(round(as.numeric(n)), scientific = FALSE, trim = TRUE)
}

# Un numero con decimales dentro de una sentencia es codigo SQL, y el SQL lleva
# punto. `formatC()` toma la marca de `OutDec` y el `sprintf()` de C la de
# `LC_NUMERIC`: con cualquiera de las dos en coma el porcentaje de `TABLESAMPLE`
# salia `12,5`, el motor respondia "syntax error at or near ','" y
# `perfilar_dbi(universo = "muestra_motor")` se quedaba sin muestra.
# La sonda de capacidad no lo veia: usa el literal `"1"`, sin decimales.
.decimal_sql_dbi <- function(x) {
  .marca_decimal_c(formatC(x, format = "fg", digits = 8, decimal.mark = "."))
}

# La muestra debe conservar los digitos antes de llegar a R. MySQL y MariaDB
# requieren CHAR en CAST; los demas motores cubiertos aceptan VARCHAR. En T-SQL
# `CAST(... AS VARCHAR)` sin largo es `VARCHAR(30)`, y un `decimal(38, s)` con
# mas de 30 cifras no entra: el motor aborta la lectura y la muestra entera
# -todas las columnas- quedaba `no_disponible` (medido en SQL Server 2022 con
# 99999999999999999999999999999999999999). 40 caracteres alcanzan para 38
# cifras, el signo y el punto; se piden 48.
#
# Y `money`/`smallmoney` en T-SQL: `CAST(... AS VARCHAR)` los escribe con dos
# decimales (estilo 0), y guardan cuatro. La muestra leia 0,0001 como "0.00":
# minimo, media y desvio 0 sobre una columna de 0,0001 a 0,0004, publicados como
# observados (medido en SQL Server 2022). `CONVERT(..., 2)` escribe los cuatro.
.cast_entero_ancho_texto_dbi <- function(expr, alias, conexion = NULL,
                                         tipo = NA_character_) {
  senas <- if (is.null(conexion)) "" else .senas_conexion_dbi(conexion)
  sqlserver <- grepl("sql server|microsoft sql|sqlserver|mssql", senas,
                     perl = TRUE, useBytes = TRUE)
  moneda <- length(tipo) == 1L && !is.na(tipo) &&
    .minusculas_ascii(trimws(as.character(tipo))) %in% c("money", "smallmoney")
  if (sqlserver && moneda) {
    return(paste0("CONVERT(VARCHAR(48), ", expr, ", 2) AS ", alias))
  }
  tipo_texto <- if (.es_mysql_dbi(senas)) {
    "CHAR"
  } else if (sqlserver) {
    "VARCHAR(48)"
  } else {
    "VARCHAR"
  }
  paste0("CAST(", expr, " AS ", tipo_texto, ") AS ", alias)
}

.dialectos_dbi <- function() {
  list(
    limit = list(
      nombre = "limit",
      descripcion = "LIMIT n [OFFSET k]",
      motores = "PostgreSQL, SQLite, MySQL/MariaDB, DuckDB y compatibles",
      patron = paste0(
        "sqlite|postgres|redshift|mysql|mariadb|duckdb|clickhouse|monetdb|",
        "vertica|greenplum|presto|trino|spark|hive|snowflake|bigquery|athena"
      ),
      alias_tabla = function(nombre) paste0(" AS ", nombre),
      mediana_escalar = list(resto = "%", division = "/"),
      cast_entero_ancho_texto = .cast_entero_ancho_texto_dbi,
      limitar = function(sql, n, salto = 0) {
        paste0(
          sql, " LIMIT ", .entero_sql_dbi(n),
          if (salto > 0) paste0(" OFFSET ", .entero_sql_dbi(salto)) else ""
        )
      },
      muestreo = c("tablesample_reservoir", "tablesample_system",
                   "tablesample_bernoulli", "tablesample_percent", "random_limit")
    ),
    top = list(
      nombre = "top",
      descripcion = "TOP (n), y OFFSET k ROWS FETCH NEXT n ROWS ONLY con orden",
      motores = "SQL Server 2012 o posterior, Sybase",
      patron = "sql server|microsoft sql|sqlserver|mssql|tsql|sybase",
      alias_tabla = function(nombre) paste0(" AS ", nombre),
      mediana_escalar = NULL,
      cast_entero_ancho_texto = .cast_entero_ancho_texto_dbi,
      limitar = function(sql, n, salto = 0) {
        if (salto > 0) {
          return(paste0(
            sql, " OFFSET ", .entero_sql_dbi(salto), " ROWS FETCH NEXT ",
            .entero_sql_dbi(n), " ROWS ONLY"
          ))
        }
        if (!grepl("^SELECT ", sql)) return(NULL)
        sub("^SELECT ", paste0("SELECT TOP (", .entero_sql_dbi(n), ") "), sql)
      },
      muestreo = c("tablesample_reservoir", "tablesample_system",
                   "tablesample_bernoulli", "tablesample_percent", "random_limit")
    ),
    fetch_first = list(
      nombre = "fetch_first",
      descripcion = "OFFSET k ROWS FETCH FIRST n ROWS ONLY",
      motores = "Oracle 12c o posterior, DB2, Derby, H2",
      patron = "oracle|db2|informix|derby|hsqldb|\\bh2\\b",
      alias_tabla = function(nombre) paste0(" ", nombre),
      mediana_escalar = NULL,
      cast_entero_ancho_texto = .cast_entero_ancho_texto_dbi,
      limitar = function(sql, n, salto = 0) {
        paste0(
          sql,
          if (salto > 0) paste0(" OFFSET ", .entero_sql_dbi(salto), " ROWS") else "",
          " FETCH FIRST ", .entero_sql_dbi(n), " ROWS ONLY"
        )
      },
      muestreo = c("tablesample_reservoir", "tablesample_system",
                   "tablesample_bernoulli", "tablesample_percent", "oracle_sample",
                   "random_limit")
    ),
    rownum = list(
      nombre = "rownum",
      descripcion = "ROWNUM <= n; no expresa salto",
      motores = "Oracle anterior a 12c",
      patron = "oracle",
      alias_tabla = function(nombre) paste0(" ", nombre),
      mediana_escalar = NULL,
      cast_entero_ancho_texto = .cast_entero_ancho_texto_dbi,
      limitar = function(sql, n, salto = 0) {
        if (salto > 0) return(NULL)
        paste0(
          "SELECT * FROM (", sql, ") lupa_recorte WHERE ROWNUM <= ",
          .entero_sql_dbi(n)
        )
      },
      muestreo = c("tablesample_reservoir", "tablesample_system",
                   "tablesample_bernoulli", "tablesample_percent", "oracle_sample",
                   "random_limit")
    ),
    portable = list(
      nombre = "portable",
      descripcion = "sin cl\u00e1usula de l\u00edmite: se acota con dbSendQuery() y dbFetch(n)",
      motores = "cualquier motor con DBI",
      patron = NA_character_,
      alias_tabla = function(nombre) paste0(" AS ", nombre),
      mediana_escalar = NULL,
      cast_entero_ancho_texto = .cast_entero_ancho_texto_dbi,
      limitar = function(sql, n, salto = 0) NULL,
      muestreo = c("tablesample_reservoir", "tablesample_system",
                   "tablesample_bernoulli", "tablesample_percent", "random_limit")
    )
  )
}

.candidatos_muestreo_dbi <- function(conexion, dialecto,
                                     tipo_objeto = NA_character_) {
  nombres <- if (!is.null(dialecto$muestreo)) dialecto$muestreo else character()
  senas <- .senas_conexion_dbi(conexion)
  # En DuckDB un numero sin unidad dentro de `TABLESAMPLE` es una cantidad de
  # filas, y `BERNOULLI` no acepta cantidades: `BERNOULLI (20)` es error de
  # sintaxis en 1.5 y en 2.0, y la forma que acepta es `BERNOULLI (20 PERCENT)`.
  # PostgreSQL, al reves, rechaza `PERCENT`. Medido en las dos versiones.
  bernoulli_con_unidad <- grepl("duckdb", senas, perl = TRUE, useBytes = TRUE)
  todas <- list(
    # Primero la forma de cantidad fija, y la razon salio de medir contra
    # DuckDB: `TABLESAMPLE (p PERCENT)` es a nivel de bloque y devuelve 0 filas
    # o 2.048 sobre una tabla de 5.000, asi que dos consultas del mismo perfil
    # ven muestras de tamano distinto -o una ve cero- y las metricas dejan de
    # ser comparables entre si. Una forma que devuelve exactamente `n` filas no
    # arregla que cada consulta saque su propia muestra, pero al menos respeta
    # el tamano solicitado.
    tablesample_reservoir = list(
      nombre = "tablesample_reservoir",
      descripcion = "TABLESAMPLE RESERVOIR (n ROWS)",
      patron = "duckdb",
      tipo = "tablesample_filas",
      constructor = function(tabla, filas) paste0(
        tabla, " TABLESAMPLE RESERVOIR (", .entero_sql_dbi(filas), " ROWS)"
      )
    ),
    # La fuente por bloques se intenta antes que las formas fila a fila. Se
    # prefiere `SYSTEM` cuando el adaptador la declara porque su costo favorece
    # tablas grandes; su variacion de paginas se publica en la metadata.
    #
    #   TABLESAMPLE SYSTEM (20)      678  904  452  1384
    #   TABLESAMPLE BERNOULLI (20)  1011 1017  981  1050
    #
    # `SYSTEM` elige bloques enteros, asi que sobre una tabla chica el tamano de
    # la muestra salta de un tercio al doble de lo pedido, y puede dar cero.
    # `BERNOULLI` decide fila por fila y se conserva como alternativa declarada;
    # cuesta mas en el motor -recorre la tabla- pero evita el sesgo de paginas.
    tablesample_bernoulli = list(
      nombre = "tablesample_bernoulli",
      descripcion = if (bernoulli_con_unidad) {
        "TABLESAMPLE BERNOULLI (p PERCENT)"
      } else "TABLESAMPLE BERNOULLI (p)",
      patron = "postgres|redshift|duckdb",
      tipo = "tablesample",
      constructor = function(tabla, porcentaje) paste0(
        tabla, " TABLESAMPLE BERNOULLI (", porcentaje,
        if (bernoulli_con_unidad) " PERCENT" else "", ")"
      )
    ),
    tablesample_system = list(
      nombre = "tablesample_system",
      descripcion = "TABLESAMPLE SYSTEM (p)",
      patron = "postgres|redshift|sql server|microsoft sql|sqlserver|mssql",
      tipo = "tablesample",
      constructor = function(tabla, porcentaje) paste0(
        tabla, " TABLESAMPLE SYSTEM (", porcentaje, ")"
      )
    ),
    tablesample_percent = list(
      nombre = "tablesample_percent",
      descripcion = "TABLESAMPLE (p PERCENT)",
      patron = "sql server|microsoft sql|sqlserver|mssql|sybase",
      tipo = "tablesample",
      constructor = function(tabla, porcentaje) paste0(
        tabla, " TABLESAMPLE (", porcentaje, " PERCENT)"
      )
    ),
    oracle_sample = list(
      nombre = "oracle_sample",
      descripcion = "SAMPLE (p)",
      patron = "oracle",
      tipo = "tablesample",
      constructor = function(tabla, porcentaje) paste0(
        tabla, " SAMPLE (", porcentaje, ")"
      )
    ),
    random_limit = list(
      nombre = "random_limit",
      descripcion = "ORDER BY funci\u00f3n pseudoaleatoria con l\u00edmite del dialecto",
      patron = NA_character_,
      tipo = "aleatorio",
      funciones = list(
        list(nombre = "random", patron = "sqlite|postgres|redshift|duckdb|snowflake|bigquery", sql = "RANDOM()"),
        list(nombre = "rand", patron = "mysql|mariadb|clickhouse", sql = "RAND()"),
        list(nombre = "newid", patron = "sql server|microsoft sql|sqlserver|mssql", sql = "NEWID()"),
        list(nombre = "dbms_random", patron = "oracle", sql = "DBMS_RANDOM.VALUE"),
        list(nombre = "random_generic", patron = NA_character_, sql = "RANDOM()")
      )
    )
  )
  controlador_simulado <- inherits(conexion, "SQLiteConnection") &&
    grepl("sql server|microsoft sql|sqlserver|mssql", senas, perl = TRUE)
  orden_funciones <- function(funciones) {
    reconocidas <- vapply(funciones, function(x) {
      !is.na(x$patron) && grepl(x$patron, senas, perl = TRUE)
    }, logical(1L))
    c(which(reconocidas), which(!reconocidas))
  }
  if ("random_limit" %in% nombres) {
    funciones <- todas$random_limit$funciones
    reconocidas <- vapply(funciones, function(x) {
      !is.na(x$patron) && grepl(x$patron, senas, perl = TRUE)
    }, logical(1L))
    if (any(reconocidas) && !controlador_simulado) {
      funciones <- funciones[reconocidas]
    }
    todas$random_limit$funciones <- funciones[orden_funciones(funciones)]
  }
  candidatos <- todas[nombres]
  # Cuando el controlador se reconoce, no se sondean sintaxis de otro motor:
  # en SQL Server un error de compilacion puede abortar la transaccion con
  # `XACT_ABORT ON`, aunque la tabla y los datos sean sanos.
  patrones_conocidos <- vapply(candidatos, function(candidato) {
    !is.na(candidato$patron) && grepl(candidato$patron, senas, perl = TRUE)
  }, logical(1L))
  if (any(patrones_conocidos) && !controlador_simulado) {
    conserva <- vapply(candidatos, function(candidato) {
      is.na(candidato$patron) || grepl(candidato$patron, senas, perl = TRUE)
    }, logical(1L))
    candidatos <- candidatos[conserva]
  }
  # SQL Server acepta `TABLESAMPLE` sobre tablas locales, pero no sobre vistas.
  # El catalogo conoce el objeto antes de armar la sonda; quitar esas formas
  # evita una sentencia que `XACT_ABORT ON` convertiria en perdida de la
  # transaccion del usuario.
  es_sqlserver <- any(grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas, perl = TRUE
  ))
  # Un sinonimo, una tabla externa o una funcion de tabla puede no aparecer en
  # `sys.objects`: en ese caso el catalogo deja `tipo_objeto` vacio y rige el
  # camino anterior para lo que no es una vista. La condicion debe seguir
  # siendo escalar aun cuando el lector de campos no haya podido clasificarlo.
  tipo_objeto <- if (length(tipo_objeto) == 1L) {
    valor <- as.character(tipo_objeto)
    if (is.na(valor)) NA_character_ else
      .minusculas_ascii(trimws(valor))
  } else {
    NA_character_
  }
  if (es_sqlserver && isTRUE(tipo_objeto %in% c("v", "view"))) {
    candidatos <- candidatos[!vapply(
      candidatos, function(candidato) identical(candidato$tipo, "tablesample"),
      logical(1L)
    )]
  }
  candidatos
}

.sondas_muestreo_previstas_dbi <- function(candidatos) {
  if (!length(candidatos)) return(0L)
  as.integer(sum(vapply(candidatos, function(candidato) {
    if (identical(candidato$tipo, "tablesample_filas") ||
        identical(candidato$tipo, "tablesample")) {
      1L
    } else {
      length(candidato$funciones)
    }
  }, integer(1L))))
}

# `alias` estaba en la firma y la funcion lo REASIGNA antes de usarlo, con
# `dbQuoteIdentifier(conexion, "lupa_sonda")`. O sea que lo que pasara el
# llamador se descartaba siempre; y de hecho pasaba `NULL`. Un argumento
# sombreado es peor que uno sin usar: hace creer que el valor influye.
.forma_muestreo_dbi <- function(candidato, tabla_sql, campos_sql, porcentaje,
                                muestra, dialecto) {
  # Con `muestra = Inf` -la tabla entera, que es el valor por omision- ninguna
  # forma de muestreo en el motor tiene sentido, y hay que decirlo una sola vez:
  #
  # - la de cantidad fija escribiria `RESERVOIR (Inf ROWS)` y el motor no parsea;
  # - la de porcentaje recibe una fraccion saturada en 1, o sea `100 PERCENT`,
  #   que es la tabla entera;
  # - la de orden pseudoaleatorio no tiene donde cortar, y ordenar todo para
  #   llevarse todo tampoco es muestrear.
  #
  # Estaba guardado rama por rama y de tres se guardaron dos: la de DuckDB se
  # paso por alto y contra un motor real daba error de sintaxis. Guardar caso por
  # caso es exactamente como se olvida uno, y ademas deja la siguiente rama que
  # se agregue sin proteger. Por eso vive aca y no adentro.
  if (!is.finite(muestra)) return(NULL)
  if (identical(candidato$tipo, "tablesample_filas")) {
    return(list(
      sql = paste0(
        "SELECT ", paste(campos_sql, collapse = ", "), " FROM ",
        candidato$constructor(tabla_sql, muestra)
      ),
      filas = -1L,
      metodo = candidato$nombre,
      descripcion = candidato$descripcion,
      funcion = NA_character_
    ))
  }
  if (identical(candidato$tipo, "tablesample")) {
    base <- paste0(
      "SELECT ", paste(campos_sql, collapse = ", "), " FROM ",
      candidato$constructor(tabla_sql, porcentaje)
    )
    acotada <- dialecto$limitar(base, muestra, 0)
    return(list(
      sql = if (is.null(acotada)) base else acotada,
      filas = -1L,
      metodo = candidato$nombre,
      descripcion = candidato$descripcion,
      funcion = NA_character_
    ))
  }
  funcion <- candidato$funciones[[1L]]
  base <- paste0(
    "SELECT ", paste(campos_sql, collapse = ", "), " FROM ", tabla_sql,
    " ORDER BY ", funcion$sql
  )
  acotada <- dialecto$limitar(base, muestra, 0)
  if (is.null(acotada)) return(NULL)
  list(
    sql = acotada, filas = -1L, metodo = candidato$nombre,
    descripcion = candidato$descripcion,
    funcion = funcion$nombre
  )
}

.estado_forma_muestreo_dbi <- function(candidato, tabla_sql, campos_sql,
                                       muestra, dialecto) {
  if (is.null(candidato)) {
    return(list(
      forma_construible = FALSE,
      motivo = "capacidad_no_aceptada:sin_forma_muestreo"
    ))
  }
  forma <- tryCatch(
    # `porcentaje = "1"` solo permite construir la sentencia. No se ejecuta:
    # el plan usa esta comprobacion para detectar, entre otros casos, que
    # `muestra = Inf` no tiene una forma de subconjunto que escribir.
    .forma_muestreo_dbi(
      candidato, tabla_sql, campos_sql, porcentaje = "1", muestra, dialecto
    ),
    error = function(e) e
  )
  if (inherits(forma, "condition")) {
    return(list(
      forma_construible = FALSE,
      motivo = "capacidad_no_aceptada:sonda_muestreo"
    ))
  }
  if (is.null(forma)) {
    return(list(
      forma_construible = FALSE,
      motivo = "capacidad_no_aceptada:sonda_muestreo"
    ))
  }
  list(forma_construible = TRUE, motivo = NA_character_)
}

.sondar_muestreo_dbi <- function(conexion, tabla_sql, dialecto, presupuesto,
                                 tipo_objeto = NA_character_) {
  candidatos <- .candidatos_muestreo_dbi(conexion, dialecto, tipo_objeto)
  if (!length(candidatos)) {
    return(list(
      disponible = FALSE, candidato = NULL, sondas = character(),
      motivo = "capacidad_no_aceptada:sin_forma_muestreo"
    ))
  }
  alias <- .citar_identificador_dbi(conexion, "lupa_sonda")
  sondas <- character()
  aceptada <- NULL
  presupuesto_bloqueado <- FALSE
  for (candidato in candidatos) {
    if (identical(candidato$tipo, "tablesample_filas")) {
      forma <- .forma_muestreo_dbi(
        candidato, tabla_sql, paste0("1 AS ", alias), porcentaje = "1",
        muestra = 1L, dialecto = dialecto
      )
      if (is.null(forma)) next
      sql <- forma$sql
    } else if (identical(candidato$tipo, "tablesample")) {
      # Sin `WHERE 1 = 0`, y la razon vale la pena: DuckDB acepta
      # `TABLESAMPLE SYSTEM (10) WHERE 1 = 0` y rechaza la misma clausula sin el
      # filtro, porque con un filtro trivialmente falso no llega a validar el
      # metodo de muestreo. La sonda pasaba y la consulta real fallaba: una
      # sonda que no ejercita la forma que despues se emite no prueba nada. El
      # recorte lo pone el propio muestreo mas el limite del dialecto, asi que
      # sigue siendo barata.
      forma <- .forma_muestreo_dbi(
        candidato, tabla_sql, paste0("1 AS ", alias), porcentaje = "1",
        muestra = 1L, dialecto = dialecto
      )
      if (is.null(forma)) next
      sql <- forma$sql
    } else {
      funciones <- candidato$funciones
      for (funcion in funciones) {
        sql <- paste0(
          "SELECT 1 AS ", alias, " FROM ", tabla_sql,
          " WHERE 1 = 0 ORDER BY ", funcion$sql
        )
        acotada <- dialecto$limitar(sql, 1L, 0)
        if (!is.null(acotada)) sql <- acotada
        sondas <- c(sondas, sql)
        prueba <- .consultar_dbi(
          conexion, sql, presupuesto, etapa = "sonda_muestreo"
        )
        presupuesto_bloqueado <- presupuesto_bloqueado ||
          .consulta_bloqueada_por_presupuesto_dbi(prueba, presupuesto)
        if (is.null(aceptada) && isTRUE(prueba$ok) && !is.null(acotada)) {
          aceptada <- candidato
          aceptada$funciones <- list(funcion)
        }
      }
      next
    }
    sondas <- c(sondas, sql)
    prueba <- .consultar_dbi(
      conexion, sql, presupuesto, etapa = "sonda_muestreo"
    )
    presupuesto_bloqueado <- presupuesto_bloqueado ||
      .consulta_bloqueada_por_presupuesto_dbi(prueba, presupuesto)
    if (is.null(aceptada) && isTRUE(prueba$ok)) aceptada <- candidato
  }
  if (is.null(aceptada)) {
    return(list(
      disponible = FALSE, candidato = NULL, sondas = sondas,
      motivo = if (presupuesto_bloqueado) {
        .motivo_presupuesto_dbi(presupuesto)
      } else {
        "capacidad_no_aceptada:sonda_muestreo"
      }
    ))
  }
  list(
    disponible = TRUE, candidato = aceptada, sondas = sondas,
    motivo = NA_character_
  )
}

.fraccion_muestreo_dbi <- function(muestra, n_total) {
  total <- .numero_dbi(n_total)
  if (!is.finite(total) || total <= 0) return(1)
  min(1, max(.Machine$double.eps, muestra / total))
}

.fraccion_solicitada_muestreo_dbi <- function(muestra, n_total) {
  total <- .numero_dbi(n_total)
  pedido <- .numero_dbi(muestra)
  if (length(total) != 1L || !is.finite(total) ||
      length(pedido) != 1L || !is.finite(pedido)) return(NA_real_)
  .fraccion_muestreo_dbi(min(pedido, total), total)
}

.es_error_motor_fuente_muestreada_dbi <- function(error) {
  if (inherits(error, "lupa_error_dbi")) return(FALSE)
  clases <- .minusculas_ascii(class(error))
  any(grepl(
    "dbi|database|sql|duck|sqlite|postgres|mysql|maria|odbc|driver",
    clases, perl = TRUE, useBytes = TRUE
  ))
}

.motivo_error_fuente_muestreada_dbi <- function(error) {
  mensaje <- .mensaje_motor(error)
  if (.es_error_motor_fuente_muestreada_dbi(error)) {
    paste0("capacidad_no_aceptada:fuente_muestreada:", mensaje)
  } else {
    paste0("error_fuente_muestreada:", mensaje)
  }
}

.capturar_fuente_muestreada_dbi <- function(...) {
  tryCatch(
    list(fuente = .fuente_muestreada_dbi(...), motivo = NA_character_),
    error = function(e) {
      .repropagar_transaccion_dbi(e)
      list(
        fuente = NULL,
        motivo = .motivo_error_fuente_muestreada_dbi(e)
      )
    }
  )
}

.fuente_muestreada_dbi <- function(tabla_sql, campos_sql, muestra, n_total,
                                   dialecto, resolucion) {
  fraccion <- .fraccion_muestreo_dbi(muestra, n_total)
  porcentaje <- .decimal_sql_dbi(fraccion * 100)
  forma <- .forma_muestreo_dbi(
    resolucion$candidato, tabla_sql, campos_sql, porcentaje, muestra,
    dialecto
  )
  if (is.null(forma)) return(NULL)
  forma$fraccion <- fraccion
  # Lo pedido y lo que la tabla puede dar no son lo mismo. Pedir mil filas de
  # una tabla de diez devuelve diez, y extrapolar dividiendo por mil hundia
  # todos los conteos: `n_validos` caia a cero sobre una columna llena y
  # disparaba `sin_valores`. El tamano efectivo es el que se informa y el que
  # divide.
  total <- .numero_dbi(n_total)
  efectivas <- if (is.finite(total)) min(as.numeric(muestra), total) else {
    as.numeric(muestra)
  }
  forma$filas_solicitadas <- efectivas
  forma$filas_pedidas <- as.numeric(muestra)
  forma
}

.motivo_exito_muestreo_dbi <- function(forma) {
  if (is.null(forma) || is.null(forma$metodo)) return(NA_character_)
  if (identical(forma$metodo, "tablesample_system")) {
    return("sesgo_muestreo:tablesample_system_por_bloques")
  }
  if (identical(forma$metodo, "random_limit") &&
      identical(forma$funcion, "newid")) {
    return("sesgo_muestreo:random_limit_newid_por_fila")
  }
  if (identical(forma$metodo, "random_limit")) {
    return("sesgo_muestreo:random_limit_por_fila")
  }
  paste0("muestreo_aceptado:", forma$metodo)
}

# La mediana exacta puede conservar el limite y el salto sin llevar el orden
# completo a R, pero el conteo que los calcula tiene que vivir en la misma
# sentencia. `%` es el operador que comparten SQLite y PostgreSQL; `/` conserva
# division entera cuando ambos operandos son los conteos enteros de esos
# motores. La sonda de abajo impide extender esa suposicion a otro motor.
.candidatos_mediana_escalar_dbi <- function(conexion, dialecto) {
  forma <- dialecto$mediana_escalar
  if (is.null(forma)) return(list())
  valor <- .citar_identificador_dbi(conexion, "valor")
  construir <- function(expr, tabla, alias, materializar = FALSE,
                        doble_exacto = FALSE) {
    promedio <- .promedio_mediana_sql_dbi(
      conexion, valor, doble_exacto = doble_exacto
    )
    if (isTRUE(materializar)) {
      fuente <- "lupa_mediana_datos"
      cuenta <- "COUNT(*)"
      cuerpo <- paste0(
        "WITH ", fuente, " AS (SELECT ", expr, " AS ", valor,
        " FROM ", tabla, " WHERE ", expr, " IS NOT NULL) ",
        "SELECT ", promedio,
        " AS ", alias,
        " FROM (SELECT ", valor, " FROM ", fuente,
        " ORDER BY ", valor,
        " LIMIT 2 - (SELECT ", cuenta, " ", forma$resto, " 2 FROM ",
        fuente, ")",
        " OFFSET (SELECT (", cuenta, " - 1) ", forma$division,
        " 2 FROM ", fuente, "))", dialecto$alias_tabla("lupa_mediana")
      )
      return(cuerpo)
    }
    cuenta <- .contar_no_nulos_sql_dbi(expr, .senas_conexion_dbi(conexion))
    paste0(
      "SELECT ", promedio,
      " AS ", alias,
      " FROM (SELECT ", expr, " AS ", valor, " FROM ", tabla,
      " WHERE ", expr, " IS NOT NULL ORDER BY ", expr,
      " LIMIT 2 - (SELECT ", cuenta, " ", forma$resto, " 2 FROM ",
      tabla, ")",
      " OFFSET (SELECT (", cuenta, " - 1) ", forma$division,
      " 2 FROM ", tabla, "))", dialecto$alias_tabla("lupa_mediana")
    )
  }
  list(list(
    nombre = "subconsulta_escalar",
    construir = construir,
    sonda = function(alias, materializar = FALSE) {
      tabla <- paste0(
        "(SELECT 1 AS lupa_valor UNION ALL SELECT 2 AS lupa_valor",
        " UNION ALL SELECT 3 AS lupa_valor UNION ALL SELECT 4 AS lupa_valor)",
        " lupa_mediana_sonda"
      )
      construir('"lupa_valor"', tabla, alias, materializar = materializar)
    },
    error_esperado = "no_aplica"
  ))
}

.sondar_mediana_escalar_dbi <- function(conexion, dialecto, presupuesto,
                                        materializar = FALSE) {
  candidatos <- .candidatos_mediana_escalar_dbi(conexion, dialecto)
  sondas <- character()
  elegida <- NULL
  presupuesto_bloqueado <- FALSE
  for (candidato in candidatos) {
    alias <- .citar_identificador_dbi(conexion, "mediana")
    sql <- candidato$sonda(alias, materializar = materializar)
    sondas <- c(sondas, sql)
    prueba <- .consultar_dbi(
      conexion, sql, presupuesto, etapa = "sonda_mediana_escalar"
    )
    presupuesto_bloqueado <- presupuesto_bloqueado ||
      .consulta_bloqueada_por_presupuesto_dbi(prueba, presupuesto)
    if (!isTRUE(prueba$ok)) next
    celda <- .valor_campo_dbi(prueba$datos, "mediana")
    if (!isTRUE(celda$ok)) next
    valor <- .escalar_finito_dbi(celda$valor)
    if (isTRUE(is.finite(valor)) &&
        isTRUE(all.equal(valor, 2.5, tolerance = 1e-8))) {
      elegida <- candidato
      break
    }
  }
  list(
    disponible = !is.null(elegida), candidato = elegida, sondas = sondas,
    motivo = if (is.null(elegida)) {
      if (!length(candidatos)) {
        paste0(
          "El dialecto `", dialecto$nombre,
          "` no declara una forma de mediana con subconsulta escalar; se",
          " conserva la v\u00eda de dos consultas."
        )
      } else if (presupuesto_bloqueado) {
        .motivo_presupuesto_dbi(presupuesto)
      } else {
        paste(
          "El motor no acept\u00f3 la mediana con subconsulta escalar o no",
          "conserv\u00f3 la divisi\u00f3n entera esperada; se conserva la v\u00eda de dos",
          "consultas."
        )
      }
    } else {
      "El motor acept\u00f3 la mediana con subconsulta escalar y divisi\u00f3n entera."
    }
  )
}

.publicar_mediana_escalar_dbi <- function(resolucion) {
  if (is.null(resolucion)) return(NULL)
  candidato <- resolucion$candidato
  list(
    disponible = isTRUE(resolucion$disponible),
    metodo = if (is.null(candidato)) NA_character_ else candidato$nombre,
    sondas = resolucion$sondas,
    motivo = resolucion$motivo
  )
}

# La forma de ventanas mantiene la relacion muestreada en una sola referencia:
# el conteo y las posiciones se calculan sobre la misma CTE que luego agrega las
# dos posiciones centrales. Es la salida de `muestra_motor` en los dialectos que
# no aceptan la forma escalar ni una consolidada -MySQL, SQL Server con
# compatibilidad antigua- y la de cada columna que no puede usar la consolidada
# (ver `.resumen_columna_dbi()`).
#
# Las posiciones centrales se eligen sin dividir. `2 * posicion` entre `n` y
# `n + 2` deja exactamente `(n + 1) %/% 2` y `(n + 2) %/% 2`, las dos que
# promedia `median()`. La forma anterior, `posicion IN ((n + 1) / 2, ...)`,
# suponia division entera: en DuckDB, MySQL y MariaDB `/` es decimal, la
# primera central no coincidia con ninguna posicion y la mediana de 1, 2, 3 y 4
# daba 3. Medido el 2026-11-05 en los cinco motores.
#
# La consulta de prueba lee de un `SELECT ... UNION ALL`, como la consulta real
# lee de una subconsulta. Leia de `(VALUES (1.0), ...) AS t(v)`, que MySQL 8.4
# rechaza por sintaxis -pide `VALUES ROW(...)`-: la prueba fallaba por una
# construccion que el paquete nunca emite y la mediana de la muestra quedaba
# `no_disponible` en un motor que acepta la CTE y las ventanas.
#
# Con `escalada = TRUE` las dos centrales se promedian con la expresion de
# `.mediana_escalada_dbi()`, que no desborda con valores enormes, pero dentro de
# la misma sentencia: una segunda consulta leeria otra muestra.
.candidatos_mediana_cte_ventana_dbi <- function(conexion) {
  alias <- function(nombre) {
    .citar_identificador_dbi(conexion, nombre)
  }
  construir <- function(expr, tabla, alias_salida, escalada = FALSE,
                        tipo = NA_character_, doble_exacto = FALSE) {
    valor <- alias("valor")
    n_validos <- alias("n_validos")
    promedio <- if (isTRUE(escalada)) {
      .promedio_centrales_escalado_sql_dbi(valor)
    } else {
      .promedio_mediana_sql_dbi(conexion, valor, tipo, doble_exacto)
    }
    paste0(
      "WITH lupa_mediana_datos AS (",
      "SELECT ", expr, " AS ", valor, " FROM ", tabla,
      " WHERE ", expr, " IS NOT NULL), ",
      "ordenada AS (SELECT ", valor, ", COUNT(*) OVER () AS ",
      n_validos, ", ROW_NUMBER() OVER (ORDER BY ", valor,
      ") AS ", alias("posicion"), " FROM lupa_mediana_datos) ",
      "SELECT ", promedio, " AS ", alias_salida,
      " FROM ordenada WHERE 2 * ", alias("posicion"),
      " BETWEEN ", n_validos, " AND ", n_validos, " + 2"
    )
  }
  list(list(
    nombre = "cte_ventana",
    construir = construir,
    sonda = function(alias_salida) {
      construir(
        "v", paste0(
          "(SELECT 1.0 AS v UNION ALL SELECT 2.0 AS v",
          " UNION ALL SELECT 3.0 AS v UNION ALL SELECT 4.0 AS v) AS lupa_sonda"
        ), alias_salida
      )
    },
    error_esperado = "no_aplica"
  ))
}

.nombre_mediana_cte_muestra_dbi <- function(muestreo) {
  if (is.null(muestreo)) return("cte_ventana")
  metodo <- if (!is.null(muestreo$metodo)) muestreo$metodo else
    if (!is.null(muestreo$candidato)) muestreo$candidato$nombre else NA_character_
  funcion <- if (!is.null(muestreo$funcion)) muestreo$funcion else {
    funciones <- if (is.null(muestreo$candidato)) NULL else
      muestreo$candidato$funciones
    if (length(funciones)) funciones[[1L]]$nombre else NA_character_
  }
  if (identical(metodo, "tablesample_system")) {
    return("cte_ventana_tablesample_system")
  }
  if (identical(metodo, "random_limit") && identical(funcion, "newid")) {
    return("cte_ventana_newid")
  }
  "cte_ventana"
}

.sondar_mediana_cte_ventana_dbi <- function(conexion, presupuesto) {
  if (!is.null(presupuesto) && !is.null(presupuesto$mediana_cte_ventana)) {
    return(presupuesto$mediana_cte_ventana)
  }
  candidatos <- .candidatos_mediana_cte_ventana_dbi(conexion)
  alias <- .citar_identificador_dbi(conexion, "mediana")
  sondas <- character()
  elegida <- NULL
  control_negativo_ok <- FALSE
  presupuesto_bloqueado <- FALSE
  for (candidato in candidatos) {
    sql <- candidato$sonda(alias)
    sondas <- c(sondas, sql)
    positiva <- .consultar_dbi(
      conexion, sql, presupuesto, etapa = "sonda_mediana_cte_ventana"
    )
    presupuesto_bloqueado <- presupuesto_bloqueado ||
      .consulta_bloqueada_por_presupuesto_dbi(positiva, presupuesto)
    celda <- if (isTRUE(positiva$ok)) {
      .valor_campo_dbi(positiva$datos, "mediana")
    } else {
      list(ok = FALSE, valor = NA_real_)
    }
    valor <- if (isTRUE(celda$ok)) .escalar_finito_dbi(celda$valor) else NA_real_
    valor_ok <- isTRUE(is.finite(valor)) &&
      isTRUE(all.equal(valor, 2.5, tolerance = 1e-8))
    sql_negativa <- sub(
      "AVG\\(", "FUNCION_INVALIDA_LUPA(", sql, fixed = FALSE
    )
    sondas <- c(sondas, sql_negativa)
    negativa <- .consultar_dbi(
      conexion, sql_negativa, presupuesto,
      etapa = "sonda_mediana_cte_ventana_control_negativo"
    )
    presupuesto_bloqueado <- presupuesto_bloqueado ||
      .consulta_bloqueada_por_presupuesto_dbi(negativa, presupuesto)
    control_negativo_ok <- !isTRUE(negativa$ok) && !presupuesto_bloqueado
    if (is.null(elegida) && valor_ok && control_negativo_ok) {
      elegida <- candidato
    }
  }
  resultado <- list(
    disponible = !is.null(elegida), candidato = elegida, sondas = sondas,
    control_negativo = control_negativo_ok,
    motivo = if (is.null(elegida)) {
      if (presupuesto_bloqueado) {
        .motivo_presupuesto_dbi(presupuesto)
      } else {
        "capacidad_no_aceptada:sonda_mediana_cte_ventana"
      }
    } else {
      "La sonda de la CTE de ventanas devolvi\u00f3 2,5 y su control negativo fall\u00f3."
    }
  )
  if (!is.null(presupuesto)) presupuesto$mediana_cte_ventana <- resultado
  resultado
}

# La frecuencia de la moda y su denominador pueden salir de la misma
# agregacion: la ventana se aplica sobre los grupos que ya produjo GROUP BY.
# La sonda usa una tabla chica para no asumir que todos los motores aceptan
# una ventana sobre un agregado.
.candidatos_moda_guardian_dbi <- function(conexion, dialecto) {
  alias <- function(nombre) {
    .citar_identificador_dbi(conexion, nombre)
  }
  # `valor` es lo que se lee del grupo: por omision la columna, y para un
  # decimal su texto exacto (ver `.expresion_decimal_moda_dbi()`). El grupo y el
  # desempate siguen siendo la columna.
  construir <- function(columna, tabla, valor = columna, orden = columna) {
    sin_limite <- paste0(
      "SELECT ", valor, " AS ", alias("valor"), ", ",
      .conteo_sql_dbi("COUNT(*)", .senas_conexion_dbi(conexion)), " AS ",
      alias("frecuencia"), ", ",
      .conteo_sql_dbi("SUM(COUNT(*)) OVER ()", .senas_conexion_dbi(conexion)),
      " AS ",
      alias("n_validos_guard"), " FROM ", tabla, " WHERE ", columna,
      " IS NOT NULL GROUP BY ", columna, " ORDER BY COUNT(*)",
      " DESC, ", orden, " ASC"
    )
    acotada <- dialecto$limitar(sin_limite, 1L, 0)
    if (is.null(acotada)) sin_limite else acotada
  }
  list(list(
    nombre = "ventana_agregado",
    construir = construir,
    sonda = function() {
      tabla <- paste0(
        "(SELECT 1 AS lupa_valor UNION ALL SELECT 2 UNION ALL SELECT 2)",
        dialecto$alias_tabla("lupa_moda_sonda")
      )
      construir(alias("lupa_valor"), tabla)
    }
  ))
}

.sondar_moda_guardian_dbi <- function(conexion, dialecto, presupuesto) {
  if (!is.null(presupuesto) && !is.null(presupuesto$moda_guardian)) {
    return(presupuesto$moda_guardian)
  }
  candidatos <- .candidatos_moda_guardian_dbi(conexion, dialecto)
  sondas <- character()
  elegida <- NULL
  presupuesto_bloqueado <- FALSE
  for (candidato in candidatos) {
    sql <- candidato$sonda()
    sondas <- c(sondas, sql)
    prueba <- .consultar_dbi(
      conexion, sql, presupuesto, filas = 1L,
      etapa = "sonda_moda_guardian"
    )
    presupuesto_bloqueado <- presupuesto_bloqueado ||
      .consulta_bloqueada_por_presupuesto_dbi(prueba, presupuesto)
    if (!isTRUE(prueba$ok)) next
    valor <- .valor_campo_dbi(prueba$datos, "valor")
    frecuencia <- .valor_campo_dbi(prueba$datos, "frecuencia")
    guardian <- .valor_campo_dbi(prueba$datos, "n_validos_guard")
    if (!isTRUE(valor$ok) || !isTRUE(frecuencia$ok) ||
        !isTRUE(guardian$ok)) next
    if (isTRUE(.numero_dbi(valor$valor) == 2) &&
        isTRUE(.numero_dbi(frecuencia$valor) == 2) &&
        isTRUE(.numero_dbi(guardian$valor) == 3)) {
      elegida <- candidato
      break
    }
  }
  resultado <- list(
    disponible = !is.null(elegida), candidato = elegida, sondas = sondas,
    motivo = if (is.null(elegida)) {
      if (!length(candidatos)) {
        "El adaptador no declara una forma de moda con guardian; se conserva la consulta actual sin guardian."
      } else if (presupuesto_bloqueado) {
        .motivo_presupuesto_dbi(presupuesto)
      } else {
        paste(
          "El motor rechaz\u00f3 la forma de moda con guardian o no devolvi\u00f3 el",
          "resultado esperado; se conserva la consulta actual sin guardian."
        )
      }
    } else {
      paste(
        "El motor acept\u00f3 la forma de moda con guardian; la cota se comprueba",
        "dentro de la misma sentencia."
      )
    }
  )
  if (!is.null(presupuesto)) presupuesto$moda_guardian <- resultado
  resultado
}

.publicar_moda_guardian_dbi <- function(resolucion) {
  if (is.null(resolucion)) return(NULL)
  candidato <- resolucion$candidato
  list(
    disponible = isTRUE(resolucion$disponible),
    metodo = if (is.null(candidato)) NA_character_ else candidato$nombre,
    sondas = resolucion$sondas,
    motivo = resolucion$motivo
  )
}

# Un percentil exacto del motor se acepta solo si devuelve el valor con todas
# sus cifras. MariaDB 11.8 tipa el resultado de `PERCENTILE_CONT` como
# `double(18,10)`: satura en 99999999.9999999999 y redondea a diez decimales.
# La mediana de una columna de montos del orden de 1e12 se publicaba 1e8, la de
# una del orden de 1e-12 se publicaba 0 y la de `rnorm()` perdia desde el
# decimo decimal, todas como `calculado` y en el camino por omision. Medido el
# 2026-11-05. La consulta de prueba corria sobre `1.0` y nada miraba su valor.
#
# La de ahora lee una sola fila -el percentil de una fila es esa fila, sin
# interpolar- con un valor de mas de 1e8 y otro de menos de 1e-10, y exige los
# dos identicos. El literal lleva exponente para que todos los motores lo lean
# como doble.
.CIFRAS_PRUEBA_PERCENTIL_DBI <- c(
  lupa_sonda = 1.2345678901234567e11,
  lupa_percentil_fino = 1.2345678901234567e-11
)

.prueba_percentil_dbi <- function(alias, ventana = FALSE) {
  sobre <- if (isTRUE(ventana)) " OVER ()" else ""
  literal <- function(x) sprintf("%.17e", x)
  paste0(
    "SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY lupa_valor)", sobre,
    " AS ", alias, ", PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY lupa_fino)",
    sobre, " AS lupa_percentil_fino FROM (SELECT ",
    literal(.CIFRAS_PRUEBA_PERCENTIL_DBI[["lupa_sonda"]]), " AS lupa_valor, ",
    literal(.CIFRAS_PRUEBA_PERCENTIL_DBI[["lupa_percentil_fino"]]),
    " AS lupa_fino) lupa_sonda"
  )
}

# `NA` si la prueba volvio con todas las cifras; si no, lo que volvio.
.cifras_perdidas_percentil_dbi <- function(datos) {
  leidos <- vapply(names(.CIFRAS_PRUEBA_PERCENTIL_DBI), function(campo) {
    celda <- .valor_campo_dbi(datos, campo)
    if (!isTRUE(celda$ok)) return(NA_real_)
    .escalar_finito_dbi(celda$valor)
  }, numeric(1L))
  if (identical(unname(leidos), unname(.CIFRAS_PRUEBA_PERCENTIL_DBI))) {
    return(NA_character_)
  }
  paste0(
    "el percentil devolvi\u00f3 ",
    paste(sprintf("%.17g", leidos), collapse = " y "), " en lugar de ",
    paste(sprintf("%.17g", .CIFRAS_PRUEBA_PERCENTIL_DBI), collapse = " y "),
    ": pierde cifras"
  )
}

# Las sondas ordenan por la COLUMNA de la subconsulta y no por una constante.
# Ordenar por `1.0` parecia lo mas neutral y hacia que dos caminos declarados no
# se ejercitaran NUNCA, cada uno por su motivo, y sin que se notara: la sonda
# fallaba, el paquete degradaba a la via por columna y publicaba valores
# correctos. Medido el 2026-08-30 contra los motores reales:
#
#   - SQL Server rechaza una constante en el `ORDER BY` de una funcion de
#     ventana -"Windowed functions... do not support constants as ORDER BY
#     clause expressions"-, asi que `PERCENTILE_CONT_OVER` no se activaba jamas.
#   - MariaDB 11.8 implementa `PERCENTILE_CONT` SOLO como funcion de ventana,
#     y estaba clasificada con el candidato que no lleva `OVER`: su sonda
#     fallaba por la sintaxis, no por la constante. Pasa al candidato con
#     ventana, donde acepta la consolidada y varias expresiones a la vez.
#
# Una sonda tiene que parecerse a la consulta que habilita. La que ordenaba por
# una constante probaba una forma que el paquete no emite nunca.
#
# Y tiene que mirar el valor, no solo que la consulta corra: ver
# `.prueba_percentil_dbi()`. MariaDB acepta la forma con ventana y pierde
# cifras.
#
# Algunos motores pueden obtener varios percentiles en la misma agregacion.
# Esta capacidad se sondea por separado porque una sonda que solo prueba una
# mediana no prueba que el motor acepte varias expresiones en un SELECT.
.candidatos_mediana_consolidada_dbi <- function(conexion) {
  senas <- .senas_conexion_dbi(conexion)
  candidatos <- list(
    list(
      nombre = "PERCENTILE_CONT",
      patron = "postgres|redshift|oracle|snowflake|duckdb",
      exacta = TRUE,
      error_esperado = "desconocido",
      construir = function(expr, tabla, alias) paste0(
        "SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY ", expr,
        ") AS ", alias, " FROM ", tabla
      ),
      construir_multiple = function(expresiones, tabla) paste0(
        "SELECT ", paste(expresiones, collapse = ", "), " FROM ", tabla
      ),
      expresion = function(expr, alias) paste0(
        "PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY ", expr,
        ") AS ", alias
      ),
      sonda = function(alias) .prueba_percentil_dbi(alias),
      comprobar_cifras = TRUE
    ),
    list(
      nombre = "PERCENTILE_CONT_OVER",
      patron = "sql server|microsoft sql|sqlserver|mssql|mariadb",
      exacta = TRUE,
      error_esperado = "desconocido",
      construir = function(expr, tabla, alias) paste0(
        "SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY ", expr,
        ") OVER () AS ", alias, " FROM ", tabla
      ),
      construir_multiple = function(expresiones, tabla) paste0(
        "SELECT DISTINCT ", paste(expresiones, collapse = ", "),
        " FROM ", tabla
      ),
      expresion = function(expr, alias) paste0(
        "PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY ", expr,
        ") OVER () AS ", alias
      ),
      sonda = function(alias) .prueba_percentil_dbi(alias, ventana = TRUE),
      comprobar_cifras = TRUE
    )
  )
  reconocidos <- vapply(candidatos, function(x) {
    !is.na(x$patron) && grepl(x$patron, senas, perl = TRUE)
  }, logical(1L))
  # La consolidacion solo tiene implementaciones declaradas para estos motores.
  # En un motor sin senas no se adivina una sintaxis ni se paga una sonda que no
  # puede justificar el camino que se emitira: se conserva la mediana actual por
  # columna. Los motores reconocidos se prueban, como las demas capacidades.
  candidatos[which(reconocidos)]
}

.sondar_mediana_consolidada_dbi <- function(conexion, presupuesto) {
  if (!is.null(presupuesto$mediana_consolidada)) {
    return(presupuesto$mediana_consolidada)
  }
  alias <- .citar_identificador_dbi(conexion, "lupa_sonda")
  candidatos <- .candidatos_mediana_consolidada_dbi(conexion)
  sondas <- character()
  motivos_motor <- character()
  elegida <- NULL
  presupuesto_bloqueado <- FALSE
  for (candidato in candidatos) {
    sql <- candidato$sonda(alias)
    sondas <- c(sondas, sql)
    prueba <- .consultar_dbi(
      conexion, sql, presupuesto, etapa = "sonda_mediana_consolidada"
    )
    presupuesto_bloqueado <- presupuesto_bloqueado ||
      .consulta_bloqueada_por_presupuesto_dbi(prueba, presupuesto)
    perdida <- if (isTRUE(prueba$ok) && isTRUE(candidato$comprobar_cifras)) {
      .cifras_perdidas_percentil_dbi(prueba$datos)
    } else NA_character_
    if (!is.na(perdida)) {
      motivos_motor <- c(
        motivos_motor, paste0("`", candidato$nombre, "`: ", perdida)
      )
      next
    }
    if (is.null(elegida) && isTRUE(prueba$ok)) elegida <- candidato
    if (!isTRUE(prueba$ok)) {
      motivo <- if (is.null(prueba$motivo) || !length(prueba$motivo) ||
                    all(is.na(prueba$motivo))) {
        ""
      } else {
        .resumir_valor_reporte(prueba$motivo[[1L]], max_caracteres = 240L)
      }
      if (nzchar(motivo)) {
        motivos_motor <- c(
          motivos_motor,
          paste0("`", candidato$nombre, "`: ", motivo)
        )
      }
    }
  }
  motivo_sin_candidato <- if (!length(candidatos)) {
    "No hay una forma consolidada declarada para este motor; se conserva la mediana por columna."
  } else if (any(grepl("pierde cifras", motivos_motor, fixed = TRUE, useBytes = TRUE))) {
    "El motor devolvi\u00f3 `PERCENTILE_CONT` sin todas sus cifras; se conserva la mediana por columna."
  } else {
    "El motor no acept\u00f3 una consulta consolidada de `PERCENTILE_CONT`; se conserva la mediana por columna."
  }
  if (length(motivos_motor)) {
    motivo_sin_candidato <- paste0(
      motivo_sin_candidato,
      " Motivo del motor: ",
      paste(unique(motivos_motor), collapse = "; ")
    )
  }
  resultado <- list(
    disponible = !is.null(elegida), candidato = elegida, sondas = sondas,
    motivo = if (is.null(elegida)) {
      if (presupuesto_bloqueado) {
        .motivo_presupuesto_dbi(presupuesto)
      } else {
        motivo_sin_candidato
      }
    } else {
      paste0("El motor acept\u00f3 `", elegida$nombre,
             "` para consolidar medianas.")
    }
  )
  presupuesto$mediana_consolidada <- resultado
  resultado
}

.candidatos_aproximacion_dbi <- function(conexion, tipo) {
  senas <- .senas_conexion_dbi(conexion)
  if (identical(tipo, "distintos")) {
    candidatos <- list(
      list(
        nombre = "APPROX_COUNT_DISTINCT",
        patron = "sql server|microsoft sql|sqlserver|mssql",
        error_esperado = "desconocido",
        construir = function(expr, tabla, alias) paste0(
          "SELECT APPROX_COUNT_DISTINCT(", expr, ") AS ", alias,
          " FROM ", tabla
        ),
        expresion = function(expr, alias) paste0(
          "APPROX_COUNT_DISTINCT(", expr, ") AS ", alias
        ),
        sonda = function(alias) paste0(
          "SELECT APPROX_COUNT_DISTINCT(1) AS ", alias
        )
      ),
      list(
        nombre = "approx_count_distinct",
        patron = "spark|databricks|hive",
        error_esperado = "desconocido",
        construir = function(expr, tabla, alias) paste0(
          "SELECT approx_count_distinct(", expr, ") AS ", alias,
          " FROM ", tabla
        ),
        expresion = function(expr, alias) paste0(
          "approx_count_distinct(", expr, ") AS ", alias
        ),
        sonda = function(alias) paste0(
          "SELECT approx_count_distinct(1) AS ", alias
        )
      ),
      list(
        nombre = "approx_count_distinct_generico",
        patron = NA_character_,
        error_esperado = "desconocido",
        construir = function(expr, tabla, alias) paste0(
          "SELECT APPROX_COUNT_DISTINCT(", expr, ") AS ", alias,
          " FROM ", tabla
        ),
        expresion = function(expr, alias) paste0(
          "APPROX_COUNT_DISTINCT(", expr, ") AS ", alias
        ),
        sonda = function(alias) paste0(
          "SELECT APPROX_COUNT_DISTINCT(1) AS ", alias
        )
      )
    )
  } else {
    candidatos <- list(
      list(
        nombre = "PERCENTILE_CONT",
        patron = "postgres|redshift|duckdb|sql server|microsoft sql|sqlserver|mssql",
        exacta = TRUE,
        error_esperado = "desconocido",
        construir = function(expr, tabla, alias) paste0(
          "SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY ", expr,
          ") AS ", alias, " FROM ", tabla
        ),
        sonda = function(alias) .prueba_percentil_dbi(alias),
        comprobar_cifras = TRUE
      ),
      list(
        nombre = "PERCENTILE_CONT_OVER",
        patron = "sql server|microsoft sql|sqlserver|mssql|mariadb",
        exacta = TRUE,
        error_esperado = "desconocido",
        construir = function(expr, tabla, alias) paste0(
          "SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY ", expr,
          ") OVER () AS ", alias, " FROM ", tabla
        ),
        sonda = function(alias) .prueba_percentil_dbi(alias, ventana = TRUE),
        comprobar_cifras = TRUE
      ),
      list(
        nombre = "approx_percentile",
        patron = "snowflake|presto|trino",
        exacta = FALSE,
        error_esperado = "desconocido",
        construir = function(expr, tabla, alias) paste0(
          "SELECT APPROX_PERCENTILE(", expr, ", 0.5) AS ", alias,
          " FROM ", tabla
        ),
        sonda = function(alias) paste0(
          "SELECT APPROX_PERCENTILE(1.0, 0.5) AS ", alias
        )
      ),
      list(
        nombre = "approx_quantile",
        patron = "duckdb",
        exacta = FALSE,
        error_esperado = "desconocido",
        construir = function(expr, tabla, alias) paste0(
          "SELECT approx_quantile(", expr, ", 0.5) AS ", alias,
          " FROM ", tabla
        ),
        sonda = function(alias) paste0(
          "SELECT approx_quantile(1.0, 0.5) AS ", alias
        )
      ),
      list(
        nombre = "percentile_approx",
        patron = "spark|databricks|hive",
        exacta = FALSE,
        error_esperado = "desconocido",
        construir = function(expr, tabla, alias) paste0(
          "SELECT percentile_approx(", expr, ", 0.5) AS ", alias,
          " FROM ", tabla
        ),
        sonda = function(alias) paste0(
          "SELECT percentile_approx(1.0, 0.5) AS ", alias
        )
      ),
      list(
        nombre = "quantile",
        patron = "clickhouse",
        exacta = FALSE,
        error_esperado = "desconocido",
        construir = function(expr, tabla, alias) paste0(
          "SELECT quantile(0.5)(", expr, ") AS ", alias,
          " FROM ", tabla
        ),
        sonda = function(alias) paste0(
          "SELECT quantile(0.5)(1.0) AS ", alias
        )
      )
    )
  }
  reconocidos <- vapply(candidatos, function(x) {
    !is.na(x$patron) && grepl(x$patron, senas, perl = TRUE)
  }, logical(1L))
  candidatos[c(which(reconocidos), which(!reconocidos))]
}

.sondar_aproximacion_dbi <- function(conexion, tipo, presupuesto) {
  candidatos <- .candidatos_aproximacion_dbi(conexion, tipo)
  alias <- .citar_identificador_dbi(conexion, "lupa_sonda")
  sondas <- character()
  elegida <- NULL
  presupuesto_bloqueado <- FALSE
  for (candidato in candidatos) {
    sql <- candidato$sonda(alias)
    if (.es_oracle_dbi(conexion) &&
        !grepl(.regex_sin_caja("\\bFROM\\b"), sql, perl = TRUE)) {
      sql <- paste0(sql, " FROM DUAL")
    }
    sondas <- c(sondas, sql)
    resultado <- .consultar_dbi(
      conexion, sql, presupuesto, etapa = "sonda_aproximacion"
    )
    presupuesto_bloqueado <- presupuesto_bloqueado ||
      .consulta_bloqueada_por_presupuesto_dbi(resultado, presupuesto)
    # Una forma exacta que pierde cifras no es una aproximacion: es un numero
    # falso. Ver `.prueba_percentil_dbi()`.
    if (isTRUE(resultado$ok) && isTRUE(candidato$comprobar_cifras) &&
        !is.na(.cifras_perdidas_percentil_dbi(resultado$datos))) {
      next
    }
    if (is.null(elegida) && isTRUE(resultado$ok)) elegida <- candidato
  }
  list(
    disponible = !is.null(elegida), candidato = elegida, sondas = sondas,
    motivo = if (is.null(elegida)) {
      if (presupuesto_bloqueado) {
        .motivo_presupuesto_dbi(presupuesto)
      } else {
        paste0("El motor no acept\u00f3 una funci\u00f3n aproximada para `", tipo, "`.")
      }
    } else {
      paste0("El motor acept\u00f3 `", elegida$nombre, "` para `", tipo, "`.")
    }
  )
}

.orden_muestra_publica_dbi <- function(orden_muestra = NULL, muestreo = NULL) {
  solicitado <- if (is.null(orden_muestra)) character() else {
    as.character(orden_muestra)
  }
  solicitado <- solicitado[!is.na(solicitado) & nzchar(solicitado)]
  if (!length(solicitado)) {
    return(list(
      solicitado = character(), aplicado = NA,
      motivo = "No se solicit\u00f3 `orden_muestra`."
    ))
  }
  aplicado <- if (!is.null(muestreo) &&
                  !is.null(muestreo$orden_muestra_aplicado)) {
    isTRUE(muestreo$orden_muestra_aplicado)
  } else {
    metodo <- if (is.null(muestreo)) NA_character_ else muestreo$metodo
    if (grepl("tablesample_|random_limit", as.character(metodo),
              perl = TRUE, useBytes = TRUE)) FALSE else NA
  }
  motivo <- if (isTRUE(aplicado)) {
    "Se aplic\u00f3 `orden_muestra`."
  } else if (identical(aplicado, FALSE)) {
    "No se aplic\u00f3 `orden_muestra`: el m\u00e9todo de muestreo por bloques o filas gobierna la selecci\u00f3n."
  } else {
    "No se pudo verificar si se aplic\u00f3 `orden_muestra`."
  }
  list(solicitado = solicitado, aplicado = aplicado, motivo = motivo)
}

.publicar_muestreo_dbi <- function(resolucion, forma = NULL, n_total = NA,
                                   muestreo_meta = NULL) {
  candidato <- resolucion$candidato
  motivo_exito <- .motivo_exito_muestreo_dbi(forma)
  numero <- function(objeto, nombre) {
    if (is.null(objeto) || is.null(objeto[[nombre]]) ||
        !length(objeto[[nombre]])) {
      return(NA_real_)
    }
    suppressWarnings(as.numeric(objeto[[nombre]][[1L]]))
  }
  filas_obtenidas <- numero(muestreo_meta, "filas_obtenidas")
  motivo_filas_obtenidas <- if (is.finite(filas_obtenidas)) {
    NA_character_
  } else if (!is.null(muestreo_meta) &&
             length(muestreo_meta$motivo_filas_obtenidas) == 1L &&
             !is.na(muestreo_meta$motivo_filas_obtenidas)) {
    as.character(muestreo_meta$motivo_filas_obtenidas)
  } else {
    NA_character_
  }
  orden <- .orden_muestra_publica_dbi(
    if (is.null(muestreo_meta)) NULL else muestreo_meta$orden_muestra,
    muestreo_meta
  )
  list(
    disponible = isTRUE(resolucion$disponible),
    metodo = if (is.null(forma)) {
      if (is.null(candidato)) NA_character_ else candidato$nombre
    } else forma$metodo,
    # `metodo` conserva el nombre historico de la capacidad. Estos campos
    # explicitos hacen auditable la distincion entre TABLESAMPLE y el fallback
    # fila a fila; en particular, un NEWID aceptado no queda como un random
    # anonimo ni pierde el motivo de su aceptacion.
    metodo_muestreo = if (is.null(forma)) {
      if (is.null(candidato)) NA_character_ else candidato$nombre
    } else forma$metodo,
    funcion_muestreo = if (is.null(forma)) {
      funciones <- if (is.null(candidato)) NULL else candidato$funciones
      if (length(funciones)) funciones[[1L]]$nombre else NA_character_
    } else forma$funcion,
    sesgo_muestreo = if (identical(motivo_exito,
                                   "sesgo_muestreo:tablesample_system_por_bloques")) {
      "por_bloques"
    } else if (grepl("random_limit", as.character(if (is.null(forma)) {
      NA_character_
    } else forma$metodo), fixed = TRUE, useBytes = TRUE)) {
      "por_fila"
    } else NA_character_,
    descripcion = if (is.null(forma)) {
      if (is.null(candidato)) NA_character_ else candidato$descripcion
    } else forma$descripcion,
    fraccion = if (is.null(forma)) NA_real_ else forma$fraccion,
    # `tamano_muestra` es parte del contrato anterior: conserva el tamano
    # efectivo solicitado a la consulta, que puede estar acotado por el
    # universo. Los nombres explicitos de abajo evitan confundirlo con lo que
    # realmente devolvio la lectura.
    tamano_muestra = if (is.null(forma)) {
      numero(muestreo_meta, "tamano_muestra")
    } else {
      numero(forma, "filas_solicitadas")
    },
    filas_solicitadas = if (!is.null(forma) &&
                            !is.null(forma$filas_pedidas)) {
      numero(forma, "filas_pedidas")
    } else {
      numero(muestreo_meta, "filas_solicitadas")
    },
    filas_pedidas = if (!is.null(forma) &&
                        !is.null(forma$filas_pedidas)) {
      numero(forma, "filas_pedidas")
    } else {
      numero(muestreo_meta, "filas_pedidas")
    },
    filas_obtenidas = filas_obtenidas,
    motivo_filas_obtenidas = motivo_filas_obtenidas,
    orden_muestra_aplicado = orden$aplicado,
    motivo_orden_muestra = orden$motivo,
    universo = n_total,
    sondas = resolucion$sondas,
    motivo = if (is.null(forma) || is.na(motivo_exito)) {
      resolucion$motivo
    } else motivo_exito,
    motivo_exito = if (is.null(forma) || is.na(motivo_exito)) {
      NA_character_
    } else motivo_exito,
    motivo_sonda = resolucion$motivo,
    sql = if (is.null(forma)) NA_character_ else forma$sql
  )
}

.publicar_muestreo_plan_dbi <- function(muestreo, muestra) {
  if (is.null(muestreo)) {
    return(list(
      estado = "no_solicitado", disponible = NA, forma_construible = NA,
      metodo = NA_character_, filas_solicitadas = muestra,
      sondas_previstas = 0L,
      motivo = "El plan no solicita una muestra del motor."
    ))
  }
  candidato <- muestreo$candidato
  sondas_previstas <- if (is.null(muestreo$sondas_previstas)) {
    length(muestreo$sondas)
  } else {
    muestreo$sondas_previstas
  }
  list(
    estado = if (!isTRUE(muestreo$disponible)) "no_disponible" else if (
      length(muestreo$sondas)
    ) "disponible" else "no_sondeado",
    disponible = isTRUE(muestreo$disponible),
    forma_construible = isTRUE(muestreo$forma_construible),
    metodo = if (is.null(candidato)) NA_character_ else candidato$nombre,
    filas_solicitadas = muestra,
    sondas_previstas = as.integer(sondas_previstas),
    motivo = muestreo$motivo
  )
}

.publicar_aproximacion_dbi <- function(resolucion) {
  candidato <- resolucion$candidato
  list(
    disponible = isTRUE(resolucion$disponible),
    metodo = if (is.null(candidato)) NA_character_ else candidato$nombre,
    error_esperado = if (is.null(candidato)) NA_character_ else {
      candidato$error_esperado
    },
    sondas = resolucion$sondas,
    motivo = resolucion$motivo
  )
}

# Las senas de la conexion se leen una vez por corrida. `.senas_conexion_dbi()`
# se consulta al armar cada sentencia -175 veces sobre una tabla de cuatro
# columnas-, y `DBI::dbGetInfo()` no siempre es gratis: en duckdb 1.1 cada
# llamada manda `pragma_version()` al motor, que el plan no anuncia ni
# `max_consultas` cuenta. Un estado de la llamada, como `.CONTEXTO_COPIAS`: lo
# fijan `perfilar_dbi()` y `plan_perfilado_dbi()`, y se restaura al salir.
.CONTEXTO_SENAS <- new.env(parent = emptyenv())
.CONTEXTO_SENAS$conexion <- NULL
.CONTEXTO_SENAS$info <- NULL

.fijar_senas_conexion_dbi <- function(conexion, marco = parent.frame()) {
  volver <- substitute({
    .CONTEXTO_SENAS$conexion <- conexion_previa
    .CONTEXTO_SENAS$info <- info_previa
  }, list(conexion_previa = .CONTEXTO_SENAS$conexion,
          info_previa = .CONTEXTO_SENAS$info))
  # Una corrida anidada sobre la misma conexion -el plan dentro del perfil-
  # usa la lectura que ya esta.
  if (!is.null(.CONTEXTO_SENAS$conexion) &&
      identical(conexion, .CONTEXTO_SENAS$conexion)) {
    return(invisible(NULL))
  }
  # Solo se guarda una lectura que funciono: si falla, cada sitio sigue
  # preguntando y recibe el error como antes.
  info <- tryCatch(DBI::dbGetInfo(conexion), error = function(e) NULL)
  .CONTEXTO_SENAS$conexion <- if (is.null(info)) NULL else conexion
  .CONTEXTO_SENAS$info <- info
  do.call(on.exit, list(volver, add = TRUE), envir = marco)
  invisible(NULL)
}

.info_dbi_corrida <- function(conexion) {
  if (!is.null(.CONTEXTO_SENAS$conexion) &&
      identical(conexion, .CONTEXTO_SENAS$conexion)) {
    return(.CONTEXTO_SENAS$info)
  }
  DBI::dbGetInfo(conexion)
}

.info_senas_conexion_dbi <- function(conexion) {
  tryCatch(.info_dbi_corrida(conexion), error = function(e) list())
}

.senas_conexion_dbi <- function(conexion) {
  informacion <- .info_senas_conexion_dbi(conexion)
  nombres <- names(informacion)
  normalizar <- function(x) {
    .minusculas_ascii(gsub("[^A-Za-z0-9]", "", as.character(x)))
  }
  nombres_norm <- normalizar(nombres)
  campos_norm <- c(
    "dbmsname", "databasename", "databaseproductname", "dbms",
    "drivername", "driver", "sourcename", "servername", "server",
    "url", "jdbcurl", "databaseproductversion", "dbversion", "version"
  )
  sensibles <- grepl(
    "password|passwd|credential|secret|token|user(name)?|uid|pwd",
    nombres_norm, perl = TRUE
  )
  posiciones <- which(nombres_norm %in% campos_norm & !sensibles)
  textos <- c(
    class(conexion),
    attr(class(conexion), "package", exact = TRUE),
    unlist(informacion[posiciones], use.names = FALSE)
  )
  if (inherits(conexion, "JDBCConnection") &&
      requireNamespace("rJava", quietly = TRUE)) {
    metadata <- tryCatch({
      java_con <- tryCatch(conexion@jc, error = function(e) NULL)
      if (is.null(java_con)) NULL else {
        rJava::.jcall(java_con, "Ljava/sql/DatabaseMetaData;", "getMetaData")
      }
    }, error = function(e) NULL)
    if (!is.null(metadata)) {
      textos <- c(
        textos,
        tryCatch(rJava::.jcall(
          metadata, "Ljava/lang/String;", "getDatabaseProductName"
        ), error = function(e) NA_character_),
        tryCatch(rJava::.jcall(
          metadata, "Ljava/lang/String;", "getDriverName"
        ), error = function(e) NA_character_),
        tryCatch(rJava::.jcall(
          metadata, "Ljava/lang/String;", "getDatabaseProductVersion"
        ), error = function(e) NA_character_)
      )
    }
  }
  textos <- as.character(textos)
  .minusculas_ascii(paste(textos[nzchar(textos) & !is.na(textos)], collapse = " "))
}

# `odbc` publica la version de SQL Server como `db.version` (por ejemplo,
# `16.00.4265`). No se consulta al motor: si el controlador no la entrega, la
# version queda desconocida y se usa la regla conservadora del prefijo.
.version_servidor_sqlserver_dbi <- function(conexion) {
  senas <- .senas_conexion_dbi(conexion)
  if (!grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas,
    perl = TRUE, useBytes = TRUE
  )) return(NA_real_)
  informacion <- tryCatch(.info_dbi_corrida(conexion), error = function(e) NULL)
  if (!is.list(informacion)) return(NA_real_)
  nombres <- names(informacion)
  normalizar <- function(x) .minusculas_ascii(gsub("[^A-Za-z0-9]", "", x))
  normalizados <- normalizar(nombres)
  posiciones <- which(normalizados %in% c(
    "dbversion", "databaseproductversion", "version"
  ))
  valores <- c(
    if ("db.version" %in% nombres) informacion[["db.version"]] else NULL,
    unlist(informacion[posiciones], use.names = FALSE)
  )
  for (valor in as.character(valores)) {
    if (is.na(valor) || !nzchar(trimws(valor))) next
    captura <- regexec("^[[:space:]]*([0-9]+)(?:\\.[0-9]+)?", valor)
    partes <- regmatches(valor, captura)[[1L]]
    if (length(partes) == 2L) {
      salida <- suppressWarnings(as.numeric(partes[[2L]]))
      if (is.finite(salida)) return(salida)
    }
  }
  NA_real_
}

.es_oracle_dbi <- function(conexion) {
  grepl("oracle", .senas_conexion_dbi(conexion), fixed = TRUE, useBytes = TRUE)
}

# El orden de los candidatos sale de las senas del motor, pero la palabra final
# la tiene la sonda: adivinar por el nombre de la clase es una heuristica, y
# una heuristica no puede decidir si una consulta obligatoria se puede armar.
.orden_dialectos_dbi <- function(conexion) {
  dialectos <- .dialectos_dbi()
  senas <- .senas_conexion_dbi(conexion)
  reconocidos <- vapply(dialectos, function(dialecto) {
    !is.na(dialecto$patron) && grepl(dialecto$patron, senas, perl = TRUE)
  }, logical(1L))
  c(names(dialectos)[reconocidos], names(dialectos)[!reconocidos])
}

.resolver_dialecto_dbi <- function(conexion, sql_forma, dialecto, presupuesto) {
  dialectos <- .dialectos_dbi()
  if (!identical(dialecto, "auto")) {
    return(list(
      dialecto = dialectos[[dialecto]], sondas = character(),
      motivo = "Declarado por el usuario en `dialecto`; no se sonde\u00f3 el motor.",
      declarado = TRUE
    ))
  }
  sondas <- character()
  presupuesto_bloqueado <- FALSE
  for (nombre in .orden_dialectos_dbi(conexion)) {
    candidato <- dialectos[[nombre]]
    if (identical(nombre, "portable")) break
    sql <- candidato$limitar(sql_forma, 1L, 0)
    if (is.null(sql)) next
    sondas <- c(sondas, sql)
    resultado <- .consultar_dbi(
      conexion, sql, presupuesto, etapa = "sonda_dialecto"
    )
    presupuesto_bloqueado <- presupuesto_bloqueado ||
      .consulta_bloqueada_por_presupuesto_dbi(resultado, presupuesto)
    if (resultado$ok) {
      return(list(
        dialecto = candidato, sondas = sondas, declarado = FALSE,
        motivo = paste0(
          "El motor acept\u00f3 la sonda de cero filas del dialecto `", nombre, "`."
        )
      ))
    }
    if (isTRUE(presupuesto$agotado)) break
  }
  list(
    dialecto = dialectos$portable, sondas = sondas, declarado = FALSE,
    motivo = if (presupuesto_bloqueado) {
      .motivo_presupuesto_dbi(presupuesto)
    } else {
      paste(
        "Ning\u00fan dialecto de l\u00edmite conocido pas\u00f3 la sonda; las filas se acotan",
        "en el cliente con dbSendQuery() y dbFetch(n)."
      )
    }
  )
}

# ---- Consultas -----------------------------------------------------------

.texto_tabla_dbi <- function(tabla) {
  texto <- tryCatch(as.character(tabla), error = function(e) character())
  if (!length(texto)) texto <- tryCatch(format(tabla), error = function(e) "")
  paste(texto, collapse = ".")
}

.info_conexion_dbi <- function(conexion) {
  info <- tryCatch(.info_dbi_corrida(conexion), error = function(e) {
    list(no_disponible = .mensaje_motor(e))
  })
  list(
    clase_conexion = class(conexion),
    informacion_dbi = info
  )
}

.es_conexion_dbi <- function(conexion) {
  isTRUE(tryCatch(
    inherits(conexion, "DBIConnection"), error = function(e) FALSE
  ))
}

.conexion_valida_dbi <- function(conexion) {
  tryCatch(
    isTRUE(DBI::dbIsValid(conexion)),
    error = function(e) {
      isTRUE(tryCatch({
        DBI::dbGetInfo(conexion)
        TRUE
      }, error = function(e) FALSE))
    }
  )
}

# `filas >= 0` usa la via portable: el motor prepara el resultado y R lee solo
# las filas pedidas. Es la unica forma de acotar sin clausula de dialecto.
.consultar_dbi <- function(conexion, sql, presupuesto = NULL, filas = -1L,
                           etapa = "consulta") {
  finalizar <- function(salida, medicion) {
    salida <- .adjuntar_medicion_dbi(salida, medicion)
    .registrar_falla_consulta_dbi(salida, presupuesto)
    salida
  }
  if (!.gastar_dbi(presupuesto)) {
    return(finalizar(list(
      ok = FALSE, datos = NULL, motivo = .motivo_presupuesto_dbi(presupuesto)
    ), .medicion_consulta_vacia_dbi(etapa)))
  }
  medicion <- .iniciar_consulta_dbi(presupuesto, etapa)
  if (filas < 0) {
    salida <- tryCatch(
      list(ok = TRUE, datos = .marcar_utf8_tabla(
        .traer_consulta_dbi(conexion, sql)
      ), motivo = NA_character_),
      error = function(e) {
        if (inherits(e, "lupa_error_transaccion_dbi")) .detener(e)
        list(ok = FALSE, datos = NULL, motivo = .mensaje_motor(e),
             sqlstate = .sqlstate_dbi(e))
      }
    )
    return(finalizar(
      salida, .terminar_consulta_dbi(medicion, salida$datos)
    ))
  }
  resultado <- NULL
  on.exit(
    if (!is.null(resultado)) .limpiar_consulta_dbi(resultado, conexion),
    add = TRUE
  )
  salida <- tryCatch({
    resultado <- .enviar_consulta_dbi(conexion, sql)
    list(ok = TRUE, datos = .marcar_utf8_tabla(
      .traer_filas_dbi(resultado, n = filas, conexion)
    ), motivo = NA_character_)
  }, error = function(e) {
    if (inherits(e, "lupa_error_transaccion_dbi")) .detener(e)
    list(ok = FALSE, datos = NULL, motivo = .mensaje_motor(e),
         sqlstate = .sqlstate_dbi(e))
  })
  finalizar(
    salida, .terminar_consulta_dbi(medicion, salida$datos)
  )
}

# Recorre el texto UNA vez. La version anterior armaba en cada caracter el
# resto entero del texto (`paste(caracteres[i:limite])`), le corria la expresion
# del numero, pedia `tail()` de la salida y la hacia crecer con `c()`: cuadratica
# en el largo de la consulta, y se llamaba sobre cada fila de
# `pg_stat_statements` y, en `.adjuntar_derrame_sql_dbi()`, sobre cada fila del
# SQL una vez POR consulta medida. Medido con 4807 filas en
# `pg_stat_statements`: una tabla de una columna y 23 filas tardaba 47 s con
# `instrumentar = TRUE` y 3,6 s sin el, el 90 % aca. La salida es la misma -se
# comparo contra la version anterior sobre cada consulta del catalogo-: solo
# se busca un numero donde puede empezar uno, en una ventana que se agranda si
# el numero la llena.
.normalizar_sql_derrame_dbi <- function(sql) {
  if (is.null(sql) || length(sql) != 1L || is.na(sql)) return(NA_character_)
  texto <- sub(";+[[:space:]]*$", "", as.character(sql))
  caracteres <- strsplit(texto, "", fixed = TRUE)[[1L]]
  limite <- length(caracteres)
  salida <- character(limite)
  n_salida <- 0L
  # El primer caracter del ultimo elemento de la salida: lo unico que la regla
  # del numero mira de lo anterior.
  primero_anterior <- ""
  literal <- 0L
  i <- 1L
  es_borde <- function(valor) !grepl("[A-Za-z0-9_$]", valor, perl = TRUE)
  borde <- es_borde(caracteres)
  puede_empezar <- grepl("^[-+0-9.]$", caracteres, perl = TRUE)
  patron_numero <- "^(?:[-+]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][-+]?[0-9]+)?)"
  numero_en <- function(i) {
    ancho <- 64L
    repeat {
      hasta <- min(limite, i + ancho - 1L)
      resto <- paste(caracteres[i:hasta], collapse = "")
      captura <- regmatches(resto, regexpr(patron_numero, resto, perl = TRUE))
      # Lo que queda de la ventana despues del numero tiene que alcanzar para
      # saber que no sigue: "1234e" cortado en la `e` casaria "1234" y en el
      # texto entero "1234e+12".
      if (!length(captura) || hasta == limite ||
          .nchar_texto_seguro(captura)[[1L]] <= hasta - i + 1L - 4L) {
        return(captura)
      }
      ancho <- ancho * 4L
    }
  }
  while (i <= limite) {
    actual <- caracteres[[i]]
    if (identical(actual, "\"")) {
      inicio <- i
      i <- i + 1L
      while (i <= limite) {
        if (identical(caracteres[[i]], "\"") &&
            i < limite && identical(caracteres[[i + 1L]], "\"")) {
          i <- i + 2L
        } else if (identical(caracteres[[i]], "\"")) {
          i <- i + 1L
          break
        } else {
          i <- i + 1L
        }
      }
      n_salida <- n_salida + 1L
      salida[[n_salida]] <- paste(caracteres[inicio:(i - 1L)], collapse = "")
      primero_anterior <- "\""
      next
    }
    if (identical(actual, "'")) {
      literal <- literal + 1L
      i <- i + 1L
      while (i <= limite) {
        if (identical(caracteres[[i]], "'") && i < limite &&
            identical(caracteres[[i + 1L]], "'")) {
          i <- i + 2L
        } else if (identical(caracteres[[i]], "'")) {
          i <- i + 1L
          break
        } else {
          i <- i + 1L
        }
      }
      n_salida <- n_salida + 1L
      salida[[n_salida]] <- paste0("$", literal)
      primero_anterior <- "$"
      next
    }
    if (puede_empezar[[i]] && (i == 1L || es_borde(primero_anterior))) {
      captura <- numero_en(i)
      if (length(captura) == 1L && nzchar(captura)) {
        siguiente <- i + .nchar_texto_seguro(captura)[[1L]]
        if (siguiente > limite || borde[[siguiente]]) {
          literal <- literal + 1L
          n_salida <- n_salida + 1L
          salida[[n_salida]] <- paste0("$", literal)
          primero_anterior <- "$"
          i <- siguiente
          next
        }
      }
    }
    n_salida <- n_salida + 1L
    salida[[n_salida]] <- actual
    primero_anterior <- actual
    i <- i + 1L
  }
  gsub("[[:space:]]+", " ",
       trimws(paste(salida[seq_len(n_salida)], collapse = "")))
}

.estadisticas_derrame_postgresql_dbi <- function(conexion) {
  sql <- paste(
    "SELECT queryid, query, calls, temp_blks_read, temp_blks_written",
    "FROM pg_stat_statements",
    # Las consultas de esta corrida las ejecuta este usuario en esta base: lo
    # demas del catalogo no se puede atribuir y solo agrega filas que leer.
    "WHERE userid = (SELECT oid FROM pg_roles WHERE rolname = current_user)",
    "AND dbid = (SELECT oid FROM pg_database",
    "WHERE datname = current_database())",
    "AND (query ILIKE '%COUNT(DISTINCT%'",
    "OR query ILIKE '%AS frecuencia%'",
    "OR query ILIKE '%frecuencia%'",
    "OR query ILIKE '%lupa_mediana%'",
    "OR query ILIKE '%PERCENTILE_CONT%')"
  )
  datos <- tryCatch(
    .traer_consulta_dbi(conexion, sql),
    error = function(e) NULL
  )
  if (is.null(datos) || !all(c(
    "queryid", "query", "calls", "temp_blks_read", "temp_blks_written"
  ) %in% names(datos))) {
    return(NULL)
  }
  # El texto normalizado NO se calcula aca sobre todo el catalogo: la pareja
  # antes/despues se arma por `queryid`, y el texto solo hace falta para las
  # filas que esta ventana movio. Ver `.finalizar_instrumentacion_derrame_dbi()`.
  datos
}

.normalizar_consultas_derrame_dbi <- function(datos, filas = seq_len(nrow(datos))) {
  if (is.null(datos$query_normalizada)) {
    datos$query_normalizada <- rep(NA_character_, nrow(datos))
  }
  faltan <- filas[is.na(datos$query_normalizada[filas])]
  if (length(faltan)) {
    datos$query_normalizada[faltan] <- vapply(
      datos$query[faltan], .normalizar_sql_derrame_dbi, character(1L),
      USE.NAMES = FALSE
    )
  }
  datos
}

.iniciar_instrumentacion_derrame_dbi <- function(conexion, presupuesto,
                                                  exacto = TRUE) {
  estado <- list(
    estado = "no_solicitado", disponible = FALSE,
    fuente = NA_character_, motivo = NA_character_, antes = NULL,
    despues = NULL, consultas = NULL
  )
  if (!isTRUE(exacto)) {
    estado$motivo <- paste(
      "La estrategia de distintos no emite `COUNT(DISTINCT)` exacto."
    )
  } else if (is.null(presupuesto) || !isTRUE(presupuesto$instrumentar)) {
    estado$estado <- "no_medido"
    estado$motivo <- paste(
      "La instrumentaci\u00f3n est\u00e1 apagada; DBI no mide bloques temporales."
    )
  } else if (!grepl(.regex_sin_caja("postgres|pqconnection"),
                    .senas_conexion_dbi(conexion), perl = TRUE)) {
    estado$estado <- "no_disponible"
    estado$motivo <- paste(
      "El controlador no fue reconocido como PostgreSQL; no se puede",
      "consultar una estad\u00edstica de bloques temporales portable."
    )
  } else {
    antes <- .estadisticas_derrame_postgresql_dbi(conexion)
    if (is.null(antes)) {
      estado$estado <- "no_disponible"
      estado$motivo <- paste(
        "El servidor no expone `pg_stat_statements` o la credencial no puede",
        "leer sus bloques temporales."
      )
    } else {
      estado$estado <- "observando"
      estado$disponible <- TRUE
      estado$fuente <- "pg_stat_statements"
      estado$antes <- antes
    }
  }
  if (!is.null(presupuesto)) presupuesto$derrame <- estado
  estado
}

.finalizar_instrumentacion_derrame_dbi <- function(conexion, presupuesto) {
  if (is.null(presupuesto)) return(invisible(NULL))
  estado <- presupuesto$derrame
  if (!identical(estado$estado, "observando")) return(invisible(NULL))
  despues <- .estadisticas_derrame_postgresql_dbi(conexion)
  if (is.null(despues)) {
    estado$estado <- "no_disponible"
    estado$disponible <- FALSE
    estado$motivo <- paste(
        "La lectura final de `pg_stat_statements` fall\u00f3; no se publica el",
      "derrame porque no se puede separar esta corrida."
    )
    presupuesto$derrame <- estado
    return(invisible(NULL))
  }
  estado$despues <- despues
  antes <- estado$antes
  consultas <- list()
  tiene_queryid <- all(c("queryid") %in% names(antes)) &&
    all(c("queryid") %in% names(despues))
  clave_queryid <- function(x) {
    valor <- tryCatch(as.character(x), error = function(e) NA_character_)
    if (length(valor) != 1L || is.na(valor) || !nzchar(valor)) NA_character_ else valor
  }
  duplicados_texto <- function(datos) {
    claves <- datos$query_normalizada
    any(!is.na(claves) & nzchar(claves) & duplicated(claves))
  }
  # Las claves se leen UNA vez: se recorrian enteras por cada fila de
  # `despues`, cuadratico en el tamano de `pg_stat_statements`.
  claves_antes <- if (tiene_queryid) {
    vapply(antes$queryid, clave_queryid, character(1L), USE.NAMES = FALSE)
  } else character()
  claves_despues <- if (tiene_queryid) {
    vapply(despues$queryid, clave_queryid, character(1L), USE.NAMES = FALSE)
  } else character()
  if (!tiene_queryid) {
    antes <- .normalizar_consultas_derrame_dbi(antes)
    despues <- .normalizar_consultas_derrame_dbi(despues)
  }
  hay_ambiguedad_sin_queryid <- !tiene_queryid &&
    (duplicados_texto(antes) || duplicados_texto(despues))
  # Un `queryid` repetido -la misma consulta de otro usuario, de otra base o
  # anidada- o ausente no se puede emparejar. Antes, si habia UNO repetido en
  # todo el catalogo, ninguna fila se emparejaba: cada una quedaba sin "antes"
  # y sus llamadas y bloques de TODA la historia del servidor se publicaban
  # como de esta ventana. Medido: 712 consultas "observadas" y
  # 5333 llamadas en una corrida que emitio cinco. La fila que no se puede
  # emparejar no se atribuye; las demas si.
  ambiguas <- if (tiene_queryid) {
    unique(c(claves_antes[duplicated(claves_antes)],
             claves_despues[duplicated(claves_despues)]))
  } else character()
  ambiguas <- ambiguas[!is.na(ambiguas)]
  hay_ambiguedad_queryid <- length(ambiguas) > 0L
  # Solo pueden entrar las filas cuyas llamadas crecieron en la ventana -la
  # condicion de abajo descartaba las otras despues de normalizarlas- y solo
  # esas se normalizan.
  candidatas <- seq_len(nrow(despues))
  previa <- rep(NA_integer_, nrow(despues))
  if (tiene_queryid) {
    previa <- match(claves_despues, claves_antes, incomparables = NA)
    llamadas_despues_todas <- vapply(
      seq_len(nrow(despues)), function(i) .numero_dbi(despues$calls[[i]]),
      numeric(1L)
    )
    llamadas_antes_todas <- vapply(seq_along(previa), function(i) {
      if (is.na(previa[[i]])) 0 else .numero_dbi(antes$calls[[previa[[i]]]])
    }, numeric(1L))
    delta <- llamadas_despues_todas - llamadas_antes_todas
    atribuibles <- !is.na(claves_despues) & !(claves_despues %in% ambiguas)
    candidatas <- which(atribuibles & !is.na(delta) & delta >= 1)
  }
  despues <- .normalizar_consultas_derrame_dbi(despues, candidatas)
  for (i in candidatas) {
    clave <- despues$query_normalizada[[i]]
    if (is.na(clave) || !nzchar(clave)) next
    indices_previos <- if (tiene_queryid) {
      if (is.na(previa[[i]])) integer() else previa[[i]]
    } else if (!hay_ambiguedad_sin_queryid) {
      which(!is.na(antes$query_normalizada) & antes$query_normalizada == clave)
    } else integer()
    previo <- if (length(indices_previos) == 1L) {
      antes[indices_previos, , drop = FALSE]
    } else antes[FALSE, , drop = FALSE]
    llamadas_antes <- if (nrow(previo)) .numero_dbi(previo$calls[[1L]]) else 0
    llamadas_despues <- .numero_dbi(despues$calls[[i]])
    leidos_antes <- if (nrow(previo)) .numero_dbi(previo$temp_blks_read[[1L]]) else 0
    escritos_antes <- if (nrow(previo)) .numero_dbi(previo$temp_blks_written[[1L]]) else 0
    delta_llamadas <- llamadas_despues - llamadas_antes
    delta_leidos <- .numero_dbi(despues$temp_blks_read[[i]]) - leidos_antes
    delta_escritos <- .numero_dbi(despues$temp_blks_written[[i]]) - escritos_antes
    # El contador puede incluir otra sesion o llamada concurrente. Se publica
    # el agregado de la ventana y ese limite de atribucion queda explicito.
    if (!isTRUE(delta_llamadas >= 1) || !is.finite(delta_leidos) ||
        !is.finite(delta_escritos) || delta_leidos < 0 || delta_escritos < 0) {
      next
    }
    consultas[[length(consultas) + 1L]] <- list(
      query_normalizada = clave, derrame = delta_leidos > 0 || delta_escritos > 0,
      bloques_temporales_leidos = delta_leidos,
      bloques_temporales_escritos = delta_escritos,
      llamadas_en_ventana = delta_llamadas
    )
  }
  if (!length(consultas)) {
    estado$estado <- "no_disponible"
    estado$disponible <- FALSE
    estado$motivo <- if (hay_ambiguedad_sin_queryid || hay_ambiguedad_queryid) {
      paste(
        "`pg_stat_statements` tiene varias entradas para el mismo texto SQL",
        "normalizado y no se pudo atribuir cada fila por `queryid`; no se",
        "publica el derrame."
      )
    } else {
      paste(
        "`pg_stat_statements` no devolvi\u00f3 una pareja atribuible por `queryid`",
        "para esta corrida; no se publica el derrame."
      )
    }
  } else {
    estado$estado <- "medido"
    estado$consultas <- consultas
    llamadas <- sum(vapply(consultas, function(x) x$llamadas_en_ventana,
                           numeric(1L)))
    estado$motivo <- paste(
      "Los bloques temporales se publican como agregado sobre el texto SQL",
      "normalizado; `llamadas_en_ventana` =", llamadas,
      "y puede incluir otra sesi\u00f3n o llamada concurrente."
    )
  }
  presupuesto$derrame <- estado
  invisible(NULL)
}

.publicar_derrame_dbi <- function(presupuesto) {
  estado <- if (is.null(presupuesto)) NULL else presupuesto$derrame
  if (is.null(estado)) {
    return(list(
      disponible = FALSE, estado = "no_disponible", fuente = NA_character_,
      motivo = "No se pudo iniciar la instrumentaci\u00f3n de derrame.",
      consultas_observadas = 0L, consultas_con_derrame = 0L,
      bloques_temporales_leidos = NA_real_,
      bloques_temporales_escritos = NA_real_, llamadas_en_ventana = NA_real_
    ))
  }
  consultas <- estado$consultas
  if (is.null(consultas)) consultas <- list()
  derrames <- vapply(consultas, function(x) isTRUE(x$derrame), logical(1L))
  leidos <- if (length(consultas)) sum(vapply(
    consultas, function(x) x$bloques_temporales_leidos, numeric(1L)
  )) else NA_real_
  escritos <- if (length(consultas)) sum(vapply(
    consultas, function(x) x$bloques_temporales_escritos, numeric(1L)
  )) else NA_real_
  llamadas <- if (length(consultas)) sum(vapply(
    consultas, function(x) x$llamadas_en_ventana, numeric(1L)
  )) else NA_real_
  list(
    disponible = identical(estado$estado, "medido"),
    estado = estado$estado,
    fuente = estado$fuente,
    motivo = estado$motivo,
    consultas_observadas = as.integer(length(consultas)),
    consultas_con_derrame = as.integer(sum(derrames)),
    bloques_temporales_leidos = leidos,
    bloques_temporales_escritos = escritos,
    llamadas_en_ventana = llamadas
  )
}

# Oracle, DB2, Firebird y Snowflake pliegan a mayusculas los identificadores.
# El alias va comillado para que el motor lo respete, y la comparacion se hace
# sin distinguir caja para que un motor que lo pliegue igual no invente un
# motivo falso.
.campo_resultado_dbi <- function(datos, campo) {
  nombres <- names(datos)
  if (!length(nombres)) return(NA_integer_)
  posicion <- .indice_nombre(campo, nombres)
  if (is.na(posicion)) {
    posicion <- match(
      .normalizacion_minusculas_vector(.nombres_para_operar(campo)),
      .normalizacion_minusculas_vector(.nombres_para_operar(nombres))
    )
  }
  posicion
}

.valor_campo_dbi <- function(datos, campo) {
  if (is.null(datos) || !nrow(datos)) {
    return(list(
      ok = FALSE, valor = NULL,
      motivo = "La consulta no devolvi\u00f3 ninguna fila."
    ))
  }
  posicion <- .campo_resultado_dbi(datos, campo)
  if (is.na(posicion)) {
    return(list(ok = FALSE, valor = NULL, motivo = paste0(
      "La consulta no devolvi\u00f3 el campo `", campo, "`; devolvi\u00f3 ",
      paste0("`", names(datos), "`", collapse = ", "), "."
    )))
  }
  valores <- datos[[posicion]]
  if (!length(valores)) {
    return(list(ok = FALSE, valor = NULL, motivo = paste0(
      "El campo `", campo, "` volvi\u00f3 vac\u00edo."
    )))
  }
  list(ok = TRUE, valor = valores[[1L]], motivo = NA_character_)
}

# El mismo motor que pliega los alias pliega los nombres de columna. Lo que el
# usuario escribio en `orden_muestra` se resuelve contra la grafia que devuelve
# el motor, sin distinguir caja, y se sigue usando la del motor.
.resolver_columnas_dbi <- function(pedidas, campos) {
  posicion <- .indice_nombre(pedidas, campos)
  faltan <- is.na(posicion)
  if (any(faltan)) {
    posicion[faltan] <- match(
      .normalizacion_minusculas_vector(.nombres_para_operar(pedidas[faltan])),
      .normalizacion_minusculas_vector(.nombres_para_operar(campos))
    )
  }
  posicion
}

.escalar_dbi <- function(conexion, sql, campo, presupuesto = NULL,
                         etapa = "consulta") {
  resultado <- .consultar_dbi(conexion, sql, presupuesto, etapa = etapa)
  if (!resultado$ok) {
    return(.adjuntar_medicion_dbi(
      list(ok = FALSE, valor = NULL, motivo = resultado$motivo), resultado
    ))
  }
  .adjuntar_medicion_dbi(.valor_campo_dbi(resultado$datos, campo), resultado)
}

# Habia dos funciones con cuerpos identicos para la misma pregunta -esta y
# `.bit64_disponible()` en columnas.R- y una tercera forma distinta en
# `.hay_paquete()`. Tres puntos de verdad para "esta bit64?": cambiar el
# criterio en uno y olvidar el otro es cuestion de tiempo. Queda uno solo.
.bit64_disponible_dbi <- function() .bit64_disponible()

.numero_dbi <- function(valor) {
  if (is.null(valor) || !length(valor)) return(NA_real_)
  if (inherits(valor, "integer64")) {
    return(suppressWarnings(as.numeric(valor[[1L]])))
  }
  suppressWarnings(as.numeric(valor[[1L]]))
}

# El limite donde un `double` deja de representar enteros exactamente. Debajo de
# el, `numeric` y `integer64` guardan el mismo numero y `integer64` no compra
# nada; encima, el `double` ya perdio digitos y `integer64` es la unica forma de
# conservarlos.
.MAX_ENTERO_EXACTO_DBI <- 2^53

# La misma frontera para un `integer64`, escrita una vez: si cada valor cabe en
# un doble sin perderse -valor absoluto menor que 2^53-. La usan el resumen en
# memoria (`.resumen_integer64()`) y el recorrido por bloques de
# `perfilar_dbi()`. `NA` para un `NA`.
.integer64_exacto_en_doble <- function(x) {
  limite <- bit64::as.integer64(.MAX_ENTERO_EXACTO_DBI)
  x > -limite & x < limite
}

.MOTIVO_INTEGER64_FUERA_DE_PRECISION_DBI <- paste(
  # Lleva `.FRAGMENTO_ENTERO_64_DBI`, que la corroboracion reconoce.
  "La columna es un entero de 64 bits con alg\u00fan valor de valor absoluto de al",
  "menos 2^53, que un doble no representa con exactitud: m\u00ednimo, m\u00e1ximo,",
  "media, n_ceros, n_negativos y desv\u00edo no se publican como calculados, y la",
  "mediana s\u00f3lo cuando su valor no depende de uno de esos valores.",
  "n_distintos y la moda se cuentan sobre el valor exacto."
)

# Un `integer64` no se opera con `min()`, `max()`, `mean()` ni la resta de base:
# leen sus bits como si fueran un doble. El driver lo entrega asi para todo
# BIGINT de PostgreSQL -`bigserial`, la clave por omision- y para todo INTEGER de
# SQLite que no entra en 32 bits -marcas de tiempo en milisegundos, cedulas-, y
# la via por bloques publicaba `minimo = 4.94e-324` con estado `calculado`. Por
# debajo de 2^53 el doble representa el entero exacto y se opera como doble; si
# algun valor llega a 2^53, no hay doble que lo sostenga y quien llama declara
# las magnitudes `no_disponible` con este motivo, como la via SQL.
.integer64_como_doble_dbi <- function(x) {
  if (!inherits(x, "integer64")) return(list(ok = TRUE, valores = x))
  if (!.bit64_disponible()) {
    return(list(ok = FALSE, motivo = paste(
      "requiere_bit64: la columna lleg\u00f3 como entero de 64 bits y el paquete",
      "bit64 no est\u00e1 disponible para operarla."
    )))
  }
  exactos <- .integer64_exacto_en_doble(x)
  if (any(!is.na(exactos) & !exactos)) {
    return(list(ok = FALSE, motivo = .MOTIVO_INTEGER64_FUERA_DE_PRECISION_DBI))
  }
  list(ok = TRUE, valores = as.numeric(x))
}

# Ninguna columna decide la clase de un campo de toda la tabla. `rbind()` toma
# la clase de la primera fila: una `media` `integer64` -la via por bloques sobre
# un BIGINT- volvia `integer64` la columna `media` de `resumen_tabla$columnas`
# entera y truncaba a entero las medias de las columnas dobles (0,5604 se
# publicaba 0). Las magnitudes son dobles y se convierten en cada fila ANTES de
# unirlas: despues ya es tarde. Un `integer64` que el doble no sostiene no llega
# hasta aca -lo retiene su via con el motivo-; si llegara, sale `NA`, nunca un
# numero truncado.
.CAMPOS_MAGNITUD_RESUMEN_DBI <- c(
  "prop_faltantes", "tasa_distintos", "minimo", "maximo", "media", "mediana",
  "desvio"
)

.fila_magnitudes_dobles_dbi <- function(fila) {
  for (campo in intersect(.CAMPOS_MAGNITUD_RESUMEN_DBI, names(fila))) {
    valor <- fila[[campo]]
    if (is.null(valor) || length(valor) != 1L) next
    if (inherits(valor, "integer64")) {
      como_doble <- .integer64_como_doble_dbi(valor)
      fila[[campo]] <- if (isTRUE(como_doble$ok)) {
        como_doble$valores
      } else NA_real_
    } else if (is.numeric(valor) || is.logical(valor)) {
      fila[[campo]] <- as.numeric(valor)
    }
  }
  fila
}

.entero_exacto_grande_dbi <- function(texto) {
  if (is.na(texto) || !grepl("^[+-]?[0-9]+$", texto)) return(FALSE)
  # La comparacion se hace sobre el texto para no perder el digito justo al
  # convertirlo: `as.numeric("9007199254740993")` ya devuelve ...992.
  digitos <- sub("^[+-]", "", texto)
  digitos <- sub("^0+(?=[0-9])", "", digitos, perl = TRUE)
  nchar(digitos) > 16L ||
    (nchar(digitos) == 16L && digitos > "9007199254740992")
}

# Un conteo sale `numeric`, salvo que sea tan grande que un `double` ya no lo
# represente y el motor lo haya entregado de una forma que si lo conserva
# -texto, o `integer64`-.
#
# La version anterior devolvia `integer64` para cualquier conteo cuando `bit64`
# estaba instalado, incluido un 20. Eso no agregaba precision -el double ya era
# exacto- y agregaba tres problemas medidos:
#
#  1. La clase del mismo campo dependia de si el usuario tenia `bit64`, que es
#     un `Suggests`.
#  2. `perfilar()` devolvia `integer` para `n_distintos` y `perfilar_dbi()`
#     devolvia `integer64`: dos puertas del mismo paquete en desacuerdo sobre el
#     mismo campo.
#  3. Lo peor: un perfil guardado con `bit64` presente y leido donde no esta
#     muestra `9.881313e-323` donde midio `20`, sin error y sin aviso, y suma
#     como si fuera un numero. Informar como medido algo que no lo es, en el
#     paquete cuyo argumento es justamente ese.
#
# El caso donde `integer64` si compra exactitud queda intacto, y para un conteo
# significa una tabla de mas de nueve mil billones de filas.
.conteo_dbi <- function(valor) {
  if (is.null(valor) || !length(valor)) return(NA_real_)
  primero <- valor[[1L]]
  if (inherits(valor, "integer64")) {
    if (is.na(primero)) return(NA_real_)
    texto <- format(primero, scientific = FALSE, trim = TRUE)
    if (.entero_exacto_grande_dbi(texto)) return(primero)
    return(suppressWarnings(as.numeric(primero)))
  }
  texto <- if (is.character(valor)) as.character(primero) else NA_character_
  if (!is.na(texto) && .entero_exacto_grande_dbi(texto) &&
      .bit64_disponible_dbi()) {
    return(bit64::as.integer64(texto))
  }
  numero <- suppressWarnings(as.numeric(primero))
  if (!length(numero) || is.na(numero)) return(NA_real_)
  numero
}

# Si el conteo que se guarda representa el numero del motor sin perder digitos.
# Tiene que contestar sobre lo que `.conteo_dbi()` guarda y no sobre otra cosa:
# antes decia FALSE para un conteo entregado como texto por encima de 2^53, que
# es justamente el caso donde si se guarda exacto. El paquete se declaraba menos
# preciso de lo que era, que es el error simetrico del que importa, pero error
# igual.
.conteo_exacto_dbi <- function(valor) {
  if (is.null(valor) || !length(valor)) return(FALSE)
  primero <- valor[[1L]]
  if (inherits(valor, "integer64")) {
    if (is.na(primero)) return(FALSE)
    return(.bit64_disponible_dbi())
  }
  if (is.character(valor)) {
    texto <- as.character(primero)
    if (.entero_exacto_grande_dbi(texto)) return(.bit64_disponible_dbi())
  }
  numero <- .numero_dbi(valor)
  is.finite(numero) && abs(numero) <= .MAX_ENTERO_EXACTO_DBI
}

.metadatos_sql_dbi <- function(alcance = "tabla_completa", universo = NA,
                               tamano_muestra = NA, fraccion = NA_real_,
                               metodo = NA_character_,
                               error_esperado = NA_character_, lote = NA_integer_,
                               columnas_compartidas = NA_integer_,
                               id_consulta = NA_integer_,
                               estrategia_solicitada = NA_character_,
                               estrategia_resuelta = NA_character_,
                               estado_estrategia = NA_character_) {
  list(
    alcance = alcance,
    universo = universo,
    tamano_muestra = tamano_muestra,
    fraccion = fraccion,
    metodo = metodo,
    error_esperado = error_esperado,
    lote = lote,
    columnas_compartidas = columnas_compartidas,
    id_consulta = id_consulta,
    estrategia_solicitada = estrategia_solicitada,
    estrategia_resuelta = estrategia_resuelta,
    estado_estrategia = estado_estrategia
  )
}

.agregar_metadatos_estrategia_distintos_dbi <- function(metadatos,
                                                        estrategia) {
  if (is.null(estrategia)) return(metadatos)
  metadatos$estrategia_solicitada <- estrategia$estrategia_solicitada
  metadatos$estrategia_resuelta <- estrategia$estrategia_resuelta
  metadatos$estado_estrategia <- estrategia$estado
  metadatos
}

.mezclar_metadatos_dbi <- function(base, extra = NULL) {
  if (is.null(extra)) return(base)
  for (nombre in names(extra)) {
    if (!is.null(extra[[nombre]])) base[[nombre]] <- extra[[nombre]]
  }
  base
}

# ---- Registro de auditoria ----------------------------------------------

.memoria_trabajo_sql_dbi <- function(estado, metadatos) {
  if (length(estado) != 1L || is.na(estado)) return(NA_character_)
  estado <- as.character(estado)
  if (estado %in% c(
    "no_solicitado", "omitida", "omitido_por_costo",
    "omitido_por_privacidad", "no_disponible", "no_aplica",
    "sin_valores", "no_medido"
  )) {
    return(NA_character_)
  }

  alcance <- if (is.null(metadatos$alcance)) {
    NA_character_
  } else {
    as.character(metadatos$alcance)
  }
  fraccion <- if (is.null(metadatos$fraccion)) {
    NA_real_
  } else {
    suppressWarnings(as.numeric(metadatos$fraccion))
  }
  if (length(alcance) == 1L && identical(alcance, "muestra") &&
      length(fraccion) == 1L && isTRUE(is.finite(fraccion)) &&
      fraccion < 1) {
    return("acotado")
  }

  # Una muestra saturada tiene alcance `muestra`, pero fraccion = 1: su cap no
  # acota el universo y por eso continua en R3 junto a las tablas completas.
  alcance_tabla <- length(alcance) == 1L && (
    alcance %in% c("tabla_completa", "tabla_muestreada") ||
      (identical(alcance, "muestra") &&
         length(fraccion) == 1L && isTRUE(fraccion == 1))
  )
  if (!alcance_tabla) return(NA_character_)

  metodo <- if (is.null(metadatos$metodo)) {
    NA_character_
  } else {
    as.character(metadatos$metodo)
  }
  if (length(metodo) != 1L || is.na(metodo)) {
    return(NA_character_)
  }
  if (!metodo %in% names(.REGISTRO_MEMORIA_TRABAJO_DBI)) {
    # En la muestra saturada `random_limit` ya no limita filas: el agregado
    # plano recorre la tabla completa y conserva su estado acotado de una
    # pasada. No se agrega al registro general de metodos de muestra; fuera de
    # este caso, un metodo no registrado sigue publicando `NA`.
    if (identical(alcance, "muestra") && isTRUE(fraccion == 1) &&
        identical(metodo, "random_limit")) {
      return("acotado")
    }
    return(NA_character_)
  }
  unname(.REGISTRO_MEMORIA_TRABAJO_DBI[[metodo]])
}

.registro_sql_dbi <- function(columna, metricas, estado, motivo, sql,
                              metadatos = NULL, medicion = NULL,
                              etapa = NULL) {
  if (is.null(metadatos)) metadatos <- .metadatos_sql_dbi()
  if (is.null(medicion)) {
    medicion <- .medicion_consulta_vacia_dbi()
  }
  metricas <- as.character(metricas)
  # Los caminos que publican una muestra pueden llegar aca desde un agregado
  # consolidado, una omision o el spool. La regla vive en un solo clasificador;
  # esta guarda evita que una de esas salidas vuelva a copiar un estado/error de
  # grupo antes de escribir la fila publica.
  if (length(metricas) && !is.null(metadatos$muestreo_regla)) {
    clasificaciones <- lapply(metricas, function(nombre) {
      .clasificar_metrica_muestreo_dbi(
        nombre, metadatos$muestreo_regla, metadatos$fraccion_regla
      )
    })
    conocidas <- vapply(
      clasificaciones, function(x) isTRUE(x$conocida), logical(1L)
    )
    if (all(conocidas)) {
      metadatos$error_esperado <- vapply(
        clasificaciones, `[[`, character(1L), "error_esperado"
      )
      estado_registro <- rep_len(as.character(estado), length(metricas))
      estados_medidos <- estado_registro %in% c(
        "calculado", "estimado", "estimado_motor", "estimado_catalogo",
        "observado", "observado_muestra", "garantizado"
      )
      estados_muestra <- vapply(
        clasificaciones, `[[`, character(1L), "estado"
      )
      estado_registro[estados_medidos & !is.na(estados_muestra)] <-
        estados_muestra[estados_medidos & !is.na(estados_muestra)]
      estado <- estado_registro
      motivo_registro <- rep_len(as.character(motivo), length(metricas))
      motivos_muestra <- vapply(
        clasificaciones, `[[`, character(1L), "motivo"
      )
      completar <- estados_medidos & is.na(motivo_registro) &
        !is.na(motivos_muestra)
      motivo_registro[completar] <- motivos_muestra[completar]
      motivo <- motivo_registro
    }
  }
  etapa_publicada <- if (!is.null(medicion$etapa) &&
                         length(medicion$etapa) == 1L &&
                         !is.na(medicion$etapa)) {
    medicion$etapa
  } else if (!is.null(etapa) && length(etapa) == 1L && !is.na(etapa)) {
    etapa
  } else if (identical(estado, "no_solicitado")) {
    "no_solicitado"
  } else {
    "resumen_sql"
  }
  medicion_valor <- function(nombre, defecto) {
    valor <- medicion[[nombre]]
    if (is.null(valor) || !length(valor)) defecto else valor
  }
  data.frame(
    columna = rep_len(as.character(columna), length(metricas)),
    metrica = metricas,
    estado = rep_len(as.character(estado), length(metricas)),
    motivo = rep_len(as.character(motivo), length(metricas)),
    sql = rep_len(as.character(sql), length(metricas)),
    alcance = rep_len(as.character(metadatos$alcance), length(metricas)),
    universo = rep_len(metadatos$universo, length(metricas)),
    tamano_muestra = rep_len(metadatos$tamano_muestra, length(metricas)),
    fraccion = rep_len(as.numeric(metadatos$fraccion), length(metricas)),
    metodo = rep_len(as.character(metadatos$metodo), length(metricas)),
    error_esperado = rep_len(as.character(metadatos$error_esperado), length(metricas)),
    lote = rep_len(as.integer(metadatos$lote), length(metricas)),
    columnas_compartidas = rep_len(
      as.integer(metadatos$columnas_compartidas), length(metricas)
    ),
    id_consulta = rep_len(
      as.integer(metadatos$id_consulta), length(metricas)
    ),
    estrategia_solicitada = rep_len(
      as.character(metadatos$estrategia_solicitada), length(metricas)
    ),
    estrategia_resuelta = rep_len(
      as.character(metadatos$estrategia_resuelta), length(metricas)
    ),
    estado_estrategia = rep_len(
      as.character(metadatos$estado_estrategia), length(metricas)
    ),
    duracion_ms = rep_len(
      as.numeric(medicion_valor("duracion_ms", NA_real_)), length(metricas)
    ),
    n_filas_resultado = rep_len(
      as.numeric(medicion_valor("n_filas_resultado", NA_real_)), length(metricas)
    ),
    bytes_resultado_r = rep_len(
      as.numeric(medicion_valor("bytes_resultado_r", NA_real_)), length(metricas)
    ),
    cpu_ms = rep_len(
      as.numeric(medicion_valor("cpu_ms", NA_real_)), length(metricas)
    ),
    consulta_id = rep_len(
      as.integer(medicion_valor("consulta_id", NA_integer_)), length(metricas)
    ),
    etapa = rep_len(as.character(etapa_publicada), length(metricas)),
    derrame = rep_len(NA, length(metricas)),
    bloques_temporales_leidos = rep_len(NA_real_, length(metricas)),
    bloques_temporales_escritos = rep_len(NA_real_, length(metricas)),
    fuente_derrame = rep_len(NA_character_, length(metricas)),
    llamadas_en_ventana = rep_len(NA_real_, length(metricas)),
    memoria_trabajo = vapply(
      rep_len(as.character(estado), length(metricas)),
      .memoria_trabajo_sql_dbi, character(1L), metadatos = metadatos
    ),
    stringsAsFactors = FALSE
  )
}

.adjuntar_derrame_sql_dbi <- function(sql, derrame) {
  if (!is.data.frame(sql)) return(sql)
  if (!"derrame" %in% names(sql)) sql$derrame <- NA
  if (!"bloques_temporales_leidos" %in% names(sql)) {
    sql$bloques_temporales_leidos <- NA_real_
  }
  if (!"bloques_temporales_escritos" %in% names(sql)) {
    sql$bloques_temporales_escritos <- NA_real_
  }
  if (!"fuente_derrame" %in% names(sql)) {
    sql$fuente_derrame <- NA_character_
  }
  if (!"llamadas_en_ventana" %in% names(sql)) {
    sql$llamadas_en_ventana <- NA_real_
  }
  if (is.null(derrame) || !identical(derrame$estado, "medido") ||
      !length(derrame$consultas)) {
    return(sql)
  }
  # El SQL de esta corrida se normaliza una vez, no una vez por consulta medida.
  normalizadas <- vapply(
    sql$sql, .normalizar_sql_derrame_dbi, character(1L), USE.NAMES = FALSE
  )
  for (consulta in derrame$consultas) {
    indices <- which(normalizadas == consulta$query_normalizada)
    if (!length(indices)) next
    sql$derrame[indices] <- isTRUE(consulta$derrame)
    sql$bloques_temporales_leidos[indices] <-
      consulta$bloques_temporales_leidos
    sql$bloques_temporales_escritos[indices] <-
      consulta$bloques_temporales_escritos
    sql$fuente_derrame[indices] <- derrame$fuente
    sql$llamadas_en_ventana[indices] <- consulta$llamadas_en_ventana
  }
  sql
}

.registrar_resultado_dbi <- function(registros, columna, metricas, resultado,
                                     motivo_exito = NA_character_,
                                     metadatos = NULL) {
  metadatos <- .mezclar_metadatos_dbi(metadatos, resultado$metadatos)
  if (is.null(metadatos)) metadatos <- .metadatos_sql_dbi()
  estado <- if (!isTRUE(resultado$ok)) {
    "no_disponible"
  } else if (!is.null(resultado$estado)) {
    resultado$estado
  } else {
    "calculado"
  }
  motivo <- if (isTRUE(resultado$ok)) motivo_exito else resultado$motivo
  sql <- if (is.null(resultado$sql)) NA_character_ else resultado$sql
  c(registros, list(.registro_sql_dbi(
    columna, metricas, estado, motivo, sql, metadatos, medicion = resultado
  )))
}

.marcar_nivel_sql_dbi <- function(sql) {
  if (!is.data.frame(sql) || !"consulta_id" %in% names(sql)) return(sql)
  nivel <- rep.int(1L, nrow(sql))
  medidos <- which(!is.na(sql$consulta_id))
  if (length(medidos)) {
    grupos <- .dividir_por_bytes(medidos, as.character(sql$consulta_id[medidos]))
    for (indices in grupos) {
      if (length(indices) > 1L) nivel[indices[-1L]] <- 2L
    }
  }
  sql$nivel <- as.integer(nivel)
  if ("memoria_trabajo" %in% names(sql)) {
    sql <- sql[c(setdiff(names(sql), "memoria_trabajo"), "memoria_trabajo")]
  }
  sql
}

.cobertura_dbi_vacia <- function() {
  data.frame(
    bloque = character(), elemento = character(), estado = character(),
    motivo = character(), como_resolverlo = character(), sql = character(),
    stringsAsFactors = FALSE
  )
}

# La clasificacion personal de la muestra no alcanza a justificar valores del
# resumen SQL cuando la muestra quedo recortada. Se reutiliza `cobertura` para
# decirlo junto a cada cifra de valor, sin copiar el valor que se protege.
.cobertura_clasificacion_personal_parcial_dbi <- function(resumen, perfil) {
  vacia <- .cobertura_dbi_vacia()
  salida_vacia <- list(columnas = character(), cobertura = vacia)
  if (!is.list(resumen) || !is.list(perfil) ||
      !is.data.frame(resumen$columnas) || !is.data.frame(perfil$columnas)) {
    return(salida_vacia)
  }
  total <- .numero_corroboracion_dbi(resumen$meta$filas)
  observado <- .numero_corroboracion_dbi(perfil$meta$filas_analizadas)
  if (length(total) != 1L || !is.finite(total) || total < 0 ||
      length(observado) != 1L || !is.finite(observado) || observado < 0 ||
      observado >= total) {
    return(salida_vacia)
  }
  tope <- as.character(perfil$meta$tope_que_mando)
  if (length(tope) != 1L || is.na(tope) ||
      !(tope %in% c("celdas", "bytes"))) {
    # Una muestra elegida por el usuario tambien puede ser parcial, pero no es
    # la degradacion que esta cobertura debe atribuir a los topes de lectura.
    return(salida_vacia)
  }
  campos <- intersect(
    c("moda", "minimo", "maximo", "media", "mediana",
      "minimo_exacto", "maximo_exacto"),
    names(resumen$columnas)
  )
  if (!length(campos) || !nrow(resumen$columnas)) return(salida_vacia)
  utilizable <- function(valor) {
    if (length(valor) != 1L || is.na(valor)) return(FALSE)
    if (is.character(valor)) return(nzchar(valor))
    TRUE
  }
  tiene_cifra <- vapply(seq_len(nrow(resumen$columnas)), function(i) {
    any(vapply(campos, function(campo) {
      utilizable(resumen$columnas[[campo]][[i]])
    }, logical(1L)))
  }, logical(1L))
  if (!any(tiene_cifra)) return(salida_vacia)
  nombres <- as.character(resumen$columnas$columna[tiene_cifra])
  nombres <- nombres[!is.na(nombres) & nzchar(nombres)]
  if (!length(nombres)) return(salida_vacia)
  texto_filas <- function(valor) format(
    valor, scientific = FALSE, trim = TRUE
  )
  registros <- list()
  for (i in which(tiene_cifra)) {
    columna <- as.character(resumen$columnas$columna[[i]])
    campos_columna <- campos[vapply(campos, function(campo) {
      utilizable(resumen$columnas[[campo]][[i]])
    }, logical(1L))]
    for (campo in campos_columna) {
      registros[[length(registros) + 1L]] <- .registro_cobertura_dbi(
        "resumen_tabla", paste0(columna, "::", campo), "degradado",
        paste0(
          "La clasificaci\u00f3n autom\u00e1tica de datos personales cubri\u00f3 s\u00f3lo ",
        texto_filas(observado), " de ", texto_filas(total),
        if (total == 1L) " fila. La cifra SQL de `" else " filas. La cifra SQL de `", columna, "::", campo,
          "` cubre la tabla completa y no se puede justificar con esa",
          " clasificaci\u00f3n parcial."
        ),
        paste(
          "Aumentar `max_celdas_muestra` o `max_bytes_muestra`, o usar `Inf`,",
          "para que la clasificaci\u00f3n cubra las filas publicadas."
        ),
        NA_character_
      )
    }
  }
  list(
    columnas = unique(nombres),
    cobertura = if (length(registros)) do.call(rbind, registros) else vacia
  )
}

.registro_cobertura_dbi <- function(bloque, elemento, estado, motivo,
                                    como_resolverlo, sql = NA_character_) {
  data.frame(
    bloque = as.character(bloque), elemento = as.character(elemento),
    estado = as.character(estado), motivo = as.character(motivo),
    como_resolverlo = as.character(como_resolverlo), sql = as.character(sql),
    stringsAsFactors = FALSE
  )
}

.cobertura_politicas_muestra_dbi <- function(
    aplicabilidad = NULL, columnas_opcionales = character(),
    sentinelas_numericos = c(-9, -99, -999, -9999, 999)) {
  politicas <- character()
  if (!is.null(aplicabilidad) && length(aplicabilidad)) {
    politicas <- c(politicas, "aplicabilidad")
  }
  if (length(columnas_opcionales)) {
    politicas <- c(politicas, "columnas_opcionales")
  }
  declarados <- tryCatch(
    .sentinelas_numericos_declarados(sentinelas_numericos),
    error = function(e) numeric()
  )
  if (length(declarados)) {
    politicas <- c(politicas, "sentinelas_numericos")
  }
  if (!length(politicas)) return(.cobertura_dbi_vacia())
  do.call(rbind, lapply(politicas, function(argumento) {
    .registro_cobertura_dbi(
      "resumen_tabla", argumento, "degradado",
      paste0(
        "El resumen SQL no honra `", argumento,
        "`; sus agregados se calculan sin esa pol\u00edtica, mientras",
        " `perfil_muestra` si la aplica. Los dos bloques pueden publicar",
        " medidas distintas sobre las mismas filas."
      ),
      paste0(
        "Usar `perfil_muestra` para esta pol\u00edtica. Para que",
        " `resumen_tabla` la honre, traducir `", argumento,
        "` al SQL del motor en una futura implementaci\u00f3n."
      )
    )
  }))
}

# `resumen_tabla` no pasa por `perfilar()`: sus cifras salen del SQL, y ahi
# `media`, `mediana` y `desvio` de una columna declarada en `columnas_codigo`
# se publicaban mientras `perfil_muestra` las callaba. Se aplica la MISMA
# declaracion, ya validada por `.normalizar_columnas_codigo()`: esas tres
# cifras quedan en `NA` y la cobertura lo declara por columna. Ver
# `.resumen_codigo_declarado()`.
.aplicar_columnas_codigo_dbi <- function(resumen, columnas_codigo) {
  if (!length(columnas_codigo) || !is.list(resumen) ||
      !is.data.frame(resumen$columnas) || !nrow(resumen$columnas)) {
    return(resumen)
  }
  columnas <- resumen$columnas
  declaradas <- .nombres_para_operar(as.character(columnas$columna)) %in%
    .nombres_para_operar(columnas_codigo)
  campos <- intersect(c("media", "mediana", "desvio"), names(columnas))
  if (!any(declaradas) || !length(campos)) return(resumen)
  # La fila de cobertura va en toda columna declarada con resumen numerico, no
  # solo donde habia una cifra que borrar: por el camino del spool el resumen
  # sale del perfil de la muestra, que ya la callo, y la fila no se escribia.
  con_cifras <- declaradas & Reduce(`|`, lapply(
    intersect(c(campos, "minimo", "maximo"), names(columnas)),
    function(campo) !is.na(columnas[[campo]])
  ))
  for (campo in campos) columnas[[campo]][declaradas] <- NA
  resumen$columnas <- columnas
  if (any(con_cifras)) {
    nuevas <- do.call(rbind, lapply(
      as.character(columnas$columna[con_cifras]), function(columna) {
        .registro_cobertura_dbi(
          "resumen_tabla", columna, "no_aplica",
          paste(
            "La columna se declar\u00f3 en `columnas_codigo`: es un c\u00f3digo y no",
            "una magnitud, as\u00ed que `media`, `mediana` y `desvio` no se",
            "publican. `minimo`, `maximo` y los conteos describen sus valores."
          ),
          paste(
            "Si la columna es una magnitud y no un c\u00f3digo, quitarla de",
            "`columnas_codigo`."
          )
        )
      }
    ))
    cobertura <- resumen$cobertura
    resumen$cobertura <- if (is.null(cobertura) || !nrow(cobertura)) {
      nuevas
    } else {
      rbind(cobertura, nuevas)
    }
    rownames(resumen$cobertura) <- NULL
  }
  resumen
}

.agregar_cobertura_politicas_muestra_dbi <- function(
    resultado, aplicabilidad = NULL, columnas_opcionales = character(),
    sentinelas_numericos = c(-9, -99, -999, -9999, 999),
    columnas_codigo = character(), lectura_convertida = NULL,
    cobertura_texto = NULL) {
  if (!is.list(resultado) || !is.list(resultado$resumen_tabla)) {
    return(resultado)
  }
  # Las columnas que se leyeron convertidas en el motor, con la expresion: ver
  # `.lectura_convertida_dbi()`. Solo cuando hubo alguna.
  if (NROW(lectura_convertida)) {
    resultado$resumen_tabla$meta$lectura_convertida <- lectura_convertida
  }
  # Los tres caminos de `perfilar_dbi()` terminan aca, asi que la declaracion
  # de codigos se aplica en un solo lugar para los tres.
  resultado$resumen_tabla <- .aplicar_columnas_codigo_dbi(
    resultado$resumen_tabla, columnas_codigo
  )
  nuevas <- .cobertura_politicas_muestra_dbi(
    aplicabilidad = aplicabilidad,
    columnas_opcionales = columnas_opcionales,
    sentinelas_numericos = sentinelas_numericos
  )
  # El texto que el controlador entrega en latin1 -bajo una sesion que no es
  # UTF-8, o configurado asi-: ver `.texto_del_controlador_dbi()`.
  if (NROW(cobertura_texto)) nuevas <- rbind(nuevas, cobertura_texto)
  if (!nrow(nuevas)) return(resultado)
  cobertura <- resultado$resumen_tabla$cobertura
  resultado$resumen_tabla$cobertura <- if (is.null(cobertura) || !nrow(cobertura)) {
    nuevas
  } else {
    rbind(cobertura, nuevas)
  }
  rownames(resultado$resumen_tabla$cobertura) <- NULL
  resultado
}

# Compara solo mediciones exactas de `n_validos` y `n_distintos`. Si salen de
# consultas distintas y se contradicen, la explicacion defendible es que la
# tabla cambio entre ambas sentencias: cada valor puede ser correcto dentro de
# su propio grupo de consistencia. No se usa esta funcion para aplicar una cota.
.cobertura_cambio_entre_consultas_dbi <- function(columnas, sql) {
  vacia <- .cobertura_dbi_vacia()
  if (!is.data.frame(columnas) || !is.data.frame(sql) ||
      !all(c("columna", "n_validos", "n_distintos") %in% names(columnas)) ||
      !all(c("columna", "metrica", "estado", "consulta_id", "sql") %in%
             names(sql))) {
    return(vacia)
  }
  nombres <- as.character(columnas$columna)
  exacto <- function(columna, metrica) {
    indices <- which(
      .nombres_para_operar(as.character(sql$columna)) %in%
        .nombres_para_operar(columna) &
        as.character(sql$metrica) == metrica &
        as.character(sql$estado) == "calculado" &
        !is.na(sql$consulta_id)
    )
    if (!length(indices)) return(NULL)
    indice <- indices[[length(indices)]]
    list(
      id = sql$consulta_id[[indice]],
      sentencia = sql$sql[[indice]]
    )
  }
  numero <- function(x) {
    valor <- .numero_dbi(x)
    if (length(valor) != 1L || is.na(valor) || !is.finite(valor)) {
      return(NA_real_)
    }
    valor
  }
  texto_valor <- function(x) {
    format(x, scientific = FALSE, trim = TRUE)
  }
  texto_sentencia <- function(registro) {
    sentencia <- as.character(registro$sentencia)
    if (!length(sentencia) || is.na(sentencia)) sentencia <- "no conservada"
    paste0("sentencia ", as.character(registro$id), ": ", sentencia)
  }
  registros <- lapply(seq_len(nrow(columnas)), function(i) {
    columna <- nombres[[i]]
    validos <- exacto(columna, "n_validos")
    distintos <- exacto(columna, "n_distintos")
    if (is.null(validos) || is.null(distintos)) return(NULL)
    id_validos <- as.character(validos$id)
    id_distintos <- as.character(distintos$id)
    if (!length(id_validos) || !length(id_distintos) ||
        is.na(id_validos) || is.na(id_distintos) ||
        identical(id_validos, id_distintos)) {
      return(NULL)
    }
    n_validos <- numero(columnas$n_validos[[i]])
    n_distintos <- numero(columnas$n_distintos[[i]])
    if (is.na(n_validos) || is.na(n_distintos) || n_distintos <= n_validos) {
      return(NULL)
    }
    motivo <- paste0(
      "No hubo lectura instant\u00e1nea de la tabla: `n_validos` = ",
      texto_valor(n_validos), " sali\u00f3 de ", texto_sentencia(validos),
      " y `n_distintos` = ", texto_valor(n_distintos), " sali\u00f3 de ",
      texto_sentencia(distintos), ". Ambos valores son exactos dentro de su",
      " sentencia, pero pertenecen a grupos de consistencia distintos y no se",
      " pueden comparar como una sola fotograf\u00eda. La diferencia es evidencia",
      " de que la tabla cambi\u00f3 durante la corrida; no se atribuye al motor ni",
      " al paquete."
    )
    .registro_cobertura_dbi(
      "consistencia", columna, "alcance_distinto", motivo,
      paste(
        "Repetir el perfil bajo una instant\u00e1nea o una transacci\u00f3n con el nivel",
        "de aislamiento que garantice una lectura consistente."
      ),
      NA_character_
    )
  })
  registros <- Filter(Negate(is.null), registros)
  if (!length(registros)) vacia else do.call(rbind, registros)
}

# `resumen_tabla` y `perfil_muestra` responden a la misma pregunta por caminos
# distintos. La muestra puede explicar que los valores ordinarios no coincidan,
# pero no explica una imposibilidad unilateral (por ejemplo, que una muestra
# tenga mas faltantes que la tabla completa) ni que uno de los caminos no pueda
# producir un valor. Esta separacion evita convertir una diferencia esperable de
# alcance en una acusacion contra el motor.
.METRICAS_CORROBORACION_DBI <- c(
  "media", "mediana", "minimo", "maximo", "desvio", "n_distintos",
  "n_faltantes", "n_ceros", "n_negativos", "moda", "frecuencia_moda"
)
.METRICAS_CORROBORACION_NUMERICAS_DBI <- c(
  "media", "mediana", "minimo", "maximo", "desvio"
)
.METRICAS_CORROBORACION_CONTEOS_DBI <- c(
  "n_distintos", "n_faltantes", "n_ceros", "n_negativos",
  "frecuencia_moda"
)
# Dos tolerancias, por lo que cada metrica es. `minimo`, `maximo`, la `mediana`
# y la moda son valores LEIDOS de la columna -uno, o el promedio de dos-: los dos
# caminos los tienen que dar iguales salvo la representacion del doble, y ahi
# vale `64 * eps`. Ensancharla escondia divergencias reales: el minimo de un
# entero de once cifras que cambio en una unidad difiere en 1e-11 relativo.
# `media` y `desvio` se ACUMULAN, y cada lado acumula con su algoritmo y en su
# orden: sobre 61 enteros de un millon, el `STDEV` de SQL Server da
# 31312.270967375953 y R 31312.270967376771 -2,6e-14 relativo, la de R es la
# exacta- y la corroboracion acusaba a la muestra. Medido en
# SQL Server con 5 semillas por magnitud, de 1e2 a 1e9: hasta 1,9e-13. Para esas
# dos, 1e-10 relativo: mil veces el error medido, y cinco ordenes por debajo de
# una diferencia real -la media de `{1e16, 1, -1e16}`, 0 contra 1/3, o el desvio
# de una pasada que se rompe con una media grande frente al ancho, 26,13 contra
# 27,18-, que siguen saliendo.
.TOLERANCIA_ABSOLUTA_CORROBORACION_DBI <- 1e-10
.TOLERANCIA_RELATIVA_CORROBORACION_DBI <- 64 * .Machine$double.eps
.TOLERANCIA_RELATIVA_ACUMULADA_CORROBORACION_DBI <- 1e-10
.METRICAS_ACUMULADAS_CORROBORACION_DBI <- c("media", "desvio")

.tolerancia_relativa_corroboracion_dbi <- function(metrica) {
  if (metrica %in% .METRICAS_ACUMULADAS_CORROBORACION_DBI) {
    .TOLERANCIA_RELATIVA_ACUMULADA_CORROBORACION_DBI
  } else {
    .TOLERANCIA_RELATIVA_CORROBORACION_DBI
  }
}

# Que metricas de cada columna calcularon `resumen_tabla` y `perfil_muestra` con
# la MISMA semantica. Solo esas se corroboran: una diferencia entre dos cifras
# que miden cosas distintas a proposito no es una divergencia del motor, del
# controlador ni de un snapshot, que es lo que el motivo de la divergencia
# enumera. Es una sola funcion para todas las razones, porque la propiedad es
# una: cerrarla solo para `columnas_codigo` dejaba abiertas otras cuatro
# puertas -tres declaraciones que el resumen SQL no honra y una guarda que no
# publica-, con `perfilar_coleccion()` subiendo la tabla a
# `alcance = "divergencias"`:
#
# * `columnas_codigo`: `media`, `mediana` y `desvio` no se calculan.
# * `columnas_opcionales`: `n_faltantes` se cuenta sobre las celdas presentes.
# * `aplicabilidad`: `n_faltantes` se cuenta sobre el universo aplicable; y si la
#   muestra dejo afuera valores presentes -fuera de la regla o donde no se pudo
#   decidir-, todas las metricas describen otro conjunto de valores.
# * `sentinelas_numericos` declarados: las metricas de magnitud de una columna
#   numerica se calculan sin los centinelas, si la muestra excluyo alguno. Un
#   no finito tambien se excluye y NO entra aca: esa divergencia es la que
#   `perfilar_dbi()` declara a proposito (`NaN` e infinitos).
# * El entero ancho desde 2^53: el resumen no publica sus metricas de
#   magnitud a proposito, y la muestra cuenta `n_ceros` y `n_negativos` exactos.
# * El `desvio` de un decimal que la muestra leyo como doble y no publico
#   (`decimal_doble`, ver `.tapar_desvio_decimal_doble_perfil_dbi()`): el del
#   resumen es el del tipo de la columna, el de la muestra el de los dobles.
#   Se lee de la declaracion de la muestra, no se deduce aca.
# * Lo que un lado no calculo, por construccion y no por lista de causas: una
#   metrica que `resumen_tabla$sql` declara `no_disponible` -el motor rechazo la
#   consulta sobre el tipo (`json`, `xml`, `point` de PostgreSQL; `text`,
#   `ntext`, `image`, `geography` de SQL Server), una guarda la retuvo, la cota
#   no se pudo sostener-, y en `perfil_muestra` la moda que `perfilar()` no pudo
#   contar -frecuencia `NA` sobre valores presentes: una columna de blobs- o
#   toda metrica de una columna compuesta, que `perfilar()` no analiza. Se
#   publicaban como `divergencia` (`faltante_un_lado`) y `perfilar_coleccion()`
#   subia la tabla a `alcance = "divergencias"` pidiendo releer bajo una
#   lectura consistente, que da lo mismo: un lado no dio un valor, y su motivo
#   ya esta publicado. Las excepciones son las causas que
#   la corroboracion existe para declarar, y se siguen comparando: un `NaN` o un
#   infinito que el motor cuenta y R no, y un valor que el motor guarda como
#   texto en una columna numerica (ver `.no_disponible_que_se_compara_dbi()`).
#
# Devuelve una fila por par columna-metrica con la causa, que se publica en
# `meta$corroboracion_bloques$no_comparadas`.
.no_comparables_corroboracion_dbi <- function(
    resumen, perfil, columnas_codigo = character(),
    columnas_opcionales = character(), aplicabilidad = NULL,
    sentinelas_numericos = NULL) {
  vacia <- data.frame(
    columna = character(), metrica = character(), causa = character(),
    stringsAsFactors = FALSE
  )
  if (!is.list(resumen) || !is.list(perfil) ||
      !is.data.frame(resumen$columnas) || !is.data.frame(perfil$columnas)) {
    return(vacia)
  }
  operar <- .nombres_para_operar
  codigos <- operar(as.character(columnas_codigo))
  opcionales <- operar(as.character(columnas_opcionales))
  con_aplicabilidad <- if (is.list(aplicabilidad) && length(aplicabilidad) &&
                           !is.null(names(aplicabilidad))) {
    operar(as.character(names(aplicabilidad)))
  } else character()
  sentinelas <- tryCatch(
    .sentinelas_numericos_declarados(sentinelas_numericos),
    error = function(e) numeric()
  )
  desvio_doble <- operar(as.character(
    if (is.list(perfil$meta)) {
      perfil$meta[["desvio_decimal_doble", exact = TRUE]]
    }
  ))
  magnitud <- c(
    "media", "mediana", "minimo", "maximo", "desvio", "n_ceros", "n_negativos"
  )
  sql <- resumen$sql
  campo <- function(columna, nombre) {
    .numero_corroboracion_dbi(.valor_corroboracion_dbi(
      perfil$columnas, columna, nombre
    ))
  }
  filas <- list()
  agregar <- function(columna, metricas, causa) {
    metricas <- intersect(metricas, .METRICAS_CORROBORACION_DBI)
    if (!length(metricas)) return(invisible(NULL))
    filas[[length(filas) + 1L]] <<- data.frame(
      columna = rep(columna, length(metricas)), metrica = metricas,
      causa = rep(causa, length(metricas)), stringsAsFactors = FALSE
    )
    invisible(NULL)
  }
  nombres <- unique(intersect(
    as.character(resumen$columnas$columna), as.character(perfil$columnas$columna)
  ))
  for (columna in nombres) {
    clave <- operar(columna)
    if (clave %in% codigos) {
      agregar(columna, c("media", "mediana", "desvio"), "columnas_codigo")
    }
    if (clave %in% opcionales) {
      agregar(columna, "n_faltantes", "columnas_opcionales")
    }
    if (clave %in% desvio_doble) {
      agregar(columna, "desvio", "decimal_doble")
    }
    if (clave %in% con_aplicabilidad) {
      fuera <- campo(columna, "n_presentes_fuera_de_aplicabilidad") +
        campo(columna, "n_presentes_en_aplicabilidad_indeterminada")
      agregar(
        columna,
        if (isTRUE(fuera == 0)) "n_faltantes" else .METRICAS_CORROBORACION_DBI,
        "aplicabilidad"
      )
    }
    if (length(sentinelas) &&
        .tipo_numerico_corroboracion_dbi(perfil$columnas, columna)) {
      no_finitos <- campo(columna, "n_nan") +
        campo(columna, "n_infinito_positivo") +
        campo(columna, "n_infinito_negativo")
      excluidos <- campo(columna, "n_valores_excluidos_resumen") - no_finitos
      if (!isTRUE(excluidos <= 0)) {
        agregar(columna, magnitud, "sentinelas_numericos")
      }
    }
    if (is.data.frame(sql) &&
        all(c("columna", "metrica", "estado", "motivo") %in% names(sql))) {
      propias <- operar(as.character(sql$columna)) %in% clave &
        as.character(sql$estado) == "no_disponible" &
        .es_motivo_entero_64_dbi(as.character(sql$motivo))
      if (any(propias)) {
        agregar(
          columna, unique(as.character(sql$metrica[propias])), "entero_64_bits"
        )
      }
      # La fila que la corroboracion leeria -la ultima comparable, como en
      # `.estado_corroborable_dbi()`-: si dice `no_disponible`, el resumen no
      # dio un valor para comparar.
      sin_valor <- vapply(.METRICAS_CORROBORACION_DBI, function(metrica) {
        indice <- .estado_corroborable_dbi(sql, columna, metrica)
        !is.null(indice) &&
          identical(as.character(sql$estado[[indice]]), "no_disponible") &&
          !.es_motivo_entero_64_dbi(as.character(sql$motivo[[indice]])) &&
          !.no_disponible_que_se_compara_dbi(as.character(sql$motivo[[indice]]))
      }, logical(1L))
      if (any(sin_valor)) {
        agregar(
          columna, .METRICAS_CORROBORACION_DBI[sin_valor],
          "no_disponible_en_resumen"
        )
      }
    }
    estado_cuantitativo <- .valor_corroboracion_dbi(
      perfil$columnas, columna, "estado_resumen_cuantitativo"
    )
    if (identical(as.character(estado_cuantitativo), "tipo_compuesto_no_analizado")) {
      agregar(columna, .METRICAS_CORROBORACION_DBI, "muestra_no_analiza_compuesta")
    } else {
      presentes <- campo(columna, "n") - campo(columna, "n_faltantes")
      frecuencia <- .valor_corroboracion_dbi(
        perfil$columnas, columna, "frecuencia_moda"
      )
      if (.es_na_corroboracion_dbi(frecuencia) && isTRUE(presentes > 0)) {
        agregar(columna, c("moda", "frecuencia_moda"), "moda_no_calculada_en_muestra")
      }
    }
  }
  if (!length(filas)) return(vacia)
  salida <- do.call(rbind, filas)
  # Una metrica que dos razones excluyen se publica una vez, con las dos.
  clave_par <- .clave_no_comparable_dbi(salida$columna, salida$metrica)
  causas <- tapply(salida$causa, factor(clave_par, levels = unique(clave_par)),
                   function(x) paste(unique(x), collapse = "; "))
  salida <- salida[!duplicated(clave_par), , drop = FALSE]
  salida$causa <- as.character(causas[clave_par[!duplicated(clave_par)]])
  rownames(salida) <- NULL
  salida
}

# Las causas de un `no_disponible` del resumen que la corroboracion SI compara,
# porque la diferencia es la que existe para declarar (`?perfilar_dbi`, "Lo que
# la corroboracion compara"): el motor respondio `NaN` o un infinito, que cuenta
# como valor donde R no, o devolvio algo que no se lee como numero -SQLite con
# texto en una columna numerica-. Se reconocen por el fragmento que escribe cada
# motivo, la misma regla para quien lo escribe y quien lo lee.
.FRAGMENTO_NAN_DBI <- "El motor respondi\u00f3 `NaN` para"
.FRAGMENTO_INFINITO_DBI <- "El motor respondi\u00f3 un infinito para"

.no_disponible_que_se_compara_dbi <- function(motivo) {
  motivo <- as.character(motivo)
  !is.na(motivo) & (
    grepl(.FRAGMENTO_NAN_DBI, motivo, fixed = TRUE, useBytes = TRUE) |
      grepl(.FRAGMENTO_INFINITO_DBI, motivo, fixed = TRUE, useBytes = TRUE) |
      grepl(.FRAGMENTO_NO_NUMERO_DBI, motivo, fixed = TRUE, useBytes = TRUE)
  )
}

.clave_no_comparable_dbi <- function(columna, metrica) {
  .clave_par_identificador(
    .nombres_para_operar(as.character(columna)), as.character(metrica),
    sep = "\u001f"
  )
}

.valor_corroboracion_dbi <- function(columnas, columna, metrica) {
  if (!is.data.frame(columnas) || !all(c("columna", metrica) %in% names(columnas))) {
    return(NULL)
  }
  indices <- which(.nombres_para_operar(as.character(columnas$columna)) %in%
                   .nombres_para_operar(columna))
  if (!length(indices)) return(NULL)
  columnas[[metrica]][[indices[[1L]]]]
}

# El motivo de una metrica de magnitud que el motor devolvio y no se pudo leer
# como numero, y su reconocimiento: una sola regla para quien lo escribe -la
# sonda de magnitud y las metricas basicas- y para la corroboracion, que lo usa
# como CAUSA de la divergencia.
.FRAGMENTO_NO_NUMERO_DBI <- "que no se pudo leer como n\u00famero"

.motivo_no_numero_dbi <- function(que, valor = "") {
  paste0(
    "El motor devolvi\u00f3 un valor para ", que, " ", .FRAGMENTO_NO_NUMERO_DBI,
    valor, ": probablemente la columna no es de la magnitud que estas ",
    "m\u00e9tricas suponen. No se publica como calculada."
  )
}

.es_motivo_no_numero_dbi <- function(motivo) {
  !is.na(motivo) & grepl(.FRAGMENTO_NO_NUMERO_DBI, motivo, fixed = TRUE)
}

# Que el motor guarda TEXTO en una columna numerica se MIDE, no se deduce de que
# una metrica no se pudo leer como numero: un `Inf` -un numero-
# hacia publicar "Causa medida: el motor guarda en esta columna valores que no
# son numeros" sobre una columna con cinco `real` y un `null`. En SQLite, que
# es el motor que admite texto en una columna de afinidad numerica, se cuenta
# con `typeof()`. Devuelve la frase que se agrega al motivo, o "" si no se midio
# texto: en los demas motores una columna numerica no puede guardarlo.
.FRAGMENTO_TEXTO_MEDIDO_DBI <- "guardados como texto o blob, medido con `typeof()`"

.texto_guardado_medido_dbi <- function(conexion, tabla_sql, columna_sql, alias,
                                       presupuesto = NULL) {
  if (!grepl("sqlite", .senas_conexion_dbi(conexion), fixed = TRUE,
             useBytes = TRUE)) {
    return("")
  }
  sql <- paste0(
    "SELECT SUM(CASE WHEN typeof(", columna_sql, ") IN ('text', 'blob') ",
    "THEN 1 ELSE 0 END) AS ", alias("n_texto"), " FROM ", tabla_sql
  )
  medido <- .escalar_dbi(
    conexion, sql, "n_texto", presupuesto, etapa = "tipos_guardados"
  )
  n <- if (isTRUE(medido$ok)) .numero_dbi(medido$valor) else NA_real_
  if (!isTRUE(n > 0)) return("")
  paste0(
    " La columna tiene ", format(n, scientific = FALSE, trim = TRUE),
    if (n == 1L) " valor " else " valores ", .FRAGMENTO_TEXTO_MEDIDO_DBI, "."
  )
}

.es_motivo_texto_medido_dbi <- function(motivo) {
  !is.na(motivo) & grepl(.FRAGMENTO_TEXTO_MEDIDO_DBI, motivo, fixed = TRUE, useBytes = TRUE)
}

# La causa de una divergencia que se puede MEDIR: el motor guarda en la columna
# valores que no son numeros -una de sus metricas de magnitud no se pudo leer
# como numero- y el controlador la entrego a la muestra como numerica. Medido
# con SQLite: una columna de afinidad INTEGER con dos `'abc'` daba
# en el resumen SQL `moda = "abc"` y en la muestra `moda = 0`, `minimo = 0` y una
# relacion aritmetica sobre las dos filas, porque RSQLite convierte a 0 el
# texto de una columna que tipa como numerica (con su aviso "mixed type"). La
# divergencia ya se declaraba, con una lista de causas posibles; ahora con la
# medida. Se declara y no se relee la columna como texto: la decision esta
# escrita en `?perfilar_dbi`. Medida de verdad: la causa exige
# el conteo de `typeof()` en el motivo -ver `.texto_guardado_medido_dbi()`-, y
# no solo que una magnitud no se haya podido leer.
.causa_divergencia_no_numero_dbi <- function(sql, columnas, columna) {
  if (!.tipo_numerico_corroboracion_dbi(columnas, columna)) return(NULL)
  if (!is.data.frame(sql) ||
      !all(c("columna", "estado", "motivo") %in% names(sql))) {
    return(NULL)
  }
  propias <- .nombres_para_operar(as.character(sql$columna)) %in%
    .nombres_para_operar(columna)
  if (!any(propias & as.character(sql$estado) == "no_disponible" &
           .es_motivo_no_numero_dbi(as.character(sql$motivo)) &
           .es_motivo_texto_medido_dbi(as.character(sql$motivo)))) {
    return(NULL)
  }
  paste(
    "Causa medida: el motor guarda en esta columna valores que no son",
    "n\u00fameros -`typeof()` cuenta valores guardados como texto o blob- y",
    "el controlador la entreg\u00f3 a la muestra como num\u00e9rica, as\u00ed que",
    "`perfil_muestra` describe esos valores ya convertidos por el controlador",
    "(RSQLite convierte a 0 el texto de una columna que tipa como num\u00e9rica, y",
    "lo avisa: \"mixed type\"). Las cifras de magnitud de `perfil_muestra` para",
    "esta columna no describen lo guardado."
  )
}

.tipo_numerico_corroboracion_dbi <- function(columnas, columna) {
  if (!is.data.frame(columnas) || !"tipo_inferido" %in% names(columnas)) {
    return(FALSE)
  }
  indices <- which(.nombres_para_operar(as.character(columnas$columna)) %in%
                   .nombres_para_operar(columna))
  if (!length(indices)) return(FALSE)
  .minusculas_ascii(as.character(columnas$tipo_inferido[[indices[[1L]]]])) %in%
    c("entero", "doble", "numero", "numerico", "integer", "double")
}

.estado_corroborable_dbi <- function(sql, columna, metrica) {
  if (!is.data.frame(sql) ||
      !all(c("columna", "metrica", "estado") %in% names(sql))) {
    return(NULL)
  }
  indices <- which(.nombres_para_operar(as.character(sql$columna)) %in%
    .nombres_para_operar(columna) &
    as.character(sql$metrica) == metrica)
  if (!length(indices)) return(NULL)
  no_medido <- c(
    "no_solicitado", "no_aplica", "omitida",
    "omitido_por_costo", "omitido_por_privacidad", "no_medido"
  )
  estados <- as.character(sql$estado[indices])
  comparables <- which(!is.na(estados) & !estados %in% no_medido)
  if (!length(comparables)) return(NULL)
  indices[[comparables[[length(comparables)]]]]
}

.es_na_corroboracion_dbi <- function(valor) {
  if (is.null(valor) || length(valor) != 1L) return(TRUE)
  resultado <- tryCatch(is.na(valor[[1L]]), error = function(e) FALSE)
  isTRUE(resultado)
}

# Un numero que llega como TEXTO publicado -la moda numerica- se escribio con la
# marca de `OutDec`, que el paquete conserva a proposito (`?perfilar`): se lee
# con esa misma marca. Con `OutDec = ","` la moda 2.5 se publica "2,5" en los dos
# bloques, `as.numeric()` daba `NA` en los dos y la corroboracion declaraba
# `divergencia` entre dos valores identicos.
#
# El texto se lee legible (`.texto_legible_recortado()`): la moda describe lo
# almacenado y puede ser una cadena sin marca que no es UTF-8 valido, que no es
# un numero en ninguna sesion y sobre la que `as.numeric()` aborta en una sesion
# UTF-8. El recorte no cambia nada: `as.numeric()` ya ignora los blancos.
.numero_corroboracion_dbi <- function(valor) {
  if (is.null(valor) || length(valor) != 1L) return(NA_real_)
  primero <- valor[[1L]]
  if (is.character(primero) || is.factor(primero)) {
    texto <- .texto_legible_recortado(primero)
    marca <- getOption("OutDec", ".")
    if (!is.na(texto) && is.character(marca) && length(marca) == 1L &&
        !identical(marca, ".")) {
      texto <- gsub(marca, ".", texto, fixed = TRUE)
    }
    return(suppressWarnings(as.numeric(texto)))
  }
  suppressWarnings(as.numeric(primero))
}

.texto_corroboracion_dbi <- function(valor) {
  if (.es_na_corroboracion_dbi(valor)) return("NA")
  if (is.numeric(valor) || inherits(valor, "integer64")) {
    numero <- .numero_corroboracion_dbi(valor)
    if (is.nan(numero)) return("NaN")
    if (is.infinite(numero)) return(if (numero > 0) "Inf" else "-Inf")
    return(format(numero, scientific = TRUE, digits = 17L, trim = TRUE))
  }
  as.character(valor[[1L]])
}

.valor_normalizado_corroboracion_dbi <- function(valor, numerico) {
  if (numerico) return(.numero_corroboracion_dbi(valor))
  if (is.null(valor) || !length(valor)) return(NA_character_)
  # El texto que identifica el valor, no el que imprime la sesion: un conteo llega
  # entero de un lado y doble del otro, y con `scipen = -9` `as.character()` daba
  # "12" contra "1.2e+01" -nueve divergencias falsas de nueve-.
  .texto_identidad(valor[[1L]])
}

.equivalentes_sentinela_real_dbi <- function(a, b, sentinelas) {
  if (is.null(a) || is.null(b) || length(a) != 1L || length(b) != 1L ||
      !length(sentinelas)) return(FALSE)
  # Una moda de texto se lee legible, como en `.numero_corroboracion_dbi()`: la
  # que es una cadena sin marca que no es UTF-8 valido abortaba `as.numeric()`
  # -y con el `perfilar_dbi()`- en una sesion UTF-8.
  legible <- function(v) {
    v <- v[[1L]]
    if (is.character(v)) .texto_legible_recortado(v) else v
  }
  a_num <- suppressWarnings(as.numeric(legible(a)))
  b_num <- suppressWarnings(as.numeric(legible(b)))
  if (!is.finite(a_num) || !is.finite(b_num)) return(FALSE)
  declarados <- suppressWarnings(as.numeric(sentinelas))
  declarados <- declarados[is.finite(declarados)]
  if (!length(declarados)) return(FALSE)
  any(vapply(declarados, function(declarado) {
    real <- .real_dbi_a_doble(declarado)
    corto <- .real_dbi_lectura_corta(real)
    representaciones <- c(declarado, real, corto)
    isTRUE(a_num %in% representaciones) &&
      isTRUE(b_num %in% representaciones)
  }, logical(1L)))
}

.comparar_celda_corroboracion_dbi <- function(
    a, b, numerico, relativa = .TOLERANCIA_RELATIVA_CORROBORACION_DBI) {
  faltante_a <- .es_na_corroboracion_dbi(a)
  faltante_b <- .es_na_corroboracion_dbi(b)
  if (xor(faltante_a, faltante_b)) {
    return(list(
      difiere = TRUE, motivo = "faltante_un_lado", delta = NA_real_
    ))
  }
  if (faltante_a && faltante_b) {
    return(list(
      difiere = FALSE, motivo = "faltante_en_ambos", delta = NA_real_
    ))
  }
  # Se comparan VALORES: dos textos iguales son el mismo valor, se lean o no
  # como numero. La moda de una columna de texto que el perfil infiere `doble`
  # -"3,75"- se comparaba como numero, daba `NA` en los dos lados y salia
  # `divergencia` con el motivo "valor no numerico en un lado", que tampoco era
  # cierto.
  # Solo entre textos: `as.character()` de un doble escribe 15 cifras y daria
  # por iguales dos dobles que no lo son.
  es_texto <- function(v) is.character(v[[1L]]) || is.factor(v[[1L]])
  if (es_texto(a) && es_texto(b) && identical(
    .valor_normalizado_corroboracion_dbi(a, FALSE),
    .valor_normalizado_corroboracion_dbi(b, FALSE)
  )) {
    return(list(difiere = FALSE, motivo = "igualdad_exacta", delta = NA_real_))
  }
  a <- .valor_normalizado_corroboracion_dbi(a, numerico)
  b <- .valor_normalizado_corroboracion_dbi(b, numerico)
  if (numerico) {
    if (is.na(a) && is.na(b)) {
      return(list(difiere = TRUE, motivo = "texto_distinto", delta = NA_real_))
    }
    if (is.na(a) || is.na(b)) {
      return(list(
        difiere = TRUE, motivo = "valor_no_numerico_un_lado", delta = NA_real_
      ))
    }
    if (is.infinite(a) || is.infinite(b)) {
      igual <- isTRUE(a == b)
      return(list(
        difiere = !igual,
        motivo = if (igual) "igualdad_exacta" else "infinito_distinto",
        delta = NA_real_
      ))
    }
    delta <- abs(a - b)
    escala <- max(abs(a), abs(b))
    limite <- .TOLERANCIA_ABSOLUTA_CORROBORACION_DBI + relativa * escala
    dentro <- is.finite(delta) && is.finite(limite) && delta <= limite
    return(list(
      difiere = !dentro,
      motivo = if (dentro) "dentro_de_tolerancia" else "fuera_de_tolerancia",
      delta = as.numeric(delta)
    ))
  }
  igual <- isTRUE(a == b)
  list(
    difiere = !igual,
    motivo = if (igual) "igualdad_exacta" else "texto_distinto",
    delta = NA_real_
  )
}

.contradiccion_muestra_corroboracion_dbi <- function(metrica, a, b) {
  if (metrica %in% .METRICAS_CORROBORACION_CONTEOS_DBI) {
    return(is.finite(a) && is.finite(b) && a < b)
  }
  if (identical(metrica, "minimo")) {
    return(is.finite(a) && is.finite(b) && a > b)
  }
  if (identical(metrica, "maximo")) {
    return(is.finite(a) && is.finite(b) && a < b)
  }
  FALSE
}

.cobertura_corroboracion_bloques_dbi <- function(
    resumen, perfil, protegidas = character(), columnas_codigo = character(),
    columnas_opcionales = character(), aplicabilidad = NULL,
    sentinelas_numericos = NULL) {
  vacia <- .cobertura_dbi_vacia()
  meta_vacia <- list(
    disponible = FALSE, estado = "no_disponible", filas_resumen = NA_real_,
    filas_muestra = NA_real_, fraccion = NA_real_, metricas =
      .METRICAS_CORROBORACION_DBI,
    motivo = "No hay dos bloques p\u00fablicos que comparar."
  )
  if (!is.list(resumen) || !is.list(perfil) ||
      !is.data.frame(resumen$columnas) || !is.data.frame(perfil$columnas)) {
    return(list(cobertura = vacia, meta = meta_vacia))
  }
  universo <- if (is.null(resumen$meta$universo)) NA_character_ else
    as.character(resumen$meta$universo)
  total <- .numero_corroboracion_dbi(resumen$meta$filas)
  observado <- .numero_corroboracion_dbi(perfil$meta$filas_analizadas)
  fraccion <- if (is.finite(total) && total > 0 && is.finite(observado)) {
    observado / total
  } else if (is.finite(total) && total == 0 && is.finite(observado) && observado == 0) {
    1
  } else {
    NA_real_
  }
  meta <- list(
    disponible = TRUE, estado = NA_character_, filas_resumen = total,
    filas_muestra = observado, fraccion = fraccion,
    metricas = .METRICAS_CORROBORACION_DBI,
    tolerancia = list(
      absoluta = .TOLERANCIA_ABSOLUTA_CORROBORACION_DBI,
      relativa = .TOLERANCIA_RELATIVA_CORROBORACION_DBI,
      relativa_acumulada = .TOLERANCIA_RELATIVA_ACUMULADA_CORROBORACION_DBI,
      metricas_acumuladas = .METRICAS_ACUMULADAS_CORROBORACION_DBI,
      criterio = paste(
        "|resumen_tabla - perfil_muestra| <= tolerancia_absoluta +",
        "tolerancia_relativa * max(|resumen_tabla|, |perfil_muestra|);",
        "en `media` y `desvio`, que cada lado acumula con su algoritmo,",
        "tolerancia_relativa_acumulada en lugar de tolerancia_relativa"
      )
    ),
    motivo = NA_character_, divergencias = 0L,
    no_comparadas = .no_comparables_corroboracion_dbi(
      NULL, NULL
    )
  )
  if (!identical(universo, "tabla_completa")) {
    meta$estado <- "no_comparable_por_universo"
    meta$motivo <- paste(
      "Los agregados SQL no tienen el mismo universo que la lectura del",
      "perfil: `universo = \"muestra_motor\"` puede seleccionar otra muestra.",
      "No se comparan dos subconjuntos como si fueran las mismas filas."
    )
    return(list(cobertura = vacia, meta = meta))
  }
  if (length(total) != 1L || !is.finite(total) || total < 0 ||
      length(observado) != 1L || !is.finite(observado) || observado < 0) {
    meta$estado <- "no_comparable_por_filas"
    meta$motivo <- paste(
          "No se pudo establecer cu\u00e1ntas filas cubre cada bloque; no se",
      "declara una divergencia num\u00e9rica sin esa evidencia."
    )
    return(list(cobertura = vacia, meta = meta))
  }
  completa <- isTRUE(total == observado)
  meta$estado <- if (completa) "comparacion_completa" else "muestra_parcial"
  meta$motivo <- if (completa) {
    "La muestra cubre el 100% de las filas; las diferencias se corroboran directamente."
  } else {
    paste(
      "La muestra cubre menos del 100%: las diferencias ordinarias de",
      "momentos, mediana, moda y conteos se atribuyen al muestreo y no se",
      "declaran. S\u00f3lo se declaran valores NA en un lado o contradicciones",
      "unilaterales imposibles para una submuestra."
    )
  }
  nombres <- intersect(
    as.character(resumen$columnas$columna),
    as.character(perfil$columnas$columna)
  )
  registros <- list()
  # Las comparaciones que DIFIEREN y no se declaran divergencia porque la
  # muestra es parcial. Se cuentan para no callarlas: el README promete que la
  # corroboracion "no calla que no coinciden", y con una muestra parcial la
  # cobertura salia vacia -medido: moda `a` 90 veces contra `b` 10 veces, cero
  # filas-. La regla de no llamarlas divergencia es correcta y se conserva; lo
  # que faltaba era decir que hubo diferencias que no se pudieron corroborar.
  no_corroboradas <- list()
  # Lo que `meta$criterio_comparacion` declara esperable no se llama
  # divergencia. El resumen SQL agrupa y ordena con el cotejamiento del motor y
  # el perfil de muestra compara byte a byte: sobre una columna `COLLATE NOCASE`
  # la corroboracion publicaba tres `divergencia` -`n_distintos` 5 contra 9, la
  # moda y su frecuencia- en el mismo objeto cuyo `meta` dice que esa diferencia
  # "es esperable, y no es un error de ninguno de los dos". Se reconoce solo la
  # forma que un cotejamiento puede producir: fundir valores -menos distintos
  # en el resumen SQL, y una moda mas frecuente-, o desempatar distinto una
  # moda con la misma frecuencia. Al reves es imposible y sigue siendo
  # divergencia. La via por bloques compara en R y no tiene esta excusa.
  esperables_cotejamiento <- list()
  por_cotejamiento <- !identical(resumen$meta$metodo, "dbfetch_bloques")
  explica_cotejamiento <- function(columna, metrica) {
    leer <- function(columnas, campo) {
      .numero_corroboracion_dbi(.valor_corroboracion_dbi(columnas, columna, campo))
    }
    distintos_sql <- leer(resumen$columnas, "n_distintos")
    distintos_muestra <- leer(perfil$columnas, "n_distintos")
    frecuencia_sql <- leer(resumen$columnas, "frecuencia_moda")
    frecuencia_muestra <- leer(perfil$columnas, "frecuencia_moda")
    funde <- isTRUE(is.finite(distintos_sql) && is.finite(distintos_muestra) &&
                      distintos_sql < distintos_muestra)
    frecuencias <- is.finite(frecuencia_sql) && is.finite(frecuencia_muestra)
    switch(
      metrica,
      n_distintos = funde,
      frecuencia_moda = funde && frecuencias &&
        frecuencia_sql > frecuencia_muestra,
      moda = funde || (frecuencias && frecuencia_sql == frecuencia_muestra),
      FALSE
    )
  }
  # Solo se corrobora lo que los dos bloques calcularon con la misma semantica:
  # ver `.no_comparables_corroboracion_dbi()`. Lo que la declaracion
  # `columnas_codigo` manda no calcular era la primera de esas razones (la
  # corroboracion corre antes de que `.aplicar_columnas_codigo_dbi()` borre
  # `media`, `mediana` y `desvio` del resumen SQL); las
  # demas declaraciones y la guarda del entero de 64 bits son la misma
  # propiedad. Lo que no se compara queda en
  # `meta$no_comparadas`, con su causa.
  no_comparadas <- .no_comparables_corroboracion_dbi(
    resumen, perfil, columnas_codigo = columnas_codigo,
    columnas_opcionales = columnas_opcionales, aplicabilidad = aplicabilidad,
    sentinelas_numericos = sentinelas_numericos
  )
  no_comparadas <- no_comparadas[
    !.nombres_para_operar(no_comparadas$columna) %in%
      .nombres_para_operar(protegidas), , drop = FALSE
  ]
  rownames(no_comparadas) <- NULL
  meta$no_comparadas <- no_comparadas
  claves_no_comparadas <- .clave_no_comparable_dbi(
    no_comparadas$columna, no_comparadas$metrica
  )
  for (columna in unique(nombres)) {
    if (.nombres_para_operar(columna) %in% .nombres_para_operar(protegidas)) {
      next
    }
    tipo_numerico <- .tipo_numerico_corroboracion_dbi(
      perfil$columnas, columna
    )
    tipo_inferido <- {
      indices_tipo <- which(.nombres_para_operar(
        as.character(perfil$columnas$columna)
      ) %in% .nombres_para_operar(columna))
      if (length(indices_tipo) && "tipo_inferido" %in%
          names(perfil$columnas)) {
        .minusculas_ascii(as.character(
          perfil$columnas$tipo_inferido[[indices_tipo[[1L]]]]
        ))
      } else NA_character_
    }
    tipo_texto <- !is.na(tipo_inferido) && tipo_inferido %in% c(
      "texto", "text", "character", "cadena", "string", "factor"
    )
    causa_medida <- .causa_divergencia_no_numero_dbi(
      resumen$sql, perfil$columnas, columna
    )
    for (metrica in .METRICAS_CORROBORACION_DBI) {
      if (.clave_no_comparable_dbi(columna, metrica) %in%
          claves_no_comparadas) {
        next
      }
      indice_sql <- .estado_corroborable_dbi(
        resumen$sql, columna, metrica
      )
      if (is.null(indice_sql)) next
      a_crudo <- .valor_corroboracion_dbi(
        resumen$columnas, columna, metrica
      )
      b_crudo <- .valor_corroboracion_dbi(
        perfil$columnas, columna, metrica
      )
      if (is.null(a_crudo) || is.null(b_crudo)) next
      es_numerica <- metrica %in% .METRICAS_CORROBORACION_NUMERICAS_DBI ||
        (identical(metrica, "moda") && tipo_numerico)
      comparacion <- if (.equivalentes_sentinela_real_dbi(
                           a_crudo, b_crudo, sentinelas_numericos
                         )) {
        list(difiere = FALSE, motivo = "igualdad_sentinela_real",
             delta = 0)
      } else {
        .comparar_celda_corroboracion_dbi(
          a_crudo, b_crudo, es_numerica,
          relativa = .tolerancia_relativa_corroboracion_dbi(metrica)
        )
      }
      difiere <- if (completa) {
        isTRUE(comparacion$difiere)
      } else if (identical(comparacion$motivo, "faltante_un_lado")) {
        TRUE
      } else if (es_numerica && !is.na(comparacion$delta)) {
        .contradiccion_muestra_corroboracion_dbi(
          metrica,
          .numero_corroboracion_dbi(a_crudo),
          .numero_corroboracion_dbi(b_crudo)
        )
      } else {
        FALSE
      }
      if (!isTRUE(difiere)) {
        if (!completa && isTRUE(comparacion$difiere)) {
          no_corroboradas[[length(no_corroboradas) + 1L]] <-
            .clave_par_identificador(columna, metrica, sep = "::")
        }
        next
      }
      if (por_cotejamiento && tipo_texto &&
          !identical(comparacion$motivo, "faltante_un_lado") &&
          metrica %in% c("n_distintos", "moda", "frecuencia_moda") &&
          explica_cotejamiento(columna, metrica)) {
        esperables_cotejamiento[[length(esperables_cotejamiento) + 1L]] <-
          .clave_par_identificador(columna, metrica, sep = "::")
        next
      }
      valor_sql <- .texto_corroboracion_dbi(a_crudo)
      valor_muestra <- .texto_corroboracion_dbi(b_crudo)
      detalle_muestra <- paste(
        "La diferencia ordinaria no se atribuye a muestreo porque",
        if (identical(comparacion$motivo, "faltante_un_lado")) {
          "uno de los caminos no produjo un valor utilizable."
        } else {
          "la relaci\u00f3n entre la tabla completa y la submuestra es imposible."
        }
      )
      motivo <- paste0(
        "Corroboraci\u00f3n cruzada: `resumen_tabla` y `perfil_muestra` no",
        " coinciden en `", metrica, "` para `", columna, "`. ",
        "`resumen_tabla` (SQL) = ", valor_sql, "; `perfil_muestra`",
        " (`perfilar()` sobre ", format(observado, scientific = FALSE,
          trim = TRUE), " de ", format(total, scientific = FALSE, trim = TRUE),
        if (total == 1L) " fila) = " else " filas) = ", valor_muestra, ". ",
        if (!is.null(causa_medida)) {
          causa_medida
        } else if (completa) {
          paste(
            "La cobertura es 100%; la diferencia supera la tolerancia o",
            "un lado qued\u00f3 en NA. Puede deberse al motor, al controlador,",
            "a la conversi\u00f3n, a que las lecturas no compartieron snapshot,",
            "o -en una media- a la suma en coma flotante cuando la columna",
            "mezcla magnitudes muy distintas, que cada lado acumula a su modo."
          )
        } else detalle_muestra,
        " No se elige un ganador: ambos valores quedan publicados."
      )
      como_resolverlo <- if (!is.null(causa_medida)) {
        paste(
          "Limpiar en el origen los valores que no son n\u00fameros, o leer la",
          "columna como texto (`CAST(columna AS TEXT)` en una vista) y",
          "perfilar esa lectura. No reemplazar un bloque por el otro."
        )
      } else if (completa) {
        paste(
          "Revisar el SQL, el controlador y la conversi\u00f3n de tipos; repetir",
          "la corroboraci\u00f3n bajo un snapshot si se necesita separar un cambio",
          "de tabla de una diferencia del motor. No reemplazar un bloque por el otro."
        )
      } else {
        paste(
          "Repetir con `muestra = Inf` para cubrir el 100% y decidir si la",
          "diferencia persiste. No extrapolar ni reemplazar un bloque por el otro."
        )
      }
      sentencia <- if ("sql" %in% names(resumen$sql)) {
        as.character(resumen$sql$sql[[indice_sql]])
      } else NA_character_
      registros[[length(registros) + 1L]] <- .registro_cobertura_dbi(
        "corroboracion", .clave_par_identificador(columna, metrica, sep = "::"),
        "divergencia", motivo, como_resolverlo, sentencia
      )
    }
  }
  if (length(no_corroboradas)) {
    claves <- unlist(no_corroboradas, use.names = FALSE)
    registros[[length(registros) + 1L]] <- .registro_cobertura_dbi(
      "corroboracion", paste(claves, collapse = ", "),
      "no_corroborada",
      paste0(
        "Hay ", length(claves),
        if (length(claves) == 1L) " comparaci\u00f3n entre `resumen_tabla` y " else
          " comparaciones entre `resumen_tabla` y ",
        "`perfil_muestra` que no coinciden y no se declaran divergencia: la ",
        "muestra cubre ", format(observado, scientific = FALSE, trim = TRUE),
        " de ", format(total, scientific = FALSE, trim = TRUE),
        if (total == 1L) " fila, y una diferencia ordinaria de momentos, mediana, moda o " else
          " filas, y una diferencia ordinaria de momentos, mediana, moda o ",
        "conteos es esperable en una submuestra."
      ),
      paste(
        "Repetir con `muestra = Inf` para cubrir el 100% y decidir si la",
        "diferencia persiste. No extrapolar ni reemplazar un bloque por el otro."
      ),
      NA_character_
    )
  }
  if (length(esperables_cotejamiento)) {
    claves <- unlist(esperables_cotejamiento, use.names = FALSE)
    registros[[length(registros) + 1L]] <- .registro_cobertura_dbi(
      "corroboracion", paste(claves, collapse = ", "),
      "no_corroborada",
      paste0(
        "Hay ", length(claves),
        if (length(claves) == 1L) " comparaci\u00f3n entre `resumen_tabla` y " else
          " comparaciones entre `resumen_tabla` y ",
        "`perfil_muestra` que no coinciden y no se declaran divergencia: el ",
        "resumen SQL agrupa y ordena con el cotejamiento del motor y el perfil ",
        "de muestra compara byte a byte (`meta$criterio_comparacion` y ",
        "`meta$criterio_moda`). En una columna de texto, menos distintos en el ",
        "resumen SQL -con la moda y la frecuencia que de ah\u00ed se siguen-, o una ",
        "moda empatada que cada lado desempata con su orden, es lo que ese ",
        "criterio anticipa."
      ),
      paste(
        "Para contar con el criterio de R, usar `bloque_filas`, que compara en",
        "R, o consultar la columna con un cotejamiento binario. No reemplazar",
        "un bloque por el otro."
      ),
      NA_character_
    )
  }
  salida <- if (length(registros)) do.call(rbind, registros) else vacia
  meta$divergencias <- as.integer(sum(
    as.character(salida$estado) == "divergencia"
  ))
  meta$no_corroboradas <- as.integer(
    length(no_corroboradas) + length(esperables_cotejamiento)
  )
  list(cobertura = salida, meta = meta)
}

.agregar_cobertura_corroboracion_dbi <- function(resultado,
                                                 columnas_codigo = character(),
                                                 columnas_opcionales = character(),
                                                 aplicabilidad = NULL,
                                                 sentinelas_numericos = NULL) {
  if (!is.list(resultado) || !is.list(resultado$resumen_tabla) ||
      is.null(resultado$perfil_muestra)) {
    return(resultado)
  }
  resumen <- resultado$resumen_tabla
  perfil <- resultado$perfil_muestra
  parcial <- .cobertura_clasificacion_personal_parcial_dbi(resumen, perfil)
  proteccion <- resumen$meta$proteccion_personal
  desactivada <- is.list(proteccion) && identical(
    as.character(proteccion$base), "desactivada por el usuario"
  )
  clasificadas <- .columnas_personales_protegidas(perfil$datos_personales)
  if (length(parcial$columnas) && !desactivada) {
    resumen <- .proteger_resumen_dbi(
      resumen, unique(c(clasificadas, parcial$columnas)),
      "perfil_muestra_parcial", perfil
    )
  }
  if (length(parcial$columnas)) {
    if (!is.list(resumen$meta$proteccion_personal)) {
      resumen$meta$proteccion_personal <- list()
    }
    resumen$meta$proteccion_personal$columnas_clasificacion_dudosa <-
      parcial$columnas
    cobertura <- resumen$cobertura
    resumen$cobertura <- if (is.null(cobertura) || !nrow(cobertura)) {
      parcial$cobertura
    } else {
      rbind(cobertura, parcial$cobertura)
    }
    rownames(resumen$cobertura) <- NULL
  }
  protegidas <- unique(c(
    if (isTRUE(resumen$meta$proteccion_personal$aplicada)) {
      clasificadas
    } else character(),
    parcial$columnas
  ))
  corroboracion <- .cobertura_corroboracion_bloques_dbi(
    resumen, perfil, protegidas = protegidas,
    columnas_codigo = columnas_codigo,
    columnas_opcionales = columnas_opcionales, aplicabilidad = aplicabilidad,
    sentinelas_numericos = sentinelas_numericos
  )
  cobertura <- resumen$cobertura
  resumen$cobertura <- if (is.null(cobertura) || !nrow(cobertura)) {
    corroboracion$cobertura
  } else if (!nrow(corroboracion$cobertura)) {
    cobertura
  } else {
    rbind(cobertura, corroboracion$cobertura)
  }
  rownames(resumen$cobertura) <- NULL
  resumen$meta$corroboracion_bloques <- corroboracion$meta
  resultado$resumen_tabla <- resumen
  resultado
}

# ---- Metricas ------------------------------------------------------------

.METRICAS_DBI <- c(
  "validos", "distintos", "moda", "basicos", "mediana", "desvio"
)

.CAMPOS_METRICA_DBI <- list(
  validos = c("n_validos", "n_faltantes", "prop_faltantes"),
  distintos = c("n_distintos", "tasa_distintos"),
  moda = c("moda", "frecuencia_moda"),
  basicos = c("minimo", "maximo", "media", "n_ceros", "n_negativos"),
  mediana = "mediana",
  desvio = "desvio"
)

# Cuando el usuario no pide extremos, se conservan dentro de la misma consulta
# solo para decidir el escalado del desvio. Nunca pasan a la fila publicada:
# son evidencia de magnitud, no valores solicitados.
.CAMPOS_ESCALA_AUX_DBI <- c("minimo", "maximo", "maximo_abs", "minimo_abs")

.METRICAS_OBSERVADAS_MUESTRA_DBI <- c(
  "n_validos", "n_faltantes", "prop_faltantes", "n_distintos",
  "tasa_distintos", "n_ceros", "n_negativos", "frecuencia_moda"
)

.METRICAS_NUMERICAS_DBI <- c("basicos", "mediana", "desvio")

# La estrategia de `distintos` se elige de forma explicita. El orden es parte
# del contrato: el primer valor es el valor por omision de la API.
.ESTRATEGIAS_DISTINTOS_DBI <- c(
  "exacta", "aproximada_motor", "catalogo", "omitida"
)

# La moda puede pagar un agrupamiento que crece con la cardinalidad. La mediana
# no sigue ese regimen: su costo queda gobernado por las filas, asi que no entra
# en la politica proporcional. Se conserva el conjunto historico para que las
# decisiones y el plan sigan describiendo ambas metricas, pero solo la primera
# usa el umbral.
.METRICAS_COSTOSAS_DBI <- c("moda", "mediana")
.METRICA_CARDINALIDAD_COSTO_DBI <- "moda"
.UMBRAL_CARDINALIDAD_COSTO_DBI <- 0.5

# Estas metricas no tienen una cota simple sobre una muestra sin supuestos
# adicionales. Las demas pueden tener un error muestral estimable bajo un plan
# probabilistico, pero esta corrida no lo calcula.
.METRICAS_ERROR_NO_ESTIMABLE_DBI <- c(
  "n_distintos", "tasa_distintos", "moda", "frecuencia_moda", "mediana"
)

.clasificar_metrica_muestreo_dbi <- function(metrica, muestreo, fraccion) {
  metrica <- as.character(metrica)
  metricas_conocidas <- unlist(.CAMPOS_METRICA_DBI, use.names = FALSE)
  if (length(metrica) != 1L || is.na(metrica) ||
      !metrica %in% metricas_conocidas) {
    return(list(
      conocida = FALSE, disponible = FALSE, efectivo = FALSE,
      estado = NA_character_, error_esperado = NA_character_,
      motivo = NA_character_
    ))
  }
  fraccion_numero <- suppressWarnings(as.numeric(fraccion))
  disponible <- !is.null(muestreo) && isTRUE(muestreo$disponible)
  efectivo <- disponible && !(
    length(fraccion_numero) == 1L && is.finite(fraccion_numero) &&
      fraccion_numero >= 1
  )
  error_esperado <- if (!efectivo) {
    "no_aplica"
  } else if (metrica %in% .METRICAS_ERROR_NO_ESTIMABLE_DBI) {
    "no_estimable"
  } else {
    "no_estimado"
  }
  motivo <- if (!efectivo) {
    NA_character_
  } else if (metrica %in% c("n_validos", "n_faltantes", "prop_faltantes")) {
    paste(
      "conteo exacto en la muestra; no estima la tabla completa.",
      "El denominador es `n_total_consulta` de esa misma sentencia."
    )
  } else if (metrica %in% c("n_ceros", "n_negativos", "frecuencia_moda")) {
    paste(
      "conteo exacto en la muestra; no estima la tabla completa.",
      "La escala es la de las filas observadas por esa consulta."
    )
  } else if (metrica %in% c("moda")) {
    paste(
      "La moda de una muestra no tiene una cota simple de error sin",
      "supuestos adicionales sobre la distribuci\u00f3n."
    )
  } else if (metrica %in% c("mediana")) {
    paste(
      "La mediana de una muestra no tiene una cota simple de error sin",
      "supuestos adicionales sobre la distribuci\u00f3n."
    )
  } else if (metrica %in% c("n_distintos", "tasa_distintos")) {
    paste(
      "La cardinalidad observada en una muestra no estima la del universo",
      "sin un estimador declarado."
    )
  } else {
    paste(
      "El error muestral podr\u00eda estimarse bajo un plan probabil\u00edstico, pero no",
      "se calcul\u00f3 en esta corrida."
    )
  }
  list(
    conocida = TRUE, disponible = disponible, efectivo = efectivo,
    estado = if (disponible) {
      if (metrica %in% .METRICAS_OBSERVADAS_MUESTRA_DBI) {
        "observado_muestra"
      } else {
        "estimado"
      }
    } else NA_character_,
    error_esperado = error_esperado, motivo = motivo
  )
}

.error_esperado_muestreo_dbi <- function(metricas, muestreo, fraccion) {
  vapply(metricas, function(metrica) {
    .clasificar_metrica_muestreo_dbi(metrica, muestreo, fraccion)$error_esperado
  }, character(1L))
}

.validar_politica_costo_dbi <- function(politica_costo,
                                       umbral_cardinalidad) {
  if (length(politica_costo) > 1L) {
    if (identical(politica_costo, c("todas", "por_cardinalidad"))) {
      politica_costo <- politica_costo[[1L]]
    } else {
      .detener_dbi(
        "lupa_error_argumento_dbi",
        "`politica_costo` debe ser un \u00fanico valor: `todas` o `por_cardinalidad`."
      )
    }
  }
  opciones <- c("todas", "por_cardinalidad")
  if (!is.character(politica_costo) || length(politica_costo) != 1L ||
      is.na(politica_costo) || !politica_costo %in% opciones) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      paste0(
        "`politica_costo` debe ser un \u00fanico valor: `todas` o `por_cardinalidad`."
      )
    )
  }
  politica <- politica_costo
  if (!is.numeric(umbral_cardinalidad) ||
      length(umbral_cardinalidad) != 1L ||
      is.na(umbral_cardinalidad) || !is.finite(umbral_cardinalidad) ||
      umbral_cardinalidad < 0 || umbral_cardinalidad > 1) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      "`umbral_cardinalidad` debe ser un n\u00famero entre 0 y 1."
    )
  }
  list(
    nombre = politica,
    umbral = as.numeric(umbral_cardinalidad)
  )
}

.metricas_para_politica_costo_dbi <- function(metricas, politica,
                                              incluir_valores) {
  if (!identical(politica$nombre, "por_cardinalidad") ||
      !isTRUE(incluir_valores) ||
      !(.METRICA_CARDINALIDAD_COSTO_DBI %in% metricas)) {
    return(metricas)
  }
  unique(c(metricas, "validos", "distintos"))
}

.validar_estrategia_distintos_dbi <- function(estrategia_distintos) {
  .argumento_dbi(
    .elegir_opcion(estrategia_distintos, .ESTRATEGIAS_DISTINTOS_DBI)
  )
}

.estrategia_distintos_dbi <- function(metricas_solicitadas, politica,
                                      incluir_valores,
                                      estrategia_solicitada) {
  publica <- "distintos" %in% metricas_solicitadas
  para_costo <- identical(politica$nombre, "por_cardinalidad") &&
    isTRUE(incluir_valores) &&
    .METRICA_CARDINALIDAD_COSTO_DBI %in% metricas_solicitadas
  list(
    publica = publica,
    para_costo = para_costo,
    requiere_medicion = publica || para_costo,
    estrategia_solicitada = estrategia_solicitada,
    estrategia_resuelta = NA_character_,
    estado = if (publica || para_costo) "no_disponible" else "no_solicitado",
    disponible = FALSE,
    motivo = NA_character_,
    error_esperado = NA_character_,
    candidato = NULL,
    sondas = character(), estimaciones = NULL, fuentes = NULL,
    sql_catalogo = NA_character_
  )
}

.interpretar_n_distintos_catalogo_dbi <- function(raw, filas_catalogo,
                                                   columna) {
  motivo <- NA_character_
  estimado <- NA_real_
  if (!is.finite(raw)) {
    motivo <- paste0(
      "`pg_stats.n_distinct` no tiene una estimaci\u00f3n utilizable para `",
      columna, "`; puede no haberse ejecutado ANALYZE. No se supone cero."
    )
  } else if (raw >= 0) {
    estimado <- raw
    motivo <- paste0(
      "Estimaci\u00f3n de cat\u00e1logo `pg_stats.n_distinct = ", raw,
      "`; el valor no fue medido recorriendo la tabla."
    )
  } else if (is.finite(filas_catalogo) && filas_catalogo >= 0) {
    estimado <- round(abs(raw) * filas_catalogo)
    motivo <- paste0(
      "Estimaci\u00f3n de cat\u00e1logo: `pg_stats.n_distinct = ", raw,
      "` es una fracci\u00f3n de las filas y `pg_class.reltuples = ",
      filas_catalogo, "; se estima n_distintos = ", estimado,
      ". No fue medido recorriendo la tabla."
    )
  } else {
    motivo <- paste0(
      "`pg_stats.n_distinct = ", raw,
      "` es una fracci\u00f3n, pero `pg_class.reltuples` no tiene un valor utilizable;",
      " puede no haberse ejecutado ANALYZE. No se supone cero."
    )
  }
  disponible <- is.finite(estimado) && estimado >= 0
  proporcion <- if (disponible && is.finite(filas_catalogo) &&
                    filas_catalogo > 0) {
    min(1, max(0, estimado / filas_catalogo))
  } else {
    NA_real_
  }
  list(
    disponible = disponible,
    n_distintos = if (disponible) estimado else NA_real_,
    n_filas = filas_catalogo, n_distintos_catalogo = raw,
    proporcion_distintos = proporcion, motivo = motivo
  )
}

.logico_catalogo_dbi <- function(valor) {
  if (is.logical(valor)) return(valor)
  texto <- .minusculas_ascii(trimws(as.character(valor)))
  ifelse(
    texto %in% c("true", "t", "1"), TRUE,
    ifelse(texto %in% c("false", "f", "0"), FALSE, NA)
  )
}

.seleccionar_fila_catalogo_dbi <- function(datos, columna,
                                            nombre_columna,
                                            nombre_inherited,
                                            nombre_sin_hijas) {
  sin_decision <- function(motivo = NULL) {
    list(fila = NA_integer_, inherited = NA, motivo = motivo)
  }
  if (is.na(nombre_columna) || is.na(nombre_inherited) ||
      is.na(nombre_sin_hijas)) {
    return(sin_decision(paste(
      "La respuesta de `pg_stats` no informa `inherited` y si la relaci\u00f3n",
      "tiene hijas; no se puede decidir qu\u00e9 fila describe lo que se lee."
    )))
  }
  filas <- which(
    .normalizacion_minusculas_vector(.nombres_para_operar(
      as.character(datos[[nombre_columna]])
    )) == .normalizacion_minusculas_vector(.nombres_para_operar(columna))
  )
  if (!length(filas)) return(sin_decision())
  inherited <- .logico_catalogo_dbi(datos[[nombre_inherited]][filas])
  sin_hijas <- .logico_catalogo_dbi(datos[[nombre_sin_hijas]][filas])
  if (anyNA(inherited) || anyNA(sin_hijas) ||
      length(unique(sin_hijas)) != 1L) {
    return(sin_decision(paste0(
      "Hay filas de `pg_stats` para `", columna,
      "` cuyo `inherited` o relaci\u00f3n de hijas no se puede interpretar;",
      " no hay estimaci\u00f3n utilizable."
    )))
  }
  heredadas <- filas[which(inherited)]
  propias <- filas[which(!inherited)]
  if (length(heredadas) > 1L) {
    return(sin_decision(paste0(
      "Hay ", length(heredadas), " filas de `pg_stats` con `inherited = TRUE`",
      " para `", columna, "`; no se puede decidir cu\u00e1l describe lo que se lee."
    )))
  }
  if (length(heredadas) == 1L) {
    return(list(fila = heredadas[[1L]], inherited = TRUE, motivo = NULL))
  }
  if (length(propias) == 1L && isTRUE(sin_hijas[[1L]])) {
    return(list(fila = propias[[1L]], inherited = FALSE, motivo = NULL))
  }
  if (length(propias) == 1L) {
    return(sin_decision(paste0(
      "La relaci\u00f3n tiene hijas pero `pg_stats` no devolvi\u00f3 una fila con",
      " `inherited = TRUE` para `", columna,
      "`; la fila propia describe otro universo y no hay estimaci\u00f3n utilizable."
    )))
  }
  sin_decision(paste0(
    "Hay ", length(propias), " filas de `pg_stats` con `inherited = FALSE`",
    " para `", columna,
    "` y no se puede decidir cu\u00e1l describe lo que se lee; no hay estimaci\u00f3n",
    " utilizable."
  ))
}

.estimar_distintos_catalogo_dbi <- function(conexion, tabla, columnas,
                                            presupuesto) {
  senas <- .senas_conexion_dbi(conexion)
  if (!grepl(.regex_sin_caja("postgres|pqconnection"), senas)) {
    vacias <- .fuentes_cardinalidad_vacias_dbi(columnas)
    return(list(
      disponible = FALSE, estimaciones = vacias, fuentes = vacias,
      sql = NA_character_, motivo = paste(
        "`catalogo` requiere PostgreSQL y su `pg_stats`: no hay una estad\u00edstica",
        "portable de cardinalidad para este motor."
      )
    ))
  }
  piezas <- .piezas_tabla_cardinalidad_dbi(tabla)
  vacias <- .fuentes_cardinalidad_vacias_dbi(columnas)
  if (is.na(piezas$tabla) || !nzchar(piezas$tabla) || !length(columnas)) {
    return(list(
      disponible = FALSE, estimaciones = vacias, fuentes = vacias,
      sql = NA_character_,
      motivo = "No se pudo resolver la relaci\u00f3n o sus columnas para leer `pg_stats`."
    ))
  }
  literal <- function(x) as.character(DBI::dbQuoteString(conexion, x))
  # `pg_stats` tiene un guardian de RLS del motor: con RLS activo para quien
  # consulta, la vista devuelve cero filas. Esto se verifico ejecutando
  # PostgreSQL 16 con un rol con politica. No agregar una guarda redundante ni
  # tratarlo como un defecto pendiente: lupa ya cae en "no disponible".
  condicion_esquema <- if (is.na(piezas$esquema) || !nzchar(piezas$esquema)) {
    "pg_catalog.pg_table_is_visible(c.oid)"
  } else {
    paste0("n.nspname = ", literal(piezas$esquema))
  }
  condicion_columnas <- paste(
    vapply(columnas, literal, character(1L), USE.NAMES = FALSE),
    collapse = ", "
  )
  # Una tabla particionada (`relkind = 'p'`) no tiene filas propias y
  # PostgreSQL puede guardar alli el total de sus particiones. Se excluye del
  # sumatorio para no contar ese total dos veces; las relaciones regulares si
  # aportan sus `reltuples` propios.
  sql <- paste(
    "WITH RECURSIVE relaciones AS (",
    "SELECT c.oid, n.nspname AS schemaname, c.relname AS tablename,",
    "c.reltuples, c.relkind, TRUE AS es_raiz,",
    "NOT EXISTS (SELECT 1 FROM pg_catalog.pg_inherits h",
    "WHERE h.inhparent = c.oid) AS sin_hijas",
    "FROM pg_catalog.pg_class AS c",
    "JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace",
    "WHERE c.relname = ", literal(piezas$tabla), " AND ",
    condicion_esquema,
    " UNION ",
    "SELECT hija.oid, ns.nspname AS schemaname, hija.relname AS tablename,",
    "hija.reltuples, hija.relkind, FALSE AS es_raiz,",
    "NOT EXISTS (SELECT 1 FROM pg_catalog.pg_inherits h2",
    "WHERE h2.inhparent = hija.oid) AS sin_hijas",
    "FROM pg_catalog.pg_inherits AS herencia",
    "JOIN relaciones AS padre ON padre.oid = herencia.inhparent",
    "JOIN pg_catalog.pg_class AS hija ON hija.oid = herencia.inhrelid",
    "JOIN pg_catalog.pg_namespace AS ns ON ns.oid = hija.relnamespace",
    "), filas_jerarquia AS (",
    "SELECT CASE WHEN SUM(CASE WHEN r.relkind <> 'p' AND r.reltuples < 0",
    "THEN 1 ELSE 0 END) = 0 THEN SUM(CASE WHEN r.relkind <> 'p'",
    "THEN r.reltuples ELSE 0 END) ELSE NULL END AS reltuples",
    "FROM relaciones AS r",
    ")",
    "SELECT s.attname AS lupa_columna,",
    "s.n_distinct AS lupa_n_distinct,",
    "j.reltuples AS lupa_n_filas,",
    "s.inherited AS lupa_inherited,",
    "raiz.sin_hijas AS lupa_sin_hijas ",
    "FROM pg_catalog.pg_stats AS s ",
    "JOIN pg_catalog.pg_class AS c ON c.relname = s.tablename ",
    "JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace ",
    "AND n.nspname = s.schemaname ",
    "JOIN relaciones AS raiz ON raiz.oid = c.oid AND raiz.es_raiz ",
    "CROSS JOIN filas_jerarquia AS j ",
    "WHERE s.tablename = ", literal(piezas$tabla),
    " AND ", condicion_esquema,
    " AND s.attname IN (", condicion_columnas, ")"
  )
  consulta <- .consultar_dbi(
    conexion, sql, presupuesto, etapa = "cardinalidad_catalogo"
  )
  if (!isTRUE(consulta$ok) || is.null(consulta$datos)) {
    motivo <- paste(
      "No se pudo leer `pg_stats.n_distinct`:",
      if (isTRUE(consulta$ok)) "la consulta no devolvi\u00f3 una tabla." else
        consulta$motivo
    )
    return(list(
      disponible = FALSE, estimaciones = vacias, fuentes = vacias,
      sql = sql, motivo = motivo
    ))
  }
  datos <- consulta$datos
  nombre_columna <- .campo_resultado_dbi(datos, "lupa_columna")
  nombre_distintos <- .campo_resultado_dbi(datos, "lupa_n_distinct")
  nombre_filas <- .campo_resultado_dbi(datos, "lupa_n_filas")
  nombre_inherited <- .campo_resultado_dbi(datos, "lupa_inherited")
  nombre_sin_hijas <- .campo_resultado_dbi(datos, "lupa_sin_hijas")
  estimaciones <- vector("list", length(columnas))
  fuentes <- vector("list", length(columnas))
  names(estimaciones) <- columnas
  names(fuentes) <- columnas
  for (columna in columnas) {
    seleccion <- .seleccionar_fila_catalogo_dbi(
      datos, columna, nombre_columna, nombre_inherited, nombre_sin_hijas
    )
    fila <- seleccion$fila
    raw <- if (!is.na(fila) && !is.na(nombre_distintos)) {
      .numero_dbi(datos[[nombre_distintos]][fila])
    } else {
      NA_real_
    }
    filas_catalogo <- if (!is.na(fila) && !is.na(nombre_filas)) {
      .numero_dbi(datos[[nombre_filas]][fila])
    } else {
      NA_real_
    }
    interpretacion <- if (is.na(fila)) {
      .interpretar_n_distintos_catalogo_dbi(NA_real_, NA_real_, columna)
    } else {
      .interpretar_n_distintos_catalogo_dbi(raw, filas_catalogo, columna)
    }
    if (!is.null(seleccion$motivo)) interpretacion$motivo <- seleccion$motivo
    interpretacion$inherited <- seleccion$inherited
    estimaciones[[columna]] <- list(
      disponible = interpretacion$disponible,
      n_distintos = interpretacion$n_distintos,
      n_filas = interpretacion$n_filas,
      n_distintos_catalogo = interpretacion$n_distintos_catalogo,
      proporcion_distintos = interpretacion$proporcion_distintos,
      inherited = interpretacion$inherited,
      motivo = interpretacion$motivo, sql = sql,
      fuente = "pg_stats.n_distinct"
    )
    fuentes[[columna]] <- if (isTRUE(interpretacion$disponible)) {
      list(
        nombre = "estimacion_catalogo", exacta = FALSE,
        n_distintos = interpretacion$n_distintos,
        n_filas = interpretacion$n_filas,
        proporcion_distintos = interpretacion$proporcion_distintos,
        inherited = interpretacion$inherited,
        motivo = interpretacion$motivo,
        fuente = "pg_stats.n_distinct"
      )
    } else {
      .fuente_cardinalidad_desconocida_dbi()
    }
  }
  disponibles <- vapply(
    estimaciones, function(x) isTRUE(x$disponible), logical(1L)
  )
  list(
    disponible = any(disponibles), estimaciones = estimaciones,
    fuentes = fuentes, sql = sql,
    motivo = if (any(disponibles)) paste(
      "Se ley\u00f3 `pg_stats.n_distinct` como estimaci\u00f3n de cat\u00e1logo;",
      "no es una medici\u00f3n del universo de la tabla y puede faltar sin ANALYZE."
    ) else paste(
      "No hay estimaciones utilizables de `pg_stats.n_distinct`; puede no",
      "haberse ejecutado ANALYZE. No se supone cero."
    )
  )
}

.resolver_estrategia_distintos_dbi <- function(conexion, estrategia,
                                               presupuesto, hay_metrica,
                                               tabla = NULL, columnas = NULL,
                                               universo = "tabla_completa") {
  if (!isTRUE(hay_metrica)) {
    estrategia$estado <- "no_solicitado"
    estrategia$motivo <- paste(
      "La m\u00e9trica `distintos` no se pidi\u00f3 en esta corrida."
    )
    return(estrategia)
  }
  switch(
    estrategia$estrategia_solicitada,
    exacta = {
      estrategia$estrategia_resuelta <- "COUNT(DISTINCT)"
      estrategia$estado <- "calculado"
      estrategia$disponible <- TRUE
      estrategia$motivo <- paste(
        "Se calcular\u00e1 la cardinalidad exacta sobre las filas de la corrida."
      )
      estrategia$error_esperado <- "no_aplica"
    },
    aproximada_motor = {
      resolucion <- .sondar_aproximacion_dbi(
        conexion, "distintos", presupuesto
      )
      estrategia$disponible <- isTRUE(resolucion$disponible)
      estrategia$candidato <- resolucion$candidato
      estrategia$sondas <- resolucion$sondas
      estrategia$motivo <- resolucion$motivo
      if (isTRUE(resolucion$disponible)) {
        estrategia$estrategia_resuelta <- resolucion$candidato$nombre
        estrategia$estado <- "estimado_motor"
        estrategia$error_esperado <- resolucion$candidato$error_esperado
      } else {
        estrategia$estado <- "no_disponible"
      }
    },
    catalogo = {
      if (identical(universo, "muestra_motor")) {
        # Es el mismo principio que aplica `.estimar_derrame_postgresql_dbi()`:
        # se niega a estimar el derrame de una muestra con estadisticas de la
        # tabla completa y no se inventa una equivalencia entre universos.
        estrategia$disponible <- FALSE
        estrategia$estado <- "no_disponible"
        estrategia$motivo <- paste0(
          "La estrategia `catalogo` no est\u00e1 disponible con `universo = ",
          universo,
          "`: el cat\u00e1logo describe la relaci\u00f3n entera y la corrida mide un",
          " subconjunto; usarlo publicar\u00eda la cardinalidad de un universo como",
          " si fuera de otro."
        )
      } else {
        catalogo <- .estimar_distintos_catalogo_dbi(
          conexion, tabla, columnas, presupuesto
        )
        estrategia$estimaciones <- catalogo$estimaciones
        estrategia$fuentes <- catalogo$fuentes
        estrategia$sql_catalogo <- catalogo$sql
        estrategia$disponible <- isTRUE(catalogo$disponible)
        estrategia$motivo <- catalogo$motivo
        if (isTRUE(catalogo$disponible)) {
          estrategia$estrategia_resuelta <- "pg_stats.n_distinct"
          estrategia$estado <- "estimado_catalogo"
          estrategia$error_esperado <- "desconocido"
        } else {
          estrategia$estado <- "no_disponible"
        }
      }
    },
    omitida = {
      estrategia$estado <- "omitida"
      estrategia$motivo <- paste(
        "La estrategia `omitida` no emite una consulta para `distintos`."
      )
    }
  )
  estrategia
}

.publicar_estrategia_distintos_dbi <- function(estrategia) {
  list(
    estrategia_solicitada = estrategia$estrategia_solicitada,
    estrategia_resuelta = estrategia$estrategia_resuelta,
    estado = estrategia$estado,
    motivo = estrategia$motivo,
    error_esperado = estrategia$error_esperado,
    disponible = isTRUE(estrategia$disponible),
    publica = isTRUE(estrategia$publica),
    para_costo = isTRUE(estrategia$para_costo),
    requiere_medicion = isTRUE(estrategia$requiere_medicion),
    sondas = estrategia$sondas,
    fuente = if (identical(estrategia$estado, "estimado_catalogo")) {
      "pg_stats.n_distinct"
    } else {
      NA_character_
    },
    sql_catalogo = estrategia$sql_catalogo
  )
}

.publicar_estrategia_mediana_dbi <- function(preparacion) {
  solicitada <- preparacion$estrategia_mediana
  if (!"mediana" %in% preparacion$metricas_ejecucion) {
    if (identical(preparacion$universo, "muestra_motor") &&
        !is.null(preparacion$muestreo) &&
        !isTRUE(preparacion$muestreo$disponible)) {
      motivo <- preparacion$muestreo$motivo
      motivo_presupuesto <- !is.null(preparacion$presupuesto) &&
        length(motivo) == 1L && !is.na(motivo) &&
        identical(
          as.character(motivo),
          .motivo_presupuesto_dbi(preparacion$presupuesto)
        )
      if (length(motivo) != 1L || is.na(motivo) ||
          (!grepl("^[a-z_]+:[a-z_]+", motivo) && !motivo_presupuesto)) {
        motivo <- "capacidad_no_aceptada:sonda_muestreo"
      }
      return(list(
        estrategia_solicitada = solicitada,
        estrategia_resuelta = "no_disponible", estado = "no_disponible",
        motivo = motivo
      ))
    }
    return(list(
      estrategia_solicitada = solicitada,
      estrategia_resuelta = NA_character_, estado = "no_solicitado",
      motivo = "La m\u00e9trica `mediana` no se pidi\u00f3 en esta corrida."
    ))
  }
  guardia_newid <- if (is.null(preparacion$presupuesto)) NULL else
    preparacion$presupuesto$guardia_newid
  if (identical(preparacion$universo, "muestra_motor") &&
      is.list(guardia_newid) && !isTRUE(guardia_newid$aceptado)) {
    return(list(
      estrategia_solicitada = solicitada,
      estrategia_resuelta = "no_disponible", estado = "no_disponible",
      motivo = guardia_newid$motivo,
      metadata_costo = guardia_newid
    ))
  }
  if (identical(preparacion$universo, "muestra_motor")) {
    cte <- preparacion$mediana_cte_ventana_resolucion
    if (is.list(cte) && isTRUE(cte$disponible)) {
      metodo <- if (!is.null(preparacion$mediana_cte_ventana)) {
        preparacion$mediana_cte_ventana$nombre
      } else {
        cte$candidato$nombre
      }
      return(list(
        estrategia_solicitada = solicitada,
        estrategia_resuelta = metodo,
        estado = "calculado",
        motivo = "Se us\u00f3 la CTE de ventanas sobre una sola relaci\u00f3n muestreada.",
        sondas = cte$sondas
      ))
    }
    # La mediana muestreada no puede degradarse a `dos_consultas`, aunque el
    # dialecto conserve esa via para `tabla_completa`.
    if (is.list(cte)) {
      return(list(
        estrategia_solicitada = solicitada,
        estrategia_resuelta = "no_disponible", estado = "no_disponible",
        motivo = if (length(cte$motivo) == 1L && !is.na(cte$motivo)) {
          cte$motivo
        } else {
          "capacidad_no_aceptada:sonda_mediana_cte_ventana"
        },
        sondas = cte$sondas
      ))
    }
  }
  consolidada <- preparacion$mediana_consolidada_resolucion
  if (is.list(consolidada) && isTRUE(consolidada$disponible)) {
    return(list(
      estrategia_solicitada = solicitada,
      estrategia_resuelta = consolidada$candidato$nombre,
      estado = "calculado",
      motivo = "Se us\u00f3 una forma exacta consolidada aceptada por el motor."
    ))
  }
  escalar <- preparacion$mediana_escalar_resolucion
  if (is.list(escalar) && isTRUE(escalar$disponible)) {
    return(list(
      estrategia_solicitada = solicitada,
      estrategia_resuelta = escalar$candidato$nombre,
      estado = "calculado",
      motivo = "Se us\u00f3 una forma exacta escalar aceptada por el motor."
    ))
  }
  aproximada <- preparacion$aproximaciones_resolucion$mediana
  if (is.list(aproximada) && isTRUE(aproximada$disponible)) {
    return(list(
      estrategia_solicitada = solicitada,
      estrategia_resuelta = aproximada$candidato$nombre,
      estado = "estimado",
      motivo = "No hubo una forma exacta aceptada; se us\u00f3 la aproximaci\u00f3n nativa al final."
    ))
  }
  # En la tabla completa la CTE solo se prueba cuando el dialecto no expresa un
  # salto de filas (ver `.resumen_columna_dbi()`); la resolucion queda en el
  # presupuesto. Sin consolidada, escalar ni aproximacion, es lo que corrio.
  tardia <- if (is.null(preparacion$presupuesto)) NULL else
    preparacion$presupuesto$mediana_cte_ventana
  if (identical(preparacion$universo, "tabla_completa") && is.list(tardia) &&
      isTRUE(tardia$disponible)) {
    return(list(
      estrategia_solicitada = solicitada,
      estrategia_resuelta = "cte_ventana", estado = "calculado",
      motivo = paste(
        "Se us\u00f3 la CTE de ventanas: el dialecto no expresa un salto de",
        "filas para la v\u00eda de dos consultas."
      ),
      sondas = tardia$sondas
    ))
  }
  list(
    estrategia_solicitada = solicitada,
    estrategia_resuelta = "exacta_por_columna", estado = "calculado",
    motivo = "Se us\u00f3 la forma exacta por columna como \u00faltimo camino."
  )
}

.fuente_cardinalidad_desconocida_dbi <- function() {
  list(
    nombre = "desconocida", exacta = FALSE,
    proporcion_distintos = NA_real_, motivo = paste(
      "No hay una garant\u00eda estructural ni una estimaci\u00f3n de cat\u00e1logo utilizable;",
      "la cardinalidad s\u00f3lo se puede conocer midiendo `distintos`."
    )
  )
}

.fuentes_cardinalidad_vacias_dbi <- function(columnas) {
  salida <- rep(list(.fuente_cardinalidad_desconocida_dbi()),
                length(columnas))
  names(salida) <- columnas
  salida
}

.validar_metricas_dbi <- function(metricas) {
  if (is.null(metricas)) return(.METRICAS_DBI)
  if (!is.character(metricas) || !length(metricas) || anyNA(metricas)) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      "`metricas` debe ser NULL o un vector de texto sin ausentes."
    )
  }
  desconocidas <- setdiff(metricas, .METRICAS_DBI)
  if (length(desconocidas)) {
    .detener_dbi("lupa_error_argumento_dbi", paste0(
      "M\u00e9tricas desconocidas: ", paste(desconocidas, collapse = ", "),
      ". Las disponibles son: ", paste(.METRICAS_DBI, collapse = ", "), "."
    ))
  }
  unique(metricas)
}

.validar_max_consultas_dbi <- function(max_consultas) {
  if (!is.numeric(max_consultas) || length(max_consultas) != 1L ||
      is.na(max_consultas) || max_consultas < 1) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      "`max_consultas` debe ser un n\u00famero mayor o igual a 1, o Inf."
    )
  }
  as.numeric(max_consultas)
}

.validar_tamano_lote_dbi <- function(tamano_lote, nombre = "tamano_lote") {
  if (!is.numeric(tamano_lote) || length(tamano_lote) != 1L ||
      is.na(tamano_lote) || !is.finite(tamano_lote) || tamano_lote < 1 ||
      tamano_lote != floor(tamano_lote)) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      paste0("`", nombre, "` debe ser un entero positivo finito.")
    )
  }
  as.integer(tamano_lote)
}

.resolver_tamanos_lote_dbi <- function(tamano_lote,
                                       tamano_lote_planos,
                                       tamano_lote_distintos) {
  # El argumento antiguo sigue siendo util para reproducir corridas previas.
  # Solo en ese caso se copia a las dos familias; la API nueva siempre deja
  # que los distintos tengan un lote propio y conservador.
  if (!is.null(tamano_lote)) {
    tamano_lote_planos <- tamano_lote
    tamano_lote_distintos <- tamano_lote
  }
  list(
    planos = .validar_tamano_lote_dbi(
      tamano_lote_planos, "tamano_lote_planos"
    ),
    distintos = .validar_tamano_lote_dbi(
      tamano_lote_distintos, "tamano_lote_distintos"
    )
  )
}

# `Inf` significa "toda la tabla, sea del tamano que sea". Es la unica forma de
# pedirlo sin averiguar antes cuantas filas hay: el armado de la muestra ya no
# pone `LIMIT` cuando lo pedido no es menor que el total, asi que `Inf` cae solo
# en ese camino. Existe porque un analisis de calidad no se corre todos los dias
# y suele convenir esperar antes que mirar menos filas.
.validar_muestra_dbi <- function(muestra) {
  if (!is.numeric(muestra) || length(muestra) != 1L || is.na(muestra) ||
      muestra < 1 ||
      (is.finite(muestra) && muestra != floor(muestra))) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      "`muestra` debe ser un entero positivo, o `Inf` para la tabla entera."
    )
  }
  as.numeric(muestra)
}

# Los topes de la muestra tienen que decidirse antes de la lectura que se
# entrega a `perfilar()`. Las celdas se pueden resolver con el esquema y el
# conteo que ya acompana a la corrida; los bytes quedan abiertos hasta la
# sonda chica que hace el bloque DBI. El plan usa la misma funcion con un
# `n_total` desconocido y publica entonces una cota, no una falsa exactitud.
.tope_muestra_dbi <- function(muestra, n_total, n_columnas,
                             max_celdas_muestra, max_bytes_muestra) {
  max_celdas_muestra <- .validar_limite_duplicados(
    max_celdas_muestra, "max_celdas_muestra"
  )
  max_bytes_muestra <- .validar_limite_duplicados(
    max_bytes_muestra, "max_bytes_muestra"
  )
  total <- .numero_dbi(n_total)
  total_conocido <- length(total) == 1L && !is.na(total) &&
    is.finite(total) && total >= 0
  solicitado <- if (total_conocido) min(total, muestra) else muestra
  por_celdas <- if (n_columnas > 0 && is.finite(max_celdas_muestra)) {
    floor(as.numeric(max_celdas_muestra) / n_columnas)
  } else {
    Inf
  }
  if (total_conocido && total > 0 && por_celdas < 1) {
    .detener(
      "`max_celdas_muestra` debe permitir al menos una fila para todas las columnas.",
      call. = FALSE
    )
  }
  filas <- min(solicitado, por_celdas)
  if (total_conocido && total > 0 && filas < 1) {
    .detener(
      "`max_celdas_muestra` debe permitir al menos una fila para todas las columnas.",
      call. = FALSE
    )
  }
  list(
    filas_solicitadas = solicitado,
    filas_por_celdas = por_celdas,
    filas_por_bytes = Inf,
    filas_efectivas = filas,
    celdas_solicitadas = solicitado * n_columnas,
    celdas_efectivas = filas * n_columnas,
    bytes_sonda = NA_real_, bytes_muestra = NA_real_,
    max_celdas_muestra = max_celdas_muestra,
    max_bytes_muestra = max_bytes_muestra,
    recortada = filas < solicitado,
    motivos = character()
  )
}

.tope_muestra_plan_dbi <- function(muestra, n_columnas,
                                  max_celdas_muestra, max_bytes_muestra) {
  max_celdas_muestra <- .validar_limite_duplicados(
    max_celdas_muestra, "max_celdas_muestra"
  )
  max_bytes_muestra <- .validar_limite_duplicados(
    max_bytes_muestra, "max_bytes_muestra"
  )
  por_celdas <- if (n_columnas > 0 && is.finite(max_celdas_muestra)) {
    floor(as.numeric(max_celdas_muestra) / n_columnas)
  } else {
    Inf
  }
  filas_maximas <- min(as.numeric(muestra), por_celdas)
  list(
    filas_solicitadas = as.numeric(muestra),
    filas_por_celdas = por_celdas,
    filas_maximas = filas_maximas,
    celdas_solicitadas = as.numeric(muestra) * n_columnas,
    celdas_maximas = filas_maximas * n_columnas,
    max_celdas_muestra = max_celdas_muestra,
    max_bytes_muestra = max_bytes_muestra,
    recortada_por_celdas = filas_maximas < as.numeric(muestra),
    requiere_sonda_bytes = is.finite(max_bytes_muestra),
    motivo = paste(
      "El tope de celdas se resuelve antes de leer con el ancho del esquema;",
      if (is.finite(max_bytes_muestra)) {
        "el tope de bytes requiere una sonda de hasta 100 filas antes de fijar el l\u00edmite final."
      } else {
        "el tope de bytes est\u00e1 desactivado con `Inf`."
      }
    )
  )
}

# ---- Tipos ---------------------------------------------------------------
#
# Que una columna admita agregados cuantitativos lo decide el motor, no el
# prototipo que expone el driver. Un DECIMAL, un NUMBER o un BIGINT devuelto
# como texto o como `integer64` cae en `no_aplica` si solo se mira la clase de
# R, aunque SQL si pueda calcularlo. Por eso se consulta tambien el tipo
# declarado en `dbColumnInfo()`, que nunca degrada la decision: solo la
# habilita.

.PATRON_TIPO_NUMERICO_DBI <- paste0(
  "^(decimal|numeric|number|int|integer|int2|int4|int8|bigint|smallint|",
  "tinyint|mediumint|float|float4|float8|double|real|money|smallmoney|",
  "binary_float|binary_double|integer64|int64|bigserial|hugeint|ubigint|",
  "bigintunsigned)$"
)

.tipo_declarado_numerico_dbi <- function(tipo) {
  if (is.null(tipo) || !length(tipo) || is.na(tipo[[1L]])) return(FALSE)
  limpio <- .minusculas_ascii(trimws(sub("\\(.*", "", as.character(tipo[[1L]]))))
  limpio <- gsub("[[:space:]_-]+", "", limpio)
  grepl(.PATRON_TIPO_NUMERICO_DBI, limpio, perl = TRUE)
}

# Algunos controladores exponen BIGINT como `integer` y otros conservan el
# nombre original. La guarda solo se usa sobre valores grandes: si el tipo es
# de 32 bits, no puede alcanzar el umbral y no se produce un falso positivo.
.tipo_declarado_entero_ancho_dbi <- function(tipo) {
  if (is.null(tipo) || !length(tipo) || is.na(tipo[[1L]])) return(FALSE)
  limpio <- .minusculas_ascii(trimws(as.character(tipo[[1L]])))
  limpio <- gsub("[[:space:]_-]+", "", limpio)
  base <- sub("\\(.*", "", limpio)
  if (base %in% c(
    "tinyint", "utinyint", "smallint", "usmallint", "integer", "uinteger",
    "int", "uint", "int1", "int2", "int4", "int8", "int16", "int32",
    "int64", "int128", "uint8", "uint16", "uint32", "uint64", "uint128",
    "bigint", "ubigint", "hugeint", "uhugeint", "bigserial",
    "bigintunsigned", "integer64"
  )) {
    return(TRUE)
  }
  if (!grepl("^(decimal|numeric|number)\\(", limpio, perl = TRUE)) {
    return(FALSE)
  }
  contenido <- sub("^[^(]+\\(", "", limpio)
  contenido <- sub("\\)$", "", contenido)
  partes <- strsplit(contenido, ",", fixed = TRUE)[[1L]]
  precision <- suppressWarnings(as.numeric(partes[[1L]]))
  escala <- if (length(partes) >= 2L) {
    suppressWarnings(as.numeric(partes[[2L]]))
  } else {
    0
  }
  isTRUE(is.finite(precision) && precision > 15 &&
    is.finite(escala) && escala == 0)
}

# Un controlador que entrega como `numeric` un entero ancho puede haber perdido
# cifras, pero solo cuando la magnitud cruza 2^53. Si no hay extremos utilizables
# -por ejemplo, se pidio solo la moda o la consulta de basicos fallo-, se pide la
# forma textual: es exacta si hace falta y conserva la salida visible para los
# valores chicos.
.entero_doble_ancho_moda_dbi <- function(prototipo, tipo, extremos = NULL) {
  if (!is.double(prototipo) ||
      !.tipo_declarado_entero_ancho_dbi(tipo)) return(FALSE)
  if (is.null(extremos)) return(TRUE)
  extremos <- suppressWarnings(as.numeric(extremos))
  extremos <- extremos[is.finite(extremos)]
  if (!length(extremos)) return(TRUE)
  any(abs(extremos) >= .MAX_ENTERO_EXACTO_DBI)
}

.extremos_basicos_moda_dbi <- function(agregados, columna) {
  if (!is.list(agregados) || !is.list(agregados$basicos)) return(NULL)
  basicos <- agregados$basicos[[columna]]
  if (!is.list(basicos) || !isTRUE(basicos$ok) ||
      !is.data.frame(basicos$datos) || !nrow(basicos$datos)) return(NULL)
  extremos <- vapply(c("minimo", "maximo"), function(nombre) {
    celda <- .valor_campo_dbi(basicos$datos, nombre)
    if (!isTRUE(celda$ok)) return(NA_real_)
    .escalar_finito_dbi(celda$valor)
  }, numeric(1L))
  if (any(!is.finite(extremos))) NULL else extremos
}

# Un tipo decimal exacto -`numeric`, `decimal`, `number`, con o sin precision y
# escala-. Lo que el motor guarda es el decimal, y un doble desde 2^53 ya no lo
# representa: 90071992547409001 y 90071992547409002 son el mismo doble. La guarda
# del entero ancho miraba solo `numeric(20,0)`, un texto que ni RPostgres ni odbc
# publican -dan `numeric` por `.typname` y el codigo ODBC `2`-, asi que nunca se
# disparaba en el camino principal: con `bloque_filas`, 60 distintos salian 4, con
# una moda que no estaba en la columna, sin aviso. Por eso
# decide el valor -un doble de al menos 2^53 que viene de un decimal ya no es
# exacto-, y el tipo solo dice que viene de un decimal. odbc publica el codigo
# ODBC: 2 es `SQL_NUMERIC` y 3 `SQL_DECIMAL` -SQL Server da 2 para `decimal` y
# `numeric`, y 3 para `money`, que no llega a 2^53-.
.tipo_declarado_decimal_dbi <- function(tipo) {
  if (is.null(tipo) || !length(tipo) || is.na(tipo[[1L]])) return(FALSE)
  limpio <- .minusculas_ascii(trimws(as.character(tipo[[1L]])))
  limpio <- gsub("[[:space:]_-]+", "", limpio)
  limpio %in% c("2", "3") ||
    grepl("^(decimal|numeric|number)(\\(.*\\))?$", limpio, perl = TRUE)
}

# RPostgres publica en `type` la clase de R -`double` para `numeric` y para
# `double precision`- y el tipo del motor en `.typname`. La guarda del decimal
# necesita distinguirlos (ver `.tipo_declarado_decimal_dbi()`): el tipo
# declarado de una columna `numeric` pasa a ser `numeric`. Solo ese; las otras
# columnas conservan lo que publico el controlador.
.tipos_declarados_con_motor_dbi <- function(tipos, tipos_motor) {
  if (is.null(tipos) || is.null(tipos_motor) ||
      length(tipos) != length(tipos_motor)) {
    return(tipos)
  }
  motor <- .minusculas_ascii(trimws(as.character(tipos_motor)))
  decimal <- !is.na(motor) & grepl(
    "^(numeric|decimal)(\\(|$)", motor, perl = TRUE
  )
  tipos[decimal] <- motor[decimal]
  tipos
}

# Un tipo temporal declarado por el motor manda sobre lo que diga el prototipo.
# El `dbFetch(n = 0)` de algunos controladores -RMariaDB entre ellos- devuelve
# un `numeric(0)` para una columna `DATE`: la clase se pierde con las filas. Sin
# esta comprobacion, `is.numeric()` decia que si, y la columna se media como
# numero: `MIN` daba los dias desde 1970 y `AVG(f * 1.0)` daba YYYYMMDD en
# MariaDB. Dos unidades distintas, las dos publicadas como `calculado`.
.PATRON_TIPO_TEMPORAL_DBI <- paste0(
  "^(date|datetime|datetime2|smalldatetime|timestamp|timestamptz|",
  "timestampwithtimezone|timestampwithouttimezone|time|timetz|year|",
  "interval|datetimeoffset)$"
)

.tipo_declarado_temporal_dbi <- function(tipo) {
  if (is.null(tipo) || !length(tipo) || is.na(tipo[[1L]])) return(FALSE)
  limpio <- .minusculas_ascii(trimws(sub("\\(.*", "", as.character(tipo[[1L]]))))
  limpio <- gsub("[[:space:]_-]+", "", limpio)
  grepl(.PATRON_TIPO_TEMPORAL_DBI, limpio, perl = TRUE)
}

# SQL Server no admite estas columnas como expresion comparable en
# `COUNT(DISTINCT)`, `GROUP BY`, `ORDER BY` ni `MIN/MAX`. El nombre sale del
# catalogo `sys.columns`; los codigos ODBC no bastan porque mezclan tipos
# binarios que si admiten esas operaciones con `geography`.
.tipo_sqlserver_sin_agregados_dbi <- function(tipo) {
  if (is.null(tipo) || !length(tipo) || is.na(tipo[[1L]])) return(FALSE)
  limpio <- .minusculas_ascii(trimws(as.character(tipo[[1L]])))
  base <- sub("\\(.*", "", limpio)
  base %in% c("text", "ntext", "image", "xml", "geography")
}

.motivo_tipo_sqlserver_sin_agregados_dbi <- function(tipo) {
  paste0(
    "SQL Server no admite el tipo `", as.character(tipo[[1L]]),
    "` en los agregados y ordenamientos solicitados; la m\u00e9trica queda",
    " `no_disponible` y no se emite una consulta sobre la columna."
  )
}

# `dbExistsTable()` no distingue una tabla que no existe de una que existe y no
# se puede ver, y el mensaje lo decia asi. Pero cuando la consulta de
# comprobacion falla, **el motor suele decir cual de las dos es**: PostgreSQL
# responde "permiso denegado a la relacion", SQL Server "permission was denied".
# Repetir la disyuncion con esa evidencia en la mano es informar como incierto
# algo que ya esta resuelto: el reverso del invariante, y en una corrida real
# fueron veintitres tablas descritas como "no existe o no hay permiso" cuando el
# motor habia dicho que era permiso.
.PATRON_PERMISO_DBI <- paste0(
  "permiso denegado|permission denied|permission was denied|",
  "insufficient privilege|no tiene privilegios|not authorized|",
  "acceso denegado|access denied|ORA-00942|ORA-01031"
)

.mensaje_tabla_inaccesible_dbi <- function(motivo) {
  detalle <- if (!is.na(motivo)) motivo else ""
  if (!is.na(motivo) &&
      grepl(.regex_sin_caja(.PATRON_PERMISO_DBI), motivo, perl = TRUE)) {
    return(paste(
      "La tabla existe pero la credencial no tiene permiso para verla: el",
      "motor lo dijo expl\u00edcitamente.", detalle
    ))
  }
  paste(
    "La tabla solicitada no existe en la conexi\u00f3n DBI, o la credencial no",
    "tiene permiso para verla. El motor no distinguio entre las dos, y",
    "`dbExistsTable()` tampoco.", detalle
  )
}

.es_numerico_dbi <- function(prototipo, tipo_declarado = NA_character_) {
  if (inherits(prototipo, c("Date", "POSIXt", "difftime"))) return(FALSE)
  if (.tipo_declarado_temporal_dbi(tipo_declarado)) return(FALSE)
  if (is.numeric(prototipo)) return(TRUE)
  if (inherits(prototipo, "integer64")) return(TRUE)
  if (is.logical(prototipo) || is.raw(prototipo) || is.list(prototipo)) {
    return(FALSE)
  }
  .tipo_declarado_numerico_dbi(tipo_declarado)
}

# ---- Resumen por columna -------------------------------------------------

.fila_resumen_dbi <- function(columna, n_total) {
  list(
    columna = columna,
    n = .conteo_dbi(n_total),
    n_validos = NA_real_,
    n_faltantes = NA_real_,
    prop_faltantes = NA_real_,
    n_distintos = NA_real_,
    tasa_distintos = NA_real_,
    moda = NA_character_,
    frecuencia_moda = NA_real_,
    minimo = NA_real_,
    maximo = NA_real_,
    media = NA_real_,
    mediana = NA_real_,
    desvio = NA_real_,
    n_ceros = NA_real_,
    n_negativos = NA_real_
  )
}

# `numeric(0)` es lo que devuelve `as.numeric(NULL)`, y es lo que reventaba el
# ensamblado de la fila y los `if`. Ningun valor entra a la fila sin pasar por
# aca.
.escalar_finito_dbi <- function(valor) {
  if (is.null(valor) || !length(valor)) return(NA_real_)
  numero <- suppressWarnings(as.numeric(valor[[1L]]))
  if (!length(numero) || is.na(numero)) return(NA_real_)
  numero
}

# El motor devolvio algo y R no lo pudo leer como numero: no es lo mismo que el
# motor no haya devuelto nada. Pasa de verdad -SQLite responde `MIN` de una
# columna `DATE` como el texto "2020-01-01", que `as.numeric()` convierte en
# `NA`- y el resultado se publicaba como `calculado` con valor `NA`, que es la
# contradiccion exacta que el paquete persigue: `NA` significa "no se midio" y
# `calculado` significa "se midio".
#
# La comprobacion es agnostica del motor y del tipo: si vino un valor no nulo y
# la conversion lo perdio, la metrica no se publica.
.valor_perdido_en_conversion_dbi <- function(crudo, convertido) {
  if (is.null(crudo) || !length(crudo)) return(FALSE)
  original <- crudo[[1L]]
  # `NaN` no es "el motor no devolvio nada": duckdb conserva el `NaN` como valor
  # y responde `MAX` y `AVG` con `NaN`. `is.na(NaN)` es TRUE, y la guarda lo
  # tomaba por un nulo: se publicaba `calculado` con valor `NA`.
  es_nan <- is.numeric(original) && isTRUE(is.nan(original))
  if (is.null(original) || !length(original) ||
      (is.na(original) && !es_nan)) return(FALSE)
  !isTRUE(is.finite(convertido))
}

# Un infinito que el motor devuelve no es "un valor que no se pudo leer como
# numero": es un numero, y R lo lee. La columna guarda `Inf` o `-Inf` -SQLite,
# PostgreSQL y duckdb los admiten en una columna de punto flotante- y el motor
# los cuenta en `MIN`, `MAX`, `AVG` y el orden de la mediana, mientras que la
# regla del paquete es una: los estadisticos de magnitud se calculan solo con
# valores finitos. Medido: `c(1, 2, 3, 4, Inf, NA)` salia con
# `minimo`, `maximo`, `media` y `mediana` en `NA` "porque la columna no es de
# la magnitud que estas metricas suponen", y la corroboracion publicaba como
# causa MEDIDA que la columna guardaba texto. `typeof()` daba cinco `real`.
.es_infinito_motor_dbi <- function(crudo) {
  if (is.null(crudo) || !length(crudo)) return(FALSE)
  original <- crudo[[1L]]
  is.numeric(original) && !inherits(original, "integer64") &&
    isTRUE(is.infinite(original))
}

.motivo_infinito_dbi <- function(que) {
  paste0(
    .FRAGMENTO_INFINITO_DBI, " ", if (identical(que, "la sonda de magnitud"))
      que else paste0("`", que, "`"),
    ": la columna guarda valores infinitos y el motor los cuenta en `MIN`, ",
    "`MAX`, `AVG` y el orden de la mediana, mientras que los estad\u00edsticos de ",
    "magnitud se calculan s\u00f3lo con valores finitos. En este motor la consulta ",
    "no los pudo excluir, y las m\u00e9tricas de magnitud de esta columna no se ",
    "publican como calculadas."
  )
}

# Como se escribe un infinito en el SQL de cada motor que los admite. `9e999`
# desborda a `Inf` en el lector de SQLite; PostgreSQL y duckdb leen
# 'Infinity'. En SQL Server y MySQL una columna de punto flotante no admite
# infinitos; en un motor sin senas no se adivina la sintaxis: `NULL`, y las
# magnitudes quedan sin publicar con `.motivo_infinito_dbi()`.
.literales_infinito_dbi <- function(conexion, como_numeric = FALSE) {
  senas <- .senas_conexion_dbi(conexion)
  if (isTRUE(como_numeric) &&
      grepl("postgres|pqconnection", senas, useBytes = TRUE)) {
    return(c(
      "CAST('1e309' AS NUMERIC)",
      "CAST('-1e309' AS NUMERIC)"
    ))
  }
  if (grepl("duckdb", senas, fixed = TRUE, useBytes = TRUE)) {
    return(c("CAST('Infinity' AS DOUBLE)", "CAST('-Infinity' AS DOUBLE)"))
  }
  if (grepl("postgres|pqconnection", senas, useBytes = TRUE)) {
    return(c(
      "CAST('Infinity' AS DOUBLE PRECISION)",
      "CAST('-Infinity' AS DOUBLE PRECISION)"
    ))
  }
  if (grepl("sqlite", senas, fixed = TRUE, useBytes = TRUE)) {
    return(c("9e999", "-9e999"))
  }
  NULL
}

# PostgreSQL ordena `NaN` por encima de todos los numeros y lo incluye en los
# agregados. La via de infinitos puede reutilizarse si la relacion finita
# excluye tambien este literal. No se declara para otros motores: duckdb, por
# ejemplo, conserva la distincion en R y mantiene su contrato propio.
.literal_nan_dbi <- function(conexion, como_numeric = FALSE) {
  senas <- .senas_conexion_dbi(conexion)
  if (!grepl("postgres|pqconnection", senas, useBytes = TRUE)) return(NULL)
  if (isTRUE(como_numeric)) {
    "CAST('NaN' AS NUMERIC)"
  } else {
    "CAST('NaN' AS DOUBLE PRECISION)"
  }
}

# Cuenta los infinitos de la columna en un motor que sabe escribirlos. Solo se
# pregunta cuando ninguna otra respuesta del motor lo dice: ver el `AVG` de los
# basicos.
.hay_infinitos_dbi <- function(conexion, tabla_sql, columna_sql, alias,
                               presupuesto = NULL,
                               como_numeric = FALSE) {
  infinitos <- .literales_infinito_dbi(conexion, como_numeric)
  if (is.null(infinitos)) return(FALSE)
  sql <- paste0(
    "SELECT SUM(CASE WHEN ", columna_sql, " = ", infinitos[[1L]], " OR ",
    columna_sql, " = ", infinitos[[2L]], " THEN 1 ELSE 0 END) AS ",
    alias("n_infinitos"), " FROM ", tabla_sql
  )
  contado <- .escalar_dbi(
    conexion, sql, "n_infinitos", presupuesto, etapa = "sonda_infinitos"
  )
  isTRUE(contado$ok) && isTRUE(.numero_dbi(contado$valor) > 0)
}

# Las metricas de magnitud de una columna con infinitos, sobre los valores
# finitos: la MISMA maquinaria del resumen por columna -basicos, mediana por
# cualquiera de sus caminos, desvio- sobre una subconsulta que deja afuera los
# dos infinitos. Ni una regla nueva por metrica ni una consulta escrita aparte:
# `n_validos` de la subconsulta es el de los finitos, y es el que usa la mediana
# exacta en dos consultas. Solo sobre la tabla completa: sobre una muestra del
# motor, la subconsulta volveria a muestrear otras filas. Devuelve `NULL` si
# este motor no tiene como escribir el infinito.
.magnitudes_finitas_dbi <- function(conexion, tabla_sql, columna, columna_sql,
                                    prototipo, n_total, dialecto,
                                    pedidas_numericas, presupuesto,
                                    incluir_valores, tipo_declarado,
                                    motivo_ilegible, universo,
                                    decisiones_costo,
                                    como_numeric = FALSE) {
  if (!identical(universo, "tabla_completa")) return(NULL)
  infinitos <- .literales_infinito_dbi(conexion, como_numeric)
  nan <- .literal_nan_dbi(conexion, como_numeric)
  if (is.null(infinitos)) return(NULL)
  pg_float8 <- grepl("postgres|pqconnection", .senas_conexion_dbi(conexion),
                     useBytes = TRUE) &&
    .tipo_declarado_float8_dbi(tipo_declarado, conexion)
  lectura_exacta <- .es_lectura_double_exacta_dbi(columna_sql) ||
    isTRUE(como_numeric)
  # En PostgreSQL, al combinar infinitos con DBL_MAX se vuelve a calcular sobre
  # una relacion finita. Convertir esa relacion a NUMERIC exacto evita que
  # `STDDEV_SAMP(double precision)` desborde antes de que el resultado llegue a
  # R; la formula normal de float8 sigue siendo binaria fuera de este camino.
  convertir_finitos <- pg_float8 && !lectura_exacta
  valor_finito <- if (convertir_finitos) {
    .lectura_double_postgresql_dbi(columna_sql)
  } else columna_sql
  columna_alias <- as.character(DBI::dbQuoteIdentifier(conexion, columna))
  predicados <- c(
    if (!is.null(nan)) paste0(columna_sql, " <> ", nan),
    paste0(columna_sql, " <> ", infinitos[[1L]]),
    paste0(columna_sql, " <> ", infinitos[[2L]])
  )
  predicado_finito <- paste(predicados, collapse = " AND ")
  # La reconstruccion exacta escribe la columna decenas de veces y el resumen de
  # la relacion finita la vuelve a escribir en cada referencia. Si PostgreSQL
  # funde las subconsultas, la expresion se multiplica: con un `real`, que ya
  # llega envuelto en su lectura, el planificador tardaba minutos sobre tres
  # filas, y `statement_timeout` no lo cortaba. `OFFSET 0` deja la subconsulta
  # sin fundir.
  tabla_finita <- paste0(
    "(SELECT ", valor_finito, " AS ", columna_alias, " FROM ", tabla_sql,
    " WHERE ", predicado_finito, if (convertir_finitos) " OFFSET 0",
    ")", dialecto$alias_tabla("lupa_finitos")
  )
  interno <- .resumen_columna_dbi(
    conexion, tabla_finita, columna, prototipo, n_total, dialecto = dialecto,
    metricas = c("validos", pedidas_numericas), presupuesto = presupuesto,
    incluir_valores = incluir_valores, tipo_declarado = tipo_declarado,
    motivo_ilegible = motivo_ilegible, universo = "tabla_completa",
    # La relacion finita puede tener una columna NUMERIC aunque la sonda del
    # resumen original haya elegido una forma aproximada para float8. Esa forma
    # fue sondada sobre otra expresion; la mediana exacta local evita reusarla.
    aproximacion_mediana = NULL,
    mediana_escalar = NULL, decisiones_costo = decisiones_costo,
    solo_finitos = TRUE,
    # La relacion ya excluye los valores no finitos. Para un float8 original
    # se conserva la lectura exacta de cada doble, pero no se vuelven a usar
    # los literales NUMERIC de infinito: PostgreSQL intentaria convertir
    # `1e309` al tipo de la columna antes de ejecutar el filtro y desbordaria.
    infinitos_como_numeric = lectura_exacta,
    numeric_exact = convertir_finitos || lectura_exacta,
    columna_sql = columna_alias
  )
  campos <- unlist(.CAMPOS_METRICA_DBI[pedidas_numericas], use.names = FALSE)
  sql <- interno$sql
  sql <- sql[as.character(sql$metrica) %in% campos, , drop = FALSE]
  # "La columna no contiene valores no nulos" es falso: los tiene, y son
  # infinitos.
  sin_finitos <- as.character(sql$estado) == "sin_valores"
  if (any(sin_finitos)) {
    sql$motivo[sin_finitos] <- paste(
      "La columna no contiene valores finitos: los estad\u00edsticos de magnitud",
      "se calculan s\u00f3lo con valores finitos."
    )
  }
  list(fila = interno$fila[campos], sql = sql, literales = interno$literales)
}

.motivo_nan_dbi <- function(que) {
  paste0(
    .FRAGMENTO_NAN_DBI, " ", if (identical(que, "la sonda de magnitud"))
      que else paste0("`", que, "`"),
    ": la columna guarda valores `NaN` y el motor los cuenta como valores -en ",
    "`MAX`, `AVG` y el orden de la mediana-, mientras que en R son ausentes. ",
    "Las m\u00e9tricas de magnitud de esta columna no se publican como calculadas."
  )
}

# Y el mismo cuidado con los enteros grandes: un `integer64` por encima de 2^53
# pierde exactitud al pasar a doble, y el maximo publicado seria un numero que
# no esta en la columna. Se comprueba con la vuelta completa, que no depende de
# donde caiga el redondeo.
# El consejo depende del controlador: duckdb entrega un BIGINT como doble por
# omision y se le pide en `duckdb::duckdb()`; RSQLite, RPostgres, RMariaDB y
# odbc lo piden en `DBI::dbConnect()`, y entregan `integer64` por omision.
# Recomendar "RSQLite o duckdb" en una conexion de PostgreSQL era un consejo que
# no aplicaba.
.remedio_entero_doble_dbi <- function(conexion = NULL) {
  if (inherits(conexion, "duckdb_connection")) {
    return(paste(
      "Conectar pidiendo `integer64`:",
      "`DBI::dbConnect(duckdb::duckdb(bigint = \"integer64\"))`."
    ))
  }
  paste(
    "Conectar pidiendo `integer64`: el argumento `bigint = \"integer64\"` de",
    "`DBI::dbConnect()` en RSQLite, RPostgres, RMariaDB y odbc, o",
    "`duckdb::duckdb(bigint = \"integer64\")` en duckdb."
  )
}

# Lo que escriben las guardas del entero de 64 bits -la del resumen SQL y la del
# recorrido por bloques- y lo que la corroboracion reconoce como "el resumen no
# publica esta metrica a proposito": una sola regla para quien la escribe y
# quien la lee, como `.FRAGMENTO_NO_NUMERO_DBI`.
.FRAGMENTO_ENTERO_64_DBI <- "entero de 64 bits"
.FRAGMENTO_ENTERO_ANCHO_DBI <- "entero ancho"

.es_motivo_entero_64_dbi <- function(motivo) {
  !is.na(motivo) & (
    grepl(.FRAGMENTO_ENTERO_64_DBI, motivo, fixed = TRUE, useBytes = TRUE) |
      grepl(.FRAGMENTO_ENTERO_ANCHO_DBI, motivo, fixed = TRUE, useBytes = TRUE)
  )
}

.fragmento_entero_doble_dbi <- function(tipo) {
  limpio <- if (is.null(tipo) || !length(tipo) || is.na(tipo[[1L]])) {
    ""
  } else {
    base <- .minusculas_ascii(trimws(as.character(tipo[[1L]])))
    sub("\\(.*", "", gsub("[[:space:]_-]+", "", base))
  }
  if (limpio %in% c(
    "hugeint", "uhugeint", "int128", "uint128"
  )) .FRAGMENTO_ENTERO_ANCHO_DBI else .FRAGMENTO_ENTERO_64_DBI
}

# `valor` es lo que entrego el controlador. Un `integer64` llego EXACTO -el
# driver no lo paso por un doble- y la metrica no se publica porque las de
# magnitud son dobles: decir "el driver entrego como doble" y recomendar pedir
# `integer64` describia otra cosa. Medido sobre PostgreSQL,
# SQL Server y MariaDB, que entregan `integer64`.
.motivo_entero_doble_dbi <- function(metrica = NULL, prefijo = NULL,
                                     valor = NULL, conexion = NULL,
                                     tipo = NA_character_,
                                     mediana_por_valor = FALSE) {
  inicio <- if (!is.null(prefijo) && length(prefijo) && !is.na(prefijo)) {
    as.character(prefijo)
  } else if (!is.null(metrica) && length(metrica) && !is.na(metrica)) {
    paste0("El valor de `", metrica, "` ")
  } else {
    "La sonda de magnitud "
  }
  exacto <- !is.null(valor) && length(valor) &&
    inherits(valor[[1L]], "integer64")
  if (!exacto && .tipo_declarado_decimal_dbi(tipo)) {
    return(.motivo_decimal_doble_dbi(mediana_por_valor = mediana_por_valor))
  }
  if (exacto) {
    return(paste(
      paste0(
        inicio, "es un ", .FRAGMENTO_ENTERO_64_DBI, " con un valor de valor ",
        "absoluto de al menos 2^53:"
      ),
      "el controlador lo entreg\u00f3 exacto, como `integer64`, pero un doble no",
      "lo representa y las m\u00e9tricas de magnitud se publican como dobles. No se",
      "publica como calculada. `n_distintos` y la moda se cuentan sobre el",
      "valor exacto."
    ))
  }
  fragmento <- .fragmento_entero_doble_dbi(tipo)
  paste(
    paste0(
      inicio,
      "es un ", fragmento, " que el driver entreg\u00f3 como doble;"
    ),
    "un valor con valor absoluto de al menos 2^53 puede haber perdido",
    "exactitud. No se publica como calculada.",
    .remedio_entero_doble_dbi(conexion)
  )
}

# El motivo de la guarda del decimal (ver `.tipo_declarado_decimal_dbi()`), el
# mismo en la via SQL y en la de bloques: la condicion es de la representacion
# que entrego el controlador, no del valor decimal guardado en el motor.
.FRAGMENTO_DECIMAL_DOBLE_DBI <- paste(
  "decimal entregado como doble con un valor de valor absoluto de al menos 2^53"
)

.motivo_decimal_doble_dbi <- function(bloques = FALSE,
                                      mediana_por_valor = FALSE) {
  paste(
    paste0(
      "La columna es un ", .FRAGMENTO_DECIMAL_DOBLE_DBI, ":"
    ),
    "desde ah\u00ed un doble no distingue dos valores consecutivos",
    "-90071992547409001 y 90071992547409002 son el mismo doble-, as\u00ed que",
    if (isTRUE(mediana_por_valor)) {
      paste(
        "m\u00ednimo, m\u00e1ximo, n_ceros y n_negativos no se publican como",
        "calculados, la mediana s\u00f3lo cuando su valor no depende de uno de",
        "esos dobles, y la media y el desv\u00edo s\u00f3lo si salen de las sumas",
        "exactas en el motor."
      )
    } else {
      paste(
        "m\u00ednimo, m\u00e1ximo, n_ceros, n_negativos y mediana no se publican",
        "como calculados, y la media y el desv\u00edo s\u00f3lo si salen de las",
        "sumas exactas en el motor."
      )
    },
    if (isTRUE(bloques)) {
      paste(
        "Con `bloque_filas` tampoco `n_distintos` ni la moda: se contarian en",
        "R sobre esos dobles."
      )
    } else {
      "`n_distintos` y la moda los cuenta el motor sobre el valor exacto."
    },
    "Las cifras de `perfil_muestra` para esta columna salen de los mismos",
    "dobles. Para ver los valores exactos, leer la columna como texto en una",
    "vista (`CAST(columna AS VARCHAR(40))`) y perfilar esa lectura."
  )
}

.entero_perdido_en_conversion_dbi <- function(
    crudo, tipo_declarado = NA_character_) {
  if (is.null(crudo) || !length(crudo)) return(FALSE)
  original <- crudo[[1L]]
  if (is.na(original)) return(FALSE)
  if (inherits(original, "integer64")) {
    if (!.bit64_disponible_dbi()) return(FALSE)
    # El aviso de bit64 -"integer precision lost while converting to double"- es
    # la perdida que esta funcion mide: se recoge aca y la declara quien llama,
    # como el resto. El `tryCatch()` solo atrapaba errores: con `warn = 0` el
    # aviso crudo, en ingles, le llegaba al usuario.
    avisada <- FALSE
    regreso <- tryCatch(
      withCallingHandlers(
        bit64::as.integer64(as.numeric(original)),
        warning = function(w) {
          avisada <<- TRUE
          invokeRestart("muffleWarning")
        }
      ),
      error = function(e) NULL
    )
    return(avisada || is.null(regreso) || is.na(regreso) || regreso != original)
  }
  if (!is.double(original) ||
      !(.tipo_declarado_entero_ancho_dbi(tipo_declarado) ||
          .tipo_declarado_decimal_dbi(tipo_declarado))) {
    return(FALSE)
  }
  isTRUE(is.finite(original) && abs(original) >= .MAX_ENTERO_EXACTO_DBI)
}

# La mediana de una columna entera o decimal se publica `calculado` cuando su
# valor es exacto, y eso se decide por el valor y no por la columna. Habia dos
# reglas: la de los basicos negaba la mediana de toda columna con algun valor de
# al menos 2^53 -la de `{1, 2, 2^63 - 1}` en BIGINT, que es 2-, y la de la
# mediana misma la publicaba cuando su valor quedaba por debajo de 2^53, que es
# lo que pasaba con HUGEINT porque ahi los basicos desbordan. La segunda
# entrega mas, pero sola miente con una cantidad par: el promedio de
# -9007199254740991 y 9007199254740995 es 2, el de sus dobles es 2,5, y 2,5
# esta muy por debajo de 2^53 (medido en DuckDB, HUGEINT). La de ahora:
#
#   - Un valor de al menos 2^53 no se publica: puede ser una central que el
#     doble ya redondeo.
#   - Con una cantidad impar la mediana ES la central, y el redondeo es
#     monotono: una central de al menos 2^53 da un doble de al menos 2^53. Por
#     debajo, la central llego exacta, aunque la columna tenga otros valores
#     enormes.
#   - Con una cantidad par se promedian dos centrales y el resultado no dice si
#     alguna paso de 2^53. Si la columna tiene valores asi -`columna_ancha`-, no
#     se publica. Si no los tiene, las dos llegaron exactas y el motor redondea
#     una sola vez su promedio, salvo PostgreSQL: su `PERCENTILE_CONT` interpola
#     `bajo + (alto - bajo) * 0.5` en doble, y la resta redondea cuando las
#     centrales distan mas de 2^53 -la mediana de -9007199254740991 y
#     9007199254740990 salia -1, y es -0,5-. Eso solo puede pasar si los
#     extremos distan mas de 2^53 (`interpola_restando`).
#
# Devuelve la causa por la que no se publica, o `NA` si se publica.
.causa_mediana_inexacta_dbi <- function(valor, n = NA_real_,
                                        columna_ancha = FALSE,
                                        extremos = NULL,
                                        interpola_restando = FALSE) {
  valor <- suppressWarnings(as.numeric(valor))
  if (length(valor) != 1L || !is.finite(valor)) return(NA_character_)
  if (abs(valor) >= .MAX_ENTERO_EXACTO_DBI) return("valor")
  n <- suppressWarnings(as.numeric(n))
  impar <- length(n) == 1L && is.finite(n) && n %% 2 == 1
  if (impar) return(NA_character_)
  if (isTRUE(columna_ancha)) return("par")
  if (isTRUE(interpola_restando)) {
    extremos <- suppressWarnings(as.numeric(extremos))
    extremos <- extremos[is.finite(extremos)]
    if (length(extremos) >= 2L &&
        max(extremos) - min(extremos) > .MAX_ENTERO_EXACTO_DBI) {
      return("resta")
    }
  }
  NA_character_
}

.motivo_mediana_inexacta_dbi <- function(causa, tipo = NA_character_,
                                         n = NA_real_) {
  if (identical(causa, "resta")) {
    return(paste(
      "PostgreSQL interpola `PERCENTILE_CONT` en doble como",
      "`bajo + (alto - bajo) * 0.5`, y los extremos de la columna distan m\u00e1s",
      "de 2^53: con una cantidad par de valores, la resta de las dos centrales",
      "puede redondear y la mediana no ser la exacta. No se publica como",
      "calculada."
    ))
  }
  # Sin `.FRAGMENTO_DECIMAL_DOBLE_DBI`: ese texto marca la columna para
  # `.aplicar_guardas_salida_muestra_dbi()`, que le pasaria este motivo -de la
  # mediana- al minimo y al resto.
  fragmento <- if (.tipo_declarado_decimal_dbi(tipo)) {
    "decimal con alg\u00fan valor de valor absoluto de al menos 2^53"
  } else {
    paste(
      .fragmento_entero_doble_dbi(tipo),
      "con alg\u00fan valor de valor absoluto de al menos 2^53"
    )
  }
  n <- suppressWarnings(as.numeric(n))
  conocida <- length(n) == 1L && is.finite(n)
  paste(
    paste0(
      "La columna es un ", fragmento,
      if (conocida) {
        " y la cantidad de valores es par: la mediana promedia"
      } else {
        " y no se conoce la cantidad de valores: si es par, la mediana promedia"
      },
      " dos centrales, y su valor no dice si alguna es uno de"
    ),
    "esos valores, que un doble no representa. No se publica como calculada.",
    "Con una cantidad impar la mediana es la central, y se publica cuando",
    "queda por debajo de 2^53."
  )
}

# Con una cantidad par, las dos centrales estan en (-2^52, 2^52) si menos de la
# mitad de los valores llega a 2^52 y menos de la mitad baja de -2^52: la alta
# es la `n / 2 + 1`, y deja `n / 2 - 1` por encima; la baja, simetrica. Ahi
# cualquier forma de promediarlas -la interpolacion de PostgreSQL incluida- es
# exacta, y la mediana de una columna que pasa de 2^53 se puede publicar. Una
# consulta mas, solo para esas columnas y solo en la tabla completa: en la
# muestra del motor leeria otra muestra.
.LIMITE_CENTRALES_DBI <- "4503599627370496"

.centrales_por_debajo_dbi <- function(conexion, tabla_sql, columna_sql, alias,
                                      n, presupuesto = NULL) {
  n <- .numero_dbi(n)
  if (!is.finite(n) || n < 2 || n %% 2 != 0) return(FALSE)
  senas <- .senas_conexion_dbi(conexion)
  contar <- function(condicion, nombre) {
    paste0(
      .conteo_sql_dbi(paste0(
        "SUM(CASE WHEN ", columna_sql, " ", condicion, " THEN 1 ELSE 0 END)"
      ), senas),
      " AS ", alias(nombre)
    )
  }
  sql <- paste0(
    "SELECT ", contar(paste0(">= ", .LIMITE_CENTRALES_DBI), "centrales_altas"),
    ", ", contar(paste0("<= -", .LIMITE_CENTRALES_DBI), "centrales_bajas"),
    " FROM ", tabla_sql
  )
  resultado <- .consultar_dbi(conexion, sql, presupuesto, etapa = "mediana")
  if (!isTRUE(resultado$ok)) return(FALSE)
  altas <- .numero_dbi(.valor_campo_dbi(resultado$datos, "centrales_altas")$valor)
  bajas <- .numero_dbi(.valor_campo_dbi(resultado$datos, "centrales_bajas")$valor)
  isTRUE(is.finite(altas) && is.finite(bajas) && altas < n / 2 &&
           bajas < n / 2)
}

# Que la consulta de basicos desbordara -`HUGEINT * 1.0` en DuckDB, cerca del
# tope del tipo- dice que la columna tiene valores enormes, aunque no se sepa
# cuales: la mediana se juzga como la de una columna que pasa de 2^53. La misma
# lectura del motivo que decide el repliegue de la mediana.
.es_desborde_motor_dbi <- function(motivo) {
  grepl(
    "overflow|underflow|out of range|fuera de rango|error while fetching rows",
    .minusculas_ascii(as.character(motivo %||% "")), useBytes = TRUE
  )
}

.metricas_omitidas_dbi <- function(registros, columna, metricas, estado,
                                    motivo, metadatos = NULL) {
  campos <- unlist(.CAMPOS_METRICA_DBI[metricas], use.names = FALSE)
  if (!length(campos)) return(registros)
  c(registros, list(
    .registro_sql_dbi(
      columna, campos, estado, motivo, NA_character_, metadatos = metadatos
    )
  ))
}

.motivo_decision_costo_dbi <- function(decision, metrica) {
  if (is.null(decision) || is.null(decision$detalle)) return(NA_character_)
  especifica <- decision$detalle[[metrica]]
  if (is.list(especifica) && length(especifica$motivo)) {
    return(as.character(especifica$motivo))
  }
  # Alias de compatibilidad para decisiones creadas por extensiones que aun no
  # publican el detalle separado.
  decision$detalle$motivo
}

.decision_costo_dbi <- function(columna, politica,
                                n_validos = NA_real_, n_distintos = NA_real_,
                                alcance = "la tabla",
                                fuente_cardinalidad_costo = NULL) {
  conservar <- list(moda = TRUE, mediana = TRUE)
  fuente <- fuente_cardinalidad_costo
  if (is.null(fuente)) fuente <- .fuente_cardinalidad_desconocida_dbi()
  motivo_mediana <- paste(
    "La mediana se conserva: no se aplica un umbral de proporci\u00f3n porque su",
    "costo medido permanece plano frente a la cardinalidad y lo gobierna el",
    "n\u00famero de filas. `umbral_cardinalidad` gobierna s\u00f3lo la moda."
  )
  detalle <- list(
    n_validos = n_validos, n_distintos = n_distintos,
    proporcion_distintos = NA_real_, motivo = NA_character_,
    fuente_cardinalidad_costo = fuente$nombre,
    umbral_cardinalidad = politica$umbral,
    moda = list(
      estado = "conservada", motivo = NA_character_,
      criterio = "proporcion_distintos", umbral = politica$umbral
    ),
    mediana = list(
      estado = "conservada", motivo = motivo_mediana,
      criterio = "filas", umbral = NA_real_
    )
  )
  if (!identical(politica$nombre, "por_cardinalidad")) {
    detalle$moda$motivo <- paste0(
      "La moda se conserva porque `politica_costo = \"", politica$nombre,
      "\"` no aplica el criterio de cardinalidad."
    )
    detalle$motivo <- detalle$moda$motivo
    return(c(conservar, detalle = list(detalle)))
  }
  validos <- .numero_dbi(n_validos)
  distintos <- .numero_dbi(n_distintos)
  proporcion <- if (is.finite(validos) && validos > 0 &&
                    is.finite(distintos) && distintos >= 0) {
    distintos / validos
  } else {
    NA_real_
  }
  distintos_fuente <- .numero_dbi(fuente$n_distintos)
  if (is.finite(distintos_fuente) && distintos_fuente >= 0) {
    distintos <- distintos_fuente
    if (is.finite(fuente$proporcion_distintos)) {
      proporcion <- as.numeric(fuente$proporcion_distintos)
    } else if (is.finite(validos) && validos > 0) {
      proporcion <- distintos / validos
    }
    detalle$fuente_cardinalidad_costo <- fuente$nombre
  } else if (!is.null(fuente$proporcion_distintos) &&
      is.finite(fuente$proporcion_distintos)) {
    proporcion <- as.numeric(fuente$proporcion_distintos)
    if (!is.finite(validos) && proporcion == 1) validos <- NA_real_
    if (!is.finite(distintos) && is.finite(validos) && proporcion == 1) {
      distintos <- validos
    }
    detalle$fuente_cardinalidad_costo <- fuente$nombre
  } else if (is.finite(proporcion)) {
    detalle$fuente_cardinalidad_costo <- "medicion_exacta"
  }
  detalle$n_validos <- if (is.finite(validos)) validos else n_validos
  detalle$n_distintos <- if (is.finite(distintos)) distintos else n_distintos
  detalle$proporcion_distintos <- proporcion
  if (is.finite(proporcion) && proporcion >= politica$umbral) {
    conservar$moda <- FALSE
    detalle$moda$estado <- "omitida_por_costo"
    detalle$moda$motivo <- paste0(
      "Se omiti\u00f3 la moda de la columna `", columna, "`: tiene ", distintos,
        if (isTRUE(distintos == 1L)) " valor distinto de " else " valores distintos de ",
      validos, " v\u00e1lidos (", formatC(proporcion, format = "f", digits = 3),
      ") sobre ", alcance, "; la pol\u00edtica optativa considera que agrupar u",
      " ordenar toda la columna no justifica el costo. Para pedirla igual, usar",
      " `politica_costo = \"todas\"`; para mover el criterio, cambiar",
      " `umbral_cardinalidad`."
    )
  } else if (is.finite(proporcion)) {
    detalle$moda$motivo <- paste0(
      "La moda se conserva: la proporci\u00f3n de distintos (",
      formatC(proporcion, format = "f", digits = 3), ") queda por debajo de ",
      "`umbral_cardinalidad` (",
      formatC(politica$umbral, format = "f", digits = 3), ")."
    )
  } else {
    detalle$moda$motivo <- paste(
      "La moda se conserva porque no se pudo determinar una proporci\u00f3n de",
      "distintos utilizable para aplicar `umbral_cardinalidad`."
    )
  }
  detalle$motivo <- detalle$moda$motivo
  c(conservar, detalle = list(detalle))
}

.decisiones_costo_dbi <- function(columnas, agregados, politica,
                                  universo = "tabla_completa",
                                  fuentes_cardinalidad_costo = NULL) {
  salida <- vector("list", length(columnas))
  names(salida) <- columnas
  alcance <- if (identical(universo, "muestra_motor")) "la muestra medida" else
    "la tabla completa"
  for (columna in columnas) {
    conteo <- agregados$conteos[[columna]]
    validos <- if (is.null(conteo) || is.null(conteo$validos)) {
      NA_real_
    } else .numero_dbi(conteo$validos$valor)
    distintos <- if (is.null(conteo) || is.null(conteo$distintos)) {
      NA_real_
    } else .numero_dbi(conteo$distintos$valor)
    fuente <- if (is.null(fuentes_cardinalidad_costo)) {
      NULL
    } else {
      fuentes_cardinalidad_costo[[columna]]
    }
    salida[[columna]] <- .decision_costo_dbi(
      columna, politica, validos, distintos, alcance,
      fuente_cardinalidad_costo = fuente
    )
  }
  salida
}

.piezas_tabla_cardinalidad_dbi <- function(tabla) {
  if (isTRUE(.es_id_dbi(tabla))) {
    piezas <- .partes_id_dbi(tabla)
    return(list(
      esquema = if ("esquema" %in% names(piezas)) piezas[["esquema"]] else NA_character_,
      tabla = unname(piezas[["tabla"]])
    ))
  }
  if (is.character(tabla) && length(tabla) == 1L && !is.na(tabla)) {
    cortado <- .partir_identificador(tabla)
    partes <- vapply(
      cortado$partes, .quitar_comillas_identificador, character(1L),
      USE.NAMES = FALSE
    )
    if (length(partes) == 2L) {
      return(list(esquema = partes[[1L]], tabla = partes[[2L]]))
    }
    return(list(esquema = NA_character_, tabla = partes[[1L]]))
  }
  list(esquema = NA_character_, tabla = NA_character_)
}

.resolver_fuentes_cardinalidad_dbi <- function(conexion, tabla, columnas,
                                               estrategia, presupuesto) {
  fuentes <- .fuentes_cardinalidad_vacias_dbi(columnas)
  if (identical(estrategia$estrategia_solicitada, "catalogo") &&
      is.list(estrategia$fuentes)) {
    indices_fuentes <- .indice_nombre(
      names(estrategia$fuentes), names(fuentes)
    )
    for (i in which(!is.na(indices_fuentes))) {
      fuentes[[indices_fuentes[[i]]]] <- estrategia$fuentes[[i]]
    }
  }
  # La clave se lee siempre para publicarla en `meta$clave`. Su resultado solo
  # gobierna la politica de costo cuando esa politica lo necesita.
  piezas <- .piezas_tabla_cardinalidad_dbi(tabla)
  catalogo <- .clave_primaria_dbi(
    conexion, piezas$tabla, piezas$esquema, presupuesto = presupuesto
  )
  # Red universal, por encima del filtro de cada motor: una clave cuyas columnas
  # no estan entre las que se acaban de medir no puede ser de la tabla medida.
  #
  # Existe porque el filtro por esquema resuelve el caso de CADA motor conocido,
  # y esta clase de fallo aparece justamente en los que no se conocen: el
  # catalogo contesta por una homonima y la respuesta llega con la forma de una
  # respuesta buena. Esta comprobacion no necesita saber la precedencia de nadie
  # -compara contra las columnas que el propio perfilado leyo-, asi que cubre
  # tambien al motor que todavia no se probo. Se descubrio sobre SQL Server el
  # 2026-08-30: publicaba clave en `x` para una tabla de columnas `y, dato`.
  # `length(columnas)` no es defensa de rutina: si el esquema de la tabla no se
  # pudo leer, la lista llega vacia y TODA columna de la clave pareceria ajena.
  # Descartar una clave buena porque no se sabe contra que compararla seria
  # silenciar por ignorancia, que es el error opuesto y de igual importancia.
  if (length(catalogo$columnas) && length(columnas)) {
    ajenas <- catalogo$columnas[
      is.na(.resolver_columnas_dbi(catalogo$columnas, columnas))
    ]
    if (length(ajenas)) catalogo <- .clave_de_otra_relacion(catalogo, ajenas)
  }
  # Una clave compuesta no vuelve unica cada columna por separado. Solo una
  # clave primaria simple, aplicada y validada, permite afirmar que su columna
  # tiene tantos distintos como valores validos, sin contarla.
  if (isTRUE(estrategia$para_costo) &&
      length(catalogo$columnas) == 1L &&
      identical(catalogo$garantia, "garantizada")) {
    posicion <- .resolver_columnas_dbi(catalogo$columnas, columnas)
    if (length(posicion) == 1L && !is.na(posicion)) {
      columna <- columnas[[posicion]]
      fuentes[[columna]] <- list(
        nombre = "clave_primaria_garantizada", exacta = TRUE,
        proporcion_distintos = 1, motivo = paste(
          "La clave primaria simple est\u00e1 declarada y garantizada por el",
          "cat\u00e1logo; sus valores v\u00e1lidos son \u00fanicos."
        )
      )
    }
  }
  list(fuentes = fuentes, catalogo = catalogo)
}

.columnas_distintos_ejecucion_dbi <- function(
    metricas, estrategia_distintos, campos,
    fuentes_cardinalidad_costo = NULL, politica_costo = NULL) {
  if (!"distintos" %in% metricas) return(character())
  if (identical(estrategia_distintos$estado, "estimado_catalogo")) {
    return(character())
  }
  if (isTRUE(estrategia_distintos$publica)) return(campos)
  if (is.null(fuentes_cardinalidad_costo)) return(NULL)
  if (!is.null(politica_costo) &&
      identical(politica_costo$nombre, "por_cardinalidad")) {
    return(campos[vapply(
      fuentes_cardinalidad_costo,
      function(x) !isTRUE(x$exacta), logical(1L)
    )])
  }
  character()
}

# Los dos conteos recorren la misma tabla, asi que se piden juntos: una
# consulta por columna en vez de dos. `COUNT(DISTINCT ...)` no es universal, y
# consolidar acopla fallos, asi que si la consulta combinada se rechaza los dos
# conteos se reintentan por separado. Un rechazo no puede arrastrar a la otra
# metrica.
.conteos_columna_dbi <- function(conexion, tabla_sql, columna_sql, alias,
                                 pide_validos, pide_distintos,
                                 presupuesto = NULL,
                                 aproximacion_distintos = NULL,
                                 incluir_total = FALSE) {
  senas <- .senas_conexion_dbi(conexion)
  total_alias <- alias("n_total_consulta")
  sql_validos <- paste0(
    "SELECT ", if (isTRUE(incluir_total)) {
      paste0(.conteo_sql_dbi("COUNT(*)", senas), " AS ", total_alias, ", ")
    } else "",
    .contar_no_nulos_sql_dbi(columna_sql, senas), " AS ", alias("n_validos"),
    " FROM ", tabla_sql
  )
  expresion_distintos <- if (is.null(aproximacion_distintos)) {
    c(
      paste0(.contar_no_nulos_sql_dbi(columna_sql, senas), " AS ",
             alias("n_validos_guard")),
      paste0(
        .conteo_sql_dbi(
          paste0("COUNT(DISTINCT ", columna_sql, ")"), senas
        ), " AS ", alias("n_distintos")
      )
    )
  } else if (is.function(aproximacion_distintos$expresion)) {
    c(
      paste0(.contar_no_nulos_sql_dbi(columna_sql, senas), " AS ",
             alias("n_validos_guard")),
      aproximacion_distintos$expresion(
        columna_sql, alias("n_distintos")
      )
    )
  } else {
    NULL
  }
  sql_distintos <- if (!is.null(aproximacion_distintos)) {
    if (is.function(aproximacion_distintos$expresion)) {
      paste0(
        "SELECT ", paste(expresion_distintos, collapse = ", "),
        " FROM ", tabla_sql
      )
    } else {
      aproximacion_distintos$construir(
        columna_sql, tabla_sql, alias("n_distintos")
      )
    }
  } else {
    paste0(
      "SELECT ", paste(expresion_distintos, collapse = ", "),
      " FROM ", tabla_sql
    )
  }
  puede_consolidar <- is.character(expresion_distintos) &&
    length(expresion_distintos) > 0L &&
    all(!is.na(expresion_distintos) & nzchar(trimws(expresion_distintos)))
  if (pide_validos && pide_distintos) {
    if (puede_consolidar) {
      sql <- paste0(
        "SELECT ", if (isTRUE(incluir_total)) {
          paste0(.conteo_sql_dbi("COUNT(*)", senas), " AS ", total_alias, ", ")
        } else "",
        .contar_no_nulos_sql_dbi(columna_sql, senas), " AS ", alias("n_validos"),
        ", ", paste(expresion_distintos, collapse = ", "),
        " FROM ", tabla_sql
      )
      consulta <- .consultar_dbi(
        conexion, sql, presupuesto, etapa = "conteos"
      )
      if (isTRUE(consulta$ok)) {
        validos <- .valor_campo_dbi(consulta$datos, "n_validos")
        distintos <- .valor_campo_dbi(consulta$datos, "n_distintos")
        if (isTRUE(validos$ok) && isTRUE(distintos$ok)) {
          validos$sql <- sql
          distintos$sql <- sql
          validos <- .adjuntar_medicion_dbi(validos, consulta)
          distintos <- .adjuntar_medicion_dbi(distintos, consulta)
          validos <- .adjuntar_denominador_consulta_dbi(
            validos, consulta, if (isTRUE(incluir_total)) total_alias else NULL
          )
          distintos <- .adjuntar_guardian_distintos_dbi(
            distintos, consulta, alias("n_validos_guard")
          )
          if (!is.null(aproximacion_distintos)) {
            distintos$metadatos <- .mezclar_metadatos_dbi(
              distintos$metadatos, list(
              metodo = aproximacion_distintos$nombre,
              error_esperado = aproximacion_distintos$error_esperado
              )
            )
            distintos$estado <- "estimado"
          }
          salida <- list(
            validos = validos, distintos = distintos, consolidada = TRUE
          )
          if (isTRUE(incluir_total)) {
            salida$conteo <- .valor_campo_dbi(
              consulta$datos, .nombre_alias_dbi(total_alias)
            )
            salida$conteo$sql <- sql
            salida$conteo$metadatos <- list(
              id_consulta = as.integer(consulta$consulta_id)
            )
            salida$conteo <- .adjuntar_medicion_dbi(
              salida$conteo, consulta
            )
          }
          return(salida)
        }
      }
    }
  }
  resultado <- list(consolidada = FALSE)
  if (pide_validos) {
    consulta_validos <- .consultar_dbi(
      conexion, sql_validos, presupuesto, etapa = "conteos"
    )
    validos <- .resultado_lote_dbi(
      consulta_validos, sql_validos, alias("n_validos"), list()
    )
    validos <- .adjuntar_denominador_consulta_dbi(
      validos, consulta_validos,
      if (isTRUE(incluir_total)) total_alias else NULL
    )
    resultado$validos <- validos
    if (isTRUE(incluir_total) && isTRUE(validos$ok)) {
      resultado$conteo <- .resultado_lote_dbi(
        consulta_validos, sql_validos, total_alias, list(
          id_consulta = as.integer(consulta_validos$consulta_id)
        )
      )
    }
  }
  if (pide_distintos) {
    consulta_distintos <- .consultar_dbi(
      conexion, sql_distintos, presupuesto, etapa = "conteos"
    )
    distintos <- .resultado_lote_dbi(
      consulta_distintos, sql_distintos, alias("n_distintos"), list()
    )
    distintos <- .adjuntar_guardian_distintos_dbi(
      distintos, consulta_distintos,
      if (isTRUE(puede_consolidar)) alias("n_validos_guard") else NULL
    )
    if (!is.null(aproximacion_distintos) && isTRUE(distintos$ok)) {
      distintos$metadatos <- .mezclar_metadatos_dbi(
        distintos$metadatos, list(
          metodo = aproximacion_distintos$nombre,
          error_esperado = aproximacion_distintos$error_esperado
        )
      )
      distintos$estado <- "estimado"
    }
    resultado$distintos <- distintos
  }
  resultado
}

.lotes_columnas_dbi <- function(columnas, tamano_lote) {
  if (!length(columnas)) return(list())
  split(columnas, ceiling(seq_along(columnas) / tamano_lote))
}

.metadatos_lote_dbi <- function(numero, columnas) {
  list(
    lote = as.integer(numero),
    columnas_compartidas = as.integer(length(columnas)),
    id_consulta = NA_integer_
  )
}

.alias_agregado_dbi <- function(alias, lote, posicion, metrica) {
  alias(paste0("lupa_l", lote, "_c", posicion, "_", metrica))
}

.nombre_alias_dbi <- function(alias) {
  texto <- as.character(alias)
  texto <- sub("^`(.*)`$", "\\1", texto)
  texto <- sub('^"(.*)"$', "\\1", texto)
  sub("^\\[(.*)\\]$", "\\1", texto)
}

.resultado_lote_dbi <- function(consulta, sql, alias, metadatos) {
  if (!consulta$ok) {
    return(.adjuntar_medicion_dbi(list(
      ok = FALSE, valor = NULL, motivo = consulta$motivo, sql = sql,
      metadatos = metadatos
    ), consulta))
  }
  resultado <- .valor_campo_dbi(consulta$datos, .nombre_alias_dbi(alias))
  resultado$sql <- sql
  resultado$metadatos <- metadatos
  if (isTRUE(resultado$ok) && !is.null(consulta$consulta_id) &&
      length(consulta$consulta_id) == 1L && !is.na(consulta$consulta_id)) {
    resultado$metadatos$id_consulta <- as.integer(consulta$consulta_id)
  }
  .adjuntar_medicion_dbi(resultado, consulta)
}

.valor_denominador_consulta_dbi <- function(consulta, alias) {
  vacio <- list(
    n_total_consulta = NA_real_,
    consulta_id_denominador = NA_integer_
  )
  if (is.null(alias) || !isTRUE(consulta$ok)) return(vacio)
  celda <- .valor_campo_dbi(consulta$datos, .nombre_alias_dbi(alias))
  if (!isTRUE(celda$ok)) return(vacio)
  valor <- .conteo_dbi(celda$valor)
  if (is.na(valor)) return(vacio)
  list(
    n_total_consulta = valor,
    consulta_id_denominador = as.integer(consulta$consulta_id)
  )
}

.adjuntar_denominador_consulta_dbi <- function(resultado, consulta, alias) {
  resultado$metadatos <- .mezclar_metadatos_dbi(
    resultado$metadatos,
    .valor_denominador_consulta_dbi(consulta, alias)
  )
  resultado
}

.adjuntar_guardian_dbi <- function(resultado, consulta, alias) {
  guardian <- list(
    n_validos_guard = NA_real_,
    consulta_id_guard = NA_integer_,
    cota_comprobable = FALSE
  )
  if (!is.null(alias) && isTRUE(consulta$ok)) {
    celda <- .valor_campo_dbi(consulta$datos, .nombre_alias_dbi(alias))
    if (isTRUE(celda$ok)) {
      valor <- .conteo_dbi(celda$valor)
      if (!is.na(valor)) {
        guardian$n_validos_guard <- valor
        guardian$consulta_id_guard <- as.integer(consulta$consulta_id)
        guardian$cota_comprobable <- !is.na(consulta$consulta_id)
      }
    }
  }
  resultado$metadatos <- .mezclar_metadatos_dbi(
    resultado$metadatos, guardian
  )
  resultado
}

.adjuntar_guardian_distintos_dbi <- function(resultado, consulta, alias) {
  .adjuntar_guardian_dbi(resultado, consulta, alias)
}

.adjuntar_guardian_moda_dbi <- function(resultado, consulta, alias) {
  .adjuntar_guardian_dbi(resultado, consulta, alias)
}

.conteo_desde_consulta_dbi <- function(consulta, sql, alias) {
  if (!isTRUE(consulta$ok)) return(NULL)
  resultado <- .valor_campo_dbi(
    consulta$datos, .nombre_alias_dbi(alias)
  )
  if (!isTRUE(resultado$ok) || is.na(.conteo_dbi(resultado$valor))) {
    return(NULL)
  }
  resultado$sql <- sql
  resultado$metadatos <- list(
    id_consulta = as.integer(consulta$consulta_id)
  )
  .adjuntar_medicion_dbi(resultado, consulta)
}

.resultado_lote_campos_dbi <- function(consulta, sql, alias, metricas,
                                       metadatos) {
  if (!consulta$ok) {
    return(.adjuntar_medicion_dbi(list(
      ok = FALSE, datos = NULL, motivo = consulta$motivo, sql = sql,
      metadatos = metadatos
    ), consulta))
  }
  celdas <- lapply(metricas, function(metrica) {
    .valor_campo_dbi(
      consulta$datos, .nombre_alias_dbi(alias[[metrica]])
    )
  })
  fallas <- vapply(celdas, function(celda) !isTRUE(celda$ok), logical(1L))
  if (any(fallas)) {
    return(.adjuntar_medicion_dbi(list(
      ok = FALSE, datos = NULL,
      motivo = paste(vapply(celdas[fallas], `[[`, character(1L), "motivo"),
                     collapse = " "),
      sql = sql, metadatos = metadatos
    ), consulta))
  }
  valores <- lapply(celdas, `[[`, "valor")
  names(valores) <- metricas
  datos <- as.data.frame(valores, stringsAsFactors = FALSE)
  .adjuntar_medicion_dbi(
    list(ok = TRUE, datos = datos, motivo = NA_character_, sql = sql,
         metadatos = utils::modifyList(
           metadatos,
           if (!is.null(consulta$consulta_id) &&
               length(consulta$consulta_id) == 1L &&
               !is.na(consulta$consulta_id)) {
             list(id_consulta = as.integer(consulta$consulta_id))
           } else list()
         )),
    consulta
  )
}

# La media en el motor, como doble. `AVG(x * 1.0)` promueve una columna entera
# sin depender del nombre de un tipo, y en SQLite, duckdb y PostgreSQL da la
# media entera. En SQL Server no: `int * 1.0` es `numeric`, y `AVG` de un
# `numeric` devuelve seis decimales. Sobre 61 enteros el motor publicaba
# 16.934426 y la muestra 16.934426229508198, y la corroboracion declaraba
# `divergencia` en la media de TODA columna entera -tambien `bigint`- de una
# tabla perfilada entera. En T-SQL -SQL Server y Sybase, las
# senas del dialecto `top`- se pide como `FLOAT`, que es el doble de 53 bits:
# la misma cifra que lee R, y no una tolerancia que esconda la diferencia.
# MySQL y MariaDB hacen lo mismo con otra escala: `AVG` de un `DECIMAL` suma
# `div_precision_increment` (4) decimales a los de `int * 1.0`, y la media de
# una `int` salia `decimal(16,5)`, 16.93443 -la cifra que se publica en el
# resumen- con dos divergencias falsas en MariaDB 11.8 y MySQL 8.4. Ahi se
# multiplica por `1e0`, un literal `DOUBLE` en cualquier version: `CAST(x AS
# DOUBLE)` existe en MySQL solo desde la 8.0.17. Su `STDDEV_SAMP` ya devuelve
# `DOUBLE`. Las medianas no pasan por aca: promedian uno o dos valores (ver
# `.promedio_mediana_sql_dbi()`).
.es_transact_sql_dbi <- function(senas) {
  length(senas) == 1L && !is.na(senas) &&
    grepl(.dialectos_dbi()$top$patron, senas, perl = TRUE)
}

# La mediana promedia uno o dos valores, y con `* 1.0` la aritmetica decimal
# de MySQL y MariaDB los promedia exactos (ver arriba) mientras la escala
# alcance; un decimal va por la suma de sus centrales (ver
# `.CAMPO_CENTRALES_N_DBI`). No se suma `0e0` despues del `AVG`: sobre doubles
# extremos MySQL puede rechazar esa suma al devolver la fila, aunque el promedio
# simple sea una respuesta valida.
#
# Salvo un `decimal` en T-SQL. Ahi `decimal(p, s) * 1.0` es `decimal(p + 3,
# s + 1)`, y desde `p = 36` pasa de las 38 cifras: SQL Server recorta la escala
# hasta dejar 6 decimales. Medido en SQL Server 2022, con compatibilidad 100 y
# 160 por igual: la mediana de 0,0000001 y 0,0000003 en `decimal(38,7)` daba
# `0`; la de dos valores de 1e-21 en `decimal(38,30)`, 5,0550945e-21 contra
# 5,0550944535e-21. Con compatibilidad menor que 110 no hay `PERCENTILE_CONT`,
# asi que todo `decimal` pasaba por aca. El promedio iba en `FLOAT`, pero con
# compatibilidad 100 el `CAST` de un decimal a `FLOAT` no redondea bien: en
# `decimal(38,30)` y `decimal(38,20)` 868 y 879 de 3.000 valores salian a un ulp
# del doble correcto, que es el que lee el controlador, y 426 de 1.500 medianas
# de pares a un ulp de `median()` (medido en SQL Server 2022; con
# compatibilidad 160, ninguno). Es el caso de PostgreSQL 9.3: la mediana tiene
# que ser el doble que lee el controlador, y aca solo el controlador lo tiene.
# La consulta devuelve la suma de las una o dos filas centrales y cuantas son
# (ver `.CAMPO_CENTRALES_N_DBI`). Los enteros siguen con `* 1.0`, que los
# promedia exactos tambien pasado 2^53.
#
# Y salvo el `float8` de PostgreSQL leido como NUMERIC exacto (`float8send()`,
# antes de la 12 o con `extra_float_digits <= 0`). `AVG()` de ese NUMERIC es
# exacto, pero PostgreSQL lo devuelve redondeado a su escala de division -unas
# 16 cifras- y R lee otro doble. Medido en PostgreSQL 9.3 sobre pares de dobles:
# 427 de 3.000 promedios a un ulp de `median()`, por la CTE de ventanas
# (`dialecto = "portable"`) y por la subconsulta escalar de la muestra. Va el
# mismo promedio que la via de dos consultas: la suma en doble, leida exacta.
#
# La mediana de un decimal en MySQL, MariaDB y SQL Server: la SUMA de las una o
# dos filas centrales, en el tipo de la columna, y cuantas son. `AVG(valor *
# 1.0)` necesita una cifra de escala mas que la columna, y en la escala maxima
# del motor -30 en MySQL 8.4, 38 en MariaDB- se recorta: la mediana de 1e-30 y
# 2e-30 en `DECIMAL(65,30)` daba 2e-30 (medido; MariaDB da 1,5e-30 ahi y el
# mismo 2e-38 en `DECIMAL(65,38)`). La suma no agrega escala y en los dos motores
# no desborda ni con 65 cifras (devuelve 66, medido). En T-SQL la suma de un
# `decimal(p, s)` es `decimal(38, s)`, sin recortar la escala como la resta o el
# producto. El controlador convierte esa suma exacta al doble mas cercano, y
# dividirla por 1 o por 2 en R es exacto: la mediana es el doble mas cercano de
# la exacta. Promediar en R los dobles de cada central -lo que se hacia en
# T-SQL- no lo es: la de 0,10 y 0,20 daba 0,15000000000000002, y es 0,15. En
# T-SQL una suma que no entra en `decimal(38, s)` -dos centrales cerca del tope
# del tipo- desborda, y `ejecutar_mediana()` cae al promedio escalado.
.CAMPO_CENTRALES_N_DBI <- "lupa_mediana_n"

# La mediana que devuelve el motor, o la suma de las centrales dividida por
# cuantas son si la consulta las devolvio asi (ver `.promedio_mediana_sql_dbi()`).
# Sin la cuenta es `.escalar_dbi(conexion, sql, "mediana")`.
.escalar_mediana_dbi <- function(conexion, sql, presupuesto = NULL,
                                 etapa = "mediana") {
  resultado <- .consultar_dbi(conexion, sql, presupuesto, etapa = etapa)
  if (!resultado$ok) {
    return(.adjuntar_medicion_dbi(
      list(ok = FALSE, valor = NULL, motivo = resultado$motivo), resultado
    ))
  }
  mediana <- .valor_campo_dbi(resultado$datos, "mediana")
  cuantas <- if (isTRUE(mediana$ok)) {
    .campo_resultado_dbi(resultado$datos, .CAMPO_CENTRALES_N_DBI)
  } else NA_integer_
  if (!is.na(cuantas)) {
    n <- .numero_dbi(resultado$datos[[cuantas]])
    suma <- .numero_dbi(mediana$valor)
    mediana$valor <- if (is.finite(n) && n %in% c(1, 2) && is.finite(suma)) {
      suma / n
    } else NA_real_
  }
  .adjuntar_medicion_dbi(mediana, resultado)
}

# La regla de la mediana de un decimal, en un solo predicado: la usan la
# consulta (`.promedio_mediana_sql_dbi()`), su lectura (`ejecutar_mediana()`),
# la seleccion de la consolidada y el plan. Vale en T-SQL, MySQL, MariaDB,
# PostgreSQL y DuckDB. En SQL Server desde la compatibilidad 110, PostgreSQL
# desde la 9.4 y DuckDB la mediana de un decimal salia de la consolidada
# (`PERCENTILE_CONT`), que interpola en doble: quedaba a un ulp del doble mas
# cercano en 20 de 24 pares medidos, y en DuckDB, ademas, sobre la conversion
# de cada valor de mas de 18 cifras, que no es la mas cercana. Por la suma de
# las centrales cuesta una consulta por columna decimal: el perfil por omision
# de un millon de filas con tres decimales tardo 2,0 % mas en PostgreSQL 16,
# 3,3 % mas en SQL Server y lo mismo en DuckDB. SQLite guarda un decimal como
# REAL: su suma es la de dos dobles, que es lo que ya promedia. `money` de SQL
# Server entra con su codigo ODBC (`3`) o con su nombre; el de PostgreSQL no,
# que RPostgres lee como `0` y se lee convertido.
.mediana_decimal_por_centrales_dbi <- function(senas, tipo) {
  if (.es_transact_sql_dbi(senas) && .moneda_sqlserver_dbi(tipo)) return(TRUE)
  if (!.tipo_declarado_decimal_dbi(tipo)) return(FALSE)
  .es_transact_sql_dbi(senas) || .es_mysql_dbi(senas) ||
    (length(senas) == 1L && !is.na(senas) &&
       grepl("postgres|pqconnection|duckdb", senas, useBytes = TRUE))
}

# `money` o `smallmoney` de SQL Server: el controlador da el codigo ODBC `3`
# (`SQL_DECIMAL`; `decimal` y `numeric` dan `2` o, por el catalogo, su nombre
# con precision y escala), o el nombre.
.moneda_sqlserver_dbi <- function(tipo) {
  if (is.null(tipo) || !length(tipo) || is.na(tipo[[1L]])) return(FALSE)
  .minusculas_ascii(trimws(as.character(tipo[[1L]]))) %in%
    c("3", "money", "smallmoney")
}

.promedio_mediana_sql_dbi <- function(conexion, valor, tipo = NA_character_,
                                      doble_exacto = FALSE) {
  senas <- .senas_conexion_dbi(conexion)
  if (.mediana_decimal_por_centrales_dbi(senas, tipo)) {
    suma <- paste0("SUM(", valor, ")")
    # La suma de dos `DECIMAL` de DuckDB es un `DECIMAL(38, s)`, y el
    # controlador lo convierte a un doble que no es el mas cercano (medido con
    # duckdb 2.0: 85 de 300 sumas de `DECIMAL(38,20)`, 30 de 300 de
    # `DECIMAL(18,2)`); su conversion de texto a doble si lo es (2.700 de
    # 2.700). PostgreSQL y SQL Server entregan la suma como el doble mas cercano
    # (1.600 de 1.600 en cada uno, hasta `(38,30)`).
    if (grepl("duckdb", senas, useBytes = TRUE)) {
      suma <- paste0("CAST(CAST(", suma, " AS VARCHAR) AS DOUBLE)")
    }
    # La suma de dos `money` es `money` y desborda cerca de su tope (dos
    # centrales de 8e14: "Arithmetic overflow error converting expression to
    # data type money"), y odbc la lee a un doble que no es el mas cercano (25
    # de 300 sumas). En `decimal(38,4)`, que guarda las cuatro cifras, ni una
    # cosa ni la otra (300 de 300).
    if (.es_transact_sql_dbi(senas) && .moneda_sqlserver_dbi(tipo)) {
      suma <- paste0("SUM(CAST(", valor, " AS DECIMAL(38,4)))")
    }
    # Quien llama agrega ` AS <alias>`: la suma sale con el alias de la mediana
    # y la cuenta con el suyo (ver `.CAMPO_CENTRALES_N_DBI`).
    return(paste0(
      "COUNT(", valor, ") AS ",
      .citar_identificador_dbi(conexion, .CAMPO_CENTRALES_N_DBI),
      ", ", suma
    ))
  }
  if (isTRUE(doble_exacto) &&
      grepl("postgres|pqconnection", .senas_conexion_dbi(conexion),
            useBytes = TRUE)) {
    return(.promedio_centrales_float8_exacto_sql_dbi(valor))
  }
  if (.es_mysql_dbi(.senas_conexion_dbi(conexion))) {
    paste0("AVG(", valor, " * 1.0)")
  } else {
    paste0("AVG(", valor, " * 1.0)")
  }
}

# El promedio de una o dos centrales `float8` leidas como NUMERIC exacto. La
# suma se hace en doble -la de `median()`- y vuelve leida por sus ocho bytes,
# porque PostgreSQL 9.3 escribe el doble con 15 cifras; con extremos se suma la
# mitad de cada NUMERIC, que no desborda aunque las dos centrales sean DBL_MAX.
.promedio_centrales_float8_exacto_sql_dbi <- function(valor) {
  media_binaria <- paste0(
    "SUM(CAST(", valor, " AS DOUBLE PRECISION)) / COUNT(*)"
  )
  paste0(
    "CASE WHEN MAX(ABS(CAST(", valor,
    " AS DOUBLE PRECISION))) > 1e150 THEN ",
    "CASE WHEN COUNT(*) = 2 THEN SUM(CAST(", valor,
    " AS NUMERIC) / 2) ELSE MAX(CAST(", valor,
    " AS NUMERIC)) END ELSE ",
    .lectura_double_postgresql_dbi(media_binaria),
    " END"
  )
}

.es_mysql_dbi <- function(senas) {
  length(senas) == 1L && !is.na(senas) &&
    grepl("mysql|mariadb", senas, perl = TRUE)
}

.es_conexion_mysql_dbi <- function(conexion) {
  inherits(conexion, c("MySQLConnection", "MariaDBConnection"))
}

# RMySQL conserva un conteo exacto si recibe texto; convertir el DECIMAL de
# `SUM()` o el BIGINT sin signo a doble perderia cifras por encima de 2^53.
# MariaDB recibe la misma forma y publica las mismas cifras, sin advertir.
.conteo_sql_dbi <- function(expresion, senas = "") {
  if (.es_mysql_dbi(senas)) paste0("CAST(", expresion, " AS CHAR)") else
    expresion
}

# Cuantos valores no nulos tiene una columna: UNA expresion para todos los
# motores y todas las consultas que lo cuentan -la compartida, la por columna,
# la de lotes de distintos, la del desvio y la de la mediana escalar-.
# `COUNT(col)` no sirve en SQL Server en dos casos medidos:
#
# * sobre `text`, `ntext` e `image` es invalido ("Operand data type text is
#   invalid for count operator"), y la completitud de esas columnas quedaba
#   `no_disponible` aunque el motor sabe contar sus nulos;
# * con enmascaramiento dinamico (DDM), `COUNT(col)` de una columna enmascarada
#   sale enmascarado -0-, y el resumen publicaba 400 de 400 faltantes en
#   columnas completas.
#
# En PostgreSQL se usa `COUNT(col)`: asi un valor compuesto cuyos campos sean
# todos nulos no se confunde con un valor SQL nulo. En los motores
# que no admiten `COUNT(col)` sobre tipos LOB se conserva la expresion CASE, que
# pregunta solo por el nulo SQL y no publica el valor enmascarado.
.contar_no_nulos_sql_dbi <- function(columna_sql, senas = "") {
  expresion <- if (grepl("postgres|pqconnection", senas, useBytes = TRUE)) {
    paste0("COUNT(", columna_sql, ")")
  } else {
    paste0("COUNT(CASE WHEN ", columna_sql,
           " IS NULL THEN NULL ELSE 1 END)")
  }
  .conteo_sql_dbi(expresion, senas)
}

.es_lectura_double_exacta_dbi <- function(expr) {
  length(expr) == 1L && !is.na(expr) &&
    grepl("float8send(", as.character(expr), fixed = TRUE, useBytes = TRUE)
}

# `float8` y `double precision` son el tipo del motor, venga del controlador que
# venga. `double` es como RPostgres declara esa misma columna -la clase de R-, y
# solo dice float8 en una conexion de RPostgres: en cualquier otra conexion que
# hable PostgreSQL (una simulada, odbc) puede ser otra cosa.
.tipo_declarado_float8_dbi <- function(tipo, conexion = NULL) {
  if (is.null(tipo) || !length(tipo) || is.na(tipo[[1L]])) return(FALSE)
  tipo <- .minusculas_ascii(trimws(as.character(tipo[[1L]])))
  tipo %in% c("float8", "double precision") ||
    (identical(tipo, "double") && inherits(conexion, "PqConnection"))
}

.abs_sql_seguro_dbi <- function(conexion, expr) {
  senas <- .senas_conexion_dbi(conexion)
  tipo <- if (grepl("postgres|pqconnection", senas, useBytes = TRUE)) {
    "NUMERIC"
  } else if (grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas,
    perl = TRUE, useBytes = TRUE
  )) {
    "FLOAT"
  } else if (.es_mysql_dbi(senas)) {
    "DOUBLE"
  } else {
    "DOUBLE"
  }
  paste0("ABS(CAST(", expr, " AS ", tipo, "))")
}

.media_sql_dbi <- function(expr, senas = "", tabla_sql = NULL,
                            float8_seguro = FALSE,
                            infinitos_como_numeric = FALSE) {
  if (isTRUE(float8_seguro) &&
      grepl("postgres|pqconnection", senas, useBytes = TRUE) &&
      length(tabla_sql) == 1L && !is.na(tabla_sql) && nzchar(tabla_sql)) {
    lectura_numeric <- isTRUE(infinitos_como_numeric) ||
      .es_lectura_double_exacta_dbi(expr)
    finitos <- if (lectura_numeric) {
      paste0(
        expr, " NOT IN (CAST('NaN' AS NUMERIC),",
        "CAST('1e309' AS NUMERIC),",
        "CAST('-1e309' AS NUMERIC))"
      )
    } else {
      paste0(
        expr, " NOT IN (CAST('NaN' AS DOUBLE PRECISION),",
        "CAST('Infinity' AS DOUBLE PRECISION),",
        "CAST('-Infinity' AS DOUBLE PRECISION))"
      )
    }
    expresion_numeric <- if (lectura_numeric) {
      as.character(expr)
    } else {
      # CAST de float8 a NUMERIC redondea a 15 cifras. Decodificar los bits
      # primero conserva el valor binario que R recibio, incluidos los extremos.
      .lectura_double_postgresql_dbi(expr)
    }
    return(paste0(
      "SUM(CASE WHEN ", finitos, " THEN ", expresion_numeric,
      " ELSE 0 END) / NULLIF(SUM(CASE WHEN ", finitos,
      " THEN 1 ELSE 0 END), 0)"
    ))
  }
  if (.es_transact_sql_dbi(senas)) {
    paste0("AVG(CAST(", expr, " AS FLOAT))")
  } else if (.es_mysql_dbi(senas)) {
    paste0("AVG(", expr, " * 1e0)")
  } else {
    paste0("AVG(", expr, " * 1.0)")
  }
}

# SQL Server puede rechazar la consulta de basicos completa cuando el AVG de
# una columna FLOAT desborda al acumular la suma. La consulta normal se conserva
# para no cambiar la tabla comun; este camino solo se emite despues de ese
# rechazo. La escala se calcula en una relacion aparte porque T-SQL no permite
# anidar MAX dentro de AVG.
.basicos_columna_escalado_sqlserver_dbi <- function(
    conexion, tabla_sql, columna_sql, alias, incluir_valores,
    presupuesto = NULL, metadatos = NULL, tipo = NA_character_) {
  senas <- .senas_conexion_dbi(conexion)
  es_sqlserver <- grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas,
    perl = TRUE, useBytes = TRUE
  )
  limpio <- if (length(tipo) == 1L && !is.na(tipo)) {
    .minusculas_ascii(trimws(as.character(tipo)))
  } else NA_character_
  es_flotante <- length(limpio) == 1L && !is.na(limpio) && (
    grepl("^(float|real|double)(\\([0-9]+\\))?$", limpio, perl = TRUE) ||
      limpio %in% c("6", "8")
  )
  if (!es_sqlserver || !es_flotante) return(NULL)
  escala_tabla_alias <- alias("lupa_escala")
  escala_alias <- alias("escala")
  maximo_alias <- alias("maximo")
  subconsulta_maximo <- paste0(
    "(SELECT MAX(ABS(CAST(", columna_sql, " AS FLOAT))) AS ",
    maximo_alias, " FROM ", tabla_sql, ") AS ", alias("lupa_maximo")
  )
  escala_subconsulta <- paste0(
    "(SELECT CASE WHEN ", maximo_alias, " = 0 THEN 2e0 ELSE ",
    "POWER(2e0, FLOOR(LOG(", maximo_alias, ", 2e0)) - 1) END AS ",
    escala_alias, " FROM ", subconsulta_maximo, ") AS ",
    escala_tabla_alias
  )
  escala <- paste0(escala_tabla_alias, ".", escala_alias)
  partes <- c(
    if (incluir_valores) paste0("MIN(", columna_sql, ") AS ", alias("minimo")),
    if (incluir_valores) paste0("MAX(", columna_sql, ") AS ", alias("maximo")),
    paste0(
      "AVG(CAST(", columna_sql, " AS FLOAT) / NULLIF(", escala,
      ", 0)) * ", escala, " AS ", alias("media")
    ),
    paste0(
      "SUM(CASE WHEN ", columna_sql, " = 0 THEN 1 ELSE 0 END) AS ",
      alias("n_ceros")
    ),
    paste0(
      "SUM(CASE WHEN ", columna_sql, " < 0 THEN 1 ELSE 0 END) AS ",
      alias("n_negativos")
    )
  )
  sql <- paste0(
    "SELECT ", paste(partes, collapse = ", "), " FROM ", tabla_sql,
    " CROSS JOIN ", escala_subconsulta, " GROUP BY ", escala
  )
  resultado <- .consultar_dbi(
    conexion, sql, presupuesto, etapa = "basicos"
  )
  resultado$sql <- sql
  resultado$metadatos <- metadatos
  resultado
}

.basicos_columna_dbi <- function(conexion, tabla_sql, columna_sql, alias,
                                 incluir_valores, presupuesto = NULL,
                                 metadatos = NULL, float8_seguro = FALSE,
                                 infinitos_como_numeric = FALSE,
                                 tipo = NA_character_) {
  senas <- .senas_conexion_dbi(conexion)
  parte_media <- paste0(.media_sql_dbi(
    columna_sql, senas, tabla_sql = tabla_sql,
    float8_seguro = float8_seguro,
    infinitos_como_numeric = infinitos_como_numeric
  ), " AS ", alias("media"))
  partes <- c(
    if (incluir_valores) paste0("MIN(", columna_sql, ") AS ", alias("minimo")),
    if (incluir_valores) paste0("MAX(", columna_sql, ") AS ", alias("maximo")),
    if (!incluir_valores) paste0("MIN(", columna_sql, ") AS ", alias("minimo")),
    if (!incluir_valores) paste0("MAX(", columna_sql, ") AS ", alias("maximo")),
    if (!incluir_valores) paste0(
      "MAX(", .abs_sql_seguro_dbi(conexion, columna_sql),
      ") AS ", alias("maximo_abs")
    ),
    if (!incluir_valores) paste0(
      "MIN(", .abs_sql_seguro_dbi(conexion, columna_sql),
      ") AS ", alias("minimo_abs")
    ),
    parte_media,
    paste0(
      .conteo_sql_dbi(
        paste0("SUM(CASE WHEN ", columna_sql, " = 0 THEN 1 ELSE 0 END)"),
        senas
      ), " AS ",
      alias("n_ceros")
    ),
    paste0(
      .conteo_sql_dbi(
        paste0("SUM(CASE WHEN ", columna_sql, " < 0 THEN 1 ELSE 0 END)"),
        senas
      ), " AS ",
      alias("n_negativos")
    )
  )
  sql <- paste0("SELECT ", paste(partes, collapse = ", "), " FROM ", tabla_sql)
  resultado <- .consultar_dbi(
    conexion, sql, presupuesto, etapa = "basicos"
  )
  if (!isTRUE(resultado$ok) && grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas,
    perl = TRUE, useBytes = TRUE
  )) {
    # SQL Server puede desbordar `AVG(FLOAT)` al sumar una columna de valores
    # extremos, aunque MIN, MAX y cada valor individual sean representables.
    # La consulta normal se conserva para columnas comunes; solo despues de su
    # fallo se obtiene la magnitud y se repite esta columna con una media
    # escalada. No se publica la sonda: solo decide el repliegue.
    sonda <- .sonda_magnitud_columna_dbi(
      conexion, tabla_sql, columna_sql, alias, presupuesto
    )
    max_abs <- if (isTRUE(sonda$ok)) {
      .escalar_finito_dbi(sonda$maximo_abs)
    } else NA_real_
    escala <- .escala_desvio_dbi(max_abs)
    if (!is.null(escala)) {
      escala_sql <- .literal_escala_desvio_dbi(escala)
      partes_escaladas <- c(
        paste0("MIN(", columna_sql, ") AS ", alias("minimo")),
        paste0("MAX(", columna_sql, ") AS ", alias("maximo")),
        paste0("MAX(", .abs_sql_seguro_dbi(conexion, columna_sql),
               ") AS ", alias("maximo_abs")),
        paste0("MIN(", .abs_sql_seguro_dbi(conexion, columna_sql),
               ") AS ", alias("minimo_abs")),
        paste0(
          "AVG(CAST(", columna_sql, " AS FLOAT) / NULLIF(", escala_sql,
          ", 0)) * ", escala_sql, " AS ", alias("media")
        ),
        paste0(
          "SUM(CASE WHEN ", columna_sql, " = 0 THEN 1 ELSE 0 END) AS ",
          alias("n_ceros")
        ),
        paste0(
          "SUM(CASE WHEN ", columna_sql, " < 0 THEN 1 ELSE 0 END) AS ",
          alias("n_negativos")
        )
      )
      sql_escalado <- paste0(
        "SELECT ", paste(partes_escaladas, collapse = ", "),
        " FROM ", tabla_sql
      )
      escalado <- .consultar_dbi(
        conexion, sql_escalado, presupuesto, etapa = "basicos_escalados"
      )
      escalado$sql <- sql_escalado
      escalado$metadatos <- metadatos
      if (isTRUE(escalado$ok)) return(escalado)
    }
  }
  resultado$sql <- sql
  resultado$metadatos <- metadatos
  if (!isTRUE(resultado$ok)) {
    escalado <- .basicos_columna_escalado_sqlserver_dbi(
      conexion, tabla_sql, columna_sql, alias, incluir_valores, presupuesto,
      metadatos, tipo = tipo
    )
    if (is.list(escalado) && isTRUE(escalado$ok)) return(escalado)
  }
  # Los basicos son una sola consulta, y si el promedio desborda -en DuckDB,
  # `HUGEINT * 1.0` es un `DECIMAL(38, 1)` que no guarda un valor desde 10^37;
  # `UHUGEINT` ni entra en `DECIMAL(38, 0)` ("Could not cast value")- el motor
  # la rechaza entera: el minimo, el maximo y los conteos, que calcula sin
  # desbordar, caian con la media, con el error del motor por motivo, y ese
  # error cita el valor de la celda aun con `incluir_valores = FALSE`. Se repite
  # sin el promedio; la media queda `no_disponible` con su propio motivo
  # (`media_desbordada`) y lo demas sigue la regla de siempre.
  desborde_media <- .es_desborde_motor_dbi(resultado$motivo) || grepl(
    "could not cast value", .minusculas_ascii(as.character(
      resultado$motivo %||% ""
    )), fixed = TRUE, useBytes = TRUE
  )
  if (!isTRUE(resultado$ok) && isTRUE(desborde_media)) {
    sql_sin_media <- paste0(
      "SELECT ", paste(setdiff(partes, parte_media), collapse = ", "),
      " FROM ", tabla_sql
    )
    sin_media <- .consultar_dbi(
      conexion, sql_sin_media, presupuesto, etapa = "basicos"
    )
    if (isTRUE(sin_media$ok) && is.data.frame(sin_media$datos) &&
        nrow(sin_media$datos)) {
      sin_media$sql <- sql_sin_media
      sin_media$metadatos <- metadatos
      sin_media$media_desbordada <- list(
        ok = FALSE, sql = sql, metadatos = metadatos,
        motivo = .MOTIVO_MEDIA_DESBORDADA_DBI
      )
      return(sin_media)
    }
  }
  resultado
}

.MOTIVO_MEDIA_ESCALADA_MUESTRA_DBI <- paste(
  "La magnitud de la columna pide la media escalada, que se calcula en otra",
  "consulta; bajo la muestra del motor esa consulta sortear\u00eda otra",
  "muestra, y la media no se publica."
)

.MOTIVO_DESVIO_ESCALADO_MUESTRA_DBI <- paste(
  "La magnitud de la columna pide el desv\u00edo escalado, que se calcula en",
  "otra consulta; bajo la muestra del motor esa consulta sortear\u00eda otra",
  "muestra, y el desv\u00edo no se publica."
)

.MOTIVO_MEDIA_DESBORDADA_DBI <- paste(
  "El motor desbord\u00f3 al promediar la columna: la media no se publica como",
  "calculada. M\u00ednimo, m\u00e1ximo y conteos se pidieron en una consulta sin",
  "el promedio."
)

.sonda_magnitud_columna_dbi <- function(conexion, tabla_sql, columna_sql,
                                        alias, presupuesto = NULL) {
  # `MAX` y no `MIN`: el valor que delata que la columna no es de la magnitud
  # que se supone queda AL FINAL del orden en los motores que importan. En
  # duckdb y PostgreSQL `NaN` es mayor que todo numero, y con `MIN` una columna
  # con `NaN` pasaba la sonda y la mediana se calculaba contandolo; en SQLite el
  # texto se ordena despues de los numeros, asi que `MIN` de una columna INTEGER
  # con texto devolvia un numero y tampoco lo veia.
  #
  # Y `MIN` en la misma consulta: un `-Inf` queda al PRINCIPIO del orden, y
  # sin el la mediana se calculaba contandolo -ver `.es_infinito_motor_dbi()`-.
  sql <- paste0(
    "SELECT ", paste(
      .expresiones_sonda_magnitud_dbi(conexion, columna_sql, "magnitud", alias),
      collapse = ", "
    ),
    " FROM ", tabla_sql
  )
  consulta <- .consultar_dbi(
    conexion, sql, presupuesto, etapa = "sonda_magnitud"
  )
  resultado <- .leer_sonda_magnitud_dbi(consulta, "magnitud")
  resultado$sql <- sql
  resultado
}

# Las expresiones de la sonda de magnitud, con alias `<base>`,
# `<base>_minima`, `<base>_maxima_abs`, `<base>_minima_abs` y
# `<base>_n_validos`: la sentencia propia de la sonda y, bajo la muestra del
# motor, el lote de agregados (ver `.agregados_lote_con_biseccion_dbi()`), que
# las lleva para que la magnitud y la cuenta salgan de la misma muestra que el
# desvio.
.expresiones_sonda_magnitud_dbi <- function(conexion, columna_sql, base,
                                            alias) {
  c(
    paste0("MAX(", columna_sql, ") AS ", alias(base)),
    paste0("MIN(", columna_sql, ") AS ", alias(paste0(base, "_minima"))),
    paste0(
      "MAX(", .abs_sql_seguro_dbi(conexion, columna_sql), ") AS ",
      alias(paste0(base, "_maxima_abs"))
    ),
    paste0(
      "MIN(", .abs_sql_seguro_dbi(conexion, columna_sql), ") AS ",
      alias(paste0(base, "_minima_abs"))
    ),
    paste0("COUNT(", columna_sql, ") AS ", alias(paste0(base, "_n_validos")))
  )
}

.leer_sonda_magnitud_dbi <- function(consulta, base) {
  if (!isTRUE(consulta$ok)) {
    return(.adjuntar_medicion_dbi(
      list(ok = FALSE, valor = NULL, motivo = consulta$motivo), consulta
    ))
  }
  resultado <- .adjuntar_medicion_dbi(
    .valor_campo_dbi(consulta$datos, base), consulta
  )
  minima <- .valor_campo_dbi(consulta$datos, paste0(base, "_minima"))
  resultado$minimo <- if (isTRUE(minima$ok)) minima$valor else NULL
  max_abs <- .valor_campo_dbi(consulta$datos, paste0(base, "_maxima_abs"))
  min_abs <- .valor_campo_dbi(consulta$datos, paste0(base, "_minima_abs"))
  n_validos <- .valor_campo_dbi(consulta$datos, paste0(base, "_n_validos"))
  resultado$maximo_abs <- if (isTRUE(max_abs$ok)) max_abs$valor else NULL
  resultado$minimo_abs <- if (isTRUE(min_abs$ok)) min_abs$valor else NULL
  resultado$n_validos <- if (isTRUE(n_validos$ok)) n_validos$valor else NULL
  resultado
}

# El desvio no cambia si a cada valor se le resta una constante, y restarle una
# cercana a la media evita la cancelacion: `STDEV` de SQL Server -y el
# `STDDEV_SAMP` de SQLite, duckdb, MariaDB y MySQL, en menor medida- acumula en
# una sola pasada, y cuando la media es grande frente al ancho de la columna
# pierde las cifras del desvio. Medido sobre 61 marcas de
# tiempo en milisegundos de una ventana de un segundo, `1760000000000 +
# runif(61, 0, 1000)`: SQL Server publicaba desvio `0` contra 314,77, sin aviso;
# los otros cuatro, 4,5e-8 relativo. `centro` es la media ya calculada -un
# numero, o el literal SQL que arma `.literal_centro_desvio_dbi()`-, y con el
# las tres formas operan sobre `(columna - centro)`. Como se resta lo decide el
# tipo declarado de la columna: ver `.resta_centrada_dbi()`.
.soporta_ventana_desvio_dbi <- function(conexion) {
  senas <- .senas_conexion_dbi(conexion)
  grepl(
    "postgres|pqconnection|sql server|microsoft sql|sqlserver|mssql|mysql|mariadb|sqlite|duckdb",
    senas, perl = TRUE, useBytes = TRUE
  )
}

.forma_desvio_ventana_dbi <- function(conexion) {
  senas <- .senas_conexion_dbi(conexion)
  if (grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas,
    perl = TRUE, useBytes = TRUE
  )) return(2L)
  if (grepl("sqlite", senas, perl = TRUE, useBytes = TRUE)) return(3L)
  1L
}

# La media de la ventana conserva las mismas promociones que `.media_sql_dbi()`.
.media_ventana_sql_dbi <- function(expr, senas = "", float8_seguro = FALSE,
                                   infinitos_como_numeric = FALSE) {
  if (isTRUE(float8_seguro) &&
      grepl("postgres|pqconnection", senas, useBytes = TRUE)) {
    lectura_numeric <- isTRUE(infinitos_como_numeric) ||
      .es_lectura_double_exacta_dbi(expr)
    expresion <- if (lectura_numeric) expr else {
      .lectura_double_postgresql_dbi(expr)
    }
    return(paste0("AVG(", expresion, ") OVER ()"))
  }
  if (.es_transact_sql_dbi(senas)) {
    paste0("AVG(CAST(", expr, " AS FLOAT)) OVER ()")
  } else if (.es_mysql_dbi(senas)) {
    paste0("AVG(", expr, " * 1e0) OVER ()")
  } else {
    paste0("AVG(", expr, " * 1.0) OVER ()")
  }
}

.formas_desvio_dbi <- function(tabla_sql, columna_sql, alias, senas = "",
                               centro = NULL, centro_sql = NULL,
                               tipo = NA_character_, numeric_exact = FALSE,
                               infinitos_como_numeric = FALSE,
                               escala_sql = NULL,
                               centro_escalado_sql = NULL,
                               columna_escalada = FALSE,
                               centro_en_ventana = FALSE) {
  numeric_exact <- isTRUE(numeric_exact) &&
    grepl("postgres|pqconnection", senas, useBytes = TRUE)
  resta <- .resta_centrada_dbi(tipo, senas)
  sqlserver <- grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas,
    perl = TRUE, useBytes = TRUE
  )
  mysql <- .es_mysql_dbi(senas)
  postgres <- grepl("postgres|pqconnection", senas, useBytes = TRUE)
  escala_habilitada <- length(escala_sql) == 1L &&
    !is.na(escala_sql) && nzchar(escala_sql)
  pg_double <- grepl("postgres|pqconnection", senas, useBytes = TRUE) &&
    !numeric_exact &&
    length(tipo) == 1L && !is.na(tipo) &&
    .minusculas_ascii(as.character(tipo)) %in% c(
      "double", "float8", "double precision"
    )
  if (is.numeric(centro)) {
    centro <- .literal_centro_desvio_dbi(
      centro, flotante = resta$literal_flotante || escala_habilitada,
      digitos = if (pg_double || numeric_exact || mysql) 17L else 15L,
      sin_empate = sqlserver && .tipo_declarado_decimal_dbi(tipo)
    )
  }
  centro_sql <- if (length(centro_sql) == 1L && !is.na(centro_sql) &&
                    nzchar(centro_sql)) as.character(centro_sql) else NULL
  centro_escalado_sql <- if (
    length(centro_escalado_sql) == 1L && !is.na(centro_escalado_sql) &&
    nzchar(centro_escalado_sql)
  ) as.character(centro_escalado_sql) else NULL
  centro <- if (length(centro) == 1L && !is.na(centro) && nzchar(centro)) {
    as.character(centro)
  } else NULL
  centro_efectivo <- if (escala_habilitada) {
    centro_sql %||% centro
  } else if (isTRUE(centro_en_ventana)) {
    centro_sql %||% centro
  } else if (sqlserver || mysql) {
    # La forma escalar de estos motores no anida un AVG() en la expresion
    # agregada; la ventana, en cambio, ya expuso el centro como una columna.
    centro
  } else {
    centro_sql %||% centro
  }
  if (length(centro_efectivo) == 1L && !escala_habilitada) {
    operando <- if (numeric_exact) {
      paste0("CAST(", columna_sql, " AS NUMERIC)")
    } else if (pg_double) {
      paste0("CAST(", columna_sql, " AS DOUBLE PRECISION)")
    } else if (is.na(resta$conversion)) columna_sql else {
      paste0("CAST(", columna_sql, " AS ", resta$conversion, ")")
    }
    columna_sql <- paste0("(", operando, " - ", centro_efectivo, ")")
  }
  if (escala_habilitada) {
    escala_factor <- as.character(escala_sql)
    escala_salida <- paste0("MAX(", escala_factor, ")")
    tipo_flotante <- .tipo_flotante_escala_desvio_dbi(senas)
    columna_desvio <- if (isTRUE(columna_escalada)) columna_sql else {
      paste0(
        "(CAST(", columna_sql, " AS ", tipo_flotante,
        ") / NULLIF(", escala_factor, ", 0))"
      )
    }
    if (length(centro_escalado_sql) == 1L) {
      columna_desvio <- paste0(
        "(", columna_desvio, " - ", centro_escalado_sql, ")"
      )
    } else if (length(centro_efectivo) == 1L) {
      columna_desvio <- paste0(
        "(", columna_desvio, " - (", centro_efectivo, " / NULLIF(",
        escala_factor, ", 0)))"
      )
    }
  } else {
    columna_desvio <- columna_sql
    escala_salida <- NULL
  }
  media_expr <- if (pg_double) {
    paste0("AVG(CAST(", columna_desvio, " AS DOUBLE PRECISION))")
  } else .media_sql_dbi(
    columna_desvio, senas, infinitos_como_numeric = infinitos_como_numeric ||
      numeric_exact
  )
  media_sql <- if (isTRUE(centro_en_ventana)) NULL else {
    paste0("(SELECT ", media_expr, " FROM ", tabla_sql, ")")
  }
  # PostgreSQL calcula `STDDEV_SAMP` de un `numeric` -`int * 1.0`- con cuatro
  # decimales cuando la magnitud es grande: sobre 61 enteros de unos nueve
  # millones daba 8956265.3453 contra 8956265.3453457393, y la corroboracion
  # declaraba `divergencia` en el desvio (la misma construccion que la media de
  # SQL Server, ver `.media_sql_dbi()`). Ahi se pide como doble. `STDEV` de SQL
  # Server ya devuelve `float`.
  desvio_muestral <- if (numeric_exact) {
    paste0("STDDEV_SAMP(CAST(", columna_desvio, " AS NUMERIC))")
  } else if (grepl("postgres|pqconnection", senas, useBytes = TRUE)) {
    paste0("STDDEV_SAMP(CAST(", columna_desvio, " AS DOUBLE PRECISION))")
  } else {
    paste0("STDDEV_SAMP(", columna_desvio, " * ",
           if (mysql) "1e0" else "1.0", ")")
  }
  if (escala_habilitada) {
    desvio_muestral <- paste0(desvio_muestral, " * ", escala_salida)
  }
  # El resultado de `STDDEV_SAMP(double precision)` tambien viaja como double.
  # PostgreSQL 9.3 con `extra_float_digits <= 0` lo serializa con 15 cifras,
  # aunque el calculo del motor sea correcto; devolver sus bits como NUMERIC
  # conserva el mismo valor que la lectura de la columna y la muestra.
  desvio_muestral_publico <- if (grepl("postgres|pqconnection", senas,
                                        useBytes = TRUE) &&
                               !numeric_exact) {
    .lectura_double_postgresql_dbi(desvio_muestral)
  } else {
    desvio_muestral
  }
  list(
    paste0(desvio_muestral_publico, " AS ", alias("desvio")),
    paste0(
      if ((mysql || postgres) && escala_habilitada) {
        "STDDEV_SAMP(CAST("
      } else "STDEV(CAST(",
      columna_desvio, " AS ", if (mysql) "DOUBLE))" else "FLOAT))",
      if (escala_habilitada) paste0(" * ", escala_salida) else "",
      " AS ", alias("desvio")
    ),
    if (isTRUE(centro_en_ventana)) {
      # La media de la ventana es un doble y no la media exacta: sus cuadrados
      # suman ademas `n * (media - centro)^2`, que se resta (las dos pasadas
      # corregidas). Sin la resta, en SQLite por la muestra del motor el desvio
      # de 2^53 - 2 y 2^53 - 1 salia 1, y es 0,7071: la media redondeada cae en
      # uno de los dos.
      conteo <- .contar_no_nulos_sql_dbi(columna_desvio, senas)
      suma_cuadrados <- paste0(
        "(SUM((", columna_desvio, ") * (", columna_desvio, ")) - SUM(",
        columna_desvio, ") * SUM(", columna_desvio, ") / ", conteo, ")"
      )
      paste0(
        "SQRT(CASE WHEN ", suma_cuadrados, " < 0 THEN 0 ELSE ",
        suma_cuadrados, " END / (", conteo, " - 1.0))",
        if (escala_habilitada) paste0(" * ", escala_salida) else "",
        " AS ", alias("desvio")
      )
    } else {
      paste0(
        "SQRT(SUM((", columna_desvio, " - ", media_sql, ") * (",
        columna_desvio, " - ", media_sql, ")) / (",
        .contar_no_nulos_sql_dbi(columna_desvio, senas), " - 1.0))",
        if (escala_habilitada) paste0(" * ", escala_salida) else "",
        " AS ", alias("desvio")
      )
    }
  )
}

.desvio_columna_dbi <- function(conexion, tabla_sql, columna_sql, alias,
                                forma, presupuesto = NULL, metadatos = NULL,
                                centro = NULL, tipo = NA_character_,
                                numeric_exact = FALSE,
                                infinitos_como_numeric = FALSE,
                                forzar_escalado = FALSE,
                                escala = NULL) {
  centro <- suppressWarnings(as.numeric(centro))
  senas <- .senas_conexion_dbi(conexion)
  sqlserver <- grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas,
    perl = TRUE, useBytes = TRUE
  )
  if (isTRUE(forzar_escalado)) {
    return(.desvio_columna_escalado_sqlserver_dbi(
      conexion, tabla_sql, columna_sql, alias, forma, presupuesto, metadatos,
      tipo = tipo,
      infinitos_como_numeric = infinitos_como_numeric, escala = escala
    ))
  }
  centro_valido <- length(centro) == 1L && is.finite(centro)
  if (!centro_valido && sqlserver) {
    sql_centro <- paste0(
      "SELECT ", .media_sql_dbi(
        columna_sql, senas,
        infinitos_como_numeric = infinitos_como_numeric || numeric_exact
      ), " AS ", alias("centro"),
      " FROM ", tabla_sql
    )
    media <- .escalar_dbi(
      conexion, sql_centro, "centro", presupuesto, etapa = "media_desvio"
    )
    if (isTRUE(media$ok)) {
      centro <- suppressWarnings(as.numeric(media$valor))
      centro_valido <- length(centro) == 1L && is.finite(centro)
    }
  }
  centro_sql <- if (!centro_valido && !sqlserver) {
    paste0(
      "(SELECT ", .media_sql_dbi(
        columna_sql, senas,
        infinitos_como_numeric = infinitos_como_numeric || numeric_exact
      ),
      " FROM ", tabla_sql, ")"
    )
  } else {
    NULL
  }
  formas <- .formas_desvio_dbi(
    tabla_sql, columna_sql, alias, senas,
    centro = if (centro_valido && is.null(centro_sql)) centro else NULL,
    centro_sql = centro_sql, tipo = tipo, numeric_exact = numeric_exact,
    infinitos_como_numeric = infinitos_como_numeric
  )
  sql <- paste0("SELECT ", formas[[forma]], " FROM ", tabla_sql)
  resultado <- .escalar_dbi(
    conexion, sql, "desvio", presupuesto, etapa = "desvio"
  )
  resultado$sql <- sql
  resultado$metadatos <- metadatos
  valor_normal <- suppressWarnings(as.numeric(resultado$valor %||% NA_real_))
  normal_fallo <- !isTRUE(resultado$ok) || length(valor_normal) != 1L ||
    !is.finite(valor_normal)
  # Que dice una consulta fallida depende del motor. En los que ya tenian el
  # repliegue (ver `.motor_escalable_desvio_dbi()`) el desborde es un error:
  # la forma normal sobre magnitudes extremas no devuelve `Inf`, falla, y la
  # respuesta es la forma escalada, que se publica tambien si falla -su motivo
  # es el de la ultima consulta que se intento-. En los demas el desborde
  # vuelve como un valor no finito, y una consulta fallida es un rechazo de la
  # columna: repetirla escalada solo sumaba otra sentencia que falla y cambiaba
  # el motivo publicado. Ahi el recalculo queda para la respuesta no finita.
  repliega_fallida <- .motor_escalable_desvio_dbi(senas, conexion)
  if (normal_fallo && (repliega_fallida || isTRUE(resultado$ok))) {
    escalado <- .desvio_columna_escalado_sqlserver_dbi(
      conexion, tabla_sql, columna_sql, alias, forma, presupuesto, metadatos,
      tipo = tipo,
      infinitos_como_numeric = infinitos_como_numeric, escala = escala
    )
    if (isTRUE(escalado$ok) || repliega_fallida) return(escalado)
  }
  resultado
}

# Los motores que ya escalaban el desvio antes de que la guarda del valor
# cubriera a todos: SQL Server, PostgreSQL, MySQL y MariaDB. En ellos la suma
# de cuadrados que no entra en un doble corta la consulta en vez de devolver un
# valor no finito -SQL Server responde "Arithmetic overflow error converting
# expression to data type float" y PostgreSQL "value out of range: overflow"-,
# asi que el repliegue escalado es ahi la respuesta a una consulta fallida, y
# su camino queda como estaba: ni una sentencia mas ni una falla publicada de
# mas. SQLite y DuckDB devuelven `Inf` -o `0` cuando los cuadrados caen por
# debajo del menor doble- y los cubre la guarda del valor de
# `.resumen_columna_dbi()`, que vale para cualquier motor que no este aca.
#
# Con `conexion`, MySQL y MariaDB cuentan solo por su controlador nativo: es la
# condicion con la que una consulta fallida ya se respondia escalada, y por
# otro controlador las mismas senas no dicen como llega el desborde.
.motor_escalable_desvio_dbi <- function(senas, conexion = NULL) {
  grepl("sql server|microsoft sql|sqlserver|mssql|postgres|pqconnection",
        senas, perl = TRUE, useBytes = TRUE) ||
    (.es_mysql_dbi(senas) &&
       (is.null(conexion) || .es_conexion_mysql_dbi(conexion)))
}

# El tipo de coma flotante al que se convierte la columna antes de dividirla
# por la escala. SQL Server y PostgreSQL lo escriben `FLOAT` -en los dos, el
# doble de 53 bits-, que es como ya lo pedia su forma escalada: el texto de la
# sentencia que publican no cambia. MySQL, MariaDB, SQLite y DuckDB lo llaman
# `DOUBLE`.
.tipo_flotante_escala_desvio_dbi <- function(senas) {
  if (grepl("sql server|microsoft sql|sqlserver|mssql|postgres|pqconnection",
            senas, perl = TRUE, useBytes = TRUE)) "FLOAT" else "DOUBLE"
}

# Repliegue escalado: la forma normal conserva exactamente la consulta enviada.
# Solo si esa forma falla (por ejemplo, STDEV sobre dos extremos de FLOAT) se
# escala por una potencia de dos. El maximo se obtiene en una subconsulta
# separada para no anidar agregados; con una columna toda en cero la escala es 2
# y el resultado sigue siendo cero, nunca `NULL`.
.desvio_columna_escalado_sqlserver_dbi <- function(
    conexion, tabla_sql, columna_sql, alias, forma, presupuesto, metadatos,
    tipo = NA_character_, infinitos_como_numeric = FALSE,
    escala = NULL) {
  senas <- .senas_conexion_dbi(conexion)
  mysql <- .es_mysql_dbi(senas)
  postgres <- grepl("postgres|pqconnection", senas, useBytes = TRUE)
  escala_tabla_alias <- alias("lupa_escala")
  escala_alias <- alias("escala")
  maximo_alias <- alias("maximo")
  tipo_flotante <- .tipo_flotante_escala_desvio_dbi(senas)
  escala_literal <- .literal_escala_desvio_dbi(escala)
  escala_subconsulta <- if (length(escala_literal) == 1L &&
                            !is.na(escala_literal) && nzchar(escala_literal)) {
    paste0("(SELECT ", escala_literal, " AS ", escala_alias, ") AS ",
           escala_tabla_alias)
  } else {
    maximo_sql <- paste0(
      "MAX(ABS(CAST(", columna_sql, " AS ", tipo_flotante, "))) AS ",
      maximo_alias
    )
    subconsulta_maximo <- paste0(
      "(SELECT ", maximo_sql, " FROM ", tabla_sql, ") AS ",
      alias("lupa_maximo")
    )
    paste0(
      "(SELECT CASE WHEN ", maximo_alias, " = 0 THEN 2e0 ELSE ",
      # Restar uno deja margen cuando LOG2(DBL_MAX) redondea a 1024:
      # POWER(2, 1024) desborda aunque DBL_MAX aun sea representable.
      if (mysql) {
        paste0("POWER(2e0, FLOOR(LOG2(", maximo_alias, ")) - 1) END AS ")
      } else if (postgres) {
        paste0(
          "POWER(2::DOUBLE PRECISION, FLOOR(LOG(2e0, CAST(", maximo_alias,
          " AS NUMERIC))) - 1) END AS "
        )
      } else {
        paste0("POWER(2e0, FLOOR(LOG(", maximo_alias, ", 2e0)) - 1) END AS ")
      },
      escala_alias, " FROM ", subconsulta_maximo, ") AS ",
      escala_tabla_alias
    )
  }
  tabla_escalada <- paste0(tabla_sql, " CROSS JOIN ", escala_subconsulta)
  escala_ref <- paste0(escala_tabla_alias, ".", escala_alias)
  # SQL Server no acepta una subconsulta dentro del argumento de STDEV. Se
  # materializa primero la columna ya centrada en una relacion derivada; asi
  # el agregado solo recibe columnas y el centro sigue saliendo de la misma
  # relacion escalada.
  centro_escalado <- paste0(
    "(SELECT AVG(CAST(", columna_sql, " AS ", tipo_flotante,
    ") / NULLIF(", escala_ref, ", 0)) FROM ", tabla_escalada, ")"
  )
  columna_centrada <- alias("lupa_centrada")
  escala_centrada <- alias("lupa_escala_salida")
  tabla_centrada <- paste0(
    "(SELECT (CAST(", columna_sql, " AS ", tipo_flotante,
    ") / NULLIF(", escala_ref, ", 0) - ", centro_escalado,
    ") AS ", columna_centrada, ", ", escala_ref, " AS ", escala_centrada,
    " FROM ", tabla_escalada, ") AS ", alias("lupa_centrada_tabla")
  )
  formas <- .formas_desvio_dbi(
    tabla_centrada, columna_centrada, alias, senas,
    centro = NULL, tipo = tipo, numeric_exact = FALSE,
    infinitos_como_numeric = infinitos_como_numeric,
    escala_sql = escala_centrada, columna_escalada = TRUE
  )
  sql <- paste0(
    "SELECT ", formas[[forma]], " FROM ", tabla_centrada,
    if (mysql) paste0(" GROUP BY ", escala_centrada) else ""
  )
  resultado <- .escalar_dbi(
    conexion, sql, "desvio", presupuesto, etapa = "desvio"
  )
  resultado$sql <- sql
  resultado$metadatos <- metadatos
  valor <- suppressWarnings(as.numeric(resultado$valor %||% NA_real_))
  if (isTRUE(resultado$ok) &&
      (length(valor) != 1L || !is.finite(valor))) {
    resultado$ok <- FALSE
    resultado$motivo <- paste(
      "El motor no devolvi\u00f3 un desv\u00edo finito despu\u00e9s del repliegue escalado."
    )
  }
  resultado
}

# La media como literal SQL para centrar el desvio: quince cifras, punto decimal
# y sin exponente -`formatC(format = "fg")`, como `.decimal_sql_dbi()`-, que
# todos los motores cubiertos leen como numero. No hace falta que sea exacta:
# cualquier constante cercana a la media deja el desvio igual y evita la
# cancelacion. `NULL` si no hay media finita: entonces no se centra.
#
# Con `flotante = TRUE`, en notacion cientifica con 17 cifras -`9.9508248786497116e+02`-,
# que T-SQL lee como `float` y no como `decimal`: un literal decimal no admite
# mas de 38 cifras, y la media de una columna `float` de magnitud 1e40 o 1e-25
# se escribia con 41 o 39 -SQL Server rechazaba la consulta centrada y quedaba,
# sin decirlo, el desvio de una pasada-. Solo para
# columnas de coma flotante: contra un `decimal`, un literal `float` convertiria
# la columna a doble antes de restar. Ver `.resta_centrada_dbi()`.
# En T-SQL, `decimal - literal` no siempre cabe: si la precision pasa de 38, el
# motor recorta la escala del resultado a la que dejan los digitos enteros de
# la columna y redondea. Redondear `v - c` es restar a todos los valores la
# misma constante -el desvio no cambia-, salvo en un empate: desde la
# compatibilidad 110 el empate se redondea lejos del cero, hacia un lado para
# los valores de abajo de la media y hacia el otro para los de arriba. En
# `decimal(38,0)` con 1, 2, 3 y 4 la media 2.5 dejaba -2, -1, 1 y 2, y el desvio
# salia 1,8257 por 1,2910; en `decimal(38,2)`, el par 0.01 y 0.02 daba el doble
# del desvio exacto (medido en SQL Server 2022; con compatibilidad 100 el
# empate va siempre hacia abajo y no pasa). Un empate solo ocurre si lo que se
# recorta del literal es exactamente un 5: con `sin_empate`, un literal con
# decimales que termina en 5 lleva una cifra mas, que no puede empatar. Sigue
# cerca de la media, que es lo unico que el centro necesita.
.literal_centro_desvio_dbi <- function(media, flotante = FALSE, digitos = 15L,
                                       sin_empate = FALSE) {
  media <- suppressWarnings(as.numeric(media))
  if (length(media) != 1L || !is.finite(media)) return(NULL)
  if (isTRUE(flotante)) {
    literal <- .marca_decimal_c(trimws(
      formatC(media, format = "e", digits = 16, decimal.mark = ".")
    ))
    .sumar_centro_motor(literal)
    return(literal)
  }
  # `trimws()`: con `"fg"`, `formatC()` rellena con espacios hasta el ancho de
  # las cifras pedidas.
  literal <- trimws(
    formatC(media, format = "fg", digits = digitos, decimal.mark = ".")
  )
  if (isTRUE(sin_empate) &&
      grepl("^-?[0-9]*\\.[0-9]*5$", literal, perl = TRUE)) {
    literal <- paste0(literal, "1")
  }
  literal <- .marca_decimal_c(literal)
  .sumar_centro_motor(literal)
  literal
}

# La misma potencia de dos que usa la via local. El umbral se decide con los
# extremos que ya devolvieron los basicos; no se emite una sonda solo para saber
# si hace falta escalar. El rango activa la escala aunque la magnitud sea
# corriente: sus cuadrados pueden caer en subnormales y perder el desvio.
.escala_desvio_dbi <- function(max_abs, forzar = FALSE, rango = NA_real_) {
  # Un `BIGINT UNSIGNED` cerca del tope vuelve del controlador como `integer64`
  # negativo: el mayor valor absoluto se toma en valor absoluto, y un rango
  # negativo -imposible- no decide nada. Sin esto `log2()` recibia un negativo y
  # el perfil soltaba "Se han producido NaNs".
  max_abs <- abs(suppressWarnings(as.numeric(max_abs)))
  rango <- suppressWarnings(as.numeric(rango))
  if (length(rango) == 1L && is.finite(rango) && rango < 0) rango <- NA_real_
  por_dispersion <- .rango_requiere_escala(rango)
  if (length(max_abs) != 1L || !is.finite(max_abs) || max_abs == 0 ||
      (!isTRUE(forzar) && !por_dispersion &&
       max_abs >= 1e-150 && max_abs <= 1e150)) {
    return(NULL)
  }
  base <- if (por_dispersion) rango else max_abs
  exponente <- floor(log2(base)) - 1
  escala <- 2^exponente
  if (!is.finite(escala) || escala == 0) return(NULL)
  escala
}

.literal_escala_desvio_dbi <- function(escala) {
  .literal_centro_desvio_dbi(escala, flotante = TRUE, digitos = 17L)
}

.media_columna_escalada_dbi <- function(
    conexion, tabla_sql, columna_sql, alias, escala, presupuesto = NULL) {
  escala_sql <- .literal_escala_desvio_dbi(escala)
  tipo_flotante <- if (.es_mysql_dbi(.senas_conexion_dbi(conexion))) {
    "DOUBLE"
  } else {
    "FLOAT"
  }
  sql <- paste0(
    "SELECT AVG(CAST(", columna_sql, " AS ", tipo_flotante,
    ") / NULLIF(", escala_sql, ", 0)) * ", escala_sql,
    " AS ", alias("media"), " FROM ", tabla_sql
  )
  resultado <- .escalar_dbi(
    conexion, sql, "media", presupuesto, etapa = "media_escalada"
  )
  resultado$sql <- sql
  valor <- suppressWarnings(as.numeric(resultado$valor %||% NA_real_))
  if (isTRUE(resultado$ok) &&
      (length(valor) != 1L || !is.finite(valor))) {
    resultado$ok <- FALSE
    resultado$motivo <- paste(
      "El motor no devolvi\u00f3 una media finita despu\u00e9s del repliegue escalado."
    )
  }
  resultado
}

# Como se resta el centro, segun el tipo declarado de la columna y el motor.
# En SQL Server la resta toma el tipo de mayor precedencia, y `real` esta por
# encima de `decimal`: `("v" - 995.082487864971)` sobre una columna `real` se
# redondeaba a 24 bits, y el desvio centrado se apartaba 1,44e-8 del de los
# valores guardados -peor que el de una pasada que vino a reemplazar-; la
# corroboracion lo publicaba como `divergencia` y `perfilar_coleccion()` subia
# la tabla a `alcance = "divergencias"`. duckdb hace lo
# mismo con `FLOAT`/`REAL`: medido, 1,44e-8. PostgreSQL, MySQL y MariaDB restan
# un `real` en doble (4e-16), y SQLite no tiene coma flotante simple.
#
# Por eso una columna de coma flotante simple se convierte a doble ANTES de
# restar -la conversion de `real` a doble es exacta-, y en SQL Server el centro
# de toda columna de coma flotante va como literal `float`. Una columna
# `decimal` o entera sigue restando en su tipo, que es exacto: convertirla
# antes perderia cifras en un `decimal(38,10)` de 1e17. El tipo es el que
# publica `dbColumnInfo()`: odbc da el codigo ODBC -7 es `SQL_REAL`, 6 y 8 son
# dobles- y duckdb el nombre que lee `.tipos_declarados_duckdb_dbi()`.
.resta_centrada_dbi <- function(tipo, senas = "") {
  sin_cambio <- list(conversion = NA_character_, literal_flotante = FALSE)
  if (is.null(tipo) || !length(tipo) || is.na(tipo[[1L]])) return(sin_cambio)
  limpio <- gsub("[[:space:]]+", "", .minusculas_ascii(as.character(tipo[[1L]])))
  senas <- paste(as.character(senas), collapse = " ")
  if (grepl("duckdb", senas, fixed = TRUE, useBytes = TRUE)) {
    if (limpio %in% c("float", "real", "float4", "double", "double precision")) {
      return(list(conversion = "DOUBLE", literal_flotante = FALSE))
    }
    return(sin_cambio)
  }
  if (!grepl("sql server|microsoft sql|sqlserver|mssql", senas, perl = TRUE,
             useBytes = TRUE)) {
    return(sin_cambio)
  }
  bits <- if (grepl("^float\\([0-9]+\\)$", limpio, perl = TRUE)) {
    suppressWarnings(as.integer(gsub("[^0-9]", "", limpio)))
  } else {
    NA_integer_
  }
  if (limpio %in% c("7", "real") || isTRUE(bits <= 24L)) {
    return(list(conversion = "FLOAT", literal_flotante = TRUE))
  }
  if (limpio %in% c("6", "8", "float", "double") || isTRUE(bits > 24L)) {
    return(list(conversion = NA_character_, literal_flotante = TRUE))
  }
  sin_cambio
}

# Un decimal que llega como doble ya no es el valor guardado: 500000000000006.60
# es, como doble, 500000000000006.625. El desvio de esos dobles se aparta del de
# los decimales en hasta `max|x| / desvio * 2^-53`, relativo: con valores de
# 5e14 y un desvio de 3, una parte en 500 -medido: 3,1115 por 3,1047 en
# `numeric(18,2)` de PostgreSQL con `bloque_filas`, y lo mismo por la muestra del
# motor en SQL Server, MySQL y MariaDB, que centran en doble-. Por la tabla
# completa el motor resta la media en el tipo de la columna y no pasa. Donde el
# desvio sale de los dobles y ese margen pasa de `.TOLERANCIA_DESVIO_DOBLE_DBI`,
# no se publica como calculado.
#
# Salvo que el tipo diga que esos dobles son los valores: un decimal de escala
# 0 -`numeric(18,0)`, `decimal(38,0)`- guarda enteros, y un entero de valor
# absoluto menor que 2^53 llega exacto al doble; por la monotonia del
# redondeo, si los extremos que llegaron quedan por debajo de 2^53, todos los
# valores tambien. Con `tipo` sin escala -`numeric` a secas, o el codigo `2`
# que da odbc cuando el catalogo no contesta- no se sabe, y la guarda sigue:
# los dobles no dicen si 500000000000006 venia de 500000000000006,0 o de
# 500000000000006,0000001. La escala la publican los catalogos de PostgreSQL
# (`format_type()`), MySQL y MariaDB (`COLUMN_TYPE`) y SQL Server
# (`sys.columns`, ver `.permisos_columnas_dbi()`), y DuckDB en el tipo de la
# via SQL (medido: `DECIMAL(38,0)`).
.TOLERANCIA_DESVIO_DOBLE_DBI <- 1e-9

.desvio_mal_condicionado_dbi <- function(desvio, extremos, tipo = NA_character_) {
  desvio <- suppressWarnings(as.numeric(desvio))
  extremos <- suppressWarnings(as.numeric(extremos))
  extremos <- extremos[is.finite(extremos)]
  if (identical(.escala_declarada_dbi(tipo), 0L) && length(extremos) &&
      all(abs(extremos) < .MAX_ENTERO_EXACTO_DBI)) {
    return(FALSE)
  }
  length(desvio) == 1L && is.finite(desvio) && desvio > 0 &&
    length(extremos) > 0L &&
    max(abs(extremos)) / desvio * 2^-53 > .TOLERANCIA_DESVIO_DOBLE_DBI
}

# La escala que declara el tipo de un decimal, si la declara: `numeric(18,2)` es
# 2, `decimal(10)` es 0 -sin escala, la de MySQL, MariaDB, SQL Server y
# PostgreSQL es 0-, y `numeric` a secas, un codigo ODBC o cualquier otro tipo,
# `NA`.
.escala_declarada_dbi <- function(tipo) {
  if (is.null(tipo) || length(tipo) != 1L || is.na(tipo)) return(NA_integer_)
  limpio <- gsub("[[:space:]]+", "", .minusculas_ascii(as.character(tipo)))
  partes <- regmatches(limpio, regexec(
    "^(?:decimal|numeric|number)\\(([0-9]+)(?:,([0-9]+))?\\)(?:unsigned)?$",
    limpio, perl = TRUE
  ))[[1L]]
  if (length(partes) != 3L) return(NA_integer_)
  if (!nzchar(partes[[3L]])) return(0L)
  as.integer(partes[[3L]])
}

# Un decimal, o `money`/`smallmoney` de SQL Server, que el controlador publica
# con su nombre y no con el codigo ODBC (`.tipo_declarado_decimal_dbi()` ya
# reconoce el codigo `3`).
.tipo_decimal_o_moneda_dbi <- function(tipo) {
  .tipo_declarado_decimal_dbi(tipo) || (
    length(tipo) >= 1L && !is.na(tipo[[1L]]) &&
      .minusculas_ascii(trimws(as.character(tipo[[1L]]))) %in%
        c("money", "smallmoney")
  )
}

.MOTIVO_DESVIO_DECIMAL_DOBLE_DBI <- paste(
  "La columna es decimal y el desv\u00edo sali\u00f3 del doble de cada valor, que no",
  "guarda todas sus cifras: la magnitud de la columna frente a su desv\u00edo es tal",
  "que ese redondeo puede moverlo m\u00e1s de una parte en mil millones. No se",
  "publica como calculado. Por la tabla completa, sin `bloque_filas`, el motor",
  "resta la media en el tipo de la columna."
)

.MOTIVO_DECIMAL_ANCHO_SPOOL_DBI <- paste(
  "La muestra conserva los valores exactos de un decimal ancho, pero",
  "sus m\u00e9tricas cuantitativas no caben en un doble sin perder cifras;",
  "no se publica la m\u00e9trica para no redondearla."
)

# La muestra del motor centra el desvio en la media de una ventana, y en estos
# motores esa media -y la resta- es un doble (ver `.media_ventana_sql_dbi()`).
# PostgreSQL promedia el `numeric` exacto; SQLite guarda los decimales como
# `REAL`, que ya son los dobles.
.centra_muestra_en_doble_dbi <- function(conexion) {
  senas <- .senas_conexion_dbi(conexion)
  .es_transact_sql_dbi(senas) || .es_mysql_dbi(senas) ||
    grepl("duckdb", senas, useBytes = TRUE)
}

# Cuando el desvio que dio la consulta consolidada -que no puede centrarse: ahi
# la media sale de la misma sentencia- corre riesgo de cancelacion. El error de
# una pasada crece con (media / desvio)^2: medido en SQL Server, 2,6e-14 con la
# media 34 veces el desvio y 3,9e-2 con 3,7e7 veces. Desde 10 veces se vuelve a
# pedir centrado; debajo, el error queda en el orden de 1e-15. Un desvio `0` con
# valores distintos es el caso extremo, y lo dice cualquiera de las dos senas:
# un minimo menor que el maximo, o mas de un distinto. Los extremos solos no
# alcanzan: sobre un `numeric` cuyos valores difieren por debajo de la
# resolucion del doble -1000 + g * 1e-15- el minimo y el maximo como dobles son
# iguales, el desvio sobre `CAST(x AS DOUBLE PRECISION)` es 0 y el motor cuenta
# 500 distintos; centrado, la resta se hace en `numeric` y el desvio sale.
.RAZON_CANCELACION_DESVIO_DBI <- 10

.riesgo_cancelacion_desvio_dbi <- function(media, desvio, minimo = NA_real_,
                                           maximo = NA_real_,
                                           n_distintos = NA_real_) {
  media <- suppressWarnings(as.numeric(media))
  desvio <- suppressWarnings(as.numeric(desvio))
  if (length(media) != 1L || length(desvio) != 1L ||
      !is.finite(media) || !is.finite(desvio)) {
    return(FALSE)
  }
  if (desvio == 0) return(.hay_variacion_dbi(minimo, maximo, n_distintos))
  abs(media) > .RAZON_CANCELACION_DESVIO_DBI * desvio
}

# Si la columna tiene al menos dos valores distintos, segun lo que el resumen ya
# midio: un minimo menor que el maximo, o mas de un distinto. FALSE si no se
# sabe.
.hay_variacion_dbi <- function(minimo = NA_real_, maximo = NA_real_,
                               n_distintos = NA_real_) {
  minimo <- suppressWarnings(as.numeric(minimo))
  maximo <- suppressWarnings(as.numeric(maximo))
  n_distintos <- suppressWarnings(as.numeric(n_distintos))
  rango <- length(minimo) == 1L && length(maximo) == 1L &&
    is.finite(minimo) && is.finite(maximo) && minimo < maximo
  distintos <- length(n_distintos) == 1L && is.finite(n_distintos) &&
    n_distintos > 1
  isTRUE(rango || distintos)
}

.guardian_dbi <- function(resultado) {
  metadatos <- resultado$metadatos
  guardado <- if (is.null(metadatos)) NA_real_ else {
    .numero_dbi(metadatos$n_validos_guard)
  }
  id_resultado <- suppressWarnings(as.integer(resultado$consulta_id))
  id_guardian <- if (is.null(metadatos)) NA_integer_ else {
    suppressWarnings(as.integer(metadatos$consulta_id_guard))
  }
  comprobable <- isTRUE(metadatos$cota_comprobable) &&
    length(guardado) == 1L && !is.na(guardado) && is.finite(guardado) &&
    length(id_resultado) == 1L && !is.na(id_resultado) &&
    length(id_guardian) == 1L && !is.na(id_guardian) &&
    identical(id_resultado, id_guardian)
  list(valor = guardado, comprobable = comprobable)
}

.guardian_distintos_dbi <- function(resultado) .guardian_dbi(resultado)

.guardian_moda_dbi <- function(resultado) .guardian_dbi(resultado)

.motivo_cota_moda_comprobable_dbi <- function() {
  paste(
    "La cota simple `frecuencia_moda <= n_validos` se comprob\u00f3 dentro de la misma",
    "sentencia mediante `n_validos_guard`."
  )
}

.motivo_cota_distintos_no_comprobable_dbi <- function() {
  paste(
    "No se pudo comprobar la cota `n_distintos <= n_validos`: los valores",
    "no tienen un guardian en la misma sentencia y pueden provenir de",
    "consultas distintas. No se atribuye una inconsistencia al motor."
  )
}

.motivo_cota_moda_no_comprobable_dbi <- function() {
  paste(
    "No se pudo comprobar una cota simple de frecuencia de la moda: la frecuencia",
    "y el n\u00famero de valores v\u00e1lidos no tienen un guardian en la misma",
    "sentencia y pueden provenir de consultas distintas. No se atribuye una",
    "inconsistencia al motor."
  )
}

# DuckDB interpola `PERCENTILE_CONT` de un DECIMAL en el DECIMAL de la columna
# y trunca a su escala: la mediana de 1,00 y 1,01 en `DECIMAL(10,2)` salia
# 1,00, y la de 1, 2, 3 y 4 en `DECIMAL(38,0)` salia 2, publicadas `calculado`
# en el camino por omision (medido con duckdb 2.0.0). Sobre el doble de cada
# valor interpola en doble, que es la mediana de R sobre lo que lee el
# controlador, como el promedio en `FLOAT` de T-SQL.
.expresion_mediana_motor_dbi <- function(conexion, expr, tipo = NA_character_) {
  if (grepl("duckdb", .senas_conexion_dbi(conexion), useBytes = TRUE) &&
      .tipo_declarado_decimal_dbi(tipo)) {
    return(paste0("CAST(", expr, " AS DOUBLE)"))
  }
  expr
}

.medianas_lote_consolidadas_dbi <- function(
    conexion, tabla_sql, lote, nombres_sql, alias, numero, candidato,
    presupuesto, estado = "calculado", n_filas = NA_real_,
    n_medianas_pendientes = length(lote),
    usar_referencia_banco = FALSE) {
  aliases <- vapply(seq_along(lote), function(i) {
    .alias_agregado_dbi(alias, "mediana", numero, i)
  }, character(1L), USE.NAMES = FALSE)
  expresiones <- vapply(seq_along(lote), function(i) {
    candidato$expresion(nombres_sql[[lote[[i]]]], aliases[[i]])
  }, character(1L), USE.NAMES = FALSE)
  sql <- candidato$construir_multiple(expresiones, tabla_sql)
  if (!is.null(presupuesto)) {
    proyeccion <- .proyectar_costo_mediana_dbi(
      presupuesto, n_filas, n_medianas_pendientes,
      usar_referencia_banco = usar_referencia_banco
    )
    if (isTRUE(proyeccion$disponible)) {
      presupuesto$proyeccion_mediana <- proyeccion
      if (!isTRUE(presupuesto$aviso_mediana_emitido)) {
        avisado <- .avisar_costo_mediana_dbi(
          proyeccion,
          habilitado = if (is.null(presupuesto$avisar_costo_mediana)) TRUE else
            presupuesto$avisar_costo_mediana,
          umbral_segundos = if (is.null(presupuesto$umbral_segundos_aviso_mediana)) {
            .UMBRAL_SEGUNDOS_AVISO_MEDIANA_DBI
          } else presupuesto$umbral_segundos_aviso_mediana
        )
        if (isTRUE(avisado)) presupuesto$aviso_mediana_emitido <- TRUE
      }
    }
  }
  consulta <- .consultar_dbi(
    conexion, sql, presupuesto, etapa = "medianas_consolidadas"
  )
  .registrar_referencia_mediana_dbi(
    presupuesto, consulta, n_filas = n_filas, n_medianas = length(lote)
  )
  salida <- vector("list", length(lote))
  names(salida) <- lote
  if (!isTRUE(consulta$ok)) {
    return(list(resultados = salida, sql = sql, ok = FALSE))
  }
  for (i in seq_along(lote)) {
    celda <- .valor_campo_dbi(
      consulta$datos, .nombre_alias_dbi(aliases[[i]])
    )
    if (!isTRUE(celda$ok)) next
    valor <- .escalar_finito_dbi(celda$valor)
    if (.valor_perdido_en_conversion_dbi(celda$valor, valor)) next
    metadatos_resultado <- .metadatos_lote_dbi(numero, lote)
    metadatos_resultado <- c(
      metadatos_resultado,
      list(
        metodo = candidato$nombre,
        error_esperado = if (identical(estado, "estimado")) {
          candidato$error_esperado
        } else {
          "no_aplica"
        }
      )
    )
    salida[[lote[[i]]]] <- .adjuntar_medicion_dbi(
      list(
        ok = TRUE, valor = valor, motivo = NA_character_, sql = sql,
        estado = estado,
        metadatos = metadatos_resultado
      ), consulta
    )
  }
  list(resultados = salida, sql = sql, ok = TRUE)
}

.medianas_consolidadas_dbi <- function(
    conexion, tabla_sql, columnas, nombres_sql, alias, candidato,
    presupuesto, tamano_lote, estado = "calculado") {
  salida <- vector("list", length(columnas))
  names(salida) <- columnas
  if (is.null(candidato) || !length(columnas)) return(salida)
  lotes <- .lotes_columnas_dbi(columnas, tamano_lote)
  for (numero in seq_along(lotes)) {
    lote <- lotes[[numero]]
    pendientes <- sum(vapply(lotes[numero:length(lotes)], length, integer(1L)))
    resultado <- .medianas_lote_consolidadas_dbi(
      conexion, tabla_sql, lote, nombres_sql, alias, numero, candidato,
      presupuesto, estado = estado,
      n_filas = if (is.null(presupuesto)) NA_real_ else {
        if (is.null(presupuesto$filas_mediana)) NA_real_ else
          presupuesto$filas_mediana
      },
      n_medianas_pendientes = pendientes,
      usar_referencia_banco = length(lotes) == 1L
    )
    # Si la forma consolidada falla sobre la consulta real, no se transforma
    # ese fallo en una `NA` calculada: el llamador deja el resultado ausente y
    # usa el camino exacto por columna, que ya declara sus propios errores.
    for (columna in lote) {
      if (!is.null(resultado$resultados[[columna]])) {
        salida[[columna]] <- resultado$resultados[[columna]]
      }
    }
    pendientes_estado <- if (is.null(presupuesto)) NA_real_ else
      .numero_dbi(presupuesto$medianas_pendientes)
    if (!is.null(presupuesto) && isTRUE(resultado$ok) &&
        length(pendientes_estado) == 1L && is.finite(pendientes_estado)) {
      presupuesto$medianas_pendientes <- max(
        0, pendientes_estado - length(lote)
      )
    }
    if (!is.null(presupuesto) && isTRUE(resultado$ok) &&
        pendientes > length(lote)) {
      proyeccion <- .proyectar_costo_mediana_dbi(
        presupuesto, presupuesto$filas_mediana, pendientes - length(lote)
      )
      presupuesto$proyeccion_mediana <- proyeccion
    }
  }
  salida
}

.resultado_agregado_no_emitido_dbi <- function(etapa, motivo,
                                               sql = NA_character_) {
  list(
    ok = FALSE, valor = NULL, datos = NULL, motivo = motivo, sql = sql,
    metadatos = NULL, consulta_id = NA_integer_, etapa = etapa,
    duracion_ms = NA_real_, n_filas_resultado = NA_real_,
    bytes_resultado_r = NA_real_, cpu_ms = NA_real_
  )
}

.resultados_lote_agregados_dbi <- function(consulta, sql,
                                           alias_por_columna, metricas,
                                           metricas_basicos, metadatos) {
  nombres <- names(alias_por_columna)
  salida <- vector("list", length(nombres))
  names(salida) <- nombres
  for (i in seq_along(nombres)) {
    aliases <- alias_por_columna[[i]]
    resultado <- list(consolidada = TRUE)
    if (!is.null(aliases$total)) {
      resultado$conteo <- .resultado_lote_dbi(
        consulta, sql, aliases$total, metadatos
      )
    }
    if ("validos" %in% metricas) {
      resultado$validos <- .resultado_lote_dbi(
        consulta, sql, aliases$validos, metadatos
      )
      resultado$validos <- .adjuntar_denominador_consulta_dbi(
        resultado$validos, consulta, aliases$total
      )
    }
    if ("basicos" %in% metricas && !is.null(aliases$basicos)) {
      resultado$basicos <- .resultado_lote_campos_dbi(
        consulta, sql, aliases$basicos, metricas_basicos, metadatos
      )
      resultado$basicos <- .adjuntar_denominador_consulta_dbi(
        resultado$basicos, consulta, aliases$total
      )
    }
    if ("desvio" %in% metricas && !is.null(aliases$desvio)) {
      resultado$desvio <- .resultado_lote_dbi(
        consulta, sql, aliases$desvio, metadatos
      )
      resultado$desvio <- .adjuntar_denominador_consulta_dbi(
        resultado$desvio, consulta, aliases$total
      )
    }
    salida[[i]] <- resultado
  }
  salida
}

.tope_sondas_agregados_dbi <- function(presupuesto, n) {
  saldo <- if (is.null(presupuesto)) Inf else .saldo_dbi(presupuesto)
  # La otra mitad queda disponible para metricas que aun no se sondearon. Es
  # la misma reserva que usa la lectura de muestra: recuperar una parte no
  # puede dejar sin presupuesto el resto del perfil.
  min(2 * n, .TOPE_SONDAS_DESCARTE_DBI, max(0, floor(saldo / 2)))
}

.recordar_lote_agregados_dbi <- function(presupuesto, n, familia = "planos") {
  if (is.null(presupuesto) || n < 1) return(invisible(NULL))
  ranura <- if (identical(familia, "distintos")) {
    "tamano_lote_distintos_funciono"
  } else {
    "tamano_lote_planos_funciono"
  }
  previo <- presupuesto[[ranura]]
  if (is.null(previo) || n > previo) presupuesto[[ranura]] <- n
  # Alias de compatibilidad: conserva el mayor lote plano, que era el unico
  # lote que existia antes de separar las familias.
  previo_total <- presupuesto$tamano_lote_funciono
  if (is.null(previo_total) || n > previo_total) {
    presupuesto$tamano_lote_funciono <- n
  }
  invisible(NULL)
}

.agregados_lote_con_biseccion_dbi <- function(
    conexion, tabla_sql, lote, nombres_sql, es_numerico, metricas,
    incluir_valores, presupuesto, numero, alias, forma,
    etapa = "agregados", incluir_total = FALSE,
    tabla_total_sql = tabla_sql, columnas_float8_numeric = character(),
    infinitos_como_numeric = FALSE, centros_desvio = NULL,
    tipos_declarados = NULL, ventana_desvio = FALSE,
    decimales_exactos = NULL, incluir_cuenta = FALSE,
    incluir_magnitud = FALSE) {
  fallas_lote_inicio <- if (is.null(presupuesto)) 0L else {
    if (is.null(presupuesto$fallas_lotes)) presupuesto$fallas_lotes <- list()
    length(presupuesto$fallas_lotes)
  }
  posponer_fallas_anterior <- if (is.null(presupuesto)) FALSE else
    isTRUE(presupuesto$posponer_fallas_lotes)
  if (!is.null(presupuesto)) {
    presupuesto$posponer_fallas_lotes <- TRUE
    on.exit({
      presupuesto$posponer_fallas_lotes <- posponer_fallas_anterior
    }, add = TRUE)
  }
  # Ver `.media_sql_dbi()`: la media se pide como doble en T-SQL.
  senas <- .senas_conexion_dbi(conexion)
  metricas_basicos <- if ("basicos" %in% metricas) {
    if (incluir_valores) {
      c("minimo", "maximo", "media", "n_ceros", "n_negativos")
    } else {
      c("media", "n_ceros", "n_negativos", .CAMPOS_ESCALA_AUX_DBI)
    }
  } else {
    character()
  }
  alias_por_columna <- vector("list", length(lote))
  names(alias_por_columna) <- lote
  for (i in seq_along(lote)) {
    alias_por_columna[[i]] <- list(
      total = if (isTRUE(incluir_total)) alias("n_total_consulta"),
      validos = if ("validos" %in% metricas) {
        .alias_agregado_dbi(alias, numero, i, "n_validos")
      },
      basicos = if ("basicos" %in% metricas && es_numerico[[i]]) {
        salida <- lapply(
          metricas_basicos,
          function(metrica) .alias_agregado_dbi(alias, numero, i, metrica)
        )
        names(salida) <- metricas_basicos
        salida
      },
      desvio = if ("desvio" %in% metricas && es_numerico[[i]]) {
        .alias_agregado_dbi(alias, numero, i, "desvio")
      }
    )
  }
  # La media y el desvio exactos de un decimal, en la misma sentencia que los
  # agregados (`.piezas_sumas_sin_centro_dbi()`): no cuestan una consulta mas
  # -con `max_consultas` justo, la de mas se quedaba sin lugar- y, bajo la
  # muestra del motor, otra sentencia veria otra muestra. Los cuadrados van si
  # se pide el desvio, aunque el de este lote salga en una segunda pasada.
  piezas_exactas <- list()
  if (length(decimales_exactos) &&
      any(c("basicos", "desvio") %in% metricas)) {
    for (i in seq_along(lote)) {
      campo <- lote[[i]]
      datos_campo <- decimales_exactos[[campo]]
      if (is.null(datos_campo) || !isTRUE(es_numerico[[i]])) next
      piezas <- .piezas_sumas_sin_centro_dbi(
        senas, nombres_sql[[campo]], datos_campo$tipo, datos_campo$filas,
        isTRUE(datos_campo$desvio) || "desvio" %in% metricas,
        paste0("lupa_suma_l", numero, "_c", i, "_"), alias
      )
      if (!is.null(piezas)) piezas_exactas[[campo]] <- piezas
    }
  }
  # Sin `validos`, la media, el desvio y los extremos no saben cuantos valores
  # vieron: una columna toda `NULL` y una de un solo valor daban motivos
  # genericos donde la ayuda promete `sin_valores` y `no_aplica`. La cuenta va
  # en la misma sentencia -bajo la muestra del motor, otra veria otra muestra-
  # y no se publica como `n_validos`, que no se pidio: la lee
  # `.valores_ausentes_por_cuenta_dbi()`. Un decimal con sumas exactas ya la
  # trae en ellas.
  if (isTRUE(incluir_cuenta) && !"validos" %in% metricas &&
      any(c("basicos", "desvio") %in% metricas)) {
    for (i in seq_along(lote)) {
      if (!isTRUE(es_numerico[[i]]) || !is.null(piezas_exactas[[lote[[i]]]])) {
        next
      }
      alias_por_columna[[i]]$cuenta <- .alias_agregado_dbi(
        alias, numero, i, "n_cuenta"
      )
    }
  }
  # Bajo la muestra del motor, la sonda de magnitud viaja aca: su propia
  # sentencia sorteaba otra muestra, y la cuenta y la magnitud que deciden el
  # desvio salian de filas que el desvio no habia visto -en SQL Server, con
  # `metricas = "desvio"`, una sonda vacia publicaba el desvio `no_aplica` con
  # un lote de 100 valores-. La lee `.resumen_columna_dbi()` en lugar de la
  # sonda. Con `basicos` no hace falta: los extremos ya vienen en el lote.
  if (isTRUE(incluir_magnitud) && !"basicos" %in% metricas) {
    for (i in seq_along(lote)) {
      if (!isTRUE(es_numerico[[i]])) next
      alias_por_columna[[i]]$magnitud <- paste0(
        "lupa_l", numero, "_c", i, "_magnitud"
      )
    }
  }
  # Con esas sumas la media y el desvio del motor no se publican, pero tienen
  # que poder calcularse: en DuckDB `x * 1.0` de un `DECIMAL(38,30)` de 9e7
  # desborda ("Overflow in multiplication of DECIMAL(38)") y tumbaba la
  # sentencia entera, con las sumas adentro. Se promedia y se desvia el doble.
  promedio_de <- function(campo) {
    if (!is.null(piezas_exactas[[campo]]) && .duckdb_senas_dbi(senas)) {
      paste0("CAST(", nombres_sql[[campo]], " AS DOUBLE)")
    } else nombres_sql[[campo]]
  }
  tabla_agregados_sql <- tabla_sql
  centros_ventana <- list()
  if (isTRUE(ventana_desvio) && any(es_numerico)) {
    centros <- vapply(seq_along(lote), function(i) {
      campo <- lote[[i]]
      exacta <- isTRUE(infinitos_como_numeric) &&
        campo %in% columnas_float8_numeric ||
        .es_lectura_double_exacta_dbi(nombres_sql[[campo]])
      if (!es_numerico[[i]]) return(NA_character_)
      nombre <- alias(paste0("lupa_media_", numero, "_", i))
      centros_ventana[[campo]] <<- nombre
      paste0(
        .media_ventana_sql_dbi(
          promedio_de(campo), senas,
          float8_seguro = campo %in% columnas_float8_numeric,
          infinitos_como_numeric = exacta
        ), " AS ", nombre
      )
    }, character(1L), USE.NAMES = FALSE)
    campos_fuente <- vapply(
      lote, function(campo) nombres_sql[[campo]], character(1L),
      USE.NAMES = FALSE
    )
    campos_fuente <- c(campos_fuente, centros[!is.na(centros)])
    tabla_agregados_sql <- paste0(
      "(SELECT ", paste(campos_fuente, collapse = ", "),
      " FROM ", tabla_sql, ") AS ", alias("lupa_desvio_ventana")
    )
  }
  expresiones_columna <- function(i) {
    campo <- lote[[i]]
    aliases <- alias_por_columna[[i]]
    exacta <- isTRUE(infinitos_como_numeric) &&
      campo %in% columnas_float8_numeric ||
      .es_lectura_double_exacta_dbi(nombres_sql[[campo]])
    c(
      if ("validos" %in% metricas) paste0(
        .contar_no_nulos_sql_dbi(nombres_sql[[campo]], senas), " AS ", aliases$validos
      ),
      if (!is.null(aliases$cuenta)) paste0(
        .contar_no_nulos_sql_dbi(nombres_sql[[campo]], senas), " AS ", aliases$cuenta
      ),
      if (!is.null(aliases$magnitud)) .expresiones_sonda_magnitud_dbi(
        conexion, nombres_sql[[campo]], aliases$magnitud, alias
      ),
      if ("basicos" %in% metricas && es_numerico[[i]]) c(
        if (incluir_valores) paste0(
          "MIN(", nombres_sql[[campo]], ") AS ", aliases$basicos$minimo
        ),
        if (incluir_valores) paste0(
          "MAX(", nombres_sql[[campo]], ") AS ", aliases$basicos$maximo
        ),
        if (!incluir_valores) paste0(
          "MIN(", nombres_sql[[campo]], ") AS ", aliases$basicos$minimo
        ),
        if (!incluir_valores) paste0(
          "MAX(", nombres_sql[[campo]], ") AS ", aliases$basicos$maximo
        ),
        if (!incluir_valores) paste0(
          "MAX(", .abs_sql_seguro_dbi(conexion, nombres_sql[[campo]]),
          ") AS ",
          aliases$basicos$maximo_abs
        ),
        if (!incluir_valores) paste0(
          "MIN(", .abs_sql_seguro_dbi(conexion, nombres_sql[[campo]]),
          ") AS ",
          aliases$basicos$minimo_abs
        ),
        paste0(
          .media_sql_dbi(
            promedio_de(campo), senas, tabla_sql = tabla_agregados_sql,
            float8_seguro = campo %in% columnas_float8_numeric,
            infinitos_como_numeric = exacta
          ), " AS ",
          aliases$basicos$media
        ),
        paste0(
          .conteo_sql_dbi(
            paste0("SUM(CASE WHEN ", nombres_sql[[campo]],
                   " = 0 THEN 1 ELSE 0 END)"), senas
          ), " AS ", aliases$basicos$n_ceros
        ),
        paste0(
          .conteo_sql_dbi(
            paste0("SUM(CASE WHEN ", nombres_sql[[campo]],
                   " < 0 THEN 1 ELSE 0 END)"), senas
          ), " AS ", aliases$basicos$n_negativos
        )
      ),
      if ("desvio" %in% metricas && es_numerico[[i]]) {
        formas <- .formas_desvio_dbi(
          tabla_agregados_sql, promedio_de(campo),
          function(nombre) aliases$desvio, senas,
          centro = if (is.null(centros_desvio)) NULL else {
            centros_desvio[[campo]]
          },
          centro_sql = if (isTRUE(ventana_desvio)) {
            centros_ventana[[campo]]
          } else NULL,
          tipo = if (is.null(tipos_declarados)) NA_character_ else {
            tipos_declarados[[campo]] %||% NA_character_
          },
          numeric_exact = exacta,
          infinitos_como_numeric = exacta,
          escala_sql = NULL,
          centro_en_ventana = isTRUE(ventana_desvio)
        )
        formas[[forma]]
      },
      piezas_exactas[[campo]]$partes
    )
  }
  total_alias <- alias("n_total_consulta")
  expresion_total <- paste0(
    .conteo_sql_dbi("COUNT(*)", senas), " AS ", total_alias
  )
  universo_alias <- alias("lupa_n_total")
  expresion_universo <- paste0(
    "(SELECT ", .conteo_sql_dbi("COUNT(*)", senas), " FROM ",
    tabla_total_sql, ") AS ", universo_alias
  )
  construir <- function(indices, con_total = FALSE, con_universo = FALSE) {
    expresiones <- c(
      if (isTRUE(con_total)) expresion_total,
      if (isTRUE(con_universo)) expresion_universo,
      unlist(lapply(indices, expresiones_columna), use.names = FALSE)
    )
    paste0(
      "SELECT ", paste(expresiones, collapse = ", "), " FROM ",
      tabla_agregados_sql
    )
  }

  cache <- list()
  clave <- function(indices) paste(indices, collapse = ",")
  sondear <- function(indices, con_total = incluir_total,
                      con_universo = FALSE) {
    llave <- paste(
      clave(indices), isTRUE(con_total), isTRUE(con_universo), sep = "|"
    )
    if (!is.null(cache[[llave]])) return(isTRUE(cache[[llave]]$ok))
    sql <- construir(
      indices, con_total = con_total, con_universo = con_universo
    )
    consulta <- .consultar_dbi(
      conexion, sql, presupuesto, etapa = etapa
    )
    cache[[llave]] <<- list(ok = consulta$ok, consulta = consulta, sql = sql)
    isTRUE(consulta$ok)
  }

  completo <- seq_along(lote)
  universo_separado <- !identical(tabla_total_sql, tabla_sql)
  inicial <- sondear(
    completo, con_total = incluir_total,
    con_universo = incluir_total && universo_separado
  )
  conteo <- NULL
  if (isTRUE(incluir_total)) {
    entrada_total <- cache[[paste(
      clave(completo), isTRUE(incluir_total),
      isTRUE(incluir_total && universo_separado), sep = "|"
    )]]
    if (isTRUE(inicial)) {
      conteo <- .conteo_desde_consulta_dbi(
        entrada_total$consulta, entrada_total$sql,
        if (isTRUE(universo_separado)) universo_alias else total_alias
      )
    }
    if (is.null(conteo)) {
      sql_total <- paste0(
        "SELECT ", .conteo_sql_dbi("COUNT(*)", senas), " AS ",
        universo_alias, " FROM ", tabla_total_sql
      )
      conteo <- .escalar_dbi(
        conexion, sql_total, .nombre_alias_dbi(universo_alias), presupuesto,
        etapa = "conteo_filas"
      )
      conteo$sql <- sql_total
      if (!isTRUE(conteo$ok)) conteo$metadatos <- NULL
    }
  }
  if (inicial) {
    grupos <- list(completo)
    culpables <- integer()
    pendientes <- integer()
    agotado <- FALSE
    sondas <- 0L
  } else {
    aislamiento <- .aislar_ilegibles_dbi(
      sondear, function() {
        is.null(presupuesto) || .saldo_dbi(presupuesto) >= 1
      }, length(lote), .tope_sondas_agregados_dbi(presupuesto, length(lote)),
      conservar_legibles = TRUE
    )
    grupos <- aislamiento$legibles
    culpables <- aislamiento$culpables
    pendientes <- unlist(aislamiento$pendientes, use.names = FALSE)
    agotado <- isTRUE(aislamiento$agotado)
    sondas <- aislamiento$sondas
  }
  if (length(grupos)) {
    .recordar_lote_agregados_dbi(
      presupuesto, max(vapply(grupos, length, integer(1L))), "planos"
    )
  }
  clasificados <- .sort_por_bytes(unique(c(unlist(grupos, use.names = FALSE), culpables)))
  desconocidos <- setdiff(seq_along(lote), clasificados)
  if (length(desconocidos)) {
    pendientes <- .sort_por_bytes(unique(c(pendientes, desconocidos)))
  }

  resultado <- vector("list", length(lote))
  names(resultado) <- lote
  for (grupo in grupos) {
    llave <- paste(
      clave(grupo), isTRUE(incluir_total),
      isTRUE(incluir_total && universo_separado && identical(grupo, completo)),
      sep = "|"
    )
    entrada <- cache[[llave]]
    if (is.null(conteo) && isTRUE(incluir_total) && !isTRUE(universo_separado)) {
      conteo <- .conteo_desde_consulta_dbi(
        entrada$consulta, entrada$sql, total_alias
      )
    }
    metadatos <- .metadatos_lote_dbi(numero, lote[grupo])
    valores <- .resultados_lote_agregados_dbi(
      entrada$consulta, entrada$sql, alias_por_columna[grupo], metricas,
      metricas_basicos, metadatos
    )
    for (i in seq_along(grupo)) {
      campo <- lote[[grupo[[i]]]]
      piezas <- piezas_exactas[[campo]]
      if (!is.null(piezas) && isTRUE(entrada$consulta$ok)) {
        exacto <- .leer_sumas_exactas_dbi(
          entrada$consulta$datos,
          list(n = paste0(piezas$prefijo, "n"), f = paste0(piezas$prefijo, "f"),
               s = paste0(piezas$prefijo, "s"), q = paste0(piezas$prefijo, "q")),
          piezas$suma, piezas$cuadrados, piezas$postgres
        )
        # Lo del motor queda como esta, con sus guardas: el resumen lo
        # reemplaza al final (`.decimales_exactos_tabla_dbi()`).
        total_lote <- suppressWarnings(as.numeric(.numero_dbi(
          entrada$consulta$datos[["n_total_consulta"]]
        )))
        valores[[i]]$exacto_decimal <- list(
          media = exacto$media, desvio = exacto$desvio, sql = entrada$sql,
          finitos = exacto$finitos,
          total = if (length(total_lote) == 1L) total_lote else NA_real_
        )
      }
      alias_cuenta <- alias_por_columna[[grupo[[i]]]]$cuenta
      if (!is.null(alias_cuenta) && isTRUE(entrada$consulta$ok)) {
        celda <- .valor_campo_dbi(
          entrada$consulta$datos, .nombre_alias_dbi(alias_cuenta)
        )
        celda_total <- .valor_campo_dbi(
          entrada$consulta$datos, .nombre_alias_dbi(total_alias)
        )
        valores[[i]]$cuenta_valores <- list(
          n = if (isTRUE(celda$ok)) .conteo_dbi(celda$valor) else NA_real_,
          total = if (isTRUE(celda_total$ok)) {
            .conteo_dbi(celda_total$valor)
          } else NA_real_
        )
      }
      base_magnitud <- alias_por_columna[[grupo[[i]]]]$magnitud
      if (!is.null(base_magnitud) && isTRUE(entrada$consulta$ok)) {
        magnitud <- .leer_sonda_magnitud_dbi(entrada$consulta, base_magnitud)
        magnitud$sql <- entrada$sql
        valores[[i]]$magnitud_lote <- magnitud
      }
      resultado[[campo]] <- valores[[i]]
    }
  }

  # Una columna que falla en la sonda combinada no necesariamente falla para
  # todas las metricas: se reintenta por columna con las mismas puertas que
  # habia antes. La biseccion localiza donde mirar, pero no convierte el fallo
  # de un agregado en la perdida de los demas.
  for (i in culpables) {
    campo <- lote[[i]]
    metadatos <- .metadatos_lote_dbi(numero, campo)
    individual <- list(consolidada = FALSE)
    if ("validos" %in% metricas) {
      conteos_columna <- .conteos_columna_dbi(
        conexion, tabla_sql, nombres_sql[[campo]], alias,
        TRUE, FALSE, presupuesto, incluir_total = TRUE
      )
      individual$validos <- conteos_columna$validos
    }
    if ("basicos" %in% metricas && es_numerico[[i]]) {
      individual$basicos <- .basicos_columna_dbi(
        conexion, tabla_sql, nombres_sql[[campo]], alias, incluir_valores,
        presupuesto, metadatos,
        float8_seguro = campo %in% columnas_float8_numeric,
        infinitos_como_numeric = isTRUE(infinitos_como_numeric) &&
          campo %in% columnas_float8_numeric ||
          .es_lectura_double_exacta_dbi(nombres_sql[[campo]]),
        tipo = if (is.null(tipos_declarados)) NA_character_ else
          tipos_declarados[[campo]] %||% NA_character_
      )
    }
    if ("desvio" %in% metricas && es_numerico[[i]]) {
      individual$desvio <- .desvio_columna_dbi(
        conexion, tabla_sql, nombres_sql[[campo]], alias, forma,
        presupuesto, metadatos,
          centro = if (is.null(centros_desvio)) NULL else {
            centros_desvio[[campo]]
          },
          numeric_exact = campo %in% columnas_float8_numeric ||
            .es_lectura_double_exacta_dbi(nombres_sql[[campo]]),
          infinitos_como_numeric = isTRUE(infinitos_como_numeric) &&
            campo %in% columnas_float8_numeric ||
            .es_lectura_double_exacta_dbi(nombres_sql[[campo]])
      )
    }
    for (metrica in intersect(names(individual), c("validos", "basicos", "desvio"))) {
      individual[[metrica]]$metadatos <- .mezclar_metadatos_dbi(
        metadatos, individual[[metrica]]$metadatos
      )
    }
    resultado[[campo]] <- individual
  }

  if (length(pendientes)) {
    motivo <- paste(
      "El lote de agregados fue rechazado y no se pudieron aislar todas sus",
      "columnas dentro del presupuesto de sondas; las columnas pendientes no",
      "se suponen culpables ni legibles."
    )
    for (i in pendientes) {
      campo <- lote[[i]]
      metadatos <- .metadatos_lote_dbi(numero, campo)
      sin_consulta <- .resultado_agregado_no_emitido_dbi(etapa, motivo)
      individual <- list(consolidada = FALSE)
      if ("validos" %in% metricas) {
        individual$validos <- .resultado_lote_dbi(
          sin_consulta, NA_character_, alias_por_columna[[i]]$validos,
          metadatos
        )
      }
      if ("basicos" %in% metricas && !is.null(alias_por_columna[[i]]$basicos)) {
        individual$basicos <- .resultado_lote_campos_dbi(
          sin_consulta, NA_character_, alias_por_columna[[i]]$basicos,
          metricas_basicos, metadatos
        )
      }
      if ("desvio" %in% metricas && !is.null(alias_por_columna[[i]]$desvio)) {
        individual$desvio <- .resultado_lote_dbi(
          sin_consulta, NA_character_, alias_por_columna[[i]]$desvio,
          metadatos
        )
      }
      resultado[[campo]] <- individual
    }
  }
  # Una columna con sumas que no llegaron dice por que: el motor rechazo la
  # consulta con las sumas aun con la columna sola (con su mensaje), o no hubo
  # presupuesto para aislarla. Lo lee `.decimales_exactos_tabla_dbi()`.
  for (i in c(culpables, pendientes)) {
    campo <- lote[[i]]
    if (is.null(piezas_exactas[[campo]]) || is.null(resultado[[campo]])) next
    motivo_exacto <- if (i %in% pendientes) {
      if (!is.null(presupuesto) && .saldo_dbi(presupuesto) < 1) {
        .motivo_presupuesto_dbi(presupuesto)
      } else {
        paste(
          "el motor rechaz\u00f3 el lote de agregados con las sumas y no se",
          "pudo aislar la columna dentro del presupuesto de sondas."
        )
      }
    } else {
      sola <- cache[startsWith(names(cache), paste0(i, "|"))]
      mensajes <- vapply(sola, function(entrada) {
        m <- entrada$consulta$motivo
        if (isTRUE(entrada$ok) || is.null(m) || !length(m) || is.na(m[[1L]])) {
          NA_character_
        } else as.character(m[[1L]])
      }, character(1L))
      mensajes <- mensajes[!is.na(mensajes)]
      paste0(
        "el motor rechaz\u00f3 la consulta de los agregados con las sumas aun con la ",
        "columna sola",
        if (length(mensajes)) paste0(": ", mensajes[[1L]]) else "."
      )
    }
    resultado[[campo]]$exacto_decimal <- list(
      media = NA_real_, desvio = NA_real_, sql = NA_character_,
      finitos = NA_real_, motivo = motivo_exacto
    )
  }
  if (!is.null(presupuesto) &&
      length(presupuesto$fallas_lotes) > fallas_lote_inicio) {
    fallas_lote <- presupuesto$fallas_lotes[
      seq.int(fallas_lote_inicio + 1L, length(presupuesto$fallas_lotes))
    ]
    presupuesto$fallas_lotes <- if (fallas_lote_inicio > 0L) {
      presupuesto$fallas_lotes[seq_len(fallas_lote_inicio)]
    } else list()
    sin_calcular <- any(vapply(resultado, function(x) {
      metricas_resultado <- intersect(
        c("validos", "basicos", "desvio"), names(x)
      )
      any(vapply(metricas_resultado, function(metrica) {
        is.list(x[[metrica]]) && !isTRUE(x[[metrica]]$ok)
      }, logical(1L)))
    }, logical(1L)))
    if (sin_calcular && length(fallas_lote)) {
      for (falla in fallas_lote) {
        ya_publicada <- any(vapply(
          presupuesto$fallas_consultas,
          function(publica) identical(publica$etapa, falla$etapa),
          logical(1L)
        ))
        if (!ya_publicada) {
          .guardar_falla_consulta_dbi(falla, presupuesto)
          break
        }
      }
    }
  }
  list(
    resultados = resultado, sondas = sondas, agotado = agotado,
    inicial = inicial, conteo = conteo
  )
}

.conteos_distintos_lote_dbi <- function(
    conexion, tabla_sql, lote, nombres_sql, alias, numero, presupuesto,
    aproximacion_distintos = NULL, incluir_total = FALSE,
    tabla_total_sql = tabla_sql) {
  senas <- .senas_conexion_dbi(conexion)
  alias_por_columna <- vapply(seq_along(lote), function(i) {
    .alias_agregado_dbi(alias, numero, i, "n_distintos")
  }, character(1L), USE.NAMES = FALSE)
  guardian_por_columna <- vapply(seq_along(lote), function(i) {
    .alias_agregado_dbi(alias, numero, i, "n_validos_guard")
  }, character(1L), USE.NAMES = FALSE)
  if (!is.null(aproximacion_distintos) &&
      !is.function(aproximacion_distintos$expresion)) {
    salida <- vector("list", length(lote))
    names(salida) <- lote
    conteo <- NULL
    if (isTRUE(incluir_total)) {
      total_alias <- alias("lupa_n_total")
      sql_total <- paste0(
        "SELECT ", .conteo_sql_dbi("COUNT(*)", senas), " AS ",
        total_alias, " FROM ", tabla_total_sql
      )
      conteo <- .escalar_dbi(
        conexion, sql_total, .nombre_alias_dbi(total_alias), presupuesto,
        etapa = "conteo_filas"
      )
      conteo$sql <- sql_total
    }
    for (i in seq_along(lote)) {
      sql <- aproximacion_distintos$construir(
        nombres_sql[[lote[[i]]]], tabla_sql, alias_por_columna[[i]]
      )
      resultado <- .escalar_dbi(
        conexion, sql, .nombre_alias_dbi(alias_por_columna[[i]]),
        presupuesto, etapa = "conteos"
      )
      resultado$sql <- sql
      resultado$metadatos <- .metadatos_lote_dbi(numero, lote[[i]])
      resultado$metadatos <- .mezclar_metadatos_dbi(
        resultado$metadatos,
        list(
          n_validos_guard = NA_real_,
          consulta_id_guard = NA_integer_,
          cota_comprobable = FALSE
        )
      )
      if (isTRUE(resultado$ok)) {
        resultado$metadatos <- .mezclar_metadatos_dbi(
          resultado$metadatos,
          list(
            metodo = aproximacion_distintos$nombre,
            error_esperado = aproximacion_distintos$error_esperado
          )
        )
        resultado$estado <- "estimado"
      }
      salida[[lote[[i]]]] <- list(
        consolidada = FALSE, distintos = resultado
      )
    }
    return(list(
      resultados = salida, sondas = 0L, agotado = isTRUE(presupuesto$agotado),
      inicial = FALSE, conteo = conteo
    ))
  }
  expresion <- function(i) {
    if (is.null(aproximacion_distintos)) {
      return(c(
        paste0(
          .contar_no_nulos_sql_dbi(nombres_sql[[lote[[i]]]], senas), " AS ",
          guardian_por_columna[[i]]
        ),
        paste0(
          .conteo_sql_dbi(
            paste0("COUNT(DISTINCT ", nombres_sql[[lote[[i]]]], ")"), senas
          ), " AS ",
          alias_por_columna[[i]]
        )
      ))
    }
    if (is.null(aproximacion_distintos$expresion)) return(NULL)
    c(
      paste0(
        .contar_no_nulos_sql_dbi(nombres_sql[[lote[[i]]]], senas), " AS ",
        guardian_por_columna[[i]]
      ),
      aproximacion_distintos$expresion(
        nombres_sql[[lote[[i]]]], alias_por_columna[[i]]
      )
    )
  }
  total_alias <- alias("lupa_n_total")
  expresion_total <- if (identical(tabla_total_sql, tabla_sql)) {
    paste0(.conteo_sql_dbi("COUNT(*)", senas), " AS ", total_alias)
  } else {
    paste0("(SELECT ", .conteo_sql_dbi("COUNT(*)", senas), " FROM ",
           tabla_total_sql, ") AS ", total_alias)
  }
  construir <- function(indices, con_total = FALSE) {
    expresiones <- c(
      if (isTRUE(con_total)) expresion_total,
      unlist(lapply(indices, expresion), use.names = FALSE)
    )
    paste0(
      "SELECT ", paste(expresiones, collapse = ", "), " FROM ", tabla_sql
    )
  }
  cache <- list()
  clave <- function(indices) paste(indices, collapse = ",")
  sondear <- function(indices, con_total = FALSE) {
    llave <- clave(indices)
    if (!is.null(cache[[llave]])) return(isTRUE(cache[[llave]]$ok))
    sql <- construir(indices, con_total = con_total)
    consulta <- .consultar_dbi(
      conexion, sql, presupuesto, etapa = "conteos"
    )
    cache[[llave]] <<- list(ok = consulta$ok, consulta = consulta, sql = sql)
    isTRUE(consulta$ok)
  }
  completo <- seq_along(lote)
  inicial <- sondear(completo, con_total = incluir_total)
  conteo <- NULL
  if (isTRUE(incluir_total)) {
    entrada_total <- cache[[clave(completo)]]
    if (isTRUE(inicial)) {
      valor_total <- .valor_campo_dbi(
        entrada_total$consulta$datos, .nombre_alias_dbi(total_alias)
      )
      if (isTRUE(valor_total$ok) &&
          !is.na(.conteo_dbi(valor_total$valor))) {
        conteo <- valor_total
        conteo$sql <- entrada_total$sql
        conteo$metadatos <- list(
          id_consulta = as.integer(entrada_total$consulta$consulta_id)
        )
        conteo <- .adjuntar_medicion_dbi(conteo, entrada_total$consulta)
      }
    }
    if (is.null(conteo)) {
      sql_total <- paste0(
        "SELECT ", .conteo_sql_dbi("COUNT(*)", senas), " AS ",
        total_alias, " FROM ", tabla_total_sql
      )
      conteo <- .escalar_dbi(
        conexion, sql_total, .nombre_alias_dbi(total_alias), presupuesto,
        etapa = "conteo_filas"
      )
      conteo$sql <- sql_total
      if (!isTRUE(conteo$ok)) conteo$metadatos <- NULL
    }
  }
  if (inicial) {
    grupos <- list(completo)
    culpables <- integer()
    pendientes <- integer()
    agotado <- FALSE
    sondas <- 0L
  } else {
    aislamiento <- .aislar_ilegibles_dbi(
      sondear, function() {
        is.null(presupuesto) || .saldo_dbi(presupuesto) >= 1
      }, length(lote), .tope_sondas_agregados_dbi(presupuesto, length(lote)),
      conservar_legibles = TRUE
    )
    grupos <- aislamiento$legibles
    culpables <- aislamiento$culpables
    pendientes <- unlist(aislamiento$pendientes, use.names = FALSE)
    agotado <- isTRUE(aislamiento$agotado)
    sondas <- aislamiento$sondas
  }
  if (length(grupos)) {
    .recordar_lote_agregados_dbi(
      presupuesto, max(vapply(grupos, length, integer(1L))), "distintos"
    )
  }
  clasificados <- .sort_por_bytes(unique(c(unlist(grupos, use.names = FALSE), culpables)))
  desconocidos <- setdiff(seq_along(lote), clasificados)
  if (length(desconocidos)) {
    pendientes <- .sort_por_bytes(unique(c(pendientes, desconocidos)))
  }
  salida <- vector("list", length(lote))
  names(salida) <- lote
  estimar <- function(resultado) {
    if (is.null(aproximacion_distintos) || !isTRUE(resultado$ok)) {
      return(resultado)
    }
    resultado$metadatos <- .mezclar_metadatos_dbi(
      resultado$metadatos,
      list(
        metodo = aproximacion_distintos$nombre,
        error_esperado = aproximacion_distintos$error_esperado
      )
    )
    resultado$estado <- "estimado"
    resultado
  }
  for (grupo in grupos) {
    llave <- clave(grupo)
    entrada <- cache[[llave]]
    metadatos <- .metadatos_lote_dbi(numero, lote[grupo])
    for (i in seq_along(grupo)) {
      resultado <- .resultado_lote_dbi(
        entrada$consulta, entrada$sql, alias_por_columna[[grupo[[i]]]],
        metadatos
      )
      resultado <- .adjuntar_guardian_distintos_dbi(
        resultado, entrada$consulta,
        guardian_por_columna[[grupo[[i]]]]
      )
      salida[[lote[[grupo[[i]]]]]] <- list(
        consolidada = TRUE, distintos = estimar(resultado)
      )
    }
  }
  for (i in culpables) {
    campo <- lote[[i]]
    metadatos <- .metadatos_lote_dbi(numero, campo)
    resultado <- .conteos_columna_dbi(
      conexion, tabla_sql, nombres_sql[[campo]], alias,
      FALSE, TRUE, presupuesto, aproximacion_distintos
    )$distintos
    resultado$metadatos <- .mezclar_metadatos_dbi(
      metadatos, resultado$metadatos
    )
    salida[[campo]] <- list(
      consolidada = FALSE, distintos = estimar(resultado)
    )
  }
  if (length(pendientes)) {
    motivo <- paste(
      "El lote de conteos distintos fue rechazado y no se pudieron aislar",
      "todas sus columnas dentro del presupuesto de sondas; las columnas",
      "pendientes no se suponen culpables ni legibles."
    )
    for (i in pendientes) {
      campo <- lote[[i]]
      sin_consulta <- .resultado_agregado_no_emitido_dbi("conteos", motivo)
      sin_consulta <- .resultado_lote_dbi(
        sin_consulta, NA_character_, alias_por_columna[[i]],
        .metadatos_lote_dbi(numero, campo)
      )
      salida[[campo]] <- list(
        consolidada = FALSE, distintos = estimar(sin_consulta)
      )
    }
  }
  list(resultados = salida, sondas = sondas, agotado = agotado,
       conteo = conteo)
}

# Como calcula el desvio la corrida, en las dos preguntas que cambian cuantas
# consultas emite: por ventana sobre la muestra del motor, sin sondear la forma,
# o en una segunda pasada centrada sobre la tabla. Las hacen los agregados y el
# plan con estas mismas funciones; con dos copias de la regla, el plan cobraba
# las dos consultas de la forma tambien en la muestra, donde no se emiten, y no
# veia la segunda pasada de MySQL sin `basicos`.
.desvio_por_ventana_dbi <- function(conexion, metricas, universo) {
  "desvio" %in% metricas && identical(universo, "muestra_motor") &&
    .soporta_ventana_desvio_dbi(conexion)
}

.desvio_separado_dbi <- function(conexion, metricas, universo,
                                 columnas_float8_numeric = character()) {
  if (!"desvio" %in% metricas || !identical(universo, "tabla_completa")) {
    return(FALSE)
  }
  senas <- .senas_conexion_dbi(conexion)
  grepl("sql server|microsoft sql|sqlserver|mssql", senas, perl = TRUE,
        useBytes = TRUE) ||
    (grepl("postgres|pqconnection", senas, useBytes = TRUE) &&
       length(columnas_float8_numeric) > 0L) ||
    (.es_mysql_dbi(senas) && !"basicos" %in% metricas)
}

.agregados_consolidados_dbi <- function(conexion, tabla_sql, columnas,
                                        columnas_sql, es_numerico, metricas,
                                        incluir_valores, presupuesto,
                                        tamano_lote_planos,
                                        tamano_lote_distintos = .TAMANO_LOTE_DISTINTOS_DBI,
                                        aproximacion_distintos = NULL,
                                        tabla_total_sql = tabla_sql,
                                        conteo_inicial = NULL,
                                        columnas_distintos = NULL,
                                        tipos_declarados = NULL,
                                        columnas_float8_numeric = character(),
                                        infinitos_como_numeric = FALSE,
                                        universo = "tabla_completa") {
  alias <- function(nombre) {
    .citar_identificador_dbi(conexion, nombre)
  }
  por_columna <- function() {
    salida <- vector("list", length(columnas))
    names(salida) <- columnas
    salida
  }
  agregados <- list(
    conteos = por_columna(), basicos = por_columna(), desvio = por_columna()
  )
  configuracion_aviso <- function(nombre, defecto) {
    valor <- if (is.null(presupuesto)) NULL else presupuesto[[nombre]]
    if (is.null(valor)) defecto else valor
  }
  nombres_sql <- stats::setNames(columnas_sql, columnas)
  conteo <- conteo_inicial
  n_total <- if (is.null(conteo)) NA_real_ else .conteo_dbi(conteo$valor)
  tomar_conteo <- function(resultado) {
    if (is.null(conteo) && !is.null(resultado$conteo)) {
      conteo <<- resultado$conteo
      n_total <<- .conteo_dbi(conteo$valor)
    }
    invisible(NULL)
  }

  senas <- .senas_conexion_dbi(conexion)
  mysql <- .es_mysql_dbi(senas)
  tipos_por_nombre <- if (is.null(tipos_declarados)) {
    NULL
  } else {
    stats::setNames(as.character(tipos_declarados), columnas)
  }
  ventana_desvio <- .desvio_por_ventana_dbi(conexion, metricas, universo)
  # La media y el desvio de un decimal salen de sus sumas exactas, pedidas en
  # el mismo lote de agregados (ver `.agregados_lote_con_biseccion_dbi()`), por
  # la tabla completa y bajo la muestra del motor. La cota de filas es la de la
  # tabla.
  decimales_exactos <- NULL
  if (!is.null(tipos_por_nombre) && any(c("basicos", "desvio") %in% metricas)) {
    for (i in seq_along(columnas)) {
      tipo <- tipos_por_nombre[[columnas[[i]]]]
      if (!isTRUE(es_numerico[[i]]) ||
          !.mediana_decimal_por_centrales_dbi(senas, tipo)) {
        next
      }
      decimales_exactos[[columnas[[i]]]] <- list(
        tipo = tipo, filas = if (is.finite(n_total)) n_total else 1e12,
        desvio = "desvio" %in% metricas
      )
    }
  }
  separar_desvio <- .desvio_separado_dbi(
    conexion, metricas, universo, columnas_float8_numeric
  )
  columnas_desvio_exactas <- columnas_float8_numeric
  metricas_planas <- intersect(c("validos", "basicos", "desvio"), metricas)
  if (separar_desvio) {
    # La forma nativa de una pasada puede perder cifras cuando la media es
    # mucho mayor que el desvio. Se conserva la exactitud calculando el centro
    # en el lote de basicos y el desvio centrado en un segundo lote.
    metricas_planas <- setdiff(metricas_planas, "desvio")
  }
  metricas_consulta <- metricas_planas
  if (separar_desvio) metricas_consulta <- unique(c(metricas_consulta, "basicos"))
  numericas <- columnas[es_numerico]
  columnas_planas <- if ("validos" %in% metricas_planas) {
    columnas
  } else {
    numericas
  }
  if (length(metricas_consulta) && length(columnas_planas)) {
    if (isTRUE(ventana_desvio)) {
      forma <- .forma_desvio_ventana_dbi(conexion)
      if (!is.null(presupuesto)) presupuesto$forma_desvio <- forma
    } else {
      if ("desvio" %in% metricas || separar_desvio) .sondar_forma_desvio(
        conexion, presupuesto, alias
      )
      forma <- presupuesto$forma_desvio
    }
    lotes <- .lotes_columnas_dbi(columnas_planas, tamano_lote_planos)
    etapa <- if ("basicos" %in% metricas_consulta) {
      "basicos"
    } else if ("desvio" %in% metricas_consulta) {
      "desvio"
    } else {
      "conteos"
    }
    for (numero in seq_along(lotes)) {
      lote <- lotes[[numero]]
      indices <- .indice_nombre(lote, columnas)
      es_numerico_lote <- es_numerico[indices]
      resultado_lote <- .agregados_lote_con_biseccion_dbi(
        conexion, tabla_sql, lote, nombres_sql, es_numerico_lote,
        metricas_consulta, incluir_valores, presupuesto, numero,
        alias, forma, etapa,
        # El total va siempre en los agregados: sin `validos` se pedia aparte,
        # en una consulta que el plan no cuenta.
        incluir_total = TRUE,
        tabla_total_sql = tabla_total_sql,
        columnas_float8_numeric = columnas_float8_numeric,
        infinitos_como_numeric = infinitos_como_numeric,
        tipos_declarados = tipos_por_nombre,
        ventana_desvio = ventana_desvio,
        decimales_exactos = decimales_exactos,
        incluir_cuenta = TRUE,
        incluir_magnitud = identical(universo, "muestra_motor")
      )
      tomar_conteo(resultado_lote)
      resultado_lote <- resultado_lote$resultados
      for (campo in lote) {
        resultado <- resultado_lote[[campo]]
        # Un resultado con filas pero sin uno de sus alias no es un rechazo de
        # columna. Mantener el reintento anterior por metrica evita cambiar la
        # disponibilidad si un controlador pliega o renombra los alias.
        if ("validos" %in% metricas_consulta &&
            !is.null(resultado$validos) && !isTRUE(resultado$validos$ok) &&
            isTRUE(resultado$consolidada)) {
          resultado$validos <- .conteos_columna_dbi(
            conexion, tabla_sql, nombres_sql[[campo]], alias,
            TRUE, FALSE, presupuesto, incluir_total = TRUE
          )$validos
        }
        if ("basicos" %in% metricas_consulta &&
            !is.null(resultado$basicos) && !isTRUE(resultado$basicos$ok) &&
            isTRUE(resultado$consolidada)) {
          resultado$basicos <- .basicos_columna_dbi(
            conexion, tabla_sql, nombres_sql[[campo]], alias, incluir_valores,
            presupuesto, .metadatos_lote_dbi(numero, campo),
            float8_seguro = campo %in% columnas_float8_numeric,
            infinitos_como_numeric = isTRUE(infinitos_como_numeric) &&
              campo %in% columnas_float8_numeric ||
              .es_lectura_double_exacta_dbi(nombres_sql[[campo]]),
            tipo = if (is.null(tipos_por_nombre)) NA_character_ else
              tipos_por_nombre[[campo]] %||% NA_character_
          )
        }
        desvio_consolidado <- if (is.null(resultado$desvio)) {
          NA_real_
        } else {
          suppressWarnings(as.numeric(resultado$desvio$valor %||% NA_real_))
        }
        mysql <- .es_mysql_dbi(senas) && .es_conexion_mysql_dbi(conexion)
        desvio_no_utilizable <- !is.null(resultado$desvio) && (
          !isTRUE(resultado$desvio$ok) ||
            (mysql && (length(desvio_consolidado) != 1L ||
                       !is.finite(desvio_consolidado)))
        )
        # Bajo la muestra del motor la repeticion sortearia otra muestra: el
        # desvio queda el del lote, y la cuenta del lote dice si faltaban
        # valores (`.valores_ausentes_por_cuenta_dbi()`).
        if ("desvio" %in% metricas_consulta && desvio_no_utilizable &&
            isTRUE(resultado$consolidada) &&
            !identical(universo, "muestra_motor")) {
          # El desvio se repite solo, pero las filas que vio la muestra las
          # conto el lote: sin ese denominador, una muestra sin filas no se
          # distingue de una con valores nulos.
          denominador_lote <- resultado$desvio$metadatos[c(
            "n_total_consulta", "consulta_id_denominador"
          )]
          if (!isTRUE(is.finite(.numero_dbi(
            denominador_lote$n_total_consulta
          )))) {
            denominador_lote <- NULL
          }
          resultado$desvio <- .desvio_columna_dbi(
            conexion, tabla_sql, nombres_sql[[campo]], alias, forma,
            presupuesto, .metadatos_lote_dbi(numero, campo),
            numeric_exact = isTRUE(infinitos_como_numeric) &&
              campo %in% columnas_float8_numeric ||
              .es_lectura_double_exacta_dbi(nombres_sql[[campo]]),
            infinitos_como_numeric = isTRUE(infinitos_como_numeric) &&
              campo %in% columnas_float8_numeric ||
              .es_lectura_double_exacta_dbi(nombres_sql[[campo]])
          )
          if (!is.null(denominador_lote) && !is.null(resultado$desvio) &&
              !is.finite(.numero_dbi(
                resultado$desvio$metadatos$n_total_consulta
              ))) {
            resultado$desvio$metadatos <- .mezclar_metadatos_dbi(
              resultado$desvio$metadatos, denominador_lote
            )
          }
        }
        if ("validos" %in% metricas) {
          base_conteos <- agregados$conteos[[campo]]
          if (is.null(base_conteos)) base_conteos <- list(consolidada = TRUE)
          agregados$conteos[[campo]] <- utils::modifyList(
            base_conteos, list(validos = resultado$validos)
          )
        }
        if ("basicos" %in% metricas && !is.null(resultado$basicos)) {
          agregados$basicos[[campo]] <- resultado$basicos
        }
        if (!is.null(decimales_exactos[[campo]])) {
          agregados$exactos[[campo]] <- resultado$exacto_decimal %||% list(
            media = NA_real_, desvio = NA_real_, sql = NA_character_
          )
        }
        if (!is.null(resultado$cuenta_valores)) {
          agregados$cuentas[[campo]] <- resultado$cuenta_valores
        }
        if (!is.null(resultado$magnitud_lote)) {
          agregados$magnitudes[[campo]] <- resultado$magnitud_lote
        }
        if ("desvio" %in% metricas_planas && !is.null(resultado$desvio)) {
          agregados$desvio[[campo]] <- resultado$desvio
        }
      }
      if (separar_desvio && "desvio" %in% metricas) {
        centro_de <- function(campo) {
          resultado <- resultado_lote[[campo]]
          basicos <- if (is.null(resultado)) NULL else resultado$basicos
          if (is.null(basicos) || !isTRUE(basicos$ok)) return(NA_real_)
          media <- .valor_campo_dbi(basicos$datos, "media")
          if (!isTRUE(media$ok)) return(NA_real_)
          valor <- suppressWarnings(as.numeric(media$valor))
          if (length(valor) != 1L || !is.finite(valor)) NA_real_ else valor
        }
        centros <- stats::setNames(
          lapply(lote, centro_de), lote
        )
        es_extremo_float8 <- function(campo) {
          if (!(campo %in% columnas_float8_numeric)) return(FALSE)
          resultado <- resultado_lote[[campo]]
          basicos <- if (is.null(resultado)) NULL else resultado$basicos
          if (is.null(basicos) || !isTRUE(basicos$ok) ||
              !is.data.frame(basicos$datos) || !nrow(basicos$datos)) {
            return(FALSE)
          }
          valores <- vapply(
            c("minimo", "maximo", "media"),
            function(metrica) {
              celda <- .valor_campo_dbi(basicos$datos, metrica)
              if (isTRUE(celda$ok)) suppressWarnings(as.numeric(celda$valor))
              else NA_real_
            }, numeric(1L)
          )
          any(abs(valores) > 1e150, na.rm = TRUE)
        }
        columnas_desvio_exactas <- lote[vapply(
          lote, es_extremo_float8, logical(1L)
        )]
        columnas_desvio <- lote[es_numerico_lote & vapply(
          centros, function(x) length(x) == 1L && is.finite(x), logical(1L)
        )]
        if (length(columnas_desvio)) {
          indices_desvio <- .indice_nombre(columnas_desvio, columnas)
          resultado_desvio <- .agregados_lote_con_biseccion_dbi(
            conexion, tabla_sql, columnas_desvio, nombres_sql,
            es_numerico[indices_desvio], "desvio", incluir_valores,
            presupuesto, numero, alias, forma,
            etapa = "desvio", incluir_total = FALSE,
            tabla_total_sql = tabla_total_sql,
            columnas_float8_numeric = columnas_desvio_exactas,
            infinitos_como_numeric = infinitos_como_numeric,
            centros_desvio = centros[columnas_desvio],
            tipos_declarados = tipos_por_nombre
          )$resultados
          for (campo in columnas_desvio) {
            resultado <- resultado_desvio[[campo]]
            desvio <- if (is.null(resultado)) NULL else resultado$desvio
            if (!is.null(desvio) && isTRUE(desvio$ok)) {
              agregados$desvio[[campo]] <- desvio
            }
          }
        }
        for (campo in lote[es_numerico_lote]) {
          if (!is.null(agregados$desvio[[campo]]) &&
              isTRUE(agregados$desvio[[campo]]$ok)) next
          resultado <- .desvio_columna_dbi(
            conexion, tabla_sql, nombres_sql[[campo]], alias, forma,
            presupuesto, .metadatos_lote_dbi(numero, campo),
            centro = centros[[campo]],
            numeric_exact = campo %in% columnas_desvio_exactas ||
              .es_lectura_double_exacta_dbi(nombres_sql[[campo]]),
            infinitos_como_numeric = isTRUE(infinitos_como_numeric) &&
              campo %in% columnas_float8_numeric ||
              .es_lectura_double_exacta_dbi(nombres_sql[[campo]])
          )
          agregados$desvio[[campo]] <- resultado
        }
      }
    }
  }
  # Si no hubo una familia plana que pudiera llevar el total fusionado, se
  # obtiene ahora, antes de pagar cualquier cardinalidad exacta.
  if (is.null(conteo)) {
    total_alias <- alias("lupa_n_total")
    sql_total <- paste0(
      "SELECT ", .conteo_sql_dbi("COUNT(*)", senas), " AS ",
      total_alias, " FROM ", tabla_total_sql
    )
    conteo <- .escalar_dbi(
      conexion, sql_total, .nombre_alias_dbi(total_alias), presupuesto,
      etapa = "conteo_filas"
    )
    conteo$sql <- sql_total
    n_total <- .conteo_dbi(conteo$valor)
  }
  if (!is.null(presupuesto) && !is.null(conteo) && isTRUE(conteo$ok)) {
    duracion_lectura <- .numero_dbi(conteo$duracion_ms)
    if (length(duracion_lectura) == 1L && is.finite(duracion_lectura) &&
        duracion_lectura > 0) {
      presupuesto$duracion_lectura_mediana <- duracion_lectura
    }
  }
  # Primero quedan disponibles los agregados planos y el total exacto que se
  # fusiona con su primera consulta. Despues se paga COUNT(DISTINCT),
  # que conserva su propia familia y su lote conservador.
  if ("distintos" %in% metricas &&
      (is.null(columnas_distintos) || length(columnas_distintos))) {
    if (is.null(columnas_distintos)) columnas_distintos <- columnas
    n_lotes_distintos <- length(.lotes_columnas_dbi(
      columnas_distintos, tamano_lote_distintos
    ))
    if (!is.null(aproximacion_distintos)) {
      presupuesto$proyeccion_distintos <- .proyeccion_distintos_vacia_dbi(
        n_lotes_distintos,
        paste(
          "La estrategia de distintos es aproximada; no se proyecta el costo",
          "de `COUNT(DISTINCT)` exacto."
        )
      )
    }
    .avisar_derrame_estimado_postgresql_dbi(
      if (is.null(presupuesto)) NULL else presupuesto$estimacion_derrame,
      habilitado = configuracion_aviso("avisar_derrame_estimado", TRUE),
      umbral_bytes = configuracion_aviso(
        "umbral_bytes_aviso_derrame_estimado",
        .UMBRAL_BYTES_AVISO_DERRAME_ESTIMADO_DBI
      )
    )
    lotes <- .lotes_columnas_dbi(
      columnas_distintos, tamano_lote_distintos
    )
    for (numero in seq_along(lotes)) {
      lote <- lotes[[numero]]
      resultado_lote <- .conteos_distintos_lote_dbi(
        conexion, tabla_sql, lote, nombres_sql, alias, numero, presupuesto,
        aproximacion_distintos,
        incluir_total = FALSE, tabla_total_sql = tabla_total_sql
      )
      tomar_conteo(resultado_lote)
      if (is.null(aproximacion_distintos) && numero == 1L &&
          is.null(presupuesto$proyeccion_distintos)) {
        resultados_referencia <- resultado_lote$resultados
        if (is.list(resultados_referencia)) {
          for (resultado_columna in resultados_referencia) {
            if (is.list(resultado_columna) &&
                !is.null(resultado_columna$distintos)) {
              .registrar_referencia_distintos_dbi(
                presupuesto, resultado_columna$distintos
              )
            }
          }
        }
        proyeccion <- .proyectar_costo_distintos_dbi(
          presupuesto, n_lotes_distintos
        )
        presupuesto$proyeccion_distintos <- proyeccion
        # El aviso temporal llega despues de pagar el primer lote, que es la
        # referencia honesta, y antes de iniciar el segundo. Con un solo lote
        # no hay trabajo futuro que evitar y la proyeccion se declara ausente.
        if (n_lotes_distintos > 1L) {
          .avisar_costo_distintos_dbi(
            proyeccion,
            habilitado = configuracion_aviso("avisar_costo_distintos", TRUE),
            umbral_segundos = configuracion_aviso(
              "umbral_segundos_aviso_distintos",
              .UMBRAL_SEGUNDOS_AVISO_DISTINTOS_DBI
            )
          )
        }
      }
      resultados <- resultado_lote$resultados
      for (campo in lote) {
        base_conteos <- agregados$conteos[[campo]]
        if (is.null(base_conteos)) base_conteos <- list()
        agregados$conteos[[campo]] <- utils::modifyList(
          base_conteos, resultados[[campo]]
        )
      }
    }
  }
  agregados$n_total <- n_total
  agregados$conteo <- conteo
  agregados$sql_conteo <- if (is.null(conteo$sql)) NA_character_ else conteo$sql
  agregados$estimacion_derrame <- if (is.null(presupuesto)) {
    .estimacion_derrame_vacia_postgresql_dbi(
      "no_solicitado", "No se solicit\u00f3 una estimaci\u00f3n de derrame."
    )
  } else presupuesto$estimacion_derrame
  agregados
}

.moda_columna_dbi <- function(conexion, tabla_sql, columna_sql, dialecto,
                              presupuesto, moda_guardian = NULL,
                              valor_sql = columna_sql,
                              orden_sql = columna_sql) {
  alias <- function(nombre) {
    .citar_identificador_dbi(conexion, nombre)
  }
  consulta <- .sql_moda_columna_dbi(
    conexion, tabla_sql, columna_sql, dialecto, moda_guardian, valor_sql,
    orden_sql
  )
  sql_moda <- consulta$sql
  resultado <- .consultar_dbi(
    conexion, sql_moda, presupuesto, filas = consulta$filas,
    etapa = "moda"
  )
  resultado$sql <- sql_moda
  resultado$metadatos <- list(
    metodo = if (is.null(moda_guardian)) {
      "consulta_actual_sin_guardian"
    } else {
      moda_guardian$nombre
    },
    n_validos_guard = NA_real_,
    consulta_id_guard = NA_integer_,
    cota_comprobable = FALSE
  )
  if (!is.null(moda_guardian)) {
    resultado <- .adjuntar_guardian_moda_dbi(
      resultado, resultado, alias("n_validos_guard")
    )
  }
  resultado
}

# Promedio de una o dos centrales que no desborda. Dos centrales no necesitan
# la escala de la columna: `a / 2 + b / 2` es exacto con valores enormes y
# `(a + b) / 2` con los demas. Dividirlos por una escala elegida con el maximo
# de TODA la columna hacia desbordar hacia abajo a un central subnormal
# (`5e-324 / 2^1022`), y PostgreSQL lo rechaza con "value out of range:
# underflow". Lo usan la via de dos consultas y la CTE de ventanas de la
# muestra, que tienen que dar el mismo numero.
.promedio_centrales_escalado_sql_dbi <- function(valor) {
  paste0(
    "CASE WHEN COUNT(*) = 2 THEN CASE WHEN MAX(ABS(", valor,
    ")) > 1e150 THEN MAX(", valor, ") / 2e0 + MIN(", valor,
    ") / 2e0 ELSE (MAX(", valor, ") + MIN(", valor,
    ")) / 2e0 END ELSE MAX(", valor, ") END"
  )
}

# La mediana de dos centrales se puede obtener sin sumar los valores enteros:
# dividir cada uno antes de sumar evita el desborde de la suma y conserva el
# promedio exacto para los dobles normales (los subnormales no entran en este
# repliegue). Una sola fila vuelve por MAX y no se promedia.
.mediana_escalada_dbi <- function(
    conexion, tabla_sql, columna_sql, alias, dialecto, n_validos,
    presupuesto = NULL) {
  n_validos <- .numero_dbi(n_validos)
  if (length(n_validos) != 1L || is.na(n_validos) ||
      !is.finite(n_validos) || n_validos < 1) {
    return(NULL)
  }
  limite <- if (n_validos %% 2 == 0) 2 else 1
  desplazamiento <- floor((n_validos - 1) / 2)
  interna <- paste0(
    "SELECT ", columna_sql, " AS ", alias("valor"),
    " FROM ", tabla_sql, " WHERE ", columna_sql,
    " IS NOT NULL ORDER BY ", columna_sql
  )
  acotada <- dialecto$limitar(interna, limite, desplazamiento)
  if (is.null(acotada)) return(NULL)
  fuente <- paste0(
    "(", acotada, ")", dialecto$alias_tabla("lupa_mediana_valores")
  )
  sql <- paste0(
    "SELECT ", .promedio_centrales_escalado_sql_dbi(alias("valor")),
    " AS ", alias("mediana"), " FROM ", fuente
  )
  resultado <- .escalar_dbi(
    conexion, sql, "mediana", presupuesto, etapa = "mediana"
  )
  resultado$sql <- sql
  resultado$metadatos <- list(metodo = "dos_centrales_escaladas")
  resultado
}

.requiere_mediana_escalada_dbi <- function(fila, n_validos, conexion = NULL) {
  n_validos <- .numero_dbi(n_validos)
  extremos <- suppressWarnings(as.numeric(c(fila$minimo, fila$maximo)))
  extremos <- abs(extremos[is.finite(extremos)])
  forzar_mysql <- !is.null(conexion) && .es_mysql_dbi(
    .senas_conexion_dbi(conexion)
  ) && length(extremos) && max(extremos) > 1e65
  length(n_validos) == 1L && is.finite(n_validos) &&
    n_validos >= 1 && length(extremos) &&
    !is.null(.escala_desvio_dbi(
      max(extremos), forzar = forzar_mysql, rango = diff(range(extremos))
    ))
}

.resumen_columna_dbi <- function(conexion, tabla_sql, columna, prototipo,
                                 n_total, dialecto = NULL,
                                 metricas = .METRICAS_DBI, presupuesto = NULL,
                                 incluir_valores = TRUE,
                                 tipo_declarado = NA_character_,
                                 tipo_motor = NA_character_,
                                 motivo_ilegible = NA_character_,
                                 universo = "tabla_completa", muestreo = NULL,
                                 aproximacion_distintos = NULL,
                                 aproximacion_mediana = NULL,
                                 tamano_muestra = NA_real_,
                                 fraccion_muestra = NA_real_,
                                 agregados = NULL,
                                 mediana_consolidada = NULL,
                                 mediana_escalar = NULL,
                                 mediana_cte_ventana = NULL,
                                 mediana_cte_ventana_motivo = NA_character_,
                                 moda_guardian = NULL,
                                 moda_precalculada = NULL,
                                 moda_entero_doble = NULL,
                                 decisiones_costo = NULL,
                                 publica_distintos = TRUE,
                                 estrategia_distintos = NULL,
                                 solo_finitos = FALSE,
                                 infinitos_como_numeric = FALSE,
                                 numeric_exact = FALSE,
                                 columna_sql = NULL) {
  if (is.null(dialecto)) dialecto <- .dialectos_dbi()$limit
  if (is.null(estrategia_distintos)) {
    estrategia_distintos <- list(
      estrategia_solicitada = "exacta",
      estrategia_resuelta = "COUNT(DISTINCT)",
      estado = "calculado", disponible = TRUE,
      motivo = NA_character_, error_esperado = "no_aplica",
      publica = isTRUE(publica_distintos), para_costo = FALSE,
      requiere_medicion = isTRUE(publica_distintos), sondas = character()
    )
  }
  tipo_operacion <- if (length(tipo_motor) == 1L && !is.na(tipo_motor)) {
    as.character(tipo_motor)
  } else tipo_declarado
  if (is.null(moda_entero_doble)) {
    moda_entero_doble <- .entero_doble_ancho_moda_dbi(
      prototipo, tipo_operacion,
      .extremos_basicos_moda_dbi(agregados, columna)
    )
  }
  motor_sqlserver <- grepl(
    "sql server|microsoft sql|sqlserver|mssql",
    .senas_conexion_dbi(conexion), perl = TRUE, useBytes = TRUE
  )
  tipo_sin_agregados <- any(grepl(
    "sql server|microsoft sql|sqlserver|mssql",
    .senas_conexion_dbi(conexion), perl = TRUE, useBytes = TRUE
  )) && .tipo_sqlserver_sin_agregados_dbi(tipo_operacion)
  motivo_tipo_sin_agregados <- if (tipo_sin_agregados) {
    .motivo_tipo_sqlserver_sin_agregados_dbi(tipo_operacion)
  } else NA_character_
  if (tipo_sin_agregados) {
    estrategia_distintos$disponible <- FALSE
    estrategia_distintos$estado <- "no_disponible"
    estrategia_distintos$motivo <- motivo_tipo_sin_agregados
  }
  fila <- .fila_resumen_dbi(columna, n_total)
  infinitos_columna_como_numeric <- isTRUE(infinitos_como_numeric) ||
    .es_lectura_double_exacta_dbi(columna_sql)
  literales <- character()
  es_muestreado <- identical(universo, "muestra_motor")
  if (grepl("postgres|pqconnection", .senas_conexion_dbi(conexion),
            useBytes = TRUE) &&
      .tipo_declarado_float8_dbi(tipo_operacion, conexion) &&
      !.es_lectura_double_exacta_dbi(columna_sql)) {
    numeric_exact <- TRUE
  }
  # En PostgreSQL la mediana exacta de un float8 se calcula sobre los dos
  # valores centrales leidos como NUMERIC. Las formas sondadas con
  # `percentile_cont`, una CTE o una division escalar pueden redondear el ultimo
  # bit de 1/3 y otros pares cercanos. En tabla completa conviene la forma
  # exacta local; la muestra conserva sus limites y su contrato propio.
  if (isTRUE(numeric_exact) && !es_muestreado &&
      grepl("postgres|pqconnection", .senas_conexion_dbi(conexion),
            useBytes = TRUE)) {
    aproximacion_mediana <- NULL
    mediana_escalar <- NULL
    mediana_cte_ventana <- NULL
  }
  metricas_de_error <- unlist(
    .CAMPOS_METRICA_DBI[metricas], use.names = FALSE
  )
  error_esperado <- if (es_muestreado) {
    .error_esperado_muestreo_dbi(
      metricas_de_error, muestreo, fraccion_muestra
    )
  } else {
    "no_aplica"
  }
  metadatos <- if (es_muestreado) {
    .metadatos_sql_dbi(
      alcance = "muestra", universo = n_total,
      tamano_muestra = tamano_muestra, fraccion = fraccion_muestra,
      metodo = if (is.null(muestreo) || is.null(muestreo$metodo)) {
        NA_character_
      } else {
        muestreo$metodo
      },
      error_esperado = error_esperado
    )
  } else {
    .metadatos_sql_dbi(
      alcance = "tabla_completa", universo = n_total, tamano_muestra = NA,
      fraccion = 1, metodo = "tabla_completa",
      error_esperado = "no_aplica"
    )
  }
  if (es_muestreado) {
    metadatos$muestreo_regla <- if (is.null(muestreo)) {
      list(disponible = FALSE)
    } else muestreo
    metadatos$fraccion_regla <- fraccion_muestra
  }
  metadatos <- .agregar_metadatos_estrategia_distintos_dbi(
    metadatos, estrategia_distintos
  )
  if (es_muestreado && !is.null(muestreo) &&
      !isTRUE(muestreo$disponible)) {
    # La incapacidad de construir o gobernar la fuente afecta a todas las
    # metricas de este alcance. El total `n` se registra fuera de esta funcion;
    # aqui no se permite que la ruta de respaldo lea `tabla_sql` completa.
    motivo_muestreo <- if (length(muestreo$motivo) == 1L &&
                           !is.na(muestreo$motivo)) {
      as.character(muestreo$motivo)
    } else {
      "capacidad_no_aceptada:sonda_muestreo"
    }
    registros <- .metricas_omitidas_dbi(
      list(), columna, metricas, "no_disponible", motivo_muestreo,
      metadatos = metadatos
    )
    return(list(
      fila = fila, sql = do.call(rbind, registros), literales = literales
    ))
  }
  registrar <- function(registros, metrica, resultado, motivo_exito = NA_character_) {
    metricas_registro <- as.character(metrica)
    metadatos_registro <- metadatos
    motivos_registro <- rep_len(as.character(motivo_exito),
                                length(metricas_registro))
    if (es_muestreado) {
      clasificaciones <- lapply(metricas_registro, function(nombre) {
        .clasificar_metrica_muestreo_dbi(
          nombre, muestreo, fraccion_muestra
        )
      })
      conocidas <- vapply(
        clasificaciones, function(x) isTRUE(x$conocida), logical(1L)
      )
      if (all(conocidas)) {
        metadatos_registro$error_esperado <- vapply(
          clasificaciones, `[[`, character(1L), "error_esperado"
        )
        if (isTRUE(resultado$ok)) {
          estados <- vapply(
            clasificaciones, `[[`, character(1L), "estado"
          )
          if (all(!is.na(estados))) resultado$estado <- estados
        }
        for (i in seq_along(metricas_registro)) {
          if (is.na(motivos_registro[[i]])) {
            motivos_registro[[i]] <- clasificaciones[[i]]$motivo
          }
        }
      }
      if (isTRUE(resultado$ok) &&
          any(metricas_registro %in% "mediana") &&
          !is.null(muestreo) && length(muestreo$motivo) == 1L &&
          !is.na(muestreo$motivo) &&
          grepl("^sesgo_muestreo:", as.character(muestreo$motivo))) {
        motivo_muestreo <- as.character(muestreo$motivo)
        indice_mediana <- match("mediana", metricas_registro)
        if (!is.na(indice_mediana)) {
          motivos_registro[[indice_mediana]] <- if (
            is.na(motivos_registro[[indice_mediana]]) ||
            !nzchar(as.character(motivos_registro[[indice_mediana]]))
          ) {
            motivo_muestreo
          } else {
            paste(motivo_muestreo,
                  as.character(motivos_registro[[indice_mediana]]),
                  sep = "; ")
          }
        }
      }
    }
    .registrar_resultado_dbi(
      registros, columna, metricas_registro, resultado, motivos_registro,
      metadatos = metadatos_registro
    )
  }
  omitir <- function(registros, metrica, estado, motivo) {
    .metricas_omitidas_dbi(
      registros, columna, metrica, estado, motivo, metadatos = metadatos
    )
  }
  if (!is.na(motivo_ilegible)) {
    registros <- .metricas_omitidas_dbi(
      list(), columna, .METRICAS_DBI, "no_disponible", motivo_ilegible,
      metadatos = metadatos
    )
    return(list(
      fila = fila, sql = do.call(rbind, registros), literales = literales
    ))
  }
  if (es_muestreado && (is.null(muestreo) || !isTRUE(muestreo$disponible))) {
    motivo <- if (is.null(muestreo)) {
      "No se resolvi\u00f3 una capacidad de muestreo del motor."
    } else {
      muestreo$motivo
    }
    registros <- omitir(list(), .METRICAS_DBI, "no_disponible", motivo)
    return(list(
      fila = fila, sql = do.call(rbind, registros), literales = literales
    ))
  }
  columna_sql <- if (length(columna_sql) == 1L && !is.na(columna_sql) &&
                     nzchar(columna_sql)) {
    as.character(columna_sql)
  } else {
    .citar_identificador_dbi(conexion, columna)
  }
  alias <- function(nombre) {
    .citar_identificador_dbi(conexion, nombre)
  }
  registros <- list()
  motivo_no_pedida <- paste(
    "La m\u00e9trica no se pidi\u00f3 en esta corrida; ver `metricas`."
  )
  motivo_privacidad <- paste(
    "El valor no se informa por `incluir_valores = FALSE`;",
    "la consulta no se emitio."
  )
  filas_mediana <- if (es_muestreado) .numero_dbi(tamano_muestra) else
    .numero_dbi(n_total)
  preparar_aviso_mediana <- function() {
    if (is.null(presupuesto)) return(invisible(NULL))
    pendientes <- .numero_dbi(presupuesto$medianas_pendientes)
    if (length(pendientes) != 1L || is.na(pendientes) ||
        !is.finite(pendientes) || pendientes < 1) pendientes <- 1
    proyeccion <- .proyectar_costo_mediana_dbi(
      presupuesto, filas_mediana, pendientes,
      usar_referencia_banco = pendientes == 1L
    )
    if (isTRUE(proyeccion$disponible)) {
      presupuesto$proyeccion_mediana <- proyeccion
      if (!isTRUE(presupuesto$aviso_mediana_emitido)) {
        avisado <- .avisar_costo_mediana_dbi(
          proyeccion,
          habilitado = if (is.null(presupuesto$avisar_costo_mediana)) TRUE else
            presupuesto$avisar_costo_mediana,
          umbral_segundos = if (is.null(presupuesto$umbral_segundos_aviso_mediana)) {
            .UMBRAL_SEGUNDOS_AVISO_MEDIANA_DBI
          } else presupuesto$umbral_segundos_aviso_mediana
        )
        if (isTRUE(avisado)) presupuesto$aviso_mediana_emitido <- TRUE
      }
    }
    invisible(NULL)
  }
  finalizar_mediana <- function(resultado) {
    .registrar_referencia_mediana_dbi(
      presupuesto, resultado, filas_mediana, n_medianas = 1L
    )
    if (!is.null(presupuesto)) {
      pendientes <- .numero_dbi(presupuesto$medianas_pendientes)
      if (isTRUE(resultado$ok) && length(pendientes) == 1L &&
          is.finite(pendientes)) {
        presupuesto$medianas_pendientes <- max(0, pendientes - 1L)
      }
      if (isTRUE(resultado$ok) && isTRUE(presupuesto$medianas_pendientes > 0)) {
        presupuesto$proyeccion_mediana <- .proyectar_costo_mediana_dbi(
          presupuesto, filas_mediana, presupuesto$medianas_pendientes
        )
      }
    }
    invisible(NULL)
  }
  # `sql_escalada` es la forma que no desborda cuando la normal no alcanza. Sin
  # ella, la de dos consultas de `.mediana_escalada_dbi()`; la CTE de la muestra
  # pasa la suya, que lee la misma relacion en una sola sentencia.
  ejecutar_mediana <- function(sql_normal, sql_escalada = NULL) {
    guardia <- guardia_mediana()
    n_validos_mediana <- guardia$n
    escala_mediana <- guardia$escala
    extremo <- guardia$requiere
    # La forma de una sentencia cuenta sus propias filas: basta con que los
    # extremos pidan escala. `guardia$requiere` exige ademas el conteo, que la
    # via de dos consultas necesita para el salto; sin `validos` entre las
    # metricas no se conoce, la normal corria con +-1,7e308 y MySQL devolvia 0
    # sin error (PostgreSQL, "value out of range").
    if (!is.null(sql_escalada)) extremo <- !is.null(escala_mediana)
    escalar <- function() {
      if (is.null(sql_escalada)) {
        return(.mediana_escalada_dbi(
          conexion, tabla_sql, columna_sql, alias, dialecto,
          n_validos_mediana, presupuesto
        ))
      }
      # Sin valores no hay centrales que promediar: no se paga otra consulta.
      n <- .numero_dbi(n_validos_mediana)
      if (length(n) == 1L && isTRUE(n < 1)) return(NULL)
      resultado <- .escalar_dbi(
        conexion, sql_escalada, "mediana", presupuesto, etapa = "mediana"
      )
      resultado$sql <- sql_escalada
      resultado
    }
    if (isTRUE(extremo)) {
      escalada <- escalar()
      if (is.list(escalada)) return(escalada)
    }
    # Un decimal en T-SQL, MySQL y MariaDB devuelve la suma de sus centrales y
    # cuantas son (ver `.promedio_mediana_sql_dbi()`); lo demas, el valor del
    # motor.
    normal <- if (.mediana_decimal_por_centrales_dbi(
      .senas_conexion_dbi(conexion), tipo_declarado
    )) {
      .escalar_mediana_dbi(conexion, sql_normal, presupuesto, etapa = "mediana")
    } else {
      .escalar_dbi(
        conexion, sql_normal, "mediana", presupuesto, etapa = "mediana"
      )
    }
    normal$sql <- sql_normal
    valor_normal <- suppressWarnings(as.numeric(normal$valor %||% NA_real_))
    # El repliegue de dos centrales es para un desborde, no para cualquier
    # falla: una aproximacion que el motor rechaza -la pidio el usuario para no
    # ordenar la columna entera- queda declarada como falla, no reemplazada por
    # la forma exacta, que es la cara, con la etiqueta de la aproximacion.
    desborde <- .es_desborde_motor_dbi(normal$motivo)
    necesita_repliegue <- (isTRUE(normal$ok) &&
      (length(valor_normal) != 1L || !is.finite(valor_normal))) ||
      (!isTRUE(normal$ok) && isTRUE(desborde))
    if (necesita_repliegue) {
      escalada <- escalar()
      if (is.list(escalada) && isTRUE(escalada$ok) &&
          is.finite(suppressWarnings(as.numeric(escalada$valor)))) {
        return(escalada)
      }
    }
    normal
  }

  # La mediana de la muestra con la CTE de ventanas: la forma normal y, si los
  # extremos la desbordarian, la escalada, las dos sobre la misma relacion.
  mediana_por_cte_ventana <- function(cte) {
    sql_mediana <- cte$construir(
      columna_sql, tabla_sql, alias("mediana"), tipo = tipo_declarado,
      doble_exacto = infinitos_columna_como_numeric
    )
    preparar_aviso_mediana()
    mediana <- ejecutar_mediana(
      sql_mediana,
      sql_escalada = cte$construir(
        columna_sql, tabla_sql, alias("mediana"), escalada = TRUE
      )
    )
    finalizar_mediana(mediana)
    if (is.null(mediana$sql)) mediana$sql <- sql_mediana
    mediana$metadatos <- list(metodo = cte$nombre)
    if (isTRUE(mediana$ok)) {
      valor <- .escalar_finito_dbi(mediana$valor)
      if (is.na(valor) && !es_muestreado) {
        # En la tabla completa es un dato, como en la forma escalar.
        mediana$estado <- "sin_valores"
        mediana$motivo <- "La columna no contiene valores no nulos."
      } else if (is.na(valor)) {
        mediana$ok <- FALSE
        mediana$motivo <- "muestra_inestable:sin_valores_validos"
      } else {
        mediana$valor <- valor
      }
    }
    mediana
  }

  # La via de dos consultas de la tabla completa necesita el conteo de validos
  # para el salto. Sin la metrica que lo da (`validos`, o la prueba de
  # magnitud cuando no se piden `basicos`), la mediana quedaba `no_disponible`
  # aunque el motor pudiera calcularla. Se cuenta aca, con la misma expresion
  # que la consulta compartida, y la mediana sale por el mismo camino -y con el
  # mismo numero- que cuando se pide `validos`. La CTE de ventanas tambien
  # cuenta sus filas, pero en tabla completa es la opcion cara: con un millon
  # de filas, contar y saltar costo 0,42 s contra 2,85 s en MySQL 8.4, 0,29
  # contra 1,33 en MariaDB 11.8 y 0,17 contra 0,63 en PostgreSQL 16 (medido el
  # 2026-11-06). En la muestra no hay eleccion: dos consultas leerian dos
  # muestras. Devuelve TRUE si el conteo sigue faltando.
  conteo_mediana_propio <- FALSE
  conteo_mediana_pendiente <- function() {
    if (!sin_conteo || is.finite(n_validos_sondeado)) return(FALSE)
    if (es_muestreado) return(TRUE)
    senas <- .senas_conexion_dbi(conexion)
    sql <- paste0(
      "SELECT ", .conteo_sql_dbi(.contar_no_nulos_sql_dbi(columna_sql, senas),
                                 senas),
      " AS ", alias("n_validos"), " FROM ", tabla_sql
    )
    conteo <- .escalar_dbi(
      conexion, sql, "n_validos", presupuesto, etapa = "mediana"
    )
    n <- if (isTRUE(conteo$ok)) .numero_dbi(conteo$valor) else NA_real_
    if (length(n) != 1L || !is.finite(n) || n < 0) return(TRUE)
    n_validos_sondeado <<- n
    conteo_mediana_propio <<- TRUE
    FALSE
  }

  guardia_mediana <- function() {
    n <- if (exists("validos_observados", inherits = FALSE)) {
      validos_observados
    } else if (is.finite(n_validos_sondeado)) {
      n_validos_sondeado
    } else {
      fila$n_validos
    }
    fila_mediana <- fila
    if (!is.finite(fila_mediana$minimo) && is.finite(minimo_sondeado)) {
      fila_mediana$minimo <- minimo_sondeado
    }
    if (!is.finite(fila_mediana$maximo) && is.finite(maximo_sondeado)) {
      fila_mediana$maximo <- maximo_sondeado
    }
    extremos <- suppressWarnings(as.numeric(c(
      fila_mediana$minimo, fila_mediana$maximo
    )))
    extremos <- extremos[is.finite(extremos)]
    rango <- if (length(extremos) >= 2L) {
      max(extremos) - min(extremos)
    } else NA_real_
    escala <- if (length(extremos)) {
      maximo <- max(abs(extremos), na.rm = TRUE)
      forzar_mysql <- .es_mysql_dbi(.senas_conexion_dbi(conexion)) &&
        maximo > 1e65
      .escala_desvio_dbi(
        maximo, forzar = forzar_mysql, rango = rango
      )
    } else NULL
    list(
      fila = fila_mediana, n = n, escala = escala,
      requiere = !is.null(escala) &&
        .requiere_mediana_escalada_dbi(fila_mediana, n, conexion = conexion)
    )
  }

  conteos <- if (!is.null(agregados) &&
                 !is.null(agregados$conteos[[columna]])) {
    agregados$conteos[[columna]]
  } else {
    pide_distintos <- "distintos" %in% metricas &&
      isTRUE(estrategia_distintos$disponible) &&
      !identical(estrategia_distintos$estado, "estimado_catalogo")
    .conteos_columna_dbi(
      conexion, tabla_sql, columna_sql, alias,
      "validos" %in% metricas, pide_distintos, presupuesto,
      aproximacion_distintos = aproximacion_distintos
    )
  }

  fuentes_denominador <- Filter(Negate(is.null), list(
    conteos$validos, conteos$basicos, conteos$desvio,
    conteos$distintos
  ))
  if (!is.null(agregados)) {
    fuentes_denominador <- c(
      fuentes_denominador,
      Filter(Negate(is.null), list(
        agregados$basicos[[columna]], agregados$desvio[[columna]]
      ))
    )
  }
  n_total_consulta <- if (length(fuentes_denominador)) {
    candidatos <- vapply(fuentes_denominador, function(resultado) {
      if (is.null(resultado$metadatos)) return(NA_real_)
      .numero_dbi(resultado$metadatos$n_total_consulta)
    }, numeric(1L))
    candidatos <- candidatos[is.finite(candidatos)]
    if (length(candidatos)) candidatos[[1L]] else NA_real_
  } else {
    NA_real_
  }
  # Un agregado sobre una muestra vacia devuelve ceros y una fila valida para
  # SQL, pero eso no significa que se hayan observado cero valores: no se
  # observo ninguna fila. `n_validos` y `n_distintos` no alcanzan para hacer la
  # distincion, porque una muestra no vacia puede tener todos sus valores nulos.
  # Cuando el denominador local esta disponible y vale cero, ninguna metrica de
  # alcance muestral tiene base para publicarse. `n` queda intacto porque sale
  # del conteo de la tabla completa.
  muestra_vacia <- es_muestreado && isTRUE(n_total_consulta == 0)
  if (muestra_vacia) {
    metodo_vacio <- if (is.null(muestreo$metodo) ||
                        is.na(muestreo$metodo) || !nzchar(muestreo$metodo)) {
      "muestreo_sin_metodo"
    } else as.character(muestreo$metodo)
    motivo <- paste0("muestra_vacia:", metodo_vacio, "_sin_filas")
    registros <- .metricas_omitidas_dbi(
      list(), columna, metricas, "no_disponible", motivo,
      metadatos = metadatos
    )
    return(list(
      fila = fila, sql = do.call(rbind, registros), literales = literales
    ))
  }
  tamano_pedido_muestra <- if (is.null(muestreo)) NA_real_ else {
    .numero_dbi(muestreo$tamano_muestra)
  }
  muestra_insuficiente <- es_muestreado &&
    !is.null(muestreo) &&
    identical(muestreo$metodo, "tablesample_system") &&
    length(tamano_pedido_muestra) == 1L &&
    is.finite(tamano_pedido_muestra) && tamano_pedido_muestra > 0 &&
    is.finite(n_total_consulta) &&
    n_total_consulta < tamano_pedido_muestra / 2
  if (muestra_insuficiente) {
    registros <- .metricas_omitidas_dbi(
      list(), columna, metricas, "no_disponible",
      "muestra_inestable:tablesample_system_tamano_insuficiente",
      metadatos = metadatos
    )
    return(list(
      fila = fila, sql = do.call(rbind, registros), literales = literales
    ))
  }

  sin_valores_validos_muestra <- FALSE

  if ("validos" %in% metricas) {
    validos <- conteos$validos
    registros <- registrar(registros, .CAMPOS_METRICA_DBI$validos, validos)
    if (validos$ok) {
      validos_observados <- .conteo_dbi(validos$valor)
      fila$n_validos <- validos_observados
      sin_valores_validos_muestra <- es_muestreado &&
        !is.na(validos_observados) && .numero_dbi(validos_observados) == 0
      if (!is.na(fila$n_validos) && !is.na(n_total_consulta)) {
        fila$n_faltantes <- n_total_consulta - validos_observados
        if (es_muestreado) {
          muestra_numero <- n_total_consulta
          fila$prop_faltantes <- if (is.finite(muestra_numero) &&
                                     muestra_numero > 0) {
            (muestra_numero - .numero_dbi(validos_observados)) / muestra_numero
          } else if (.numero_dbi(n_total) == 0) {
            NA_real_
          } else {
            NA_real_
          }
        } else {
          fila$prop_faltantes <- if (.numero_dbi(n_total_consulta) > 0) {
            .numero_dbi(fila$n_faltantes) / .numero_dbi(n_total_consulta)
          } else {
            NA_real_
          }
        }
      }
    }
  } else {
    registros <- omitir(registros, "validos", "no_solicitado", motivo_no_pedida)
  }

  if ("distintos" %in% metricas) {
    if (!isTRUE(estrategia_distintos$disponible)) {
      estado <- if (identical(estrategia_distintos$estado, "omitida")) {
        "omitida"
      } else {
        "no_disponible"
      }
      registros <- .metricas_omitidas_dbi(
        registros, columna, "distintos", estado,
        estrategia_distintos$motivo, metadatos = metadatos
      )
    } else {
      distintos <- if (identical(
        estrategia_distintos$estado, "estimado_catalogo"
      )) {
        estimacion <- estrategia_distintos$estimaciones[[columna]]
        if (is.null(estimacion) || !isTRUE(estimacion$disponible)) {
          list(
            ok = FALSE, valor = NULL,
            motivo = if (is.null(estimacion)) paste0(
              "No se obtuvo una estimaci\u00f3n de `pg_stats.n_distinct` para `",
              columna, "`."
            ) else estimacion$motivo,
            sql = NA_character_, estado = NULL,
            metadatos = list(fuente = "pg_stats.n_distinct")
          )
        } else {
          list(
            ok = TRUE, valor = estimacion$n_distintos,
            motivo = estimacion$motivo, sql = NA_character_,
            estado = "estimado_catalogo",
            metadatos = list(
              fuente = "pg_stats.n_distinct",
              n_distintos_catalogo = estimacion$n_distintos_catalogo,
              n_filas_catalogo = estimacion$n_filas,
              inherited_catalogo = estimacion$inherited
            )
          )
        }
      } else {
        conteos$distintos
      }
      if (is.null(distintos)) {
        distintos <- list(
          ok = FALSE, valor = NULL,
          motivo = "La estrategia resolvi\u00f3 una medici\u00f3n pero no se obtuvo su resultado.",
          sql = NA_character_
        )
      }
      motivo_cota <- NA_character_
      if (isTRUE(distintos$ok) && isTRUE(sin_valores_validos_muestra)) {
        distintos$ok <- FALSE
        distintos$estado <- NULL
        distintos$motivo <- "muestra_inestable:sin_valores_validos"
      }
      if (isTRUE(distintos$ok)) {
        distintos$metadatos <- .mezclar_metadatos_dbi(
          distintos$metadatos, list(
            metodo = estrategia_distintos$estrategia_resuelta,
            error_esperado = estrategia_distintos$error_esperado
          )
        )
        if (identical(estrategia_distintos$estado, "estimado_motor")) {
          distintos$estado <- "estimado_motor"
        } else if (identical(
          estrategia_distintos$estado, "estimado_catalogo"
        )) {
          distintos$estado <- "estimado_catalogo"
        }
        candidato <- .conteo_dbi(distintos$valor)
        guardian <- .guardian_distintos_dbi(distintos)
        motivo_cota <- if (!guardian$comprobable &&
                           is.null(distintos$metadatos$fuente)) {
          .motivo_cota_distintos_no_comprobable_dbi()
        } else {
          NA_character_
        }
        if (guardian$comprobable && !is.na(candidato) &&
            .numero_dbi(candidato) > guardian$valor) {
          distintos$ok <- FALSE
          distintos$estado <- NULL
          distintos$motivo <- paste0(
            "Se comprob\u00f3 en la consulta que el motor inform\u00f3 ", candidato,
            if (candidato == 1L) " valor distinto sobre " else " valores distintos sobre ", guardian$valor,
            if (guardian$valor == 1L) " v\u00e1lido, que es imposible; la m\u00e9trica no se publica." else
              " v\u00e1lidos, que es imposible; la m\u00e9trica no se publica."
          )
          motivo_cota <- NA_character_
        } else if (isTRUE(publica_distintos)) {
          fila$n_distintos <- candidato
          denominador <- if (guardian$comprobable) guardian$valor else {
            .numero_dbi(fila$n_validos)
          }
          if (!is.na(fila$n_distintos) && is.finite(denominador) &&
              denominador > 0) {
            fila$tasa_distintos <- .numero_dbi(fila$n_distintos) / denominador
          }
        }
      }
      if (isTRUE(publica_distintos)) {
        registros <- registrar(
          registros, .CAMPOS_METRICA_DBI$distintos, distintos,
          motivo_exito = motivo_cota
        )
      }
    }
  } else {
    registros <- omitir(registros, "distintos", "no_solicitado", motivo_no_pedida)
  }

  if (!("moda" %in% metricas)) {
    registros <- omitir(registros, "moda", "no_solicitado", motivo_no_pedida)
  } else if (!incluir_valores) {
    registros <- omitir(registros, "moda", "omitido_por_privacidad", motivo_privacidad)
  } else if (tipo_sin_agregados && !(
    "moda" %in% metricas &&
      .es_tipo_binario_muestra_dbi(tipo_operacion,
                                   .senas_conexion_dbi(conexion))
  )) {
    registros <- omitir(
      registros, "moda", "no_disponible", motivo_tipo_sin_agregados
    )
  } else if (!is.null(decisiones_costo) &&
             identical(decisiones_costo$moda, FALSE)) {
    registros <- omitir(
      registros, "moda", "omitido_por_costo",
      .motivo_decision_costo_dbi(decisiones_costo, "moda")
    )
  } else {
    columna_moda_sql <- .expresion_binaria_moda_dbi(
      conexion, columna_sql, tipo_operacion
    )
    valor_moda_sql <- .expresion_decimal_moda_dbi(
      conexion, columna_moda_sql, tipo_operacion,
      entero_doble = moda_entero_doble
    )
    orden_moda_sql <- .orden_moda_dbi(
      conexion, valor_moda_sql, tipo_operacion,
      orden_numerico_sql = if (isTRUE(moda_entero_doble)) {
        columna_moda_sql
      } else NULL
    )
    guardian_moda <- moda_guardian
    moda <- if (isTRUE(is.na(valor_moda_sql))) {
      list(
        ok = FALSE, datos = NULL,
        motivo = paste(
          "No se pudo pedir la moda exacta como texto en este motor;",
          "no se publica la moda del doble redondeado."
        ), sql = NA_character_
      )
    } else if (is.null(moda_precalculada)) {
      .moda_columna_dbi(
        conexion, tabla_sql, columna_moda_sql, dialecto, presupuesto,
        moda_guardian = guardian_moda, valor_sql = valor_moda_sql,
        orden_sql = orden_moda_sql
      )
    } else {
      moda_precalculada
    }
    if (moda$ok && nrow(moda$datos)) {
      # La moda no pasaba por la verificacion de nombre: un motor que plegara
      # el alias devolvia `NULL[[1L]]`, o sea NA, con estado `calculado`. Un
      # registro que declara exito sobre una metrica que no se obtuvo es peor
      # que un `no_disponible`.
      celda <- .valor_campo_dbi(moda$datos, "valor")
      frecuencia <- .valor_campo_dbi(moda$datos, "frecuencia")
      if (!celda$ok) {
        moda$ok <- FALSE
        moda$motivo <- celda$motivo
      } else if (!frecuencia$ok) {
        moda$ok <- FALSE
        moda$motivo <- frecuencia$motivo
      } else {
        valor_moda <- tryCatch(.texto_moda(celda$valor), error = function(e) e)
        if (inherits(valor_moda, "error")) {
          moda$ok <- FALSE
          moda$motivo <- .mensaje_motor(valor_moda)
        } else {
          candidato <- .conteo_dbi(frecuencia$valor)
          guardian <- .guardian_moda_dbi(moda)
          motivo_cota <- if (guardian$comprobable) {
            .motivo_cota_moda_comprobable_dbi()
          } else {
            .motivo_cota_moda_no_comprobable_dbi()
          }
          cota_invalida <- guardian$comprobable && !is.na(candidato) &&
            .numero_dbi(candidato) > guardian$valor
          if (cota_invalida) {
            moda$ok <- FALSE
            moda$motivo <- paste0(
              "Se comprob\u00f3 en la consulta que la frecuencia de la moda (",
              candidato, ") supera los ", guardian$valor,
              if (guardian$valor == 1L) " valor v\u00e1lido; la m\u00e9trica no se publica." else
                " valores v\u00e1lidos; la m\u00e9trica no se publica."
            )
            motivo_cota <- NA_character_
          } else {
            fila$moda <- valor_moda
            fila$frecuencia_moda <- candidato
            if (!is.na(candidato)) moda$motivo <- motivo_cota
          }
        }
      }
    } else if (moda$ok) {
      if (es_muestreado) {
        moda$ok <- FALSE
        moda$motivo <- "muestra_inestable:sin_valores_validos"
      } else {
        moda$motivo <- "La columna no contiene valores no nulos."
        moda$estado <- "sin_valores"
      }
      # `frecuencia_moda` quedaba en NA, y NA dice "no se midio". Aca si se
      # midio: el motor conto los valores no nulos y no hay ninguno. Es la
      # distincion que el paquete sostiene en todas partes -cero es medido y
      # ninguno-, y `perfilar()` ya devolvia cero para esta misma columna. Las
      # dos puertas daban numeros distintos sobre el mismo dato.
      #
      # Solo cuando la lectura fue sobre la tabla entera. Si se midio sobre una
      # muestra, que la muestra no traiga valores no prueba que la columna este
      # vacia, y ahi NA con su motivo es lo correcto.
      if (!es_muestreado) fila$frecuencia_moda <- 0
    }
    if (es_muestreado) {
      registros <- registrar(
        registros, "moda", moda, motivo_exito = moda$motivo
      )
      registros <- registrar(
        registros, "frecuencia_moda", moda
      )
    } else {
      registros <- registrar(
        registros, .CAMPOS_METRICA_DBI$moda, moda, motivo_exito = moda$motivo
      )
    }
  }

  metricas_numericas <- unlist(
    .CAMPOS_METRICA_DBI[.METRICAS_NUMERICAS_DBI], use.names = FALSE
  )
  pedidas_numericas <- intersect(metricas, .METRICAS_NUMERICAS_DBI)
  no_pedidas_numericas <- setdiff(.METRICAS_NUMERICAS_DBI, metricas)
  if (length(no_pedidas_numericas)) {
    registros <- omitir(
      registros, no_pedidas_numericas, "no_solicitado", motivo_no_pedida
    )
  }
  if (!length(pedidas_numericas)) {
    return(list(
      fila = fila, sql = do.call(rbind, registros), literales = literales
    ))
  }
  campos_pedidos <- unlist(
    .CAMPOS_METRICA_DBI[pedidas_numericas], use.names = FALSE
  )

  if (!.es_numerico_dbi(prototipo, tipo_declarado)) {
    registros <- c(registros, list(.registro_sql_dbi(
      columna, campos_pedidos, "no_aplica",
      paste0(
        "DBI expuso la columna como `", paste(class(prototipo), collapse = "/"),
        "`", if (length(tipo_declarado) == 1L && !is.na(tipo_declarado)) {
          paste0(" y el controlador inform\u00f3 el tipo del motor como `",
                 tipo_declarado, "`")
        } else "",
        "; no se aplicaron agregados cuantitativos."
      ),
      NA_character_, metadatos = metadatos
    )))
    return(list(
      fila = fila, sql = do.call(rbind, registros), literales = literales
    ))
  }

  # `n_validos` solo condiciona a las metricas que lo necesitan de verdad. Que
  # no se haya podido contar no es motivo para no calcular un minimo.
  sin_conteo <- is.na(fila$n_validos)
  if (!sin_conteo && .numero_dbi(fila$n_validos) == 0) {
    if (es_muestreado) {
      registros <- c(registros, list(.registro_sql_dbi(
        columna, campos_pedidos, "no_disponible",
        "muestra_inestable:sin_valores_validos", NA_character_,
        metadatos = metadatos
      )))
      return(list(
        fila = fila, sql = do.call(rbind, registros), literales = literales
      ))
    }
    registros <- c(registros, list(.registro_sql_dbi(
      columna, campos_pedidos, "sin_valores",
      "La columna no contiene valores no nulos.", NA_character_,
      metadatos = metadatos
    )))
    return(list(
      fila = fila, sql = do.call(rbind, registros), literales = literales
    ))
  }

  # Cuando el lote de basicos se cae porque el motor devolvio un valor que no se
  # puede leer como numero, lo que queda desmentido no es una metrica suelta: es
  # que la columna sea de la magnitud que TODAS estas metricas suponen. Si no se
  # pidieron basicos, la misma conclusion se prueba con la sonda de magnitud de
  # abajo. La mediana y el desvio miden esa magnitud en consultas aparte, y su
  # guardia solo mira si el resultado es un numero finito. En SQLite -tipado
  # dinamico: una columna declarada INTEGER puede contener texto- el motor no
  # rechaza, coacciona el texto a 0 y devuelve 0. La fila publicaba
  # `minimo = NA` con motivo "No se publica como calculada" al lado de
  # `mediana = 0` en estado `calculado`, indistinguible de una mediana real de
  # ceros, y el perfil de la muestra del MISMO objeto clasificaba la columna
  # como texto. Un cero fabricado por coaccion no es una medicion.
  magnitud_desmentida <- FALSE
  motivo_magnitud <- NA_character_
  magnitud_sondeada <- TRUE
  # La columna tiene un valor de al menos 2^53 que el doble no representa, y es
  # la unica causa por la que sus magnitudes no se publican. La mediana no
  # depende de todos los valores sino de sus centrales: se calcula igual y se
  # juzga por su valor (`.causa_mediana_inexacta_dbi()`). Vale si el motivo de
  # la magnitud sigue siendo el del ancho: otra causa leida despues lo pisa.
  motivo_ancho <- NA_character_
  magnitud_ancha <- function() {
    !is.na(motivo_ancho) && identical(motivo_magnitud, motivo_ancho)
  }
  # Ver `.centrales_por_debajo_dbi()`: se pregunta una vez, y solo si hace falta.
  centrales_verificadas <- NA
  centrales_por_debajo <- function() {
    if (is.na(centrales_verificadas)) {
      centrales_verificadas <<- !es_muestreado && .centrales_por_debajo_dbi(
        conexion, tabla_sql, columna_sql, alias, guardia_mediana()$n,
        presupuesto
      )
    }
    centrales_verificadas
  }
  # El motor respondio un infinito en una metrica de magnitud: ver
  # `.es_infinito_motor_dbi()`. Las magnitudes se vuelven a pedir sobre los
  # valores finitos despues de los basicos.
  infinitos_motor <- FALSE
  nan_motor <- FALSE
  n_validos_sondeado <- NA_real_
  max_abs_sondeado <- NA_real_
  minimo_sondeado <- NA_real_
  maximo_sondeado <- NA_real_
  max_abs_basicos <- NA_real_
  minimo_basicos <- NA_real_
  maximo_basicos <- NA_real_

  mediana_conservada <- is.null(decisiones_costo) ||
    isTRUE(decisiones_costo$mediana)
  necesita_sonda_magnitud <- .necesita_sonda_magnitud_dbi(
    pedidas_numericas, tipo_operacion, tipo_declarado, incluir_valores,
    mediana_conservada
  )

  if (necesita_sonda_magnitud) {
    # Bajo la muestra del motor, la del lote de agregados: la misma sentencia
    # que el desvio, la misma muestra. Una sonda propia sorteaba otra.
    sondeo <- if (es_muestreado && !is.null(agregados) &&
                  !is.null(agregados$magnitudes[[columna]])) {
      agregados$magnitudes[[columna]]
    } else {
      .sonda_magnitud_columna_dbi(
        conexion, tabla_sql, columna_sql, alias, presupuesto
      )
    }
    if (isTRUE(sondeo$ok)) {
      convertido <- .escalar_finito_dbi(sondeo$valor)
      sonda_nan <- any(vapply(
        list(sondeo$valor, sondeo$minimo, sondeo$maximo_abs,
             sondeo$minimo_abs),
        function(valor) is.numeric(valor) && length(valor) &&
          isTRUE(is.nan(valor[[1L]])), logical(1L)
      ))
      sonda_inf <- .es_infinito_motor_dbi(sondeo$valor) ||
        .es_infinito_motor_dbi(sondeo$minimo) ||
        .es_infinito_motor_dbi(sondeo$maximo_abs) ||
        .es_infinito_motor_dbi(sondeo$minimo_abs)
      if (sonda_nan) {
        sondeo$ok <- FALSE
        sondeo$motivo <- .motivo_nan_dbi("la sonda de magnitud")
        nan_motor <- TRUE
      }
      if (sonda_inf) {
        sondeo$ok <- FALSE
        if (!sonda_nan) sondeo$motivo <-
          .motivo_infinito_dbi("la sonda de magnitud")
        infinitos_motor <- TRUE
      }
      if (!sonda_nan && !sonda_inf &&
          .valor_perdido_en_conversion_dbi(sondeo$valor, convertido)) {
        valor <- if (isTRUE(incluir_valores)) paste0(
          " (\"", utils::head(as.character(sondeo$valor[[1L]]), 1L), "\")"
        ) else ""
        sondeo$ok <- FALSE
        sondeo$motivo <- paste0(
          .motivo_no_numero_dbi("la sonda de magnitud", valor),
          .texto_guardado_medido_dbi(
            conexion, tabla_sql, columna_sql, alias, presupuesto
          )
        )
      } else if (!sonda_nan && !sonda_inf &&
                 .entero_perdido_en_conversion_dbi(
        sondeo$valor, tipo_declarado
      )) {
        sondeo$ok <- FALSE
        sondeo$motivo <- .motivo_entero_doble_dbi(
          valor = sondeo$valor, conexion = conexion, tipo = tipo_declarado,
          mediana_por_valor = TRUE
        )
        motivo_ancho <- sondeo$motivo
      }
    }
    n_validos_sondeado <- .numero_dbi(sondeo$n_validos)
    max_abs_sondeado <- .escalar_finito_dbi(sondeo$maximo_abs)
    minimo_sondeado <- .escalar_finito_dbi(sondeo$minimo)
    maximo_sondeado <- .escalar_finito_dbi(sondeo$valor)
    magnitud_sondeada <- isTRUE(sondeo$ok)
    if (!magnitud_sondeada) motivo_magnitud <- sondeo$motivo
    registros <- .registrar_resultado_dbi(
      registros, columna, "sonda_magnitud", sondeo, metadatos = metadatos
    )
  }

  if ("basicos" %in% pedidas_numericas) {
    # `AVG(columna)` sin castear trunca en los motores con semantica entera.
    # Multiplicar por 1.0 promueve el tipo sin depender de un nombre de tipo
    # que cambia con el motor.
    basicos <- if (!is.null(agregados) &&
                   !is.null(agregados$basicos[[columna]])) {
      agregados$basicos[[columna]]
    } else {
      .basicos_columna_dbi(
        conexion, tabla_sql, columna_sql, alias, incluir_valores, presupuesto,
        float8_seguro = numeric_exact || (
          grepl("postgres|pqconnection", .senas_conexion_dbi(conexion),
                useBytes = TRUE) &&
            .tipo_declarado_float8_dbi(tipo_declarado, conexion) &&
            !.es_lectura_double_exacta_dbi(columna_sql)
        ),
        infinitos_como_numeric = infinitos_como_numeric,
        tipo = tipo_operacion
      )
    }
    calculados <- c("media", "n_ceros", "n_negativos")
    if (incluir_valores) calculados <- c("minimo", "maximo", calculados)
    media_escalada <- NULL
    if (basicos$ok && nrow(basicos$datos)) {
      aux_numero <- function(campo) {
        celda <- .valor_campo_dbi(basicos$datos, campo)
        if (!isTRUE(celda$ok)) return(NA_real_)
        crudo <- celda$valor
        if (is.numeric(crudo) && length(crudo) &&
            isTRUE(is.nan(crudo[[1L]]))) {
          nan_motor <<- TRUE
          return(NA_real_)
        }
        .escalar_finito_dbi(crudo)
      }
      minimo_basicos <- aux_numero("minimo")
      maximo_basicos <- aux_numero("maximo")
      max_abs_basicos <- aux_numero("maximo_abs")
      if (!is.finite(max_abs_basicos)) {
        extremos <- abs(c(minimo_basicos, maximo_basicos))
        extremos <- extremos[is.finite(extremos)]
        max_abs_basicos <- if (length(extremos)) max(extremos) else NA_real_
      }
      if (!is.finite(minimo_basicos) && isTRUE(incluir_valores)) {
        minimo_basicos <- aux_numero("minimo")
      }
      if (!is.finite(maximo_basicos) && isTRUE(incluir_valores)) {
        maximo_basicos <- aux_numero("maximo")
      }
      # `AVG` puede desbordar antes de que el resto de los basicos se lea
      # (MariaDB devuelve `Inf` en la misma fila). En ese caso no hay que
      # descartar minimo, maximo ni los conteos: los extremos ya llegaron y
      # permiten elegir el mismo repliegue, sin una sonda adicional.
      max_abs_previo <- max_abs_basicos
      if ((isTRUE(.es_mysql_dbi(.senas_conexion_dbi(conexion))) ||
           (motor_sqlserver && !is.finite(fila$media))) &&
          is.finite(max_abs_previo)) {
        escala_media <- .escala_desvio_dbi(max_abs_previo)
        if (!is.null(escala_media) && es_muestreado) {
          # El repliegue es otra sentencia, que bajo la muestra del motor
          # sortearia otra muestra (como el desvio escalado).
          media_escalada <- list(
            ok = FALSE, valor = NULL,
            motivo = .MOTIVO_MEDIA_ESCALADA_MUESTRA_DBI
          )
          basicos$datos[["media"]][[1L]] <- NA
        } else if (!is.null(escala_media)) {
          media_escalada <- .media_columna_escalada_dbi(
            conexion, tabla_sql, columna_sql, alias, escala_media, presupuesto
          )
          media_previa <- .escalar_finito_dbi(media_escalada$valor)
          if (isTRUE(media_escalada$ok) && is.finite(media_previa)) {
            basicos$datos[["media"]][[1L]] <- media_previa
          }
        }
      }
      # Se leen todos los campos antes de tocar la fila: media a medias, con la
      # auditoria diciendo `no_disponible`, seria un tercer estado que no
      # existe en el vocabulario del paquete.
      leidos <- list()
      ancho_en_basicos <- FALSE
      # El promedio desbordo y los basicos llegaron sin el: ver
      # `.basicos_columna_dbi()`. La media se registra aparte.
      media_ausente <- is.list(basicos$media_desbordada) && is.null(media_escalada)
      for (metrica in calculados) {
        nombre_motivo <- metrica
        if (identical(metrica, "media") && media_ausente) {
          # Sin el promedio, que la columna pase de 2^53 lo dicen sus extremos,
          # que esa consulta trae tambien con `incluir_valores = FALSE`: se
          # juzga el que lo muestra, con la misma regla. Si ninguno, la media
          # sigue sola, con su motivo.
          ancho_extremo <- NULL
          for (extremo in c("maximo", "minimo")) {
            celda_extremo <- .valor_campo_dbi(basicos$datos, extremo)
            if (isTRUE(celda_extremo$ok) && .entero_perdido_en_conversion_dbi(
              celda_extremo$valor, tipo_declarado
            )) {
              ancho_extremo <- extremo
              break
            }
          }
          if (is.null(ancho_extremo) || isTRUE(ancho_en_basicos)) next
          celda <- celda_extremo
          nombre_motivo <- ancho_extremo
        } else {
          celda <- .valor_campo_dbi(basicos$datos, metrica)
        }
        if (!celda$ok) {
          basicos$ok <- FALSE
          basicos$motivo <- celda$motivo
          leidos <- list()
          break
        }
        leidos[[metrica]] <- if (metrica %in% c("n_ceros", "n_negativos")) {
          .conteo_dbi(celda$valor)
        } else {
          convertido <- .escalar_finito_dbi(celda$valor)
          crudo_nan <- is.numeric(celda$valor[[1L]]) &&
            isTRUE(is.nan(celda$valor[[1L]]))
          # Sin `MIN` ni `MAX` -`incluir_valores = FALSE`-, un `Inf` y un `-Inf`
          # en la misma columna solo se ven en `AVG`: duckdb y PostgreSQL
          # responden `NaN` y SQLite, que no guarda `NaN`, `NULL`. Medido:
          # SQLite publicaba `media = NA` como `calculado` y
          # `n_negativos = 2` -contando el `-Inf`- donde los finitos dan 1, y
          # duckdb culpaba a un `NaN` que la columna no tenia. Antes de leerlo
          # como `NaN` o como nulo, se cuentan los infinitos.
          if (identical(metrica, "media") && !isTRUE(solo_finitos) &&
              (crudo_nan || is.na(convertido)) &&
              .hay_infinitos_dbi(
                conexion, tabla_sql, columna_sql, alias, presupuesto,
                como_numeric = infinitos_columna_como_numeric
              )) {
            basicos$ok <- FALSE
            basicos$motivo <- .motivo_infinito_dbi(metrica)
            magnitud_desmentida <- TRUE
            motivo_magnitud <- basicos$motivo
            infinitos_motor <- TRUE
            leidos <- list()
            break
          }
          if (crudo_nan) {
            # Un `NaN` del motor no dice que la columna sea de otra magnitud: es
            # numerica y guarda `NaN` como un valor -duckdb lo hace-, y el motor
            # lo incluye en `MAX`, `AVG` y en el orden de la mediana -la ubica al
            # final-, mientras R lo cuenta como ausente. El motivo generico de
            # abajo culpaba a la magnitud. Se retienen igual TODAS las metricas
            # de magnitud de la columna -medido: sin retenerla, la mediana del
            # motor salia 3 contra 2,5 en R-, pero con el motivo verdadero.
            basicos$ok <- FALSE
            basicos$motivo <- .motivo_nan_dbi(metrica)
            magnitud_desmentida <- TRUE
            motivo_magnitud <- basicos$motivo
            leidos <- list()
            break
          }
          # Un infinito no es un valor ilegible: es la columna que guarda
          # infinitos. Se retienen las magnitudes con ese motivo y, donde el
          # motor sabe escribir el infinito, se vuelven a pedir abajo sobre los
          # finitos.
          if (.es_infinito_motor_dbi(celda$valor)) {
            basicos$ok <- FALSE
            basicos$motivo <- .motivo_infinito_dbi(metrica)
            magnitud_desmentida <- TRUE
            motivo_magnitud <- basicos$motivo
            infinitos_motor <- TRUE
            leidos <- list()
            break
          }
          if (.valor_perdido_en_conversion_dbi(celda$valor, convertido)) {
            basicos$ok <- FALSE
            # El valor, solo si se pidieron valores y entre comillas, como la
            # sonda de magnitud: escrito entre parentesis era el MAXIMO de una
            # columna personal en claro -la prosa del paquete solo se revisa en
            # lo citado-. Medido.
            basicos$motivo <- paste0(
              .motivo_no_numero_dbi(
                paste0("`", metrica, "`"),
                if (isTRUE(incluir_valores)) paste0(
                  " (\"", utils::head(as.character(celda$valor[[1L]]), 1L), "\")"
                ) else ""
              ),
              .texto_guardado_medido_dbi(
                conexion, tabla_sql, columna_sql, alias, presupuesto
              )
            )
            magnitud_desmentida <- TRUE
            motivo_magnitud <- basicos$motivo
            leidos <- list()
            break
          }
          if (.entero_perdido_en_conversion_dbi(
            celda$valor, tipo_declarado
          )) {
            # La condicion de la columna se anota con la primera metrica que la
            # muestra, y se siguen leyendo las demas: si otra trae un valor que
            # no es numero -SQLite guarda texto en una columna INTEGER-, manda
            # esa causa, y la mediana ya no se puede juzgar por su valor.
            basicos$ok <- FALSE
            if (isTRUE(ancho_en_basicos)) next
            basicos$motivo <- .motivo_entero_doble_dbi(
              nombre_motivo, valor = celda$valor, conexion = conexion,
              tipo = tipo_declarado, mediana_por_valor = TRUE
            )
            # La condicion es de la COLUMNA, no de la metrica: si un valor de al
            # menos 2^53 llego como doble, TODAS las metricas de magnitud de esa
            # columna perdieron exactitud, no solo las cinco que este bucle
            # recorre. `mediana` y `desvio` se calculan en otras consultas y
            # salian `calculado` en la misma corrida donde `minimo`, `maximo`,
            # `media`, `n_ceros` y `n_negativos` salian `no_disponible`. Medido
            # con `UBIGINT`: los cuatro valores redondean al mismo doble y se
            # publicaba `mediana = 2^64` -que no esta en la columna- y
            # `desvio = 0` sobre una columna cuyo desvio real es 1,29, mientras
            # el motor contaba `n_distintos = 4`.
            #
            # Se usa el mismo mecanismo que la rama de arriba, y de paso queda
            # dicho lo que significa: `magnitud_desmentida` no es "la magnitud es
            # otra" sino "las metricas de magnitud de esta columna no se publican
            # como calculadas", y ahora tiene dos causas.
            #
            # Salvo la mediana, que no depende de toda la columna sino de sus
            # centrales: se calcula igual y la juzga su valor
            # (`.causa_mediana_inexacta_dbi()`). La de 2^64 del `UBIGINT` sigue
            # sin publicarse.
            magnitud_desmentida <- TRUE
            motivo_magnitud <- .motivo_entero_doble_dbi(
              valor = celda$valor, conexion = conexion, tipo = tipo_declarado,
              mediana_por_valor = TRUE
            )
            motivo_ancho <- motivo_magnitud
            ancho_en_basicos <- TRUE
            next
          }
          convertido
        }
      }
      if (isTRUE(ancho_en_basicos)) leidos <- list()
      # Un maximo menor que el minimo es imposible, y aparece de verdad: un
      # `BIGINT UNSIGNED` cerca del tope vuelve del driver como `integer64`
      # negativo, asi que el motor informa `min = 1` y `max = -1` sin mentir
      # -miente la representacion-. Se declara no disponible en vez de
      # publicarse, igual que se hace cuando hay mas distintos que validos.
      rango <- c(leidos[["minimo"]], leidos[["maximo"]])
      if (length(rango) == 2L && all(is.finite(rango)) &&
          rango[[2L]] < rango[[1L]]) {
        basicos$ok <- FALSE
        basicos$motivo <- paste0(
          "El motor inform\u00f3 un m\u00e1ximo (", rango[[2L]], ") menor que el m\u00ednimo (",
          rango[[1L]], "), que es imposible: probablemente el tipo no entra en ",
          "la representaci\u00f3n del controlador. Las m\u00e9tricas no se publican."
        )
        leidos <- list()
      }
      for (metrica in names(leidos)) fila[[metrica]] <- leidos[[metrica]]
      # Aunque `incluir_valores = FALSE` no publica minimo ni maximo, la
      # guarda de un decimal debe conocer la magnitud que el controlador
      # entrego como doble. La sonda anterior hace esa comprobacion; si falla,
      # no se deja que la media de `AVG` quede calculada con un motivo de
      # privacidad que no corresponde.
      if (isTRUE(magnitud_desmentida) &&
          .tipo_declarado_decimal_dbi(tipo_declarado)) {
        basicos$ok <- FALSE
        basicos$motivo <- motivo_magnitud
      }
      max_abs_basicos <- suppressWarnings(as.numeric(c(
        fila$minimo, fila$maximo
      )))
      max_abs_basicos <- abs(max_abs_basicos[is.finite(max_abs_basicos)])
      max_abs_basicos <- if (length(max_abs_basicos)) {
        max(max_abs_basicos)
      } else NA_real_
      motor_mysql <- .es_mysql_dbi(.senas_conexion_dbi(conexion))
      if (is.null(media_escalada) &&
          (isTRUE(motor_mysql) || (motor_sqlserver && !is.finite(fila$media))) &&
          is.finite(max_abs_basicos)) {
        escala_media <- .escala_desvio_dbi(
          max_abs_basicos, forzar = !is.finite(fila$media)
        )
        if (!is.null(escala_media) && es_muestreado) {
          media_escalada <- list(
            ok = FALSE, valor = NULL,
            motivo = .MOTIVO_MEDIA_ESCALADA_MUESTRA_DBI
          )
          fila$media <- NA_real_
        } else if (!is.null(escala_media)) {
          media_escalada <- .media_columna_escalada_dbi(
            conexion, tabla_sql, columna_sql, alias, escala_media, presupuesto
          )
          if (isTRUE(media_escalada$ok)) {
            fila$media <- .escalar_finito_dbi(media_escalada$valor)
          } else {
            fila$media <- NA_real_
          }
        }
      }
    } else if (basicos$ok) {
      basicos$ok <- FALSE
      basicos$motivo <- "La consulta de agregados no devolvi\u00f3 ninguna fila."
    }
    if (is.null(basicos$sql)) basicos$sql <- NA_character_
    calculados_basicos <- if (is.null(media_escalada)) {
      calculados
    } else {
      setdiff(calculados, "media")
    }
    media_desbordada <- if (is.null(media_escalada)) basicos$media_desbordada
    if (is.list(media_desbordada)) {
      calculados_basicos <- setdiff(calculados_basicos, "media")
      registros <- registrar(registros, "media", media_desbordada)
    }
    if (es_muestreado && isTRUE(basicos$ok)) {
      for (metrica in calculados_basicos) {
        resultado_metrica <- basicos
        registros <- registrar(registros, metrica, resultado_metrica)
      }
    } else {
      if (length(calculados_basicos)) {
        registros <- registrar(registros, calculados_basicos, basicos)
      }
    }
    if (!is.null(media_escalada)) {
      registros <- registrar(registros, "media", media_escalada)
    }
    if (!incluir_valores) {
      registros <- c(registros, list(.registro_sql_dbi(
        columna, c("minimo", "maximo"), "omitido_por_privacidad",
        motivo_privacidad, NA_character_, metadatos = metadatos
      )))
    }
  }

  # Una columna con infinitos: todas sus magnitudes -las de los basicos, la
  # mediana y el desvio- se piden de nuevo sobre los valores finitos, que es la
  # regla de `perfilar()` y de la via por bloques. Si el motor no sabe escribir
  # el infinito, o la lectura es una muestra del motor, quedan retenidas con
  # `.motivo_infinito_dbi()` -abajo, como cualquier magnitud desmentida-.
  if ((infinitos_motor || nan_motor) && !isTRUE(solo_finitos)) {
    finitas <- .magnitudes_finitas_dbi(
      conexion, tabla_sql, columna, columna_sql, prototipo, n_total, dialecto,
      pedidas_numericas, presupuesto, incluir_valores, tipo_declarado,
      motivo_ilegible, universo, decisiones_costo,
      como_numeric = infinitos_columna_como_numeric
    )
    if (!is.null(finitas)) {
      for (campo in names(finitas$fila)) fila[[campo]] <- finitas$fila[[campo]]
      previos <- do.call(rbind, registros)
      previos <- previos[
        !as.character(previos$metrica) %in% c(campos_pedidos, "sonda_magnitud"),
        , drop = FALSE
      ]
      return(list(
        fila = fila, sql = rbind(previos, finitas$sql),
        literales = c(literales, finitas$literales), cuenta_no_decide = TRUE
      ))
    }
  }

  if ("mediana" %in% pedidas_numericas) {
    if (!incluir_valores) {
      registros <- c(registros, list(.registro_sql_dbi(
        columna, "mediana", "omitido_por_privacidad", motivo_privacidad,
        NA_character_, metadatos = metadatos
      )))
    } else if ((!magnitud_sondeada || magnitud_desmentida) &&
               !(magnitud_ancha() && is.null(aproximacion_mediana))) {
      registros <- c(registros, list(.registro_sql_dbi(
        columna, "mediana", "no_disponible", motivo_magnitud, NA_character_,
        metadatos = metadatos
      )))
    } else if ((!magnitud_sondeada || magnitud_desmentida) &&
               identical(.causa_mediana_inexacta_dbi(
                 0, n = guardia_mediana()$n, columna_ancha = TRUE
               ), "par") && !centrales_por_debajo()) {
      # Con una cantidad par -o sin saber cual- la mediana de una columna que
      # pasa de 2^53 no se publica valga lo que valga: no se paga su consulta.
      registros <- c(registros, list(.registro_sql_dbi(
        columna, "mediana", "no_disponible",
        .motivo_mediana_inexacta_dbi(
          "par", tipo = tipo_declarado, n = guardia_mediana()$n
        ),
        NA_character_, metadatos = metadatos
      )))
    } else if (!is.null(decisiones_costo) &&
               identical(decisiones_costo$mediana, FALSE)) {
      registros <- omitir(
        registros, "mediana", "omitido_por_costo",
        .motivo_decision_costo_dbi(decisiones_costo, "mediana")
      )
    } else if (es_muestreado && !is.null(presupuesto) &&
               is.list(presupuesto$guardia_newid) &&
               !isTRUE(presupuesto$guardia_newid$aceptado)) {
      registros <- c(registros, list(.registro_sql_dbi(
        columna, "mediana", "no_disponible",
        presupuesto$guardia_newid$motivo, NA_character_,
        metadatos = .mezclar_metadatos_dbi(
          metadatos, list(metodo = NA_character_)
        )
      )))
    } else if (!is.null(mediana_consolidada) && !isTRUE(numeric_exact) &&
               !isTRUE(guardia_mediana()$requiere)) {
      mediana <- mediana_consolidada
      if (isTRUE(mediana$ok)) fila$mediana <- .escalar_finito_dbi(mediana$valor)
      registros <- registrar(registros, "mediana", mediana)
    } else if (!is.null(aproximacion_mediana)) {
      sql_mediana <- aproximacion_mediana$construir(
        .expresion_mediana_motor_dbi(conexion, columna_sql, tipo_declarado),
        tabla_sql, alias("mediana")
      )
      preparar_aviso_mediana()
      mediana <- ejecutar_mediana(sql_mediana)
      finalizar_mediana(mediana)
      if (is.null(mediana$sql)) mediana$sql <- sql_mediana
      if (isTRUE(mediana$ok)) {
        mediana$estado <- "estimado"
        mediana$metadatos <- list(
          metodo = aproximacion_mediana$nombre,
          error_esperado = aproximacion_mediana$error_esperado
        )
        fila$mediana <- .escalar_finito_dbi(mediana$valor)
      }
      registros <- registrar(registros, "mediana", mediana)
    } else if (!is.null(mediana_cte_ventana)) {
      mediana <- mediana_por_cte_ventana(mediana_cte_ventana)
      if (isTRUE(mediana$ok)) fila$mediana <- mediana$valor
      registros <- registrar(registros, "mediana", mediana)
    } else if (!is.null(mediana_escalar)) {
      sql_mediana <- mediana_escalar$construir(
        columna_sql, tabla_sql, alias("mediana"),
        materializar = es_muestreado,
        doble_exacto = infinitos_columna_como_numeric
      )
      preparar_aviso_mediana()
      mediana <- ejecutar_mediana(sql_mediana)
      finalizar_mediana(mediana)
      if (is.null(mediana$sql)) mediana$sql <- sql_mediana
      mediana$metadatos <- list(metodo = mediana_escalar$nombre)
      if (isTRUE(mediana$ok)) {
        valor <- .escalar_finito_dbi(mediana$valor)
        if (is.na(valor)) {
          mediana$estado <- "sin_valores"
          mediana$motivo <- "La columna no contiene valores no nulos."
        } else {
          fila$mediana <- valor
        }
      }
      registros <- registrar(registros, "mediana", mediana)
    } else if (es_muestreado) {
      # La preparacion solo prueba la CTE cuando no hay mediana consolidada ni
      # escalar. Una columna que no puede usar la consolidada -un `float8` de
      # PostgreSQL, que la deja por `numeric_exact`, o una con extremos, que la
      # deja por `guardia_mediana()`- llegaba aca sin forma de una sola
      # sentencia y publicaba `no_disponible` con el motivo de una prueba que
      # no habia corrido. La muestra no puede caer a dos consultas, que leerian
      # dos muestras distintas: la CTE se prueba ahora, una vez por corrida
      # (la resolucion queda en el presupuesto).
      cte <- if (length(mediana_cte_ventana_motivo) == 1L &&
                 !is.na(mediana_cte_ventana_motivo)) {
        list(disponible = FALSE, motivo = mediana_cte_ventana_motivo)
      } else {
        .sondar_mediana_cte_ventana_dbi(conexion, presupuesto)
      }
      if (isTRUE(cte$disponible)) {
        candidato <- cte$candidato
        candidato$nombre <- .nombre_mediana_cte_muestra_dbi(muestreo)
        mediana <- mediana_por_cte_ventana(candidato)
        if (isTRUE(mediana$ok)) fila$mediana <- mediana$valor
        registros <- registrar(registros, "mediana", mediana)
      } else {
        motivo <- if (length(cte$motivo) == 1L && !is.na(cte$motivo)) {
          cte$motivo
        } else {
          "capacidad_no_aceptada:sonda_mediana_cte_ventana"
        }
        registros <- c(registros, list(.registro_sql_dbi(
          columna, "mediana", "no_disponible", motivo, NA_character_,
          metadatos = metadatos
        )))
      }
    } else if (conteo_mediana_pendiente() ||
               (es_muestreado && !exists("validos_observados"))) {
      registros <- c(registros, list(.registro_sql_dbi(
        columna, "mediana", "no_disponible",
        paste(
          "La mediana exacta necesita la cantidad de valores no nulos,",
          "que no se pudo conocer."
        ),
        NA_character_, metadatos = metadatos
      )))
    } else if (isTRUE(conteo_mediana_propio) &&
               isTRUE(n_validos_sondeado == 0)) {
      registros <- c(registros, list(.registro_sql_dbi(
        columna, "mediana", "sin_valores",
        "La columna no contiene valores no nulos.", NA_character_,
        metadatos = metadatos
      )))
    } else {
      n_validos_numero <- if (es_muestreado) {
        .numero_dbi(validos_observados)
      } else if (is.finite(n_validos_sondeado)) {
        n_validos_sondeado
      } else {
        .numero_dbi(fila$n_validos)
      }
      limite <- if (n_validos_numero %% 2 == 0) 2 else 1
      desplazamiento <- floor((n_validos_numero - 1) / 2)
      interna <- paste0(
        "SELECT ", columna_sql, " AS ", alias("valor"), " FROM ", tabla_sql,
        " WHERE ", columna_sql, " IS NOT NULL ORDER BY ", columna_sql
      )
      acotada <- dialecto$limitar(interna, limite, desplazamiento)
      # Un dialecto sin salto -`portable`, que no supone ninguna clausula, o
      # `rownum`- no puede escribir la via de dos consultas. La CTE de ventanas
      # no necesita salto ni conteo: es SQL estandar (`WITH`, `ROW_NUMBER()`),
      # no garantizado, y por eso se prueba antes de usarla, una vez por corrida.
      cte_sin_salto <- if (is.null(acotada)) {
        .sondar_mediana_cte_ventana_dbi(conexion, presupuesto)
      }
      if (is.null(acotada) && isTRUE(cte_sin_salto$disponible)) {
        candidato <- cte_sin_salto$candidato
        candidato$nombre <- .nombre_mediana_cte_muestra_dbi(NULL)
        mediana <- mediana_por_cte_ventana(candidato)
        sin_valores <- identical(mediana$estado, "sin_valores")
        if (isTRUE(mediana$ok) && !sin_valores) fila$mediana <- mediana$valor
        registros <- registrar(
          registros, "mediana", mediana,
          motivo_exito = if (sin_valores) mediana$motivo else NA_character_
        )
      } else if (is.null(acotada)) {
        bloqueada <- !is.null(presupuesto) &&
          length(cte_sin_salto$motivo) == 1L &&
          identical(cte_sin_salto$motivo, .motivo_presupuesto_dbi(presupuesto))
        registros <- c(registros, list(.registro_sql_dbi(
          columna, "mediana", "no_disponible",
          if (bloqueada) cte_sin_salto$motivo else paste0(
            "El dialecto `", dialecto$nombre, "` no expresa un salto de filas ",
            "(`LIMIT ... OFFSET` ni `OFFSET ... FETCH`) y el motor no acept\u00f3 ",
            "la CTE de ventanas, que no lo necesita; la mediana exacta exigir\u00eda ",
            "traer ", .entero_sql_dbi(desplazamiento + limite),
            if (desplazamiento + limite == 1L) " fila a memoria." else " filas a memoria."
          ),
          NA_character_, metadatos = metadatos
        )))
      } else {
        fuente_mediana <- paste0(
          "(", acotada, ")", dialecto$alias_tabla("lupa_mediana_valores")
        )
        max_abs_mediana <- suppressWarnings(max(abs(as.numeric(c(
          fila$minimo, fila$maximo, minimo_basicos, maximo_basicos
        ))), na.rm = TRUE))
        escala_mediana <- if (
          .es_mysql_dbi(.senas_conexion_dbi(conexion)) &&
          is.finite(max_abs_mediana)
        ) .escala_desvio_dbi(max_abs_mediana) else NULL
        sql_mediana <- if (!is.null(escala_mediana)) {
          escala_sql <- .literal_escala_desvio_dbi(escala_mediana)
          paste0(
            "SELECT AVG(", alias("valor"), " * 1e0 / NULLIF(", escala_sql,
            ", 0)) * ", escala_sql, " AS ", alias("mediana"),
            " FROM ", fuente_mediana
          )
        } else if (isTRUE(numeric_exact) &&
                           grepl("postgres|pqconnection",
                                 .senas_conexion_dbi(conexion),
                                 useBytes = TRUE)) {
          # La lectura reconstruida ya es NUMERIC exacto. Devolver el promedio
          # como NUMERIC evita que `extra_float_digits = 0` redondee el doble al
          # viajar desde PostgreSQL 9.3, y la suma numerica tampoco desborda
          # cuando los dos valores centrales son DBL_MAX.
          valor <- alias("valor")
          paste0(
            "SELECT ", .promedio_centrales_float8_exacto_sql_dbi(valor),
            " AS ", alias("mediana"),
            " FROM (SELECT ", valor, " FROM ", fuente_mediana, ")",
            dialecto$alias_tabla("lupa_mediana")
          )
        } else {
          paste0(
            "SELECT ", .promedio_mediana_sql_dbi(
              conexion, alias("valor"), tipo_declarado
            ),
            " AS ", alias("mediana"),
            " FROM ", fuente_mediana
          )
        }
        preparar_aviso_mediana()
        mediana <- ejecutar_mediana(sql_mediana)
        finalizar_mediana(mediana)
        if (mediana$ok) fila$mediana <- .escalar_finito_dbi(mediana$valor)
        if (is.null(mediana$sql)) mediana$sql <- sql_mediana
        mediana$metadatos <- list(metodo = "dos_consultas")
        registros <- registrar(registros, "mediana", mediana)
      }
    }
  }

  n_validos_desvio <- .numero_dbi(fila$n_validos)
  if ((!length(n_validos_desvio) || is.na(n_validos_desvio)) &&
      is.finite(n_validos_sondeado)) {
    n_validos_desvio <- n_validos_sondeado
  }
  puede_replegar_desvio_infinito <- infinitos_motor &&
    (.es_mysql_dbi(.senas_conexion_dbi(conexion)) || grepl(
      "sql server|microsoft sql|sqlserver|mssql",
      .senas_conexion_dbi(conexion), perl = TRUE, useBytes = TRUE
    )) && length(n_validos_desvio) == 1L &&
    is.finite(n_validos_desvio) && n_validos_desvio >= 2

  if ("desvio" %in% pedidas_numericas) {
    if ((!magnitud_sondeada || magnitud_desmentida) &&
        !puede_replegar_desvio_infinito) {
      registros <- c(registros, list(.registro_sql_dbi(
        columna, "desvio", "no_disponible", motivo_magnitud, NA_character_,
        metadatos = metadatos
      )))
    } else if (length(n_validos_desvio) == 1L &&
               is.finite(n_validos_desvio) && n_validos_desvio < 2) {
      registros <- c(registros, list(.registro_sql_dbi(
        columna, "desvio", "no_aplica",
        "El desv\u00edo muestral requiere al menos dos valores no nulos.",
        NA_character_, metadatos = metadatos
      )))
    } else {
      .sondar_forma_desvio(conexion, presupuesto, alias)
      numeric_desvio <- isTRUE(numeric_exact) && any(
        abs(suppressWarnings(as.numeric(c(
          fila$minimo, fila$maximo, fila$media
        )))) > 1e150,
        na.rm = TRUE
      )
      senas_desvio <- .senas_conexion_dbi(conexion)
      mysql_desvio <- .es_mysql_dbi(senas_desvio)
      extremos_escala <- suppressWarnings(as.numeric(c(
        fila$minimo, fila$maximo, minimo_basicos, maximo_basicos,
        minimo_sondeado, maximo_sondeado
      )))
      extremos_escala <- extremos_escala[is.finite(extremos_escala)]
      max_abs <- suppressWarnings(max(c(
        abs(extremos_escala), max_abs_basicos, max_abs_sondeado
      ), na.rm = TRUE))
      if (!is.finite(max_abs)) max_abs <- NA_real_
      minimo_escala <- if (length(extremos_escala)) {
        min(extremos_escala)
      } else NA_real_
      maximo_escala <- if (length(extremos_escala)) {
        max(extremos_escala)
      } else NA_real_
      rango_desvio <- if (is.finite(minimo_escala) &&
                          is.finite(maximo_escala)) {
        maximo_escala - minimo_escala
      } else NA_real_
      escala_desvio <- .escala_desvio_dbi(
        max_abs, rango = rango_desvio
      )
      magnitud_extrema <- !is.null(escala_desvio)
      tipo_flotante <- grepl(
        "(^|[^a-z])(float|real|double)([^a-z]|$)|^(6|7|8)$",
        paste(
          .minusculas_ascii(as.character(tipo_declarado)),
          .minusculas_ascii(as.character(tipo_motor)), sep = " "
        ), perl = TRUE
      )
      # Si los agregados basicos de SQL Server no pudieron representar la
      # magnitud de un FLOAT, tambien se fuerza el repliegue; no hace falta
      # esperar a que una STDEV de una pasada fabrique ruido.
      # Sin `basicos` no hay extremos ni media que hayan fallado: bajo la
      # muestra del motor la magnitud es la del lote, y forzar el repliegue
      # porque faltaban sorteaba otra muestra.
      extremos_centro <- if (es_muestreado &&
                             !"basicos" %in% pedidas_numericas) {
        c(minimo_sondeado, maximo_sondeado)
      } else {
        c(fila$minimo, fila$maximo, fila$media)
      }
      centro_extremo_fallido <- grepl(
        "sql server|microsoft sql|sqlserver|mssql", senas_desvio,
        perl = TRUE, useBytes = TRUE
      ) && tipo_flotante && any(!is.finite(suppressWarnings(as.numeric(
        extremos_centro
      ))))
      rango_extremo <- suppressWarnings(as.numeric(fila$maximo)) -
        suppressWarnings(as.numeric(fila$minimo))
      riesgo_extremo_pg <- grepl(
        "postgres|pqconnection", senas_desvio, useBytes = TRUE
      ) && magnitud_extrema && (
        max_abs < 1e-150 ||
        !is.finite(suppressWarnings(as.numeric(fila$media))) ||
        (max_abs > 1e150 && is.finite(rango_extremo) &&
         rango_extremo > 0 &&
         abs(suppressWarnings(as.numeric(fila$media))) /
           rango_extremo > .RAZON_CANCELACION_DESVIO_DBI) ||
        (max_abs > 1e150 && isTRUE(rango_extremo == 0) &&
         .numero_dbi(fila$n_distintos) > 1)
      )
      # MySQL y MariaDB leen el centro como DECIMAL cuando queda en la forma
      # normal. Por encima de 65 cifras significativas esa forma ya no puede
      # conservarlo, aunque el valor siga dentro del rango del doble.
      centro_mysql_decimal <- isTRUE(mysql_desvio) &&
        length(max_abs) == 1L && is.finite(max_abs) && max_abs > 1e65
      forzar_escalado <- (
        (!grepl("postgres|pqconnection", senas_desvio,
                useBytes = TRUE) && magnitud_extrema) ||
        riesgo_extremo_pg || centro_extremo_fallido ||
        centro_mysql_decimal || puede_replegar_desvio_infinito
      )
      # Por columna, el desvio se pide centrado en la media ya calculada: no
      # cuesta una consulta mas y evita la cancelacion de una pasada. Ver
      # `.formas_desvio_dbi()`.
      consolidado <- !is.null(agregados) &&
        !is.null(agregados$desvio[[columna]]) && !forzar_escalado
      # El repliegue escalado es otra sentencia: bajo la muestra del motor
      # sortearia otra muestra -y su escala, otra mas-, y publicaba el desvio
      # de filas que la corrida no publica, o `no_disponible` si le tocaba una
      # vacia. Sin el no hay desvio de esta magnitud que publicar.
      repliegue_otra_muestra <- es_muestreado && forzar_escalado
      desvio <- if (repliegue_otra_muestra) {
        list(
          ok = FALSE, valor = NULL,
          motivo = .MOTIVO_DESVIO_ESCALADO_MUESTRA_DBI
        )
      } else if (consolidado) {
        agregados$desvio[[columna]]
      } else {
        .desvio_columna_dbi(
          conexion, tabla_sql, columna_sql, alias, presupuesto$forma_desvio,
          presupuesto, centro = fila$media, tipo = tipo_declarado,
          numeric_exact = numeric_desvio,
          infinitos_como_numeric = infinitos_como_numeric,
          forzar_escalado = forzar_escalado,
          escala = escala_desvio
        )
      }
      motivo_desvio <- NA_character_
      # El de la consulta consolidada no se pudo centrar: la media sale de la
      # misma sentencia. Si corre riesgo de cancelacion, se vuelve a pedir
      # centrado en ella. Solo sobre la tabla completa: sobre una muestra del
      # motor, otra consulta veria otras filas. Un decimal cuyo tipo admite las
      # sumas exactas no: su desvio sale de ellas
      # (`.decimales_exactos_tabla_dbi()`), y esa consulta, que el plan no
      # cuenta, se llevaba el lugar de la exacta.
      if (consolidado && isTRUE(desvio$ok) && !es_muestreado &&
          !.sumas_exactas_posibles_dbi(senas_desvio, tipo_declarado) &&
          .riesgo_cancelacion_desvio_dbi(
            fila$media, .escalar_finito_dbi(desvio$valor), fila$minimo,
            fila$maximo, fila$n_distintos
          )) {
        centrado <- .desvio_columna_dbi(
          conexion, tabla_sql, columna_sql, alias, presupuesto$forma_desvio,
          presupuesto, centro = fila$media, tipo = tipo_declarado,
          numeric_exact = numeric_desvio,
          infinitos_como_numeric = infinitos_como_numeric
        )
        if (isTRUE(centrado$ok)) {
          motivo_desvio <- if (isTRUE(.escalar_finito_dbi(desvio$valor) == 0)) {
            paste(
              "El desv\u00edo se recalcul\u00f3 en el motor sobre los valores centrados en",
              "la media: la consulta compartida respondi\u00f3 0 sobre una columna",
              "con valores distintos, que pierde las cifras en una sola pasada o",
              "al pasar a doble valores que difieren por debajo de su",
              "resoluci\u00f3n. Centrar no cambia el desv\u00edo."
            )
          } else {
            paste(
              "El desv\u00edo se recalcul\u00f3 en el motor sobre los valores centrados en",
              "la media: la media es mucho mayor que el desv\u00edo, y el desv\u00edo de una",
              "sola pasada pierde cifras. Centrar no cambia el desv\u00edo."
            )
          }
          desvio <- centrado
        }
      }
      valor_desvio <- suppressWarnings(as.numeric(desvio$valor %||% NA_real_))
      if (isTRUE(desvio$ok) &&
          (length(valor_desvio) != 1L || !is.finite(valor_desvio))) {
        desvio$ok <- FALSE
        desvio$motivo <- paste(
          "El motor no devolvi\u00f3 un desv\u00edo finito; no se publica como calculado."
        )
      }
      minimo_desvio <- if (length(fila$minimo) == 1L &&
                           is.finite(suppressWarnings(as.numeric(fila$minimo)))) {
        fila$minimo
      } else minimo_sondeado
      maximo_desvio <- if (length(fila$maximo) == 1L &&
                           is.finite(suppressWarnings(as.numeric(fila$maximo)))) {
        fila$maximo
      } else maximo_sondeado
      hay_variacion_desvio <- .hay_variacion_dbi(
        minimo_desvio, maximo_desvio, fila$n_distintos
      )
      # Volver a pedirlo escalado es otra sentencia. Los motores que ya
      # escalaban no la mandaban: un 0 sobre valores distintos quedaba negado
      # por la red de abajo, y asi sigue, con las mismas sentencias.
      if (isTRUE(desvio$ok) && isTRUE(valor_desvio == 0) &&
          isTRUE(hay_variacion_desvio) && !isTRUE(forzar_escalado) &&
          !.motor_escalable_desvio_dbi(senas_desvio)) {
        replegado <- .desvio_columna_dbi(
          conexion, tabla_sql, columna_sql, alias, presupuesto$forma_desvio,
          presupuesto, centro = fila$media, tipo = tipo_declarado,
          numeric_exact = numeric_desvio,
          infinitos_como_numeric = infinitos_como_numeric,
          forzar_escalado = TRUE,
          escala = escala_desvio
        )
        valor_replegado <- suppressWarnings(
          as.numeric(replegado$valor %||% NA_real_)
        )
        if (isTRUE(replegado$ok) && length(valor_replegado) == 1L &&
            is.finite(valor_replegado)) {
          desvio <- replegado
          valor_desvio <- valor_replegado
        }
      }
      if (isTRUE(desvio$ok)) fila$desvio <- valor_desvio
      # La red: un desvio 0 sobre una columna con dos valores distintos es
      # imposible, y es la cifra que publicaba una pasada en SQL Server sobre
      # marcas de tiempo en milisegundos. No se publica.
      if (isTRUE(desvio$ok) && isTRUE(valor_desvio == 0) &&
          isTRUE(hay_variacion_desvio)) {
        fila$desvio <- NA_real_
        registros <- c(registros, list(.registro_sql_dbi(
          columna, "desvio", "no_disponible",
          paste(
            "El motor respondi\u00f3 desv\u00edo 0 sobre una columna con al menos dos",
            "valores distintos, que es imposible: el c\u00e1lculo perdi\u00f3 las cifras",
            "-en una sola pasada, o al pasar a doble valores que difieren por",
            "debajo de su resoluci\u00f3n-. No se publica como calculado."
          ),
          if (is.null(desvio$sql)) NA_character_ else desvio$sql,
          metadatos = metadatos
        )))
      } else {
        registros <- registrar(registros, "desvio", desvio, motivo_desvio)
      }
    }
  }

  if (es_muestreado && .tipo_decimal_o_moneda_dbi(tipo_declarado) &&
      .centra_muestra_en_doble_dbi(conexion) &&
      .desvio_mal_condicionado_dbi(fila$desvio, c(
        fila$minimo, fila$maximo, minimo_basicos, maximo_basicos
      ), tipo = tipo_declarado)) {
    for (i in seq_along(registros)) {
      r <- registros[[i]]
      tapar <- r$metrica == "desvio" &
        r$estado %in% c("calculado", "estimado")
      if (any(tapar)) {
        r$estado[tapar] <- "no_disponible"
        r$motivo[tapar] <- .MOTIVO_DESVIO_DECIMAL_DOBLE_DBI
        registros[[i]] <- r
      }
    }
    fila$desvio <- NA_real_
  }

  # La guarda del entero ancho lee el minimo y el maximo de la consulta de
  # basicos. Si esa consulta no llego -en DuckDB, `HUGEINT * 1.0` desborda
  # cerca del tope del tipo-, la mediana sale de otra consulta y se publicaba
  # `calculado` con un doble que no distingue los valores. La mediana misma es
  # la evidencia de la magnitud. No se cambio la media a `CAST(x AS DOUBLE)`
  # para esquivar el desborde: sumar en doble erraba en 1.723 unidades la media
  # de un BIGINT de 200.000 valores cerca de 2^52, que `* 1.0` da exacta.
  #
  # La misma regla decide la mediana de toda columna entera o decimal: ver
  # `.causa_mediana_inexacta_dbi()`.
  mediana_publicada <- suppressWarnings(as.numeric(fila$mediana))
  entera_o_decimal <- .tipo_declarado_entero_ancho_dbi(tipo_declarado) ||
    .tipo_declarado_decimal_dbi(tipo_declarado) ||
    inherits(prototipo, "integer64")
  if (entera_o_decimal && length(mediana_publicada) == 1L &&
      is.finite(mediana_publicada)) {
    desborde_basicos <- exists("basicos", inherits = FALSE) &&
      is.list(basicos) && !isTRUE(basicos$ok) &&
      .es_desborde_motor_dbi(basicos$motivo)
    metodos_mediana <- unlist(lapply(registros, function(r) {
      if (!"metodo" %in% names(r)) return(character())
      as.character(r$metodo[r$metrica == "mediana"])
    }), use.names = FALSE)
    interpola_restando <- grepl(
      "postgres|pqconnection", .senas_conexion_dbi(conexion), useBytes = TRUE
    ) && any(grepl("^PERCENTILE_CONT", metodos_mediana, useBytes = TRUE))
    causa_con <- function(columna_ancha, interpola) {
      .causa_mediana_inexacta_dbi(
        mediana_publicada, n = guardia_mediana()$n,
        columna_ancha = columna_ancha,
        extremos = c(
          minimo_basicos, maximo_basicos, minimo_sondeado, maximo_sondeado
        ),
        interpola_restando = interpola
      )
    }
    causa <- causa_con(magnitud_ancha() || desborde_basicos, interpola_restando)
    # Con las dos centrales en (-2^52, 2^52) el promedio es exacto, se forme
    # como se forme: ni la columna ni la interpolacion importan.
    if (identical(causa, "par") && centrales_por_debajo()) {
      causa <- causa_con(FALSE, FALSE)
    }
    if (!is.na(causa)) {
      # Lo que la columna ya declaraba se conserva palabra por palabra cuando
      # alcanza: una mediana de al menos 2^53 en una columna que pasa de 2^53.
      motivo_mediana_ancha <- if (identical(causa, "valor") &&
                                  magnitud_ancha()) {
        motivo_magnitud
      } else if (identical(causa, "valor")) {
        .motivo_entero_doble_dbi(
          "mediana", valor = fila$mediana, conexion = conexion,
          tipo = tipo_declarado, mediana_por_valor = TRUE
        )
      } else {
        .motivo_mediana_inexacta_dbi(
          causa, tipo = tipo_declarado, n = guardia_mediana()$n
        )
      }
      for (i in seq_along(registros)) {
        r <- registros[[i]]
        tapar <- r$metrica == "mediana" &
          r$estado %in% c("calculado", "estimado")
        if (any(tapar)) {
          r$estado[tapar] <- "no_disponible"
          r$motivo[tapar] <- motivo_mediana_ancha
          registros[[i]] <- r
        }
      }
      fila$mediana <- NA_real_
    }
  }

  sobrantes <- setdiff(
    metricas_numericas,
    unlist(lapply(registros, function(x) x$metrica), use.names = FALSE)
  )
  sobrantes <- intersect(sobrantes, campos_pedidos)
  if (length(sobrantes)) {
    registros <- c(registros, list(.registro_sql_dbi(
      columna, sobrantes, "no_disponible",
      "La m\u00e9trica no se pudo calcular en esta corrida.", NA_character_,
      metadatos = metadatos
    )))
  }

  # La cuenta de los no nulos del lote solo dice cuantos valores usa la metrica
  # si la magnitud de la columna quedo establecida y es finita. Con `NaN` o
  # infinitos las magnitudes se decidieron sobre los finitos (o se retuvieron
  # bajo la muestra); si la sonda fallo o la magnitud quedo desmentida, ya estan
  # declaradas con su motivo. En esos casos la cuenta no decide
  # (`.valores_ausentes_por_cuenta_dbi()`): en PostgreSQL 9.3 un `real` con
  # `Infinity` hace fallar la sonda, y `COUNT(x) = 1` publicaba `no_aplica`.
  list(fila = fila, sql = do.call(rbind, registros), literales = literales,
       cuenta_no_decide = isTRUE(infinitos_motor) || isTRUE(nan_motor) ||
         !isTRUE(magnitud_sondeada) || isTRUE(magnitud_desmentida))
}

.columnas_dbi_vacias <- function() {
  data.frame(
    columna = character(), n = numeric(), n_validos = numeric(),
    n_faltantes = numeric(), prop_faltantes = numeric(),
    n_distintos = numeric(), tasa_distintos = numeric(),
    moda = character(), frecuencia_moda = numeric(), minimo = numeric(),
    maximo = numeric(), media = numeric(), mediana = numeric(),
    desvio = numeric(), n_ceros = numeric(), n_negativos = numeric(),
    stringsAsFactors = FALSE
  )
}

.incorporar_distintos_estructurales_dbi <- function(agregados, fuentes,
                                                     n_total, universo) {
  if (is.null(fuentes) || !length(fuentes)) return(agregados)
  for (columna in names(fuentes)) {
    fuente <- fuentes[[columna]]
    if (is.null(fuente) || !isTRUE(fuente$exacta) ||
        !is.finite(fuente$proporcion_distintos) ||
        fuente$proporcion_distintos != 1 || is.na(n_total) ||
        identical(universo, "muestra_motor")) {
      next
    }
    resultado <- list(
      ok = TRUE, valor = n_total, motivo = NA_character_, sql = NA_character_,
      estado = "garantizado",
      metadatos = list(fuente = fuente$nombre)
    )
    base <- agregados$conteos[[columna]]
    if (!is.null(base) && !is.null(base$distintos)) next
    if (is.null(base)) base <- list(consolidada = TRUE)
    agregados$conteos[[columna]] <- utils::modifyList(
      base, list(distintos = resultado)
    )
  }
  agregados
}

.resumen_tabla_dbi <- function(conexion, tabla, tabla_sql, campos, prototipo,
                               n_total, sql_conteo, info_conexion,
                               dialecto = NULL, metricas = .METRICAS_DBI,
                               metricas_ejecucion = metricas,
                               presupuesto = NULL, incluir_valores = TRUE,
                               tipos_declarados = NULL,
                               motivos_ilegibles = NULL,
                                universo = "tabla_completa",
                                estrategia_mediana = "exacta",
                                # `tabla_sql` no se usa en el cuerpo: esta para
                                # ser el valor por omision de la linea de abajo.
                                # Es una omision razonable -medir sobre la misma
                                # tabla- aunque el unico llamador siempre la
                                # pise con la tabla muestreada.
                                tabla_metricas_sql = tabla_sql,
                                muestreo = NULL, aproximaciones = list(),
                                tamano_muestra = NA_real_,
                                fraccion_muestra = NA_real_,
                                campos_consolidados = NULL,
                                campos_sql_consolidados = NULL,
                                es_numerico_consolidados = NULL,
                                tamano_lote_planos = .TAMANO_LOTE_PLANOS_DBI,
                                tamano_lote_distintos = .TAMANO_LOTE_DISTINTOS_DBI,
                                conteo = NULL,
                                tabla_total_sql = tabla_sql,
                                moda_guardian = NULL,
                                mediana_consolidada = NULL,
                                mediana_escalar = NULL,
                                mediana_cte_ventana = NULL,
                                mediana_cte_ventana_motivo = NA_character_,
                                fuentes_cardinalidad_costo = NULL,
                                estrategia_distintos = list(
                                  publica = TRUE, disponible = TRUE,
                                  estrategia_solicitada = "exacta",
                                  estrategia_resuelta = "COUNT(DISTINCT)",
                                  estado = "calculado",
                                  motivo = NA_character_,
                                  error_esperado = "no_aplica"
                                ),
                                politica_costo = list(
                                  nombre = "todas",
                                  umbral = .UMBRAL_CARDINALIDAD_COSTO_DBI
                                ),
                                infinitos_como_numeric = FALSE,
                                columnas_float8_numeric = character(),
                                tipos_motor = NULL) {
  if (is.null(dialecto)) dialecto <- .dialectos_dbi()$limit
  if (is.null(campos_consolidados)) campos_consolidados <- campos
  if (is.null(campos_sql_consolidados)) {
    campos_sql_consolidados <- vapply(campos_consolidados, function(campo) {
      .citar_identificador_dbi(conexion, campo)
    }, character(1L), USE.NAMES = FALSE)
  }
  if (is.null(es_numerico_consolidados)) {
    es_numerico_consolidados <- vapply(seq_along(campos_consolidados), function(i) {
      .es_numerico_dbi(
        .atributo_columna_dbi(prototipo, campos_consolidados[[i]], i),
        .atributo_columna_dbi(
          tipos_declarados, campos_consolidados[[i]], i
        ) %||% NA_character_
      )
    }, logical(1L))
    names(es_numerico_consolidados) <- campos_consolidados
  }
  tipo_motor_de <- function(campo) {
    if (is.na(.indice_nombre(campo, campos_consolidados))) {
      return(NA_character_)
    }
    tipo <- .atributo_columna_dbi(tipos_motor, campo) %||% NA_character_
    if (length(tipo) != 1L || is.na(tipo) || !nzchar(as.character(tipo))) {
      tipo <- .atributo_columna_dbi(tipos_declarados, campo) %||% NA_character_
    }
    as.character(tipo)
  }
  tipo_sin_agregados_de <- function(campo) {
    tipo <- tipo_motor_de(campo)
    if (any(grepl(
      "sql server|microsoft sql|sqlserver|mssql",
      .senas_conexion_dbi(conexion), perl = TRUE, useBytes = TRUE
    ))) .tipo_sqlserver_sin_agregados_dbi(tipo) else FALSE
  }
  sql_de <- function(campo) {
    if (!.nombre_representable_dbi(conexion, campo)) return(NA_character_)
    indice <- .indice_nombre(campo, campos_consolidados)
    if (is.na(indice) || indice > length(campos_sql_consolidados)) {
      return(NA_character_)
    }
    as.character(campos_sql_consolidados[[indice]])
  }
  exacto_derrame <- (
    "distintos" %in% metricas_ejecucion &&
      identical(estrategia_distintos$estrategia_resuelta, "COUNT(DISTINCT)")
  ) || ("moda" %in% metricas_ejecucion && isTRUE(incluir_valores)) || (
    "mediana" %in% metricas_ejecucion && isTRUE(incluir_valores) &&
      (!is.null(mediana_consolidada) || !is.null(mediana_escalar) ||
       (!identical(universo, "muestra_motor") && is.null(aproximaciones$mediana)))
  )
  if (!is.null(presupuesto)) .iniciar_instrumentacion_derrame_dbi(
    conexion, presupuesto, exacto = exacto_derrame
  )
  columnas_distintos_resumen <- .columnas_distintos_ejecucion_dbi(
    metricas_ejecucion, estrategia_distintos, campos_consolidados,
    fuentes_cardinalidad_costo, politica_costo
  )
  columnas_distintos_resumen <- columnas_distintos_resumen[
    !vapply(columnas_distintos_resumen, tipo_sin_agregados_de, logical(1L))
  ]
  tipos_declarados_consolidados <- .alinear_atributos_columnas_dbi(
    campos_consolidados, tipos = tipos_declarados
  )$tipos
  agregados <- .agregados_consolidados_dbi(
    conexion, tabla_metricas_sql, campos_consolidados,
    campos_sql_consolidados, es_numerico_consolidados, metricas_ejecucion,
    incluir_valores, presupuesto, tamano_lote_planos, tamano_lote_distintos,
    aproximacion_distintos = aproximaciones$distintos,
    tabla_total_sql = tabla_total_sql, conteo_inicial = conteo,
    columnas_distintos = columnas_distintos_resumen,
    tipos_declarados = tipos_declarados_consolidados,
    columnas_float8_numeric = columnas_float8_numeric,
    infinitos_como_numeric = infinitos_como_numeric,
    universo = universo
  )
  conteo <- agregados$conteo
  n_total <- agregados$n_total
  if (is.null(conteo) || !isTRUE(conteo$ok) || is.na(n_total)) {
    motivo <- if (is.null(conteo)) {
      "No se pudo obtener el conteo exacto de la tabla."
    } else if (!isTRUE(conteo$ok)) {
      paste0("No se pudo contar la tabla: ", conteo$motivo)
    } else {
      "La consulta de conteo no devolvi\u00f3 un n\u00famero utilizable."
    }
    # El presupuesto es una degradacion esperable, no un error fatal: las
    # metricas que ya entraron siguen siendo utiles aunque el denominador no
    # haya entrado. Otros fallos de conteo si impiden interpretar el resumen y
    # conservan la condicion de error que ya tenia la via DBI.
    motivo_conteo <- if (is.null(conteo)) "" else {
      if (is.null(conteo$motivo)) "" else as.character(conteo$motivo)
    }
    agotado_por_presupuesto <- length(motivo_conteo) == 1L &&
      grepl("presupuesto declarado", motivo_conteo, fixed = TRUE, useBytes = TRUE)
    if (!agotado_por_presupuesto) {
      .detener_dbi(
        "lupa_error_conteo_dbi", motivo,
        datos = list(sql = if (is.null(conteo)) NA_character_ else conteo$sql)
      )
    }
    n_total <- NA_real_
  }
  agregados <- .incorporar_distintos_estructurales_dbi(
    agregados, fuentes_cardinalidad_costo, n_total, universo
  )
  sql_conteo_registro <- if (is.null(conteo) || is.null(conteo$sql)) {
    sql_conteo
  } else {
    conteo$sql
  }
  if (identical(universo, "muestra_motor")) {
    if (is.finite(.numero_dbi(tamano_muestra))) {
      # Si la solicitud supera el universo, la consulta puede devolver menos
      # filas que las pedidas. El tamano efectivo es el que se midio y el que
      # debe aparecer en la metadata; usar el pedido volveria a extrapolar una
      # muestra que en realidad cubrio toda la tabla.
      tamano_muestra <- min(.numero_dbi(tamano_muestra), .numero_dbi(n_total))
      fraccion_muestra <- .fraccion_muestreo_dbi(tamano_muestra, n_total)
    }
    if (!is.null(muestreo)) {
      muestreo$universo <- n_total
      muestreo$tamano_muestra <- tamano_muestra
      muestreo$fraccion <- fraccion_muestra
    }
  }
  decisiones_costo <- .decisiones_costo_dbi(
    campos_consolidados, agregados, politica_costo, universo,
    fuentes_cardinalidad_costo = fuentes_cardinalidad_costo
  )
  if (!is.null(presupuesto)) {
    presupuesto$estimacion_derrame_moda <- .actualizar_n_validos_estimacion_dbi(
      presupuesto$estimacion_derrame_moda, agregados, metricas_ejecucion, "meta"
    )
    presupuesto$estimacion_derrame_mediana <- .actualizar_n_validos_estimacion_dbi(
      presupuesto$estimacion_derrame_mediana, agregados, metricas_ejecucion, "meta"
    )
  }
  # La moda y la mediana son dos familias distintas: preparar todas las modas
  # antes de entrar en la mediana deja disponibles primero las metricas con
  # mayor cobertura, incluso cuando no hay una consolidacion de medianas.
  columnas_modas <- campos_consolidados[
    !is.na(.indice_nombre(campos_consolidados, campos))
  ]
  columnas_modas <- columnas_modas[
    vapply(columnas_modas, function(campo) {
      indice_decision <- .indice_nombre(campo, names(decisiones_costo))
      decision <- if (is.na(indice_decision)) NULL else {
        decisiones_costo[[indice_decision]]
      }
      motivo <- if (is.null(motivos_ilegibles) ||
                    is.na(.indice_nombre(campo, names(motivos_ilegibles)))) {
        NA_character_
      } else {
        motivos_ilegibles[[.indice_nombre(campo, names(motivos_ilegibles))]]
      }
      binaria_moda <- .es_tipo_binario_muestra_dbi(
        tipo_motor_de(campo), .senas_conexion_dbi(conexion)
      )
      "moda" %in% metricas_ejecucion && isTRUE(incluir_valores) &&
        (!tipo_sin_agregados_de(campo) || binaria_moda) &&
        (is.null(decision) || isTRUE(decision$moda)) &&
        is.na(motivo)
    }, logical(1L))
  ]
  modas <- vector("list", length(columnas_modas))
  names(modas) <- columnas_modas
  if (length(columnas_modas) && !is.null(presupuesto) &&
      !isTRUE(presupuesto$aviso_derrame_moda_emitido)) {
    estimacion_aviso <- .filtrar_estimacion_derrame_dbi(
      presupuesto$estimacion_derrame_moda, columnas_modas
    )
    avisado <- .avisar_derrame_estimado_postgresql_dbi(
      estimacion_aviso,
      habilitado = if (is.null(presupuesto$avisar_derrame_estimado)) TRUE else
        presupuesto$avisar_derrame_estimado,
      umbral_bytes = if (is.null(presupuesto$umbral_bytes_aviso_derrame_estimado)) {
        .UMBRAL_BYTES_AVISO_DERRAME_ESTIMADO_DBI
      } else presupuesto$umbral_bytes_aviso_derrame_estimado
    )
    if (isTRUE(avisado)) presupuesto$aviso_derrame_moda_emitido <- TRUE
  }
  for (posicion in seq_along(columnas_modas)) {
    campo <- columnas_modas[[posicion]]
    pendientes <- columnas_modas[posicion:length(columnas_modas)]
    cardinalidades <- stats::setNames(lapply(pendientes, function(nombre) {
      .cardinalidad_aviso_moda_dbi(
        nombre, agregados, fuentes_cardinalidad_costo, n_total
      )
    }), pendientes)
    if (!is.null(presupuesto)) {
      proyeccion <- .proyectar_costo_moda_dbi(presupuesto, cardinalidades)
      presupuesto$proyeccion_moda <- proyeccion
      if (!isTRUE(presupuesto$aviso_moda_emitido)) {
        avisado <- .avisar_costo_moda_dbi(
          proyeccion,
          habilitado = if (is.null(presupuesto$avisar_costo_moda)) TRUE else
            presupuesto$avisar_costo_moda,
          umbral_segundos = if (is.null(presupuesto$umbral_segundos_aviso_moda)) {
            .UMBRAL_SEGUNDOS_AVISO_MODA_DBI
          } else presupuesto$umbral_segundos_aviso_moda
        )
        if (isTRUE(avisado)) presupuesto$aviso_moda_emitido <- TRUE
      }
    }
    prototipo_campo <- .atributo_columna_dbi(prototipo, campo)
    entero_doble <- .entero_doble_ancho_moda_dbi(
      prototipo_campo, tipo_motor_de(campo),
      .extremos_basicos_moda_dbi(agregados, campo)
    )
    columna_moda_sql <- .expresion_binaria_moda_dbi(
      conexion, sql_de(campo), tipo_motor_de(campo)
    )
    valor_moda_sql <- .expresion_decimal_moda_dbi(
      conexion, columna_moda_sql, tipo_motor_de(campo),
      entero_doble = entero_doble
    )
    orden_moda_sql <- .orden_moda_dbi(
      conexion, valor_moda_sql, tipo_motor_de(campo),
      orden_numerico_sql = if (isTRUE(entero_doble)) {
        columna_moda_sql
      } else NULL
    )
    guardian_moda <- moda_guardian
    modas[[campo]] <- if (isTRUE(is.na(valor_moda_sql))) {
      list(
        ok = FALSE, datos = NULL,
        motivo = paste(
          "No se pudo pedir la moda exacta como texto en este motor;",
          "no se publica la moda del doble redondeado."
        ), sql = NA_character_
      )
    } else {
      .moda_columna_dbi(
        conexion, tabla_metricas_sql, columna_moda_sql,
        dialecto, presupuesto, moda_guardian = guardian_moda,
        valor_sql = valor_moda_sql, orden_sql = orden_moda_sql
      )
    }
    if (!is.null(presupuesto)) {
      cardinalidad <- .cardinalidad_aviso_moda_dbi(
        campo, agregados, fuentes_cardinalidad_costo, n_total
      )
      .registrar_referencia_moda_dbi(
        presupuesto, modas[[campo]], cardinalidad$n_distintos, campo
      )
    }
  }
  columnas_medianas <- campos_consolidados[
    !is.na(.indice_nombre(campos_consolidados, campos))
  ]
  columnas_medianas <- columnas_medianas[
    .indice_nombre(columnas_medianas, campos_consolidados) <=
      length(es_numerico_consolidados) &
      es_numerico_consolidados[
        .indice_nombre(columnas_medianas, campos_consolidados)
      ]
  ]
  columnas_medianas <- columnas_medianas[
    vapply(columnas_medianas, function(campo) {
      indice_decision <- .indice_nombre(campo, names(decisiones_costo))
      decision <- if (is.na(indice_decision)) NULL else {
        decisiones_costo[[indice_decision]]
      }
      "mediana" %in% metricas_ejecucion && isTRUE(incluir_valores) &&
      (is.null(decision) || isTRUE(decision$mediana))
    }, logical(1L))
  ]
  if (length(columnas_medianas) && !is.null(presupuesto) &&
      !isTRUE(presupuesto$aviso_derrame_mediana_emitido)) {
    estimacion_aviso <- .filtrar_estimacion_derrame_dbi(
      presupuesto$estimacion_derrame_mediana, columnas_medianas
    )
    avisado <- .avisar_derrame_estimado_postgresql_dbi(
      estimacion_aviso,
      habilitado = if (is.null(presupuesto$avisar_derrame_estimado)) TRUE else
        presupuesto$avisar_derrame_estimado,
      umbral_bytes = if (is.null(presupuesto$umbral_bytes_aviso_derrame_estimado)) {
        .UMBRAL_BYTES_AVISO_DERRAME_ESTIMADO_DBI
      } else presupuesto$umbral_bytes_aviso_derrame_estimado
    )
    if (isTRUE(avisado)) presupuesto$aviso_derrame_mediana_emitido <- TRUE
  }
  medianas <- vector("list", length(columnas_medianas))
  names(medianas) <- columnas_medianas
  if (length(columnas_medianas) && !is.null(presupuesto)) {
    presupuesto$filas_mediana <- if (identical(universo, "muestra_motor")) {
      .numero_dbi(tamano_muestra)
    } else {
      .numero_dbi(n_total)
    }
    presupuesto$medianas_pendientes <- length(columnas_medianas)
  }
  columnas_medianas_consolidadas <- setdiff(
    columnas_medianas, columnas_float8_numeric
  )
  # Un decimal no entra en la consolidada, que interpola en doble: su mediana es
  # la suma de sus centrales (ver `.mediana_decimal_por_centrales_dbi()`) y cae
  # a la via por columna -dos consultas, o la CTE de la muestra-, con el mismo
  # tipo que alli decide la consulta.
  if (length(columnas_medianas_consolidadas)) {
    senas_consolidada <- .senas_conexion_dbi(conexion)
    por_centrales <- vapply(columnas_medianas_consolidadas, function(campo) {
      i <- .indice_nombre(campo, campos)
      .mediana_decimal_por_centrales_dbi(
        senas_consolidada,
        .atributo_columna_dbi(tipos_declarados, campo, i) %||% NA_character_
      )
    }, logical(1L))
    columnas_medianas_consolidadas <- columnas_medianas_consolidadas[
      !por_centrales
    ]
  }
  if (length(columnas_medianas_consolidadas) &&
      !is.null(mediana_consolidada)) {
    requiere_repliegue <- vapply(columnas_medianas_consolidadas, function(campo) {
      basicos <- agregados$basicos[[campo]]
      conteo <- agregados$conteos[[campo]]
      validos <- if (is.list(conteo)) conteo$validos else NULL
      if (!is.list(basicos) || !isTRUE(basicos$ok) ||
          !is.list(validos) || !isTRUE(validos$ok) ||
          !is.data.frame(basicos$datos) || !nrow(basicos$datos)) {
        return(FALSE)
      }
      minimo <- .valor_campo_dbi(basicos$datos, "minimo")
      maximo <- .valor_campo_dbi(basicos$datos, "maximo")
      .requiere_mediana_escalada_dbi(
        list(
          minimo = .escalar_finito_dbi(minimo$valor),
          maximo = .escalar_finito_dbi(maximo$valor)
        ), validos$valor, conexion = conexion
      )
    }, logical(1L))
    columnas_medianas_consolidadas <- columnas_medianas_consolidadas[
      !requiere_repliegue
    ]
  }
  if (length(columnas_medianas_consolidadas) &&
      !is.null(mediana_consolidada)) {
    expresiones_medianas <- vapply(seq_along(campos_consolidados), function(i) {
      .expresion_mediana_motor_dbi(
        conexion, campos_sql_consolidados[[i]],
        tipo_motor_de(campos_consolidados[[i]])
      )
    }, character(1L))
    medianas <- .medianas_consolidadas_dbi(
      conexion, tabla_metricas_sql, columnas_medianas_consolidadas,
      stats::setNames(expresiones_medianas, campos_consolidados),
      function(nombre) .citar_identificador_dbi(conexion, nombre),
      mediana_consolidada, presupuesto, tamano_lote_planos
    )
  }
  tipo_de <- function(i) {
    .atributo_columna_dbi(tipos_declarados, campos[[i]], i) %||% NA_character_
  }
  motivo_de <- function(campo) {
    indice <- if (is.null(motivos_ilegibles)) NA_integer_ else {
      .indice_nombre(campo, names(motivos_ilegibles))
    }
    if (is.na(indice)) {
      return(NA_character_)
    }
    motivos_ilegibles[[indice]]
  }
  resultados <- lapply(seq_along(campos), function(i) {
    campo <- campos[[i]]
    .resumen_columna_dbi(
      conexion, tabla_metricas_sql, campo,
      .atributo_columna_dbi(prototipo, campo, i) %||% NA,
      n_total, dialecto = dialecto, metricas = metricas,
      presupuesto = presupuesto, incluir_valores = incluir_valores,
      tipo_declarado = tipo_de(i), tipo_motor = tipo_motor_de(campo),
      motivo_ilegible = motivo_de(campo),
      universo = universo, muestreo = muestreo,
      aproximacion_distintos = aproximaciones$distintos,
      aproximacion_mediana = aproximaciones$mediana,
      tamano_muestra = tamano_muestra, fraccion_muestra = fraccion_muestra,
      agregados = agregados,
      moda_guardian = moda_guardian,
      mediana_consolidada = medianas[[campo]],
      mediana_escalar = mediana_escalar,
      mediana_cte_ventana = mediana_cte_ventana,
      mediana_cte_ventana_motivo = mediana_cte_ventana_motivo,
      moda_precalculada = modas[[campo]],
      decisiones_costo = decisiones_costo[[campo]],
      publica_distintos = isTRUE(estrategia_distintos$publica),
      estrategia_distintos = estrategia_distintos,
      infinitos_como_numeric = isTRUE(infinitos_como_numeric) &&
        campo %in% columnas_float8_numeric ||
        .es_lectura_double_exacta_dbi(sql_de(campo)),
      numeric_exact = grepl("postgres|pqconnection",
                             .senas_conexion_dbi(conexion), useBytes = TRUE) &&
        campo %in% columnas_float8_numeric ||
        .es_lectura_double_exacta_dbi(sql_de(campo)),
      columna_sql = sql_de(campo)
    )
  })
  if (identical(universo, "tabla_completa") ||
      (identical(universo, "muestra_motor") && !is.null(agregados$exactos))) {
    resultados <- .decimales_exactos_tabla_dbi(
      conexion, campos, resultados, metricas,
      tipo_de = function(i) {
        tipo <- tipo_motor_de(campos[[i]])
        if (length(tipo) != 1L || is.na(tipo) || !nzchar(tipo)) tipo_de(i) else
          tipo
      },
      tipo_regla = tipo_de, agregados = agregados, universo = universo,
      es_numerico = vapply(seq_along(campos), function(i) {
        .es_numerico_dbi(
          .atributo_columna_dbi(prototipo, campos[[i]], i), tipo_de(i)
        )
      }, logical(1L))
    )
  }
  resultados <- .valores_ausentes_por_cuenta_dbi(
    campos, resultados, metricas, agregados, universo = universo
  )
  .finalizar_instrumentacion_derrame_dbi(conexion, presupuesto)
  columnas <- if (length(resultados)) {
    filas <- lapply(
      lapply(resultados, `[[`, "fila"), .fila_magnitudes_dobles_dbi
    )
    as.data.frame(do.call(rbind, lapply(filas, as.data.frame)),
                  stringsAsFactors = FALSE)
  } else {
    .columnas_dbi_vacias()
  }
  numericas <- intersect(
    c("prop_faltantes", "tasa_distintos", "minimo", "maximo", "media",
      "mediana", "desvio"), names(columnas)
  )
  columnas[numericas] <- lapply(columnas[numericas], as.numeric)
  n_conocido <- !is.null(conteo) && isTRUE(conteo$ok) &&
    length(n_total) == 1L && is.finite(n_total)
  motivo_n <- if (isTRUE(n_conocido)) {
    NA_character_
  } else if (!is.null(conteo) && length(conteo$motivo) == 1L &&
             !is.na(conteo$motivo) && nzchar(as.character(conteo$motivo))) {
    as.character(conteo$motivo)
  } else {
    "No se pudo obtener el conteo exacto de la tabla."
  }
  estado_n <- if (isTRUE(n_conocido)) "calculado" else "no_disponible"
  sql <- if (length(resultados)) {
    rbind(
      .registro_sql_dbi(
        campos, rep("n", length(campos)), estado_n, motivo_n,
        sql_conteo_registro,
        metadatos = .mezclar_metadatos_dbi(.metadatos_sql_dbi(
          # `n` is the declared exception: it counts the complete universe even
          # when every other SQL metric describes a motor sample.
          alcance = "tabla_completa",
          universo = n_total, tamano_muestra = if (identical(universo, "muestra_motor")) {
            tamano_muestra
          } else NA_real_,
          fraccion = if (identical(universo, "muestra_motor")) fraccion_muestra else 1,
          metodo = "conteo_universo",
          error_esperado = "no_aplica"
        ), if (is.null(conteo)) NULL else conteo$metadatos),
        medicion = conteo,
        etapa = "conteo_filas"
      ),
      do.call(rbind, lapply(resultados, `[[`, "sql"))
    )
  } else {
    .registro_sql_dbi(character(), character(), character(), character(), character())
  }
  sql <- .marcar_nivel_sql_dbi(sql)
  rownames(columnas) <- NULL
  rownames(sql) <- NULL
  filas_obtenidas_muestra <- NA_real_
  if (identical(universo, "muestra_motor")) {
    resultados_denominador <- list()
    for (familia_nombre in c("conteos", "basicos", "desvio")) {
      familia <- agregados[[familia_nombre]]
      if (is.list(familia)) {
        resultados_denominador <- c(
          resultados_denominador, unname(familia)
        )
      }
    }
    denominadores <- unlist(lapply(resultados_denominador, function(resultado) {
      medidos <- if (!is.null(resultado$metadatos)) {
        list(resultado)
      } else {
        Filter(Negate(is.null), resultado[c(
          "validos", "basicos", "desvio"
        )])
      }
      vapply(medidos, function(medido) {
        if (is.null(medido$metadatos)) return(NA_real_)
        .numero_dbi(medido$metadatos$n_total_consulta)
      }, numeric(1L))
    }), use.names = FALSE)
    denominadores <- denominadores[is.finite(denominadores)]
    if (length(denominadores)) filas_obtenidas_muestra <- denominadores[[1L]]
  }
  meta <- list(
       universo = universo,
       incluir_valores = isTRUE(incluir_valores),
       estrategia_mediana = estrategia_mediana,
       filas_obtenidas_muestra = filas_obtenidas_muestra,
       alcance = if (identical(universo, "muestra_motor")) {
         "tabla_muestreada"
       } else {
         "tabla_completa"
       },
      tabla = .texto_tabla_dbi(tabla),
       filas = n_total,
      motor = info_conexion,
      sql_conteo_filas = sql_conteo,
      criterio_moda = paste(
        "mayor frecuencia; empates resueltos por el valor ascendente",
        "seg\u00fan el orden del motor"
      ),
      # El motor compara con su cotejamiento y R con `==`. Sobre una columna
      # `utf8mb4_general_ci`, `"A"` y `"a"` son un valor para el motor y dos
      # para R, asi que `resumen_tabla` y `perfil_muestra` pueden informar
      # cardinalidades distintas de las mismas filas. Las dos son ciertas en su
      # propia comparacion; lo que faltaba era decir cual usa cada bloque.
      criterio_comparacion = paste(
        "el resumen SQL agrupa y ordena con el cotejamiento del motor, que",
        "puede ignorar caja o acentos; el perfil de muestra compara en R, que",
        "distingue byte a byte. Una diferencia entre los dos bloques en",
        "`n_distintos` o en la moda es esperable sobre columnas con",
        "cotejamiento insensible, y no es un error de ninguno de los dos"
      ),
      # En `muestra_motor` la relacion muestreada tiene una sola identidad: la
      # del spool externo que se abre antes de las pasadas. Este campo historico
      # ya no se publica; el contrato legible vive en `meta$materializacion` y
      # en `meta$muestreo`, donde `muestra_id` no se confunde con un id de
      # consulta SQL.
      solo_lectura = TRUE,
      objetos_temporales = FALSE,
      snapshot = FALSE,
      nota_snapshot = paste(
        "No hubo lectura instant\u00e1nea: cada agregado se midi\u00f3 en su propio",
        "momento y la tabla pudo cambiar entre consultas. La cobertura declara",
        "las comparaciones incoherentes entre grupos de consistencia distintos."
      ),
      politica_costo = politica_costo,
      decisiones_costo = decisiones_costo,
      # Este objeto usa el catalogo solo para anticipar el costo de memoria.
      # Nunca reemplaza a `meta$derrame`, que solo puede salir de una medicion
      # posterior por `pg_stat_statements`.
      estimacion_derrame = agregados$estimacion_derrame,
      estimacion_derrame_moda = if (is.null(presupuesto)) {
        .estimacion_derrame_familia_vacia_dbi(
          "moda", "No se solicit\u00f3 una estimaci\u00f3n de derrame."
        )
      } else presupuesto$estimacion_derrame_moda,
      estimacion_derrame_mediana = if (is.null(presupuesto)) {
        .estimacion_derrame_familia_vacia_dbi(
          "mediana", "No se solicit\u00f3 una estimaci\u00f3n de derrame."
        )
      } else presupuesto$estimacion_derrame_mediana
    )
  if (!identical(universo, "muestra_motor")) {
    meta$filas_obtenidas_muestra <- NULL
  }
  list(
    columnas = columnas,
    sql = sql,
    cobertura = .cobertura_dbi_vacia(),
    literales = unlist(lapply(resultados, `[[`, "literales"), use.names = TRUE),
    meta = meta
  )
}

.verificar_orden_dbi <- function(conexion, tabla_sql, orden_sql, dialecto,
                                 presupuesto = NULL) {
  alias <- .citar_identificador_dbi(conexion, "n_grupos_repetidos")
  sql <- paste0(
    "SELECT ", .conteo_sql_dbi("COUNT(*)", .senas_conexion_dbi(conexion)),
    " AS ", alias, " FROM (SELECT ",
    paste(orden_sql, collapse = ", "), " FROM ", tabla_sql,
    " GROUP BY ", paste(orden_sql, collapse = ", "),
    " HAVING COUNT(*) > 1)", dialecto$alias_tabla("lupa_orden_repetido")
  )
  resultado <- .escalar_dbi(
    conexion, sql, "n_grupos_repetidos", presupuesto,
    etapa = "verificacion_orden"
  )
  repetidos <- .escalar_finito_dbi(resultado$valor)
  list(
    unico = resultado$ok && identical(repetidos, 0),
    sql = sql,
    motivo = if (!resultado$ok) {
      paste0("No se pudo verificar la unicidad del orden: ", resultado$motivo)
    } else if (is.na(repetidos)) {
      "La verificaci\u00f3n de unicidad no devolvi\u00f3 un conteo utilizable."
    } else if (repetidos > 0) {
      "Las columnas de orden no identifican cada fila de forma \u00fanica."
    } else {
      "Las columnas de orden identifican cada fila de forma \u00fanica."
    }
  )
}

# ---- Esquema: enumerar y sondear ----------------------------------------
#
# `SELECT *` es un porton innecesario: los nombres ya los dio
# `dbListFields()`. Y cuando el motor rechaza una columna -un LOB que no
# materializa, un permiso a nivel de columna- enumerar tampoco alcanza por si
# solo: hay que sondear columna por columna y descartar la que falle, para que
# las sanas se perfilen enteras.

.campos_dbi <- function(conexion, tabla, tabla_sql, presupuesto) {
  # Las columnas y lo que la credencial puede leer de cada una salen de la
  # misma funcion que usan las demas puertas: ver `.columnas_tabla_dbi()`.
  columnas <- .columnas_tabla_dbi(conexion, tabla, tabla_sql, presupuesto)
  if (length(columnas$campos)) {
    return(list(
      campos = columnas$campos, motivo = NA_character_,
      origen = if (isTRUE(columnas$catalogo)) "catalogo" else "dbListFields",
      columnas = columnas, tipos_motor = columnas$tipos_motor,
      tipo_objeto = columnas$tipo_objeto
    ))
  }
  campos <- if (is.null(columnas$error)) character() else columnas$error
  motivo <- if (inherits(campos, "condition")) {
    .mensaje_motor(campos)
  } else {
    "dbListFields() no devolvi\u00f3 ning\u00fan campo."
  }
  # El metodo por omision de DBI emite `SELECT * ... LIMIT 0`, asi que un motor
  # sin `LIMIT` muere aca, en la primera consulta, con el texto crudo del
  # driver. Se degrada a leer el esquema con una consulta de cero filas.
  respaldo <- .consultar_dbi(
    conexion, paste0("SELECT * FROM ", tabla_sql, " WHERE 1 = 0"),
    presupuesto, etapa = "esquema"
  )
  if (respaldo$ok && length(names(respaldo$datos))) {
    return(list(
      campos = names(respaldo$datos), origen = "select_cero_filas",
      motivo = paste0(
        "dbListFields() no sirvio (", motivo,
        "); los nombres se leyeron con una consulta de cero filas."
      )
    ))
  }
  .detener_dbi("lupa_error_campos_dbi", paste0(
    "No se pudieron enumerar las columnas de la tabla. dbListFields(): ",
    motivo, ". Consulta de cero filas: ",
    if (respaldo$ok) "no devolvi\u00f3 campos" else respaldo$motivo, "."
  ))
}

.sql_esquema_dbi <- function(tabla_sql, campos_sql) {
  paste0(
    "SELECT ", paste(campos_sql, collapse = ", "), " FROM ", tabla_sql,
    " WHERE 1 = 0"
  )
}

.leer_esquema_dbi <- function(conexion, sql, presupuesto, etapa = "esquema") {
  if (!.gastar_dbi(presupuesto)) {
    return(c(list(
      ok = FALSE, datos = NULL, tipos = NULL,
      motivo = .motivo_presupuesto_dbi(presupuesto)
    ), .medicion_consulta_vacia_dbi(etapa)))
  }
  medicion <- .iniciar_consulta_dbi(presupuesto, etapa)
  resultado <- NULL
  on.exit(
    if (!is.null(resultado)) .limpiar_consulta_dbi(resultado, conexion),
    add = TRUE
  )
  salida <- tryCatch({
    resultado <- .enviar_consulta_dbi(conexion, sql)
    prototipo <- .traer_filas_dbi(resultado, n = 0L, conexion)
    informacion <- tryCatch(DBI::dbColumnInfo(resultado), error = function(e) NULL)
    tipos <- if (is.data.frame(informacion) && "type" %in% names(informacion)) {
      as.character(informacion$type)
    } else {
      NULL
    }
    # El nombre del tipo EN EL MOTOR, cuando el controlador lo da: RPostgres lo
    # publica en `.typname` (`money`, `float4`), y su `type` -la clase de R,
    # `double` para los dos- no los distingue. Decide como se lee la columna:
    # ver `.lectura_convertida_dbi()`.
    tipos_motor <- if (is.data.frame(informacion) &&
                       ".typname" %in% names(informacion)) {
      as.character(informacion[[".typname"]])
    } else if (grepl("odbc", .senas_conexion_dbi(conexion),
                     useBytes = TRUE) && is.data.frame(prototipo) &&
               !is.null(attr(prototipo, "lupa_tipos_odbc", exact = TRUE))) {
      # odbc publica el codigo ODBC (por ejemplo, 7 = SQL_REAL) en `type`,
      # pero la misma informacion queda guardada por `.traer_filas_dbi()`
      # antes de que el controlador convierta el valor a `double`. Es la unica
      # forma comun de distinguir REAL de FLOAT en SQL Server.
      as.character(attr(prototipo, "lupa_tipos_odbc", exact = TRUE))
    } else {
      NULL
    }
    list(ok = TRUE, datos = prototipo, tipos = tipos, tipos_motor = tipos_motor,
         motivo = NA_character_)
  }, error = function(e) {
    .repropagar_transaccion_dbi(e)
    list(ok = FALSE, datos = NULL, tipos = NULL, tipos_motor = NULL,
         motivo = .mensaje_motor(e),
         no_representable = inherits(e, "lupa_error_codificacion_dbi"))
  })
  .adjuntar_medicion_dbi(
    salida, .terminar_consulta_dbi(medicion, salida$datos)
  )
}

# DuckDB entrega `numeric` en `dbColumnInfo()` cuando la conexion pide dobles,
# aunque la tabla declare BIGINT o DECIMAL. `DESCRIBE` conserva esa declaracion
# y permite distinguirla de REAL, FLOAT y DOUBLE sin mirar los valores.
.tipos_declarados_duckdb_dbi <- function(
    conexion, tabla_sql, campos, tipos, presupuesto) {
  if (!inherits(conexion, "duckdb_connection")) return(tipos)
  consulta <- .consultar_dbi(
    conexion, paste0("DESCRIBE ", tabla_sql), presupuesto,
    etapa = "esquema"
  )
  if (!isTRUE(consulta$ok) || !is.data.frame(consulta$datos)) return(tipos)
  datos <- consulta$datos
  if (!all(c("column_name", "column_type") %in% names(datos))) return(tipos)
  salida <- if (is.null(tipos)) rep(NA_character_, length(campos)) else tipos
  if (length(salida) < length(campos)) {
    length(salida) <- length(campos)
  }
  for (i in seq_along(campos)) {
    posicion <- .indice_nombre(campos[[i]], datos$column_name)
    if (!is.na(posicion)) salida[[i]] <- as.character(datos$column_type[[posicion]])
  }
  names(salida) <- campos
  salida
}

# Las columnas que el catalogo dijo que la credencial no puede leer
# (`sin_permiso`, ver `.columnas_tabla_dbi()`) no se nombran en NINGUNA
# consulta: no entran a la lectura conjunta ni a la sonda por columna, y se
# declaran como las que el motor rechazo, con su motivo. Antes la lectura
# conjunta las nombraba, el motor la rechazaba, y con odbc la sonda siguiente
# hacia caer a R.
.esquema_dbi <- function(conexion, tabla_sql, campos, presupuesto,
                         sin_permiso = character(),
                         sql_catalogo = NA_character_) {
  negadas <- .nombres_presentes(campos, sin_permiso)
  if (!any(negadas)) {
    return(.esquema_legibles_dbi(conexion, tabla_sql, campos, presupuesto))
  }
  if (all(negadas)) {
    .detener_dbi("lupa_error_esquema_dbi", paste(
      "No se pudo leer el esquema de la tabla: la credencial no tiene permiso",
      "SELECT sobre ninguna de sus columnas (lo dice el cat\u00e1logo del motor), y",
      "no se envi\u00f3 ninguna consulta que las nombre."
    ))
  }
  esquema <- .esquema_legibles_dbi(
    conexion, tabla_sql, campos[!negadas], presupuesto
  )
  negadas <- campos[negadas]
  motivos <- stats::setNames(
    rep(list(.motivo_columna_sin_permiso_dbi()), length(negadas)), negadas
  )
  esquema$ilegibles <- c(negadas, esquema$ilegibles)
  esquema$motivos <- c(motivos, esquema$motivos)
  esquema$sin_permiso <- negadas
  esquema$sql_catalogo <- sql_catalogo
  if (is.null(esquema$no_representables)) esquema$no_representables <- character()
  esquema
}

# El presupuesto puede agotarse despues de que el catalogo ya dio los nombres
# de las columnas, pero antes de que una consulta de cero filas devuelva sus
# tipos. Eso no es un fallo del esquema: es una corrida sin saldo. Conservar
# los nombres permite construir el resumen, declarar todas las metricas como no
# calculadas y, si hace falta, publicar la muestra como no disponible. No se
# inventan tipos ni prototipos: sin esa lectura no se decide ninguna cifra.
.esquema_minimo_por_presupuesto_dbi <- function(conexion, tabla_sql, campos,
                                               lista_campos, motivo) {
  campos <- as.character(campos)
  campos_sql <- vapply(
    campos, function(campo) .citar_identificador_dbi(conexion, campo),
    character(1L), USE.NAMES = FALSE
  )
  tipos_motor <- rep(NA_character_, length(campos))
  nombres_tipos <- if (is.list(lista_campos) &&
                       is.list(lista_campos$columnas)) {
    lista_campos$columnas$tipos_motor
  } else NULL
  if (length(nombres_tipos) && length(names(nombres_tipos))) {
    posiciones <- .indice_nombre(campos, names(nombres_tipos))
    tipos_motor[!is.na(posiciones)] <- as.character(
      nombres_tipos[posiciones[!is.na(posiciones)]]
    )
  }
  names(tipos_motor) <- campos
  prototipo <- lapply(campos, function(campo) logical())
  names(prototipo) <- campos
  tipos <- rep(NA_character_, length(campos))
  names(tipos) <- campos
  motivos <- stats::setNames(rep(list(as.character(motivo)), length(campos)), campos)
  list(
    campos = campos, campos_sql = campos_sql, prototipo = prototipo,
    prototipo_desconocido = TRUE,
    tipos = tipos, tipos_motor = tipos_motor,
    sql = .sql_esquema_dbi(tabla_sql, campos_sql), ilegibles = character(),
    motivos = motivos, sondeo = FALSE, no_representables = character(),
    sin_permiso = character(), motivo_conjunto = as.character(motivo),
    sql_catalogo = if (is.list(lista_campos$columnas)) {
      lista_campos$columnas$sql_catalogo
    } else NA_character_
  )
}

.esquema_legibles_dbi <- function(conexion, tabla_sql, campos, presupuesto) {
  representables <- vapply(
    campos, .nombre_representable_dbi, logical(1L), conexion = conexion
  )
  no_representables <- campos[!representables]
  motivos_no_representables <- stats::setNames(
    lapply(no_representables, function(campo) {
      .motivo_no_representable_dbi("La columna", texto = campo)
    }), no_representables
  )
  if (!all(representables)) campos <- campos[representables]
  if (!length(campos)) {
    .detener_dbi(
      "lupa_error_esquema_dbi",
      "No se pudo leer el esquema: ninguna columna se puede escribir en la codificaci\u00f3n de la sesi\u00f3n."
    )
  }
  campos_sql <- vapply(campos, function(campo) {
    .citar_identificador_dbi(conexion, campo)
  }, character(1L), USE.NAMES = FALSE)
  sql <- .sql_esquema_dbi(tabla_sql, campos_sql)
  esquema <- .leer_esquema_dbi(conexion, sql, presupuesto)
  if (esquema$ok) {
    tipos <- .tipos_declarados_duckdb_dbi(
      conexion, tabla_sql, campos, esquema$tipos, presupuesto
    )
    names(tipos) <- campos
    tipos_motor <- esquema$tipos_motor
    if (!is.null(tipos_motor)) names(tipos_motor) <- campos
    prototipo <- esquema$datos
    if (!is.null(prototipo)) names(prototipo) <- campos
    return(list(
      campos = campos, campos_sql = campos_sql, prototipo = prototipo,
      tipos = tipos, tipos_motor = tipos_motor, sql = sql,
      ilegibles = no_representables, motivos = motivos_no_representables,
      sondeo = FALSE, no_representables = no_representables
    ))
  }
  # Enumerar no alcanza cuando una de las columnas es la que el motor rechaza.
  # Sondear cuesta una consulta por columna, y solo se paga cuando la lectura
  # conjunta ya fallo.
  motivo_conjunto <- esquema$motivo
  legibles <- character()
  legibles_sql <- character()
  prototipos <- list()
  tipos <- character()
  tipos_motor <- character()
  motivos <- list()
  for (i in seq_along(campos)) {
    sonda <- .sql_esquema_dbi(tabla_sql, campos_sql[[i]])
    parcial <- .leer_esquema_dbi(
      conexion, sonda, presupuesto, etapa = "esquema"
    )
    if (parcial$ok && length(names(parcial$datos))) {
      legibles <- c(legibles, campos[[i]])
      legibles_sql <- c(legibles_sql, campos_sql[[i]])
      prototipos[[length(prototipos) + 1L]] <- parcial$datos[[1L]]
      tipos <- c(tipos, if (length(parcial$tipos)) parcial$tipos[[1L]] else NA_character_)
      tipos_motor <- c(tipos_motor, if (length(parcial$tipos_motor)) {
        parcial$tipos_motor[[1L]]
      } else NA_character_)
    } else {
      if (isTRUE(parcial$no_representable)) {
        no_representables <- c(no_representables, campos[[i]])
      }
      motivos[[campos[[i]]]] <- if (isTRUE(parcial$no_representable)) {
        parcial$motivo
      } else paste0(
        "El motor rechaz\u00f3 la lectura de la columna: ",
        if (parcial$ok) "no devolvi\u00f3 campos" else parcial$motivo, "."
      )
    }
  }
  if (!length(legibles)) {
    .detener_dbi("lupa_error_esquema_dbi", paste0(
      "No se pudo leer el esquema de la tabla ni columna por columna. ",
      "Lectura conjunta: ", motivo_conjunto, "."
    ))
  }
  names(prototipos) <- legibles
  prototipo <- prototipos
  tipos <- .tipos_declarados_duckdb_dbi(
    conexion, tabla_sql, legibles, tipos, presupuesto
  )
  names(tipos) <- legibles
  names(tipos_motor) <- legibles
  list(
    campos = legibles, campos_sql = legibles_sql, prototipo = prototipo,
    tipos = tipos,
    tipos_motor = if (all(is.na(tipos_motor))) NULL else tipos_motor,
    sql = .sql_esquema_dbi(tabla_sql, legibles_sql),
    ilegibles = unique(c(no_representables, names(motivos))),
    motivos = c(motivos_no_representables, motivos), sondeo = TRUE,
    motivo_conjunto = motivo_conjunto, no_representables = no_representables
  )
}

# Como llega a R el valor de cada columna. RPostgres lee mal dos tipos de
# PostgreSQL, y en los dos el motor y la lectura describian valores distintos:
#
# * `money`: lee `0` en toda celda, sin avisar -`SELECT '537.66'::money` da
#   `0`-. La muestra publicaba `constante` y `filas_duplicadas` con severidad
#   `error` sobre cinco importes distintos, y con `bloque_filas` el resumen
#   publicaba minimo, maximo, media y desvio `0` y ninguna divergencia: una cifra
#   falsa sin aviso. Se lee como `NUMERIC`, que es exacto.
# * `real` (`float4`): lee el texto decimal corto del valor -`21.3`-, mientras
#   el motor promedia el binario guardado -21.299999237060547-. La media y el
#   desvio del resumen SQL salian de un valor y los de la muestra y
#   `bloque_filas` del otro: dos cifras para la misma tabla segun la via, y la
#   corroboracion las publicaba como `divergencia`. Se lee por la forma decimal
#   mas corta que vuelve al valor guardado, la cifra que lee R desde
#   PostgreSQL 12, calculada en el motor: ver `.lectura_real_postgresql_dbi()`.
#
# La conversion es la expresion de lectura de la columna, y TODA lectura la usa:
# la seleccion de la muestra, la fuente por bloques y la tabla sobre la que el
# resumen SQL calcula sus agregados (ver `perfilar_dbi()`). PostgreSQL nombra el
# resultado de un `CAST` con el nombre de la columna, asi que la proyeccion no
# cambia de nombres. `tipos_motor` sale de `dbColumnInfo()$.typname`, que solo
# RPostgres publica: con otro controlador no se convierte nada.
.lectura_convertida_dbi <- function(conexion, campos, campos_sql, tipos_motor,
                                    tipos = NULL, presupuesto = NULL) {
  vacia <- data.frame(
    columna = character(), tipo_motor = character(), lectura = character(),
    stringsAsFactors = FALSE
  )
  salida <- list(
    campos_sql = campos_sql, proyeccion_sql = campos_sql, convertidas = vacia
  )
  if (length(campos) != length(campos_sql)) {
    return(salida)
  }
  es_postgres <- grepl(
    "postgres|pqconnection", .senas_conexion_dbi(conexion), useBytes = TRUE
  )
  motor <- if (!is.null(tipos_motor) && length(tipos_motor) == length(campos_sql)) {
    .minusculas_ascii(trimws(as.character(tipos_motor)))
  } else rep(NA_character_, length(campos_sql))
  declarado <- if (!is.null(tipos) && length(tipos) == length(campos_sql)) {
    .minusculas_ascii(trimws(as.character(tipos)))
  } else rep(NA_character_, length(campos_sql))
  tipo <- motor
  tipo[is.na(tipo)] <- declarado[is.na(tipo)]
  # `char(n)` llega como `bpchar` en RPostgres y como codigo ODBC 1; `nchar`
  # llega como codigo -8. En los dos motores el relleno es semantica del tipo,
  # no parte del valor que se compara o se presenta.
  fijo <- !is.na(tipo) & tipo %in% c("bpchar", "char", "nchar", "1", "-8")
  money <- if (es_postgres) !is.na(tipo) & tipo == "money" else {
    rep(FALSE, length(tipo))
  }
  real <- if (es_postgres) !is.na(tipo) & tipo == "float4" else {
    rep(FALSE, length(tipo))
  }
  doble <- if (es_postgres) {
    !is.na(tipo) & tipo %in% c("float8", "double precision")
  } else rep(FALSE, length(tipo))
  if (!any(fijo | money | real | doble)) return(salida)
  expresiones <- campos_sql
  expresiones[fijo] <- paste0("RTRIM(", campos_sql[fijo], ")")
  cambia <- money | real | doble
  expresiones[money] <- paste0("CAST(", campos_sql[money], " AS NUMERIC)")
  if (any(real)) {
    version <- .version_servidor_postgresql_dbi(conexion)
    expresiones[real] <- vapply(
      campos_sql[real], .lectura_real_postgresql_dbi, character(1),
      version = version, USE.NAMES = FALSE
    )
  }
  doble_convertido <- doble
  if (any(doble)) {
    version <- .version_servidor_postgresql_dbi(conexion)
    extra_float_digits <- if (!is.na(version) && version >= 120000L) {
      .extra_float_digits_postgresql_dbi(conexion, presupuesto)
    } else {
      NA_integer_
    }
    # PostgreSQL 12 o posterior escribe el doble de forma redonda con 17
    # cifras cuando `extra_float_digits >= 1`; reconstruir ahi solo agrega
    # costo y puede cambiar el valor por la aritmetica intermedia.
    doble_convertido <- doble & (
      is.na(version) || version < 120000L ||
        is.na(extra_float_digits) || extra_float_digits <= 0L
    )
    if (any(doble_convertido)) {
      expresiones[doble_convertido] <- vapply(
        campos_sql[doble_convertido], .lectura_double_postgresql_dbi,
        character(1L), USE.NAMES = FALSE
      )
    }
  }
  # `campos_sql` siempre son expresiones: pueden entrar dentro de otra consulta
  # sin llevar `AS`. `proyeccion_sql` es la unica forma que puede llevar alias,
  # porque se usa solo en una lista SELECT que conserva los nombres originales.
  lecturas <- expresiones
  # Lleva alias la expresion que PostgreSQL o SQL Server no nombran como la
  # columna: el `RTRIM()` de un `char(n)` y el doble reconstruido (un `CASE`).
  proyeccion <- expresiones
  con_alias <- fijo | doble_convertido
  if (any(con_alias)) {
    alias_dobles <- vapply(campos[con_alias], function(campo) {
      tryCatch(
        .citar_identificador_dbi(conexion, campo),
        error = function(e) paste0(
          "\"", gsub("\"", "\"\"", as.character(campo), fixed = TRUE),
          "\""
        )
      )
    }, character(1L), USE.NAMES = FALSE)
    proyeccion[con_alias] <- paste0(
      expresiones[con_alias], " AS ", alias_dobles
    )
  }
  cambia <- money | real | doble_convertido
  salida$campos_sql <- lecturas
  salida$proyeccion_sql <- proyeccion
  salida$convertidas <- data.frame(
    columna = as.character(campos[fijo | cambia]),
    tipo_motor = tipo[fijo | cambia],
    lectura = lecturas[fijo | cambia], stringsAsFactors = FALSE
  )
  salida
}

# PostgreSQL antes de la 12, y cualquier sesion con `extra_float_digits <= 0`,
# escribe un double con pocas cifras. RPostgres lee ese texto, asi que dos
# float8 distintos pueden llegar como uno. `float8send()` permite decodificar
# los ocho bytes IEEE-754 y formar el valor exacto como `numeric`, sin residuo
# en doble y sin desbordar en los extremos. Las potencias negativas de dos no
# sirven en PostgreSQL 9.3: se dividen potencias positivas para conservar las
# cifras de los subnormales. Los no finitos se representan con sentinelas
# numericos acotados que RPostgres vuelve a leer como Inf, -Inf y NaN.
.lectura_double_postgresql_dbi <- function(columna_sql) {
  bytes <- paste0("float8send(", columna_sql, ")")
  alto <- paste0(
    "(get_byte(", bytes, ", 0)::bigint * 16777216 + ",
    "get_byte(", bytes, ", 1)::bigint * 65536 + ",
    "get_byte(", bytes, ", 2)::bigint * 256 + get_byte(", bytes, ", 3)::bigint)"
  )
  bajo <- paste0(
    "(get_byte(", bytes, ", 4)::bigint * 16777216 + ",
    "get_byte(", bytes, ", 5)::bigint * 65536 + ",
    "get_byte(", bytes, ", 6)::bigint * 256 + get_byte(", bytes, ", 7)::bigint)"
  )
  signo <- paste0("((", alto, " >> 31) & 1)")
  exponente <- paste0("((", alto, " >> 20) & 2047)")
  fraccion <- paste0("((", alto, " & 1048575) * 4294967296 + ", bajo, ")")
  absoluto <- paste0(
    "CASE WHEN ", exponente, " = 0 THEN ", fraccion,
    " / power(CAST(2 AS NUMERIC), 1074) ELSE (",
    "power(CAST(2 AS NUMERIC), 52) + ", fraccion,
    ") * CASE WHEN ", exponente, " >= 1075 THEN power(CAST(2 AS NUMERIC), ",
    exponente, " - 1075) ELSE 1 / power(CAST(2 AS NUMERIC), 1075 - ",
    exponente, ") END END"
  )
  reconstruida <- paste0(
    "(CASE WHEN ", signo, " = 1 THEN -1 ELSE 1 END * (", absoluto, "))"
  )
  paste0(
    "CASE WHEN ", columna_sql, " = CAST('NaN' AS DOUBLE PRECISION) THEN ",
    "CAST('NaN' AS NUMERIC) WHEN ", columna_sql,
    " = CAST('Infinity' AS DOUBLE PRECISION) THEN CAST('1e309' AS NUMERIC)",
    " WHEN ", columna_sql,
    " = CAST('-Infinity' AS DOUBLE PRECISION) THEN CAST('-1e309' AS NUMERIC)",
    " ELSE ", reconstruida, " END"
  )
}

# La version del servidor que publica libpq -`90325`, `160015`-, sin consultar
# al motor. `NA` si el controlador no la da.
.version_servidor_postgresql_dbi <- function(conexion) {
  informacion <- tryCatch(.info_dbi_corrida(conexion), error = function(e) NULL)
  version <- if (is.list(informacion)) informacion$server.version else NULL
  if (is.null(version) || !length(version) || is.na(version[[1L]])) {
    # Algunos controladores publican `db.version` como `16.0` en lugar del
    # entero que libpq llama `server.version` (`160000` en este caso).
    version <- if (is.list(informacion)) informacion$db.version else NULL
  }
  version <- as.character(version[1L])
  if (!length(version) || is.na(version) || !nzchar(version)) return(NA_integer_)
  entero <- if (grepl("^[0-9]+$", version)) {
    suppressWarnings(as.integer(version))
  } else NA_integer_
  if (!is.na(entero)) return(entero)
  partes <- strsplit(sub("^([0-9]+(?:\\.[0-9]+){0,2}).*$", "\\1", version),
                     "\\.", fixed = FALSE)[[1L]]
  numeros <- suppressWarnings(as.integer(partes))
  if (!length(numeros) || anyNA(numeros)) return(NA_integer_)
  menor <- if (length(numeros) >= 2L) numeros[[2L]] else 0L
  revision <- if (length(numeros) >= 3L) numeros[[3L]] else 0L
  as.integer(numeros[[1L]] * 10000L + menor * 100L + revision)
}

.extra_float_digits_postgresql_dbi <- function(conexion, presupuesto = NULL) {
  # Las conexiones que solo declaran senas de PostgreSQL (por ejemplo, un
  # adaptador de prueba sobre otro motor) no necesariamente implementan SHOW.
  # Para ellas se conserva el valor por omision de PostgreSQL 12+; RPostgres
  # si puede preguntar y, si la pregunta falla, deja la lectura exacta.
  if (!inherits(conexion, "PqConnection")) return(1L)
  # La pregunta viaja al motor y se cuenta como el resto de la preparacion: el
  # plan, que prepara igual, la anticipa con la misma cuenta.
  .contar_dbi(presupuesto)
  valor <- tryCatch(
    DBI::dbGetQuery(conexion, "SHOW extra_float_digits"),
    error = function(e) NULL
  )
  if (!is.data.frame(valor) || !ncol(valor) || !nrow(valor)) {
    return(NA_integer_)
  }
  salida <- suppressWarnings(as.integer(valor[[1L]][[1L]]))
  if (length(salida) != 1L || is.na(salida)) NA_integer_ else salida
}

# Como se lee un `real` de PostgreSQL. El texto con que el servidor lo escribe
# depende de la version y de `extra_float_digits`: desde la 12, con el valor
# por omision (1), es la forma decimal mas corta que vuelve al valor guardado
# -`21.3`-; antes de la 12 -donde el valor por omision es 0- y con
# `extra_float_digits <= 0` en cualquier version son `6 + extra_float_digits`
# cifras, y 1234501 se escribe `1.2345e+06`. Con la lectura de ese texto, en
# un 9.3, 200 enteros distintos de siete cifras salian 21 distintos, con un
# minimo 1234500 que no estaba en la columna y desvio 58,07 contra 57,88, en
# las dos puertas a la vez y sin divergencia.
#
# Por eso la forma corta se calcula en el motor y no se toma del texto de la
# sesion: el valor se redondea a 6, 7, 8 y 9 cifras significativas y se queda
# la primera que vuelve al mismo `real` -nueve alcanzan siempre; el binario,
# exacto, queda como ultima red-. No depende de `extra_float_digits` ni de la
# version, y no toca el estado de la sesion. El redondeo parte de
# `CAST(x AS DOUBLE PRECISION)` pasado a `NUMERIC`, que PostgreSQL escribe con
# 15 cifras en toda version: mas que las nueve que distinguen dos `real`.
# `0`, `NaN` y los infinitos no tienen logaritmo -y un infinito no pasa a
# `NUMERIC` antes de la 14-: se leen por el binario, que para ellos es exacto.
#
# Desde la 12 el texto de la sesion se prueba primero, porque es mas barato
# -redondear en `NUMERIC` cuesta unas nueve veces mas que leer el texto-: si
# vuelve al valor guardado es la forma corta -con el valor por omision lo es
# siempre-, y si la sesion lo acorto se redondea.
# Antes de la 12 un texto que vuelve al valor puede no ser el corto
# -`extra_float_digits = 3` escribe `21.2999992`-, asi que ahi, y si la
# version no se conoce, se redondea siempre. Las dos ramas coinciden salvo en
# un empate de la ultima cifra -3774929,25 a ocho cifras: el texto da `.2` y el
# redondeo `.3`-, y las dos vuelven al mismo `real`.
#
# PostgreSQL nombra un `CASE` como la columna de su `ELSE` cuando este la nombra:
# la proyeccion conserva el nombre, como con un `CAST`.
.lectura_real_postgresql_dbi <- function(columna_sql, version = NA_integer_) {
  binario <- paste0("CAST(", columna_sql, " AS DOUBLE PRECISION)")
  decimal <- paste0("CAST(", binario, " AS NUMERIC)")
  exponente <- paste0("FLOOR(LOG(ABS(", binario, ")))")
  ramas <- vapply(6:9, function(cifras) {
    redondeo <- paste0(
      "ROUND(", decimal, ", CAST(", cifras - 1L, " - ", exponente,
      " AS INTEGER))"
    )
    paste0(
      " WHEN CAST(", redondeo, " AS REAL) = ", columna_sql,
      " THEN CAST(", redondeo, " AS DOUBLE PRECISION)"
    )
  }, character(1))
  redondeada <- paste0(
    "CASE WHEN ", columna_sql, " IN (CAST(0 AS REAL), CAST('NaN' AS REAL), ",
    "CAST('Infinity' AS REAL), CAST('-Infinity' AS REAL)) THEN ", binario,
    paste(ramas, collapse = ""), " ELSE ", binario, " END"
  )
  if (is.na(version) || version < 120000L) return(redondeada)
  texto <- paste0("CAST(", columna_sql, " AS TEXT)")
  paste0(
    "CASE WHEN CAST(", texto, " AS REAL) = ", columna_sql,
    " THEN CAST(", texto, " AS DOUBLE PRECISION) ELSE ", redondeada, " END"
  )
}

# Si `.lectura_convertida_dbi()` convierte alguna columna en esta conexion. Se
# le pregunta a ella con el codigo comun de `char`, para que la regla de que
# conexiones convierten este escrita una sola vez. La usan las lecturas que
# tienen que pagar una consulta para saber el tipo en el motor
# (`relaciones_coleccion()`): donde nada se convierte, no se paga.
.lectura_puede_convertir_dbi <- function(conexion) {
  NROW(.lectura_convertida_dbi(
    conexion, "lupa", "\"lupa\"", "1", tipos = "char"
  )$convertidas) > 0L
}

# Lo que promete la ayuda cuando una metrica no tiene valor porque no alcanzan
# los valores, y la cuenta de los no nulos llego en la misma sentencia que la
# metrica: sin valores, `sin_valores` y "La columna no contiene valores no
# nulos." por la tabla completa, y en la muestra `no_disponible` con
# `muestra_inestable:sin_valores_validos`; el desvio con uno solo, `no_aplica`.
# Una muestra sin filas no permite concluir que la columna este vacia: queda lo
# que dijo la muestra (`muestra_vacia:<metodo>`), como cualquier otra
# declaracion de la muestra entera (`muestra_inestable:...`). Devuelve el `sql`
# con las filas de la metrica reescritas, o `NULL` si la cuenta no decide.
.estado_por_cuenta_dbi <- function(sql, filas, metrica, cuenta, muestra,
                                   total = NA_real_) {
  cuenta <- suppressWarnings(as.numeric(.numero_dbi(cuenta)))
  if (!is.finite(cuenta) || !any(filas)) return(NULL)
  if (!(cuenta < 1 || (identical(metrica, "desvio") && cuenta < 2))) {
    return(NULL)
  }
  motivos <- as.character(sql$motivo[filas])
  motivos[is.na(motivos)] <- ""
  if (muestra && (
    any(startsWith(motivos, "muestra_vacia:") |
          startsWith(motivos, "muestra_inestable:")) ||
      isTRUE(.numero_dbi(total) == 0)
  )) {
    return(NULL)
  }
  if (cuenta < 1 && muestra) {
    sql$estado[filas] <- "no_disponible"
    sql$motivo[filas] <- "muestra_inestable:sin_valores_validos"
  } else if (cuenta < 1) {
    sql$estado[filas] <- "sin_valores"
    sql$motivo[filas] <- "La columna no contiene valores no nulos."
  } else {
    sql$estado[filas] <- "no_aplica"
    sql$motivo[filas] <-
      "El desv\u00edo muestral requiere al menos dos valores no nulos."
  }
  sql
}

# Las columnas numericas sin sumas exactas -dobles, enteros, decimales que no
# las admiten- deciden con la cuenta que el lote de agregados trajo cuando no
# se pidio `validos` (ver `.agregados_lote_con_biseccion_dbi()`), y un decimal
# con sumas, con la de ellas. Solo las metricas de esa misma sentencia: los
# extremos, la media y el desvio. Con `validos` pedido decide
# `.declarar_afirmados_sin_valor_dbi()` con `n_validos`.
.valores_ausentes_por_cuenta_dbi <- function(campos, resultados, metricas,
                                             agregados,
                                             universo = "tabla_completa") {
  if (!length(agregados$cuentas) && !length(agregados$exactos)) {
    return(resultados)
  }
  muestra <- identical(universo, "muestra_motor")
  for (i in seq_along(campos)) {
    cuenta <- agregados$cuentas[[campos[[i]]]]
    # Un decimal con sumas exactas trae la cuenta en ellas: decide tambien sus
    # extremos, que salen de la misma sentencia.
    exacto <- agregados$exactos[[campos[[i]]]]
    if (is.null(cuenta) && !is.null(exacto)) {
      cuenta <- list(n = exacto$finitos, total = exacto$total)
    }
    if (is.null(cuenta)) next
    # La cuenta tiene que ser de los valores que usa la metrica, los finitos:
    # `COUNT(x)` cuenta un `NaN` o un infinito, y con `(NaN, NULL)` publicaba el
    # desvio `no_aplica` donde no hay ningun valor finito. Esas columnas ya las
    # decidio la via de los finitos, y las de magnitud sin establecer ya dicen
    # por que.
    if (isTRUE(resultados[[i]]$cuenta_no_decide)) next
    sql <- resultados[[i]]$sql
    if (!is.data.frame(sql) || !nrow(sql)) next
    for (metrica in c("minimo", "maximo", "media", "desvio")) {
      pedida <- if (identical(metrica, "desvio")) {
        "desvio" %in% metricas
      } else "basicos" %in% metricas
      if (!pedida) next
      filas <- as.character(sql$metrica) == metrica
      decidido <- .estado_por_cuenta_dbi(
        sql, filas, metrica, cuenta$n, muestra, cuenta$total
      )
      if (is.null(decidido)) next
      sql <- decidido
      if (metrica %in% names(resultados[[i]]$fila)) {
        resultados[[i]]$fila[[metrica]] <- NA_real_
      }
    }
    resultados[[i]]$sql <- sql
  }
  resultados
}

# La media y el desvio de un decimal, en el decimal, por la tabla completa y
# bajo la muestra del motor. El motor los calculaba en doble: SQL Server con
# `AVG(CAST(x AS FLOAT))`, MySQL y MariaDB con `AVG(x * 1e0)`, y el desvio,
# centrado en esa media, tambien en doble. Con valores que se cancelan la media
# no era ni la de los dobles: `999999999999999.99`, `-999999999999999.98`,
# `0.01`, `0.02`, `0.03` y `-0.04` daban 0,00333 por 0,005. Y aun sin cancelar,
# la media y el desvio quedaban a un ulp del doble mas cercano en los cinco
# motores con decimales. Las sumas exactas -la cuenta, la suma y la de los
# cuadrados, como texto- van en el mismo lote que los agregados
# (`.piezas_sumas_sin_centro_dbi()`, ver `.agregados_lote_con_biseccion_dbi()`):
# la media es el doble mas cercano de la suma dividida por la cuenta, y el
# desvio, el doble mas cercano del exacto. Aca se reemplazan los del motor, con
# cualquier `metricas`, con `incluir_valores = FALSE` y con valores de 2^53 o
# mas, cuya media y desvio de los dobles no se publican; la fila queda con el
# metodo `sumas_exactas_decimal`, que la guarda del decimal ancho respeta.
#
# Si el lote no devolvio las sumas -el presupuesto, o el motor lo rechazo y la
# columna se pidio sola-, por la tabla completa la del motor queda solo si su
# error cabe en la tolerancia de los dobles, la de una parte en mil millones
# (`.TOLERANCIA_DESVIO_DOBLE_DBI`): el desvio, con la guarda de
# `.desvio_mal_condicionado_dbi()` y sin riesgo de cancelacion, y la media, si
# `n` veces el redondeo del mayor valor no pasa de esa parte de la media.
# PostgreSQL promedia en `numeric`, sin redondear cada valor. Si no,
# `no_disponible`. Bajo la muestra del motor quedan la del motor y sus guardas,
# como antes.
.decimales_exactos_tabla_dbi <- function(conexion, campos, resultados, metricas,
                                         tipo_de, tipo_regla, agregados,
                                         universo = "tabla_completa",
                                         es_numerico = NULL) {
  if (!any(c("basicos", "desvio") %in% metricas)) return(resultados)
  senas <- .senas_conexion_dbi(conexion)
  postgres <- .postgresql_dbi(senas)
  muestra <- identical(universo, "muestra_motor")
  estado_exacto <- if (muestra) "estimado" else "calculado"
  for (i in seq_along(campos)) {
    campo <- campos[[i]]
    if (!is.null(es_numerico) && !isTRUE(es_numerico[[i]])) next
    if (!.mediana_decimal_por_centrales_dbi(senas, tipo_regla(i))) next
    exacto <- agregados$exactos[[campo]]
    fila <- resultados[[i]]$fila
    datos <- agregados$basicos[[campo]]$datos
    extremos <- if (is.data.frame(datos) && nrow(datos)) {
      suppressWarnings(as.numeric(c(
        .valor_campo_dbi(datos, "minimo")$valor,
        .valor_campo_dbi(datos, "maximo")$valor
      )))
    } else NA_real_
    extremos <- extremos[is.finite(extremos)]
    n <- suppressWarnings(as.numeric(.numero_dbi(fila$n_validos)))
    if (length(n) != 1L) n <- NA_real_
    for (metrica in c("media", "desvio")) {
      if (identical(metrica, "media") && !"basicos" %in% metricas) next
      if (identical(metrica, "desvio") && !"desvio" %in% metricas) next
      sql <- resultados[[i]]$sql
      filas <- as.character(sql$metrica) == metrica
      if (!any(filas)) next
      valor_exacto <- suppressWarnings(as.numeric(exacto[[metrica]]))
      # Las sumas llegaron y no hay valor porque no alcanzan los valores: lo
      # dice la cuenta de las sumas (`.estado_por_cuenta_dbi()`).
      # Con `NaN` o infinitos decide la via de los finitos, con su motivo: la
      # de las sumas diria "no nulos" de una columna que los tiene.
      decidido <- if (isTRUE(resultados[[i]]$cuenta_no_decide)) NULL else {
        .estado_por_cuenta_dbi(
          sql, filas, metrica, exacto$finitos, muestra, exacto$total
        )
      }
      if (!is.null(decidido)) {
        resultados[[i]]$fila[[metrica]] <- NA_real_
        resultados[[i]]$sql <- decidido
        next
      }
      if (length(valor_exacto) == 1L && is.finite(valor_exacto)) {
        resultados[[i]]$fila[[metrica]] <- valor_exacto
        sql$estado[filas] <- estado_exacto
        sql$motivo[filas] <- NA_character_
        sql$sql[filas] <- exacto$sql
        if ("metodo" %in% names(sql)) sql$metodo[filas] <- "sumas_exactas_decimal"
        resultados[[i]]$sql <- sql
        next
      }
      # Sin las sumas: el respaldo, solo por la tabla completa y solo si el
      # tipo las admitia (un decimal sin escala sigue con la del motor).
      if (muestra || !.sumas_exactas_posibles_dbi(senas, tipo_de(i))) next
      publicado <- all(as.character(sql$estado[filas]) %in%
                         c("calculado", "estimado"))
      if (!publicado) next
      valor <- suppressWarnings(as.numeric(fila[[metrica]]))
      media_motor <- suppressWarnings(as.numeric(fila$media))
      tolerado <- length(valor) == 1L && is.finite(valor) &&
        length(extremos) > 0L && if (identical(metrica, "desvio")) {
          !.desvio_mal_condicionado_dbi(valor, extremos, tipo = tipo_de(i)) &&
            !isTRUE(.riesgo_cancelacion_desvio_dbi(
              media_motor, valor, min(extremos), max(extremos),
              suppressWarnings(as.numeric(fila$n_distintos))
            ))
        } else {
          postgres || (is.finite(n) && valor != 0 &&
            max(abs(extremos)) * (n + 2) * 2^-53 / abs(valor) <=
              .TOLERANCIA_DESVIO_DOBLE_DBI)
        }
      if (tolerado) next
      resultados[[i]]$fila[[metrica]] <- NA_real_
      sql$estado[filas] <- "no_disponible"
      causa <- exacto$motivo
      if (is.null(causa) || !length(causa) || is.na(causa[[1L]])) {
        causa <- paste(
          "la consulta de los agregados no las devolvi\u00f3 (ver",
          "`meta$consultas$fallas`)."
        )
      }
      sql$motivo[filas] <- paste(
        "La media y el desv\u00edo de un decimal salen de las sumas exactas",
        "en el motor, que no llegaron:", causa[[1L]], "Los del motor, que suman",
        "en doble, pueden diferir del exacto en m\u00e1s de una parte en mil",
        "millones."
      )
      resultados[[i]]$sql <- sql
    }
  }
  resultados
}

# ---- Plan previo ---------------------------------------------------------

# Si una columna numerica pide la sonda de magnitud (`MIN`/`MAX` sueltos): sin
# `basicos`, cuando el desvio o la mediana necesitan saber la magnitud -un
# entero chico va directo-, y un decimal sin valores, que la necesita para la
# guarda de 2^53. La misma regla deciden la corrida
# (`.resumen_columna_dbi()`) y el plan: el plan las contaba para todas las
# numericas y la corrida no las pedia para los enteros chicos.
.necesita_sonda_magnitud_dbi <- function(pedidas_numericas, tipo_operacion,
                                         tipo_declarado, incluir_valores,
                                         mediana_conservada = TRUE) {
  tipo_sonda_desvio <- .minusculas_ascii(as.character(tipo_operacion))
  desvio_directo_sin_magnitud <- "desvio" %in% pedidas_numericas &&
    !("basicos" %in% pedidas_numericas) &&
    !("mediana" %in% pedidas_numericas) &&
    !.tipo_declarado_decimal_dbi(tipo_operacion) &&
    length(tipo_sonda_desvio) == 1L && !is.na(tipo_sonda_desvio) &&
    grepl(
      "^(smallint|int2|integer|int|int4|tinyint|mediumint)$",
      tipo_sonda_desvio, perl = TRUE
    )
  !("basicos" %in% pedidas_numericas) &&
    ("desvio" %in% pedidas_numericas ||
       ("mediana" %in% pedidas_numericas &&
          isTRUE(incluir_valores) && isTRUE(mediana_conservada))) &&
    !desvio_directo_sin_magnitud ||
    (.tipo_declarado_decimal_dbi(tipo_declarado) && !isTRUE(incluir_valores))
}

# Cuantas consultas de prueba de la CTE de ventanas correra la muestra sin que
# la preparacion las haya corrido (ver `plan_perfilado_dbi()`): dos por
# candidato -la prueba y su control negativo-, o cero.
.prueba_cte_mediana_plan_dbi <- function(conexion, preparacion, es_numerico,
                                        incluir_valores) {
  # Con `bloque_muestra = "con_muestra"` la mediana de la muestra sale del
  # spool, en R, y la prueba no corre.
  if (!identical(preparacion$universo, "muestra_motor") ||
      .solicita_muestra_dbi(preparacion$bloque_muestra) ||
      !"mediana" %in% preparacion$metricas_ejecucion ||
      !isTRUE(incluir_valores) || is.null(preparacion$mediana_consolidada) ||
      !is.null(preparacion$mediana_escalar) ||
      !is.null(preparacion$mediana_cte_ventana) ||
      !is.null(preparacion$aproximaciones$mediana) ||
      !is.null(preparacion$presupuesto$mediana_cte_ventana) ||
      (!is.null(preparacion$muestreo) &&
         !isTRUE(preparacion$muestreo$disponible))) {
    return(0L)
  }
  senas <- .senas_conexion_dbi(conexion)
  fuera <- vapply(seq_along(preparacion$campos), function(i) {
    isTRUE(es_numerico[[i]]) && (
      preparacion$campos[[i]] %in% preparacion$columnas_float8_numeric ||
        .mediana_decimal_por_centrales_dbi(
          senas,
          .atributo_columna_dbi(
            preparacion$tipos, preparacion$campos[[i]], i
          ) %||% NA_character_
        )
    )
  }, logical(1L))
  if (!any(fuera)) return(0L)
  2L * length(.candidatos_mediana_cte_ventana_dbi(conexion))
}

.plan_consultas_dbi <- function(campos, es_numerico, metricas, incluir_valores,
                                  con_orden, dialecto, emitidas = 0,
                                  universo = "tabla_completa",
                                  muestreo_disponible = TRUE,
                                  tamano_lote_planos = .TAMANO_LOTE_PLANOS_DBI,
                                  tamano_lote_distintos = .TAMANO_LOTE_DISTINTOS_DBI,
                                  incluir_muestra = TRUE,
                                  mediana_consolidada = FALSE,
                                  columnas_distintos = NULL,
                                  columnas_moda = NULL,
                                  columnas_moda_max = NULL,
                                  columnas_mediana = NULL,
                                  columnas_mediana_max = NULL,
                                  columnas_mediana_centrales = character(),
                                  consultas_muestra = 1L,
                                  desvio_en_lotes = FALSE,
                                  desvio_por_ventana = FALSE,
                                  lectura_muestra = FALSE,
                                  catalogo_aviso = 0L,
                                  reintento_muestreo = FALSE,
                                  consultas_decimales = 0L,
                                  consultas_decimales_max =
                                    consultas_decimales,
                                  n_sondas_magnitud = NULL,
                                  n_sondas_magnitud_max = n_sondas_magnitud) {
  n_columnas <- length(campos)
  n_numericas <- sum(es_numerico)
  con_valores <- isTRUE(incluir_valores)
  acota_con_salto <- !is.null(dialecto$limitar("SELECT 1", 1L, 1))
  n_lotes <- function(n, tamano) if (n > 0) ceiling(n / tamano) else 0
  tamanos_lotes <- function(n, tamano) {
    if (n < 1) return(numeric())
    cantidad <- n %/% tamano
    resto <- n %% tamano
    c(
      rep(tamano, cantidad),
      if (resto > 0) resto else numeric()
    )
  }
  extra_biseccion <- function(n, tamano) {
    sum(2 * tamanos_lotes(n, tamano) - 1)
  }
  columnas_planas <- if ("validos" %in% metricas) n_columnas else n_numericas
  hay_planos <- any(c("validos", "basicos", "desvio") %in% metricas) &&
    columnas_planas > 0
  mide_metricas <- !identical(universo, "muestra_motor") ||
    isTRUE(muestreo_disponible)
  n_metricas <- function(valor) if (mide_metricas) valor else 0
  n_distintos <- if (is.null(columnas_distintos)) n_columnas else {
    length(columnas_distintos)
  }
  n_moda <- if (is.null(columnas_moda)) n_columnas else length(columnas_moda)
  n_moda_max <- if (is.null(columnas_moda_max)) n_moda else {
    length(columnas_moda_max)
  }
  n_mediana <- if (is.null(columnas_mediana)) n_numericas else {
    length(columnas_mediana)
  }
  n_mediana_max <- if (is.null(columnas_mediana_max)) n_mediana else {
    length(columnas_mediana_max)
  }
  # Las medianas de decimales no entran en la consolidada: una consulta cada
  # una (ver `.mediana_decimal_por_centrales_dbi()`).
  centrales_de <- function(columnas) {
    length(intersect(
      columnas_mediana_centrales,
      if (is.null(columnas)) campos[es_numerico] else columnas
    ))
  }
  n_mediana_centrales <- centrales_de(columnas_mediana)
  n_mediana_centrales_max <- centrales_de(
    if (is.null(columnas_mediana_max)) columnas_mediana else {
      columnas_mediana_max
    }
  )
  alcance_agregado <- if (identical(universo, "muestra_motor")) {
    "lee una muestra del motor"
  } else {
    "escanea la tabla completa"
  }
  clases <- list(c(
    "portones (esquema y sondas)", emitidas, "una vez"
  ))
  # La estimacion de filas del catalogo que usa el aviso de costo de la tabla
  # completa: una lectura de metadatos que la corrida hace antes de los
  # agregados (ver `.aviso_costo_agregados_dbi()`).
  if (catalogo_aviso > 0) {
    clases[[length(clases) + 1L]] <- c(
      "estimacion de filas del catalogo (aviso de costo)", catalogo_aviso,
      "lee el catalogo"
    )
  }
  # Bajo la muestra del motor sin bloque de filas, la corrida lee la muestra
  # una vez antes de los agregados para saber si todas las columnas se pueden
  # leer.
  if (isTRUE(lectura_muestra) && mide_metricas) {
    clases[[length(clases) + 1L]] <- c(
      "lectura de comprobacion de la muestra", 1, alcance_agregado
    )
  }
  if (hay_planos) {
    n_planos <- n_lotes(columnas_planas, tamano_lote_planos)
    # Las dos consultas de la forma del desvio se pagan una vez si hay lote plano,
    # aunque ninguna columna sea numerica, y no se pagan cuando el desvio sale
    # por ventana sobre la muestra (ver `.desvio_por_ventana_dbi()`).
    if ("desvio" %in% metricas && !isTRUE(desvio_por_ventana)) {
      n_planos <- n_planos + .PEAJE_FORMA_DESVIO
    }
    if ("desvio" %in% metricas && isTRUE(desvio_en_lotes)) {
      n_planos <- n_planos + n_lotes(n_numericas, tamano_lote_planos)
    }
    clases[[length(clases) + 1L]] <- c(
      "agregados planos por lotes (COUNT + MIN/MAX/AVG/SUM CASE + desvio)",
      n_metricas(n_planos), alcance_agregado
    )
  }
  if (!hay_planos) {
    clases[[length(clases) + 1L]] <- c(
      "total exacto (COUNT)", 1, "escanea la tabla completa"
    )
  }
  if (is.null(n_sondas_magnitud)) {
    n_sondas_magnitud <- if (
      !("basicos" %in% metricas) &&
        ("desvio" %in% metricas ||
          ("mediana" %in% metricas && con_valores))
    ) n_numericas else 0
  }
  if (is.null(n_sondas_magnitud_max)) n_sondas_magnitud_max <- n_sondas_magnitud
  if (n_sondas_magnitud > 0 || n_sondas_magnitud_max > 0) {
    clases[[length(clases) + 1L]] <- c(
      "sonda de magnitud (MIN)", n_metricas(n_sondas_magnitud),
      alcance_agregado, n_metricas(n_sondas_magnitud_max)
    )
  }
  if ("distintos" %in% metricas && n_distintos > 0) {
    clases[[length(clases) + 1L]] <- c(
      "distintos por lotes (clase separada)",
      n_metricas(n_lotes(n_distintos, tamano_lote_distintos)), alcance_agregado
    )
  }
  clases <- c(
    clases,
    list(
      c(
        "moda (GROUP BY + orden + limite)",
        if ("moda" %in% metricas && con_valores) n_metricas(n_moda) else 0,
        if (identical(universo, "muestra_motor")) "lee una muestra del motor" else
          "ordena o agrupa la tabla completa",
        if ("moda" %in% metricas && con_valores) n_metricas(n_moda_max) else 0
      ),
      c(
        "mediana (orden total + limite/salto)",
        if ("mediana" %in% metricas && con_valores && acota_con_salto) {
          if (isTRUE(mediana_consolidada)) {
            n_metricas(n_lotes(
              n_mediana - n_mediana_centrales, tamano_lote_planos
            ) + n_mediana_centrales)
          } else {
            n_metricas(n_mediana)
          }
        } else 0,
        if (identical(universo, "muestra_motor")) "lee una muestra del motor" else
          "ordena la tabla completa",
        if ("mediana" %in% metricas && con_valores && acota_con_salto) {
          if (isTRUE(mediana_consolidada)) {
            n_metricas(n_lotes(
              n_mediana_max - n_mediana_centrales_max, tamano_lote_planos
            ) + n_mediana_centrales_max)
          } else {
            n_metricas(n_mediana_max)
          }
        } else 0
      ),
      c(
        "verificacion de unicidad del orden", if (con_orden) 1 else 0,
        "ordena o agrupa la tabla completa"
      ),
      c(
        "media y desvio de los decimales en el decimal",
        n_metricas(consultas_decimales), "escanea la tabla completa",
        n_metricas(consultas_decimales_max)
      )
    )
  )
  if (isTRUE(incluir_muestra)) {
    clases[[length(clases) + 1L]] <- c(
      "muestra", consultas_muestra, .ALCANCE_BLOQUE_CLIENTE_DBI
    )
  }
  plan <- data.frame(
    clase_consulta = vapply(clases, function(x) x[[1L]], character(1L)),
    n_consultas = vapply(clases, function(x) as.numeric(x[[2L]]), numeric(1L)),
    alcance = vapply(clases, function(x) x[[3L]], character(1L)),
    n_consultas_max = vapply(clases, function(x) {
      if (length(x) >= 4L) as.numeric(x[[4L]]) else as.numeric(x[[2L]])
    }, numeric(1L)),
    stringsAsFactors = FALSE
  )
  plan <- plan[plan$n_consultas > 0 | plan$n_consultas_max > 0, , drop = FALSE]
  rownames(plan) <- NULL
  # El total NO es un techo cuando el motor rechaza lotes. La biseccion vuelve a
  # sondear el grupo y puede recorrer el arbol hasta 2n - 1 nodos adicionales
  # para un lote de n columnas; las respuestas de los grupos aceptados se
  # reutilizan como resultados. Se publica el rango para declarar ese peor caso
  # sin suponer que todas las columnas individuales fallan.
  attr(plan, "extra_si_se_rechazan_lotes") <-
    n_metricas(
      (if ("distintos" %in% metricas) {
        extra_biseccion(n_distintos, tamano_lote_distintos)
      } else 0) +
      (if (hay_planos) {
        extra_biseccion(columnas_planas, tamano_lote_planos)
      } else 0)
    )
  # Una muestra `TABLESAMPLE` que vuelve con menos de la mitad de lo pedido se
  # reintenta con otra forma, y el resumen entero se vuelve a ejecutar sobre la
  # muestra nueva: el peor caso repite todas las consultas de agregados. Cuando
  # pasa depende de las paginas que el motor sortee, asi que va al extremo
  # superior y no al total.
  repetidas <- !plan$clase_consulta %in% c(
    "portones (esquema y sondas)",
    "estimacion de filas del catalogo (aviso de costo)",
    "lectura de comprobacion de la muestra", "muestra",
    "verificacion de unicidad del orden"
  )
  attr(plan, "extra_si_se_reintenta_muestreo") <- if (
    isTRUE(reintento_muestreo) && mide_metricas
  ) {
    sum(plan$n_consultas_max[repetidas])
  } else 0
  plan
}

# El plan de la via SQL -la tabla completa y la muestra del motor sin bloque de
# filas-, armado desde la preparacion. Lo piden `plan_perfilado_dbi()` y la
# corrida, que lo usa para la barra de avance y lo publica en `meta$plan`: eran
# dos llamadas a `.plan_consultas_dbi()` con argumentos distintos, y la corrida
# publicaba una cuenta que no era la del plan. Cada pregunta que cambia cuantas
# consultas se emiten se contesta con la misma funcion que usa la corrida para
# decidir (`.desvio_por_ventana_dbi()`, `.desvio_separado_dbi()`, las medianas
# que dejan la consolidada). `emitidas` son las consultas ya pagadas -o, en el
# plan, previstas- antes de los agregados.
.plan_sql_dbi <- function(conexion, preparacion, es_numerico,
                          incluir_valores, tope_muestra, emitidas,
                          catalogo_aviso = 0L,
                          decisiones_costo_resueltas = NULL) {
  # El plan no consulta la tabla para despejar la cardinalidad. Un catalogo
  # estructural ya leido puede fijar la decision; lo demas abre un rango entre
  # omitir y ejecutar la moda. La mediana queda fuera de ese criterio y la
  # corrida medira lo que la politica explicita necesite, una sola vez.
  decisiones_costo <- if (is.null(decisiones_costo_resueltas)) {
    .decisiones_costo_dbi(
      preparacion$campos,
      list(conteos = stats::setNames(
        vector("list", length(preparacion$campos)), preparacion$campos
      )),
      preparacion$politica_costo, preparacion$universo,
      fuentes_cardinalidad_costo = preparacion$fuentes_cardinalidad_costo
    )
  } else {
    decisiones_costo_resueltas
  }
  decisiones_resueltas <- !is.null(decisiones_costo_resueltas)
  columnas_moda_plan <- NULL
  columnas_moda_max <- NULL
  columnas_mediana_plan <- NULL
  columnas_mediana_max <- NULL
  if (identical(preparacion$politica_costo$nombre, "por_cardinalidad") &&
      isTRUE(incluir_valores) &&
      .METRICA_CARDINALIDAD_COSTO_DBI %in% preparacion$metricas) {
    desconocidas <- vapply(
      preparacion$fuentes_cardinalidad_costo,
      function(x) identical(x$nombre, "desconocida"), logical(1L)
    )
    if ("moda" %in% preparacion$metricas) {
      columnas_moda_plan <- preparacion$campos[
        vapply(decisiones_costo, function(x) isTRUE(x$moda), logical(1L)) &
          (decisiones_resueltas | !desconocidas)
      ]
      columnas_moda_max <- unique(c(
        columnas_moda_plan,
        if (decisiones_resueltas) character() else {
          preparacion$campos[desconocidas]
        }
      ))
    } else {
      columnas_moda_plan <- character()
      columnas_moda_max <- character()
    }
    if ("mediana" %in% preparacion$metricas) {
      columnas_mediana_plan <- preparacion$campos[
        vapply(decisiones_costo, function(x) isTRUE(x$mediana), logical(1L)) &
          (decisiones_resueltas | !desconocidas)
      ]
      columnas_mediana_plan <- intersect(
        columnas_mediana_plan, preparacion$campos[preparacion$es_numerico]
      )
      columnas_mediana_max <- unique(c(
        columnas_mediana_plan,
        preparacion$campos[desconocidas & preparacion$es_numerico]
      ))
    } else {
      columnas_mediana_plan <- character()
      columnas_mediana_max <- character()
    }
  }
  senas <- .senas_conexion_dbi(conexion)
  # Las medianas que la corrida saca de la consolidada, con las mismas dos
  # preguntas que `.resumen_tabla_dbi()`: un `float8` de PostgreSQL, que se lee
  # como NUMERIC, y un decimal, cuya mediana es la suma de sus centrales. Cada
  # una es una consulta propia (o la CTE de la muestra).
  fuera_de_consolidada <- vapply(seq_along(preparacion$campos), function(i) {
    preparacion$campos[[i]] %in% preparacion$columnas_float8_numeric ||
      .mediana_decimal_por_centrales_dbi(
        senas,
        .atributo_columna_dbi(
          preparacion$tipos, preparacion$campos[[i]], i
        ) %||% NA_character_
      )
  }, logical(1L))
  muestra_sql <- identical(preparacion$universo, "muestra_motor") &&
    !.solicita_muestra_dbi(preparacion$bloque_muestra)
  # La media y el desvio exactos de los decimales van en los lotes de
  # agregados, sin consultas de mas (ver `.decimales_exactos_tabla_dbi()`).
  lotes_decimales <- list()
  # Las sondas de magnitud, con la regla de la corrida, columna por columna.
  tipos_motor_plan <- preparacion$esquema$tipos_motor
  pedidas_plan <- intersect(preparacion$metricas_ejecucion,
                            .METRICAS_NUMERICAS_DBI)
  n_sondas_magnitud <- sum(vapply(seq_along(preparacion$campos), function(i) {
    if (!isTRUE(es_numerico[[i]])) return(FALSE)
    declarado <- .atributo_columna_dbi(
      preparacion$tipos, preparacion$campos[[i]], i
    ) %||% NA_character_
    motor <- .atributo_columna_dbi(
      tipos_motor_plan, preparacion$campos[[i]], i
    ) %||% NA_character_
    operacion <- if (length(motor) == 1L && !is.na(motor) &&
                     nzchar(as.character(motor))) motor else declarado
    conservada <- is.null(columnas_mediana_plan) ||
      preparacion$campos[[i]] %in% columnas_mediana_plan
    isTRUE(.necesita_sonda_magnitud_dbi(
      pedidas_plan, operacion, declarado, incluir_valores, conservada
    ))
  }, logical(1L)))
  # Bajo la muestra del motor, con lote de agregados, la sonda viaja en el lote
  # (ver `.agregados_lote_con_biseccion_dbi()`) y no es una consulta; solo si el
  # lote no la trae y la columna se pide sola.
  n_sondas_magnitud_max <- n_sondas_magnitud
  if (muestra_sql && any(c("validos", "basicos", "desvio") %in%
                         preparacion$metricas_ejecucion)) {
    n_sondas_magnitud <- 0
  }
  .plan_consultas_dbi(
    preparacion$campos, es_numerico, preparacion$metricas_ejecucion, incluir_valores,
    length(preparacion$orden_sql) > 0 &&
      .solicita_muestra_dbi(preparacion$bloque_muestra), preparacion$dialecto,
    emitidas = emitidas,
    universo = preparacion$universo,
    muestreo_disponible = if (is.null(preparacion$muestreo)) TRUE else
      preparacion$muestreo$disponible,
    tamano_lote_planos = preparacion$tamano_lote_planos,
    tamano_lote_distintos = preparacion$tamano_lote_distintos,
    incluir_muestra = .solicita_muestra_dbi(preparacion$bloque_muestra),
    mediana_consolidada = !is.null(preparacion$mediana_consolidada),
    columnas_distintos = preparacion$columnas_distintos_ejecucion,
    columnas_moda = columnas_moda_plan,
    columnas_moda_max = columnas_moda_max,
    columnas_mediana = columnas_mediana_plan,
    columnas_mediana_max = columnas_mediana_max,
    columnas_mediana_centrales = preparacion$campos[fuera_de_consolidada],
    consultas_muestra = if (.solicita_muestra_dbi(preparacion$bloque_muestra) &&
                            isTRUE(tope_muestra$requiere_sonda_bytes)) 2L else 1L,
    desvio_en_lotes = .desvio_separado_dbi(
      conexion, preparacion$metricas_ejecucion, preparacion$universo,
      preparacion$columnas_float8_numeric
    ),
    desvio_por_ventana = .desvio_por_ventana_dbi(
      conexion, preparacion$metricas_ejecucion, preparacion$universo
    ),
    lectura_muestra = muestra_sql,
    catalogo_aviso = catalogo_aviso,
    reintento_muestreo = muestra_sql && identical(
      .candidato_muestreo_previsto_dbi(conexion, preparacion)$tipo,
      "tablesample"
    ),
    consultas_decimales = length(lotes_decimales),
    n_sondas_magnitud = n_sondas_magnitud,
    n_sondas_magnitud_max = n_sondas_magnitud_max,
    consultas_decimales_max = .consultas_maximas_lotes_decimales_dbi(
      lotes_decimales
    )
  )
}

# El plan de la muestra del motor con bloque de filas: la corrida materializa la
# muestra una vez en un spool de la sesion y calcula todo en R, sin los
# agregados SQL que el plan contaba. Lo que manda al motor es la preparacion, la
# estimacion de bytes por fila del catalogo, el conteo del universo si la
# preparacion no lo hizo, la seleccion de la muestra -dos si un `TABLESAMPLE`
# corto se reintenta- y, al final, la preparacion del plan que publica en
# `meta$plan`, que `replan` cuenta (ver `perfilar_dbi()`).
.plan_spool_dbi <- function(conexion, tabla, preparacion, emitidas, replan,
                            conteo_en_preparacion) {
  muestreo <- preparacion$muestreo
  disponible <- !is.null(muestreo) && isTRUE(muestreo$disponible)
  catalogo <- if (is.null(.sql_catalogo_bytes_fila_dbi(
    conexion, tabla, preparacion$campos, preparacion$esquema$tipos_motor
  ))) 0 else 1
  reintento <- disponible && identical(
    .candidato_muestreo_previsto_dbi(conexion, preparacion)$tipo, "tablesample"
  )
  clases <- list(
    c("portones (esquema y sondas)", emitidas, "una vez", emitidas),
    c("estimacion de bytes por fila (catalogo)", catalogo, "lee el catalogo",
      catalogo),
    c("conteo del universo", if (isTRUE(conteo_en_preparacion)) 0 else 1,
      "escanea la tabla completa",
      if (isTRUE(conteo_en_preparacion)) 0 else 1),
    c("seleccion de la muestra (spool de la sesion)", if (disponible) 1 else 0,
      .ALCANCE_BLOQUE_CLIENTE_DBI,
      if (disponible) 1 + as.numeric(reintento) else 0),
    c("preparacion del plan publicado en meta$plan", replan, "lee el catalogo",
      replan)
  )
  plan <- data.frame(
    clase_consulta = vapply(clases, function(x) x[[1L]], character(1L)),
    n_consultas = vapply(clases, function(x) as.numeric(x[[2L]]), numeric(1L)),
    alcance = vapply(clases, function(x) x[[3L]], character(1L)),
    n_consultas_max = vapply(clases, function(x) as.numeric(x[[4L]]), numeric(1L)),
    stringsAsFactors = FALSE
  )
  plan <- plan[plan$n_consultas > 0 | plan$n_consultas_max > 0, , drop = FALSE]
  rownames(plan) <- NULL
  attr(plan, "extra_si_se_rechazan_lotes") <- 0
  attr(plan, "extra_si_se_reintenta_muestreo") <- 0
  plan
}

# La forma de muestreo que la corrida va a aceptar, para contar sus consultas.
# El plan no sondea: elige la primera candidata por las senas del motor, y en
# PostgreSQL anterior a 9.5, que no tiene `TABLESAMPLE`, la corrida la rechaza y
# usa el orden aleatorio, que no cuenta la tabla antes. Medido en 9.3: el plan
# anunciaba ese conteo y la corrida emitia una consulta menos. Solo cambia la
# cuenta; `attr(plan, "muestreo")` sigue publicando la candidata sin sondear.
.candidato_muestreo_previsto_dbi <- function(conexion, preparacion) {
  muestreo <- preparacion$muestreo
  if (is.null(muestreo) || is.null(muestreo$candidato)) return(NULL)
  candidato <- muestreo$candidato
  if (!identical(candidato$tipo, "tablesample") ||
      !grepl("postgres|pqconnection", .senas_conexion_dbi(conexion),
             useBytes = TRUE)) {
    return(candidato)
  }
  version <- .version_servidor_postgresql_dbi(conexion)
  if (is.na(version) || version >= 90500L) return(candidato)
  candidatos <- .candidatos_muestreo_dbi(
    conexion, preparacion$dialecto, preparacion$tipo_objeto
  )
  sin_tablesample <- Filter(function(x) {
    !grepl("^tablesample", as.character(x$tipo))
  }, candidatos)
  if (length(sin_tablesample)) sin_tablesample[[1L]] else NULL
}

# Cuantas consultas manda la estimacion de filas del catalogo con que la tabla
# completa decide su aviso de costo: la misma pregunta que se hace
# `.estimar_bytes_fila_muestra_dbi()` antes de mandar la suya.
.consultas_catalogo_aviso_dbi <- function(conexion, tabla, preparacion) {
  if (!identical(preparacion$universo, "tabla_completa")) return(0L)
  if (is.null(.sql_catalogo_bytes_fila_dbi(conexion, tabla))) 0L else 1L
}

# Cuantas consultas se emiten no dice cuanto cuestan. Catorce consultas sobre
# dos millones de filas son mucho mas trabajo que doscientas sobre mil, y el
# plan que solo cuenta consultas deja al usuario sin la pregunta que de verdad
# tiene: si esto tarda segundos, minutos u horas.
#
# La magnitud se estima en dos numeros que son cuentas de verdad y no indices
# inventados: cuantas filas hay que leer, y cuantas veces hay que ordenar la
# tabla entera. El peso de cada clase sale de su `alcance`, que es vocabulario
# cerrado -lo escribe `.plan_consultas_dbi()` y nadie mas-.
.lecturas_clase_dbi <- function(alcance, n_consultas, filas, muestra) {
  switch(
    alcance,
    # Los portones son un punado de consultas triviales mas un COUNT(*), que si
    # recorre la tabla: se cuenta esa pasada y no el resto.
    "una vez" = filas,
    "escanea la tabla completa" = n_consultas * filas,
    "escanea la tabla completa dos veces" = 2 * n_consultas * filas,
    "ordena la tabla completa" = n_consultas * filas,
    "ordena o agrupa la tabla completa" = n_consultas * filas,
    # `muestra` llega SIEMPRE finita: el unico que llama es `.trabajo_plan_dbi()`,
    # que traduce ahi el `Inf` -toda la tabla- a `filas` antes de bajar hasta
    # aca. Hubo un tiempo en que esta linea intentaba traducirlo tambien, con un
    # `if (is.finite(muestra)) muestra else filas`; la rama `else` nunca corria
    # porque la normalizacion de arriba ya habia cerrado el valor, y el
    # comentario que la acompanaba afirmaba una traduccion que no ocurria. Dos
    # sitios que dicen hacer lo mismo y uno que no se ejecuta es peor que uno
    # solo: la traduccion vive arriba y aca se cuenta lo que llego.
    "lee una muestra del motor" = n_consultas * muestra,
    "lee las filas pedidas" = muestra,
    # Las lecturas de catalogo y de metadatos -la estimacion de filas del aviso
    # de costo, la preparacion que la corrida repite para publicar su plan- no
    # recorren la tabla.
    "lee el catalogo" = 0,
    NA_real_
  )
}

.UMBRAL_TRABAJO_MEDIO_DBI <- 1e7
.UMBRAL_TRABAJO_ALTO_DBI <- 1e9

# El otro medio del reloj. Lo de arriba cuenta el trabajo del MOTOR; el
# detector de vocabulario y las comparaciones de proximidad se hacen en R,
# sobre la muestra, y no aparecen en ninguna lectura de fila. Una tabla de
# 3.912 filas con una columna de geometria en texto salia "baja" -64.592
# lecturas- y tardaba 35 segundos: cada numero que informaba era cierto y el
# juicio era falso, porque medir la mitad y llamarlo el total es informar como
# completo algo parcial.
#
# La unidad es el par de formas comparadas, que es una cuenta y no un indice:
# la muestra trae m filas, las formas distintas son a lo sumo m, y el detector
# nunca compara mas de `max_pares` por columna. Cuanto cuesta cada par depende
# del largo de los valores, que el plan no puede saber sin leerlos; el supuesto
# queda declarado igual que el de `log2(filas)`.
.UMBRAL_PARES_MEDIO_DBI <- 2e6
.UMBRAL_PARES_ALTO_DBI <- 2e8

# Los alcances que traen filas a R. Vocabulario cerrado: lo escribe
# `.plan_consultas_dbi()` y nadie mas.
# Los dos alcances que involucran una muestra, que NO son la misma cosa:
# `"lee una muestra del motor"` es trabajo del motor -cuando
# `universo = "muestra_motor"`, el motor muestrea para sus propios agregados- y
# `"lee las filas pedidas"` es
# el bloque del cliente, que es lo unico que trae filas a R.
.ALCANCES_CON_MUESTRA_DBI <- c("lee una muestra del motor", "lee las filas pedidas")

# El trabajo del CLIENTE cuelga solo del segundo. Contarlo sobre el conjunto de
# los dos hacia que `universo = "muestra_motor"` con `bloque_muestra = "solo_agregados"`
# declarara cuatro millones de pares de formas a comparar en R sin traer una sola
# fila, y el plan impreso se contradecia a dos lineas: "el plan incluye solo
# agregados SQL" y despues "mas 4.000.000 pares de formas a comparar en R".
.ALCANCE_BLOQUE_CLIENTE_DBI <- "lee las filas pedidas"

# El tope de pares se lee de la firma del detector en vez de copiarse: si el
# valor cambia alla, el plan no se queda estimando contra un numero viejo.
.max_pares_vocabulario_dbi <- function() {
  as.numeric(eval(formals(.grupos_casi_duplicados_vocabulario)$max_pares))
}

.ORDEN_MAGNITUD_DBI <- c("baja", "media", "alta")

.mayor_magnitud_dbi <- function(a, b) {
  pos_a <- match(a, .ORDEN_MAGNITUD_DBI)
  pos_b <- match(b, .ORDEN_MAGNITUD_DBI)
  if (is.na(pos_a) || is.na(pos_b)) return("desconocida")
  .ORDEN_MAGNITUD_DBI[[max(pos_a, pos_b)]]
}

.trabajo_plan_dbi <- function(plan, filas, muestra, columnas_texto = 0,
                              max_pares = NULL) {
  vacio <- list(
    filas_leidas = NA_real_, ordenaciones = NA_real_,
    equivalente = NA_real_, magnitud = "desconocida",
    magnitud_motor = "desconocida", magnitud_texto = "desconocida",
    columnas_texto = NA_real_, pares_texto = NA_real_
  )
  # El conteo se convierte primero y se valida despues, en vez de exigir
  # `is.numeric()`: sobre una tabla grande `n_total` llega como `integer64`, y
  # `is.numeric()` da FALSE para esa clase. Rechazarla habria dejado sin
  # estimacion justo el caso donde mas importa.
  #
  # Cada guarda esta por un caso que se probo y fallaba: `Inf` hacia NaN al
  # multiplicar por cero ordenaciones y reventaba el `if`; un conteo negativo
  # daba magnitud "baja" con lecturas negativas; y un conteo no numerico
  # emitia un aviso de coercion antes de rendirse.
  numero <- function(x) {
    if (is.null(x) || length(x) != 1L) return(NA_real_)
    valor <- suppressWarnings(as.numeric(x))
    if (length(valor) != 1L || is.na(valor) || !is.finite(valor) ||
        valor < 0) {
      return(NA_real_)
    }
    valor
  }
  filas <- numero(filas)
  if (!nrow(plan)) return(vacio)
  muestra_entera <- is.numeric(muestra) && length(muestra) == 1L &&
    !is.na(muestra) && is.infinite(muestra) && muestra > 0
  if (is.na(filas)) {
    # Aunque el tamano de la tabla sea desconocido, una muestra finita pedida
    # por el usuario acota el trabajo que ocurrira en R. La mitad del motor
    # sigue desconocida; no se convierte esa incertidumbre en cero.
    n_texto <- numero(columnas_texto)
    if (is.na(n_texto)) n_texto <- 0
    muestra_numero <- numero(muestra)
    if (is.na(muestra_numero) && muestra_entera) muestra_numero <- NA_real_
    max_pares_numero <- if (is.null(max_pares)) {
      .max_pares_vocabulario_dbi()
    } else numero(max_pares)
    if (is.na(max_pares_numero)) max_pares_numero <- Inf
    hay_bloque_cliente <- any(plan$alcance %in% .ALCANCE_BLOQUE_CLIENTE_DBI)
    pares <- if (!hay_bloque_cliente) {
      0
    } else if (is.finite(muestra_numero)) {
      n_texto * min(muestra_numero * (muestra_numero - 1) / 2,
                    max_pares_numero)
    } else {
      NA_real_
    }
    if (!is.na(pares) && is.finite(pares)) {
      magnitud_texto <- if (pares < .UMBRAL_PARES_MEDIO_DBI) {
        "baja"
      } else if (pares < .UMBRAL_PARES_ALTO_DBI) {
        "media"
      } else {
        "alta"
      }
    } else {
      magnitud_texto <- "desconocida"
    }
    vacio$columnas_texto <- n_texto
    vacio$pares_texto <- pares
    vacio$magnitud_texto <- magnitud_texto
    return(vacio)
  }
  # `muestra = Inf` no es un valor invalido: es "la tabla entera", y es el valor
  # por omision. `numero()` rechaza lo no finito -- bien para `filas` y para los
  # conteos, que con `Inf` hacian NaN --, asi que aca hay que traducirlo antes de
  # perderlo. Sin esta linea el plan contaba el bloque de muestra como CERO filas
  # leidas y CERO pares de formas: `muestra = Inf` declaraba menos trabajo que
  # `muestra = filas` pidiendo exactamente las mismas filas, y caia en magnitud
  # "baja", que es la que no imprime palancas. Medido sobre 200.000 x 4:
  # 400.000 lecturas y 0 pares contra 600.000 y 4.000.000.
  muestra <- numero(muestra)
  if (is.na(muestra)) muestra <- if (muestra_entera) filas else 0
  # Y se acota una sola vez, aca, por el mismo motivo. Pedir mas filas de las
  # que hay no trae mas filas: la lectura real es `min(n_total, muestra)`. Sin
  # este tope, `muestra = 1e6` sobre una tabla de 100 filas declaraba 1.001.200
  # lecturas contra las 1.300 de `muestra = 100`, trayendo las dos las mismas
  # 100 filas. El lado del cliente ya se acotaba -por eso `pares_texto` daba
  # bien-, o sea que las dos mitades de la cuenta usaban tamanos distintos.
  muestra <- min(filas, muestra)
  lecturas <- vapply(seq_len(nrow(plan)), function(i) {
    suppressWarnings(as.numeric(.lecturas_clase_dbi(
      plan$alcance[[i]], plan$n_consultas[[i]], filas, muestra
    )))
  }, numeric(1L))
  if (anyNA(lecturas) || any(!is.finite(lecturas))) return(vacio)
  ordena <- grepl("^ordena", plan$alcance)
  ordenaciones <- sum(plan$n_consultas[ordena])
  # Ordenar no cuesta lo mismo que recorrer: una ordenacion completa se cuenta
  # como log2(filas) pasadas. Es el supuesto de libro y queda declarado, para
  # que quien no lo comparta pueda rehacer la cuenta con los dos numeros de
  # arriba, que no dependen de el.
  factor_orden <- max(1, log2(max(2, filas)))
  equivalente <- sum(lecturas) + ordenaciones * filas * (factor_orden - 1)
  if (!is.finite(equivalente)) return(vacio)
  magnitud_motor <- if (equivalente < .UMBRAL_TRABAJO_MEDIO_DBI) {
    "baja"
  } else if (equivalente < .UMBRAL_TRABAJO_ALTO_DBI) {
    "media"
  } else {
    "alta"
  }
  # El trabajo por valor solo existe si algo se trae a R, y por eso se pregunta
  # por el alcance de las consultas y no por una etiqueta de preset. `metricas`
  # selecciona SQL; `bloque_muestra` decide aparte si el plan trae filas. Cuando ese bloque
  # se omite no hay pares de formas que contar, aunque haya columnas de texto.
  n_texto <- numero(columnas_texto)
  if (is.na(n_texto)) n_texto <- 0
  if (is.null(max_pares)) max_pares <- .max_pares_vocabulario_dbi()
  tope_pares <- numero(max_pares)
  if (is.na(tope_pares)) tope_pares <- Inf
  filas_muestra <- if (any(plan$alcance %in% .ALCANCE_BLOQUE_CLIENTE_DBI)) {
    min(filas, muestra)
  } else {
    0
  }
  pares_texto <- n_texto * min(filas_muestra * (filas_muestra - 1) / 2, tope_pares)
  if (!is.finite(pares_texto)) pares_texto <- 0
  magnitud_texto <- if (pares_texto < .UMBRAL_PARES_MEDIO_DBI) {
    "baja"
  } else if (pares_texto < .UMBRAL_PARES_ALTO_DBI) {
    "media"
  } else {
    "alta"
  }
  list(
    filas_leidas = sum(lecturas), ordenaciones = ordenaciones,
    equivalente = equivalente,
    magnitud = .mayor_magnitud_dbi(magnitud_motor, magnitud_texto),
    magnitud_motor = magnitud_motor, magnitud_texto = magnitud_texto,
    columnas_texto = n_texto, pares_texto = pares_texto
  )
}

.SUPUESTO_TRABAJO_DBI <- paste(
  "El trabajo es una estimaci\u00f3n, no una medici\u00f3n, y son dos",
  "mitades. La del motor cuenta cu\u00e1ntas filas habr\u00eda que leer si",
  "ning\u00fan \u00edndice ayudara, y cuenta cada ordenaci\u00f3n completa",
  "como log2(filas) pasadas; un \u00edndice sobre la columna ordenada, o una",
  "tabla que entra en la memoria del motor, la bajan mucho. La del cliente",
  "cuenta los pares de formas que el detector de vocabulario podr\u00eda",
  "comparar en R sobre la muestra: como mucho `max_pares` por columna de",
  "texto. El conteo de pares es exacto; lo que el plan no puede saber sin",
  "leer los valores es cu\u00e1nto cuesta cada uno, que depende de su largo,",
  "as\u00ed que con valores muy largos el tiempo real es varias veces el que",
  "sugiere la referencia. Referencias: unos cinco millones de lecturas de fila",
  "por segundo sobre PostgreSQL 16 local (2.000.000 de filas por 40 columnas en",
  "metricas = c('validos', 'basicos', 'desvio'): 14 consultas, 5,3 segundos). Ese cociente est\u00e1 en las",
  "unidades que cuenta este plan y proviene de otras corridas, no es el tiempo",
  "de esta tabla.",
  "No representa filas que el motor haya le\u00eddo: la",
  "cuenta supone que ning\u00fan \u00edndice ayuda y cobra el desv\u00edo como",
  "dos pasadas, aunque un motor con desv\u00edo nativo lo resuelva en una. Sirve",
  "para convertir `filas_leidas` en segundos, que es para lo que est\u00e1, y no",
  "como medida de lo que el motor lee. Y de 660.000 a 1.150.000 pares por",
  "segundo sobre valores de cuarenta caracteres -la banda cubre dos m\u00e1quinas",
  "distintas-, que bajan a entre 70.000 y 80.000 sobre valores de doscientos.",
  "Esa tasa",
  "cuenta los pares que se comparan de verdad: con valores largos el detector",
  "recorta por `max_trabajo`, y dividir por los pares que el plan contar\u00eda",
  "inflaba la cifra cuatro veces."
)

.SUPUESTO_COSTO_DISTINTOS_PLAN_DBI <- paste(
  "El plan no proyecta el costo temporal de `COUNT(DISTINCT)` antes de",
  "correr: la \u00fanica referencia honesta es el primer lote de distintos medido",
  "en esta corrida, y el plan no emite consultas de datos."
)

.MOTIVO_MEMORIA_PROCESAMIENTO_DBI <- paste(
  "no escala de forma predecible con las filas ni con las celdas; se midi\u00f3."
)

.REFERENCIAS_MEMORIA_PROCESAMIENTO_DBI <- list(
  traer = "~0,13 GB por mill\u00f3n de filas",
  procesar = "~1,0-1,5 MB por cada mil filas",
  variacion = "1,62x entre tablas de la misma magnitud"
)

.celdas_plan_dbi <- function(filas, columnas) {
  valores <- vapply(list(filas, columnas), function(x) {
    if (is.null(x) || length(x) != 1L || is.na(x)) return(NA_real_)
    suppressWarnings(as.numeric(x))
  }, numeric(1L))
  if (anyNA(valores) || any(!is.finite(valores)) || any(valores < 0)) {
    return(NA_real_)
  }
  celdas <- valores[[1L]] * valores[[2L]]
  if (!is.finite(celdas)) NA_real_ else celdas
}

.memoria_procesamiento_plan_dbi <- function(filas, celdas, pares_texto) {
  list(
    estado = "no_estimada",
    estimada = FALSE,
    motivo = .MOTIVO_MEMORIA_PROCESAMIENTO_DBI,
    magnitud = list(
      filas = filas,
      celdas = celdas,
      pares_texto = pares_texto
    ),
    referencias = .REFERENCIAS_MEMORIA_PROCESAMIENTO_DBI,
    distincion = paste(
      "Ver todas las filas y tener todas las filas en memoria no son lo mismo."
    ),
    reparto_observado = paste(
      "En corridas de referencia, 4,5 M de filas entraron en 0,6 GB y tardaron",
      "25 s; procesar 4,5 M requiri\u00f3 aproximadamente 7 GB y 12,8 M",
      "aproximadamente 19 GB. El problema observado est\u00e1 en el procesamiento",
      "en R, no en la red ni en el motor."
    )
  )
}

.filas_plan_dbi <- function(preparacion) {
  vacio <- .denominador_catalogo_vacio_dbi(paste(
    "No hay una estimaci\u00f3n utilizable de filas en el cat\u00e1logo ya le\u00eddo;",
    "se conserva `sin dato filas`."
  ))
  estimacion <- preparacion$estimacion_derrame
  filas_catalogo <- if (is.null(estimacion)) NULL else {
    estimacion$filas_catalogo
  }
  if (is.list(filas_catalogo) && isTRUE(filas_catalogo$disponible)) {
    return(filas_catalogo)
  }
  if (is.list(filas_catalogo) && !is.null(filas_catalogo$motivo) &&
      length(filas_catalogo$motivo) == 1L &&
      !is.na(filas_catalogo$motivo) && nzchar(filas_catalogo$motivo)) {
    vacio$motivo <- if (grepl("sin dato filas", filas_catalogo$motivo,
                              fixed = TRUE, useBytes = TRUE)) {
      filas_catalogo$motivo
    } else {
      paste(filas_catalogo$motivo, "Se conserva `sin dato filas`.")
    }
  }
  # `estrategia = "catalogo"` ya trae el mismo denominador en cada estimacion
  # de columna. Se reutiliza ese valor y se exige que no haya dos universos en
  # la misma respuesta, igual que en `.seleccionar_fila_catalogo_dbi()`.
  estrategia <- preparacion$estrategia_distintos
  estimaciones <- if (is.null(estrategia)) NULL else estrategia$estimaciones
  if (identical(estrategia$estado, "estimado_catalogo") &&
      is.list(estimaciones) && length(estimaciones)) {
    filas <- vapply(estimaciones, function(x) {
      if (!is.list(x)) return(NA_real_)
      .numero_dbi(x$n_filas)
    }, numeric(1L))
    filas <- filas[is.finite(filas) & filas > 0]
    if (length(filas) && length(unique(filas)) == 1L) {
      return(list(
        disponible = TRUE, estado = "estimado_catalogo", filas = filas[[1L]],
        fuente = "pg_class.reltuples", n_relaciones = NA_integer_,
        motivo = paste(
          "Las filas se toman de `pg_class.reltuples` a traves de la",
          "jerarqu\u00eda que ya ley\u00f3 la estrategia `catalogo`. Es una estimaci\u00f3n",
          "de cat\u00e1logo, no una medici\u00f3n del universo de la tabla."
        )
      ))
    }
  }
  vacio
}

.proyeccion_plan_vacia_dbi <- function(motivo, unidad) {
  list(
    disponible = FALSE, estado = "no_disponible", unidad = unidad,
    magnitud = NA_real_, filas = NA_real_, n_columnas = 0L,
    n_medianas = 0L, n_distintos_proyectados = NA_real_,
    fuente = NA_character_, motivo = motivo
  )
}

.proyecciones_plan_catalogo_dbi <- function(
    preparacion, filas_plan, incluir_valores = TRUE) {
  motivo_filas <- filas_plan$motivo
  vacia_moda <- .proyeccion_plan_vacia_dbi(
    motivo_filas, "n_distintos_estimados"
  )
  vacia_mediana <- .proyeccion_plan_vacia_dbi(motivo_filas, "filas_estimadas")
  if (!isTRUE(filas_plan$disponible)) {
    return(list(moda = vacia_moda, mediana = vacia_mediana))
  }
  fuente <- "estimaci\u00f3n de cat\u00e1logo: pg_class.reltuples"
  if ("moda" %in% preparacion$metricas_ejecucion &&
      isTRUE(incluir_valores)) {
    datos <- preparacion$estimacion_derrame$columnas
    if ((!is.data.frame(datos) || !nrow(datos)) &&
        is.list(preparacion$fuentes_cardinalidad_costo)) {
      fuentes <- preparacion$fuentes_cardinalidad_costo
      datos <- data.frame(
        columna = names(fuentes),
        n_distintos_estimados = vapply(
          fuentes,
          function(fuente) {
            if (!is.list(fuente)) {
              return(NA_real_)
            }
            .numero_dbi(fuente$n_distintos)
          },
          numeric(1L)
        ),
        stringsAsFactors = FALSE
      )
    }
    if (is.data.frame(datos) && all(c(
      "columna", "n_distintos_estimados"
    ) %in% names(datos))) {
      columnas <- preparacion$campos
      datos <- datos[.indice_nombre(columnas, datos$columna), , drop = FALSE]
      conocidos <- is.finite(datos$n_distintos_estimados) &
        datos$n_distintos_estimados >= 0
      if (any(conocidos)) {
        n_distintos <- sum(datos$n_distintos_estimados[conocidos])
        if (is.finite(n_distintos)) {
          vacia_moda <- list(
            disponible = TRUE, estado = "estimado_catalogo",
            unidad = "n_distintos_estimados", magnitud = n_distintos,
            filas = filas_plan$filas,
            n_columnas = as.integer(sum(conocidos)), n_medianas = 0L,
            n_distintos_proyectados = n_distintos,
            fuente = paste(
              "estimaci\u00f3n de cat\u00e1logo:",
              "pg_stats.n_distinct + pg_class.reltuples"
            ),
            motivo = paste(
              "La magnitud de moda usa la suma de `n_distintos` estimados",
              "por el cat\u00e1logo; no es una duraci\u00f3n ni una medici\u00f3n. Las",
              "columnas sin estad\u00edstica quedan fuera de esta proyecci\u00f3n."
            )
          )
        }
      }
    }
  } else {
    vacia_moda$estado <- "no_solicitado"
    vacia_moda$motivo <- "La moda no se solicit\u00f3 en este plan."
  }
  if ("mediana" %in% preparacion$metricas_ejecucion &&
      isTRUE(incluir_valores)) {
    n_medianas <- sum(preparacion$es_numerico)
    magnitud <- filas_plan$filas * n_medianas
    if (n_medianas > 0 && is.finite(magnitud)) {
      vacia_mediana <- list(
        disponible = TRUE, estado = "estimado_catalogo",
        unidad = "filas_estimadas", magnitud = magnitud,
        filas = filas_plan$filas, n_columnas = 0L,
        n_medianas = as.integer(n_medianas),
        n_distintos_proyectados = NA_real_, fuente = fuente,
        motivo = paste(
          "La magnitud de mediana usa las filas estimadas por",
          "`pg_class.reltuples`; no es una duraci\u00f3n ni una medici\u00f3n."
        )
      )
    }
  } else {
    vacia_mediana$estado <- "no_solicitado"
    vacia_mediana$motivo <- "La mediana no se solicit\u00f3 en este plan."
  }
  list(moda = vacia_moda, mediana = vacia_mediana)
}

.texto_filas_plan_dbi <- function(filas, fuente = NULL) {
  numero <- .numero_dbi(filas)
  if (length(numero) != 1L || is.na(numero) || !is.finite(numero)) {
    return("sin dato filas")
  }
  texto <- .miles_dbi(numero)
  if (!is.null(fuente) && length(fuente) && !is.na(fuente) &&
      grepl("pg_class\\.reltuples", fuente, fixed = FALSE)) {
    paste0("~", texto, if (numero == 1L) " fila (estimaci\u00f3n de cat\u00e1logo)" else " filas (estimaci\u00f3n de cat\u00e1logo)")
  } else {
    paste0(texto, if (numero == 1L) " fila" else " filas")
  }
}


#' Planificar el costo de `perfilar_dbi()` antes de pagarlo
#'
#' Emite sólo consultas de preparación —leer el esquema y sondear capacidades—
#' y devuelve cuántas consultas emitiría el perfilado completo, de qué clase y
#' con qué alcance sobre la tabla. No escanea datos para decidir el costo.
#' Cuando `politica_costo = "por_cardinalidad"`, una clave estructural exacta
#' puede cerrar la decisión; si no hay una fuente de catálogo utilizable, el
#' plan publica el rango entre omitir y ejecutar la moda; la mediana no entra en
#' ese criterio proporcional. Nunca lanza `COUNT(DISTINCT ...)` para despejar
#' esa incertidumbre.
#' Las fuentes estructurales se resuelven cuando la política necesita la
#' cardinalidad, aunque `estrategia_distintos` no permita medirla. La
#' disponibilidad de la estrategia gobierna la medición, no el conocimiento que
#' ya da el catálogo.
#' Para el `COUNT(DISTINCT)` exacto, la preparación puede consultar además las
#' estadísticas de PostgreSQL (`pg_stats`, `pg_class.reltuples`, `SHOW work_mem`
#' y, desde PostgreSQL 13, `SHOW hash_mem_multiplier`) para estimar el tamaño
#' del hash y avisar un posible derrame. Esa consulta de metadatos no publica
#' cardinalidad medida ni reemplaza la medición posterior.
#' Para la moda y la mediana se publican, además, los atributos
#' `estimacion_derrame_moda` y `estimacion_derrame_mediana`. La moda deriva su
#' `metodo` (`"hash"` o `"sort"`) del primer `Aggregate` de un
#' `EXPLAIN (FORMAT JSON, COSTS OFF)` de la consulta exacta, sin `ANALYZE` ni
#' lectura de datos. La mediana siempre modela un sort y distingue su huella de
#' decisión de la magnitud del tape. Ambas usan `n_validos` de catálogo en el
#' plan, pisos de 32 bytes para tipos fijos y 42 para `numeric`, y dejan el
#' objeto como `no_disponible` cuando el catálogo o el motor no permiten una
#' estimación.
#' Cuando esa lectura de catálogo trae `pg_class.reltuples` positivo, el plan lo
#' reutiliza como una estimación declarada del número de filas. La magnitud y las
#' proyecciones de trabajo de moda y mediana quedan entonces disponibles y dicen
#' explícitamente `estimado_catalogo`; no son duraciones ni mediciones. Un valor
#' cero o negativo —típico de una relación sin `ANALYZE`— conserva el estado
#' `sin dato filas`. Los demás motores conservan ese estado si no tienen una
#' lectura de catálogo ya disponible.
#'
#' `estrategia_distintos` declara la procedencia de `n_distintos` antes de la
#' corrida y conserva por separado lo pedido, lo resuelto y el estado. No hay
#' `auto`: `"exacta"` es el valor por omisión, `"aproximada_motor"` queda
#' `no_disponible` si el motor no ofrece una función aceptada, `"catalogo"`
#' lee `pg_stats.n_distinct` en PostgreSQL y publica una estimación con estado
#' `estimado_catalogo` cuando `universo = "tabla_completa"`, y `"omitida"` no
#' emite el agregado. Con `universo = "muestra_motor"`, `catalogo` queda
#' `no_disponible`: sus estadísticas describen la relación entera y no el
#' subconjunto de la corrida.
#' Un `n_distinct`
#' positivo es un conteo y uno negativo una fracción de las filas. Si la
#' relación tiene descendientes se usa la fila `inherited = TRUE`, que describe
#' la consulta sin `ONLY`; si no tiene hijas se usa la única fila propia. La
#' fracción se convierte con la suma de `pg_class.reltuples` de la jerarquía.
#' Si falta una estimación utilizable —por ejemplo, antes de `ANALYZE`— o hay
#' filas ambiguas, se conserva `no_disponible`, nunca cero.
#' `fuente_cardinalidad_costo` sigue siendo independiente y sólo describe el
#' número usado por la política de costo cuando esa política se pide.
#'
#' El plan previo no proyecta segundos para `COUNT(DISTINCT)`: no lee los datos
#' y, por tanto, no tiene una referencia medida. La única referencia honesta es
#' el primer lote de distintos de la corrida, pero obtenerla cuesta una
#' consulta que este planificador no emite. Durante `perfilar_dbi()`, cuando hay
#' más de un lote y la instrumentación está activa, esa primera medición se
#' multiplica por la cantidad de lotes y se publica en
#' `resumen_tabla$meta$costo_distintos`. El aviso temporal llega después del
#' primer lote y antes del segundo; con un solo lote se declara que no hay nada
#' que proyectar.
#'
#' La memoria del procesamiento no se estima: no escala de forma predecible con
#' las filas ni con las celdas, y eso se midió. El atributo
#' `memoria_procesamiento` conserva esa declaración, la magnitud conocida del
#' trabajo (`filas`, `celdas` y `pares_texto`) y referencias medidas de otras
#' corridas. Esas referencias no son una predicción para la tabla del plan:
#' traer costó aproximadamente 0,13 GB por millón de filas y procesar en R
#' aproximadamente 1,0-1,5 MB por cada mil filas, pero esta segunda cifra varió
#' 1,62x entre tablas de la misma magnitud.
#'
#' Ver todas las filas y tener todas las filas en memoria no son lo mismo. En
#' corridas de referencia, 4,5 millones de filas entraron en 0,6 GB y tardaron
#' 25 segundos, mientras que procesar 4,5 millones ocupó aproximadamente 7 GB
#' y procesar 12,8 millones aproximadamente 19 GB. El problema observado está
#' en el procesamiento en R, no en la red ni en el motor.
#'
#' Para `universo = "muestra_motor"`, el plan declara una única selección que
#' se pagará para cerrar el spool externo de sesión cliente. `attr(plan,
#' "materializacion")` publica `pagado = FALSE`, backend, versión, presupuesto,
#' result set, fetches esperados, filas y bytes; `attr(plan, "pasadas")` declara
#' que valor, índice y LSH leerán el mismo spool. La referencia medida para
#' justificar este costo es PostgreSQL 16, 2 millones de filas: 10.000, 100.000
#' y 500.000 filas dieron 0,448/1,684/5,598 s con spool frente a
#' 0,814/2,178/3,265 s reordenando cada pasada; el cruce está entre 100.000 y
#' 500.000, y la elección prioriza identidad.
#' Con el bloque de filas, esa vía no corre los agregados SQL de la muestra: el
#' plan cuenta la preparación, la estimación de bytes por fila del catálogo, el
#' conteo del universo cuando la preparación no lo hace, la selección de la
#' muestra —dos en el extremo superior, si un `TABLESAMPLE` corto se reintenta—
#' y la preparación que la corrida repite para publicar su plan en
#' `meta$plan`.
#'
#' @inheritParams perfilar_dbi
#' @param bloque_filas Entero positivo que activa la fuente por
#'   bloques de `tabla_completa`. Cada bloque se obtiene con un unico result
#'   set (`dbSendQuery()` + `dbFetch(n = bloque_filas)`) y se absorbe antes de
#'   liberar la entrada. `NULL` conserva el plan historico. El plan publica la
#'   proyeccion, el orden, los bloques previstos y el costo declarado sin leer
#'   las filas. Cuenta la preparación, las pruebas de la fuente, el recorrido, la
#'   segunda pasada del localizador, la moda exacta de binarios y decimales
#'   anchos, la media de los decimales en el decimal y la lectura de
#'   `perfil_muestra`; la mediana de un decimal cuyas centrales son dobles
#'   distintos, su desvío centrado y la moda de un entero leído como doble los
#'   piden los datos y van al extremo superior.
#' @param instrumentar En el plan, si es `TRUE`, cronometra las consultas de
#'   preparación. No habilita consultas de datos ni agrega mediciones al objeto
#'   devuelto: sus costos siguen siendo predicciones. Por omisión es `FALSE`.
#'
#' @return Data frame de clase `plan_perfilado_dbi` con `clase_consulta`,
#'   `n_consultas`, `n_consultas_max` y `alcance`, y los atributos `total`,
#'   `total_minimo`, `total_maximo`, `total_lotes_rechazados`, `columnas`,
#'   `columnas_numericas`, `dialecto`, `consultas_emitidas`, `metricas`,
#'   `metricas_ejecucion`, `politica_costo`, `estrategia_distintos`,
#'   `fuente_cardinalidad_costo`, `moda_guardian`, `mediana_consolidada`, `filas`,
#'   `filas_fuente`, `estimacion_filas`, `proyecciones`, `mediana_escalar`,
#'   `tamano_lote_planos`, `tamano_lote_distintos`, `estimacion_derrame`,
#'   `estimacion_derrame_moda`, `estimacion_derrame_mediana`,
#'   `celdas`, `memoria_procesamiento`, `max_celdas_muestra`,
#'   `max_bytes_muestra`, `tope_muestra` y `muestreo`, y,
#'   cuando se pide `distintos`, `supuesto_costo_distintos`.
#'   `memoria_procesamiento` siempre tiene `estado = "no_estimada"`: no es una
#'   estimación de consumo, sino la declaración de su ausencia, el motivo, la
#'   magnitud del trabajo y referencias medidas de otras corridas. El atributo
#'   `estimacion_derrame` es independiente: sólo describe la estimación del hash
#'   en el motor para `COUNT(DISTINCT)` y no la memoria del procesamiento en R.
#'   `estimacion_derrame_moda` y `estimacion_derrame_mediana` describen,
#'   respectivamente, el nodo real de la moda y el sort de la mediana. Sus
#'   lotes deciden por el máximo de columna; en una mediana consolidada,
#'   `estado_io_total_bytes` es sólo la suma informativa de los tapes.
#'   `muestreo` declara si la forma muestreada se pudo construir sin emitir una
#'   consulta de datos. En `universo = "muestra_motor"`, cuando su `estado` es
#'   `"no_disponible"`, el plan excluye las métricas SQL de esa muestra y
#'   `supuesto` conserva el motivo.
#'   Cuando se pide `bloque_muestra = "solo_agregados"`, también conserva ese
#'   valor en el atributo `bloque_muestra` y no incluye la fila de la lectura de
#'   muestra.
#'
#'   Los atributos `max_celdas_muestra`, `max_bytes_muestra` y `tope_muestra`
#'   declaran la cota que se aplicará al bloque `perfil_muestra`. El plan no lee
#'   datos: resuelve la cota de celdas con el ancho del esquema y declara que la
#'   cota de bytes requiere una sonda de hasta cien filas durante la corrida.
#'   Si la muestra pedida supera la cota de celdas, `tope_muestra` y `print()`
#'   lo dicen antes de correr. La fila de consulta de muestra conserva su
#'   conteo separado de los agregados; los topes no cambian ninguna consulta
#'   SQL de resumen.
#'
#'   El costo no se declara como un número sino como un rango: `total` es el
#'   extremo inferior, que supone que la política omite la moda cuya cardinalidad
#'   no se conoce, y `total_maximo` el superior, que supone que la ejecuta. La
#'   mediana queda fuera de ese supuesto proporcional y se cuenta según las
#'   columnas numéricas solicitadas. Ambos incluyen la preparación y el perfilado; el rechazo
#'   de lotes puede agregar las sondas de bisección declaradas por
#'   `total_lotes_rechazados`. El costo real cae entre los extremos cuando
#'   `universo` es `"tabla_completa"` o `attr(plan, "muestreo")$estado` es
#'   `"disponible"`; en `"no_sondeado"` la forma sólo se construyó localmente
#'   y el intervalo queda condicionado a que la sonda de la corrida la acepte.
#'   Si la forma muestreada no se puede construir, el plan declara ese caso,
#'   excluye sus métricas del rango y `attr(plan, "supuesto")` dice por qué.
#'   El extremo superior incluye además, con `universo = "muestra_motor"` y una
#'   forma `TABLESAMPLE`, el reintento del resumen cuando la muestra vuelve con
#'   menos de la mitad de lo pedido, que depende de las páginas que sortee el
#'   motor. La cuenta es la de `max_consultas` y la de
#'   `resumen_tabla$meta$consultas$emitidas`: toda sentencia que el perfilado
#'   manda al motor, salvo las de la guarda de transacción, las lecturas de
#'   `pg_stat_statements` de `instrumentar` y las que algunos controladores
#'   mandan para contestar `DBI::dbGetInfo()` o `DBI::dbIsValid()` (duckdb 1.1,
#'   una o dos por corrida). Con `max_consultas` igual a
#'   `total_maximo` ninguna métrica queda afuera por el presupuesto; con
#'   `total`, sólo las consultas que piden los datos pueden quedar afuera.
#'
#'   Cuántas consultas se emiten no dice cuánto cuestan: catorce consultas
#'   sobre dos millones de filas son mucho más trabajo que doscientas sobre
#'   mil. Por eso el plan estima además la magnitud, y la estima en sus dos
#'   mitades, porque el reloj de una corrida no lo decide siempre el motor.
#'
#'   La del motor va en `filas_leidas` (cuántas filas habría que leer) y
#'   `ordenaciones_completas` (cuántas veces habría que ordenar la tabla
#'   entera), y se resume en `magnitud_motor`. La del cliente va en
#'   `columnas_texto` y `pares_texto` —cuántos pares de formas podría comparar
#'   en R el detector de vocabulario sobre la muestra— y se resume en
#'   `magnitud_texto`. `magnitud` es la mayor de las dos: `"baja"`, `"media"`,
#'   `"alta"`, o `"desconocida"` si no se conoce el número de filas.
#'   `supuesto_costo` dice de dónde sale cada cuenta.
#'
#'   El plan previo no publica duraciones, CPU, ni filas o bytes medidos, ni agrega
#'   una proyección temporal de `COUNT(DISTINCT)`. Puede publicar filas estimadas
#'   por `pg_class.reltuples` y proyecciones de trabajo de moda/mediana, siempre
#'   rotuladas como estimación de catálogo y no como medición. Aunque el plan de una corrida
#'   conserve el atributo `supuesto_costo_distintos`, la medición y la proyección
#'   sólo aparecen en `resumen_tabla$meta$costo_distintos`, después de ejecutar
#'   el primer lote. El atributo sólo declara por qué esa proyección no existe
#'   antes de correr; no es una duración ni una estimación temporal.
#'
#'   Si se pide `politica_costo = "por_cardinalidad"`, el plan busca primero una
#'   garantía estructural o una fuente de catálogo. Si la fuente queda
#'   desconocida, no emite un agregado para aclararla: `n_consultas` omite la
#'   moda y `n_consultas_max` deja abierto el camino que la ejecuta. La mediana
#'   se conserva porque su costo medido es plano frente a la cardinalidad y está
#'   gobernado por las filas. La corrida mide `distintos` sólo si la política lo
#'   necesita. La política por omisión es `"todas"`: el paquete no elige por el
#'   usuario.
#'   Una fuente estructural se resuelve aunque la estrategia de distintos este
#'   omitida o no disponible; esta ultima solo gobierna si se puede medir.
#'   El catalogo de la clave primaria se consulta siempre para conservar esa
#'   respuesta en `resumen_tabla$meta$clave`; es una lectura de metadatos y no
#'   un recorrido de la tabla.
#'
#'   Contar sólo el motor daría juicios falsos con números ciertos: una tabla
#'   chica con una columna de geometría en texto pide pocas lecturas —magnitud
#'   `"baja"` del lado del motor— y puede tardar mucho más de lo que eso
#'   sugiere, porque el trabajo está en la comparación de formas, que no es una
#'   lectura de fila. El método de
#'   impresión muestra las dos mitades, avisa cuando la magnitud es alta y
#'   nombra las palancas para acotarla, que no son las mismas de un lado que
#'   del otro.
#' @export
#' @seealso [perfilar_dbi()]
#'
#' @examples
#' if (requireNamespace("DBI", quietly = TRUE) &&
#'     requireNamespace("RSQLite", quietly = TRUE)) {
#'   con <- DBI::dbConnect(RSQLite::SQLite(), ":memory:")
#'   DBI::dbWriteTable(con, "ejemplo", data.frame(id = 1:10, valor = 11:20))
#'   plan_perfilado_dbi(con, "ejemplo")
#'   DBI::dbDisconnect(con)
#' }
plan_perfilado_dbi <- function(conexion, tabla,
                               universo = c("tabla_completa", "muestra_motor"),
                               muestra_motor = NULL, muestra = Inf,
                               orden_muestra = NULL,
                               metricas = .METRICAS_DBI,
                               estrategia_distintos = "exacta",
                               estrategia_mediana = c("exacta", "aproximada_motor"),
                               politica_costo = c("todas", "por_cardinalidad"),
                               bloque_muestra = c("con_muestra", "solo_agregados"),
                               max_consultas = Inf,
                               dialecto = "auto", incluir_valores = TRUE,
                               tamano_lote = NULL,
                               tamano_lote_planos = .TAMANO_LOTE_PLANOS_DBI,
                               tamano_lote_distintos = .TAMANO_LOTE_DISTINTOS_DBI,
                               instrumentar = FALSE,
                               umbral_cardinalidad = .UMBRAL_CARDINALIDAD_COSTO_DBI,
                               max_celdas_muestra = .MAX_CELDAS_MUESTRA,
                               max_bytes_muestra = .MAX_BYTES_MUESTRA,
                               bloque_filas = NULL,
                               max_bytes_procesamiento = .MAX_BYTES_MUESTRA,
                               max_bytes_materializacion = .MAX_BYTES_MUESTRA) {
  .fijar_numerica_c()  # LC_NUMERIC en "C" mientras lee de la conexion
  .fijar_senas_conexion_dbi(conexion)
  # El plan no recibe `proteger_datos_personales` y hereda la proteccion de
  # quien lo llama; `incluir_valores = FALSE` la suma, como en `perfilar_dbi()`
  # (ver `.protege_mensaje_motor()`): las consultas de prueba del dialecto
  # tambien publican mensajes del motor.
  .fijar_proteccion_motor(
    .protege_mensaje_motor(), incluir_valores = incluir_valores
  )
  # El nombre normalizado es el que viaja a todo lo que sigue, no solo a la
  # comprobacion de existencia (ver `.nombre_para_conexion_dbi()`).
  tabla <- .nombre_para_conexion_dbi(tabla)
  bloque_filas <- .validar_bloque_filas_dbi(bloque_filas)
  max_celdas_muestra <- .argumento_dbi(.validar_limite_duplicados(
    max_celdas_muestra, "max_celdas_muestra"
  ))
  max_bytes_muestra <- .argumento_dbi(.validar_limite_duplicados(
    max_bytes_muestra, "max_bytes_muestra"
  ))
  max_bytes_procesamiento <- .validar_presupuesto_bytes_dbi(
    max_bytes_procesamiento, "max_bytes_procesamiento"
  )
  max_bytes_materializacion <- .validar_presupuesto_bytes_dbi(
    max_bytes_materializacion, "max_bytes_materializacion"
  )
  preparacion <- .preparar_dbi(
    conexion = conexion, tabla = tabla, universo = universo,
    muestra_motor = muestra_motor, muestra = muestra,
    orden_muestra = orden_muestra,
    estrategia_mediana = estrategia_mediana, metricas = metricas,
    max_consultas = max_consultas, dialecto = dialecto,
    tamano_lote = tamano_lote,
    tamano_lote_planos = tamano_lote_planos,
    tamano_lote_distintos = tamano_lote_distintos,
    bloque_muestra = bloque_muestra, instrumentar = instrumentar,
    contar = FALSE, contar_muestreo = FALSE,
    sondar_muestreo = FALSE,
    incluir_valores = incluir_valores,
    estrategia_distintos = estrategia_distintos,
    politica_costo = politica_costo,
    umbral_cardinalidad = umbral_cardinalidad,
    max_bytes_procesamiento = max_bytes_procesamiento,
    max_bytes_materializacion = max_bytes_materializacion
  )
  filas_plan <- .filas_plan_dbi(preparacion)
  es_numerico <- vapply(seq_along(preparacion$campos), function(i) {
    .es_numerico_dbi(
      .atributo_columna_dbi(
        preparacion$prototipo, preparacion$campos[[i]], i
      ),
      .atributo_columna_dbi(
        preparacion$tipos, preparacion$campos[[i]], i
      ) %||% NA_character_
    )
  }, logical(1L))
  names(es_numerico) <- preparacion$campos
  tope_muestra <- .tope_muestra_plan_dbi(
    preparacion$muestra, length(preparacion$campos),
    max_celdas_muestra, max_bytes_muestra
  )
  consultas_antes_agregados <- preparacion$presupuesto$usadas
  # La corrida real cuenta el universo antes de construir un porcentaje para
  # TABLESAMPLE. El plan no ejecuta ese COUNT(*), pero si debe publicarlo en la
  # cantidad prevista para que su total siga coincidiendo con la corrida.
  muestreo_plan <- identical(preparacion$universo, "muestra_motor") &&
    !is.null(preparacion$muestreo) &&
    !is.null(preparacion$muestreo$candidato)
  candidato_previsto <- .candidato_muestreo_previsto_dbi(conexion, preparacion)
  conteo_muestreo <- isTRUE(muestreo_plan) && !is.null(candidato_previsto) && (
    identical(candidato_previsto$tipo, "tablesample") || (
      identical(candidato_previsto$tipo, "aleatorio") &&
        any(vapply(
          candidato_previsto$funciones,
          function(funcion) identical(funcion$nombre, "newid"),
          logical(1L)
        ))
    )
  )
  emitidas_plan <- consultas_antes_agregados +
    if (isTRUE(muestreo_plan)) {
      sondas_muestreo <- if (is.null(preparacion$muestreo$sondas_previstas)) {
        length(preparacion$muestreo$sondas)
      } else {
        preparacion$muestreo$sondas_previstas
      }
      as.integer(sondas_muestreo) + as.integer(conteo_muestreo)
    } else {
      0L
    }
  # La prueba de la CTE de ventanas. La preparacion solo la corre cuando no hay
  # mediana consolidada ni escalar; si la hay, una columna que la deja -un
  # decimal, cuya mediana es la suma de sus centrales, o un `float8` de
  # PostgreSQL, que la deja por `numeric_exact`- llega a la muestra sin forma de
  # una sola sentencia, y la corrida prueba la CTE entonces, una vez: su
  # consulta y su control negativo por candidato. El plan no la contaba
  # (DuckDB, un decimal y un doble por la muestra: una consulta de mas, y su
  # control). Una columna que la deja por sus extremos depende de los datos y
  # no se anticipa.
  emitidas_plan <- emitidas_plan + .prueba_cte_mediana_plan_dbi(
    conexion, preparacion, es_numerico, incluir_valores
  )
  plan <- .plan_sql_dbi(
    conexion, preparacion, es_numerico, incluir_valores, tope_muestra,
    emitidas = emitidas_plan,
    catalogo_aviso = .consultas_catalogo_aviso_dbi(conexion, tabla, preparacion)
  )
  # Con el bloque de filas, la muestra del motor no corre los agregados SQL:
  # se materializa una vez y se calcula en R (ver `.plan_spool_dbi()`). La
  # corrida vuelve a preparar la tabla para publicar este plan, y esa
  # preparacion es la de este plan: `consultas_antes_agregados`.
  if (identical(preparacion$universo, "muestra_motor") &&
      .solicita_muestra_dbi(preparacion$bloque_muestra)) {
    plan <- .plan_spool_dbi(
      conexion, tabla, preparacion, emitidas = emitidas_plan,
      replan = consultas_antes_agregados,
      conteo_en_preparacion = conteo_muestreo
    )
  }
  attr(plan, "total") <- sum(plan$n_consultas)
  extra <- attr(plan, "extra_si_se_rechazan_lotes", exact = TRUE)
  if (is.null(extra)) extra <- 0
  reintento <- attr(plan, "extra_si_se_reintenta_muestreo", exact = TRUE)
  if (is.null(reintento)) reintento <- 0
  attr(plan, "total_minimo") <- sum(plan$n_consultas)
  attr(plan, "total_maximo") <- sum(plan$n_consultas_max) + extra + reintento
  attr(plan, "total_lotes_rechazados") <- attr(plan, "total_maximo")
  attr(plan, "extra_si_se_rechazan_lotes") <- NULL
  attr(plan, "extra_si_se_reintenta_muestreo") <- NULL
  muestreo_plan_publico <- .publicar_muestreo_plan_dbi(
    preparacion$muestreo, if (identical(
      preparacion$universo, "muestra_motor"
    )) preparacion$muestra_motor else preparacion$muestra
  )
  motivo_muestreo <- if (identical(
    muestreo_plan_publico$estado, "no_disponible"
  )) {
    paste(
      "La forma muestreada no se puede construir; el plan no incluye sus",
      "m\u00e9tricas SQL. Motivo:", muestreo_plan_publico$motivo
    )
  } else ""
  # El total es un RANGO, no una prediccion exacta ni un techo. Ademas de las
  # sondas por rechazo de lotes, la cardinalidad desconocida deja abiertas las
  # moda que la politica puede omitir despues de medir.
  attr(plan, "supuesto") <- paste(
    "El plan no escanea datos para decidir el costo. Cuando la fuente de",
    "cardinalidad es desconocida, `total` supone que la pol\u00edtica omite la",
    "moda y `total_maximo` que la ejecuta; la mediana se conserva porque su",
    "costo medido es plano frente a la cardinalidad; la corrida mide `distintos`",
    "si la pol\u00edtica lo necesita y sigue esa decisi\u00f3n.",
    if ("distintos" %in% preparacion$metricas_ejecucion) {
      .SUPUESTO_COSTO_DISTINTOS_PLAN_DBI
    } else "",
    "Las fuentes estructurales exactas cierran ese intervalo. En cualquiera",
    "de los dos extremos, si el motor rechaza un lote se vuelve a sondear el",
    "\u00e1rbol de bisecci\u00f3n, hasta 2n - 1 consultas adicionales por lote; las",
    "respuestas aceptadas se reutilizan.", motivo_muestreo
  )
  attr(plan, "columnas") <- length(preparacion$campos)
  attr(plan, "columnas_numericas") <- sum(es_numerico)
  attr(plan, "columnas_ilegibles") <- preparacion$esquema$ilegibles
  attr(plan, "dialecto") <- preparacion$dialecto$nombre
  attr(plan, "consultas_emitidas") <- preparacion$presupuesto$usadas
  attr(plan, "metricas") <- preparacion$metricas
  attr(plan, "metricas_ejecucion") <- preparacion$metricas_ejecucion
  attr(plan, "muestreo") <- muestreo_plan_publico
  if ("distintos" %in% preparacion$metricas_ejecucion) {
    attr(plan, "supuesto_costo_distintos") <-
      .SUPUESTO_COSTO_DISTINTOS_PLAN_DBI
  }
  attr(plan, "politica_costo") <- preparacion$politica_costo
  attr(plan, "estrategia_distintos") <- .publicar_estrategia_distintos_dbi(
    preparacion$estrategia_distintos
  )
  attr(plan, "universo") <- preparacion$universo
  attr(plan, "estrategia_mediana") <- .publicar_estrategia_mediana_dbi(
    preparacion
  )
  attr(plan, "fuente_cardinalidad_costo") <-
    preparacion$fuentes_cardinalidad_costo
  attr(plan, "estimacion_derrame") <- preparacion$estimacion_derrame
  attr(plan, "estimacion_derrame_moda") <- preparacion$estimacion_derrame_moda
  attr(plan, "estimacion_derrame_mediana") <- preparacion$estimacion_derrame_mediana
  attr(plan, "moda_guardian") <- .publicar_moda_guardian_dbi(
    preparacion$moda_guardian_resolucion
  )
  attr(plan, "mediana_consolidada") <- preparacion$mediana_consolidada_resolucion
  attr(plan, "mediana_escalar") <- .publicar_mediana_escalar_dbi(
    preparacion$mediana_escalar_resolucion
  )
  attr(plan, "filas") <- filas_plan$filas
  attr(plan, "filas_fuente") <- filas_plan$fuente
  attr(plan, "estimacion_filas") <- filas_plan
  attr(plan, "proyecciones") <- .proyecciones_plan_catalogo_dbi(
    preparacion, filas_plan, incluir_valores = incluir_valores
  )
  attr(plan, "muestra") <- if (.solicita_muestra_dbi(
    preparacion$bloque_muestra
  )) preparacion$muestra else NA_real_
  attr(plan, "tamano_lote") <- preparacion$tamano_lote_planos
  attr(plan, "tamano_lote_planos") <- preparacion$tamano_lote_planos
  attr(plan, "tamano_lote_distintos") <- preparacion$tamano_lote_distintos
  attr(plan, "max_celdas_muestra") <- max_celdas_muestra
  attr(plan, "max_bytes_muestra") <- max_bytes_muestra
  attr(plan, "tope_muestra") <- tope_muestra
  if (identical(preparacion$bloque_muestra, "solo_agregados")) {
    attr(plan, "bloque_muestra") <- preparacion$bloque_muestra
  }
  # Que columnas van a pasar por el detector de vocabulario. Se mira el
  # prototipo -lo que devuelve el driver- y no el tipo declarado: es lo que de
  # verdad va a llegar a R.
  es_texto <- if (is.null(preparacion$prototipo)) {
    logical()
  } else {
    vapply(
      preparacion$prototipo,
      function(x) is.character(x) || is.factor(x),
      logical(1L)
    )
  }
  trabajo <- .trabajo_plan_dbi(
    plan, filas_plan$filas, tope_muestra$filas_maximas, sum(es_texto)
  )
  attr(plan, "filas_leidas") <- trabajo$filas_leidas
  attr(plan, "ordenaciones_completas") <- trabajo$ordenaciones
  attr(plan, "columnas_texto") <- trabajo$columnas_texto
  attr(plan, "pares_texto") <- trabajo$pares_texto
  attr(plan, "magnitud_motor") <- trabajo$magnitud_motor
  attr(plan, "magnitud_texto") <- trabajo$magnitud_texto
  attr(plan, "magnitud") <- trabajo$magnitud
  attr(plan, "supuesto_costo") <- .SUPUESTO_TRABAJO_DBI
  attr(plan, "celdas") <- .celdas_plan_dbi(
    filas_plan$filas, length(preparacion$campos)
  )
  attr(plan, "memoria_procesamiento") <- .memoria_procesamiento_plan_dbi(
    filas = attr(plan, "filas", exact = TRUE),
    celdas = attr(plan, "celdas", exact = TRUE),
    pares_texto = attr(plan, "pares_texto", exact = TRUE)
  )
  # La muestra del motor con el bloque de filas va por el spool aunque se pida
  # `bloque_filas`, que ahi solo fija el tamano de cada lectura.
  if (!is.null(bloque_filas) && !(
    identical(preparacion$universo, "muestra_motor") &&
      .solicita_muestra_dbi(preparacion$bloque_muestra)
  )) {
    # La corrida por bloques sobre la muestra del motor no tiene fuente: queda
    # `no_disponible` sin probarla, y el plan no paga esas consultas.
    usadas_antes_fuente <- preparacion$presupuesto$usadas
    fuente <- if (identical(preparacion$universo, "tabla_completa")) {
      .fuente_bloques_dbi(
        conexion, tabla, tabla_sql = preparacion$tabla_sql,
        campos = preparacion$campos,
        campos_sql = preparacion$campos_sql_bloques %||%
          preparacion$campos_sql_proyeccion,
        prototipo = preparacion$prototipo, tipos = preparacion$tipos,
        orden_sql = preparacion$orden_sql,
        clave = preparacion$catalogo_cardinalidad,
        presupuesto = preparacion$presupuesto,
        bloque_filas = bloque_filas
      )
    } else {
      list(disponible = FALSE,
           motivo = "no_disponible:fuente_bloques_solo_tabla_completa")
    }
    plan <- .plan_bloques_dbi(
      conexion, preparacion, fuente, bloque_filas,
      preparacion$metricas_ejecucion, incluir_valores, tope_muestra,
      emitidas = emitidas_plan,
      pruebas_fuente = preparacion$presupuesto$usadas - usadas_antes_fuente,
      catalogo_aviso = .consultas_catalogo_aviso_dbi(
        conexion, tabla, preparacion
      ),
      orden_muestra = NULL
    )
  }
  if (identical(preparacion$universo, "muestra_motor") &&
      .solicita_muestra_dbi(preparacion$bloque_muestra)) {
    spool_plan <- .plan_materializacion_spool_dbi(
      conexion, preparacion, max_bytes_materializacion
    )
    attr(plan, "materializacion") <- spool_plan
    attr(plan, "pasadas") <- spool_plan$pasadas
    attr(plan, "max_bytes_procesamiento") <- max_bytes_procesamiento
    attr(plan, "max_bytes_materializacion") <- max_bytes_materializacion
    attr(plan, "costo_materializacion") <- spool_plan$costo
    costo_plan <- attr(plan, "costo", exact = TRUE)
    if (is.null(costo_plan) || !is.list(costo_plan)) costo_plan <- list()
    costo_plan$materializacion <- spool_plan$costo
    costo_plan$seleccion_unica <- spool_plan$seleccion_unica
    costo_plan$spool <- "una selecci\u00f3n; lecturas posteriores en cliente"
    attr(plan, "costo") <- costo_plan
  }
  class(plan) <- unique(c("plan_perfilado_dbi", class(plan)))
  plan
}

.miles_dbi <- function(x) {
  if (is.null(x) || length(x) != 1L || is.na(x)) return("sin dato")
  # `decimal.mark` va explicito: por omision es el punto, y compartirlo con el
  # separador de miles hace que R avise en cada llamada.
  format(
    round(x), big.mark = ".", decimal.mark = ",",
    scientific = FALSE, trim = TRUE
  )
}

#' @export
print.plan_perfilado_dbi <- function(x, ...) {
  # Subconjuntar un plan -`plan[, c("clase_consulta", "n_consultas")]`- conserva
  # la clase y pierde los atributos, y este metodo imprimia entonces "sin dato
  # consultas sobre sin dato filas". Un encabezado que no puede decir nada no es
  # un plan: se imprime la tabla y se dice por que falta el resto.
  total <- attr(x, "total", exact = TRUE)
  if (is.null(total)) {
    cli::cli_alert_warning(.cli_literal(paste(
      "Este objeto conserva la clase del plan pero no sus atributos;",
      "seguramente sea un subconjunto. Se imprime s\u00f3lo la tabla."
    )))
    .print_data_frame_bytes(x, ...)
    return(invisible(x))
  }
  original <- x
  x <- .marcar_objeto_para_exhibir(x)
  cli::cli_h1("Plan de perfilado")
  filas <- attr(x, "filas", exact = TRUE)
  filas_fuente <- attr(x, "filas_fuente", exact = TRUE)
  texto_filas <- .texto_filas_plan_dbi(filas, filas_fuente)
  techo <- attr(x, "total_lotes_rechazados", exact = TRUE)
  # El rango se imprime como rango. Decir "techo" era exactamente lo que el
  # atributo `supuesto` desmiente dos lineas mas abajo.
  cuenta <- if (!is.null(techo) && !is.na(techo) && techo > total) {
    paste0("entre ", .miles_dbi(total), " y ", .miles_dbi(techo),
           if (techo == 1L) " consulta" else " consultas")
  } else {
    paste0(.miles_dbi(total), if (total == 1L) " consulta" else " consultas")
  }
  cli::cli_alert_info(.cli_literal(paste0(
    cuenta, " sobre ",
    texto_filas, " y ",
    .miles_dbi(attr(x, "columnas", exact = TRUE)),
    if (attr(x, "columnas", exact = TRUE) == 1L) " columna (dialecto " else " columnas (dialecto ",
    attr(x, "dialecto", exact = TRUE), ")"
  )))
  spool_plan <- attr(x, "materializacion", exact = TRUE)
  if (is.list(spool_plan)) {
    cli::cli_text(
      "Muestra: una selecci\u00f3n materializada en spool externo de sesi\u00f3n cliente;",
      " resultsets = ", spool_plan$costo$resultsets,
      ", presupuesto = ", .miles_dbi(spool_plan$presupuesto), " bytes."
    )
    cli::cli_text(
      "Spool pagado: ", isTRUE(spool_plan$pagado),
      "; los bloques y pasadas leen el mismo `muestra_id` cuando se materializa."
    )
  }
  fuente_plan <- attr(x, "fuente", exact = TRUE)
  if (is.list(fuente_plan) && !is.null(fuente_plan$metodo_orden)) {
    estado_capacidad <- if (isTRUE(fuente_plan$disponible)) {
      "disponible"
    } else {
      paste0("no disponible (", fuente_plan$motivo %||% "sin motivo", ")")
    }
    cli::cli_text(
      "Fuente: un result set incremental (dbSendQuery + dbFetch); capacidad: ",
      estado_capacidad, "."
    )
    cli::cli_text(
      "Orden: ", fuente_plan$metodo_orden,
      "; estable = ", isTRUE(fuente_plan$estable),
      "; orden_id = ", fuente_plan$orden_id, "."
    )
    bloques_plan <- attr(x, "bloques", exact = TRUE)
    if (is.list(bloques_plan)) {
      cli::cli_text(
        "Bloques previstos: objetivo ", .miles_dbi(bloques_plan$objetivo),
        if (bloques_plan$objetivo == 1L) " fila; m\u00ednimo " else " filas; m\u00ednimo ", .miles_dbi(bloques_plan$minimo),
        "; m\u00e1ximo ", .miles_dbi(bloques_plan$maximo), "."
      )
    }
    pasadas_plan <- attr(x, "pasadas", exact = TRUE)
    if (is.list(pasadas_plan)) {
      cli::cli_text(
        "Pasadas: valor = ", pasadas_plan$valor,
        "; \u00edndice = ", pasadas_plan$indice,
        "; materializaci\u00f3n = ", pasadas_plan$materializacion, "."
      )
    }
  }
  proyecciones <- attr(x, "proyecciones", exact = TRUE)
  if (is.list(proyecciones)) {
    if (isTRUE(proyecciones$moda$disponible)) {
      cli::cli_text(
        "Proyecci\u00f3n de moda: ~",
        .miles_dbi(proyecciones$moda$magnitud),
        " distintos acumulados en ", proyecciones$moda$n_columnas,
        if (proyecciones$moda$n_columnas == 1L) " columna; estimaci\u00f3n de cat\u00e1logo, no duraci\u00f3n. Fuente: " else
          " columnas; estimaci\u00f3n de cat\u00e1logo, no duraci\u00f3n. Fuente: ",
        proyecciones$moda$fuente, "."
      )
    }
    if (isTRUE(proyecciones$mediana$disponible)) {
      cli::cli_text(
        "Proyecci\u00f3n de mediana: ~",
        .miles_dbi(proyecciones$mediana$magnitud),
        if (proyecciones$mediana$magnitud == 1L) " fila-mediana; estimaci\u00f3n de cat\u00e1logo, no duraci\u00f3n. Fuente: " else
          " filas-mediana; estimaci\u00f3n de cat\u00e1logo, no duraci\u00f3n. Fuente: ",
        proyecciones$mediana$fuente, "."
      )
    }
  }
  for (familia in c("moda", "mediana")) {
    estimacion <- attr(x, paste0("estimacion_derrame_", familia), exact = TRUE)
    if (is.null(estimacion) || identical(estimacion$estado, "no_solicitado")) {
      next
    }
    limite <- if (identical(estimacion$metodo, "sort") ||
                  identical(familia, "mediana")) {
      estimacion$work_mem
    } else estimacion$memoria_efectiva
    cli::cli_text(
      "Derrame estimado de ", familia, ": ", estimacion$estado,
      "; m\u00e9todo/forma = ", estimacion$metodo, "/", estimacion$forma,
      "; l\u00edmite de decisi\u00f3n = ", limite, "; motivo: ", estimacion$motivo
    )
  }
  if (identical(attr(x, "bloque_muestra", exact = TRUE), "solo_agregados")) {
    cli::cli_text(
      "Perfil de muestra: no solicitado; el plan incluye s\u00f3lo agregados SQL."
    )
  } else {
    tope <- attr(x, "tope_muestra", exact = TRUE)
    if (!is.null(tope)) {
      if (isTRUE(tope$recortada_por_celdas)) {
        cli::cli_text(
          "Perfil de muestra: el tope de celdas lo limita a como m\u00e1ximo ",
          .miles_dbi(tope$filas_maximas), if (tope$filas_maximas == 1L) " fila antes de leer." else " filas antes de leer."
        )
      } else {
        cli::cli_text(
          "Perfil de muestra: se solicitan ",
          .miles_dbi(tope$filas_solicitadas),
          if (tope$filas_solicitadas == 1L) " fila; el tope de celdas no reduce ese pedido conocido." else
            " filas; el tope de celdas no reduce ese pedido conocido."
        )
      }
      if (isTRUE(tope$requiere_sonda_bytes)) {
        cli::cli_text(
          "El tope de bytes requiere una sonda previa de hasta 100 filas;",
          " el l\u00edmite final se fija despu\u00e9s de medirla."
        )
      }
    }
  }
  memoria <- attr(x, "memoria_procesamiento", exact = TRUE)
  if (!is.null(memoria)) {
    cli::cli_h2("Memoria del procesamiento")
    cli::cli_text(
      "Memoria del procesamiento: no estimada. Motivo: ", memoria$motivo
    )
    magnitud_memoria <- memoria$magnitud
    cli::cli_text(
      "Magnitud del trabajo (no consumo de memoria): ",
      .miles_dbi(magnitud_memoria$filas), if (isTRUE(magnitud_memoria$filas == 1L)) " fila; " else " filas; ",
      .miles_dbi(magnitud_memoria$celdas), if (isTRUE(magnitud_memoria$celdas == 1L)) " celda; " else " celdas; ",
      .miles_dbi(magnitud_memoria$pares_texto), if (isTRUE(magnitud_memoria$pares_texto == 1L)) " par de texto." else " pares de texto."
    )
    cli::cli_text(
      "Datos de referencia medidos, no predicci\u00f3n: traer la tabla cost\u00f3 ",
      memoria$referencias$traer, "; procesar en R cost\u00f3 ",
      memoria$referencias$procesar, "."
    )
    cli::cli_text(
      "La referencia de procesamiento vari\u00f3 por ",
      memoria$referencias$variacion,
      "; esa variaci\u00f3n es justamente el motivo por el que no se estima."
    )
    cli::cli_text(.cli_literal(memoria$distincion))
    cli::cli_text(.cli_literal(memoria$reparto_observado))
  }
  magnitud <- attr(x, "magnitud", exact = TRUE)
  if (is.null(magnitud)) magnitud <- "desconocida"
  if (identical(magnitud, "desconocida")) {
    cli::cli_alert_warning(.cli_literal(paste(
      "No se pudo estimar el trabajo: falta el n\u00famero de filas.",
      "El conteo de consultas sigue siendo v\u00e1lido."
    )))
    # Los supuestos NO se imprimen aca: el bloque final ya los imprime para
    # toda magnitud distinta de "baja", y "desconocida" lo es. Este sitio los
    # duplicaba: el plan mostraba dos veces los mismos dos parrafos, y un texto
    # repetido se lee como un error del que lo escribio, no como enfasis.
  } else {
    trabajo <- paste0(
      .miles_dbi(attr(x, "filas_leidas", exact = TRUE)),
      if (isTRUE(attr(x, "filas_leidas", exact = TRUE) == 1L)) " lectura de fila y " else
        " lecturas de fila y ",
      .miles_dbi(attr(x, "ordenaciones_completas", exact = TRUE)),
      if (isTRUE(attr(x, "ordenaciones_completas", exact = TRUE) == 1L)) {
        " ordenaci\u00f3n completa"
      } else " ordenaciones completas"
    )
    # El trabajo en R no se puede dejar afuera del titular. Cuando la mitad que
    # decide el reloj es esta, un "bajo" a secas manda al usuario a esperar
    # treinta segundos creyendo que iban a ser dos.
    n_texto <- attr(x, "columnas_texto", exact = TRUE)
    if (!is.null(n_texto) && !is.na(n_texto) && n_texto > 0) {
      trabajo <- paste0(
        trabajo, " en el motor, m\u00e1s ",
        .miles_dbi(attr(x, "pares_texto", exact = TRUE)),
        " pares de formas a comparar en R sobre ", .miles_dbi(n_texto),
        if (n_texto == 1) " columna de texto" else " columnas de texto"
      )
    }
    # Una magnitud alta o media no es un error: es una corrida que conviene
    # decidir a ojos abiertos. Por eso el aviso nombra las palancas concretas en
    # vez de limitarse a decir que es grande.
    #
    # Las nombra tambien en "media", y eso salio de una corrida contra motores
    # reales: una tabla de 4,5 millones de filas en PostgreSQL tardo 6,2 minutos
    # con las opciones por omision y su plan la clasificaba **media**. El aviso
    # avisaba, pero quien no conociera `universo = 'muestra_motor'` -que baja esa misma
    # tabla a 39 segundos- no tenia como enterarse. Un plan que dice "va a
    # costar" sin decir "y asi se acota" deja al usuario a mitad de camino
    # justo donde la decision importa.
    if (identical(magnitud, "alta") || identical(magnitud, "media")) {
      if (identical(magnitud, "alta")) {
        cli::cli_alert_danger(.cli_literal(paste0("Trabajo estimado alto: ", trabajo)))
      } else {
        cli::cli_alert_warning(.cli_literal(paste0("Trabajo estimado medio: ", trabajo)))
      }
      cli::cli_text("Para acotarlo, sin cambiar nada m\u00e1s:")
      palancas <- c(
        "universo = 'muestra_motor' mide sobre una muestra que trae el motor",
        "metricas = c(...) saca clases de consulta enteras del plan",
        "muestra = n baja las filas que se traen a R",
        "max_consultas = n pone un techo duro y declara lo que quede afuera"
      )
      # Si lo que pesa es el trabajo por valor, las palancas del motor no
      # alcanzan: bajar consultas no toca lo que se hace despues en R.
      if (identical(attr(x, "magnitud_texto", exact = TRUE), "alta")) {
        palancas <- c(
          palancas,
          paste(
            "max_trabajo_vocabulario = n acota la comparaci\u00f3n de formas,",
            "que es lo que pesa en R"
          )
        )
      }
      cli::cli_ul(.cli_literal(palancas))
    } else {
      cli::cli_alert_success(.cli_literal(paste0("Trabajo estimado bajo: ", trabajo)))
    }
  }
  supuesto_distintos <- attr(x, "supuesto_costo_distintos", exact = TRUE)
  if (!is.null(supuesto_distintos)) {
    cli::cli_text(.cli_literal(supuesto_distintos))
  }
  # `muestra = Inf` -lo que viene por omision- trae la tabla entera a R. Es lo
  # correcto para un analisis de calidad: los diagnosticos que miran los valores
  # -patrones, formatos, dependencias y casi-duplicados- solo ven lo que se les trae, y sin
  # `orden_muestra` una muestra acotada son las PRIMERAS filas del motor, no una
  # al azar. Pero conviene decirlo antes y no despues, porque sobre una tabla
  # grande es lo que manda el reloj.
  muestra_plan <- attr(x, "muestra", exact = TRUE)
  if (!identical(attr(x, "bloque_muestra", exact = TRUE), "solo_agregados") &&
      !is.null(muestra_plan) && !is.finite(muestra_plan) &&
      (is.null(fuente_plan) || isTRUE(fuente_plan$disponible))) {
    filas_plan <- attr(x, "filas", exact = TRUE)
    cli::cli_text(
      "El perfil de muestra trae la tabla entera",
      if (!is.null(filas_plan) && !is.na(filas_plan)) {
        paste0(" -", .texto_filas_plan_dbi(filas_plan, filas_fuente), "-")
      } else "",
      ": es el valor por omisi\u00f3n y sobre una tabla grande puede demorar. ",
      "`muestra = n` acota cu\u00e1ntas filas se traen, a cambio de mirar menos."
    )
  }
  # Los supuestos son largos y solo pesan cuando el numero incomoda. Sobre una
  # tabla chica el usuario ya tiene su respuesta en la linea de arriba, y dos
  # parrafos de letra fina la tapan. No se ocultan: siguen en los atributos, y
  # la palabra "techo" viaja con el conteo en todos los casos.
  if (!identical(magnitud, "baja")) {
    supuesto <- attr(x, "supuesto_costo", exact = TRUE)
    if (!is.null(supuesto)) cli::cli_text(.cli_literal(supuesto))
    techo <- attr(x, "supuesto", exact = TRUE)
    if (!is.null(techo)) cli::cli_text(.cli_literal(techo))
  } else {
    cli::cli_text(
      "Los supuestos de la cuenta est\u00e1n en los atributos ",
      "`supuesto_costo` y `supuesto`."
    )
  }
  .print_data_frame_bytes(as.data.frame(x), row.names = FALSE)
  invisible(original)
}

# ---- Proteccion de datos personales -------------------------------------
#
# El resumen de tabla completa es el bloque de mayor alcance -cubre toda la
# base, no una muestra- y era el unico que nunca pasaba por la proteccion. Se
# protegen los valores de la fila, los estadisticos de orden, los momentos y
# el SQL guardado.

.proteger_informacion_conexion_dbi <- function(info) {
  sensibles <- c("dbname", "host", "username", "servername", "sourcename")
  presentes <- intersect(sensibles, names(info$informacion_dbi))
  for (campo in presentes) {
    info$informacion_dbi[[campo]] <- "[dato de conexion protegido]"
  }
  if (length(presentes)) {
    info$informacion_dbi$proteccion_aplicada <- TRUE
  }
  info
}

# Lo que se publica de las columnas NO personales -moda, extremos, ejemplos,
# evidencia de los hallazgos- puede ser un valor que en la columna protegida esta
# solo FUERA de la muestra: el titular que es la moda de otra columna se
# publicaba exacto. Una consulta por los candidatos escritos tal cual no
# alcanzaba, por cuatro motivos: comparaba
# exacto -sin caja ni separadores-, no miraba la evidencia, no corria sobre una
# columna personal NUMERICA -una cedula guardada como entero, lo corriente en
# una base- y se cortaba en 500 candidatos sin avisar.
#
# Ahora se traen los valores DISTINTOS de las columnas protegidas, de cualquier
# tipo, y se protege con la misma regla que `perfilar()` en memoria: pliegue,
# separadores, documentos parciales, campos numericos. Solo cuando la muestra no
# cubre la tabla. Hasta `.MAXIMO_VALORES_PROTEGIDOS_DBI` valores; si hay mas, o
# si la consulta falla, se cierra del lado seguro y se declara: ver
# `.cerrar_fuera_de_muestra_dbi()`.
.MAXIMO_VALORES_PROTEGIDOS_DBI <- 2000000L

# Un valor leido de la base como el texto que se busca: el entero guardado como
# doble sin su `.0` ni notacion cientifica. Lo usan la lectura fuera de la
# muestra y la de `perfilar_coleccion()`.
.texto_de_valores_dbi <- function(v) {
  if (inherits(v, "integer64")) return(as.character(v))
  if (is.numeric(v)) {
    enteros <- !is.na(v) & is.finite(v) & v == round(v) & abs(v) < 1e18
    salida <- as.character(v)
    salida[enteros] <- formatC(v[enteros], format = "f", digits = 0)
    return(salida)
  }
  as.character(v)
}

.valores_protegidos_fuera_de_muestra_dbi <- function(conexion, preparacion,
                                                     perfil, sensibles,
                                                     presupuesto,
                                                     rellenos_columna = NULL) {
  completo <- list(valores = character(), completo = TRUE, motivo = NA_character_,
                   fechas = character())
  if (!length(sensibles) || !is.list(perfil)) return(completo)
  operar <- function(x) .nombres_para_operar(as.character(x))
  sqlite <- grepl("sqlite", .senas_conexion_dbi(conexion), fixed = TRUE, useBytes = TRUE)
  if (!isTRUE(perfil$meta$muestreo)) {
    # Sin muestreo la muestra es la tabla, salvo en SQLite: RSQLite tipa una
    # columna de afinidad numerica por sus primeras filas y lee el texto
    # "5.765.432-1" guardado en ella como 5. La via por omision protegia MENOS
    # que la muestreada sobre la misma tabla. Medido. Ahi se
    # relee como texto la columna protegida que no llego como texto.
    if (!sqlite || !is.data.frame(perfil$columnas)) return(completo)
    tipos <- perfil$columnas$tipo_declarado[
      match(operar(sensibles), operar(perfil$columnas$columna))
    ]
    sensibles <- sensibles[is.na(tipos) | tipos != "texto"]
    if (!length(sensibles)) return(completo)
  }
  indices <- match(operar(sensibles), operar(preparacion$campos))
  indices <- indices[!is.na(indices)]
  if (!length(indices)) return(completo)
  como_texto <- .texto_de_valores_dbi
  valores <- character()
  fechas <- character()
  for (indice in indices) {
    campo <- preparacion$campos_sql[[indice]]
    # En SQLite una columna de afinidad NUMERIC guarda texto, y RSQLite la lee
    # como numero: "5.765.432-1" llegaba como 5 y no tapaba nada. Medido.
    # Ahi se lee como texto; en los demas motores el tipo de la
    # columna manda, y un CAST a VARCHAR sin largo trunca en SQL Server.
    expresion <- if (sqlite) paste0("CAST(", campo, " AS TEXT)") else campo
    sql <- paste0(
      "SELECT DISTINCT ", expresion, " FROM ", preparacion$tabla_sql,
      " WHERE ", campo, " IS NOT NULL"
    )
    respuesta <- .consultar_dbi(
      conexion, sql, presupuesto,
      filas = .MAXIMO_VALORES_PROTEGIDOS_DBI + 1L,
      etapa = "proteccion_fuera_de_muestra"
    )
    if (!isTRUE(respuesta$ok)) {
      return(list(valores = character(), completo = FALSE, motivo = paste0(
        "no se pudieron consultar los valores de `",
        preparacion$campos[[indice]], "` fuera de la muestra: ", respuesta$motivo
      )))
    }
    if (NROW(respuesta$datos)) {
      leidos <- como_texto(respuesta$datos[[1L]])
      # El telefono con forma de fecha de una columna que no es de fechas: ver
      # `.fechas_que_identifican()`.
      fechas <- unique(c(fechas, .fechas_de_columna_no_fecha(leidos)))
      # Y en una columna de fechas -tambien AAAAMMDD o con el ano en dos
      # cifras- sus fechas no entran al piso: la misma regla que en memoria,
      # `.columna_de_fechas()`. Por aca entraban enteras.
      if (.columna_de_fechas(leidos)) leidos <- leidos[!.forma_de_fecha(leidos)]
      # Los rellenos confirmados de ESTA columna no entran; los de otra, si.
      if (is.data.frame(rellenos_columna) && nrow(rellenos_columna)) {
        propios <- rellenos_columna$valor[
          operar(rellenos_columna$columna) %in% operar(preparacion$campos[[indice]])
        ]
        leidos <- leidos[!.recortar_bytes(leidos) %in% propios]
      }
      valores <- unique(c(valores, leidos))
    }
    if (length(valores) > .MAXIMO_VALORES_PROTEGIDOS_DBI) {
      return(list(valores = character(), completo = FALSE, motivo = paste0(
        "las columnas protegidas tienen m\u00e1s de ",
        format(.MAXIMO_VALORES_PROTEGIDOS_DBI, big.mark = ".", scientific = FALSE),
        if (.MAXIMO_VALORES_PROTEGIDOS_DBI == 1L) " valor distinto y no se trae" else
          " valores distintos y no se traen"
      )))
    }
  }
  list(valores = valores[!is.na(valores)], completo = TRUE, motivo = NA_character_,
       fechas = fechas)
}

# Lo que se aplica con los valores de la tabla entera: la misma proteccion que el
# piso de `perfilar()`, en texto y en numeros.
.proteger_con_valores_dbi <- function(x, valores, intocables,
                                      fechas = character()) {
  identificantes <- .valores_identificantes(unique(valores), fechas)
  if (!length(identificantes) || is.null(x)) return(x)
  x <- .proteger_textos_salida(x, identificantes, intocables = intocables)
  columnas_antes <- x$columnas
  x <- .proteger_numeros_parametros(x, identificantes)
  # Como en `.proteger_perfil()`: si el piso numerico tapo uno de los centinelas
  # contados de una traza, el campo se cierra entero.
  x <- .cerrar_sentinelas_contados_en(x)
  if (inherits(columnas_antes, "data.frame")) {
    x$columnas <- .tapar_derivados_del_piso(columnas_antes, x$columnas)
    x <- .tapar_familias_como_columnas_dbi(x, columnas_antes)
  }
  x
}

# `meta$familias` de la via por bloques no publica de una columna lo que el piso
# le tapo en la tabla de columnas: con el maximo de una columna de codigos tapado
# -una cedula copiada- y el minimo, la media y el desvio tapados como sus
# derivados (`.tapar_derivados_del_piso()`), `cuantitativos` seguia publicando la
# media y el desvio, que con dos cedulas entre noventa codigos las
# reconstruyen. Se tapa en `cuantitativos` cada campo que el piso dejo en NA en
# `columnas`, comparando antes y despues: un campo que ya era NA no cuenta.
.tapar_familias_como_columnas_dbi <- function(x, columnas_antes) {
  familias <- if (is.list(x$meta)) x$meta$familias
  despues <- x$columnas
  if (!is.list(familias) || !length(familias) ||
      !is.data.frame(columnas_antes) || !is.data.frame(despues) ||
      nrow(columnas_antes) != nrow(despues) ||
      !"columna" %in% names(despues)) {
    return(x)
  }
  operar <- function(v) .nombres_para_operar(as.character(v))
  claves <- operar(despues$columna)
  for (nombre in names(familias)) {
    if (!is.list(familias[[nombre]])) next
    sobre <- familias[[nombre]][["cuantitativos"]]
    if (!is.list(sobre) || !is.list(sobre[["resultado"]])) next
    i <- match(operar(nombre), claves)
    if (is.na(i)) next
    resultado <- sobre[["resultado"]]
    campos <- intersect(c("minimo", "maximo", "media", "desvio"),
                        intersect(names(resultado), names(despues)))
    for (campo in campos) {
      tapado <- !is.na(columnas_antes[[campo]][[i]]) &&
        is.na(despues[[campo]][[i]])
      if (tapado) resultado[[campo]] <- rep(NA_real_, length(resultado[[campo]]))
    }
    sobre[["resultado"]] <- resultado
    familias[[nombre]][["cuantitativos"]] <- sobre
  }
  x$meta$familias <- familias
  x
}

# Los nombres de la tabla -y de su esquema- tal como los cita la SQL que la
# llamada escribe (`dbQuoteIdentifier()`), sin las comillas. Son estructura,
# como los nombres de las columnas: ver `.cerrar_fuera_de_muestra_dbi()`.
.nombres_tabla_dbi <- function(tabla_sql) {
  tabla_sql <- as.character(tabla_sql)
  tabla_sql <- tabla_sql[!is.na(tabla_sql) & nzchar(tabla_sql)]
  if (!length(tabla_sql)) return(character())
  nombres <- unlist(lapply(tabla_sql, function(texto) {
    partes <- tryCatch(.partir_identificador(texto)$partes,
                       error = function(e) character())
    partes <- vapply(partes, .quitar_comillas_identificador, character(1L),
                     USE.NAMES = FALSE)
    c(partes, if (length(partes) > 1L) paste(partes, collapse = "."))
  }), use.names = FALSE)
  nombres <- unique(nombres)
  nombres[!is.na(nombres) & nzchar(nombres)]
}

# Lo que un cierre tapa sin saber de quien es -los valores de las columnas no
# personales, o los de todas cuando no hay clasificacion- no incluye un valor
# igual al nombre de la tabla o de su esquema, con la clave de los nombres
# iguales a valores (`.nombres_iguales_a_valores()`). Con la
# lectura fuera de la muestra fallida, una columna no personal con el valor
# `pedidos` en una tabla `pedidos` borraba el nombre de todo el objeto
# -`meta$tabla`, cada SQL guardada, el encabezado de `print()`-: el valor
# entraba al cierre y el nombre, que no es de ninguna celda, se tapaba como
# si lo fuera. Ese texto ya se publica como estructura, y tapar la celda que lo
# repite no protege nada.
.sin_nombres_de_estructura <- function(valores, nombres) {
  valores <- unique(as.character(valores))
  valores <- valores[!is.na(valores)]
  nombres <- nombres[!is.na(nombres) & nzchar(nombres)]
  if (!length(valores) || !length(nombres)) return(valores)
  setdiff(valores, .nombres_iguales_a_valores(valores, nombres))
}

# Sin los valores de la tabla entera no se sabe que de lo publicado es de una
# persona. Se tapa todo valor de celda de las columnas no personales -moda,
# extremos, ejemplos- y la evidencia de sus hallazgos, y se dice por que.
# `nombres_tabla`: los de la tabla y su esquema (`.nombres_tabla_dbi()`), que
# son intocables como los de las columnas y no entran al cierre como valor.
.cerrar_fuera_de_muestra_dbi <- function(resumen, perfil, sensibles,
                                         nombres_tabla = character()) {
  operar <- function(x) .nombres_para_operar(as.character(x))
  no_personal <- function(columnas) !operar(columnas) %in% operar(sensibles)
  candidatos <- character()
  for (tabla in list(resumen$columnas, perfil$columnas)) {
    if (!is.data.frame(tabla) || !"columna" %in% names(tabla)) next
    filas <- no_personal(tabla$columna)
    for (campo in intersect(c("moda", "minimo", "maximo", "mediana", "media"),
                            names(tabla))) {
      candidatos <- c(candidatos, as.character(tabla[[campo]][filas]))
    }
  }
  if (is.list(perfil$patrones)) {
    for (columna in names(perfil$patrones)) {
      if (!no_personal(columna)) next
      candidatos <- c(candidatos, unlist(strsplit(
        as.character(perfil$patrones[[columna]]$ejemplos),
        .SEPARADOR_EJEMPLOS, fixed = TRUE
      ), use.names = FALSE))
    }
  }
  # Y lo que la via por bloques guarda de cada columna no personal en
  # `meta$familias`: cada valor distinto y los extremos son valores de celda,
  # como la moda. Sin esto, con la lectura fuera de la muestra fallida, salian
  # enteros.
  candidatos <- c(candidatos, .valores_familias_bloques_dbi(
    resumen$meta$familias, no_personal
  ))
  nombres_tabla <- as.character(nombres_tabla)
  intocables <- unique(c(as.character(resumen$columnas$columna), nombres_tabla))
  intocables <- intocables[!is.na(intocables) & nzchar(intocables)]
  candidatos <- .sin_nombres_de_estructura(candidatos, nombres_tabla)
  resumen <- .proteger_con_valores_dbi(resumen, candidatos, intocables)
  perfil <- .proteger_con_valores_dbi(perfil, candidatos, intocables)
  if (is.data.frame(perfil$hallazgos) && nrow(perfil$hallazgos) &&
      "evidencia" %in% names(perfil$hallazgos)) {
    filas <- no_personal(perfil$hallazgos$columna) &
      !is.na(perfil$hallazgos$evidencia)
    perfil$hallazgos$evidencia[filas] <- "[evidencia protegida]"
    # Con la evidencia tapada, la traza tampoco dice que centinelas se contaron.
    perfil$hallazgos <- .cerrar_sentinelas_contados(perfil$hallazgos)
  }
  list(resumen = resumen, perfil = perfil)
}

# Los valores de celda que `meta$familias` de la via por bloques publica de las
# columnas que `incluir()` acepta: los representantes de `distintos` y los
# extremos de `cuantitativos`.
.valores_familias_bloques_dbi <- function(familias, incluir) {
  if (!is.list(familias) || !length(familias)) return(character())
  valores <- character()
  for (nombre in names(familias)) {
    if (!isTRUE(incluir(nombre)) || !is.list(familias[[nombre]])) next
    distintos <- familias[[nombre]][["distintos"]]
    distintos <- if (is.list(distintos)) distintos[["resultado"]]
    if (is.data.frame(distintos) && "representante" %in% names(distintos)) {
      valores <- c(valores, as.character(distintos[["representante"]]))
    }
    cuantitativos <- familias[[nombre]][["cuantitativos"]]
    cuantitativos <- if (is.list(cuantitativos)) cuantitativos[["resultado"]]
    if (is.list(cuantitativos)) {
      for (campo in intersect(c("minimo", "maximo"), names(cuantitativos))) {
        valores <- c(valores, as.character(cuantitativos[[campo]]))
      }
    }
  }
  unique(valores[!is.na(valores)])
}

# Lo que la llamada publica de la tabla pasa por el piso por valor con todo lo
# que la llamada conoce de las columnas protegidas: los valores de la muestra y,
# cuando la muestra no cubre la tabla, los de la tabla entera; si esos no se
# pueden leer, se cierra. UNA funcion para las dos vias, con y sin
# `bloque_filas`. La via por bloques llamaba solo a `.proteger_resumen_dbi()`
# sin la muestra: el piso corria con los extremos de las columnas protegidas y
# nada mas, y una cedula repetida en una columna de codigos salia en
# `columnas$maximo`, en la corroboracion -con una divergencia que la proteccion
# inventaba- y en `meta$familias`; los nombres citados en una columna de texto
# libre, igual. Cerrar `meta$familias` solo en las columnas protegidas no
# alcanzaba.
#
# `bloque` es lo que devuelve `.bloque_muestra_dbi()`; sin perfil de muestra no
# hay clasificacion y se protege todo.
.proteger_salida_muestra_dbi <- function(resumen, bloque, conexion, preparacion,
                                         presupuesto) {
  # Los nombres de la tabla y de su esquema son intocables como los de las
  # columnas, en todos los pisos de la llamada.
  nombres_tabla <- .nombres_tabla_dbi(
    if (is.null(preparacion$tabla_nombre_sql)) preparacion$tabla_sql else
      preparacion$tabla_nombre_sql
  )
  intocables <- unique(c(as.character(resumen$columnas$columna), nombres_tabla))
  intocables <- intocables[!is.na(intocables) & nzchar(intocables)]
  if (is.null(bloque$perfil)) {
    # Sin muestra no hay clasificacion posible. Ante la duda se protege: para
    # una funcion de privacidad el valor por omision seguro es cerrado.
    resumen <- .proteger_resumen_dbi(
      resumen, resumen$columnas$columna, "sin_clasificacion_disponible",
      intocables = intocables, nombres_tabla = nombres_tabla
    )
    return(list(resumen = resumen, perfil = bloque$perfil))
  }
  sensibles_muestra <- .columnas_personales_protegidas(
    bloque$perfil$datos_personales
  )
  # Los rellenos que la tabla entera no confirma vuelven al piso: en el
  # resumen, en la lectura fuera de la muestra y en el perfil de la muestra,
  # que `perfilar()` protegio decidiendo sobre la muestra.
  rellenos_columna <- .rellenos_confirmados_tabla_dbi(
    bloque$rellenos_detalle, bloque$muestreo, resumen$columnas,
    resumen$sql, universo = preparacion$universo
  )
  rellenos <- unique(rellenos_columna$valor)
  no_confirmados <- setdiff(bloque$rellenos, rellenos)
  resumen <- .proteger_resumen_dbi(
    resumen, sensibles_muestra, "perfil_muestra", bloque$perfil,
    valores_muestra = c(bloque$valores_protegidos, no_confirmados),
    columnas_de_fechas = bloque$columnas_de_fechas,
    rellenos = rellenos, intocables = intocables
  )
  if (length(no_confirmados)) {
    bloque$perfil <- .proteger_con_valores_dbi(
      bloque$perfil, no_confirmados, intocables
    )
  }
  # Los rellenos confirmados salen del piso SOLO en su columna: si otra
  # columna protegida tiene el mismo valor, entra. Se sacaban de todas, y
  # el `1.111.111-1` de relleno de `cedula` dejaba publicada la cedula
  # `1.111.111-1` de un conyuge en la moda de `obs`.
  fuera <- .valores_protegidos_fuera_de_muestra_dbi(
    conexion, preparacion, bloque$perfil, sensibles_muestra, presupuesto,
    rellenos_columna = rellenos_columna
  )
  # Para el mensaje del motor de las demas tablas de una coleccion: ver
  # `.activar_valores_motor()`. Fuera de una coleccion no hace nada.
  .sumar_valores_motor(c(bloque$valores_protegidos, no_confirmados),
                       fechas = bloque$valores_protegidos)
  if (isTRUE(fuera$completo)) {
    .sumar_valores_motor(fuera$valores, fuera$fechas)
    resumen <- .proteger_con_valores_dbi(
      resumen, fuera$valores, intocables, fuera$fechas
    )
    bloque$perfil <- .proteger_con_valores_dbi(
      bloque$perfil, fuera$valores, intocables, fuera$fechas
    )
  } else {
    cerrado <- .cerrar_fuera_de_muestra_dbi(
      resumen, bloque$perfil, sensibles_muestra, nombres_tabla = nombres_tabla
    )
    resumen <- cerrado$resumen
    bloque$perfil <- cerrado$perfil
    resumen$meta$proteccion_personal$fuera_de_muestra <- paste0(
      "No verificada: ", fuera$motivo, ". Se taparon los valores y la ",
      "evidencia de las columnas no personales."
    )
  }
  list(resumen = resumen, perfil = bloque$perfil)
}

.proteger_resumen_dbi <- function(resumen, sensibles, base_clasificacion,
                                  perfil_muestra = NULL,
                                  valores_muestra = character(),
                                  columnas_de_fechas = character(),
                                  rellenos = character(),
                                  intocables = NULL,
                                  nombres_tabla = character()) {
  resumen$meta$proteccion_personal <- list(
    aplicada = length(sensibles) > 0,
    base = base_clasificacion,
    columnas = sensibles
  )
  resumen$meta$motor <- .proteger_informacion_conexion_dbi(resumen$meta$motor)
  if (!length(sensibles)) return(resumen)
  reemplazo <- "[valor protegido]"
  columnas <- resumen$columnas
  indices <- .nombres_para_operar(columnas$columna) %in%
    .nombres_para_operar(sensibles)
  if (!any(indices)) return(resumen)
  # Los valores identificantes se cosechan ANTES de taparlos, que es el unico
  # momento en que estan a la vista: por esta puerta no hay tabla original de
  # donde sacarlos despues. Sin esto habia una
  # divergencia entre puertas: sobre la misma tabla `perfilar()` enmascaraba
  # `minimo`, `maximo` y `media` de una copia no clasificada y
  # `perfilar_dbi()` los publicaba enteros.
  # La cosecha sale del perfil de la MUESTRA, no de este resumen: por esta
  # puerta la columna protegida suele ser texto y no tiene estadisticos que
  # cosechar, mientras que el perfil de la muestra trae sus valores -moda,
  # ejemplos de patron- todavia sin tapar.
  identificantes <- .valores_identificantes(unique(c(
    if (!is.null(perfil_muestra)) {
      c(
        # Los valores de la muestra, que es la fuente completa: el resumen trae
        # estadisticos y el perfil trae ejemplos, y con treinta documentos
        # distintos ni la moda ni los tres primeros ejemplos alcanzan -el
        # `maximo` de una copia numerica es el ultimo documento, que no esta en
        # ninguno de los dos-.
        valores_muestra,
        .valores_publicables_protegidos(
          perfil_muestra[["datos", exact = TRUE]], sensibles
        ),
        .valores_perfil_protegidos(
          perfil_muestra$columnas, perfil_muestra$patrones,
          perfil_muestra$datos_personales, perfil_muestra$meta,
          excluir = columnas_de_fechas, rellenos = rellenos
        )
      )
    } else character(),
    unlist(lapply(
      intersect(
        c("moda", "minimo", "maximo", "mediana", "media", "minimo_exacto",
          "maximo_exacto", "centinela_valor"),
        names(columnas)
      ),
      function(campo) {
        # Ni los de una columna de fechas ni sus centinelas: la misma regla que
        # en memoria (`.columna_de_fechas()`, `.rellenos_de_columna()`).
        cosecha <- indices & !(.nombres_para_operar(columnas$columna) %in%
                                 .nombres_para_operar(columnas_de_fechas))
        v <- as.character(columnas[[campo]][cosecha])
        v[!.recortar_bytes(v) %in% rellenos]
      }
    ), use.names = FALSE)
    # Los de la muestra ya pasaron por el piso: una fecha que quedo es de una
    # columna que no es de fechas.
  )), valores_muestra)
  # Lo que se tapa, por columna y metrica, para que `resumen_tabla$sql` lo
  # declare: ver abajo.
  tapadas <- list(data.frame(
    columna = as.character(columnas$columna[indices & !is.na(columnas$moda)]),
    metrica = rep("moda", sum(indices & !is.na(columnas$moda))),
    stringsAsFactors = FALSE
  ))
  columnas$moda[indices & !is.na(columnas$moda)] <- reemplazo
  # Los estadisticos de orden son valores reales de una celda. Los momentos
  # tambien identifican cuando la columna es un documento: la media de las
  # cedulas de una tabla chica reconstruye demasiado.
  # Y el desvio, como en `perfilar()`: la misma lista de
  # momentos (`.CAMPOS_MOMENTO_PROTEGIDOS`).
  campos <- intersect(
    c("minimo", "maximo", "mediana", .CAMPOS_MOMENTO_PROTEGIDOS),
    names(columnas)
  )
  # Se lleva aparte lo que se tapo de orden y de momento, para que el detalle
  # diga lo mismo que dice `perfilar()` sobre la misma columna: el motor escribia
  # siempre "estadisticos de orden y la media" aunque la media no estuviera, y la
  # comparacion entre las dos puertas marcaba el campo como distinto sin que la
  # proteccion lo fuera -medido en cuatro corridas-.
  oculto_orden <- rep(FALSE, nrow(columnas))
  oculto_media <- rep(FALSE, nrow(columnas))
  oculto_desvio <- rep(FALSE, nrow(columnas))
  tapar_campo <- function(campo, filas) {
    tapar <- filas & !is.na(columnas[[campo]])
    if (identical(campo, "desvio")) {
      oculto_desvio <<- oculto_desvio | tapar
    } else if (campo %in% .CAMPOS_MOMENTO_PROTEGIDOS) {
      oculto_media <<- oculto_media | tapar
    } else {
      oculto_orden <<- oculto_orden | tapar
    }
    tapadas[[length(tapadas) + 1L]] <<- data.frame(
      columna = as.character(columnas$columna[tapar]),
      metrica = rep(campo, sum(tapar)), stringsAsFactors = FALSE
    )
    columnas[[campo]][tapar] <<- NA_real_
  }
  for (campo in campos) tapar_campo(campo, indices)
  # Las columnas que COMPARTEN TIPO PERSONAL con una protegida -una copia
  # clasificada `documento_identidad` con poder discriminante debil- ya no se
  # tapan por esa sola razon. Se tapaban sus estadisticos de orden y sus
  # momentos porque por esta puerta el piso por valor no veia la tabla entera.
  # Ahora la ve -los valores de la muestra y, si la muestra no la
  # cubre, los de la tabla entera, o el cierre-, y la regla quedo tapando sin
  # proteger nada: los cinco estadisticos de un importe entero de siete cifras o
  # de un numero de factura, con el motivo falso de que la columna se protegio
  # como dato personal, mientras `perfilar()` los publicaba y el mismo objeto
  # tambien, en `perfil_muestra`. Lo que la sostenia -una copia
  # del documento- lo tapa el piso por valor; y la copia SIN su verificador la
  # clasifica la muestra como columna personal (`.copias_sin_verificador()`).
  # Y la otra publicacion de esos estadisticos: con `bloque_filas`,
  # `meta$familias` guarda por columna lo que devolvio cada acumulador -los
  # extremos, la media y el desvio en `cuantitativos`, y cada valor distinto
  # con su frecuencia en `distintos`- y salia entero: todas las cedulas y los
  # nombres de las columnas protegidas, y los extremos de una protegida de
  # valores cortos, que el piso por valor no busca. Se tapan con la misma
  # lista que la tabla de columnas, en las mismas columnas.
  resumen$meta$familias <- .proteger_familias_bloques_dbi(
    resumen$meta$familias,
    as.character(columnas$columna[indices]),
    campos
  )
  if (any(oculto_orden | oculto_media | oculto_desvio)) {
    if (!"detalle_proteccion_personal" %in% names(columnas)) {
      columnas$detalle_proteccion_personal <- NA_character_
    }
    detalle <- .detalle_proteccion_estadisticos(oculto_orden, oculto_media,
                                                oculto_desvio)
    columnas$detalle_proteccion_personal[!is.na(detalle)] <-
      detalle[!is.na(detalle)]
  }
  resumen$columnas <- columnas
  # El estado dice lo que se publico. Lo tapado quedaba `NA` -o "[valor
  # protegido]"- con `estado = calculado` y `motivo` NA en `resumen_tabla$sql`:
  # con `bloque_muestra = "solo_agregados"` y la proteccion por omision, el
  # `minimo`, el `maximo`, la `media` y la `mediana` de TODAS las columnas. Se
  # declara con el estado que el paquete ya usa cuando no se publica un valor
  # por privacidad. Tambien el `desvio`, como en
  # `perfilar()`.
  tapadas <- do.call(rbind, tapadas)
  if (is.data.frame(tapadas) && nrow(tapadas) && is.data.frame(resumen$sql) &&
      all(c("columna", "metrica", "estado", "motivo") %in% names(resumen$sql))) {
    sin_valor <- c("no_disponible", "no_aplica", "no_solicitado", "no_medido",
                   "omitido_por_costo", "omitido_por_privacidad")
    clave <- function(columna, metrica) {
      paste(.nombres_para_operar(as.character(columna)), metrica, sep = "\u001f")
    }
    filas <- clave(resumen$sql$columna, as.character(resumen$sql$metrica)) %in%
      clave(tapadas$columna, tapadas$metrica) &
      !(as.character(resumen$sql$estado) %in% sin_valor)
    if (any(filas)) {
      resumen$sql$estado[filas] <- "omitido_por_privacidad"
      resumen$sql$motivo[filas] <- if (identical(
        base_clasificacion, "sin_clasificacion_disponible"
      )) {
        paste(
          "Sin muestra no se pudo clasificar la columna como dato personal o",
          "no, y se protegi\u00f3 por omisi\u00f3n: el valor no se publica."
        )
      } else {
        paste(
          "La columna se protegi\u00f3 como dato personal: el valor no se publica",
          "(`detalle_proteccion_personal`)."
        )
      }
    }
  }
  # Y el piso sobre TODO el resumen, no solo sobre las columnas protegidas: un
  # valor identificante no se publica por ninguna puerta, tenga o no columna
  # atribuible, y tambien en los campos numericos.
  # Sin muestra no hay clasificacion y se cierran todas las columnas: es un
  # cierre, y un valor igual al nombre de la tabla no entra
  # (`.sin_nombres_de_estructura()`).
  if (identical(base_clasificacion, "sin_clasificacion_disponible")) {
    identificantes <- .sin_nombres_de_estructura(identificantes, nombres_tabla)
  }
  if (is.null(intocables)) intocables <- as.character(resumen$columnas$columna)
  if (length(identificantes)) {
    resumen <- .proteger_textos_salida(
      resumen, identificantes, intocables = intocables
    )
    columnas_antes <- resumen$columnas
    resumen <- .proteger_numeros_parametros(resumen, identificantes)
    resumen$columnas <- .tapar_derivados_del_piso(columnas_antes, resumen$columnas)
    resumen <- .tapar_familias_como_columnas_dbi(resumen, columnas_antes)
  }
  literales <- resumen$literales
  if (length(literales)) {
    filas_sensibles <- .nombres_para_operar(resumen$sql$columna) %in%
      .nombres_para_operar(sensibles)
    for (i in which(filas_sensibles)) {
      texto <- resumen$sql$sql[[i]]
      if (is.na(texto)) next
      for (literal in literales) {
        texto <- gsub(literal, "[literal protegido]", texto, fixed = TRUE)
      }
      resumen$sql$sql[[i]] <- texto
    }
  }
  # Y lo que el motivo de una columna protegida cita entre comillas: el valor que
  # el motor devolvio y R no pudo leer como numero. No pasa por el piso porque R
  # leyo ESA celda como otra cosa -una cedula "5.765.432-1" en una columna de
  # afinidad numerica-, y el motivo la publicaba en claro. Medido.
  if (is.data.frame(resumen$sql) && all(c("columna", "motivo") %in% names(resumen$sql))) {
    filas_sensibles <- .nombres_para_operar(resumen$sql$columna) %in%
      .nombres_para_operar(sensibles) & !is.na(resumen$sql$motivo)
    if (any(filas_sensibles)) {
      # Desde la primera comilla hasta la ultima: una cedula guardada con sus
      # comillas de CSV -`"5.765.432-1"`, citada como `""5.765.432-1""`-
      # dejaba el valor entre dos pares de comillas vacias. Medido.
      resumen$sql$motivo[filas_sensibles] <- sub(
        "\"(.*)\"", "\"[valor protegido]\"",
        resumen$sql$motivo[filas_sensibles], useBytes = TRUE
      )
    }
  }
  resumen
}

# `meta$familias` de la via por bloques en las columnas protegidas: en
# `cuantitativos`, los campos de `campos` -los de la tabla de columnas: los
# extremos, la mediana, la media, el desvio-; en `distintos`, cada valor
# distinto, que es un valor de celda, como la moda. Los conteos y las
# longitudes quedan, como en la tabla de columnas. Ver `.proteger_resumen_dbi()`.
.proteger_familias_bloques_dbi <- function(familias, columnas, campos) {
  if (!is.list(familias) || !length(familias) || !length(columnas)) {
    return(familias)
  }
  protegidas <- .nombres_para_operar(columnas)
  for (nombre in names(familias)) {
    if (!.nombres_para_operar(nombre) %in% protegidas) next
    if (!is.list(familias[[nombre]])) next
    for (familia in names(familias[[nombre]])) {
      sobre <- familias[[nombre]][[familia]]
      if (!is.list(sobre) || is.null(sobre[["resultado"]])) next
      resultado <- sobre[["resultado"]]
      if (identical(familia, "distintos") && is.data.frame(resultado) &&
          "representante" %in% names(resultado)) {
        representante <- resultado[["representante"]]
        resultado[["representante"]] <- if (is.numeric(representante) ||
                                             is.logical(representante)) {
          rep(NA, length(representante))
        } else rep("[valor protegido]", length(representante))
      } else if (identical(familia, "cuantitativos") && is.list(resultado)) {
        for (campo in intersect(campos, names(resultado))) {
          resultado[[campo]] <- rep(NA_real_, length(resultado[[campo]]))
        }
      }
      sobre[["resultado"]] <- resultado
      familias[[nombre]][[familia]] <- sobre
    }
  }
  familias
}

# ---- Bloque de la muestra ------------------------------------------------

# Un tipo que el controlador no puede traer en una lectura corriente: `TEXT`,
# `NTEXT`, `IMAGE`, los `MAX` de SQL Server, `CLOB`, `BLOB`, `BYTEA`. El caso
# que lo destapo es real: en una tabla de 158 columnas, 90 son de estos tipos, y
# el driver ODBC responde `07009` al leerlas.
# Tipos que muchos controladores no saben traer en una lectura corriente: hay
# que pedirlos aparte, o convertirlos, o no pedirlos. El nombre viene del motor
# ya sin espacios (ver mas abajo), asi que "nvarchar (max)" llega pegado.
#
# Este patron es un ATAJO, no la comprobacion. Reconocer el tipo ahorra el
# descarte, pero no reconocerlo no puede costar la muestra: quien decide es
# `.aislar_ilegibles_dbi()`, que le pregunta al motor.
.PATRON_TIPO_LARGO_DBI <- paste0(
  "^(text|ntext|image|clob|nclob|blob|bytea|longtext|mediumtext|tinytext|",
  "longblob|mediumblob|tinyblob|xml|xmltype|json|jsonb|geometry|geography|",
  "long|longraw|bfile|n?(var)?(char|binary)\\(max\\)|",
  "(sql_?)?w?longvar(char|binary))$"
)

# Un controlador no tiene por que informar el nombre del tipo. `odbc` resuelve
# `dbColumnInfo()` con `nanodbc::result::column_datatype()`, que devuelve el
# codigo numerico de ODBC: contra el driver `{SQL Server}` una tabla de noventa
# columnas `varchar(max)` llega como noventa veces "-1". Un patron de nombres
# reconoce cero de noventa, y esa es exactamente la tabla que motivo el
# reintento.
#   -1  SQL_LONGVARCHAR    -4  SQL_LONGVARBINARY    -10  SQL_WLONGVARCHAR
.CODIGOS_TIPO_LARGO_DBI <- c("-1", "-4", "-10")

.columnas_de_tipo_largo_dbi <- function(tipos) {
  if (is.null(tipos) || !length(tipos)) return(integer())
  limpio <- .minusculas_ascii(trimws(as.character(tipos)))
  limpio <- gsub("[[:space:]]+", "", limpio)
  which(!is.na(limpio) &
          (limpio %in% .CODIGOS_TIPO_LARGO_DBI |
             grepl(.PATRON_TIPO_LARGO_DBI, limpio, perl = TRUE)))
}

# Tope de sondas del descarte. Aislar por biseccion cuesta a lo sumo 2n-1
# sondas sobre n columnas -es el tamano del arbol cuando todas las hojas son
# culpables-, asi que 2n es "lo que alcanza en el peor caso" y no un numero
# elegido a dedo. El tope absoluto acota el costo cuando la tabla es enorme; si
# se agota, el aislamiento queda parcial y se declara.
.TOPE_SONDAS_DESCARTE_DBI <- 512L

# Averigua CUALES columnas impiden leer, en vez de adivinarlo por el nombre del
# tipo. Divide el conjunto en dos y baja solo por las mitades que siguen
# fallando: los subconjuntos que se leen bien se podan enteros.
#
# `sondear(indices)` devuelve TRUE si el motor entrega una fila con esas
# columnas. `hay_saldo()` se consulta ANTES de cada sonda: sin eso una sonda
# rechazada por presupuesto se leeria como "esta columna no se puede leer", que
# es una causa que nadie midio.
#
# Devuelve las columnas que fallan por si solas. Con
# `conservar_legibles = TRUE` tambien devuelve los grupos aceptados y las hojas
# que quedaron pendientes, para que un llamador que ya midio una sonda pueda
# reutilizarla sin volver a consultar. El camino de la muestra usa el valor por
# omision y conserva exactamente su salida y su presupuesto.
.aislar_ilegibles_dbi <- function(sondear, hay_saldo, n, tope,
                                  conservar_legibles = FALSE) {
  culpables <- integer()
  gastadas <- 0L
  agotado <- FALSE
  pendientes <- list(seq_len(n))
  legibles <- list()
  while (length(pendientes)) {
    if (gastadas >= tope || !isTRUE(hay_saldo())) {
      agotado <- TRUE
      break
    }
    grupo <- pendientes[[1L]]
    pendientes <- pendientes[-1L]
    gastadas <- gastadas + 1L
    if (isTRUE(sondear(grupo))) {
      if (isTRUE(conservar_legibles)) legibles[[length(legibles) + 1L]] <- grupo
      next
    }
    if (length(grupo) == 1L) {
      culpables <- c(culpables, grupo)
      next
    }
    corte <- length(grupo) %/% 2L
    pendientes <- c(
      list(grupo[seq_len(corte)]),
      list(grupo[(corte + 1L):length(grupo)]),
      pendientes
    )
  }
  salida <- list(
    culpables = .sort_por_bytes(culpables), sondas = gastadas, agotado = agotado
  )
  if (isTRUE(conservar_legibles)) {
    salida$legibles <- legibles
    salida$pendientes <- pendientes
  }
  salida
}

# Dos omisiones distintas no pueden contarse igual. El descarte COMPROBO que
# esas columnas no se leen: cada una fallo sola y el resto se leyo junto. El
# atajo por tipo solo las SUPUSO, porque el reintento se dispara ante cualquier
# fallo habiendo columnas de tipo largo declaradas, y un corte de red que se
# recupera en el segundo intento produciria el mismo camino. El texto lo dice
# distinto segun cual de los dos fue, y el motivo textual del motor viaja
# entero en los dos para que quien lea decida.
.motivo_omision_muestra_dbi <- function(tipo_omision, columnas, sondas, motivo_motor) {
  n <- length(columnas)
  lista <- paste(columnas, collapse = ", ")
  motor <- if (length(motivo_motor) != 1L || is.na(motivo_motor) ||
               !nzchar(as.character(motivo_motor))) {
    " El motor no inform\u00f3 un motivo."
  } else {
    paste0(" El motor dijo: ", as.character(motivo_motor), ".")
  }
  if (identical(tipo_omision, "descarte")) {
    paste0(
      "La lectura completa de la muestra fall\u00f3. Se aisl\u00f3 por descarte, con ",
      sondas, if (sondas == 1L) " sonda" else " sondas", " al motor, ",
      if (n == 1L) {
        "la columna que no se puede leer: "
      } else {
        paste0("las ", n, " columnas que no se pueden leer: ")
      },
      lista,
      ". Cada una fall\u00f3 por s\u00ed sola y el resto se ley\u00f3 junto.", motor
    )
  } else {
    paste0(
      "La lectura completa de la muestra fall\u00f3 y se reintent\u00f3 sin ",
      if (n == 1L) {
        "la columna de tipo largo declarada: "
      } else {
        paste0("las ", n, " columnas de tipo largo declaradas: ")
      },
      lista,
      ". No se comprob\u00f3 que sean la causa;", motor
    )
  }
}

.motivo_orden_ilegible_muestra_dbi <- function(columnas, motivo_motor) {
  motor <- if (length(motivo_motor) != 1L || is.na(motivo_motor) ||
               !nzchar(as.character(motivo_motor))) {
    " El motor no inform\u00f3 un motivo."
  } else {
    paste0(" El motor dijo: ", as.character(motivo_motor), ".")
  }
  paste0(
    "La lectura completa de la muestra fall\u00f3 al evaluar `orden_muestra`: ",
    "no se pudo aplicar el orden con ", paste(columnas, collapse = ", "),
    ". La muestra recuperada se ley\u00f3 sin ese orden.", motor
  )
}

# `constante` afirma que la columna tiene un unico valor no ausente. Sobre una
# muestra esa afirmacion no se puede sostener: basta una fila no leida para
# desmentirla, y una tabla de 200 filas con tres valores donde 50 filas traen
# uno solo produce exactamente ese hallazgo. Es el caso que separa una
# proporcion de una universal: `prop_faltantes` estimada sobre la muestra sigue
# siendo una estimacion honesta de la tabla, pero "un unico valor" es una
# cuantificacion universal y la muestra no la alcanza.
#
# El hallazgo no se apaga: se traslada a `cobertura_diagnosticos`, con el
# tamano de la muestra y el de la tabla, para que quede escrito que se dejo de
# decir y por que.
.constante_no_medible_en_muestra_dbi <- function(perfil, muestreo) {
  if (is.null(perfil) || isTRUE(muestreo$tabla_completa)) return(perfil)
  hallazgos <- perfil$hallazgos
  if (is.null(hallazgos) || !nrow(hallazgos)) return(perfil)
  sobra <- as.character(hallazgos$tipo_hallazgo) == "constante"
  if (!any(sobra)) return(perfil)
  filas <- .entero_sql_dbi(muestreo$filas_obtenidas)
  total <- .entero_sql_dbi(muestreo$filas_totales_fuente)
  nuevas <- do.call(rbind, lapply(which(sobra), function(i) {
    .nuevo_diagnostico_no_evaluado(
      "constante", as.character(hallazgos$columna[[i]]),
      paste0(
        "No se evalu\u00f3 si la columna es constante: el perfil describe ", filas,
        if (filas == 1L) " fila de las " else " filas de las ", total, " de la tabla. En la muestra se observ\u00f3 un ",
        "\u00fanico valor, y eso no prueba que sea el \u00fanico de la tabla."
      ),
      paste(
        "Perfilar la tabla completa, o contar los valores distintos con",
        "`resumen_tabla_dbi()`, que los mide sobre todas las filas."
      )
    )
  }))
  perfil$hallazgos <- hallazgos[!sobra, , drop = FALSE]
  rownames(perfil$hallazgos) <- NULL
  cobertura <- perfil$cobertura_diagnosticos
  perfil$cobertura_diagnosticos <- if (is.null(cobertura) || !nrow(cobertura)) {
    nuevas
  } else {
    rbind(cobertura, nuevas)
  }
  rownames(perfil$cobertura_diagnosticos) <- NULL
  perfil
}

.prototipo_campo_muestra_dbi <- function(prototipo, campo, posicion) {
  .atributo_columna_dbi(prototipo, campo, posicion)
}

# Los tipos, el prototipo y el nombre de una columna forman una sola unidad.
# Los nombres permiten recuperar esa unidad aunque una etapa haya quitado una
# columna intermedia; el argumento posicional queda como respaldo para los
# controladores que no entregan nombres en el esquema.
.atributo_columna_dbi <- function(atributos, columna, posicion = NA_integer_) {
  if (is.null(atributos) || !length(atributos)) return(NULL)
  indice <- if (length(names(atributos))) {
    .indice_nombre(columna, names(atributos))
  } else posicion
  if (length(indice) != 1L || is.na(indice) || indice < 1L ||
      indice > length(atributos)) {
    return(NULL)
  }
  atributos[[indice]]
}

.alinear_atributos_columnas_dbi <- function(campos, prototipo = NULL,
                                            tipos = NULL,
                                            tipos_motor = NULL) {
  alinear <- function(atributos) {
    if (is.null(atributos)) return(NULL)
    nombres <- names(atributos)
    posiciones <- if (length(nombres)) {
      .indice_nombre(campos, nombres)
    } else rep(NA_integer_, length(campos))
    salida <- if (length(nombres) && any(!is.na(posiciones))) {
      atributos[posiciones]
    } else {
      atributos[seq_len(min(length(atributos), length(campos)))]
    }
    if (length(salida) < length(campos)) length(salida) <- length(campos)
    names(salida) <- campos
    salida
  }
  list(
    prototipo = alinear(prototipo),
    tipos = alinear(tipos),
    tipos_motor = alinear(tipos_motor)
  )
}

.conexion_entrega_bigint_como_doble_dbi <- function(conexion) {
  bigint <- attr(conexion, "bigint", exact = TRUE)
  if (is.null(bigint) || !length(bigint) || is.na(bigint[[1L]])) {
    informacion <- tryCatch(.info_dbi_corrida(conexion), error = function(e) NULL)
    bigint <- if (is.null(informacion)) NULL else informacion$bigint
  }
  if (is.null(bigint) || !length(bigint) || is.na(bigint[[1L]])) {
    return(FALSE)
  }
  identical(.minusculas_ascii(as.character(bigint[[1L]])), "numeric")
}

.tipo_base_muestra_dbi <- function(tipo) {
  if (length(tipo) != 1L || is.na(tipo)) return(NA_character_)
  limpio <- .minusculas_ascii(trimws(as.character(tipo)))
  limpio <- sub("\\s*\\(.*$", "", limpio, perl = TRUE)
  limpio
}

.es_tipo_binario_muestra_dbi <- function(tipo, senas) {
  base <- .tipo_base_muestra_dbi(tipo)
  !is.na(base) && base %in% c(
    "bytea", "binary", "varbinary", "image", "tinyblob", "blob",
    "mediumblob", "longblob"
  ) && grepl(
    "postgres|pqconnection|sql server|microsoft sql|sqlserver|mssql|mysql|mariadb",
    senas, perl = TRUE
  )
}

.es_tipo_texto_largo_muestra_dbi <- function(tipo) {
  base <- .tipo_base_muestra_dbi(tipo)
  !is.na(base) && base %in% c(
    "text", "varchar", "character varying", "character", "char", "bpchar",
    "nvarchar", "nchar", "ntext", "xml", "clob", "varchar2", "nvarchar2",
    "tinytext", "mediumtext", "longtext", "citext"
  )
}

.bytes_maximos_campo_muestra_dbi <- function(tipo, es_binario, es_texto,
                                             max_largo) {
  if (isTRUE(es_texto) && is.finite(max_largo)) {
    # El controlador entrega texto UTF-8: cuatro bytes por caracter es una
    # cota conservadora para decidir el fetch antes de ver los valores.
    return(as.numeric(max_largo) * 4 + 128)
  }
  if (isTRUE(es_binario)) return(256)
  base <- .tipo_base_muestra_dbi(tipo)
  if (!is.na(base) && base %in% c(
    "smallint", "integer", "int", "int2", "int4", "int8", "bigint",
    "serial", "bigserial", "tinyint", "smallint", "float", "float4",
    "float8", "double", "double precision", "real", "numeric", "decimal",
    "money", "smallmoney", "date", "datetime", "datetime2", "timestamp",
    "timestamptz", "time", "boolean", "bit"
  )) return(128)
  # Para un tipo que el catalogo no describe no hay una cota segura antes del
  # fetch; el materializador sondea una fila y mide su representacion.
  Inf
}

.expresion_binaria_muestra_dbi <- function(
    expr, alias, senas, prefijo = FALSE) {
  if (grepl("postgres|pqconnection", senas, perl = TRUE)) {
    return(paste0(
      "CASE WHEN ", expr, " IS NULL THEN NULL ELSE CAST(octet_length(",
      expr, ") AS text) || ':' || md5(", expr, ") END AS ", alias
    ))
  }
  if (grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas, perl = TRUE
  )) {
    expr_binario <- paste0("CONVERT(varbinary(max), ", expr, ")")
    resumen <- if (isTRUE(prefijo)) {
      paste0(
        "HASHBYTES('MD5', CONVERT(varbinary(8000), SUBSTRING(",
        expr_binario, ", 1, 8000)))"
      )
    } else {
      paste0("HASHBYTES('MD5', ", expr_binario, ")")
    }
    return(paste0(
      "CASE WHEN ", expr, " IS NULL THEN NULL ELSE CONVERT(varchar(30),",
      " DATALENGTH(", expr, ")) + ':' + LOWER(CONVERT(varchar(64),",
      " ", resumen, ", 2)) END AS ", alias
    ))
  }
  paste0(
    "CASE WHEN ", expr, " IS NULL THEN NULL ELSE CONCAT(OCTET_LENGTH(",
    expr, "), ':', MD5(", expr, ")) END AS ", alias
  )
}

.proyeccion_binaria_muestra_dbi <- function(
    conexion, campos, campos_sql, tipos_declarados = NULL,
    tipos_motor = NULL, version_sqlserver = NA_real_) {
  senas <- .senas_conexion_dbi(conexion)
  motor_binario <- grepl(
    "postgres|pqconnection|sql server|microsoft sql|sqlserver|mssql|mysql|mariadb",
    senas, perl = TRUE
  )
  tipos <- if (!is.null(tipos_motor) && length(tipos_motor) == length(campos)) {
    as.character(tipos_motor)
  } else if (is.null(tipos_declarados)) {
    rep(NA_character_, length(campos))
  } else vapply(tipos_declarados, function(x) {
    if (length(x) && !is.na(x[[1L]])) as.character(x[[1L]]) else NA_character_
  }, character(1L))
  binarios <- vapply(seq_along(campos), function(i) {
    tipo <- .atributo_columna_dbi(tipos, campos[[i]], i) %||% NA_character_
    motor_binario && .es_tipo_binario_muestra_dbi(tipo, senas)
  }, logical(1L))
  version_sqlserver <- suppressWarnings(as.numeric(version_sqlserver))
  version_sqlserver <- if (length(version_sqlserver)) {
    version_sqlserver[[1L]]
  } else NA_real_
  binarios_prefijo <- binarios & grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas, perl = TRUE
  ) & (is.na(version_sqlserver) || version_sqlserver < 13)
  expresiones <- campos_sql
  if (any(binarios)) {
    expresiones[binarios] <- vapply(which(binarios), function(i) {
      expr <- .citar_identificador_dbi(conexion, campos[[i]])
      alias <- .citar_identificador_dbi(conexion, campos[[i]])
      .expresion_binaria_muestra_dbi(
        expr, alias, senas, prefijo = binarios_prefijo[[i]]
      )
    }, character(1L))
  }
  list(
    campos_sql = expresiones, tipos = tipos, motor_binario = motor_binario,
    binarios = binarios,
    columnas_binarias = as.character(campos[binarios]),
    columnas_binarias_prefijo = as.character(campos[binarios_prefijo])
  )
}

.campos_sql_muestra_dbi <- function(
    conexion, campos, campos_sql, prototipo, tipos_declarados, dialecto,
    tipos_motor = NULL, version_sqlserver = NA_real_,
    max_largo_valor_vocabulario = .MAX_LARGO_VALOR_CASI_DUPLICADOS) {
  vacia <- list(
    campos_sql = campos_sql, columnas_castadas = character(),
    columnas_binarias = character(), columnas_binarias_prefijo = character(),
    columnas_texto_largo = character(), bytes_por_fila_max = Inf,
    max_largo_valor_vocabulario = max_largo_valor_vocabulario,
    version_sqlserver = NA_real_
  )
  if (is.null(dialecto$cast_entero_ancho_texto)) {
    return(vacia)
  }
  castadas <- vapply(seq_along(campos), function(i) {
    prototipo_campo <- .prototipo_campo_muestra_dbi(
      prototipo, campos[[i]], i
    )
    tipo <- .atributo_columna_dbi(tipos_declarados, campos[[i]], i) %||%
      NA_character_
    prototipo_doble <- (is.double(prototipo_campo) ||
      (is.integer(prototipo_campo) &&
        .conexion_entrega_bigint_como_doble_dbi(conexion))) &&
      !inherits(prototipo_campo, "integer64")
    (.tipo_declarado_entero_ancho_dbi(tipo) ||
      .tipo_declarado_decimal_dbi(tipo)) &&
      prototipo_doble
  }, logical(1L))
  expresiones <- campos_sql
  if (any(castadas)) {
    expresiones[castadas] <- vapply(which(castadas), function(i) {
      dialecto$cast_entero_ancho_texto(
        campos_sql[[i]], campos_sql[[i]], conexion,
        tipo = .atributo_columna_dbi(tipos_motor, campos[[i]], i) %||%
          NA_character_
      )
    }, character(1L))
  }
  senas <- .senas_conexion_dbi(conexion)
  binaria <- .proyeccion_binaria_muestra_dbi(
    conexion, campos, expresiones, tipos_declarados, tipos_motor,
    version_sqlserver = version_sqlserver
  )
  expresiones <- binaria$campos_sql
  motor_binario <- binaria$motor_binario
  motor_texto <- motor_binario && (
    !grepl("sql server|microsoft sql|sqlserver|mssql", senas, perl = TRUE) ||
      identical(as.character(dialecto$nombre), "top")
  )
  tipos <- binaria$tipos
  binarios <- binaria$binarios
  max_largo <- suppressWarnings(as.numeric(max_largo_valor_vocabulario))
  textos_largos <- vapply(seq_along(campos), function(i) {
    motor_texto && !binarios[[i]] &&
      .es_tipo_texto_largo_muestra_dbi(
        .atributo_columna_dbi(tipos, campos[[i]], i) %||% NA_character_
      ) &&
      is.finite(max_largo) && max_largo > 0
  }, logical(1L))
  if (any(textos_largos)) {
    expresiones[textos_largos] <- vapply(which(textos_largos), function(i) {
      expr <- .citar_identificador_dbi(conexion, campos[[i]])
      alias <- .citar_identificador_dbi(conexion, campos[[i]])
      fuente <- sub(
        "\\s+AS\\s+(?:\"(?:\"\"|[^\"])*\"|\\[(?:\\]\\]|[^]])*\\]|`(?:``|[^`])*`|[^[:space:]]+)\\s*$",
        "", campos_sql[[i]], perl = TRUE
      )
      tipo <- .tipo_base_muestra_dbi(
        .atributo_columna_dbi(tipos, campos[[i]], i) %||% NA_character_
      )
      if (grepl("postgres|pqconnection", senas, perl = TRUE)) {
        paste0(
          "CASE WHEN ", expr, " IS NULL THEN NULL WHEN CHAR_LENGTH(",
          expr, ") > ", format(max_largo, scientific = FALSE, trim = TRUE),
          " THEN 'lupa_texto_largo:' || CHAR_LENGTH(", expr,
          ") || ':' || OCTET_LENGTH(", expr, ") || ':' || MD5(", expr,
          ") ELSE ", fuente, " END AS ", alias
        )
      } else if (grepl(
        "sql server|microsoft sql|sqlserver|mssql", senas, perl = TRUE
      )) {
        unicode <- tipo %in% c("nvarchar", "nchar", "ntext")
        # SQL Server conserva los espacios de relleno de CHAR/NCHAR al
        # convertirlos a varchar/nvarchar. La muestra y la tabla completa
        # deben agrupar el mismo valor textual que entregan los otros motores.
        expr_texto <- if (tipo %in% c("char", "nchar")) {
          paste0("RTRIM(", expr, ")")
        } else expr
        texto <- if (unicode) {
          paste0("CONVERT(nvarchar(max), ", expr_texto, ")")
        } else {
          paste0("CONVERT(varchar(max), ", expr_texto, ")")
        }
        bytes <- paste0("DATALENGTH(", expr, ")")
        chars <- if (unicode) paste0("DATALENGTH(", expr, ") / 2") else bytes
        hash_text <- if (tipo %in% c("text", "ntext", "xml")) texto else expr
        hash_bytes <- paste0("CONVERT(varbinary(max), ", hash_text, ")")
        version_antigua <- is.na(version_sqlserver) || version_sqlserver < 13
        resumen <- if (isTRUE(version_antigua)) {
          paste0(
            "HASHBYTES('MD5', CONVERT(varbinary(8000), SUBSTRING(",
            hash_bytes, ", 1, 8000)))"
          )
        } else {
          paste0("HASHBYTES('MD5', ", hash_bytes, ")")
        }
        paste0(
          "CASE WHEN ", expr, " IS NULL THEN NULL WHEN ", chars, " > ",
          format(max_largo, scientific = FALSE, trim = TRUE),
          " THEN 'lupa_texto_largo:' + CONVERT(varchar(30), ", chars,
          ") + ':' + CONVERT(varchar(30), ", bytes,
          ") + ':' + LOWER(CONVERT(varchar(64), ", resumen,
          ", 2)) ELSE ", texto, " END AS ", alias
        )
      } else if (grepl("mysql|mariadb", senas, perl = TRUE)) {
        paste0(
          "CASE WHEN ", expr, " IS NULL THEN NULL WHEN CHAR_LENGTH(",
          expr, ") > ", format(max_largo, scientific = FALSE, trim = TRUE),
          " THEN CONCAT('lupa_texto_largo:', CHAR_LENGTH(", expr,
          "), ':', OCTET_LENGTH(", expr, "), ':', MD5(", expr,
          ")) ELSE ", fuente, " END AS ", alias
        )
      } else {
        fuente
      }
    }, character(1L))
  }
  maximos <- vapply(seq_along(campos), function(i) {
    .bytes_maximos_campo_muestra_dbi(
      .atributo_columna_dbi(tipos, campos[[i]], i) %||% NA_character_,
      binarios[[i]], textos_largos[[i]], max_largo
    )
  }, numeric(1L))
  bytes_fila <- if (length(maximos) && all(is.finite(maximos))) {
    sum(maximos) + max(4096, 128 * length(maximos))
  } else Inf
  list(
    campos_sql = expresiones,
    columnas_castadas = as.character(campos[castadas]),
    columnas_binarias = binaria$columnas_binarias,
    columnas_binarias_prefijo = binaria$columnas_binarias_prefijo,
    columnas_texto_largo = as.character(campos[textos_largos]),
    bytes_por_fila_max = bytes_fila,
    max_largo_valor_vocabulario = max_largo_valor_vocabulario,
    version_sqlserver = version_sqlserver
  )
}

# La moda de una columna binaria se pide en la misma representacion que la
# muestra -largo y MD5, en minusculas en todos los motores-: asi la
# corroboracion compara el mismo valor, y la misma tabla en dos motores publica
# la misma moda. `HASHBYTES()` de SQL Server da el MD5 en mayusculas.
.expresion_binaria_moda_dbi <- function(
    conexion, columna_sql, tipo, version_sqlserver = NULL) {
  senas <- .senas_conexion_dbi(conexion)
  if (!.es_tipo_binario_muestra_dbi(tipo, senas)) return(columna_sql)
  if (grepl("postgres|pqconnection", senas, perl = TRUE)) {
    return(paste0(
      "CASE WHEN ", columna_sql, " IS NULL THEN NULL ELSE CAST(octet_length(",
      columna_sql, ") AS text) || ':' || md5(", columna_sql, ") END"
    ))
  }
  if (grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas, perl = TRUE
  )) {
    binario <- paste0("CONVERT(varbinary(max), ", columna_sql, ")")
    version <- if (is.null(version_sqlserver)) {
      .version_servidor_sqlserver_dbi(conexion)
    } else {
      suppressWarnings(as.numeric(version_sqlserver[[1L]]))
    }
    version_antigua <- length(version) != 1L || is.na(version) || version < 13
    resumen <- if (isTRUE(version_antigua)) {
      paste0(
        "HASHBYTES('MD5', CONVERT(varbinary(8000), SUBSTRING(",
        binario, ", 1, 8000)))"
      )
    } else {
      paste0("HASHBYTES('MD5', ", binario, ")")
    }
    return(paste0(
      "CASE WHEN ", columna_sql, " IS NULL THEN NULL ELSE CONVERT(varchar(30),",
      " DATALENGTH(", columna_sql, ")) + ':' + LOWER(CONVERT(varchar(64),",
      " ", resumen, ", 2)) END"
    ))
  }
  paste0(
    "CASE WHEN ", columna_sql, " IS NULL THEN NULL ELSE CONCAT(OCTET_LENGTH(",
    columna_sql, "), ':', MD5(", columna_sql, ")) END"
  )
}

# El motor agrupa el decimal exacto, pero el controlador puede convertir el
# valor seleccionado a doble antes de que `lupa` lo lea. Se separan ambas
# expresiones: `columna_sql` sigue gobernando `GROUP BY` y el desempate, y esta
# devuelve el grupo como texto exacto. Para la moda no hace falta una consulta
# adicional y el texto conserva tambien la escala declarada por el motor.
.expresion_decimal_moda_dbi <- function(conexion, columna_sql, tipo,
                                        entero_doble = FALSE) {
  decimal <- .tipo_declarado_decimal_dbi(tipo)
  if (!decimal && !isTRUE(entero_doble)) return(columna_sql)
  senas <- .senas_conexion_dbi(conexion)
  if (isTRUE(entero_doble)) {
    if (grepl("postgres|pqconnection", senas, perl = TRUE)) {
      return(paste0("CAST(", columna_sql, " AS text)"))
    }
    if (grepl(
      "sql server|microsoft sql|sqlserver|mssql", senas,
      perl = TRUE
    )) {
      return(paste0("CONVERT(varchar(100), ", columna_sql, ")"))
    }
    if (grepl("mysql|mariadb", senas, perl = TRUE)) {
      return(paste0("CAST(", columna_sql, " AS CHAR)"))
    }
    if (grepl("duckdb", senas, fixed = TRUE, useBytes = TRUE)) {
      return(paste0("CAST(", columna_sql, " AS VARCHAR)"))
    }
    # SQLite y los adaptadores que siguen la sintaxis de CAST aceptan TEXT;
    # si el motor no la acepta, la llamada la degrada a no_disponible y no
    # publica el doble redondeado.
    if (grepl("sqlite", senas, fixed = TRUE, useBytes = TRUE)) {
      return(paste0("CAST(", columna_sql, " AS TEXT)"))
    }
    return(NA_character_)
  }
  if (grepl("postgres|pqconnection", senas, perl = TRUE)) {
    texto <- paste0("CAST(", columna_sql, " AS text)")
    return(paste0(
      "CASE WHEN POSITION('.' IN ", texto, ") > 0 THEN ",
      "TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM ", texto,
      ")) ELSE ", texto, " END"
    ))
  }
  if (grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas,
    perl = TRUE
  )) {
    texto <- paste0("CONVERT(varchar(100), ", columna_sql, ")")
    punto <- paste0("CHARINDEX('.', ", texto, ")")
    fraccion <- paste0(
      "SUBSTRING(", texto, ", ", punto, " + 1, LEN(", texto, "))"
    )
    fraccion_sin_ceros <- paste0(
      "CASE WHEN PATINDEX('%[1-9]%', ", fraccion, ") = 0 THEN '' ELSE ",
      "LEFT(", fraccion, ", LEN(", fraccion, ") - PATINDEX('%[^0]%', ",
      "REVERSE(", fraccion, ")) + 1) END"
    )
    return(paste0(
      "CASE WHEN ", punto, " > 0 THEN LEFT(", texto, ", ", punto,
      " - 1) + CASE WHEN ", fraccion_sin_ceros, " = '' THEN '' ELSE '.' + ",
      fraccion_sin_ceros, " END ELSE ", texto, " END"
    ))
  }
  if (grepl("mysql|mariadb", senas, perl = TRUE)) {
    texto <- paste0("CAST(", columna_sql, " AS CHAR)")
    return(paste0(
      "CASE WHEN INSTR(", texto, ", '.') > 0 THEN ",
      "TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM ", texto,
      ")) ELSE ", texto, " END"
    ))
  }
  if (grepl("duckdb", senas, perl = TRUE)) {
    texto <- paste0("CAST(", columna_sql, " AS VARCHAR)")
    return(paste0(
      "CASE WHEN POSITION('.' IN ", texto, ") > 0 THEN ",
      "TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM ", texto,
      ")) ELSE ", texto, " END"
    ))
  }
  columna_sql
}

.orden_moda_dbi <- function(conexion, valor_sql, tipo,
                            orden_numerico_sql = NULL) {
  senas <- .senas_conexion_dbi(conexion)
  if (isTRUE(.tipo_declarado_entero_ancho_dbi(tipo)) &&
      length(orden_numerico_sql) == 1L && !is.na(orden_numerico_sql) &&
      nzchar(orden_numerico_sql)) {
    return(as.character(orden_numerico_sql))
  }
  if (!.es_tipo_binario_muestra_dbi(tipo, senas)) return(valor_sql)
  if (grepl("postgres|pqconnection", senas, perl = TRUE)) {
    return(paste0("convert_to(", valor_sql, ", 'UTF8')"))
  }
  if (grepl(
    "sql server|microsoft sql|sqlserver|mssql", senas,
    perl = TRUE, useBytes = TRUE
  )) {
    return(paste0("(", valor_sql, ") COLLATE Latin1_General_100_BIN2"))
  }
  if (.es_mysql_dbi(senas)) {
    # `valor_sql` ya es la representacion canonica (largo:hash). Volver a
    # castear la expresion en ORDER BY rompe `ONLY_FULL_GROUP_BY` porque el
    # servidor deja de reconocerla como la misma expresion agrupada.
    return(valor_sql)
  }
  paste0("CAST(", valor_sql, " AS BLOB)")
}

.ajustar_longitudes_binarias_dbi <- function(perfil, datos,
                                             columnas_binarias,
                                             columnas_binarias_prefijo = character()) {
  if (!is.list(perfil) || !is.data.frame(perfil$columnas) ||
      !length(columnas_binarias) || !is.data.frame(datos)) {
    return(perfil)
  }
  binarias <- intersect(as.character(columnas_binarias), names(datos))
  for (columna in binarias) {
    valores <- as.character(datos[[columna]])
    captura <- regmatches(
      valores, regexec("^([0-9]+):", valores, perl = TRUE)
    )
    largos <- suppressWarnings(as.numeric(vapply(captura, function(x) {
      if (length(x) > 1L) x[[2L]] else NA_character_
    }, character(1L))))
    largos <- largos[is.finite(largos)]
    posicion <- match(columna, as.character(perfil$columnas$columna))
    if (is.na(posicion)) next
    # La muestra trae el largo y el MD5 como texto, y `perfilar()` describe ese
    # texto: la columna salia `texto` y con el Unicode evaluado. La columna es
    # binaria, como la declaraba la lectura del contenido.
    for (campo in intersect(c("tipo_declarado", "tipo_inferido"),
                            names(perfil$columnas))) {
      perfil$columnas[[campo]][[posicion]] <- "blob"
    }
    for (campo in intersect(c("n_variantes_unicode", "unicode_evaluado"),
                            names(perfil$columnas))) {
      perfil$columnas[[campo]][[posicion]] <- NA
    }
    if (!length(largos)) next
    if ("longitud_minima" %in% names(perfil$columnas)) {
      perfil$columnas$longitud_minima[[posicion]] <- min(largos)
    }
    if ("longitud_maxima" %in% names(perfil$columnas)) {
      perfil$columnas$longitud_maxima[[posicion]] <- max(largos)
    }
    if ("longitud_media" %in% names(perfil$columnas)) {
      perfil$columnas$longitud_media[[posicion]] <- mean(largos)
    }
    if ("n_longitudes_resumidas" %in% names(perfil$columnas)) {
      perfil$columnas$n_longitudes_resumidas[[posicion]] <-
        length(unique(largos))
    }
  }
  # Un resumen MD5 es distinto para cada contenido distinto: que casi todos lo
  # sean no dice nada de la columna, y sobre el contenido binario `perfilar()`
  # no lo informa.
  hallazgos <- perfil$hallazgos
  if (length(binarias) && is.data.frame(hallazgos) && nrow(hallazgos) &&
      all(c("columna", "tipo_hallazgo") %in% names(hallazgos))) {
    quitar <- .nombres_presentes(hallazgos$columna, binarias) &
      as.character(hallazgos$tipo_hallazgo) %in% "alta_cardinalidad"
    if (any(quitar)) {
      hallazgos <- hallazgos[!quitar, , drop = FALSE]
      rownames(hallazgos) <- NULL
      perfil$hallazgos <- hallazgos
    }
  }
  perfil$meta$columnas_binarias <- as.character(columnas_binarias)
  perfil$meta$representacion_binaria <- paste(
    "La muestra conserva NULL, largo y un resumen MD5; no trae el contenido binario."
  )
  if (length(columnas_binarias_prefijo)) {
    perfil$meta$representacion_binaria <- paste(
      perfil$meta$representacion_binaria,
      "Para SQL Server anterior a 13, o cuando la versi\u00f3n no se pudo saber,",
      "el MD5 usa s\u00f3lo el prefijo de 8000 bytes y conserva el largo completo."
    )
    perfil$meta$columnas_binarias_prefijo <- as.character(
      columnas_binarias_prefijo
    )
  }
  perfil
}

.extraer_textos_largos_dbi <- function(valores) {
  valores <- as.character(valores)
  capturas <- regmatches(valores, regexec(
    "^lupa_texto_largo:([0-9]+):([0-9]+):([0-9A-Fa-f]{32})$",
    valores, perl = TRUE
  ))
  es_largo <- vapply(capturas, function(x) length(x) == 4L, logical(1L))
  caracteres <- rep(NA_real_, length(valores))
  bytes <- rep(NA_real_, length(valores))
  if (any(es_largo)) {
    caracteres[es_largo] <- suppressWarnings(as.numeric(vapply(
      capturas[es_largo], `[[`, character(1L), 2L
    )))
    bytes[es_largo] <- suppressWarnings(as.numeric(vapply(
      capturas[es_largo], `[[`, character(1L), 3L
    )))
  }
  list(es_largo = es_largo, caracteres = caracteres, bytes = bytes)
}

.ajustar_textos_largos_dbi <- function(perfil, datos, columnas_texto_largo,
                                       max_largo = .MAX_LARGO_VALOR_CASI_DUPLICADOS) {
  if (!is.list(perfil) || !is.data.frame(perfil$columnas) ||
      !length(columnas_texto_largo) || !is.data.frame(datos)) {
    return(perfil)
  }
  cobertura <- perfil$cobertura_diagnosticos
  if (!is.data.frame(cobertura)) cobertura <- .cobertura_diagnosticos_vacia()
  for (columna in intersect(as.character(columnas_texto_largo), names(datos))) {
    valores <- datos[[columna]]
    extraidos <- .extraer_textos_largos_dbi(valores)
    largos <- ifelse(
      extraidos$es_largo, extraidos$caracteres,
      suppressWarnings(nchar(as.character(valores), type = "chars"))
    )
    validos <- !is.na(valores) & is.finite(largos)
    largos <- largos[validos]
    posicion <- match(columna, as.character(perfil$columnas$columna))
    if (is.na(posicion) || !length(largos)) next
    if ("longitud_minima" %in% names(perfil$columnas)) {
      perfil$columnas$longitud_minima[[posicion]] <- min(largos)
    }
    if ("longitud_maxima" %in% names(perfil$columnas)) {
      perfil$columnas$longitud_maxima[[posicion]] <- max(largos)
    }
    if ("longitud_media" %in% names(perfil$columnas)) {
      perfil$columnas$longitud_media[[posicion]] <- mean(largos)
    }
    if ("n_longitudes_resumidas" %in% names(perfil$columnas)) {
      perfil$columnas$n_longitudes_resumidas[[posicion]] <- length(unique(largos))
    }
    largos_largos <- extraidos$bytes[extraidos$es_largo &
                                      is.finite(extraidos$bytes)]
    if (length(largos_largos)) {
      cobertura <- rbind(cobertura, .nuevo_diagnostico_no_evaluado(
        "texto_largo_no_evaluado", columna,
        paste0(
          "No se evaluaron ", length(largos_largos),
          if (length(largos_largos) == 1L) {
            " valor de texto que supera `max_largo_valor_vocabulario = "
          } else {
            " valores de texto que superan `max_largo_valor_vocabulario = "
          },
          max_largo, ": hasta ", max(largos_largos),
          " bytes. Se conservaron los conteos, duplicados y longitudes."
        ),
        paste0(
          "Subir `max_largo_valor_vocabulario` si esos valores deben entrar",
          " en los diagn\u00f3sticos textuales, o usar `Inf` expl\u00edcitamente."
        ), dependencia = NA_character_, columnas = columna
      ))
      cobertura <- do.call(rbind, c(list(cobertura), .filas_dependientes_texto_largo(
        columna, .diagnosticos_afectados_texto_largo(columna)
      )))
    }
  }
  perfil$cobertura_diagnosticos <- cobertura
  perfil$meta$columnas_texto_largo <- as.character(columnas_texto_largo)
  perfil$meta$representacion_texto_largo <- paste(
    "Los valores largos conservan caracteres, bytes y resumen MD5; no se",
    "trae su contenido completo al cliente."
  )
  perfil
}

.convertir_enteros_ancho_muestra_dbi <- function(
    datos, columnas_castadas, tipos_declarados = NULL) {
  cobertura <- .cobertura_diagnosticos_vacia()
  if (!is.data.frame(datos) || !length(columnas_castadas)) {
    return(list(datos = datos, cobertura = cobertura))
  }
  for (columna in intersect(columnas_castadas, names(datos))) {
    posicion <- match(columna, names(datos))
    tipo <- .atributo_columna_dbi(
      tipos_declarados, columna, posicion
    ) %||% NA_character_
    es_decimal <- .tipo_declarado_decimal_dbi(tipo)
    if (.bit64_disponible_dbi()) {
      texto <- as.character(datos[[posicion]])
      convertido <- tryCatch(
        suppressWarnings(bit64::as.integer64(texto)),
        error = function(e) NULL
      )
      texto_convertido <- if (!is.null(convertido)) {
        tryCatch(
          bit64::as.character.integer64(convertido),
          error = function(e) NULL
        )
      } else {
        NULL
      }
      conversion_exacta <- !is.null(convertido) &&
        !is.null(texto_convertido) &&
        length(texto_convertido) == length(texto) &&
        all(
          (is.na(texto) & is.na(texto_convertido)) |
            (!is.na(texto) & !is.na(texto_convertido) &
               texto == texto_convertido)
        )
      if (isTRUE(conversion_exacta)) {
        cabe_entero <- all(
          is.na(convertido) |
            (convertido >= -2147483648 & convertido <= 2147483647)
        )
        datos[[posicion]] <- if (isTRUE(cabe_entero)) {
          as.integer(convertido)
        } else {
          convertido
        }
        next
      }
      texto_no_entero <- !is.na(texto) &
        !grepl("^[+-]?[0-9]+$", texto, perl = TRUE)
      if (es_decimal && any(texto_no_entero)) {
        convertido_decimal <- suppressWarnings(as.numeric(texto))
        if (all(is.na(texto) | !is.na(convertido_decimal))) {
          datos[[posicion]] <- convertido_decimal
          next
        }
      }
      motivo <- paste0(
        "No se pudo convertir a `integer64` la columna `", columna,
        "` que se trajo como texto; la columna queda como texto."
      )
    } else {
      motivo <- paste0(
        "La columna `", columna,
        "` se trajo como texto para conservar los d\u00edgitos exactos, pero",
        " falta el paquete opcional `bit64` para convertirla a `integer64`."
      )
    }
    cobertura <- rbind(
      cobertura,
      .nuevo_diagnostico_no_evaluado(
        "entero64_como_texto", columna, motivo,
        paste(
          "Instalar `bit64` para convertirla a `integer64`, o pedir el tipo",
          "`integer64` al conectar si el controlador lo admite."
        ),
        "bit64"
      )
    )
  }
  list(datos = datos, cobertura = cobertura)
}

.tipo_real_dbi <- function(tipo) {
  if (length(tipo) != 1L || is.na(tipo)) return(FALSE)
  limpio <- gsub("[[:space:]]+", "", .minusculas_ascii(as.character(tipo)))
  limpio %in% c("7", "real", "float4") || identical(limpio, "float(24)")
}

.real_dbi_a_doble <- function(valor) {
  if (length(valor) != 1L || is.na(valor) || !is.finite(valor)) {
    return(as.numeric(valor))
  }
  bytes <- writeBin(as.numeric(valor), raw(), size = 4L)
  readBin(bytes, what = "numeric", n = 1L, size = 4L)
}

.real_dbi_lectura_corta <- function(valor) {
  binario <- .real_dbi_a_doble(valor)
  if (length(binario) != 1L || is.na(binario) || !is.finite(binario)) {
    return(binario)
  }
  for (digitos in 6:9) {
    texto <- formatC(
      binario, format = "fg", digits = digitos, decimal.mark = "."
    )
    candidata <- suppressWarnings(as.numeric(texto))
    if (length(candidata) == 1L && is.finite(candidata) &&
        identical(.real_dbi_a_doble(candidata), binario)) {
      return(candidata)
    }
  }
  binario
}

# odbc devuelve el REAL de SQL Server con su valor binario de float32. Un
# centinela fraccionario declarado es un double en R, y la igualdad exacta no lo
# encuentra. Se alinean solo los valores iguales a la representacion float32 de
# un centinela declarado; los demas `real` quedan como los entrego el driver.
.ajustar_sentinelas_real_dbi <- function(
    datos, campos, tipos, sentinelas, tipos_motor = NULL) {
  if (!is.data.frame(datos) || !length(campos) || !length(sentinelas) ||
      is.null(tipos)) return(datos)
  declarados <- suppressWarnings(as.numeric(sentinelas))
  declarados <- declarados[is.finite(declarados)]
  if (!length(declarados)) return(datos)
  for (i in seq_along(campos)) {
    tipo <- .atributo_columna_dbi(tipos_motor, campos[[i]], i) %||%
      .atributo_columna_dbi(tipos, campos[[i]], i) %||% NA_character_
    if (!.tipo_real_dbi(tipo)) next
    posicion <- match(campos[[i]], names(datos))
    if (is.na(posicion) || !is.numeric(datos[[posicion]])) next
    for (declarado in declarados) {
      representado <- .real_dbi_a_doble(declarado)
      representado_corto <- .real_dbi_lectura_corta(representado)
      iguales <- !is.na(datos[[posicion]]) & (
        datos[[posicion]] == representado |
          datos[[posicion]] == representado_corto
      )
      datos[[posicion]][iguales] <- declarado
    }
  }
  datos
}

.bloque_muestra_dbi <- function(conexion, tabla, tabla_sql, campos, campos_sql,
                                muestra, muestra_motor, orden_muestra, orden_sql, dialecto,
                                n_total, presupuesto, info_conexion,
                                argumentos, muestreo = NULL,
                                prototipo = NULL,
                                tipos_declarados = NULL,
                                tipos_motor = NULL,
                                trazador = NULL,
                                max_celdas_muestra = .MAX_CELDAS_MUESTRA,
                                max_bytes_muestra = .MAX_BYTES_MUESTRA,
                                enmascaradas = character()) {
  cobertura <- .cobertura_dbi_vacia()
  # Una columna enmascarada (DDM de SQL Server) no entra en la muestra: sus
  # valores son la mascara -`xxxx`, `1900-01-01`, `0`- y la muestra publicaba
  # "un unico valor no ausente" y divergencias contra el resumen sobre columnas
  # completas. Su completitud la mide el resumen SQL.
  sacar <- .nombres_presentes(campos, enmascaradas)
  if (any(sacar)) {
    for (columna in campos[sacar]) {
      cobertura <- rbind(cobertura, .registro_cobertura_dbi(
        "perfil_muestra", columna, "alcance_distinto",
        .motivo_columna_enmascarada_dbi(), .remedio_columna_enmascarada_dbi()
      ))
    }
    if (all(sacar)) {
      return(list(
        perfil = NULL,
        cobertura = rbind(cobertura, .registro_cobertura_dbi(
          "perfil_muestra", .texto_tabla_dbi(tabla), "no_disponible",
          paste(
            "Todas las columnas legibles llegan enmascaradas: no hay muestra",
            "que perfilar."
          ),
          .remedio_columna_enmascarada_dbi()
        )),
        muestreo = NULL
      ))
    }
    quedan <- which(!sacar)
    if (!is.null(prototipo) && length(prototipo) == length(campos)) {
      prototipo <- prototipo[quedan]
    }
    if (!is.null(tipos_declarados) && length(tipos_declarados) == length(campos)) {
      tipos_declarados <- tipos_declarados[quedan]
    }
    if (!is.null(tipos_motor) && length(tipos_motor) == length(campos)) {
      tipos_motor <- tipos_motor[quedan]
    }
    if (!is.null(prototipo) && length(prototipo) == length(campos) &&
        is.null(names(prototipo))) {
      prototipo <- prototipo[quedan]
    }
    campos <- campos[quedan]
    campos_sql <- campos_sql[quedan]
  }
  # En Oracle la cadena vacia **es** NULL: no hay forma de distinguirlas, ni
  # desde SQL ni desde el controlador. Eso cambia una medida que el paquete
  # publica: los mismos tres valores `("", NA, "x")` dan dos faltantes por
  # Oracle y uno por SQLite. La completitud de la misma columna sale distinta
  # segun el motor, y no porque el dato cambie.
  #
  # No es un defecto que se pueda arreglar -es la semantica del motor- pero
  # callarlo si lo seria: quien compare completitud entre entregas de motores
  # distintos estaria leyendo una diferencia que no esta en los datos.
  if (identical(.via_clave_primaria(conexion), "all_constraints")) {
    cobertura <- rbind(cobertura, .registro_cobertura_dbi(
      "faltantes", NA_character_, "advertido",
      paste(
        "En este motor la cadena vac\u00eda y el nulo son el mismo valor, as\u00ed que",
        "los faltantes informados incluyen las cadenas vac\u00edas y no se pueden",
        "separar. Medido: las mismas tres filas dan dos faltantes aqu\u00ed y uno",
        "en un motor que las distingue."
      ),
      paste(
        "Al comparar completitud entre motores, tener presente que la",
        "diferencia puede venir de esta sem\u00e1ntica y no del dato. Si importa",
        "distinguirlas, hay que marcarlas con un valor propio antes de cargar."
      )
    ))
  }
  verificacion <- if (length(orden_sql)) {
    .verificar_orden_dbi(conexion, tabla_sql, orden_sql, dialecto, presupuesto)
  } else {
    list(
      unico = FALSE, sql = NA_character_,
      motivo = "No se declar\u00f3 `orden_muestra`; SQL no garantiza el orden de las filas."
    )
  }
  total_numero <- .numero_dbi(n_total)
  total_conocido <- length(total_numero) == 1L &&
    !is.na(total_numero) && is.finite(total_numero)
  alcance <- .tope_muestra_dbi(
    muestra, n_total, length(campos_sql),
    max_celdas_muestra, max_bytes_muestra
  )
  n_obtener <- alcance$filas_efectivas
  usa_muestreo <- !is.null(muestreo) && isTRUE(muestreo$disponible)
  proyeccion_muestra <- .campos_sql_muestra_dbi(
    conexion, campos, campos_sql, prototipo, tipos_declarados, dialecto,
    tipos_motor = tipos_motor,
    version_sqlserver = .version_servidor_sqlserver_dbi(conexion)
  )
  campos_sql_muestra <- proyeccion_muestra$campos_sql
  columnas_castadas <- proyeccion_muestra$columnas_castadas
  tabla_es_derivada <- grepl("^\\s*\\(", tabla_sql, perl = TRUE)
  alias_orden <- if (length(orden_sql)) {
    if (tabla_es_derivada && grepl("\\s+AS\\s+[^[:space:]]+$", tabla_sql,
                                   perl = TRUE)) {
      sub("^.*\\s+AS\\s+([^[:space:]]+)$", "\\1", tabla_sql,
          perl = TRUE)
    } else {
      .citar_identificador_dbi(conexion, "lupa_orden")
    }
  } else ""
  tabla_sql_orden <- if (!nzchar(alias_orden) || tabla_es_derivada) {
    tabla_sql
  } else {
    paste0(tabla_sql, " AS ", alias_orden)
  }
  orden_sql_orden <- if (nzchar(alias_orden)) {
    paste0(alias_orden, ".", orden_sql)
  } else orden_sql
  indices_orden_todos <- if (length(orden_muestra)) {
    .resolver_columnas_dbi(orden_muestra, campos)
  } else {
    integer()
  }
  # La receta de la lectura estaba escrita una sola vez y el reintento la
  # rehacia a mano, asi que perdia por el camino el muestreo del motor: volvia a
  # una lectura de primeras filas mientras `metodo` seguia declarando
  # `TABLESAMPLE`. Ahora la arma la misma funcion para cualquier subconjunto de
  # columnas, y lo que se declara sale de lo que se emitio.
  armar_muestra_dbi <- function(indices, filas_solicitadas = n_obtener,
                                aplicar_orden = TRUE, orden_indices = NULL) {
    sub_sql <- campos_sql_muestra[indices]
    indices_orden_subconjunto <- if (is.null(orden_indices)) {
      indices_orden_todos
    } else {
      intersect(orden_indices, indices_orden_todos)
    }
    orden_para <- if (length(orden_sql) && isTRUE(aplicar_orden) &&
                      length(indices_orden_subconjunto)) {
      orden_sql_orden[match(indices_orden_subconjunto, indices_orden_todos)]
    } else {
      character()
    }
    origen <- if (usa_muestreo) {
      .fuente_muestreada_dbi(
        tabla_sql, sub_sql, muestra_motor, n_total, dialecto,
        list(candidato = muestreo$candidato)
      )
    } else {
      NULL
    }
    base <- if (!is.null(origen)) {
      origen$sql
    } else {
      paste0(
        "SELECT ", paste(sub_sql, collapse = ", "), " FROM ", tabla_sql_orden,
        if (length(orden_para)) {
          paste0(" ORDER BY ", paste(orden_para, collapse = ", "))
        } else ""
      )
    }
    # `origen$sql` ya contiene el limite del muestreo del motor. Aplicarle
    # otro limite directamente arma `... LIMIT ... LIMIT ...` en PostgreSQL o
    # duplica `TOP` en SQL Server. Si el perfil local pide menos filas, el
    # recorte vive afuera de una tabla derivada: conserva las mismas filas que
    # fallo la lectura original y cada dialecto limita una sentencia propia.
    recorte <- if (!is.null(origen) &&
                   filas_solicitadas < origen$filas_solicitadas) {
      envoltura <- paste0(
        "SELECT * FROM (", base, ")",
        dialecto$alias_tabla("lupa_muestra_recorte")
      )
      dialecto$limitar(envoltura, filas_solicitadas, 0)
    } else if (!is.null(origen)) {
      NULL
    } else if (!total_conocido || filas_solicitadas < total_numero) {
      dialecto$limitar(base, filas_solicitadas, 0)
    } else {
      NULL
    }
    orden_aplicado <- is.null(origen) && length(orden_para) > 0L
    motivo_orden <- if (length(orden_muestra) && !is.null(origen)) {
      "No se aplic\u00f3 `orden_muestra`: el m\u00e9todo de muestreo por bloques o filas gobierna la selecci\u00f3n."
    } else if (length(orden_muestra) && !length(orden_para)) {
      "No se aplic\u00f3 `orden_muestra` en este subconjunto: falta una columna del orden. La muestra recuperada no es estable."
    } else if (length(orden_para)) {
      "Se aplic\u00f3 `orden_muestra`."
    } else {
      "No se solicit\u00f3 `orden_muestra`."
    }
    list(
      fuente = origen,
      sql = if (is.null(recorte)) base else recorte,
      filas = if (!is.null(origen)) {
        origen$filas
      } else if (is.null(recorte) && (!total_conocido || filas_solicitadas < total_numero)) {
        filas_solicitadas
      } else {
        -1L
      },
      acotado_en = if (!is.null(origen)) {
        "motor_muestreo"
      } else if (!is.null(recorte)) {
        "motor"
      } else if (!total_conocido || filas_solicitadas < total_numero) {
        "cliente"
      } else {
        "sin recorte"
      },
      metodo = if (!is.null(origen)) {
        origen$metodo
      } else if (length(orden_para)) {
        "primeras_filas_segun_orden"
      } else {
        "primeras_filas_sin_orden_garantizado"
      },
      orden_muestra_aplicado = orden_aplicado,
      motivo_orden_muestra = motivo_orden
    )
  }
  # Una sonda pregunta si el motor entrega ESTE subconjunto de columnas sobre
  # las MISMAS filas que la muestra: es la misma lectura, armada por la misma
  # funcion, con menos columnas. Antes leia una fila sin `ORDER BY`, y un fallo
  # que esta en una fila que no es la primera -una vista que convierte un texto
  # sucio en la fila 150- no se veia nunca: la muestra de las demas columnas se
  # perdia con un motivo que afirmaba lo contrario de lo que pasaba, "ninguna
  # fallo por si sola". Cuesta lo que la lectura, a lo sumo
  # `2n - 1` veces, y solo despues de que la lectura completa fallo.
  sondear_muestra_dbi <- function(indices, aplicar_orden = TRUE,
                                  orden_indices = NULL) {
    if (!length(indices)) return(TRUE)
    armado <- armar_muestra_dbi(
      indices, aplicar_orden = aplicar_orden, orden_indices = orden_indices
    )
    respuesta <- .consultar_dbi(
      conexion, armado$sql, presupuesto, filas = armado$filas,
      etapa = "sonda_lectura_muestra"
    )
    isTRUE(respuesta$ok)
  }
  hay_saldo_dbi <- function() {
    is.null(presupuesto) || .saldo_dbi(presupuesto) >= 1
  }
  lectura_inicio <- if (isTRUE(presupuesto$instrumentar)) .ahora_dbi() else NULL
  lectura_cpu_inicio <- if (isTRUE(presupuesto$instrumentar)) {
    .ahora_cpu_dbi()
  } else NULL
  if (is.finite(max_bytes_muestra)) {
    filas_sonda <- min(n_obtener, 100)
    sonda <- armar_muestra_dbi(seq_along(campos_sql), filas_sonda)
    consulta_sonda <- .consultar_dbi(
      conexion, sonda$sql, presupuesto, filas = sonda$filas,
      etapa = "sonda_bytes_muestra"
    )
    if (isTRUE(consulta_sonda$ok)) {
      alcance$bytes_sonda <- as.numeric(utils::object.size(consulta_sonda$datos))
      filas_sonda_obtenidas <- nrow(consulta_sonda$datos)
      if (filas_sonda_obtenidas > 0) {
        bytes_vacios <- as.numeric(utils::object.size(
          consulta_sonda$datos[0, , drop = FALSE]
        ))
        if (bytes_vacios > max_bytes_muestra) {
          .detener_dbi(
            "lupa_error_argumento_dbi",
            paste0(
              "`max_bytes_muestra` es menor que el tama\u00f1o m\u00ednimo de la",
              " muestra vac\u00eda (", bytes_vacios, " bytes)."
            )
          )
        }
        bytes_por_fila <- max(
          (alcance$bytes_sonda - bytes_vacios) / filas_sonda_obtenidas,
          alcance$bytes_sonda / filas_sonda_obtenidas, 1
        )
        alcance$filas_por_bytes <- floor(
          max(0, as.numeric(max_bytes_muestra) - bytes_vacios) /
            bytes_por_fila
        )
        if (alcance$filas_por_bytes < 1) {
          .detener_dbi(
            "lupa_error_argumento_dbi",
            "`max_bytes_muestra` no permite materializar una fila de la muestra."
          )
        }
        alcance$filas_efectivas <- min(
          alcance$filas_efectivas, alcance$filas_por_bytes
        )
        alcance$celdas_efectivas <-
          alcance$filas_efectivas * length(campos_sql)
      }
    }
  }
  n_obtener <- alcance$filas_efectivas
  # La consulta final siempre se arma con el limite resuelto. La medicion es solo
  # una medida previa para decidir ese limite; nunca se recorta en R lo que ya
  # vino del motor.
  armado <- armar_muestra_dbi(seq_along(campos_sql), alcance$filas_efectivas)
  fuente <- armado$fuente
  sql_muestra <- armado$sql
  filas <- armado$filas
  acotado_en <- armado$acotado_en
  muestreo_meta <- list(
    filas_solicitadas = as.numeric(muestra),
    filas_solicitadas_sin_topes = alcance$filas_solicitadas,
    filas_maximas_por_celdas = alcance$filas_por_celdas,
    filas_maximas_por_bytes = alcance$filas_por_bytes,
    max_celdas_muestra = max_celdas_muestra,
    max_bytes_muestra = max_bytes_muestra,
    celdas_solicitadas = alcance$celdas_solicitadas,
    celdas_efectivas = alcance$celdas_efectivas,
    bytes_sonda = alcance$bytes_sonda,
    bytes_muestra = alcance$bytes_muestra,
    filas_obtenidas = NA_real_,
    motivo_filas_obtenidas = NA_character_,
    filas_totales_fuente = n_total,
    tabla_completa = FALSE,
    metodo = if (!is.null(fuente)) {
      fuente$metodo
    } else if (length(orden_sql)) {
      "primeras_filas_segun_orden"
    } else {
      "primeras_filas_sin_orden_garantizado"
    },
    acotado_en = acotado_en,
    dialecto = dialecto$nombre,
    columnas_leidas = campos,
    orden_muestra = orden_muestra,
    orden_muestra_aplicado = isTRUE(armado$orden_muestra_aplicado),
    motivo_orden_muestra = armado$motivo_orden_muestra,
    orden_unico_verificado = isTRUE(verificacion$unico),
    reproducible = isTRUE(verificacion$unico),
    motivo_reproducibilidad = verificacion$motivo,
    sql_verificacion_orden = verificacion$sql,
    sql_muestra = sql_muestra
  )
  if (!is.null(fuente)) {
    muestreo_meta$fraccion <- fuente$fraccion
    muestreo_meta$tamano_muestra <- fuente$filas_solicitadas
    muestreo_meta$universo <- n_total
    muestreo_meta$capacidad <- muestreo$candidato$nombre
  }
  consulta <- .consultar_dbi(
    conexion, sql_muestra, presupuesto, filas = filas,
    etapa = "lectura_muestra"
  )
  campos_omitidos <- character()
  if (!consulta$ok) {
    muestreo_meta$motivo_filas_obtenidas <- consulta$motivo
    # Una sola columna que el controlador no sabe traer se llevaba puesta la
    # muestra entera: el usuario perdia el perfil por fila de las otras ciento
    # cincuenta. Es el reflejo de todo-o-nada otra vez, y la salida es la misma
    # que en los demas lugares: reintentar sin lo que no se puede leer y
    # declarar que quedo afuera.
    #
    # El reintento no castea. Castear exige una sintaxis por motor y una
    # decision sobre cuanto truncar, y las dos cosas son adivinar; dejar la
    # columna afuera y decirlo no supone nada.
    #
    # Dos caminos, y el orden importa. El primero es el atajo por tipo: sale
    # gratis cuando el motor informa nombres que se reconocen. El segundo es el
    # descarte, que le PREGUNTA al motor cuales columnas no puede traer en vez
    # de deducirlo del nombre del tipo. La version anterior tenia solo el
    # atajo, y contra el driver `{SQL Server}` -que informa el tipo como codigo
    # ODBC, "-1" y no "varchar(max)"- reconocia cero de noventa columnas: el
    # reintento no se disparaba nunca y la muestra se perdia igual, en
    # silencio. Cualquier patron de tipos va a ir siempre atras del zoo de
    # controladores; la correccion no puede colgar de el.
    motivo_original <- consulta$motivo
    recuperado <- NULL
    tipo_omision <- NA_character_
    sondas_descarte <- 0L
    descarte_agotado <- FALSE
    largas <- .columnas_de_tipo_largo_dbi(tipos_declarados)
    if (length(largas) && length(largas) < length(campos_sql)) {
      quedan <- setdiff(seq_along(campos_sql), largas)
      candidato <- armar_muestra_dbi(
        quedan, aplicar_orden = !any(
          .resolver_columnas_dbi(orden_muestra, campos) %in% largas
        )
      )
      prueba <- .consultar_dbi(
        conexion, candidato$sql, presupuesto, filas = candidato$filas,
        etapa = "lectura_muestra"
      )
      if (isTRUE(prueba$ok)) {
        recuperado <- list(
          consulta = prueba, armado = candidato,
          quedan = quedan, omitidas = largas
        )
        tipo_omision <- "tipo_declarado"
      }
    }
    culpables <- integer()
    tope_descarte <- 0
    if (is.null(recuperado) && length(campos_sql) > 1L) {
      # El descarte gasta consultas del mismo presupuesto que el resto del
      # perfil. Recuperar la muestra a costa de quedarse sin saldo para las
      # demas mediciones seria cambiar un agujero por otro, asi que el descarte
      # no puede llevarse mas de la mitad de lo que queda.
      saldo_actual <- if (is.null(presupuesto)) Inf else .saldo_dbi(presupuesto)
      tope_descarte <- min(
        (if (length(orden_sql)) 4L else 2L) * length(campos_sql),
        .TOPE_SONDAS_DESCARTE_DBI,
        max(0, floor(saldo_actual / 2))
      )
      sondas_descarte <- 0L
      aplicar_orden_sondas <- TRUE
      fallo_orden <- FALSE
      culpables_orden <- integer()
      indices_orden <- integer()
      if (length(orden_sql)) {
        indices_orden <- .resolver_columnas_dbi(orden_muestra, campos)
        if (!anyNA(indices_orden) && length(indices_orden)) {
          # Antes de atribuir el fallo a todas las columnas, comprobar la
          # columna de orden sola. Si ella falla, las sondas con `ORDER BY`
          # contaminan tambien a las columnas sanas y el descarte debe quitar
          # el orden para poder aislar la causa real.
          sondas_descarte <- 1L
          prueba_orden <- sondear_muestra_dbi(
            indices_orden, aplicar_orden = TRUE
          )
          aplicar_orden_sondas <- isTRUE(prueba_orden)
          fallo_orden <- !isTRUE(prueba_orden)
          if (fallo_orden) {
            # Un fallo del `ORDER BY` no demuestra que fallen todas las
            # columnas que lo componen. Probarlas de a una evita perder una
            # columna sana cuando solo una de ellas es la expresion rota.
            for (indice_orden in unique(indices_orden)) {
              if (sondas_descarte >= tope_descarte ||
                  !isTRUE(hay_saldo_dbi())) {
                descarte_agotado <- TRUE
                break
              }
              sondas_descarte <- sondas_descarte + 1L
              if (!isTRUE(sondear_muestra_dbi(
                indice_orden, aplicar_orden = TRUE,
                orden_indices = indice_orden
              ))) {
                culpables_orden <- c(culpables_orden, indice_orden)
              }
            }
          }
        }
      }
      indices_para_aislar <- setdiff(
        seq_along(campos_sql), unique(culpables_orden)
      )
      aislamiento <- if (length(indices_para_aislar)) {
        .aislar_ilegibles_dbi(
          function(indices) sondear_muestra_dbi(
            indices_para_aislar[indices], aplicar_orden = aplicar_orden_sondas
          ),
          hay_saldo_dbi, length(indices_para_aislar),
          max(0L, tope_descarte - sondas_descarte)
        )
      } else {
        list(culpables = integer(), sondas = 0L, agotado = FALSE)
      }
      sondas_descarte <- sondas_descarte + aislamiento$sondas
      descarte_agotado <- isTRUE(descarte_agotado) ||
        isTRUE(aislamiento$agotado)
      culpables <- c(
        unique(culpables_orden),
        indices_para_aislar[aislamiento$culpables]
      )
      culpables <- .sort_por_bytes(unique(culpables))
      if ((length(culpables) && length(culpables) < length(campos_sql)) ||
          (fallo_orden && !length(culpables))) {
        quedan <- setdiff(seq_along(campos_sql), culpables)
        candidato <- armar_muestra_dbi(
          quedan, aplicar_orden = !fallo_orden && !any(
            .resolver_columnas_dbi(orden_muestra, campos) %in% culpables
          )
        )
        if (fallo_orden && !isTRUE(candidato$orden_muestra_aplicado)) {
          candidato$motivo_orden_muestra <- paste0(
            "No se aplic\u00f3 `orden_muestra` porque el motor no pudo evaluar",
            " la columna solicitada; se recuper\u00f3 la muestra sin ese orden."
          )
        }
        prueba <- .consultar_dbi(
          conexion, candidato$sql, presupuesto, filas = candidato$filas,
          etapa = "lectura_muestra"
        )
        if (isTRUE(prueba$ok)) {
          recuperado <- list(
            consulta = prueba, armado = candidato,
            quedan = quedan, omitidas = culpables
          )
          tipo_omision <- if (fallo_orden && length(culpables_orden)) {
            "orden"
          } else {
            "descarte"
          }
        }
      }
    }
    if (!is.null(recuperado)) {
      campos_omitidos <- campos[recuperado$omitidas]
      if (identical(tipo_omision, "orden")) {
        motivo_omision <- .motivo_orden_ilegible_muestra_dbi(
          campos[culpables_orden], motivo_original
        )
        otras_omitidas <- setdiff(
          recuperado$omitidas, unique(culpables_orden)
        )
        if (length(otras_omitidas)) {
          motivo_omision <- paste0(
            motivo_omision, " ", .motivo_omision_muestra_dbi(
              "descarte", campos[otras_omitidas], sondas_descarte,
              motivo_original
            )
          )
        }
      } else {
        motivo_omision <- .motivo_omision_muestra_dbi(
          tipo_omision, campos_omitidos, sondas_descarte, motivo_original
        )
      }
      cobertura <- rbind(cobertura, .registro_cobertura_dbi(
        "perfil_muestra", .texto_tabla_dbi(tabla), "alcance_distinto",
        motivo_omision,
        paste(
          "El resumen por columna las cubre igual; lo que falta es su perfil",
          "por fila. Para incluirlas, convertirlas a texto acotado en una",
          "vista y perfilar esa vista."
        ),
        recuperado$armado$sql
      ))
      consulta <- recuperado$consulta
      sql_muestra <- recuperado$armado$sql
      filas <- recuperado$armado$filas
      campos <- campos[recuperado$quedan]
      campos_sql <- campos_sql[recuperado$quedan]
      campos_sql_muestra <- campos_sql_muestra[recuperado$quedan]
      if (!is.null(prototipo)) prototipo <- .alinear_atributos_columnas_dbi(
        campos, prototipo = prototipo
      )$prototipo
      if (!is.null(tipos_declarados)) tipos_declarados <-
        .alinear_atributos_columnas_dbi(
          campos, tipos = tipos_declarados
        )$tipos
      if (!is.null(tipos_motor)) tipos_motor <- .alinear_atributos_columnas_dbi(
        campos, tipos_motor = tipos_motor
      )$tipos_motor
      columnas_castadas <- intersect(
        columnas_castadas, campos
      )
      # `muestreo_meta` se arma antes de leer, asi que sin esto quedaba
      # congelado con la lectura que fallo: declaraba haber leido la columna
      # que justamente no se pudo leer, y publicaba el SQL original en vez
      # del que de verdad se emitio. Es el invariante al reves -informar como
      # medido lo que no se midio- y en el peor lugar, porque `meta` es donde
      # se mira para saber que se hizo. `metodo` y `acotado_en` entran por lo
      # mismo: el reintento puede cambiar la forma de muestrear.
      muestreo_meta$columnas_leidas <- campos
      muestreo_meta$sql_muestra <- sql_muestra
      muestreo_meta$acotado_en <- recuperado$armado$acotado_en
      muestreo_meta$metodo <- recuperado$armado$metodo
      muestreo_meta$orden_muestra_aplicado <- isTRUE(
        recuperado$armado$orden_muestra_aplicado
      )
      muestreo_meta$motivo_orden_muestra <- recuperado$armado$motivo_orden_muestra
      if (!is.null(recuperado$armado$fuente)) {
        muestreo_meta$fraccion <- recuperado$armado$fuente$fraccion
        muestreo_meta$tamano_muestra <- recuperado$armado$fuente$filas_solicitadas
      }
      muestreo_meta$columnas_omitidas <- campos_omitidos
      muestreo_meta$motivo_columnas_omitidas <- motivo_omision
      # Como se decidio la omision, para que se pueda filtrar: comprobada por
      # descarte, o supuesta por el tipo que declaro el motor.
      muestreo_meta$omision_comprobada <- identical(tipo_omision, "descarte")
      muestreo_meta$sondas_descarte <- as.numeric(sondas_descarte)
    } else if (sondas_descarte > 0L) {
      # El descarte corrio y no sirvio. Decirlo es parte del resultado: sin
      # esto el motivo final seria el del motor a secas y nadie sabria que ya
      # se busco la columna culpable. Y cada final es distinto -no aislar
      # ninguna no es lo mismo que que fallen todas-, asi que el texto no puede
      # ser uno solo.
      detalle <- if (fallo_orden && length(culpables_orden)) {
        paste0(
          "la evaluaci\u00f3n del `ORDER BY` fall\u00f3 en las columnas ",
          paste(campos[culpables_orden], collapse = ", "),
          "; la muestra sin ese orden no se pudo recuperar."
        )
      } else if (fallo_orden && !length(culpables)) {
        "el `ORDER BY` fall\u00f3, pero las sondas sin orden no localizaron una columna culpable."
      } else if (!length(culpables)) {
        paste(
          "ninguna fall\u00f3 por s\u00ed sola: el fallo no es de una columna en",
          "particular."
        )
      } else if (length(culpables) == length(campos_sql)) {
        "todas fallan por si solas: no queda ning\u00fan subconjunto legible."
      } else {
        "la lectura sin las que fallan tampoco sali\u00f3."
      }
      if (descarte_agotado) {
        detalle <- paste0(
          "se agoto el tope de sondas (", tope_descarte,
          ") y el aislamiento qued\u00f3 parcial; ", detalle
        )
      }
      consulta$motivo <- paste0(
        motivo_original, " Se sondearon ", sondas_descarte,
        " subconjuntos de columnas para aislar cu\u00e1l no se puede leer, y ",
        detalle
      )
    }
  }
  if (!consulta$ok) {
    .registrar_etapa_dbi(
      trazador, "lectura_muestra", lectura_inicio, .ahora_dbi(),
      cpu_inicio = lectura_cpu_inicio, cpu_fin = .ahora_cpu_dbi()
    )
    .registrar_etapa_dbi(
      trazador, "perfilado_muestra", estado = "no_solicitado"
    )
    # Antes se descartaba aca el resumen entero cuando fallaba la consulta de
    # muestra. Ahora la muestra se declara no disponible y el resumen sale igual,
    # con su alcance.
    cobertura <- rbind(cobertura, .registro_cobertura_dbi(
      "perfil_muestra", .texto_tabla_dbi(tabla), "no_disponible",
      paste0("No se pudo leer la muestra: ", consulta$motivo),
      paste(
        "El resumen de tabla completa se devolvi\u00f3 igual. Para reintentar s\u00f3lo",
        "la muestra, declarar `dialecto` o `orden_muestra`, o reducir",
        "`muestra`."
      ),
      sql_muestra
    ))
    return(list(perfil = NULL, cobertura = cobertura, muestreo = muestreo_meta))
  }
  datos_muestra <- .ajustar_sentinelas_real_dbi(
    consulta$datos, campos, tipos_declarados,
    argumentos[["sentinelas_numericos"]], tipos_motor = tipos_motor
  )
  conversion_muestra <- .convertir_enteros_ancho_muestra_dbi(
    datos_muestra, columnas_castadas, tipos_declarados
  )
  datos_muestra <- conversion_muestra$datos
  n_obtenidas <- nrow(datos_muestra)
  alcance$filas_efectivas <- as.numeric(n_obtenidas)
  alcance$celdas_efectivas <- alcance$filas_efectivas * length(campos_sql)
  alcance$bytes_muestra <- if (is.finite(max_bytes_muestra)) {
    as.numeric(utils::object.size(datos_muestra))
  } else {
    NA_real_
  }
  alcance$recortada <- alcance$filas_efectivas < alcance$filas_solicitadas
  alcance$motivos <- .motivos_muestra_perfilado(alcance)
  .registrar_etapa_dbi(
    trazador, "lectura_muestra", lectura_inicio, .ahora_dbi(),
    cpu_inicio = lectura_cpu_inicio, cpu_fin = .ahora_cpu_dbi()
  )
  muestreo_meta$filas_obtenidas <- as.numeric(n_obtenidas)
  muestreo_meta$celdas_efectivas <- alcance$celdas_efectivas
  muestreo_meta$bytes_sonda <- alcance$bytes_sonda
  muestreo_meta$bytes_muestra <- alcance$bytes_muestra
  muestreo_meta$tabla_completa <- n_obtenidas == .numero_dbi(n_total)
  if (!identical(as.numeric(n_obtenidas), as.numeric(n_obtener))) {
    cobertura <- rbind(cobertura, .registro_cobertura_dbi(
      "perfil_muestra", .texto_tabla_dbi(tabla), "alcance_distinto",
      paste0(
        "La consulta de muestra devolvi\u00f3 ", n_obtenidas,
        if (n_obtenidas == 1L) " fila; se esperaba " else " filas; se esperaban ",
        .entero_sql_dbi(n_obtener), if (n_obtener == 1L) ". La tabla pudo cambiar durante la lectura." else ". La tabla pudo cambiar durante la lectura."
      ),
      paste(
        "El perfil de la muestra describe las filas efectivamente le\u00eddas;",
        "`filas_obtenidas` declara cu\u00e1ntas son."
      ),
      sql_muestra
    ))
    muestreo_meta$coincide_con_lo_pedido <- FALSE
  } else {
    muestreo_meta$coincide_con_lo_pedido <- TRUE
  }
  if (is.null(argumentos$nombre)) {
    argumentos$nombre <- paste0("muestra DBI de ", .texto_tabla_dbi(tabla))
  }
  argumentos$muestra <- Inf
  # Los topes ya se resolvieron sobre la relacion remota. Pasar `Inf` aca
  # evita una segunda decision local que podria volver a recortar en R lo que
  # el bloque acaba de traer y, ademas, deja la cobertura con una sola fuente
  # de verdad: el alcance calculado antes de la lectura.
  argumentos$max_celdas_muestra <- Inf
  argumentos$max_bytes_muestra <- Inf
  if (!is.null(trazador)) {
    attr(datos_muestra, "lupa_trazador_tiempos_dbi") <- trazador
  }
  perfil <- tryCatch(
    .medir_etapa_dbi(
      trazador, "perfilado_muestra",
      do.call(perfilar, c(list(datos = datos_muestra), argumentos))
    ),
    error = function(e) e
  )
  if (inherits(perfil, "condition")) {
    cobertura <- rbind(cobertura, .registro_cobertura_dbi(
      "perfil_muestra", .texto_tabla_dbi(tabla), "no_disponible",
      paste0(
        "La muestra se ley\u00f3 pero no se pudo perfilar: ",
        .motivo_perfilado_muestra_dbi(perfil, datos_muestra, argumentos)
      ),
      paste(
        "El resumen de tabla completa se devolvi\u00f3 igual. Revisar los",
        "argumentos enviados a perfilar()."
      ),
      sql_muestra
    ))
    return(list(perfil = NULL, cobertura = cobertura, muestreo = muestreo_meta))
  }
  perfil <- .ajustar_longitudes_binarias_dbi(
    perfil, datos_muestra, proyeccion_muestra$columnas_binarias,
    proyeccion_muestra$columnas_binarias_prefijo
  )
  # El desvio de un decimal que llego como doble: ver
  # `.tapar_desvio_decimal_doble_perfil_dbi()`.
  perfil <- .tapar_desvio_decimal_doble_perfil_dbi(
    perfil, .columnas_desvio_decimal_doble_dbi(
      datos_muestra, campos, tipos_declarados, perfil$columnas, conexion
    )
  )
  if (nrow(conversion_muestra$cobertura)) {
    perfil$cobertura_diagnosticos <- rbind(
      perfil$cobertura_diagnosticos, conversion_muestra$cobertura
    )
    rownames(perfil$cobertura_diagnosticos) <- NULL
  }
  perfil$meta$filas_analizadas <- alcance$filas_efectivas
  perfil$meta$filas_totales_fuente <- .numero_dbi(n_total)
  perfil$meta$muestreo <- n_obtenidas < .numero_dbi(n_total)
  perfil$meta$muestra <- as.numeric(muestra)
  perfil$meta$muestra_efectiva <- alcance$filas_efectivas
  perfil$meta$celdas_solicitadas <- alcance$celdas_solicitadas
  perfil$meta$celdas_efectivas <- alcance$celdas_efectivas
  perfil$meta$max_celdas_muestra <- max_celdas_muestra
  perfil$meta$max_bytes_muestra <- max_bytes_muestra
  perfil$meta$bytes_sonda <- alcance$bytes_sonda
  perfil$meta$bytes_muestra <- alcance$bytes_muestra
  cobertura_topes <- .cobertura_muestra_perfilado(alcance)
  perfil$meta$tope_que_mando <- .tope_que_mando(alcance)
  perfil$meta$tope_que_mando_texto <- if (nrow(cobertura_topes)) {
    cobertura_topes$motivo[[1L]]
  } else {
    NA_character_
  }
  if (nrow(cobertura_topes)) {
    perfil$cobertura_diagnosticos <- rbind(
      perfil$cobertura_diagnosticos, cobertura_topes
    )
    rownames(perfil$cobertura_diagnosticos) <- NULL
    # El resumen es el canal principal de la via DBI. Reusar exactamente la
    # fila del perfil evita que dos redacciones del mismo tope se separen con
    # el tiempo y que una de las dos deje de declarar lo que la otra vio.
    cobertura <- rbind(cobertura, .registro_cobertura_dbi(
      "perfil_muestra", .texto_tabla_dbi(tabla), "degradado",
      cobertura_topes$motivo[[1L]], cobertura_topes$como_resolverlo[[1L]],
      sql_muestra
    ))
  }
  perfil <- .constante_no_medible_en_muestra_dbi(perfil, muestreo_meta)
  perfil$meta$origen_dbi <- list(
    tipo = "DBI",
    conexion = info_conexion,
    tabla = .texto_tabla_dbi(tabla),
    muestreo = muestreo_meta,
    solo_lectura = TRUE,
    objetos_temporales = FALSE
  )
  # Los valores de las columnas protegidas se cosechan aca, que es el unico lugar
  # donde la muestra esta a la vista: el perfil que sale ya esta protegido y no
  # conserva los datos. La proteccion del resumen los necesita para tapar, en las
  # columnas que no son personales, el valor de una persona que es su moda o su
  # minimo. Antes se buscaban en `perfil_muestra$datos`, que no existe: `$` hacia
  # coincidencia parcial con `datos_personales` y no salia ningun valor, de modo
  # que solo la moda SQL de la columna protegida contaba como protegida. Medido:
  # el titular que era la moda de otra columna se publicaba en el
  # resumen y en la corroboracion cruzada. Viajan en el bloque, nunca en el perfil.
  valores_protegidos <- tryCatch({
    protegidas <- .columnas_personales_protegidas(perfil$datos_personales)
    .valores_identificantes(
      .valores_publicables_protegidos(datos_muestra, protegidas),
      .fechas_que_identifican(datos_muestra, protegidas)
    )
  }, error = function(e) character())
  # Y que columnas protegidas son de fechas, con la misma regla que en memoria
  # -`.columna_de_fechas()`-: la cosecha del resumen no tiene la muestra y sus
  # ejemplos y estadisticos entraban al piso enteros.
  columnas_de_fechas <- tryCatch({
    protegidas <- .columnas_personales_protegidas(perfil$datos_personales)
    indices <- .indice_nombre(protegidas, names(datos_muestra))
    protegidas[vapply(indices, function(i) {
      !is.na(i) && .columna_de_fechas(datos_muestra[[i]])
    }, logical(1L))]
  }, error = function(e) character())
  # Y los centinelas de las columnas protegidas -`.rellenos_de_columna()`-, que
  # la lectura de la tabla entera trae sin sus frecuencias. Con su cuenta en la
  # muestra: aca solo son CANDIDATOS. La regla pide que la columna sin ellos sea
  # casi una clave, y en una muestra los clientes que se repiten casi no se
  # repiten -la cedula valida de un cliente con 600 movimientos salia
  # como moda de otra columna-. Los confirma la tabla entera, en
  # `.rellenos_confirmados_tabla_dbi()`.
  rellenos_detalle <- tryCatch({
    protegidas <- .columnas_personales_protegidas(perfil$datos_personales)
    indices <- .indice_nombre(protegidas, names(datos_muestra))
    filas <- lapply(which(!is.na(indices)), function(j) {
      x <- datos_muestra[[indices[[j]]]]
      valores <- .rellenos_de_columna(x)
      if (!length(valores)) return(NULL)
      texto <- as.character(x)
      data.frame(
        columna = protegidas[[j]], valor = valores,
        cuenta = vapply(valores, function(v) sum(texto == v, na.rm = TRUE),
                        numeric(1L), USE.NAMES = FALSE),
        stringsAsFactors = FALSE
      )
    })
    filas <- Filter(Negate(is.null), filas)
    if (length(filas)) do.call(rbind, filas) else NULL
  }, error = function(e) NULL)
  rellenos <- if (is.null(rellenos_detalle)) character() else {
    unique(rellenos_detalle$valor)
  }
  list(perfil = perfil, cobertura = cobertura, muestreo = muestreo_meta,
       valores_protegidos = valores_protegidos,
       columnas_de_fechas = columnas_de_fechas,
       rellenos = rellenos, rellenos_detalle = rellenos_detalle)
}

# Que candidatos a relleno de la muestra lo son en la TABLA ENTERA, con la regla
# de `.rellenos_de_columna()`: la columna sin ellos, casi una clave. Leida la
# tabla completa, la muestra es la tabla y se confirman todos. Si no, con los
# conteos exactos de la tabla: `n_distintos` y `n_validos` calculados, y la
# cuenta de la muestra como cota inferior de la del candidato -la tasa que da es
# una cota inferior de la verdadera, asi que si alcanza, alcanza-. Sin conteo
# exacto no se confirma ninguno y siguen en el piso: no se afloja una guarda
# sobre lo que solo vio una muestra.
#
# Con `universo = "muestra_motor"` no hay tabla entera: los conteos `calculado`
# son los de la relacion muestreada por el motor, y con `muestra = Inf` la
# muestra en R ES esa relacion (`tabla_completa`). No se confirma ninguno: la
# cedula valida de un cliente frecuente se confirmaba como relleno sobre la
# muestra del motor y salia en la moda de otra columna. Medido.
#
# Devuelve los confirmados POR COLUMNA -`columna`, `valor`-: un relleno de la
# cedula no saca del piso el mismo valor de otra columna protegida, como en
# memoria (`.valores_publicables_protegidos()`).
.rellenos_confirmados_tabla_dbi <- function(detalle, muestreo, columnas, sql,
                                            universo = "tabla_completa") {
  vacio <- data.frame(columna = character(), valor = character(),
                      stringsAsFactors = FALSE)
  if (!is.data.frame(detalle) || !nrow(detalle)) return(vacio)
  if (!identical(universo, "tabla_completa")) return(vacio)
  if (is.list(muestreo) && isTRUE(muestreo$tabla_completa)) {
    return(unique(.seleccionar_columnas(detalle, c("columna", "valor"))))
  }
  if (!is.data.frame(columnas) ||
      !all(c("columna", "n_validos", "n_distintos") %in% names(columnas))) {
    return(vacio)
  }
  operar <- function(x) .nombres_para_operar(as.character(x))
  calculado <- function(columna, metrica) {
    is.data.frame(sql) &&
      all(c("columna", "metrica", "estado") %in% names(sql)) &&
      any(operar(sql$columna) %in% operar(columna) &
            as.character(sql$metrica) == metrica &
            as.character(sql$estado) == "calculado")
  }
  confirmados <- vacio
  for (columna in unique(detalle$columna)) {
    i <- match(operar(columna), operar(columnas$columna))
    if (is.na(i) || !calculado(columna, "n_validos") ||
        !calculado(columna, "n_distintos")) next
    validos <- .numero_dbi(columnas$n_validos[[i]])
    distintos <- .numero_dbi(columnas$n_distintos[[i]])
    propios <- detalle[operar(detalle$columna) == operar(columna), ,
                       drop = FALSE]
    if (length(validos) != 1L || length(distintos) != 1L ||
        !is.finite(validos) || !is.finite(distintos)) next
    resto <- validos - sum(propios$cuenta)
    if (resto <= 0) next
    if ((distintos - nrow(propios)) / resto >= .TASA_CASI_CLAVE_RELLENO) {
      confirmados <- rbind(confirmados,
                           .seleccionar_columnas(propios, c("columna", "valor")))
    }
  }
  unique(confirmados)
}

# ---- Portones ------------------------------------------------------------

# Lo que describe la mascara y no el dato no se publica como del dato. Una
# columna enmascarada (DDM de SQL Server, sin `UNMASK`) conserva su completitud
# -el conteo de no nulos no se enmascara: `.contar_no_nulos_sql_dbi()`- y todo
# lo demas del resumen queda `no_disponible` con su motivo: distintos, moda,
# extremos, media, mediana y desvio salian de `xxxx` y de `0`.
# Corre sobre el resultado de las tres vias -la SQL, la de bloques y la del
# spool- antes de la corroboracion, para que esta no compare la mascara.
.declarar_enmascaradas_dbi <- function(resultado, preparacion) {
  enmascaradas <- preparacion$enmascaradas
  resumen <- resultado$resumen_tabla
  if (!length(enmascaradas) || is.null(resumen)) return(resultado)
  otras <- setdiff(names(.CAMPOS_METRICA_DBI), "validos")
  campos_otros <- unlist(.CAMPOS_METRICA_DBI[otras], use.names = FALSE)
  mascaras <- preparacion$mascaras
  sql_catalogo <- preparacion$lista_campos$columnas$sql_catalogo
  if (is.null(sql_catalogo)) sql_catalogo <- NA_character_
  for (columna in enmascaradas) {
    indice <- if (length(mascaras)) .indice_nombre(columna, names(mascaras)) else NA
    motivo <- .motivo_columna_enmascarada_dbi(
      if (is.na(indice)) NA_character_ else mascaras[[indice]]
    )
    if (is.data.frame(resumen$columnas) && nrow(resumen$columnas)) {
      filas <- .nombres_presentes(resumen$columnas$columna, columna)
      for (campo in intersect(campos_otros, names(resumen$columnas))) {
        resumen$columnas[[campo]][filas] <- NA
      }
    }
    if (is.data.frame(resumen$sql) && nrow(resumen$sql)) {
      tocar <- .nombres_presentes(resumen$sql$columna, columna) &
        resumen$sql$metrica %in% campos_otros &
        !resumen$sql$estado %in% c("no_aplica", "no_solicitado")
      resumen$sql$estado[tocar] <- "no_disponible"
      resumen$sql$motivo[tocar] <- motivo
      if ("memoria_trabajo" %in% names(resumen$sql)) {
        resumen$sql$memoria_trabajo[tocar] <- NA_character_
      }
    }
    resumen$cobertura <- rbind(
      if (is.null(resumen$cobertura)) .cobertura_dbi_vacia() else resumen$cobertura,
      .registro_cobertura_dbi(
        "resumen_tabla", columna, "no_disponible", motivo,
        .remedio_columna_enmascarada_dbi(), sql_catalogo
      )
    )
  }
  resultado$resumen_tabla <- resumen
  resultado
}

# Un estado que afirma un valor -`calculado`, `estimado`, `observado_muestra`-
# con el valor ausente es una contradiccion: `NA` dice "no se midio" y el
# estado dice "se midio". Recorrer seis motores (SQLite, DuckDB, PostgreSQL,
# SQL Server, MySQL, MariaDB), cuatro caminos y ocho juegos de metricas sobre
# columnas vacias, de un valor, sin repetidos y de texto encontro 1.458
# registros asi (medido el 2026-11-06): `tasa_distintos` de una columna vacia
# en el camino por omision, la moda de una columna sin repetidos, la mediana
# consolidada de una columna vacia, los basicos de una columna vacia sin
# `validos`, y en `con_muestra` todas las metricas numericas de las columnas de
# texto. Cada camino tiene su motivo, y el que falte manana tendra otro: la
# regla se aplica una vez, sobre el resumen ya armado, en las tres salidas de
# `perfilar_dbi()` y antes de las protecciones, que tapan valores a proposito y
# declaran su propio estado.
.ESTADOS_QUE_AFIRMAN_VALOR_DBI <- c("calculado", "estimado", "observado_muestra")

# El valor de una metrica puede venir en otro campo de la fila: la cifra exacta
# de un entero o decimal ancho, o la fecha.
.CAMPOS_DEL_VALOR_DBI <- list(
  minimo = c("minimo", "minimo_exacto", "minimo_fecha"),
  maximo = c("maximo", "maximo_exacto", "maximo_fecha"),
  media = c("media", "media_fecha"),
  mediana = c("mediana", "mediana_fecha")
)

.METRICAS_DE_MAGNITUD_DBI <- c(
  "minimo", "maximo", "media", "mediana", "desvio", "n_ceros", "n_negativos"
)

.declarar_afirmados_sin_valor_dbi <- function(resultado, preparacion = NULL) {
  resumen <- resultado$resumen_tabla
  if (!is.list(resumen) || !is.data.frame(resumen$sql) ||
      !is.data.frame(resumen$columnas) || !nrow(resumen$sql) ||
      !all(c("columna", "metrica", "estado") %in% names(resumen$sql))) {
    return(resultado)
  }
  sql <- resumen$sql
  columnas <- resumen$columnas
  universo <- if (!is.null(preparacion$universo)) preparacion$universo else
    resumen$meta$universo
  es_muestra <- identical(as.character(universo), "muestra_motor")
  fila <- .indice_nombre(as.character(sql$columna), as.character(columnas$columna))
  metrica <- as.character(sql$metrica)
  candidatas <- which(
    as.character(sql$estado) %in% .ESTADOS_QUE_AFIRMAN_VALOR_DBI &
      !is.na(fila) & metrica %in% names(columnas)
  )
  if (!length(candidatas)) return(resultado)
  # Las columnas que el esquema leyo como no numericas. Sin preparacion no se
  # puede saber, y ninguna metrica se declara `no_aplica` por el tipo.
  no_numericas <- character()
  if (!is.null(preparacion$campos) && length(preparacion$campos)) {
    numerica <- vapply(seq_along(preparacion$campos), function(i) {
      .es_numerico_dbi(
        .atributo_columna_dbi(
          preparacion$prototipo, preparacion$campos[[i]], i
        ),
        .atributo_columna_dbi(
          preparacion$tipos, preparacion$campos[[i]], i
        ) %||% NA_character_
      )
    }, logical(1L))
    no_numericas <- as.character(preparacion$campos)[!numerica]
  }
  valor_presente <- function(nombre, j) {
    campos <- intersect(
      if (is.null(.CAMPOS_DEL_VALOR_DBI[[nombre]])) nombre else
        .CAMPOS_DEL_VALOR_DBI[[nombre]],
      names(columnas)
    )
    any(vapply(campos, function(campo) {
      valor <- columnas[[campo]][[j]]
      length(valor) == 1L && !is.na(valor) &&
        (!is.character(valor) || nzchar(valor))
    }, logical(1L)))
  }
  numero <- function(campo, j) {
    if (!campo %in% names(columnas)) return(NA_real_)
    suppressWarnings(as.numeric(columnas[[campo]][[j]]))
  }
  # Se decide sobre los estados de entrada: reclasificar el minimo antes que la
  # mediana no puede cambiar lo que la mediana concluye de la columna.
  estado_entrada <- as.character(sql$estado)
  sin_valor <- function(nombre, j) {
    k <- which(fila == j & metrica == nombre)
    length(k) > 0L && (
      any(estado_entrada[k] == "sin_valores") ||
        (any(estado_entrada[k] %in% .ESTADOS_QUE_AFIRMAN_VALOR_DBI) &&
           !valor_presente(nombre, j))
    )
  }
  for (i in candidatas) {
    j <- fila[[i]]
    nombre <- metrica[[i]]
    if (valor_presente(nombre, j)) next
    motivo_previo <- if ("motivo" %in% names(sql)) {
      as.character(sql$motivo[[i]])
    } else NA_character_
    conserva_motivo <- is.list(preparacion) &&
      identical(as.character(preparacion$universo), "muestra_motor") &&
      identical(as.character(preparacion$bloque_muestra), "con_muestra") &&
      identical(motivo_previo, .MOTIVO_DECIMAL_ANCHO_SPOOL_DBI)
    n_validos <- numero("n_validos", j)
    # Sin el conteo, un MIN y un MAX que el motor devolvio nulos sobre la tabla
    # entera dicen lo mismo: no hay valores no nulos.
    vacia <- (is.finite(n_validos) && n_validos == 0) ||
      (!es_muestra && !is.finite(n_validos) &&
         sin_valor("minimo", j) && sin_valor("maximo", j))
    columna <- as.character(columnas$columna[[j]])
    if (nombre %in% .METRICAS_DE_MAGNITUD_DBI &&
        length(.nombres_presentes(columna, no_numericas)) &&
        any(.nombres_presentes(columna, no_numericas))) {
      estado <- "no_aplica"
      motivo <- "La m\u00e9trica es num\u00e9rica y la columna no lo es."
    } else if (vacia && es_muestra) {
      estado <- "no_disponible"
      motivo <- "muestra_inestable:sin_valores_validos"
    } else if (vacia) {
      estado <- "sin_valores"
      motivo <- "La columna no contiene valores no nulos."
    } else if (identical(nombre, "desvio") && is.finite(n_validos) &&
               n_validos < 2) {
      estado <- "no_aplica"
      motivo <- "El desv\u00edo muestral requiere al menos dos valores no nulos."
    } else if (identical(nombre, "moda") &&
               isTRUE(numero("frecuencia_moda", j) == 1) &&
               !(is.finite(n_validos) && n_validos == 1)) {
      # En la tabla completa es un hecho: no hay moda. En una muestra sin
      # repetidos la tabla puede tenerla, y no se sabe cual.
      if (es_muestra) {
        estado <- "no_disponible"
        motivo <- paste(
          "Ning\u00fan valor se repite en la muestra: la moda de la tabla no",
          "se puede estimar."
        )
      } else {
        estado <- "no_aplica"
        motivo <- "Ning\u00fan valor se repite: la columna no tiene moda."
      }
    } else {
      estado <- "no_disponible"
      motivo <- if (conserva_motivo) motivo_previo else paste(
        "La consulta termin\u00f3 sin un valor para la m\u00e9trica; no se",
        "publica como calculada."
      )
    }
    sql$estado[[i]] <- estado
    sql$motivo[[i]] <- motivo
    if (estado %in% c("no_aplica", "sin_valores") &&
        "error_esperado" %in% names(sql)) {
      sql$error_esperado[[i]] <- "no_aplica"
    }
    if ("memoria_trabajo" %in% names(sql)) {
      sql$memoria_trabajo[[i]] <- NA_character_
    }
  }
  resumen$sql <- sql
  resultado$resumen_tabla <- resumen
  resultado
}

.CAMPOS_VALOR_MUESTRA_DBI <- c(
  "moda", "minimo", "maximo", "mediana", "minimo_exacto",
  "maximo_exacto", "minimo_fecha", "maximo_fecha", "media_fecha",
  "mediana_fecha", "centinela_valor"
)
.CAMPOS_MAGNITUD_MUESTRA_DBI <- c(
  "minimo", "maximo", "media", "n_ceros", "n_negativos", "mediana",
  "desvio"
)

.columnas_decimal_doble_muestra_dbi <- function(datos, campos, tipos) {
  if (!is.data.frame(datos) || !nrow(datos)) return(character())
  salida <- vapply(seq_along(campos), function(i) {
    tipo <- .atributo_columna_dbi(tipos, campos[[i]], i) %||% NA_character_
    if (!.tipo_declarado_decimal_dbi(tipo)) return(FALSE)
    x <- datos[[campos[[i]]]]
    # Un `integer64` guarda sus bits en un `double` -`is.double()` le da
    # `TRUE`-, pero es el decimal entero convertido exacto desde su texto
    # (`.convertir_enteros_ancho_muestra_dbi()`): `perfilar()` lo resume como
    # cualquier `integer64`, y esta guarda le tapaba la mediana y los conteos
    # exactos con el motivo de un doble que no llego.
    is.double(x) && !inherits(x, "integer64") &&
      any(is.finite(x) & abs(x) >= .MAX_ENTERO_EXACTO_DBI)
  }, logical(1L))
  campos[salida]
}

# Las columnas cuyo desvio, calculado en R sobre lo leido, sale de los dobles de
# un decimal y no se puede publicar: la magnitud frente al desvio es tal que el
# redondeo de cada valor lo mueve mas de lo tolerado (ver
# `.desvio_mal_condicionado_dbi()`). `columnas` trae el desvio de esa lectura
# -el resumen del spool, o `perfil_muestra`-. Una sola regla para todo desvio
# que se calcula en R sobre la muestra. Un decimal entero que la muestra
# convirtio a `integer64` llego exacto y no entra; los que pasan de 2^53 ya los
# tapa `.columnas_decimal_doble_muestra_dbi()`. SQLite guarda los decimales como
# `REAL`: esos dobles son los valores.
.columnas_desvio_decimal_doble_dbi <- function(datos, campos, tipos, columnas,
                                               conexion = NULL) {
  if (!is.data.frame(datos) || !nrow(datos) || !is.data.frame(columnas) ||
      !all(c("columna", "desvio") %in% names(columnas))) {
    return(character())
  }
  if (!is.null(conexion) &&
      grepl("sqlite", .senas_conexion_dbi(conexion), useBytes = TRUE)) {
    return(character())
  }
  salida <- character()
  for (i in seq_along(campos)) {
    campo <- as.character(campos[[i]])
    tipo <- .atributo_columna_dbi(tipos, campo, i) %||% NA_character_
    if (!.tipo_decimal_o_moneda_dbi(tipo)) next
    x <- datos[[campo]]
    if (!is.double(x) || inherits(x, "integer64")) next
    finitos <- x[is.finite(x)]
    if (!length(finitos)) next
    filas <- .nombres_presentes(columnas$columna, campo)
    if (!any(filas)) next
    desvio <- columnas$desvio[filas][[1L]]
    if (.desvio_mal_condicionado_dbi(desvio, range(finitos), tipo = tipo)) {
      salida <- c(salida, campo)
    }
  }
  salida
}

# El desvio de `perfil_muestra` lo calcula `perfilar()` sobre lo leido, y un
# decimal llega como el doble de su texto. Por la via por omision el resumen lo
# calcula el motor restando en el tipo de la columna y es el exacto; la muestra
# publicaba el de los dobles -3,30971 por 3,32050 en un `numeric(18,2)` de 5e14
# con centavos, medido en PostgreSQL 16 y 9.3, MySQL, MariaDB, DuckDB y SQL
# Server- y la corroboracion lo contaba como divergencia, que
# `perfilar_coleccion()` sube a `alcance = "divergencias"`. No se publica, y la
# columna queda declarada en `meta$desvio_decimal_doble`: la corroboracion lee
# esa declaracion para no comparar lo que un lado no calculo (causa
# `decimal_doble`), en lugar de contar un faltante de un lado.
.tapar_desvio_decimal_doble_perfil_dbi <- function(perfil, columnas_tapar) {
  if (!length(columnas_tapar) || !is.list(perfil) ||
      !is.data.frame(perfil$columnas)) {
    return(perfil)
  }
  if ("desvio" %in% names(perfil$columnas)) {
    perfil$columnas$desvio[
      .nombres_presentes(perfil$columnas$columna, columnas_tapar)
    ] <- NA_real_
  }
  if (!is.list(perfil$meta)) perfil$meta <- list()
  previas <- perfil$meta[["desvio_decimal_doble", exact = TRUE]]
  perfil$meta[["desvio_decimal_doble"]] <- unique(c(
    as.character(previas), as.character(columnas_tapar)
  ))
  perfil
}

# El desvio del spool lo calcula `perfilar()` sobre lo leido: es el caso de la
# via por bloques, y la guarda es la misma. Sin ella, un `numeric(18,2)` de 5e14
# con desvio 3 publicaba por la muestra del motor -el camino por omision de
# `universo = "muestra_motor"`- un desvio a una parte en 300 del exacto, en
# PostgreSQL, MySQL, MariaDB y DuckDB. `perfil_muestra` sale de esos dobles y
# se tapa; el resumen, salvo en las columnas de `desvio_exacto`, cuyo desvio ya
# salio del texto de cada decimal, restado en el decimal
# (`.desvio_decimal_texto_dbi()`).
.tapar_desvio_decimal_doble_muestra_dbi <- function(resultado, datos, campos,
                                                    tipos, conexion = NULL,
                                                    desvio_exacto =
                                                      character()) {
  resumen <- resultado$resumen_tabla
  if (!is.list(resumen)) return(resultado)
  tapar_columnas <- .columnas_desvio_decimal_doble_dbi(
    datos, campos, tipos, resumen$columnas, conexion
  )
  if (!length(tapar_columnas)) return(resultado)
  sql <- resumen$sql
  for (campo in setdiff(tapar_columnas, desvio_exacto)) {
    filas <- .nombres_presentes(resumen$columnas$columna, campo)
    resumen$columnas$desvio[filas] <- NA_real_
    if (is.data.frame(sql) && nrow(sql)) {
      tapar <- .nombres_presentes(sql$columna, campo) &
        as.character(sql$metrica) == "desvio" &
        as.character(sql$estado) %in% .ESTADOS_QUE_AFIRMAN_VALOR_DBI
      sql$estado[tapar] <- "no_disponible"
      sql$motivo[tapar] <- .MOTIVO_DESVIO_DECIMAL_DOBLE_DBI
    }
  }
  resumen$sql <- sql
  resultado$resumen_tabla <- resumen
  if (is.list(resultado$perfil_muestra)) {
    resultado$perfil_muestra <- .tapar_desvio_decimal_doble_perfil_dbi(
      resultado$perfil_muestra, tapar_columnas
    )
  }
  resultado
}

.enmascarar_campos_muestra_dbi <- function(filas, columnas) {
  if (!is.data.frame(filas) || !nrow(filas) || !length(columnas) ||
      !"columna" %in% names(filas)) return(filas)
  indices <- .nombres_presentes(filas$columna, columnas)
  for (campo in intersect(.CAMPOS_MAGNITUD_MUESTRA_DBI, names(filas))) {
    filas[[campo]][indices] <- NA
  }
  filas
}

.redactar_campo_privacidad_dbi <- function(valor, mensaje) {
  if (is.factor(valor)) {
    return(factor(rep(NA_character_, length(valor)), levels = levels(valor)))
  }
  if (is.character(valor)) {
    valor[!is.na(valor)] <- mensaje
    return(valor)
  }
  if (is.numeric(valor) || is.integer(valor) || is.logical(valor)) {
    valor[] <- NA
    return(valor)
  }
  if (is.list(valor)) return(rep(list(NULL), length(valor)))
  valor
}

.redactar_campos_privacidad_dbi <- function(x, campos, mensaje) {
  recorrer <- function(valor, nombre = NULL) {
    if (!is.null(nombre) && length(nombre) == 1L &&
        !is.na(nombre) && nombre %in% campos) {
      valor <- .redactar_campo_privacidad_dbi(valor, mensaje)
    }
    if (is.data.frame(valor)) {
      nombres <- names(valor)
      for (i in seq_along(valor)) {
        valor[[i]] <- recorrer(valor[[i]], nombres[[i]])
      }
    } else if (is.list(valor)) {
      nombres <- names(valor)
      for (i in seq_along(valor)) {
        nombre_hijo <- if (is.null(nombres)) NULL else nombres[[i]]
        valor[i] <- list(recorrer(valor[[i]], nombre_hijo))
      }
    }
    atributos <- attributes(valor)
    if (length(atributos)) {
      for (atributo in names(atributos)) {
        attr(valor, atributo) <- recorrer(
          attr(valor, atributo, exact = TRUE), atributo
        )
      }
    }
    valor
  }
  recorrer(x)
}

.redactar_salida_privacidad_dbi <- function(resumen, perfil) {
  mensaje <- "Omitido por incluir_valores = FALSE."
  campos_celda <- c(
    .CAMPOS_VALOR_MUESTRA_DBI,
    "bbox_xmin", "bbox_xmax", "bbox_ymin", "bbox_ymax"
  )
  if (is.data.frame(resumen$columnas)) {
    for (campo in intersect(campos_celda, names(resumen$columnas))) {
      resumen$columnas[[campo]] <- .redactar_campo_privacidad_dbi(
        resumen$columnas[[campo]], mensaje
      )
    }
  }
  if (is.data.frame(resumen$sql)) {
    # `media`, `desvio`, `n_ceros` y `n_negativos` son estadisticos, no
    # valores de celdas. Sus motivos diagnosticos no deben desaparecer bajo
    # una guarda de privacidad: en particular, un decimal entregado como
    # doble no fue omitido por pedir `incluir_valores = FALSE`. Solo se
    # redactan los motivos de metricas que si publicarian un valor de celda.
    if ("motivo" %in% names(resumen$sql) &&
        "metrica" %in% names(resumen$sql)) {
      tocar_motivo <- as.character(resumen$sql$metrica) %in%
        .CAMPOS_VALOR_MUESTRA_DBI
      resumen$sql$motivo[tocar_motivo] <- mensaje
    } else {
      resumen$sql <- .redactar_campos_privacidad_dbi(
        resumen$sql, "motivo", mensaje
      )
    }
    resumen$sql <- .redactar_campos_privacidad_dbi(
      resumen$sql, "memoria_trabajo", mensaje
    )
  }
  if (is.data.frame(resumen$cobertura)) {
    resumen$cobertura <- .redactar_campos_privacidad_dbi(
      resumen$cobertura, c("motivo", "como_resolverlo"), mensaje
    )
  }
  # Las familias guardan representantes y extremos de los acumuladores por
  # bloque. No son necesarias para interpretar los conteos, asi que se retiran
  # enteras cuando no se pueden publicar valores de celda.
  if (is.list(resumen$meta)) {
    resumen$meta$familias <- NULL
    resumen$meta$corroboracion_bloques <- .redactar_campos_privacidad_dbi(
      resumen$meta$corroboracion_bloques,
      c("motivo", "evidencia", "como_resolverlo"), mensaje
    )
  }
  if (!is.list(perfil)) return(list(resumen = resumen, perfil = perfil))
  if (is.data.frame(perfil$columnas)) {
    for (campo in intersect(campos_celda, names(perfil$columnas))) {
      perfil$columnas[[campo]] <- .redactar_campo_privacidad_dbi(
        perfil$columnas[[campo]], mensaje
      )
    }
  }
  # `ejemplos` son valores de celdas aunque el patron sea estructural. Los
  # demas campos conservan conteos, proporciones y nombres de diagnostico.
  perfil$patrones <- .redactar_campos_privacidad_dbi(
    perfil$patrones, c("ejemplos", "valor", "valores", "representante"),
    mensaje
  )
  perfil$hallazgos <- .redactar_campos_privacidad_dbi(
    perfil$hallazgos, c("descripcion", "evidencia", "sugerencia",
                         "trazabilidad"), mensaje
  )
  perfil$cobertura_diagnosticos <- .redactar_campos_privacidad_dbi(
    perfil$cobertura_diagnosticos, c("motivo", "como_resolverlo"), mensaje
  )
  perfil$datos_personales <- .redactar_campos_privacidad_dbi(
    perfil$datos_personales, c("fundamento", "evidencia"), mensaje
  )
  # Si un adaptador agrega la muestra cruda al perfil, no debe escapar por una
  # via que el perfilador estandar no usa.
  perfil$datos <- NULL
  if (is.list(perfil$meta)) perfil$meta$familias <- NULL
  list(resumen = resumen, perfil = perfil)
}

.aplicar_guardas_salida_muestra_dbi <- function(
    resultado, incluir_valores = TRUE, columnas_decimal = character(),
    motivos_decimal = NULL) {
  if (!is.list(resultado) || !is.list(resultado$resumen_tabla)) {
    return(resultado)
  }
  resumen <- resultado$resumen_tabla
  perfil <- resultado$perfil_muestra
  sql <- resumen$sql
  # La mediana que la via SQL publico por su valor -ver
  # `.causa_mediana_inexacta_dbi()`- no depende de los dobles que la condicion
  # de la columna describe: no se tapa. Solo cuando las columnas salen de los
  # motivos del resumen; el spool las pasa porque sus cifras salen de la
  # muestra leida en R.
  mediana_por_valor <- character()
  if (!length(columnas_decimal) && is.data.frame(sql) && nrow(sql) &&
      all(c("columna", "estado", "motivo") %in% names(sql))) {
    filas_decimal <- as.character(sql$estado) == "no_disponible" &
      grepl(.FRAGMENTO_DECIMAL_DOBLE_DBI, as.character(sql$motivo),
            fixed = TRUE, useBytes = TRUE)
    columnas_decimal <- unique(as.character(sql$columna[filas_decimal]))
    columnas_decimal <- columnas_decimal[!is.na(columnas_decimal)]
    if ("metrica" %in% names(sql)) {
      publicadas <- as.character(sql$metrica) == "mediana" &
        as.character(sql$estado) %in% c("calculado", "estimado") &
        .nombres_presentes(sql$columna, columnas_decimal)
      mediana_por_valor <- unique(as.character(sql$columna[publicadas]))
    }
  }
  # La media y el desvio de un decimal que salieron de las sumas exactas del
  # motor (metodo `sumas_exactas_decimal`) no dependen de esos dobles: tampoco
  # se tapan.
  exactas <- if (is.data.frame(sql) && nrow(sql) &&
                 all(c("columna", "metrica", "estado", "metodo") %in% names(sql))) {
    as.character(sql$metrica) %in% c("media", "desvio") &
      as.character(sql$estado) %in% c("calculado", "estimado") &
      as.character(sql$metodo) %in% "sumas_exactas_decimal"
  } else logical()
  if (length(columnas_decimal)) {
    if (is.data.frame(resumen$columnas)) {
      medianas <- if ("mediana" %in% names(resumen$columnas)) {
        resumen$columnas$mediana
      }
      previas <- resumen$columnas
      resumen$columnas <- .enmascarar_campos_muestra_dbi(
        resumen$columnas, columnas_decimal
      )
      if (length(mediana_por_valor) && !is.null(medianas)) {
        conservar <- .nombres_presentes(
          resumen$columnas$columna, mediana_por_valor
        )
        resumen$columnas$mediana[conservar] <- medianas[conservar]
      }
      for (metrica in intersect(c("media", "desvio"), names(previas))) {
        columnas_exactas <- unique(as.character(
          sql$columna[exactas & as.character(sql$metrica) == metrica]
        ))
        if (!length(columnas_exactas)) next
        conservar <- .nombres_presentes(
          resumen$columnas$columna, columnas_exactas
        )
        resumen$columnas[[metrica]][conservar] <- previas[[metrica]][conservar]
      }
    }
    if (is.data.frame(sql) && nrow(sql)) {
      # Una metrica que no se pidio sigue siendo no pedida: la guarda del
      # decimal habla de las que se midieron. Y el motivo es el del decimal, no
      # el de la primera fila de la columna: con `metricas` sin `mediana`, esa
      # fila era la de `mediana` y su "no se pidio" pasaba a `minimo`,
      # `maximo` y `media`, que si se habian pedido.
      tocar <- .nombres_presentes(sql$columna, columnas_decimal) &
        as.character(sql$metrica) %in% .CAMPOS_MAGNITUD_MUESTRA_DBI &
        !(as.character(sql$estado) %in% "no_solicitado") & !exactas &
        !(as.character(sql$metrica) == "mediana" &
            .nombres_presentes(sql$columna, mediana_por_valor))
      sql$estado[tocar] <- "no_disponible"
      sql$motivo[tocar] <- vapply(sql$columna[tocar], function(columna) {
        if (!is.null(motivos_decimal) && !is.null(motivos_decimal[[columna]])) {
          return(as.character(motivos_decimal[[columna]]))
        }
        propios <- as.character(sql$motivo[
          .nombres_presentes(sql$columna, columna)
        ])
        propios <- propios[!is.na(propios) & grepl(
          .FRAGMENTO_DECIMAL_DOBLE_DBI, propios, fixed = TRUE, useBytes = TRUE
        )]
        if (length(propios)) propios[[1L]] else .motivo_decimal_doble_dbi()
      }, character(1L), USE.NAMES = FALSE)
      resumen$sql <- sql
    }
    if (is.list(perfil) && is.data.frame(perfil$columnas)) {
      perfil$columnas <- .enmascarar_campos_muestra_dbi(
        perfil$columnas, columnas_decimal
      )
    }
  }
  if (!isTRUE(incluir_valores)) {
    if (is.data.frame(resumen$columnas)) {
      campos <- intersect(.CAMPOS_VALOR_MUESTRA_DBI, names(resumen$columnas))
      for (campo in campos) resumen$columnas[[campo]][] <- NA
    }
    if (is.data.frame(sql) && nrow(sql)) {
      tocar <- as.character(sql$metrica) %in% c(
        "moda", "minimo", "maximo", "mediana", "minimo_fecha",
        "maximo_fecha", "media_fecha", "mediana_fecha", "centinela_valor"
      )
      sql$estado[tocar] <- "omitido_por_privacidad"
      sql$motivo[tocar] <- paste(
        "El valor no se informa por incluir_valores = FALSE.",
        "La salida no publica valores de celda."
      )
      if ("memoria_trabajo" %in% names(sql)) {
        sql$memoria_trabajo[tocar] <- NA_character_
      }
      resumen$sql <- sql
    }
    if (is.list(perfil)) {
      if (is.data.frame(perfil$columnas)) {
        campos <- intersect(.CAMPOS_VALOR_MUESTRA_DBI, names(perfil$columnas))
        for (campo in campos) perfil$columnas[[campo]][] <- NA
      }
      perfil$meta$incluir_valores <- FALSE
    }
  }
  if (!isTRUE(incluir_valores)) {
    privado <- .redactar_salida_privacidad_dbi(resumen, perfil)
    resumen <- privado$resumen
    perfil <- privado$perfil
    if (is.data.frame(resumen$sql) && "sql" %in% names(resumen$sql)) {
      resumen$sql$sql <- .tapar_centros_sql_dbi(resumen$sql$sql)
    }
  }
  resumen$meta$incluir_valores <- isTRUE(incluir_valores)
  resultado$resumen_tabla <- resumen
  if (is.list(perfil)) resultado$perfil_muestra <- perfil
  resultado
}

.solicita_muestra_dbi <- function(bloque_muestra) {
  identical(bloque_muestra, "con_muestra")
}

.preparar_dbi <- function(conexion, tabla, universo, muestra_motor, muestra,
                          orden_muestra, estrategia_mediana, metricas,
                          max_consultas, dialecto, tamano_lote = NULL,
                          tamano_lote_planos = .TAMANO_LOTE_PLANOS_DBI,
                          tamano_lote_distintos = .TAMANO_LOTE_DISTINTOS_DBI,
                          bloque_muestra, instrumentar = TRUE,
                          contar = TRUE, incluir_valores = TRUE,
                          estrategia_distintos = "exacta",
                          politica_costo = "todas",
                          umbral_cardinalidad = .UMBRAL_CARDINALIDAD_COSTO_DBI,
                          contar_muestreo = TRUE,
                          sondar_muestreo = TRUE,
                          max_bytes_procesamiento = .MAX_BYTES_MUESTRA,
                          max_bytes_materializacion = .MAX_BYTES_MUESTRA) {
  .requerir_dbi()
  max_bytes_procesamiento <- .validar_presupuesto_bytes_dbi(
    max_bytes_procesamiento, "max_bytes_procesamiento"
  )
  max_bytes_materializacion <- .validar_presupuesto_bytes_dbi(
    max_bytes_materializacion, "max_bytes_materializacion"
  )
  universo <- .argumento_dbi(
    .elegir_opcion(universo, c("tabla_completa", "muestra_motor"))
  )
  estrategia_mediana <- .argumento_dbi(.elegir_opcion(
    estrategia_mediana, c("exacta", "aproximada_motor")
  ))
  dialecto <- .argumento_dbi(.elegir_opcion(
    dialecto, c("auto", "limit", "top", "fetch_first", "rownum", "portable")
  ))
  muestra <- .validar_muestra_dbi(muestra)
  if (identical(universo, "muestra_motor")) {
    if (!is.numeric(muestra_motor) || length(muestra_motor) != 1L ||
        is.na(muestra_motor) || !is.finite(muestra_motor) ||
        muestra_motor < 1 || muestra_motor != floor(muestra_motor)) {
      .detener_dbi(
        "lupa_error_argumento_dbi",
        "`muestra_motor` debe ser un entero positivo finito cuando `universo = \"muestra_motor\"`."
      )
    } else {
      muestra_motor <- as.numeric(muestra_motor)
    }
    if (identical(estrategia_mediana, "aproximada_motor")) {
      .detener_dbi(
        "lupa_error_argumento_dbi",
        "`universo = \"muestra_motor\"` no se puede combinar con `estrategia_mediana = \"aproximada_motor\"`: la muestra ya es una aproximaci\u00f3n del universo."
      )
    }
  } else if (!is.null(muestra_motor)) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      "`muestra_motor` s\u00f3lo se puede usar con `universo = \"muestra_motor\"`."
    )
  }
  bloque_muestra <- .argumento_dbi(.elegir_opcion(
    bloque_muestra, c("con_muestra", "solo_agregados")
  ))
  if (identical(bloque_muestra, "solo_agregados")) {
    orden_muestra <- NULL
  }
  # Sin validar, `incluir_valores = NA` abortaba con el error de R "valor
  # ausente donde TRUE/FALSE es necesario".
  if (!is.logical(incluir_valores) || length(incluir_valores) != 1L ||
      is.na(incluir_valores)) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      "`incluir_valores` debe ser TRUE o FALSE."
    )
  }
  metricas_solicitadas <- .validar_metricas_dbi(metricas)
  politica_costo <- .validar_politica_costo_dbi(
    politica_costo, umbral_cardinalidad
  )
  estrategia_distintos <- .validar_estrategia_distintos_dbi(
    estrategia_distintos
  )
  metricas <- .metricas_para_politica_costo_dbi(
    metricas_solicitadas, politica_costo, incluir_valores
  )
  max_consultas <- .validar_max_consultas_dbi(max_consultas)
  tamanos_lote <- .resolver_tamanos_lote_dbi(
    tamano_lote, tamano_lote_planos, tamano_lote_distintos
  )
  if (!is.logical(instrumentar) || length(instrumentar) != 1L ||
      is.na(instrumentar)) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      "`instrumentar` debe ser TRUE o FALSE."
    )
  }
  if (!.es_conexion_dbi(conexion)) {
    .detener_dbi(
      "lupa_error_conexion_dbi",
      "`conexion` debe ser una conexi\u00f3n DBI: no hereda de `DBIConnection`."
    )
  }
  if (!.conexion_valida_dbi(conexion)) {
    .detener_dbi(
      "lupa_error_conexion_dbi",
      "`conexion` debe ser una conexi\u00f3n DBI abierta y v\u00e1lida."
    )
  }
  presupuesto <- .presupuesto_dbi(max_consultas, instrumentar = instrumentar)
  .contar_dbi(presupuesto)
  # El nombre se normaliza y pasa por la guarda ANTES de la primera llamada que
  # toca la conexion: con un nombre marcado latin1, `dbExistsTable()` de odbc
  # dejaba la conexion rota y la consulta siguiente del usuario hacia caer a R.
  # Ver `.nombre_para_conexion_dbi()`.
  tabla <- .nombre_para_conexion_dbi(tabla)
  .exigir_nombre_representable_dbi(
    conexion, tabla, que = "La tabla no se puede leer: su nombre"
  )
  # Un nombre de dos partes con punto es lo que cualquiera escribe, y
  # `dbExistsTable()` no lo resuelve: lo toma como un nombre literal. Antes esto
  # hacia que `coleccion("esquema.tabla")` funcionara y `perfilar_dbi()` con el
  # mismo texto fallara diciendo que la tabla no existe. Se conserva el literal
  # cuando existe y, si no, se usa el mismo parseo que `coleccion()`.
  existe <- tryCatch(
    .existe_tabla_dbi(conexion, tabla),
    error = function(e) e
  )
  if (inherits(existe, "condition")) {
    if (inherits(existe, "lupa_error_codificacion_dbi")) {
      .detener_dbi(
        "lupa_error_codificacion_dbi", conditionMessage(existe)
      )
    }
    .detener_dbi("lupa_error_tabla_dbi", paste0(
      "No se pudo comprobar `tabla`: ", .mensaje_motor(existe)
    ))
  }
  if (is.character(tabla) && length(tabla) == 1L && !is.na(tabla) &&
      grepl(".", tabla, fixed = TRUE, useBytes = TRUE)) {
    if (!isTRUE(existe)) {
      cortado <- tryCatch(.partir_identificador(tabla), error = function(e) NULL)
      partes <- if (!is.null(cortado) && !isTRUE(cortado$abierto)) {
        vapply(cortado$partes, .quitar_comillas_identificador, character(1L),
               USE.NAMES = FALSE)
      } else character()
      if (length(partes) == 2L && all(nzchar(partes))) {
        tabla <- DBI::Id(schema = partes[[1L]], table = partes[[2L]])
      }
    }
  }
  tabla_sql <- .citar_identificador_dbi(
    conexion, tabla, que = "La tabla no se puede leer: su nombre"
  )
  if (!.sentencia_representable_dbi(conexion, tabla_sql)) {
    .detener_dbi(
      "lupa_error_codificacion_dbi",
      .motivo_no_representable_dbi("La tabla no se puede leer: su nombre")
    )
  }
  motivo_existe <- NA_character_
  if (!isTRUE(existe)) {
    # Algunos controladores no implementan nombres calificados en
    # `dbExistsTable()`. La consulta no trae datos y confirma la tabla sin
    # depender de una API de metadatos incompleta.
    comprobacion <- .consultar_dbi(
      conexion, paste0("SELECT 1 FROM ", tabla_sql, " WHERE 1 = 0"),
      presupuesto, etapa = "porton_tabla"
    )
    existe <- isTRUE(comprobacion$ok)
    if (!isTRUE(existe)) motivo_existe <- comprobacion$motivo
  }
  if (!isTRUE(existe)) {
    .detener_dbi("lupa_error_tabla_dbi", paste(
      .mensaje_tabla_inaccesible_dbi(motivo_existe)
    ))
  }
  lista_campos <- .campos_dbi(conexion, tabla, tabla_sql, presupuesto)
  campos_declarados <- lista_campos$campos
  if (!is.null(orden_muestra) &&
      (!is.character(orden_muestra) || !length(orden_muestra) ||
       anyNA(orden_muestra) || any(!nzchar(orden_muestra)))) {
    .detener_dbi(
      "lupa_error_argumento_dbi",
      "`orden_muestra` debe ser NULL o nombres de columnas."
    )
  }
  if (length(orden_muestra)) {
    for (columna in orden_muestra) {
      .exigir_nombre_representable_dbi(
        conexion, columna, que = "La columna de `orden_muestra`"
      )
    }
    posicion <- .resolver_columnas_dbi(orden_muestra, campos_declarados)
    if (anyNA(posicion)) {
      .detener_dbi("lupa_error_argumento_dbi", paste0(
        "Columnas de `orden_muestra` inexistentes: ",
        paste(orden_muestra[is.na(posicion)], collapse = ", "), "."
      ))
    }
    orden_muestra <- campos_declarados[posicion]
  }

  permisos <- lista_campos$columnas
  sin_permiso <- if (is.null(permisos)) character() else permisos$ilegibles
  esquema <- tryCatch(
    .esquema_dbi(
      conexion, tabla_sql, campos_declarados, presupuesto,
      sin_permiso = sin_permiso,
      sql_catalogo = if (is.null(permisos)) NA_character_ else permisos$sql_catalogo
    ),
    error = function(e) {
      bloqueado <- isTRUE(presupuesto$agotado) && grepl(
        "presupuesto declarado", conditionMessage(e), fixed = TRUE,
        useBytes = TRUE
      )
      if (!bloqueado) .detener(e)
      .esquema_minimo_por_presupuesto_dbi(
        conexion, tabla_sql, campos_declarados, lista_campos,
        .motivo_presupuesto_dbi(presupuesto)
      )
    }
  )
  # SQL Server/FreeTDS publica codigos ODBC que no distinguen `geography` de
  # otros tipos binarios. El catalogo ya leyo el nombre del tipo: usarlo en
  # todas las decisiones evita mandar agregados que el motor rechaza.
  tipos_catalogo <- if (is.null(permisos)) NULL else permisos$tipos_motor
  # En PostgreSQL el catalogo devuelve `format_type()` -por ejemplo,
  # `character(10)`-, pero la lectura comun necesita el `typname` de DBI
  # (`bpchar`) para emitir `RTRIM()` en todas sus puertas. El tipo del catalogo
  # se conserva para las relaciones; solo reemplaza el codigo ODBC en SQL
  # Server, donde hace falta distinguir LOB y geography para no emitir SQL que
  # el motor rechaza. En PostgreSQL tambien conserva la precision declarada de
  # los numericos anchos; en MySQL y MariaDB reemplaza la clase ambigua que
  # devuelven algunos controladores (`BLOB/TEXT`, `VAR_STRING` o `raw`).
  if (.motor_permisos_columnas_dbi(conexion) %in%
      c("sqlserver", "mysql", "postgresql") &&
      is.list(permisos) && length(tipos_catalogo) &&
      length(esquema$campos)) {
    posiciones_tipo <- .indice_nombre(esquema$campos, names(tipos_catalogo))
    tipos_catalogo_texto <- as.character(tipos_catalogo[posiciones_tipo])
    catalogo_decimal_preciso <- if (
      identical(.motor_permisos_columnas_dbi(conexion), "postgresql")
    ) {
      !is.na(tipos_catalogo_texto) & grepl(
        "^(numeric|decimal|number)\\(", tipos_catalogo_texto, perl = TRUE
      )
    } else rep(TRUE, length(posiciones_tipo))
    conocidos <- !is.na(posiciones_tipo) & catalogo_decimal_preciso
    if (any(conocidos)) {
      tipos_motor <- if (is.null(esquema$tipos_motor)) {
        rep(NA_character_, length(esquema$campos))
      } else as.character(esquema$tipos_motor)
      if (length(tipos_motor) < length(esquema$campos)) {
        length(tipos_motor) <- length(esquema$campos)
      }
      tipos_motor[conocidos] <- unname(tipos_catalogo[posiciones_tipo[conocidos]])
      esquema$tipos_motor <- tipos_motor
    }
  }
  # Las que llegan enmascaradas se leen -su completitud es la del dato- y se
  # declaran: ver `.columnas_tabla_dbi()` y `perfilar_dbi()`.
  enmascaradas <- if (is.null(permisos)) character() else {
    permisos$enmascaradas[.nombres_presentes(permisos$enmascaradas, esquema$campos)]
  }
  mascaras <- if (is.null(permisos)) character() else {
    permisos$mascaras[.nombres_presentes(names(permisos$mascaras), enmascaradas)]
  }
  # El nombre de la tabla queda aparte de la relacion que se lee: con una
  # columna sin permiso SQL Server rechaza toda consulta sobre la tabla, tambien
  # `COUNT(*)`, y TODA lectura -conteo, agregados, muestra, bloques- va sobre una
  # tabla derivada con las columnas legibles (ver `.columnas_tabla_dbi()`). Lo
  # que necesita el nombre -catalogos, la proteccion de los nombres de la
  # tabla- usa `tabla_nombre_sql`.
  tabla_nombre_sql <- tabla_sql
  if (length(esquema$sin_permiso) && !is.null(permisos) &&
      isTRUE(permisos$proyectar)) {
    tabla_sql <- paste0(
      "(SELECT ", paste(esquema$campos_sql, collapse = ", "), " FROM ",
      tabla_nombre_sql, ") AS ",
      .citar_identificador_dbi(conexion, "lupa_legibles")
    )
  }
  campos <- esquema$campos
  prototipo <- esquema$prototipo
  # Las clases de R de las columnas se conocen aca, antes de leer un valor: es
  # el unico punto de la via fuera de los manejadores que convierten un error
  # de consulta en una metrica no calculada. Ver `.exigir_integer64_confiable()`.
  .exigir_integer64_confiable(prototipo, via_dbi = TRUE)
  if (length(names(prototipo)) == length(campos) &&
      !identical(.nombres_para_operar(names(prototipo)),
                 .nombres_para_operar(campos))) {
    campos <- names(prototipo)
  }
  atributos <- .alinear_atributos_columnas_dbi(
    campos, prototipo = prototipo, tipos = esquema$tipos,
    tipos_motor = esquema$tipos_motor
  )
  prototipo <- atributos$prototipo
  esquema$prototipo <- prototipo
  esquema$tipos <- atributos$tipos
  esquema$tipos_motor <- atributos$tipos_motor
  orden_sql <- if (length(orden_muestra)) {
    posicion <- .resolver_columnas_dbi(orden_muestra, campos)
    if (anyNA(posicion)) {
      faltan <- orden_muestra[is.na(posicion)]
      negadas <- faltan[.nombres_presentes(faltan, esquema$sin_permiso)]
      if (length(negadas)) {
        .detener_dbi("lupa_error_esquema_dbi", paste0(
          "No se puede ordenar la muestra por `orden_muestra`: la credencial ",
          "no tiene permiso SELECT sobre ", paste(negadas, collapse = ", "),
          " (lo dice el cat\u00e1logo del motor). Elegir columnas legibles."
        ))
      }
      # Una columna que la sesion no puede escribir no la rechazo el motor: no
      # se le mando. El motivo es el de la guarda, con su remedio, como en
      # `relaciones_coleccion()`. Antes, bajo `C`,
      # `orden_muestra = "a\u00f1o"` por odbc decia "El motor rechazo las
      # columnas de `orden_muestra`: a\u00f1o."
      sin_escribir <- if (length(esquema$no_representables)) {
        faltan[!is.na(.indice_nombre(faltan, esquema$no_representables))]
      } else character()
      if (length(sin_escribir)) {
        .detener_dbi("lupa_error_codificacion_dbi", .motivo_no_representable_dbi(
          paste0(
            "La columna de `orden_muestra` ",
            paste0("`", .comillas_sin_locale(sin_escribir), "`", collapse = ", ")
          ),
          texto = sin_escribir
        ))
      }
      motivos <- vapply(faltan, function(columna) {
        motivo <- esquema$motivos[[columna]]
        if (is.null(motivo)) "" else paste0(" (", motivo, ")")
      }, character(1L), USE.NAMES = FALSE)
      .detener_dbi("lupa_error_esquema_dbi", paste0(
        "El motor rechaz\u00f3 las columnas de `orden_muestra`: ",
        paste0(faltan, motivos, collapse = ", "), "."
      ))
    }
    orden_muestra <- campos[posicion]
    tipos_orden <- if (length(lista_campos$tipos_motor)) {
      posiciones_tipo <- .indice_nombre(orden_muestra,
                                        names(lista_campos$tipos_motor))
      as.character(lista_campos$tipos_motor[posiciones_tipo])
    } else character()
    si_tipo_no_ordenable <- if (any(grepl(
      "sql server|microsoft sql|sqlserver|mssql",
      .senas_conexion_dbi(conexion), perl = TRUE, useBytes = TRUE
    )) && length(tipos_orden)) {
      vapply(tipos_orden, .tipo_sqlserver_sin_agregados_dbi, logical(1L))
    } else logical(length(tipos_orden))
    if (any(si_tipo_no_ordenable, na.rm = TRUE)) {
      .detener_dbi(
        "lupa_error_argumento_dbi",
        paste0(
          "SQL Server no puede ordenar `orden_muestra` por las columnas de tipo ",
          "no comparable: ",
          paste(orden_muestra[which(si_tipo_no_ordenable)], collapse = ", "), "."
        )
      )
    }
    vapply(orden_muestra, function(campo) {
      .citar_identificador_dbi(conexion, campo)
    }, character(1L), USE.NAMES = FALSE)
  } else {
    character()
  }
  # La forma de la consulta obligatoria se prueba antes de gastar el bloque de
  # agregados: proyeccion, ORDER BY y clausula de limite, con cero filas.
  sql_forma <- paste0(
    "SELECT ", paste(esquema$campos_sql, collapse = ", "), " FROM ", tabla_sql,
    " WHERE 1 = 0",
    if (length(orden_sql)) paste0(" ORDER BY ", paste(orden_sql, collapse = ", ")) else ""
  )
  resolucion <- .resolver_dialecto_dbi(
    conexion, sql_forma, dialecto, presupuesto
  )
  es_numerico <- vapply(seq_along(campos), function(i) {
    .es_numerico_dbi(
      .atributo_columna_dbi(prototipo, campos[[i]], i),
      .atributo_columna_dbi(esquema$tipos, campos[[i]], i) %||% NA_character_
    )
  }, logical(1L))
  names(es_numerico) <- campos
  tipos_motor <- if (is.null(esquema$tipos_motor)) {
    rep(NA_character_, length(campos))
  } else as.character(esquema$tipos_motor)
  if (length(tipos_motor) < length(campos)) length(tipos_motor) <- length(campos)
  names(tipos_motor) <- campos
  tipos_sin_agregados <- if (any(grepl(
    "sql server|microsoft sql|sqlserver|mssql",
    .senas_conexion_dbi(conexion), perl = TRUE, useBytes = TRUE
  ))) {
    vapply(
      tipos_motor[seq_along(campos)], .tipo_sqlserver_sin_agregados_dbi,
      logical(1L)
    )
  } else logical(length(campos))
  # Estas columnas siguen pudiendo aportar `validos`, pero no se incluyen en
  # ninguna consulta de distintos, moda, magnitudes u ordenamiento SQL.
  es_numerico[tipos_sin_agregados] <- FALSE
  muestreo <- NULL
  if (identical(universo, "muestra_motor")) {
    if (isTRUE(sondar_muestreo)) {
      muestreo <- .sondar_muestreo_dbi(
        conexion, tabla_sql, resolucion$dialecto, presupuesto,
        tipo_objeto = lista_campos$tipo_objeto
      )
      muestreo$sondas_previstas <- length(muestreo$sondas)
    } else {
      # Elegir una candidata por las senas del motor no comprueba que funcione:
      # el plan no puede pagar una sonda que ya lee la tabla solo para saberlo.
      # Publica las sondas que la corrida intentara y deja la verificacion para
      # la corrida; si fallan, el resultado se degrada como cualquier capacidad.
      candidatos <- .candidatos_muestreo_dbi(
        conexion, resolucion$dialecto, lista_campos$tipo_objeto
      )
      muestreo <- list(
        disponible = length(candidatos) > 0L,
        candidato = if (length(candidatos)) candidatos[[1L]] else NULL,
        sondas = character(),
        sondas_previstas = .sondas_muestreo_previstas_dbi(candidatos),
        motivo = "La capacidad de muestreo queda sin sondear hasta la corrida."
      )
    }
    estado_forma <- .estado_forma_muestreo_dbi(
      muestreo$candidato, tabla_sql, esquema$campos_sql, muestra_motor,
      resolucion$dialecto
    )
    muestreo$forma_construible <- estado_forma$forma_construible
    if (!isTRUE(estado_forma$forma_construible)) {
  # La corrida y el plan comparten esta decision estructural: no hay una
      # consulta de datos que pueda producir metricas sobre una muestra que no
      # se puede escribir. La lista de metricas solicitadas se conserva para
      # publicar cada ausencia, pero no se intenta emitirlas.
      if (!is.null(muestreo$candidato)) {
        muestreo$disponible <- FALSE
        if (is.null(muestreo$sondas) || !length(muestreo$sondas) ||
            grepl("no pudo construir", muestreo$motivo, fixed = TRUE, useBytes = TRUE) ||
            grepl("sin sondear", muestreo$motivo, fixed = TRUE, useBytes = TRUE)) {
          muestreo$motivo <- estado_forma$motivo
        }
      }
      # No tiene sentido sondear moda, mediana ni cardinalidad para una
      # muestra que ya sabemos que no se puede escribir. `metricas_solicitadas`
      # conserva el pedido para que el resumen publique sus ausencias.
      metricas <- character()
    }
  }
  estrategia_distintos <- .estrategia_distintos_dbi(
    metricas_solicitadas, politica_costo, incluir_valores,
    estrategia_distintos
  )
  estrategia_distintos <- .resolver_estrategia_distintos_dbi(
    conexion, estrategia_distintos,
    presupuesto, "distintos" %in% metricas,
    tabla = tabla, columnas = campos, universo = universo
  )
  fuentes_cardinalidad_costo <- .fuentes_cardinalidad_vacias_dbi(campos)
  catalogo_cardinalidad <- NULL
  # La disponibilidad gobierna la medicion de cardinalidad, no la lectura de
  # una garantia estructural que no recorre la tabla. La consulta de catalogo
  # tampoco recorre la tabla y se hace en todas las corridas para publicar la
  # misma informacion en `meta$clave`.
  fuentes <- .resolver_fuentes_cardinalidad_dbi(
    conexion, tabla, campos, estrategia_distintos, presupuesto
  )
  fuentes_cardinalidad_costo <- fuentes$fuentes
  catalogo_cardinalidad <- fuentes$catalogo
  fuentes_no_exactas <- vapply(
    fuentes_cardinalidad_costo,
    function(x) !isTRUE(x$exacta), logical(1L)
  )
  muestreo_ejecutable <- !identical(universo, "muestra_motor") ||
    isTRUE(muestreo$disponible)
  estrategia_distintos$requiere_medicion <- if (identical(
    estrategia_distintos$estado, "estimado_catalogo"
  )) {
    FALSE
  } else {
    (isTRUE(estrategia_distintos$publica) &&
       isTRUE(estrategia_distintos$disponible) &&
       isTRUE(muestreo_ejecutable) &&
       (identical(universo, "muestra_motor") || any(fuentes_no_exactas))) ||
      (isTRUE(estrategia_distintos$para_costo) &&
       isTRUE(estrategia_distintos$disponible) &&
       isTRUE(muestreo_ejecutable) && any(fuentes_no_exactas))
  }
  # Una estrategia no disponible no abre una segunda oportunidad para ejecutar
  # el conteo exacto. Se quita de la ejecucion, pero queda en `metricas` para
  # que el resumen publique el motivo de la ausencia.
  if (!isTRUE(estrategia_distintos$disponible)) {
    metricas <- setdiff(metricas, "distintos")
  }
  aproximaciones <- list()
  aproximaciones_resolucion <- list()
  moda_guardian_resolucion <- NULL
  moda_guardian <- NULL
  mediana_consolidada_resolucion <- NULL
  mediana_consolidada <- NULL
  mediana_escalar_resolucion <- NULL
  mediana_escalar <- NULL
  mediana_cte_ventana_resolucion <- NULL
  mediana_cte_ventana <- NULL
  mediana_cte_ventana_motivo <- NA_character_
  if ("moda" %in% metricas && isTRUE(incluir_valores)) {
    moda_guardian_resolucion <- .sondar_moda_guardian_dbi(
      conexion, resolucion$dialecto, presupuesto
    )
    if (isTRUE(moda_guardian_resolucion$disponible)) {
      moda_guardian <- moda_guardian_resolucion$candidato
    }
  }
  if ("mediana" %in% metricas && isTRUE(incluir_valores) &&
      any(es_numerico)) {
    mediana_consolidada_resolucion <- .sondar_mediana_consolidada_dbi(
      conexion, presupuesto
    )
    if (isTRUE(mediana_consolidada_resolucion$disponible)) {
      mediana_consolidada <- mediana_consolidada_resolucion$candidato
    }
  }
  if (identical(estrategia_distintos$estrategia_solicitada,
                "aproximada_motor") &&
      isTRUE(estrategia_distintos$disponible)) {
    resolucion_distintos <- list(
      disponible = TRUE, candidato = estrategia_distintos$candidato,
      sondas = estrategia_distintos$sondas,
      motivo = estrategia_distintos$motivo
    )
    aproximaciones_resolucion$distintos <- resolucion_distintos
    aproximaciones$distintos <- estrategia_distintos$candidato
  }
  if ("mediana" %in% metricas && isTRUE(incluir_valores) &&
      any(es_numerico) && is.null(mediana_consolidada) &&
      is.null(mediana_escalar)) {
    mediana_escalar_resolucion <- .sondar_mediana_escalar_dbi(
      conexion, resolucion$dialecto, presupuesto,
      materializar = identical(universo, "muestra_motor")
    )
    if (isTRUE(mediana_escalar_resolucion$disponible)) {
      mediana_escalar <- mediana_escalar_resolucion$candidato
    }
  }
  if (identical(universo, "muestra_motor") && "mediana" %in% metricas &&
      isTRUE(incluir_valores) && any(es_numerico) &&
      is.null(mediana_consolidada) && is.null(mediana_escalar)) {
    mediana_cte_ventana_resolucion <- .sondar_mediana_cte_ventana_dbi(
      conexion, presupuesto
    )
    mediana_cte_ventana_motivo <- mediana_cte_ventana_resolucion$motivo
    if (isTRUE(mediana_cte_ventana_resolucion$disponible)) {
      mediana_cte_ventana <- mediana_cte_ventana_resolucion$candidato
      mediana_cte_ventana$nombre <- .nombre_mediana_cte_muestra_dbi(
        muestreo
      )
    }
  }
  if ("mediana" %in% metricas && isTRUE(incluir_valores) &&
      any(es_numerico) && identical(estrategia_mediana, "aproximada_motor") &&
      is.null(mediana_consolidada) && is.null(mediana_escalar)) {
    resolucion_mediana <- .sondar_aproximacion_dbi(
      conexion, "mediana", presupuesto
    )
    aproximaciones_resolucion$mediana <- resolucion_mediana
    if (isTRUE(resolucion_mediana$disponible)) {
      aproximaciones$mediana <- resolucion_mediana$candidato
    }
  }
  sql_conteo <- paste0(
    "SELECT ", .conteo_sql_dbi("COUNT(*)", .senas_conexion_dbi(conexion)),
    " AS ",
    .citar_identificador_dbi(conexion, "lupa_n_total"),
    " FROM ", tabla_sql
  )
  # El plan necesita el total antes de estimar el trabajo y conserva por eso el
  # conteo como porton propio. En una corrida, en cambio, el total viaja con la
  # primera consulta de agregados. Las formas de TABLESAMPLE necesitan conocer
  # el total antes de poder escribir su porcentaje; ese es el unico camino de
  # una corrida que paga el porton por adelantado para no cambiar su muestra.
  contar_adelante <- isTRUE(contar) || (
    isTRUE(contar_muestreo) && identical(universo, "muestra_motor") &&
      !is.null(muestreo) &&
      !is.null(muestreo$candidato) &&
      (identical(muestreo$candidato$tipo, "tablesample") ||
       (identical(muestreo$candidato$tipo, "aleatorio") &&
        any(vapply(
          muestreo$candidato$funciones,
          function(funcion) identical(funcion$nombre, "newid"),
          logical(1L)
        ))))
  )
  conteo <- NULL
  n_total <- NA_real_
  if (contar_adelante) {
    conteo <- .escalar_dbi(
      conexion, sql_conteo, "lupa_n_total", presupuesto,
      etapa = "conteo_filas"
    )
    if (!conteo$ok) {
      if (!.consulta_bloqueada_por_presupuesto_dbi(conteo, presupuesto)) {
        .detener_dbi("lupa_error_conteo_dbi", paste0(
          "No se pudo contar la tabla: ", conteo$motivo
        ), datos = list(sql = sql_conteo))
      }
      # TABLESAMPLE y NEWID necesitan el total para construir una fraccion
      # real. Sin el, publicar una forma con 100% seria afirmar una seleccion
      # que puede ser la tabla entera. La corrida sigue y deja la muestra en
      # `no_disponible`, como el resto de las metricas que quedaron afuera.
      n_total <- NA_real_
      if (identical(universo, "muestra_motor") && !is.null(muestreo)) {
        muestreo$disponible <- FALSE
        muestreo$motivo <- paste(
          "No se pudo obtener el total para construir la muestra del motor:",
          .motivo_presupuesto_dbi(presupuesto)
        )
      }
    } else {
      n_total <- .conteo_dbi(conteo$valor)
      if (is.na(n_total)) {
        .detener_dbi("lupa_error_conteo_dbi", paste0(
          "La consulta de conteo no devolvi\u00f3 un n\u00famero utilizable. SQL: ",
          sql_conteo
        ), datos = list(sql = sql_conteo))
      }
    }
  }
  hay_agregados_fusionables <- length(campos) > 0L && (
    any(metricas %in% c("validos", "distintos")) ||
      any(es_numerico) && any(metricas %in% c("basicos", "desvio"))
  )
  columnas_distintos_ejecucion <- .columnas_distintos_ejecucion_dbi(
    metricas, estrategia_distintos, campos,
    fuentes_cardinalidad_costo, politica_costo
  )
  columnas_distintos_ejecucion <- setdiff(
    columnas_distintos_ejecucion, campos[tipos_sin_agregados]
  )
  columnas_moda_estimacion <- if (
    "moda" %in% metricas && isTRUE(incluir_valores)
  ) setdiff(campos, campos[tipos_sin_agregados]) else character()
  columnas_mediana_estimacion <- if (
    "mediana" %in% metricas && isTRUE(incluir_valores)
  ) campos[es_numerico] else character()
  columnas_catalogo_derrame <- unique(c(
    columnas_distintos_ejecucion,
    columnas_moda_estimacion,
    columnas_mediana_estimacion
  ))
  # Se consulta el catalogo una sola vez por corrida. En la corrida real el
  # aviso se emite mas tarde, cuando los agregados planos ya terminaron, pero
  # los datos de la estimacion quedan listos antes del primer distinto. En el
  # plan esto sigue siendo solo lectura de metadatos, nunca una medicion.
  presupuesto$estimacion_derrame <- .estimar_derrame_postgresql_dbi(
    conexion, tabla, columnas_distintos_ejecucion, presupuesto,
    exacto = identical(estrategia_distintos$estrategia_resuelta, "COUNT(DISTINCT)"),
    universo = universo, tamano_lote = tamanos_lote$distintos,
    columnas_stats = columnas_catalogo_derrame
  )
  forma_mediana_estimacion <- if (!is.null(mediana_consolidada)) {
    "consolidada"
  } else if (!is.null(mediana_escalar)) {
    "subconsulta_escalar"
  } else {
    "dos_consultas"
  }
  presupuesto$estimacion_derrame_moda <-
    .estimar_derrame_familia_postgresql_dbi(
      conexion, tabla, columnas_moda_estimacion, presupuesto, "moda",
      universo = universo, tamano_lote = tamanos_lote$planos,
      forma = NA_character_, dialecto = resolucion$dialecto,
      moda_guardian = moda_guardian, tipos = esquema$tipos,
      prototipo = prototipo, tabla_sql = tabla_sql
    )
  presupuesto$estimacion_derrame_mediana <-
    .estimar_derrame_familia_postgresql_dbi(
      conexion, tabla, columnas_mediana_estimacion, presupuesto, "mediana",
      universo = universo, tamano_lote = tamanos_lote$planos,
      forma = forma_mediana_estimacion, tipos = esquema$tipos,
      prototipo = prototipo, tabla_sql = tabla_sql
    )
  metricas_ejecucion <- metricas
  # La expresion con que se lee cada columna: ver `.lectura_convertida_dbi()`.
  # `esquema$campos_sql` sigue siendo el identificador de la columna, que es lo
  # que nombra los agregados sobre la tabla de lectura.
  lectura <- .lectura_convertida_dbi(
    conexion, campos, esquema$campos_sql, esquema$tipos_motor,
    tipos = esquema$tipos, presupuesto = presupuesto
  )
  tipos_declarados <- .tipos_declarados_con_motor_dbi(
    esquema$tipos, esquema$tipos_motor
  )
  nombres_tipos <- campos
  if (!is.null(tipos_declarados)) names(tipos_declarados) <- nombres_tipos
  if (!is.null(esquema$tipos_motor)) names(esquema$tipos_motor) <- nombres_tipos
  proyeccion_binaria <- .proyeccion_binaria_muestra_dbi(
    conexion, campos, lectura$proyeccion_sql,
    tipos_declarados = tipos_declarados,
    tipos_motor = esquema$tipos_motor,
    version_sqlserver = .version_servidor_sqlserver_dbi(conexion)
  )
  list(
    universo = universo, muestra_motor = muestra_motor,
    estrategia_mediana = estrategia_mediana,
    metricas = metricas_solicitadas, metricas_ejecucion = metricas_ejecucion,
    muestra = muestra,
    bloque_muestra = bloque_muestra,
    max_consultas = max_consultas, presupuesto = presupuesto,
    instrumentar = isTRUE(instrumentar),
    tamano_lote = tamanos_lote$planos,
    tamano_lote_planos = tamanos_lote$planos,
    tamano_lote_distintos = tamanos_lote$distintos,
    tabla_sql = tabla_sql, tabla_nombre_sql = tabla_nombre_sql,
    enmascaradas = enmascaradas, mascaras = mascaras,
    campos = campos, campos_sql = lectura$campos_sql,
    campos_sql_proyeccion = lectura$proyeccion_sql,
    campos_sql_bloques = proyeccion_binaria$campos_sql,
    columnas_binarias_bloques = proyeccion_binaria$columnas_binarias,
    columnas_binarias_bloques_prefijo =
      proyeccion_binaria$columnas_binarias_prefijo,
    lectura_convertida = lectura$convertidas,
    columnas_float8_numeric = if (inherits(conexion, "PqConnection") &&
        !is.null(esquema$tipos_motor) &&
        length(esquema$tipos_motor) == length(campos)) {
      as.character(campos[
        .minusculas_ascii(as.character(esquema$tipos_motor)) %in%
          c("float8", "double precision")
      ])
    } else character(),
    infinitos_como_numeric = is.data.frame(lectura$convertidas) &&
      nrow(lectura$convertidas) > 0L && any(
        .minusculas_ascii(as.character(lectura$convertidas$tipo_motor)) %in%
          c("float8", "double precision")
      ),
    prototipo = prototipo,
    tipos = tipos_declarados,
    esquema = esquema,
    es_numerico = es_numerico, muestreo = muestreo,
    aproximaciones = aproximaciones,
    aproximaciones_resolucion = aproximaciones_resolucion,
    moda_guardian = moda_guardian,
    moda_guardian_resolucion = moda_guardian_resolucion,
    mediana_consolidada = mediana_consolidada,
    mediana_consolidada_resolucion = mediana_consolidada_resolucion,
    mediana_escalar = mediana_escalar,
    mediana_escalar_resolucion = mediana_escalar_resolucion,
    mediana_cte_ventana = mediana_cte_ventana,
    mediana_cte_ventana_resolucion = mediana_cte_ventana_resolucion,
    mediana_cte_ventana_motivo = mediana_cte_ventana_motivo,
    politica_costo = politica_costo,
    estrategia_distintos = estrategia_distintos,
    fuentes_cardinalidad_costo = fuentes_cardinalidad_costo,
    catalogo_cardinalidad = catalogo_cardinalidad,
    columnas_distintos_ejecucion = columnas_distintos_ejecucion,
    estimacion_derrame = presupuesto$estimacion_derrame,
    estimacion_derrame_moda = presupuesto$estimacion_derrame_moda,
    estimacion_derrame_mediana = presupuesto$estimacion_derrame_mediana,
    n_total = n_total, conteo = conteo, sql_conteo = sql_conteo,
    conteo_fusionable = hay_agregados_fusionables && !(
      identical(universo, "muestra_motor") && !is.null(muestreo) &&
        !is.null(muestreo$candidato) &&
        identical(muestreo$candidato$tipo, "tablesample")
    ),
    orden_sql = orden_sql,
    orden_muestra = orden_muestra, dialecto = resolucion$dialecto,
    max_bytes_procesamiento = max_bytes_procesamiento,
    max_bytes_materializacion = max_bytes_materializacion,
    resolucion = resolucion, campos_declarados = campos_declarados,
    lista_campos = lista_campos, tipo_objeto = lista_campos$tipo_objeto
  )
}

#' Perfilar una muestra leída mediante DBI
#'
#' Calcula en SQL un resumen sobre la tabla completa o sobre una relación
#' muestreada por el motor, según `universo`. Con `universo = "muestra_motor"`
#' y `bloque_muestra = "con_muestra"`, ejecuta una sola selección y la
#' materializa en un spool externo de la sesión cliente; el resumen y
#' [perfilar()] leen esa misma materialización. Con
#' `bloque_muestra = "solo_agregados"`, el resumen usa la relación muestreada
#' sin seleccionar filas para el cliente.
#' `bloque_muestra = "solo_agregados"` sigue omitiendo el objeto
#' `perfil_muestra`, pero no vuelve a seleccionar filas.
#'
#' La función no escribe en la conexión ni crea objetos temporales del motor;
#' `muestra_motor` puede crear un spool externo temporal de sesión, con bytes,
#' checksum, presupuesto y estado. `DBI` es una
#' dependencia opcional. Cada agregado no disponible queda en `NA` y su
#' consulta, estado y motivo se conservan en `resumen_tabla$sql`.
#' Las expresiones se ejecutan como capacidades a comprobar, no como un
#' dialecto SQL universal.
#'
#' En `muestra_motor`, `max_celdas_muestra` y `max_bytes_muestra` se aplican
#' antes de armar la selección y se publican como filas pedidas y filas
#' efectivas. El spool estima bytes por fila desde el catálogo cuando el motor
#' lo permite; si la estimación no existe, comienza con un bloque pequeño y lo
#' adapta. La materialización publica la fuente, la estimación, el recorte y el
#' presupuesto efectivo en `meta$materializacion`. Un recorte, un muestreo corto
#' de `TABLESAMPLE` o una falla de una consulta emiten la clase
#' `lupa_aviso_muestra_motor`, que se puede capturar o silenciar por clase.
#' Las columnas binarias compatibles se leen como largo y resumen MD5, por lo
#' que se conservan faltantes, duplicados y largos sin traer el contenido a R.
#' En SQL Server anterior a 13, o si la versión no se pudo determinar, el MD5
#' usa un prefijo de 8000 bytes y conserva el largo completo; esta decisión
#' queda en la metadata de `perfil_muestra` y también convierte `image` a
#' `varbinary(max)` antes de resumirla.
#' Si `TABLESAMPLE` entrega menos de la mitad de las filas efectivas, se hace
#' un solo reintento con una fracción mayor. PostgreSQL prefiere
#' `TABLESAMPLE BERNOULLI`; en los demás motores se conserva el método por
#' bloques y, solo si no existe, se considera el orden pseudoaleatorio sujeto a
#' la misma guarda de costo. La metadata publica ambos métodos, la cantidad de
#' reintentos, la guarda y cuál spool quedó elegido: una falla o una muestra más
#' corta en el segundo intento conserva la primera muestra válida.
#'
#' Las fallas de consultas solicitadas se conservan en
#' `resumen_tabla$meta$consultas$fallas`, con `etapa`, `consulta_id`,
#' `sqlstate`, `tipo` y `motivo`. Un `SQLSTATE` `57014` se publica como
#' `cancelada`; los rechazos tienen `tipo = "rechazada"`. Las etapas internas
#' `clave_primaria`, `proteccion_coleccion`, `sonda_collation_dbi`,
#' `sonda_fuente_bloques`, `sonda_desvio`, `estimacion_derrame`, `explain_moda`,
#' `sonda_muestreo`, `sonda_mediana_escalar`, `sonda_mediana_cte_ventana`,
#' `sonda_mediana_cte_ventana_control_negativo`, `sonda_moda_guardian`,
#' `sonda_mediana_consolidada`, `sonda_aproximacion`, `sonda_dialecto`,
#' `consulta`, `cardinalidad_catalogo`, `tipos_guardados`, `sonda_infinitos`,
#' `sonda_magnitud`, `esquema`, `sonda_lectura_muestra`, `sonda_bytes_muestra`,
#' `proteccion_fuera_de_muestra`, `porton_tabla` y
#' `catalogo_bytes_muestra` se conservan aparte en
#' `resumen_tabla$meta$consultas$sondas_fallidas` y no disparan el aviso de
#' degradacion. El aviso que informa que la muestra no esta disponible conserva
#' ademas la clase historica `lupa_muestra_dbi_no_disponible`.
#'
#' Cuando el catálogo estima al menos `1e8` filas y se pidió
#' `universo = "tabla_completa"`, la función avisa antes de los agregados con
#' la clase `lupa_aviso_costo_dbi` y sugiere usar
#' `universo = "muestra_motor"`. El umbral se llama
#' `.UMBRAL_FILAS_AVISO_AGREGADOS_DBI` y no afecta tablas menores ni la vía de
#' muestra. La consulta de ese aviso es interna y no consume el presupuesto de
#' `max_consultas`, para que el aviso no cambie qué métricas entran en la
#' corrida.
#'
#' @section Dos tablas se llaman cobertura:
#' El resultado trae dos, y cubren cosas distintas. `resumen_tabla$cobertura`
#' habla de **métricas SQL**: qué pidió esta función al motor y qué pasó, con
#' `bloque`, `elemento`, `estado` —`no_disponible`, `no_solicitado`,
#' `degradado`, `presupuesto_agotado`, `alcance_distinto`— y la consulta en
#' `sql`. `alcance_distinto` declara que dos valores exactos incoherentes
#' salieron de grupos de consistencia distintos: es evidencia de que la tabla
#' cambio durante la corrida, no una acusacion contra el motor.
#' `perfil_muestra$cobertura_diagnosticos` habla de **diagnósticos**: qué
#' comprobación no se corrió sobre la muestra y por qué, con `diagnostico`,
#' `columna`, `motivo` y `como_resolverlo`, el mismo esquema que devuelve
#' [perfilar()]. Un motor que rechaza una columna aparece en la primera; una
#' prueba estadística que no corresponde a esa columna, en la segunda. Comparten
#' la palabra y no el vocabulario, así que conviene mirar cuál se está leyendo.
#' Si una columna declarada como entero de 64 bits o mas ancho, o como decimal
#' -`numeric`, `decimal`, con o sin precision-, llega como doble
#' y contiene un valor con valor absoluto de al menos 2^53, `resumen_tabla`
#' deja en `no_disponible` las métricas de magnitud que dependen de un valor que
#' el doble no representa: `minimo`, `maximo`, `media`, `n_ceros`, `n_negativos`
#' y `desvio`, por la columna. La `mediana` depende sólo de sus centrales y se
#' decide por su valor: con una cantidad impar de valores es la central, y se
#' publica si queda por debajo de 2^53 —una central de al menos 2^53 daría un
#' doble de al menos 2^53—; con una cantidad par promedia dos centrales y su
#' valor no dice si alguna pasó de 2^53: se publica sólo si las dos quedan
#' entre -2^52 y 2^52, lo que en la tabla completa cuenta una consulta más
#' (cuántos valores llegan a 2^52 y cuántos bajan de -2^52) y en la muestra del
#' motor no se puede saber. La misma regla
#' corre cuando la consulta de básicos desborda (un `HUGEINT` cerca de su tope en
#' DuckDB): la consulta se repite sin el promedio, la media queda `no_disponible`
#' con su motivo, y el mínimo, el máximo y los conteos se juzgan como en
#' cualquier otra columna. En una columna que no pasa de 2^53, la mediana de una cantidad par
#' tampoco se publica en PostgreSQL si sus extremos distan más de 2^53:
#' `PERCENTILE_CONT` interpola `bajo + (alto - bajo) * 0.5` en doble y esa resta
#' redondea. La de un `numeric` no pasa por ahí: es la suma de sus centrales.
#' Lo que el motor cuenta con exactitud -`n_distintos`, la moda- se
#' sigue publicando. La moda de un entero ancho que llego como `numeric` se pide al
#' motor como texto exacto cuando la magnitud cruza 2^53; un `BIGINT` con
#' valores chicos conserva la moda numerica de siempre. Lo decide el valor: un
#' decimal desde 2^53 ya no cabe en un doble
#' -90071992547409001 y 90071992547409002 son el mismo-, y el tipo solo dice
#' que viene de un decimal: RPostgres lo publica como `numeric` sin precision y
#' odbc con su codigo ODBC (2 y 3), asi que una regla que esperara
#' `numeric(20,0)` no se ejerceria. Para la muestra, la
#' seleccion SQL trae esas columnas como texto y, si `bit64` esta instalado,
#' las convierte a `integer64` antes de perfilar: `n_distintos`, la moda y los
#' diagnosticos por identidad conservan los valores exactos. Los estadisticos
#' de magnitud por encima de 2^53 siguen usando
#' `estado_resumen_cuantitativo = "omitidos_precision"`, como en memoria, y la
#' mediana se publica cuando sus una o dos centrales caben en un doble, como en
#' [perfilar()]. Un decimal entero que la muestra convirtió a `integer64` se
#' resume como tal. En SQL Server el texto de un decimal de 38 cifras se pide
#' como `VARCHAR(48)` —`VARCHAR` a secas es `VARCHAR(30)`, y la lectura de la
#' muestra entera abortaba— y el de `money` con sus cuatro decimales. Si
#' falta `bit64`, la columna queda como texto y `cobertura_diagnosticos` explica
#' la limitacion y recomienda instalarlo o pedir `integer64` al conectar. Las
#' columnas declaradas como `double`, `real` o `float` no entran en esta guarda.
#' Con `bloque_filas` rige la misma regla, sobre los valores que el
#' controlador entrega como `integer64` —un `BIGINT` o `bigserial` de
#' PostgreSQL, un `INTEGER` de SQLite que no entra en 32 bits—: por debajo de
#' 2^53 se opera con el valor exacto, y desde 2^53 las seis que dependen de toda
#' la columna quedan `no_disponible` con su motivo y la mediana se decide por su
#' valor, como en el resumen SQL. Un bloque que el controlador entrega como `integer`
#' y otro como `integer64` —RSQLite elige la clase por los valores de cada
#' bloque— se unen como `integer64` antes de contar distintos, moda y mediana. Un decimal o un entero ancho que llega como
#' doble desde 2^53 deja ademas `n_distintos` y `tasa_distintos` en
#' `no_disponible`: con bloques se contarian en R sobre esos dobles, que no
#' distinguen los valores. La moda de un decimal, y la de un entero ancho
#' entregado como `numeric`, se le pide al motor como texto exacto en las tres
#' vias, en PostgreSQL, SQL Server, MySQL, MariaDB y DuckDB; si la via o el
#' adaptador no puede construir esa forma, queda `no_disponible` con su motivo.
#' Las cifras de `perfil_muestra` de esa
#' columna salen de los mismos dobles; sin bloques, la corroboracion avisa la
#' diferencia en `n_distintos` y la moda contra las del motor. Un decimal por
#' debajo de 2^53 con mas cifras de las que guarda un doble -`numeric(30,20)`-
#' no entra en esta guarda. Ninguna columna cambia la clase de un campo
#' de la tabla: `minimo`, `maximo`, `media`, `mediana` y `desvio` de
#' `resumen_tabla$columnas` son siempre dobles.
#' Cuando `incluir_valores = FALSE`, la promesa de privacidad alcanza las tres
#' vias de salida: resumen SQL, `perfil_muestra` y `bloque_filas`. Se omiten los
#' valores de celda -incluidos moda, extremos, medianas, centinelas y ejemplos
#' de patrones-, se limpian la cobertura y los motivos de las metricas que
#' publicarian un valor de celda (los de un estadistico como la media o el
#' desvio se conservan: no contienen valores), y no se conservan familias de
#' acumuladores ni una muestra cruda en el resultado. La limpieza recorre también
#' los atributos de cada hoja del resultado, incluidos los resúmenes de patrones.
#' Los conteos, proporciones y agregados que no son valores de celda pueden seguir
#' publicandose. La marca queda registrada como `meta$incluir_valores = FALSE` en
#' ambos resultados.
#' Si se omite el bloque con `bloque_muestra = "solo_agregados"`, la cobertura
#' usa el estado `no_solicitado`: no es un fallo ni se cuenta como una métrica
#' no disponible. En `muestra_motor`, la selección materializada se hace una
#' sola vez antes de las pasadas; el spool se relee y se verifica mediante su
#' trailer. Un trailer ausente publica
#' `spool_incompleto:trailer_ausente`; un trailer o checksum que no coincide
#' publica `spool_checksum_invalido`.
#' Si la lectura materializada falla, se cierran el resultado DBI y el archivo
#' del spool aun cuando el error deshaga una transacción; no queda una conexión
#' de archivo abierta para un finalizador posterior.
#'
#' @section Fallo parcial:
#' Ningún bloque descarta al otro. Si se pide la muestra pero el motor rechaza su
#' consulta, o si la muestra no se puede perfilar, el resultado sale igual con
#' `perfil_muestra = NULL` y una fila en `resumen_tabla$cobertura` que declara
#' el estado `no_disponible`, el motivo y cómo resolverlo. Si se pide sólo
#' agregados, `perfil_muestra = NULL` se acompaña de una fila `no_solicitado`:
#' no se intentó leer la muestra. Si el motor rechaza una columna, esa columna
#' queda con sus métricas en `no_disponible` y las demás se perfilan enteras.
#' Lo mismo con una columna cuyo nombre la sesión no puede escribir: odbc pasa
#' la consulta por la codificación nativa, y bajo el locale `C` —el de un
#' `Rscript` de cron en Linux— un nombre con tilde no se puede mandar; mandarlo
#' dejaría la conexión rota y la consulta siguiente haría caer a R. La consulta
#' no se envía: la columna queda en `no_disponible` con ese motivo, y una tabla
#' con un nombre así da `lupa_error_codificacion_dbi`. Para leerlas, correr la
#' sesión con un locale UTF-8 (`LC_ALL=C.UTF-8`). RPostgres, RSQLite y duckdb
#' reciben la consulta en UTF-8 y leen esos nombres en cualquier locale.
#' Una columna que la credencial no puede leer —un `GRANT SELECT` por columnas o
#' un `DENY SELECT` sobre una columna— se sabe antes de leer, por el catálogo del
#' motor: en PostgreSQL `pg_attribute` con `has_column_privilege()`, legibles
#' por cualquier rol (`dbListFields()` de RPostgres no lista esas columnas), y en
#' SQL Server `sys.columns` con `HAS_PERMS_BY_NAME()`. La columna aparece en
#' `resumen_tabla$columnas` con sus métricas en `no_disponible` y una fila de
#' cobertura con el motivo y el remedio, no se nombra en ninguna consulta, y las
#' demás se perfilan enteras. SQL Server rechaza además cualquier consulta sobre
#' la tabla, también `COUNT(*)`, cuando hay una columna sin permiso: la lectura
#' va sobre una tabla derivada con las columnas legibles, y el SQL publicado lo
#' muestra. Con `universo = "muestra_motor"` la columna se declara igual, en
#' `resumen_tabla$columnas` y en la cobertura; `TABLESAMPLE` no se puede
#' escribir sobre la tabla derivada, así que la muestra del motor usa otra forma
#' que el motor acepte o se degrada con su motivo (limitación conocida). Con odbc las consultas se ejecutan sin preparar
#' (`immediate = TRUE`, como el `dbGetQuery()` de odbc): preparada, una consulta
#' rechazada por un permiso de columna dejaría la conexión rota y la siguiente
#' haría caer a R. Lo que el catálogo no ve —un sinónimo, una tabla de otra
#' base, una tabla temporal— se intenta leer: el rechazo del motor se declara
#' y la conexión sigue.
#' Con enmascaramiento dinámico de SQL Server (`MASKED WITH`, 2016+) y una
#' credencial sin `UNMASK` sobre la columna o la base, el motor devuelve la
#' máscara y no el dato. La completitud de esa columna se publica —los no nulos
#' se cuentan con una expresión que el motor no enmascara—; distintos, moda,
#' extremos, media, mediana y desvío quedan `no_disponible` con el motivo, la
#' columna no entra en `perfil_muestra` (una fila `alcance_distinto` lo dice) y
#' `resumen_tabla$cobertura` la declara. Con `UNMASK` se perfila entera.
#' SQL Server tampoco admite `COUNT(DISTINCT)`, `GROUP BY`, `ORDER BY` ni
#' `MIN`/`MAX` sobre `text`, `ntext`, `image`, `xml` y `geography`. El catálogo
#' reconoce esos tipos antes de armar las consultas: `validos` se conserva con
#' la expresión de nulos, mientras `n_distintos` y `moda` quedan
#' `no_disponible` con su motivo y no se manda una sentencia que el motor
#' rechazaría. Si `orden_muestra` pide una de esas columnas, la llamada se
#' rechaza antes de enviar el orden. En una vista SQL Server,
#' `universo = "muestra_motor"` usa el límite pseudoaleatorio compatible en
#' vez de `TABLESAMPLE`, que sólo acepta tablas locales. Limitación: el
#' catálogo no resuelve el objeto al que apunta un sinónimo. Si apunta a una
#' vista, `muestra_motor` prueba `TABLESAMPLE`, el motor lo rechaza y la vía
#' pasa al límite pseudoaleatorio; si apunta a una tabla con `text`, `ntext`,
#' `image`, `xml` o `geography`, la vía pide los distintos y la moda de esas
#' columnas, el motor los rechaza y quedan sin medir. Con `XACT_ABORT ON` y una
#' transacción abierta, en los dos casos el motor deshace la transacción, y la
#' vía lo informa con `lupa_error_transaccion_dbi`.
#' Si la lectura de la muestra falla, la columna que la hace fallar se busca
#' por descarte leyendo las MISMAS filas que la muestra con menos columnas —un
#' fallo que está en una fila que no es la primera, como el `CAST` de un texto
#' sucio en una vista, también se encuentra—; la muestra sale con las demás y
#' una fila `alcance_distinto` nombra la culpable.
#' Si una vista falla en una fila durante `universo = "muestra_motor"` o
#' `bloque_filas`, la vía intenta el mismo resumen SQL sobre la tabla completa:
#' así conserva las métricas de las columnas sanas y declara la muestra o el
#' recorrido de bloques como `no_disponible`, en vez de convertir todas las
#' columnas en `NA`. Si el resumen completo tampoco puede ejecutarse sobre la
#' vista, sólo se conservan las métricas que el motor alcanzó a contestar y las
#' demás quedan `no_disponible`; la cobertura identifica la columna o la
#' consulta que impidió completar el resumen.
#' El nombre de la tabla se normaliza antes de la primera llamada a la conexión,
#' también la que comprueba que existe: un nombre marcado `latin1` —el que da
#' `read.csv(encoding = "latin1")`— se convierte a UTF-8 y se lee, y uno con
#' bytes que no son UTF-8 válido y no declaran su codificación —`read.csv()`
#' sin `fileEncoding` sobre un archivo latin1— no se adivina: con odbc da
#' `lupa_error_codificacion_dbi` antes de tocar la conexión, que así no queda
#' rota. Una columna de `orden_muestra` que la sesión no puede escribir da
#' también `lupa_error_codificacion_dbi`, con ese remedio: no la rechazó el
#' motor, no se le mandó.
#' Los **valores** de texto tienen el mismo origen. Bajo un locale que no es
#' UTF-8, FreeTDS entrega las columnas de texto no Unicode (`varchar`, `char`,
#' `text`) en latin1 y odbc las marca UTF-8 sin convertirlas; las `nvarchar`
#' llegan en UTF-8. Un valor así se lee como latin1 —lo que es—, y no como texto
#' UTF-8 roto: no se publica el hallazgo de bytes que no forman UTF-8 válido, que
#' sería del controlador y no del dato, y los valores entran en los análisis de
#' texto y en las comparaciones de [relaciones_coleccion()]. Lo que no se puede
#' recuperar es un carácter que no está en latin1 —el signo del euro—: el
#' controlador lo entrega como `?`. Por eso cada columna de texto no Unicode
#' leída bajo una sesión así queda en `resumen_tabla$cobertura` con estado
#' `degradado`, el motivo y el remedio —correr con un locale UTF-8—, salvo que
#' el controlador haya entregado en ella texto UTF-8 no ASCII (está configurado
#' en UTF-8).
#' Bajo una sesión UTF-8, la columna que el controlador entregue en latin1 —un
#' `ClientCharset` configurado así— se lee igual y se declara igual.
#' Los `stop()` de esta vía llevan clase de condición propia —todas heredan de
#' `lupa_error_dbi`— para que se puedan rescatar con `tryCatch()`:
#' `lupa_error_conexion_dbi`, `lupa_error_tabla_dbi`, `lupa_error_campos_dbi`,
#' `lupa_error_conteo_dbi`, `lupa_error_esquema_dbi`,
#' `lupa_error_codificacion_dbi`, `lupa_error_argumento_dbi`,
#' `lupa_error_transaccion_dbi` y `lupa_error_integer64`. La última sale cuando
#' la lectura por bloques recibe una columna `integer64` y `bit64` no está
#' instalado: sin él R iguala entre sí todos los valores negativos. Sin bloques,
#' los agregados que calcula el motor se devuelven y la muestra no, con un aviso
#' que dice por qué. Alcanza `bit64` 4.0.5 o posterior.
#'
#' @section Dentro de una transacción:
#' La vía se puede correr dentro de una transacción abierta por el usuario —es
#' lo que recomienda el motivo de `consistencia` para una lectura consistente—.
#' En PostgreSQL un error cualquiera aborta la transacción, y la vía manda
#' consultas que pueden fallar a propósito —las
#' sondas de dialecto— o por el dato —una métrica que el motor no calcula sobre
#' un tipo, una vista rota—: con una transacción abierta, cada sentencia de la
#' vía va entre un `SAVEPOINT` propio y su `RELEASE`, y si falla se vuelve con
#' `ROLLBACK TO SAVEPOINT`. La transacción se reconoce por RPostgres
#' (`dbBegin()`, `dbWithTransaction()`) o por el motor, para un `BEGIN` mandado
#' a mano. El paquete nunca manda `BEGIN`, `COMMIT` ni `ROLLBACK`; fuera de una
#' transacción no agrega ninguna sentencia de ese tipo. Lo mismo vale para
#' [plan_perfilado_dbi()], [perfilar_coleccion()] y [relaciones_coleccion()].
#' SQL Server puede deshacer la transacción completa ante un error de ejecución,
#' incluso con `XACT_ABORT` apagado: antes y después de cada envío y lectura la
#' vía mide `@@TRANCOUNT` y `XACT_STATE()`. Si cambian, levanta
#' `lupa_error_transaccion_dbi` y no continúa leyendo en autocommit como si la
#' instantánea siguiera viva. Si la sesión tiene `IMPLICIT_TRANSACTIONS ON`, el
#' motivo lo declara como una transacción implícita de la sesión, no como una
#' transacción abierta por el usuario. `SAVE TRANSACTION` no evita los errores
#' del motor que deshacen la transacción completa. La etapa publicada en el
#' motivo es la que detectó el cambio: `dbSendQuery`, `dbFetch` o
#' `dbClearResult`. Las sondas de sintaxis de otros motores no se ejecutan
#' cuando el controlador ya fue reconocido; así se evita que `XACT_ABORT ON`
#' aborte la transacción por una sentencia que no corresponde a ese motor.
#' Un desbordamiento de datos que el motor no puede aislar puede abortarla
#' igualmente y queda documentado en `lupa_error_transaccion_dbi`. MySQL,
#' MariaDB y SQLite no abortan la transacción por el error de una consulta.
#' duckdb sí la aborta por un error al
#' preparar, como el de una sonda de dialecto— y no tiene `SAVEPOINT`: dentro
#' de una transacción de duckdb, un objeto que falla al leerse —una vista que
#' convierte un texto sucio— la deja abortada, y hay que cerrarla con
#' `ROLLBACK`.
#'
#' @section Muestra y aproximaciones:
#' `universo = "muestra_motor"` sondea las formas declaradas por el adaptador y
#' usa `TABLESAMPLE` cuando el motor lo acepta, o una función pseudoaleatoria con
#' el límite del dialecto. Si ninguna forma es compatible, las métricas SQL
#' quedan en `no_disponible`: no se sustituyen por resultados de la tabla completa.
#' La estimación de bytes de SQL Server usa `sys.partitions` y
#' `sys.allocation_units`, que no requieren `VIEW DATABASE STATE` para una
#' tabla accesible al usuario. Si el catálogo no se puede leer, esa consulta interna
#' queda en la metadata sin convertirse en una falla de consulta solicitada.
#' Cada registro publica `alcance`, `universo`, `tamano_muestra`, `fraccion`,
#' `metodo` y `error_esperado`. En `resumen_tabla$meta$muestreo`,
#' `tamano_muestra` conserva el nombre historico y declara el tamano efectivo
#' solicitado a la consulta; `filas_solicitadas` y `filas_pedidas` declaran el
#' pedido original y `filas_obtenidas` las filas que devolvio el spool. La
#' materializacion publica `muestra_id`, `snapshot_id`, `orden_id`, `n_filas`,
#' `bytes`, `checksum`, backend, version y presupuesto en
#' `meta$materializacion`; las pasadas publican el mismo `muestra_id`. También
#' publica la estimación de bytes por fila del catálogo, los bytes medidos,
#' la fracción real materializada y `tope_que_mando` cuando un tope recortó la
#' copia. La estimación sólo fija el primer bloque: el tamaño medido gobierna
#' los siguientes y la parte que entra se conserva cuando el presupuesto se
#' agota.
#' El contrato de `perfil_muestra` es campo por campo: `meta$filas_analizadas`
#' es la cantidad efectivamente entregada a los diagnósticos; `hallazgos` solo
#' contiene familias disponibles; y `cobertura_diagnosticos` tiene una fila por
#' familia no evaluada. `meta$origen_dbi$muestreo` conserva filas solicitadas,
#' entregadas, reproducibilidad, `muestra_id`, `snapshot_id` y checksum. El
#' método de impresión remite a esa cobertura cuando el campo no está
#' disponible; no reemplaza la ausencia con `NULL` silencioso. Cuando el orden
#' de la muestra del motor no se demostró estable, cada traza de `hallazgos` se
#' publica `no_disponible` con `alcance = "orden_muestra_no_estable"`, sin
#' índices ni claves y con su total; los patrones raros conservan su cantidad y
#' retiran sus nombres.
#' Bajo `bloque_filas`, `perfil_muestra` sigue siendo la muestra diagnóstica
#' acotada por `muestra`, `max_celdas_muestra` y `max_bytes_muestra`; no es la
#' cobertura completa. Por eso `perfil_muestra$general$filas` es el tamaño de
#' esa muestra y la cobertura se lee en `meta$bloques$filas_vistas`.
#' En `muestra_motor`, todas las metricas SQL salvo `n` describen la relacion
#' muestreada; `n` es el total de la tabla completa y esta marcado con
#' `alcance = "tabla_completa"`, `metodo = "conteo_universo"` y
#' `error_esperado = "no_aplica"`. Los conteos `n_validos`, `n_faltantes`,
#' `prop_faltantes`, `n_distintos`, `tasa_distintos`, `n_ceros`,
#' `n_negativos` y `frecuencia_moda` son observaciones de esa muestra, no
#' extrapolaciones al universo. Sus motivos declaran la escala local y el
#' denominador `n_total_consulta` cuando corresponde.
#' `TABLESAMPLE SYSTEM` es la fuente preferida cuando el adaptador la declara y
#' la sonda la acepta; publica `metodo_muestreo = "tablesample_system"`,
#' `sesgo_muestreo = "por_bloques"` y el motivo estable
#' `sesgo_muestreo:tablesample_system_por_bloques`. Si se usa el fallback
#' `random_limit` con `NEWID()`, la metadata publica
#' `metodo_muestreo = "random_limit"`, `funcion_muestreo = "newid"`,
#' `sesgo_muestreo = "por_fila"` y
#' `sesgo_muestreo:random_limit_newid_por_fila`. Ese fallback se acepta solo
#' si la politica de costo conserva `n_total`, la proyeccion, la tasa y sus
#' tres umbrales; si no, la mediana queda `no_disponible` con
#' `capacidad_no_aceptada:newid_costo_excede_presupuesto` aunque se silencien
#' los avisos.
#' Si `TABLESAMPLE` devuelve cero o menos de la mitad de las filas pedidas, se
#' intenta una vez con una forma de muestreo más amplia. Si el reintento logra
#' una muestra suficiente, se conservan en `meta$muestreo` ambos métodos y no
#' se emite un aviso por la escasez transitoria. Si la muestra final sigue
#' corta, se publica el aviso y las métricas de alcance quedan con el estado
#' correspondiente. Un `random_limit` que devuelve cero conserva el motivo
#' `muestra_vacia:random_limit_sin_filas` (o el método efectivo equivalente).
#' Esto no permite concluir que la columna esté vacía, por lo que no se publica
#' cero ni se dispara la cascada `sin_valores`. Una muestra no vacía sin valores
#' válidos usa `muestra_inestable:sin_valores_validos`; una capacidad no aceptada
#' usa `capacidad_no_aceptada:...`. `n` conserva el conteo de la tabla completa.
#' Hay dos excepciones, en las que lo perfilado no es la muestra pedida: si la
#' materialización queda recortada por `max_bytes_materializacion`, o si no se
#' puede leer y lo que queda es el perfil aislado de las columnas legibles, `n`
#' es la cantidad de filas perfiladas, para que las demás cuentas se lean contra
#' ellas y no contra el total de la tabla.
#'
#' Con `bloque_muestra = "solo_agregados"` cada sentencia sobre la muestra del
#' motor sortea la suya. Lo que decide los agregados de una columna -la cuenta
#' de sus valores, su magnitud, la media y el desvío- sale del lote de
#' agregados, una sola sentencia: si la magnitud pide la media o el desvío
#' escalados (valores de más de `1e150` o de menos de `1e-150` en valor
#' absoluto), no se recalculan en otra consulta, que sortearía otra muestra, y
#' quedan `no_disponible` con su motivo. La moda, la mediana y los distintos se
#' calculan cada uno en su sentencia, sobre su propia muestra; las cotas de la
#' moda y de los distintos se comprueban dentro de esa sentencia (ver el
#' `consulta_id`). Con `"con_muestra"` todo sale de la única muestra
#' materializada en el spool.
#'
#' Un estado que afirma un valor (`calculado`, `estimado`, `observado_muestra`)
#' nunca se publica con el valor ausente. Si el valor falta, el registro dice
#' por qué: `sin_valores` cuando la columna no tiene valores no nulos en la
#' tabla completa (en la muestra, `no_disponible` con
#' `muestra_inestable:sin_valores_validos`); `no_aplica` para una métrica
#' numérica sobre una columna que no lo es, para el desvío con menos de dos
#' valores y para la moda cuando ningún valor de la tabla se repite;
#' `no_disponible` en cualquier otro caso, también la moda de una muestra sin
#' repetidos, porque la tabla puede tenerla.
#'
#' En una muestra, `error_esperado` vale `no_estimado` para metricas cuyo error
#' podria calcularse bajo un plan probabilistico pero no se calculo,
#' `no_estimable` para la moda, la mediana y la cardinalidad observada, que no
#' tienen una cota simple sin supuestos o un estimador declarado, y `no_aplica`
#' cuando no hubo muestreo efectivo. El `motivo` de cada registro explica la
#' distincion. `metodo`, `tamano_muestra` y `fraccion` conservan las condiciones
#' de la corrida; no se publica una cota numerica sin una formula justificada.
#' Si la materialización completa falla y sólo se puede construir un perfil
#' aislado de las columnas legibles, ese perfil queda como diagnóstico. Las
#' métricas SQL del resumen pasan a `no_disponible`, con `tamano_muestra` y
#' `fraccion` en `NA`, y la cobertura nombra que la muestra aislada no
#' representa la materialización solicitada.
#' Los distintos de una muestra se publican como cardinalidad de la muestra,
#' no como cardinalidad del universo. `estrategia_distintos` es explicita y
#' vale `"exacta"` por omision: calcula `COUNT(DISTINCT)` sobre las filas de la
#' corrida. `"aproximada_motor"` sondea una funcion nativa y, si no hay una
#' capacidad aceptada, deja la metrica `no_disponible`; nunca ejecuta el conteo
#' exacto como repliegue. `"catalogo"` lee `pg_stats.n_distinct` y publica
#' `estimado_catalogo` sólo cuando `universo = "tabla_completa"`. Con
#' `universo = "muestra_motor"` queda `no_disponible`, porque el catálogo
#' describe la relación entera y la corrida mide un subconjunto; no se inventa
#' una equivalencia entre universos.
#' `"omitida"` no emite la
#' consulta. Cada resultado y el atributo `meta$estrategia_distintos` separan
#' `estrategia_solicitada`, `estrategia_resuelta` y `estado`.
#'
#' Las comparaciones que tienen una cota dura usan solo valores del mismo grupo
#' de consistencia. El grupo queda probado por el
#' `consulta_id` que ya se registra en `resumen_tabla$sql`: dos metricas con el
#' mismo identificador salieron de la misma sentencia. La consulta exacta de
#' distintos trae el conteo de no nulos `AS n_validos_guard` junto a
#' `COUNT(DISTINCT columna)`. Si una capacidad aproximada sólo construye una
#' consulta completa y no puede traer ese guardian, la cota no se comprueba y
#' el motivo lo declara; no se atribuye un valor imposible al motor.
#' La consulta de la moda intenta traer `SUM(COUNT(*)) OVER () AS
#' n_validos_guard` junto a su frecuencia. La forma se sondea antes de usarla;
#' si el motor la rechaza, se conserva la consulta anterior y
#' `meta$moda_guardian` publica el repliegue. Cuando la sonda pasa, la cota
#' `frecuencia_moda <= n_validos` se comprueba dentro de la misma sentencia y
#' el motivo de la métrica lo declara.
#' `meta$snapshot` queda en `FALSE`, siguiendo la declaracion de colecciones: no
#' hubo lectura instantanea del motor. `snapshot_id` identifica positivamente la
#' materializacion cliente, pero solo se publica evidencia positiva de snapshot
#' transaccional cuando el adaptador la demuestra. La cobertura agrega una entrada concreta solo si
#' `n_validos` y `n_distintos` son exactos, incoherentes y provienen de grupos
#' distintos; su motivo conserva ambas sentencias.
#' La mediana muestral que no tiene una forma consolidada o escalar, y la de
#' cada columna que no puede usar la consolidada (un decimal, un `float8` de
#' PostgreSQL o una columna con extremos), usa una sola CTE con
#' `COUNT(*) OVER ()`,
#' `ROW_NUMBER() OVER` y el promedio de las posiciones centrales, elegidas sin
#' dividir; con extremos, el promedio no desborda y sigue en la misma
#' sentencia. La sonda barata repite esa construccion sobre
#' `SELECT 1.0 UNION ALL ... SELECT 4.0`, exige `2.5` y un control negativo que
#' falle; no se sondea la tabla de produccion. Si esa capacidad falla, la
#' mediana se publica como `no_disponible` con
#' `capacidad_no_aceptada:sonda_mediana_cte_ventana`, nunca como
#' `dos_consultas` bajo `muestra_motor`. Si la preparación no la probó —porque
#' hay mediana consolidada— y una columna decimal o un `float8` de PostgreSQL la
#' van a necesitar, [plan_perfilado_dbi()] cuenta esa prueba y su control
#' negativo entre los portones; la que deja la consolidada por sus extremos
#' depende de los datos y no se anticipa.
#'
#' Las cotas de error no documentadas de una aproximacion nativa quedan como
#' `"desconocido"`. Una aproximacion solo se consolida cuando entrega una
#' expresion que se puede incrustar en el `SELECT`; si solo construye una
#' consulta completa, se emite por separado. Una consulta no emitida o sin un
#' valor utilizable queda `no_disponible`.
#'
#' @section Motores medidos:
#' El camino principal es PostgreSQL por RPostgres, en la 9.3 y en la 16, y SQL
#' Server 2022 por odbc con el controlador FreeTDS, en sesiones UTF-8 y bajo el
#' locale `C` de un `Rscript` de cron. Los siete motores —PostgreSQL 9.3 y 16,
#' SQL Server 2022, MySQL y MariaDB (RMariaDB), SQLite (RSQLite) y duckdb— se
#' verifican contra el motor real con el guion `benchmark/verificar_motor.R`, y
#' SQLite y duckdb se ejercitan además en las pruebas del paquete. Con otro
#' motor, otro controlador u otra versión la función corre por la vía portable
#' (ver «Dialecto») y declara en la cobertura lo que no pudo medir, pero sus
#' cifras no están comprobadas contra ese motor. Las configuraciones avanzadas
#' —una transacción abierta por el usuario, permisos por columna,
#' enmascaramiento dinámico, `universo = "muestra_motor"`, `bloque_filas`—
#' tienen sus limitaciones conocidas en «Fallo parcial» y «Dentro de una
#' transacción».
#'
#' @section Dialecto:
#' Acotar filas no es SQL estándar. En vez de suponer `LIMIT`, la función
#' sondea el motor con una consulta de cero filas y elige la primera capacidad
#' que acepte: `LIMIT n [OFFSET k]`, `TOP (n)` y `OFFSET … FETCH NEXT`,
#' `FETCH FIRST … ROWS ONLY`, o `ROWNUM`. Si ninguna sirve queda la vía
#' portable, que acota en el cliente con `dbSendQuery()` y `dbFetch(n)`; en ese
#' caso la mediana exacta se declara no disponible en vez de traer media tabla
#' a memoria. El alias de subconsulta se escribe con `AS` o sin él según el
#' motor, y los alias de columna van comillados y se comparan sin distinguir
#' caja, porque hay motores que los pliegan a mayúsculas.
#' Para los motores del dialecto `limit`, la mediana exacta usa una sola
#' sentencia: el `COUNT` queda como subconsulta escalar de la consulta que
#' ordena y recorta. La forma se sondea antes de usarla; en SQLite y
#' PostgreSQL se usan `%` y `/` con division entera. Bajo
#' `muestra_motor`, los dialectos sin una forma escalar ni consolidada usan la
#' CTE de ventanas descrita arriba y no degradan a `dos_consultas`. En
#' `tabla_completa` se conserva el camino previo, incluido `dos_consultas` si
#' es el que resuelve ese dialecto; `PERCENTILE_CONT` no cambia.
#' `dos_consultas` necesita el conteo de valores no nulos para el salto: si
#' `metricas` no incluye `"validos"`, la mediana lo cuenta en una consulta
#' propia y sale igual que con todas las métricas.
#' La mediana consolidada tambien se sondea antes de usarla; en SQL Server
#' requiere nivel de compatibilidad >= 110. Se sondea; estos son los motivos
#' conocidos de que no se active: la funcion no esta disponible, el motor
#' rechaza la sonda o devuelve el percentil sin todas sus cifras. La prueba lee
#' una fila con un valor de más de 1e8 y otro de menos de 1e-10 y exige los dos
#' idénticos: MariaDB tipa `PERCENTILE_CONT` como `double(18,10)`, que satura
#' en 1e8 y redondea a diez decimales, y por eso usa la mediana por columna
#' como MySQL. En ese caso el mensaje del motor queda en
#' `meta$mediana_consolidada$motivo` —sin sus literales con la protección
#' activa, entero sin ella, como todo mensaje del motor: ver «Datos
#' personales»—, y se conserva la mediana por columna.
#' La mediana de un decimal no entra en la consolidada: en MySQL, MariaDB, SQL
#' Server, PostgreSQL y DuckDB se piden, en el tipo de la columna, la suma de
#' sus una o dos filas centrales y cuántas son, y R divide: es el doble más
#' cercano de la mediana exacta, por la tabla completa y por la muestra del
#' motor. Cuesta una consulta por columna decimal, que el plan cuenta.
#' Con `bloque_filas` y en el resumen de la muestra del motor con
#' `bloque_muestra = "con_muestra"` (el spool), la mediana de un decimal que el
#' controlador entrega como doble también es la del decimal: por bloques, con
#' una cantidad impar la central es un valor y su doble es el más cercano, y con
#' dos centrales que caen en el mismo doble la mediana cae en él; con dos
#' centrales distintas se le piden al motor como texto, con el mismo salto que
#' la vía de dos consultas —una consulta ordenada por columna—, y R las suma.
#' `money` de SQL Server se pide siempre, porque odbc no lo lee al doble más
#' cercano. El spool ya trae cada decimal como texto y la calcula de ahí.
#' `PERCENTILE_CONT` interpola en doble, y la de un decimal quedaba a un ulp
#' del doble más cercano (la de 0,10 y 0,20 daba 0,15000000000000002, el
#' promedio de los dobles); en DuckDB, además, interpola un `DECIMAL` en su
#' propia escala y trunca, y convierte a doble un decimal de más de 18 cifras
#' sin dar el más cercano: ahí la suma se lee por su texto. `AVG(x * 1.0)`
#' necesita una cifra de escala más que la columna y en la escala máxima del
#' motor —30 en MySQL, 38 en MariaDB— se recortaba (la mediana de 1e-30 y 2e-30
#' salía 2e-30). La
#' mediana consolidada de las demás columnas numéricas interpola en doble y
#' puede quedar a una unidad de la última cifra del doble más cercano.
#'
#' @section Lo que el motor guarda distinto que R:
#' El resumen SQL describe lo que el motor tiene delante, y en estos casos eso
#' no es lo mismo que la tabla en R:
#'
#' * **Fechas en SQLite.** SQLite no tiene tipo fecha: RSQLite guarda un `Date`
#'   como número de días desde 1970 y un `POSIXct` como segundos, y sin más
#'   información el motor los describe como números —`minimo = 17956`—. Con
#'   `DBI::dbConnect(RSQLite::SQLite(), ..., extended_types = TRUE)` la columna
#'   se declara temporal y `perfilar_dbi()` no le aplica agregados
#'   cuantitativos, y lo dice.
#' * **`NaN` en duckdb.** duckdb conserva `NaN` como un valor: lo cuenta como
#'   presente y distinto, y responde `MAX` y `AVG` con `NaN`. En R, `NaN` cuenta
#'   como ausente. Los conteos pueden diferir por eso, y una métrica que el motor
#'   respondió con `NaN` no se publica: queda `no_disponible` con su motivo.
#' * **Infinitos.** SQLite, PostgreSQL y duckdb admiten `Inf` y `-Inf` en una
#'   columna de punto flotante, y el motor los cuenta en `MIN`, `MAX`, `AVG` y
#'   el orden de la mediana. Los estadísticos de magnitud se calculan sólo con
#'   valores finitos, como en [perfilar()] y con `bloque_filas`: cuando el motor
#'   responde un infinito, `minimo`, `maximo`, `media`, `mediana`, `desvio`,
#'   `n_ceros` y `n_negativos` se vuelven a pedir sobre una subconsulta que deja
#'   afuera los infinitos, y su `sql` lo muestra. Donde la consulta no sabe
#'   escribir el infinito, o sobre una muestra del motor, esas métricas quedan
#'   `no_disponible` con ese motivo. Un infinito es un número: no se informa
#'   como un valor que no se pudo leer como número.
#' * **`money` y `real` en PostgreSQL.** RPostgres lee `0` en toda celda
#'   `money`, sin avisar, y un `real` por el texto con que lo escribe el
#'   servidor, mientras el motor opera sobre el binario guardado
#'   —21.299999237060547—. Las dos columnas se leen convertidas en el motor:
#'   `money` como `CAST(x AS NUMERIC)` y `real` por la forma decimal más corta
#'   que vuelve al valor guardado —`21.3`, la cifra que lee R desde PostgreSQL
#'   12—, que se calcula en el motor redondeando a 6, 7, 8 y 9 cifras. No se
#'   toma del texto de la sesión: antes de PostgreSQL 12, o con
#'   `extra_float_digits` de 0 o menos en cualquier versión, ese texto tiene
#'   seis cifras y 1234501 se escribe `1.2345e+06` —200 valores distintos se
#'   leerían como 21, con un mínimo que no está en la columna—. Así la lectura
#'   da el valor guardado en cualquier versión y con cualquier
#'   `extra_float_digits` desde -6, sin tocar el estado de la sesión; en un
#'   empate de la última cifra puede elegir la otra forma corta, que vuelve al
#'   mismo `real`. Por debajo de -6 el servidor escribe todo doble con menos de
#'   nueve cifras, y ninguna lectura —tampoco la de un `double precision`—
#'   llega entera a R. La conversión vale para toda lectura —la
#'   muestra, `bloque_filas`, `muestra_motor`— y el resumen SQL calcula sus
#'   agregados sobre esa misma lectura, así que las vías publican la misma
#'   cifra. Las columnas convertidas y su expresión quedan en
#'   `resumen_tabla$meta$lectura_convertida`. Se reconocen por el tipo que
#'   publica `DBI::dbColumnInfo()` de RPostgres; con otro controlador no se
#'   convierte nada.
#'   Para `double precision`, PostgreSQL 12 o posterior con
#'   `extra_float_digits >= 1` conserva la lectura nativa: el servidor ya
#'   escribe una representación redonda de 17 cifras y no se agrega una
#'   reconstrucción que pueda cambiar el valor ni encarecer cada consulta. En
#'   PostgreSQL 9.3, en versiones anteriores a la 12 o con
#'   `extra_float_digits <= 0`, la lectura usa `float8send()` para decodificar
#'   los ocho bytes IEEE-754 y formar el valor exacto como `NUMERIC`; esto
#'   conserva también los dobles vecinos bajo una potencia de dos, los valores
#'   desde `2^53` y los extremos finitos. `NaN` e infinitos se representan por
#'   sentinelas numéricos que RPostgres vuelve a leer como sus valores originales.
#'   La expresión de lectura se mantiene sin alias para poder entrar en una
#'   consulta derivada; sólo la lista de proyección le agrega el alias original.
#'   Esa misma distinción se usa en el resumen SQL, la muestra, los bloques, las
#'   expresiones anidadas y las relaciones de una colección.
#'   Los agregados de esa misma lectura excluyen `NaN` e infinitos con
#'   sentinelas de `NUMERIC`; la media se escala en `NUMERIC` para no desbordar
#'   ni perder subnormales por underflow. La lectura nativa de PostgreSQL 12+
#'   con 17 cifras no pasa por esa reconstrucción.
#'   En PostgreSQL 9.3 y en sesiones con pocas cifras la decodificación exacta
#'   es más costosa que la lectura nativa; se conserva ese costo para no
#'   publicar cifras falsas y se aplica sólo cuando la sesión no garantiza los
#'   17 dígitos.
#'   Cuando la media o el desvío de esa lectura vuelven por una sesión de
#'   PostgreSQL 9.3 o con `extra_float_digits <= 0`, el resultado se decodifica
#'   por sus ocho bytes antes de publicarse. Así no queda recortado a 15 cifras
#'   por el transporte; la aritmética del motor todavía puede diferir de R en
#'   unos ulps, y esa diferencia se conserva como tal en la corroboración.
#'
#'   **`datetimeoffset` en SQL Server.** FreeTDS puede entregar a `odbc` un
#'   `datetimeoffset` con desplazamiento distinto de `+00:00` ya convertido a
#'   UTC. Una vez perdido el desplazamiento, Lupa no puede reconstruirlo desde
#'   el valor recibido: la corroboración lo deja como divergencia de una fecha,
#'   no como diferencia de cotejamiento. Para conservar el desplazamiento hay
#'   que leer la columna como texto o normalizarla en la consulta de origen.
#' * **Extremos y equivalencia entre motores.** SQL Server puede desbordar al
#'   agregar un `float` que contiene `-DBL_MAX` o `+DBL_MAX`; en ese caso las
#'   métricas que desbordan quedan `no_disponible` con el mensaje del motor,
#'   aunque la muestra conserve el valor, y el desvío se recalcula escalado
#'   (ver «Magnitudes extremas»). El mismo `real` puede mostrar una
#'   última cifra distinta entre PostgreSQL y SQL Server porque RPostgres lee
#'   la forma decimal corta y FreeTDS/odbc entrega el `float32`; cada resumen
#'   es coherente con los valores que su controlador devolvió, pero la
#'   comparación entre motores puede declararlo `materialmente_distinto`.
#'   En un `real`, un centinela fraccionario se alinea a `float32`; si el valor
#'   declarado tiene más precisión que la representación binaria almacenada,
#'   no se considera el mismo centinela y no se cuentan faltantes disfrazados.
#'   La lista explícita de centinelas conserva además la reserva documentada de
#'   los valores por omisión: declarar un valor lo vuelve a contar incluso si
#'   aparece una sola vez.
#'   En PostgreSQL anterior a la 12, o con `extra_float_digits <= 0`, una
#'   combinación de `+DBL_MAX` o `-DBL_MAX` con infinitos se calcula sobre los
#'   finitos que sobreviven la limpieza. En PostgreSQL 12 o posterior con la
#'   sesión por omisión, esa misma combinación hace desbordar el motor y el
#'   mínimo, el máximo, la media y el desvío quedan `no_disponible`, con el
#'   error del motor como motivo: se declara, no se calcula. Si una columna que
#'   conserva ambos extremos finitos hace desbordar la suma de cuadrados, el
#'   desvío se recalcula escalado.
#' * **Magnitudes extremas.** Cuando el mínimo y el máximo ya medidos dejan el
#'   mayor valor absoluto fuera de `[1e-150, 1e150]` —donde los cuadrados
#'   desbordan o caen en subnormales y pierden cifras—, el desvío se le pide al
#'   motor sobre `x / 2^k`, centrado en la media de esos mismos valores, y se
#'   multiplica por `2^k`: escalar por una potencia de dos es exacto, y no
#'   cuesta una consulta para decidirlo. También se escala cuando el rango
#'   —el máximo menos el mínimo— es tan chico que sus cuadrados caerían en
#'   subnormales, y la magnitud se conoce aunque no se pidan los básicos ni se
#'   publiquen los valores. En MySQL, MariaDB y SQL Server la media de esas
#'   columnas sale igual, `AVG(x / 2^k) * 2^k`, porque la suma de `AVG()`
#'   desborda; la mediana de dos centrales enormes se promedia como
#'   `a / 2 + b / 2`; y por encima de `1e65` el centro va como doble, porque un
#'   `DECIMAL` tiene 65 cifras. Una columna constante da `0`. Si el motor no
#'   puede, la métrica queda `no_disponible` con su falla en
#'   `meta$consultas$fallas` y el aviso: no se publica `Inf` ni un `0` sobre
#'   valores distintos. `perfilar()` y `perfilar_dbi(..., bloque_filas = n)`
#'   suman los cuadrados sin error en una unidad que es potencia de dos —la que
#'   deja el mayor valor en 2^400— y que sube cuando llega un bloque que no
#'   cubre: el desvío es el doble más cercano también en esas magnitudes. Las columnas de magnitud común no cambian de consulta ni de cifra.
#' * **La media en coma flotante.** Cada lado suma a su modo; sobre una columna
#'   que mezcla magnitudes muy distintas —`1e20` junto a `1`— las medias pueden
#'   diferir entre motores y con la de R. La media y el desvío de R
#'   —[perfilar()], `perfil_muestra` y `bloque_filas`— son los dobles más
#'   cercanos de la media y el desvío exactos de los dobles que leyó. La media
#'   y el desvío de un decimal que el controlador entrega como doble son los
#'   del decimal, los dobles más cercanos de los exactos, por la tabla
#'   completa, por `bloque_filas` y por la muestra del motor, con
#'   `bloque_muestra = "con_muestra"` y con `"solo_agregados"`. El motor suma en
#'   el tipo de la columna, y devuelve como texto, la columna y los cuadrados de
#'   sus diferencias con la media escrita en su escala —o de los valores, donde
#'   no hay media o las diferencias pasan de 38 cifras—, con expresiones
#'   elegidas para que no desborden ni redondeen con las cifras del tipo, las de
#'   los extremos y las filas: en SQL Server y duckdb la parte entera y la
#'   fracción por separado, porque la suma de un `decimal(38,30)` desborda; en
#'   duckdb el cuadrado con un factor de 19 cifras, que lo lleva a 128 bits —el
#'   de dos `DECIMAL(15,0)` desbordaba en 64—; y donde nada de eso entra, en
#'   trozos de nueve cifras. R divide y saca la raíz con aritmética entera, sin
#'   cancelación. La muestra leída en R hace lo mismo con el texto de cada
#'   valor. Por la tabla completa y bajo la muestra del motor las sumas van en
#'   la misma consulta que los demás agregados, sin consultas de más y, bajo la
#'   muestra, sobre las mismas filas; por bloques, en lotes de hasta
#'   `tamano_lote_planos` columnas, con las expresiones que acepta el motor
#'   (1.664 en PostgreSQL). Un lote que el motor rechaza se parte hasta aislar
#'   la columna, y las demás siguen. Entran con cualquier `metricas`, con
#'   `incluir_valores = FALSE` —la media es un literal que sale de los datos, y
#'   el SQL publicado la lleva tapada— y con valores de 2^53 o más; en
#'   PostgreSQL, `NaN` e `Infinity` quedan fuera, como en la media de la tabla
#'   completa. En duckdb la media y el desvío del motor de esas columnas se
#'   piden sobre el doble: `x * 1.0` de un `DECIMAL(38,30)` desborda. Las
#'   sumas reemplazan la media y el desvío del motor, que los
#'   calculaba en doble: en MySQL, MariaDB y SQL Server promediaba el doble de
#'   cada valor, y con valores que se cancelan la media salía lejos
#'   (`999999999999999.99`, `-999999999999999.98`, `0.01`, `0.02`, `0.03` y
#'   `-0.04` daban 0,00333 por 0,005); el desvío, y la media con escala 30,
#'   quedaban a un ulp. Si las sumas no llegan —el presupuesto, o el motor
#'   rechaza el lote aun con la columna sola—, por la tabla completa la del
#'   motor queda sólo si su
#'   error cabe en una parte en mil millones (el desvío, con la guarda de los
#'   dobles; la media, si `n` redondeos del mayor valor no pasan de esa parte de
#'   la media), y si no queda `no_disponible` con el motivo; por bloques, la
#'   media y el desvío quedan `no_disponible`, como si la suma del motor no es
#'   la de lo que leyeron los bloques. Sin escala declarada —un decimal que el
#'   catálogo no describe— el desvío por bloques sale de los dobles, con su
#'   guarda; la de una tabla temporal la leen el catálogo de `tempdb` en SQL
#'   Server y `SHOW COLUMNS` en MySQL y MariaDB. La media y el desvío de una columna de coma flotante
#'   o entera que calcula el motor salen de su aritmética y no son, en general,
#'   el doble más cercano del
#'   exacto: medido sobre columnas de cuatro a nueve valores en los siete
#'   motores, por la tabla completa, la media quedó a uno o dos ulps en hasta 19
#'   de 112 columnas (SQL Server) y el desvío a un ulp en 6 a 11 de cada 21 a
#'   112; con más filas la diferencia puede crecer, y con valores que se
#'   cancelan, más: `1e20`, `1`, `-1e20` y `2` dan 0,5 por 0,75 en MySQL,
#'   MariaDB, SQL Server y duckdb. La corroboración cruzada la
#'   tolera hasta `1e-10` relativa y la declara cuando pasa de ahí. La media y
#'   el desvío se le piden al motor como doble donde su aritmética decimal los
#'   recortaría: en SQL Server `AVG(CAST(x AS FLOAT))`, porque `AVG` de un
#'   `numeric` devuelve seis decimales, y en PostgreSQL
#'   `STDDEV_SAMP(CAST(x AS DOUBLE PRECISION))`, porque sobre magnitudes
#'   grandes el desvío de un `numeric` sale con cuatro; en MySQL y MariaDB
#'   `AVG(x * 1e0)`, porque `AVG` de un `DECIMAL` devuelve cinco decimales. En
#'   los demás motores, `x * 1.0`.
#' * **El desvío de una sola pasada.** `STDEV` de SQL Server —y, con menos
#'   pérdida, el desvío nativo de SQLite, duckdb, MariaDB y MySQL— acumula en
#'   una sola pasada, y cuando la media es muy grande frente al ancho de la
#'   columna pierde las cifras del desvío: sobre marcas de tiempo en
#'   milisegundos de una ventana de un segundo, SQL Server responde `0`. El
#'   desvío no cambia si a cada valor se le resta una constante, así que se le
#'   pide al motor sobre los valores centrados en la media ya calculada: siempre
#'   en la consulta por columna, y en la consulta compartida —donde la media sale
#'   de la misma sentencia— se vuelve a pedir centrado cuando la media supera
#'   diez veces el desvío, o cuando respondió `0` sobre una columna con valores
#'   distintos, con una consulta más que el plan no anticipa porque
#'   depende de los datos. Su fila de `sql` lo dice. La resta se hace en un tipo
#'   que no pierde cifras: en SQL Server y duckdb una columna `real` (`FLOAT` en
#'   duckdb) restaría en 24 bits —en T-SQL `real - decimal` es `real`— y el
#'   desvío centrado se apartaría del de los valores guardados, así que se
#'   convierte a doble antes de restar; en SQL Server el centro de una
#'   columna de coma flotante va como literal `float`, que no tiene el tope de 38
#'   cifras de un decimal. Una columna decimal o entera resta en su tipo, que es
#'   exacto; en SQL Server, si la resta pasa de 38 cifras el motor recorta la
#'   escala y redondea, y un empate se redondearía hacia lados distintos según
#'   el signo, así que el centro de un decimal nunca termina en 5. Con
#'   `bloque_filas` los momentos se acumulan centrados, sobre los dobles que
#'   entrega el controlador. El desvío de un decimal sale de las sumas exactas
#'   del motor (ver «La media en coma flotante»): la resta con la media escrita
#'   en la escala de la columna es exacta (medido en SQL Server, con
#'   compatibilidad 160 y 100, y en MySQL hasta `decimal(38,30)` y
#'   `DECIMAL(65,30)`). Sin escala declarada en SQL Server, MySQL y MariaDB, el
#'   de los dobles: si es tan grande frente a su desvío que el redondeo de cada
#'   valor a doble puede moverlo más de una parte en mil millones
#'   (`max |x| / desvio * 2^-53`) queda `no_disponible`, salvo que el tipo
#'   declare escala 0 —`numeric(18,0)`, `decimal(38,0)`— y los valores queden
#'   por debajo de 2^53: ahí los dobles son los valores. La escala la publican
#'   PostgreSQL, MySQL, MariaDB, DuckDB y el
#'   catálogo de SQL Server, también la de una tabla temporal. Bajo
#'   `muestra_motor`, la media y el desvío
#'   se piden en la misma consulta, sobre las mismas filas de una sola
#'   evaluación de la muestra: una relación derivada calcula la media de esas
#'   filas con una ventana (`AVG(x) OVER ()`) y el desvío se pide centrado en
#'   ella; esa misma evaluación da las filas obtenidas y decide el reintento. En
#'   SQLite, que suma los cuadrados en la consulta, se resta además
#'   `n * (media - centro)^2` (las dos pasadas corregidas), porque la media de
#'   la ventana no es la exacta. En SQL Server, MySQL, MariaDB y duckdb esa media y la resta son
#'   dobles; la media y el desvío de un decimal salen de sus sumas exactas,
#'   pedidas en la misma consulta (ver «La media en coma flotante»). Con
#'   `bloque_muestra = "con_muestra"` el
#'   resumen de un decimal sale del texto que la muestra trae de cada valor: el
#'   desvío es el doble más cercano del exacto, de las sumas sin redondeo de
#'   las diferencias con una de sus centrales y de sus cuadrados. El de
#'   `perfil_muestra` lo calcula [perfilar()] sobre lo leído, que
#'   para un decimal es el doble de su texto, y rige la regla de los dobles en
#'   todas las vías, también por la tabla completa, donde el de `resumen_tabla`
#'   es el exacto: no se publica (queda `NA`) y la columna queda en
#'   `perfil_muestra$meta$desvio_decimal_doble`. No
#'   se fija una semilla ni se toca el generador de números aleatorios de R.
#'   Como red en todas las
#'   vías, un desvío `0` sobre una columna con dos valores distintos —un mínimo
#'   menor que el máximo— es imposible y queda `no_disponible` con su motivo.
#' * **El cotejamiento.** El resumen SQL agrupa y ordena con el cotejamiento
#'   de la columna: sobre una `COLLATE NOCASE` de SQLite o una colación ICU no
#'   determinista de PostgreSQL, "Montevideo" y "montevideo" son un valor, y
#'   `n_distintos`, la moda y su frecuencia salen de esa cuenta. Con
#'   `bloque_filas` las filas se leen y se comparan en R, byte a byte, como el
#'   perfil de muestra. Cada `resumen_tabla` lo dice en
#'   `meta$criterio_comparacion` y `meta$criterio_moda`. La corroboración no
#'   llama divergencia a la diferencia que ese criterio explica —menos
#'   distintos en el resumen SQL, con la moda y la frecuencia que de ahí se
#'   siguen, o una moda empatada que cada lado desempata con su orden—: la deja
#'   en una fila `no_corroborada` con ese motivo.
#'   En SQL Server, el resumen SQL aplica la igualdad de texto que ignora los
#'   espacios finales; la vía por bloques compara en R los valores que recibió
#'   y, por eso, puede contar `"A1"` y `"A1 "` como distintos en
#'   `n_distintos`. Esa diferencia de alcance se publica como criterio de
#'   comparación y no se corrige inventando una equivalencia en R.
#' * **`datetimeoffset` en SQL Server.** FreeTDS/odbc puede entregar un
#'   `datetimeoffset` con desplazamiento distinto de `+00:00` como `POSIXct` en
#'   UTC y perder el desplazamiento original. La lectura no lo puede recuperar
#'   después; la corroboración no lo excusa como un cotejamiento y deja la
#'   divergencia publicada. Para conservar el instante y el desplazamiento,
#'   leer la columna como texto con el desplazamiento o normalizarla en el
#'   origen antes de perfilar.
#' * **Una columna que mezcla tipos de almacenamiento.** SQLite admite texto en
#'   una columna de afinidad numérica, y RSQLite la lee como número: convierte
#'   ese texto en `0` y lo avisa ("mixed type"). El resumen SQL ve los valores
#'   guardados —la moda puede ser el texto, y las métricas de magnitud quedan
#'   `no_disponible` porque el motor devolvió algo que no se lee como número—,
#'   y `perfil_muestra` ve lo que entregó el controlador: `minimo = 0`, una moda
#'   `0` que nadie escribió. `perfilar_dbi()` no relee la columna como texto:
#'   cuenta con `typeof()` los valores guardados como texto o blob y declara
#'   cada divergencia con esa causa medida en `resumen_tabla$cobertura`,
#'   y dice que las cifras de magnitud de `perfil_muestra` para esa columna no
#'   describen lo guardado. Para perfilar los valores guardados, leer la columna
#'   como texto (`CAST(columna AS TEXT)` en una vista) o limpiarla en el origen.
#'   **Limitación conocida:** un texto que R sí lee como número —`'0x10'`,
#'   hexadecimal, que `as.numeric()` lee 16— pasa la sonda de magnitud como un
#'   número, y el resumen SQL publica `maximo = 16` sobre una columna `NUMERIC`
#'   cuyo máximo numérico es otro; las divergencias de la corroboración son la
#'   señal.
#' * **Lo que la corroboración compara.** Sólo las métricas que los dos bloques
#'   calculan con la misma semántica. No compara lo que una declaración o una
#'   guarda hacen distinto a propósito, porque esa diferencia no es del motor,
#'   del controlador ni de un snapshot: la `media`, la `mediana` y el `desvio`
#'   de una columna de `columnas_codigo`, que no se calculan; `n_faltantes` de
#'   una columna de `columnas_opcionales` o de `aplicabilidad`, que la muestra
#'   cuenta sobre su universo —y todas las métricas de la columna con
#'   `aplicabilidad` si la muestra dejó afuera valores presentes—; las métricas
#'   de magnitud de una columna de la que la muestra excluyó los
#'   `sentinelas_numericos` declarados; las de un entero ancho desde
#'   2^53, que el resumen no publica; y el `desvio` de un decimal que la
#'   muestra leyó como doble y no publicó (causa `decimal_doble`, ver
#'   `perfil_muestra$meta$desvio_decimal_doble`). Tampoco lo que un bloque no calculó: una
#'   métrica que `resumen_tabla$sql` declara `no_disponible` —el motor rechazó
#'   la consulta sobre el tipo (`json`, `xml` o `point` de PostgreSQL; `text`,
#'   `ntext`, `image` o `geography` de SQL Server), una guarda la retuvo—, la
#'   moda que la muestra no pudo contar —una columna de blobs— y las métricas
#'   de una columna compuesta, que la muestra no analiza: su motivo ya está
#'   publicado, y una relectura daría lo mismo. Un `NaN` o un infinito sí se
#'   compara, y un valor guardado como texto en una columna numérica también:
#'   es la diferencia del motor que la corroboración existe para declarar. Lo que
#'   no se comparó queda en `resumen_tabla$meta$corroboracion_bloques$no_comparadas`,
#'   una fila por columna y métrica con su causa. La tolerancia está en
#'   `meta$corroboracion_bloques$tolerancia`: `1e-10` absoluta más `64` épsilon
#'   de máquina relativos para los valores leídos —`minimo`, `maximo`,
#'   `mediana`, la moda—, y `1e-10` relativa para `media` y `desvio`, que cada
#'   lado acumula con su algoritmo y en su orden. Medido en SQL Server, la
#'   diferencia de la acumulación llega a 2e-13; una divergencia real es de otro
#'   orden y sigue saliendo. Limitación conocida: la tolerancia absoluta se
#'   suma siempre, tambien a `desvio`; por eso puede ocultar diferencias en
#'   columnas cuyos valores no son pequeños pero cuyo desvio es menor que
#'   `1e-4`. En valores menores que `1e-10` —p-valores, concentraciones en
#'   unidades del sistema internacional— la corroboración tampoco distingue
#'   dos lecturas.
#'
#' @section Costo:
#' Los agregados de una tabla ancha se emiten por lotes; `muestra` acota lo que
#' se trae a R, no el trabajo del motor. `bloque_muestra` decide si se trae esa
#' muestra; `universo`, `metricas`, `tamano_lote_planos`, `tamano_lote_distintos` y
#' `max_consultas` acotan el trabajo SQL. [plan_perfilado_dbi()] dice cuántas
#' consultas se van a emitir antes de emitirlas. El orden de degradación es
#' agregados planos, total del universo cuando hace falta, distintos, moda y
#' mediana. Los
#' agregados planos sobre la misma tabla y filtro —el conteo de no nulos,
#' mínimos, máximos, medias, ceros, negativos y desvío— comparten una consulta
#' por lote y cada consulta que trae `n_validos` lleva además
#' `COUNT(*) AS n_total_consulta` en la misma sentencia. La completitud usa ese
#' denominador local, no el total de otro lote. Los no nulos se cuentan en
#' PostgreSQL con `COUNT(col)`, para no contar como faltante un tipo compuesto
#' cuyos campos sean todos nulos. En SQL Server y en los motores que
#' rechazan `COUNT()` sobre `text`, `ntext` e `image` se usa una expresión CASE;
#' la pregunta por el nulo se contesta sin publicar el valor enmascarado.
#' La fusión conserva la medición, no una identidad bit a bit entre
#' agrupamientos: la media y el desvío pueden diferir en el último bit según
#' cómo se agrupen las sumas, porque la suma en punto flotante no es asociativa.
#'
#' El total del universo se conserva por separado cuando el perfil se calcula
#' sobre una muestra. Si el lote completo es rechazado, sus mitades se sondean
#' por bisección: los grupos
#' aceptados se reutilizan como mediciones y las columnas culpables se reintentan
#' por métrica, con su denominador local. Las fuentes `TABLESAMPLE` que necesitan
#' el total del universo para escribir un porcentaje lo cuentan antes.
#' `COUNT(DISTINCT ...)` queda en una clase separada y usa su propio tamaño de
#' lote, conservador por omisión porque una cardinalidad puede derramar mucho
#' más que veinte agregados planos; la consulta exacta trae su
#' `n_validos_guard` compañero.
#' Cuando se pide `mediana` o `desvio` sin pedir `basicos`, cada columna que el
#' esquema expone como numérica paga además una sonda propia de magnitud. Usa
#' `MIN` para comprobar que el motor no está coaccionando texto a cero; la fila
#' `sonda_magnitud` queda declarada en `resumen_tabla$sql`, con su estado y la
#' etapa `sonda_magnitud`. Si la sonda no entra en `max_consultas`, las métricas
#' dependientes quedan `no_disponible` con el motivo del presupuesto. Cuando
#' `incluir_valores = FALSE`, el motivo no publica el valor que devolvió el
#' motor. Bajo `universo = "muestra_motor"` con `bloque_muestra =
#' "solo_agregados"`, si se pide también `validos` o `desvio`, la sonda no es
#' una consulta aparte: va en el lote de agregados, la misma sentencia y la
#' misma muestra que el desvío, y su fila `sonda_magnitud` comparte el
#' `consulta_id` del lote.
#' La proyección temporal no usa esos agregados planos: si hay más de un lote y
#' `instrumentar = TRUE`, se mide el primer lote de distintos y, después de
#' ejecutarlo, se multiplica su mediana por la cantidad total de lotes. El aviso
#' llega antes del segundo lote, en la unidad que se va a evitar; con un solo
#' lote no hay nada que proyectar. Si la duración no se pudo medir, el resultado
#' declara la proyección como no disponible.
#' La moda tiene otro canal: después de cada moda medida se obtiene una tasa en
#' ms por distinto y se usa para proyectar las modas pendientes. La cardinalidad
#' se toma del agregado de la corrida, de una clave garantizada o de la
#' estimación de catálogo que esté disponible; si falta, `meta$costo_moda` lo
#' declara y no inventa un número. El aviso llega antes de la siguiente moda.
#' La mediana se proyecta en ms por fila. La primera mediana medida en esta
#' corrida sirve para proyectar las restantes y el aviso precede a ese trabajo.
#' Si no existe una primera medición local para una mediana total, usa la
#' referencia declarada de otra corrida de 68 ms por millón de filas.
#' Si la consulta inicial que obtuvo las filas fue medida y resulta una cota
#' mayor, se publica también esa cota de lectura —no como medición de mediana—
#' para no subestimar una tabla grande recién cargada.
#' Las dos proyecciones quedan separadas en `meta$costo_moda` y
#' `meta$costo_mediana`; apagar el aviso no apaga su medición ni su metadata.
#' Antes de la primera consulta exacta se estima, cuando PostgreSQL expone
#' `pg_stats`, el tamaño de los hashes con `n_distinct`, `avg_width` y
#' `pg_class.reltuples`; `SHOW work_mem` y, desde PostgreSQL 13,
#' `SHOW hash_mem_multiplier` dan el límite efectivo. `meta$estimacion_derrame`
#' y `attr(meta$plan, "estimacion_derrame")` conservan el diagnóstico, siempre
#' rotulado como estimación y nunca como derrame medido. Si supera el límite se
#' avisa antes de pagar `COUNT(DISTINCT)` y se recomienda subir `work_mem` en la
#' sesión; el paquete no lo modifica. Una estadística ausente, un permiso
#' insuficiente o una versión sin el parámetro dejan la parte correspondiente
#' como no disponible. `n_distinct` es una estimación de muestra y puede quedar
#' corta; si luego `pg_stat_statements` mide un derrame, esa medición manda.
#' La misma corrida publica `meta$estimacion_derrame_moda` y
#' `meta$estimacion_derrame_mediana`. La moda deriva `metodo` del plan exacto
#' mediante `EXPLAIN (FORMAT JSON, COSTS OFF)` sin `ANALYZE`; la mediana usa
#' siempre un sort contra `work_mem`, con pisos de 32 bytes para tipos fijos y
#' 42 para `numeric`. El plan usa `n_validos` de catálogo. En la meta y en el
#' aviso, cuando se pidió la familia `validos`, ese denominador se reemplaza por
#' el medido en los agregados planos y se conserva también el valor de catálogo;
#' si no se midió, el motivo declara que se retuvo el catálogo. Ese reemplazo
#' alcanza solo al denominador: si la estimación publicada
#' marca `supera_memoria = TRUE`, el aviso se emite también con catálogo y
#' declara su fuente. La consolidada
#' decide por el máximo de columna y publica la suma de tapes sólo como
#' `estado_io_total_bytes` informativo.
#'
#' Los avisos de esta vía son deliberadamente distintos de los de [perfilar()]:
#' `perfilar_dbi()` los emite también en guiones no interactivos porque el costo
#' relevante ocurre en el servidor y puede consumir decenas de segundos antes
#' de que el llamador pueda hacer algo. En cambio, el aviso de tabla ancha de
#' [perfilar()] estima trabajo local sobre una tabla ya en R y queda limitado a
#' sesiones interactivas para no convertir la salida de un guion en ruido.
#' Cada aviso DBI tiene su propio interruptor y umbral porque sus unidades no
#' son comparables —segundos frente a bytes— y silenciar uno no debe ocultar el
#' otro. Apagar un aviso no apaga ninguna medición: `meta$costo_distintos`,
#' `meta$costo_moda`, `meta$costo_mediana`, `meta$derrame` y
#' `meta$estimacion_derrame` se publican igual.
#' Lo que no entra en el presupuesto queda en `no_disponible` con su motivo,
#' nunca en cero. `meta$tamano_lote_funciono` conserva el mayor lote aceptado
#' durante esa corrida; no se guarda estado global asociado a la conexión.
#'
#' @section Instrumentación:
#' `resumen_tabla$sql` conserva una fila por métrica y agrega la duración de la
#' consulta que la respalda, las filas devueltas y los bytes que ese resultado
#' ocupa en R. `consulta_id` identifica el intento dentro de la corrida y
#' `duracion_ms` es la duración de la consulta, repetida en cada fila que esa
#' consulta produjo; no es una duración por métrica. La columna `nivel` marca
#' qué filas se pueden sumar: la primera fila de cada `consulta_id` queda en
#' `nivel = 1` y sus repeticiones en `nivel = 2`. Por eso una suma segura usa
#' sólo `duracion_ms[nivel == 1]` (con `na.rm = TRUE` si corresponde), no la
#' columna completa.
#' `id_consulta` identifica la consulta de datos que produjo la medición: dos
#' métricas con el mismo identificador vieron exactamente las mismas filas y se
#' pueden comparar directamente. `NA` declara que esa garantía no se puede
#' hacer; en particular, las métricas por columna —moda, frecuencia de la moda
#' y mediana— no comparten filas con otras métricas. `etapa` permite agruparlo
#' (`conteos`, `moda`, `basicos`, `mediana`,
#' `desvio`, `lectura_muestra` y las sondas). Las métricas no solicitadas o que
#' no emitieron consulta conservan esos campos y los dejan en `NA`; en
#' particular, `NA` no significa cero.
#'
#' `resumen_tabla$sql$memoria_trabajo` agrega el eje del estado de trabajo del
#' motor: se deriva en orden como `NA` para una fila sin medición, `acotado`
#' para una muestra con `fraccion < 1` y, en los demás alcances efectivos,
#' según el método resuelto del registro; una muestra saturada (`fraccion = 1`)
#' cae a este último caso porque su tope es vacuo y se clasifica como tabla
#' completa. Sus únicos valores son
#' `"creciente"`, `"acotado"` y `NA`.
#'
#' En PostgreSQL, con `instrumentar = TRUE`, se toma una foto de
#' `pg_stat_statements` antes y después de la ventana que cubre los agregados
#' exactos instrumentables de distintos, moda y mediana. Las firmas se filtran
#' por texto y se normalizan en el paquete: cada literal numérico o de cadena
#' se reemplaza por su parámetro posicional y los identificadores entre comillas
#' dobles se conservan. Sólo se publica un derrame cuando una consulta coincide
#' y su contador aumentó en al menos una llamada dentro de la ventana. En ese caso,
#' `resumen_tabla$sql` agrega `derrame`,
#' `bloques_temporales_leidos`, `bloques_temporales_escritos` y
#' `fuente_derrame`, además de `llamadas_en_ventana`; `resumen_tabla$meta$derrame`
#' conserva el resumen y la fuente. Cuando el contador aumentó más de una vez,
#' el motivo declara que los bloques son un agregado de ese texto exacto y
#' pueden incluir otra sesión o llamada concurrente. Si la extensión no está
#' disponible o la instrumentación está apagada, el estado queda
#' `no_disponible` o `no_medido`: el paquete no deduce un derrame del tiempo ni
#' modifica `work_mem`.
#'
#' `resumen_tabla$meta$estimacion_derrame` es un diagnóstico distinto: conserva
#' la estimación de memoria y siempre la rotula como no medida. Puede quedar
#' parcial o no disponible por permisos, falta de `ANALYZE`, particiones sin
#' estadísticas o un motor que no sea PostgreSQL. Si ambos diagnósticos existen,
#' `meta$derrame` es la evidencia posterior y prevalece sobre la estimación;
#' una estimación que no superó el límite no contradice un derrame medido.
#' `meta$estimacion_derrame_moda` y `meta$estimacion_derrame_mediana` siguen la
#' misma regla, con el método del plan de la moda y el sort de la mediana;
#' `n_validos_medido` sólo aparece con valor cuando la familia `validos` fue
#' solicitada y sus agregados planos lo pudieron medir.
#'
#' `resumen_tabla$tiempos` reúne las etapas grandes del cliente en las mismas
#' unidades (`duracion_ms`): `lectura_muestra`, `perfilado_muestra`,
#' `perfilado_columnas`, y los análisis opcionales cuando se solicitan. Una
#' etapa apagada queda con estado `no_solicitado`; si la instrumentación se
#' apaga queda con estado `no_medido` y duración `NA`. La columna `nivel` dice cuáles se
#' pueden sumar: las de `nivel = 1` son disjuntas entre sí, y las de nivel mayor
#' están contenidas en alguna de ellas. `perfilado_muestra` es inclusivo
#' -contiene el perfilado por columna, las dependencias y los casi-duplicados-,
#' así que sumar la columna entera da más que la corrida.
#'
#' @section Datos personales:
#' `proteger_datos_personales` viaja en `...` hacia [perfilar()] y vale `FALSE`
#' por omisión: la protección es un complemento que se pide. Con `TRUE` alcanza
#' a los dos bloques: en `resumen_tabla` se
#' reemplaza la moda de las columnas clasificadas como personales, se ocultan
#' sus estadísticos de orden y sus momentos, se sanean los datos de conexión y
#' el SQL guardado no contiene ningún valor derivado de los datos. La
#' clasificación se toma del perfil de la muestra; si la muestra no se pudo
#' leer, la protección se aplica a todas las columnas y `meta` lo declara.
#' Lo que se oculta no queda `calculado`: su fila de `resumen_tabla$sql` dice
#' `omitido_por_privacidad`, con un motivo que distingue la columna clasificada
#' como personal de la que se cerró porque, sin muestra, no se pudo clasificar.
#' Una columna que no se protege publica sus estadísticos aunque comparta el
#' tipo personal con una protegida, como en [perfilar()]: un importe entero de
#' siete cifras o un número de factura clasificado `documento_identidad`
#' débil. Una copia del documento la tapa el piso por valor, que corre con la
#' tabla entera, y la que lo copia sin su verificador se clasifica como columna
#' personal con la regla de [perfilar()], sobre la muestra. Por la vía por
#' bloques eso incluye `meta$familias`, que guarda cada valor distinto de
#' toda columna no protegida: una columna `debil` —las cédulas sin su
#' verificador de OTRAS personas, como las de un garante— publica ahí cada
#' uno de sus valores, donde [perfilar()] publica sus dos extremos.
#' Limitación conocida: como la clasificación es sobre la muestra, con
#' una muestra que ve menos de tres valores distintos de la copia —chica y
#' ordenada sobre una tabla agrupada por persona— la copia no se clasifica, y
#' el resumen de la tabla entera publica sus extremos, que pueden ser
#' documentos de personas que la muestra no vio; por bloques, cada valor
#' distinto en `meta$familias`. Una muestra mayor o aleatoria lo evita, y
#' también declararla en `columnas_personales`. Lo mismo vale para una columna
#' cuya palabra el resto del nombre califica y que decide por sus valores
#' —`celular_estado`, `contacto_alta`, `usuario_baja`, `nombre_departamento`—:
#' rala, con una muestra que no trae ninguno de sus valores o unos pocos sin
#' su forma, no se protege, y por bloques publica cada valor en
#' `meta$familias`. No se cierra protegiendo por la palabra a la columna sin
#' valores, porque en [perfilar()] taparía la evidencia de toda columna vacía
#' con un nombre así. Un documento por el nombre, en cambio, se protege aunque
#' la muestra no traiga valores —una columna rala de documentos,
#' `cedula_conyuge`, `ci_tutor`—: se publica sólo si la muestra trae veinte
#' valores o más, de dos distintos, que lo desmientan.
#' El desvío se oculta como la media, como en [perfilar()]; también en
#' `resumen_tabla$meta$familias`, donde la vía por bloques (`bloque_filas`)
#' guarda lo que devolvió cada acumulador: ahí se tapan los extremos, la media
#' y el desvío de las columnas protegidas, y cada valor distinto. Y por la vía
#' por bloques corre el mismo piso por valor que sin ella —con los valores de
#' la muestra y, si la muestra no cubre la tabla, con los de la tabla entera—,
#' sobre **todas** las columnas: una cédula copiada en una columna de códigos o
#' un nombre citado en un texto libre se tapan en `resumen_tabla$columnas`, en
#' la corroboración y en `meta$familias` igual que sin `bloque_filas`; la misma
#' tabla publica lo mismo por las dos vías. Lo que el piso tapa en la tabla de
#' columnas —un extremo que es un documento, y la media y el desvío que lo
#' reconstruyen— se tapa también en `meta$familias`.
#' Si la muestra se recorta, la clasificación personal sólo cubre esas filas:
#' las cifras de valor del resumen SQL completo quedan marcadas en
#' `resumen_tabla$cobertura` y, con la protección activa, se ocultan hasta que
#' la clasificación cubra el mismo alcance. La corroboración no repite esas
#' cifras dudosas en su anotación. Y cuando la muestra no cubre la tabla, se
#' traen los valores distintos de las columnas protegidas de la tabla entera
#' —de texto o numéricas, una consulta por columna— y se protege con ellos lo
#' que se publica, con la misma regla que [perfilar()] en memoria: tildes, caja,
#' separadores, el documento parcial, los campos numéricos y la evidencia de los
#' hallazgos. Un valor de una persona que sólo está fuera de la muestra se tapa
#' igual. El **relleno** que sale del piso en memoria —el dígito repetido cinco
#' veces o más en una columna que sin él es casi una clave— se decide sobre la
#' tabla entera, no sobre la muestra: en la muestra de una tabla de movimientos
#' los clientes que se repiten casi no se repiten, y la cédula válida de un
#' cliente con seiscientos movimientos saldría como moda de otra columna. Con
#' la tabla leída completa decide la muestra, que es la tabla; si no, la
#' confirman los conteos exactos de la tabla —`n_distintos` y `n_validos`
#' calculados—, y sin ellos el relleno sigue en el piso. Con
#' `universo = "muestra_motor"` no hay tabla entera que lo confirme —los
#' conteos son los de la muestra del motor, y con `muestra = Inf` la muestra en
#' R es esa misma relación—: el relleno sigue en el piso. Y sale del piso sólo
#' en su columna, como en memoria: si otra columna protegida tiene el mismo
#' valor —el `1.111.111-1` de relleno de `cedula` es la cédula de un cónyuge—,
#' ese valor se sigue tapando. Y la protección es
#' **por tabla**: un valor protegido de otra tabla escrito en ésta no se
#' conoce; [perfilar_coleccion()] los cruza. Se traen hasta dos millones de valores; si hay más, o si la consulta
#' no se puede hacer, se tapan todos los valores de celda de las columnas no
#' personales —moda, extremos, ejemplos y, por la vía por bloques, cada valor
#' distinto y los extremos de `meta$familias`— y la evidencia de sus hallazgos, y
#' `resumen_tabla$meta$proteccion_personal$fuera_de_muestra` dice por qué. Salvo
#' un valor igual al nombre de la tabla o de su esquema, que es estructura: se
#' publica en `meta`, en cada SQL guardada y en `print()`, y un valor de celda
#' igual a él no se tapa —taparlo taparía el nombre en todo el objeto—; lo
#' mismo cuando
#' sin muestra se cierran todas las columnas. Limitación conocida: un
#' valor igual al nombre de una **columna** sí se tapa, porque un nombre de
#' columna puede ser el de una persona —una planilla con una columna por
#' docente—, y tapa también ese nombre en la descripción de las sondas de
#' dialecto (`meta$dialecto$sondas`) y, con `bloque_filas`, en la de la fuente
#' por bloques (`meta$fuente_bloques`, `meta$plan`); en `columnas$columna` y
#' en la SQL guardada queda. En
#' SQLite los valores se leen como texto, porque una columna de afinidad
#' numérica guarda texto y el controlador lo convertiría en número; también sin
#' muestreo, cuando la muestra es la tabla entera: ahí se releen como texto, con
#' una consulta, las columnas protegidas que el controlador no leyó como texto.
#' Y el motivo
#' de una cifra que no se pudo leer como número no cita el valor de una columna
#' protegida. Tampoco el **mensaje de un error del motor**, que es texto ajeno
#' y cita la celda que hizo fallar la consulta —`invalid input syntax for type
#' bigint: "4.685.467-9"`, en una vista que castea una cédula escrita con
#' puntos—: ese valor nunca se leyó, así que el piso no lo conoce y puede ser
#' de cualquier columna. Con la protección activa, todo mensaje de error que se
#' publica —en `sql`, `cobertura`, `meta`, en la colección y en los avisos— lleva
#' sus literales entre comillas —simples, dobles, tipográficas, bajas como las
#' del polaco, angulares— cambiados por `[literal omitido]`; también
#' un identificador entre comillas, salvo el nombre de la tabla o de una de sus
#' columnas. Y fuera de las comillas el mensaje publica **sólo lo permitido**:
#' el vocabulario de los mensajes de los motores, en inglés y en castellano,
#' las palabras de SQL, los nombres de tipo, los nombres de la tabla y de sus
#' columnas, los códigos SQLSTATE, los signos y los números de menos de seis
#' cifras —el piso de la protección: la línea, la posición, un código—;
#' todo lo demás sale `[literal omitido]`. Un número se cuenta con sus
#' separadores: `4.685.467-9` es uno de ocho cifras, y se lee como lo lee el
#' piso de la protección, con los mismos separadores —un espacio duro o uno
#' fino, el punto medio, una raya, `" - "`, dos espacios, un tabulador o un
#' salto de línea entre los grupos: `"099 - 123 - 456"` es uno de nueve—. El
#' mensaje se lee como lo dijo el motor: odbc lo arma con cli, que pone una
#' viñeta después de cada salto de línea y corta las líneas al ancho de la
#' consola, y un número partido en dos líneas —`"2901\n1234"`— quedaría partido
#' por la viñeta; se toman las líneas que guarda la condición, unidas por el
#' salto que puso el motor, y así se publican, sin las viñetas. Tampoco llevan
#' los colores ni los enlaces que cli pone en una consola a color —la de
#' RStudio—: las secuencias ANSI quedarían guardadas en el motivo y, con
#' protección, pegadas a los marcadores. Lo que cli agrega dentro de una línea
#' no se distingue del texto del motor y queda: sin color, cli cita entre
#' comillas el archivo del controlador (`'nanodbc/nanodbc.cpp:1802'`) y con
#' protección esa cita sale `[literal omitido]`; con color se publica. Así
#' se tapa también el
#' valor que el motor cita sin comillas —duckdb: `Type INT64 with value
#' 59899123456 can't be cast`, y la cadena que `strptime` repite en otra
#' línea, que se tapa entera; SQL Server con la sesión en sueco o neerlandés—
#' y la cola de un valor que lleva una comilla adentro. Y el mensaje pasa
#' también por el piso con los valores protegidos que la llamada ya leyó —en
#' [perfilar_coleccion()], los de todas sus tablas—, antes de las dos pasadas,
#' con el valor entero a la vista, y otra vez al final: un valor escrito sólo
#' con lo permitido —los apellidos `"Campos Cadena"`, dos palabras del
#' vocabulario, o un nombre cuyas palabras son columnas de otra tabla— se
#' tapa entero, y el nombre de una columna que es también uno de esos
#' valores —la docente `"Florencia"` de una planilla con una columna por
#' docente— deja de exceptuarse, con la comparación del piso. En
#' [perfilar_coleccion()] cada mensaje se vuelve a leer al final, desde como
#' llegó, con todo lo que la colección leyó: con una vista perfilada antes que
#' su tabla base, el piso todavía no conoce el nombre cuando llega el mensaje,
#' y releer el texto ya tapado dejaría su resto —`"De Los Campos"` de
#' `"María De Los Campos"`—. Lo que queda
#' abierto: un valor que la llamada **no** leyó —la celda que hizo fallar la
#' lectura de la muestra, de una columna que la vista castea— escrito sólo con
#' lo permitido, o igual al nombre de una columna, se publica, porque el
#' mensaje no tiene cómo distinguirlo del vocabulario ni de un nombre. Un mensaje en otro
#' idioma conserva su SQL, sus tipos y sus nombres y se lee peor, que es el
#' lado cerrado. Quedan una palabra de SQL entre comillas —`Incorrect syntax
#' near 'LIMIT'` dice que el motor no acepta ese dialecto— y un signo suelto.
#' El texto que PostgreSQL cita sin comillas al no poder leer un JSON
#' (`CONTEXT:  JSON data, line 1: ...`) se tapa hasta el fin de la línea, en
#' PostgreSQL, en duckdb y en SQL Server.
#' **Sin protección** (`proteger_datos_personales = FALSE`) el mensaje del motor
#' se publica entero, en todas esas salidas: el literal que hizo fallar la
#' lectura y el SQL de esa lectura, sólo sin las viñetas, los cortes ni los
#' colores que agrega cli. El diagnóstico es el cometido del paquete —`Conversion failed when
#' converting the nvarchar value 'N/D' to data type int` dice que la columna
#' trae un faltante disfrazado—, y sin protección ya se publican valores de
#' todas las columnas —modas, ejemplos, patrones—: omitirlo ahí no protegería
#' nada y quitaría el diagnóstico. Vale igual en [perfilar_coleccion()], que
#' pasa la bandera a cada tabla y la aplica a sus propios motivos.
#' [plan_perfilado_dbi()], [coleccion()], [estimar_costo_coleccion()] y
#' [relaciones_coleccion()] no tienen la bandera: llamadas por su cuenta, tapan
#' el mensaje como con la protección activa.
#' `incluir_valores = FALSE` va más lejos: no emite las consultas de moda ni de
#' mediana y no informa mínimo ni máximo, útil cuando la tabla es un padrón y
#' la moda de un identificador único es un documento real. Si se pidió `desvio`,
#' la sonda de magnitud que ese cálculo necesita puede emitirse, pero su motivo
#' nunca publica el valor devuelto por el motor.
#'
#' @param conexion Conexión abierta compatible con DBI.
#' @param tabla Nombre de tabla o un objeto aceptado por
#'   [DBI::dbQuoteIdentifier()].
#' @param universo Universo sobre el que se calculan los agregados SQL:
#'   `"tabla_completa"` (por omisión) o `"muestra_motor"`. En el segundo caso,
#'   todas las métricas SQL usan la relación muestreada por el motor y no se
#'   reemplazan silenciosamente por resultados de la tabla completa.
#' @param muestra_motor Cantidad positiva y finita de filas que el motor debe
#'   tomar cuando `universo = "muestra_motor"`. Es obligatorio en ese universo y
#'   debe quedar `NULL` para `"tabla_completa"`; la función rechaza temprano
#'   valores no enteros, no positivos o `Inf`. Si una vista falla en una fila,
#'   el resumen conserva el alcance de la materialización que sí se pudo leer:
#'   las columnas legibles se perfilan y la columna rota queda
#'   `no_disponible`; la cobertura no presenta esa lectura parcial como una
#'   lectura completa de la vista.
#' @param muestra Cantidad positiva de filas solicitadas para el perfil de
#'   muestra que se trae a R, o `Inf` para traer la tabla entera. Este límite es
#'   independiente de `universo`: en `muestra_motor`, `muestra_motor` decide las
#'   filas del resumen SQL y `muestra` decide las filas del bloque
#'   `perfil_muestra`. En `tabla_completa`, `muestra` no cambia los agregados.
#'   Cuando `universo = "muestra_motor"`, el resumen usa toda la materialización
#'   del motor y este argumento solo recorta el diagnóstico en R; por eso
#'   `meta$materializacion$n_filas` puede ser mayor que
#'   `perfil_muestra$meta$filas`.
#'
#'   Sin `orden_muestra`, las filas del bloque en R no son una muestra aleatoria
#'   garantizada sino las primeras que devuelva el motor. El límite también
#'   alcanza la muestra común con que se buscan dependencias. Use un entero
#'   finito para acotar ese trabajo cuando el tiempo no sea la restricción.
#' @param max_celdas_muestra Máximo de celdas que puede contener el bloque
#'   `perfil_muestra`. Por defecto es `1000000`; se calcula antes de leer como
#'   filas por columnas del esquema. Si reduce la muestra,
#'   `perfil_muestra$cobertura_diagnosticos` usa la misma declaración que
#'   `perfilar()`, con las celdas solicitadas, el umbral y el tope que mandó.
#'   `Inf` desactiva este tope. No modifica los agregados SQL.
#' @param max_bytes_muestra Máximo de bytes de la muestra materializada que
#'   alimenta `perfil_muestra`. Por defecto es `512 MiB`. En
#'   `muestra_motor`, el límite se cruza con el presupuesto de materialización
#'   y se respeta antes de cada `dbFetch(n)`: cuando la cota de tipos es
#'   demasiado conservadora se lee una fila inicial, se mide lo que ocupa en la
#'   materialización y los bloques siguientes se piden con el doble de margen
#'   sobre la fila más grande medida; el spool nunca pasa el tope. Si reduce la muestra, `meta$muestreo`,
#'   `meta$materializacion` y `cobertura_diagnosticos` informan las filas
#'   solicitadas, efectivas y cuál tope mandó. `meta$muestreo$filas_por_bytes`
#'   publica la cantidad obtenida de la medicion y
#'   `meta$muestreo$filas_por_bytes_fuente` lo declara. `Inf` desactiva este
#'   tope. No modifica los agregados SQL.
#' @param max_bytes_procesamiento Límite de bytes del estado retenido por el
#'   procesamiento por bloques y por la lectura del spool en R. Se comprueba
#'   antes de publicar un bloque o una pasada; si la materialización cabe pero
#'   el objeto que R necesita para perfilarla supera el límite, el perfil se
#'   descarta y se emite el mismo aviso de alcance degradado, con
#'   `tope_que_mando = "procesamiento"`. `Inf` desactiva este límite.
#' @param max_bytes_materializacion Presupuesto de bytes del spool externo de
#'   `muestra_motor`. Se mide por chunk antes de cada escritura, dejando espacio
#'   para el trailer; si no alcanza, se publica
#'   `spool_presupuesto_excedido` y se conserva la parte que entró como muestra
#'   recortada, con `muestra_inestable:presupuesto_materializacion`. En
#'   `muestra_motor`, el primer bloque se acota antes de pedirlo y los siguientes
#'   se adaptan a los bytes medidos; el resultado conserva
#'   `meta$bytes_muestra` y `meta$tiempos`. `Inf` desactiva este límite.
#' @section Valores de texto extensos:
#'   En `muestra_motor`, las columnas de texto de PostgreSQL, SQL Server,
#'   MySQL y MariaDB que superan `max_largo_valor_vocabulario` se solicitan
#'   como largo en caracteres, largo en bytes y resumen MD5. El contenido
#'   completo se conserva solo para los valores que no superan ese umbral, por
#'   lo que el tamaño máximo de una fila se conoce antes de `dbFetch(n)`. La
#'   cobertura agrega `texto_largo_no_evaluado` para declarar los diagnósticos
#'   textuales que no se pudieron calcular sobre esos valores; sus faltantes,
#'   duplicados y longitudes siguen entrando en las métricas disponibles.
#' @param bloque_filas Entero positivo que activa el recorrido de
#'   `tabla_completa` por bloques. Se abre un unico result set con
#'   `dbSendQuery()` y cada bloque se lee con `dbFetch(n = bloque_filas)` antes
#'   de liberar la entrada; `NULL` conserva la via existente. El resultado
#'   publica `meta$alcance$orden`, `meta$bloques`, `meta$bytes` y los eventos del
#'   vigilante. Los drivers sin retencion incremental demostrada (incluido
#'   DuckDB en esta matriz) quedan `no_disponible` con su motivo y un aviso
#'   `lupa_aviso_muestra_motor`, sin caer en `dbGetQuery()`. Si se pide `moda` o `mediana`, la lectura por bloques inicia tambien el mapa
#'   central de distintos aunque `n_distintos` no se haya pedido: la mediana
#'   depende de ese mapa y la fila `n_distintos` conserva `no_solicitado`.
#'   Las columnas binarias compatibles se solicitan en la misma forma que la
#'   muestra, `largo:md5`, para que R no materialice los bytes crudos; los
#'   largos que se publican se reconstruyen desde el prefijo y son los largos
#'   originales, no el largo de esa cadena.
#'   Bajo `bloque_filas`, `perfil_muestra` sigue siendo la muestra diagnóstica
#'   acotada por `muestra`, `max_celdas_muestra` y `max_bytes_muestra`; su
#'   `general$filas` no es la cobertura, que se publica en
#'   `meta$bloques$filas_vistas`. Si el recorrido por bloques no puede leer una
#'   columna de una vista, se vuelve a leer la muestra diagnóstica por columnas:
#'   las columnas sanas conservan su perfil y sus magnitudes, y la columna rota
#'   queda en `no_disponible` con el motivo del motor. No se publica como
#'   privacidad ni como `no_solicitado`.
#' @param orden_muestra Columnas para `ORDER BY`. La salida solo declara orden
#'   reproducible cuando la combinación es única en toda la tabla. Sin este
#'   argumento, DBI no garantiza el orden ni la pertenencia de una muestra
#'   limitada, y `meta` lo declara expresamente. No se usa cuando
#'   `bloque_muestra = "solo_agregados"`. Con la lectura por bloques, la identidad de la
#'   fuente por bloques gobierna el recorrido y este pedido queda declarado en
#'   `meta$orden_muestra` con el motivo estable de que no gobierna esa via. Si
#'   el motor falla al evaluar una columna del `ORDER BY`, la vía prueba cada
#'   componente, recupera las columnas legibles sin ese orden cuando puede y
#'   publica `alcance_distinto` con el motivo de que el orden pedido no se pudo
#'   aplicar; no lo presenta como si ninguna columna fallara.
#' @section Progreso:
#' Traer la tabla entera puede tardar minutos sobre una tabla grande, y una
#' corrida callada no se distingue de una colgada. En una sesión interactiva se
#' muestra una barra que avanza contra las consultas que el plan dice que se van
#' a emitir —un total conocido, no una estimación—, y no aparece cuando la
#' corrida es de menos de una docena de consultas, porque termina antes de que
#' sirva.
#'
#' `options(lupa.progreso = TRUE)` la fuerza y `FALSE` la apaga; fuera de una
#' sesión interactiva está apagada, para que la salida de un guion no traiga
#' ruido que despues haya que filtrar. No cambia ningún valor de lo que se mide:
#' hay una prueba que compara el perfil con la barra y sin ella.
#'
#' @param estrategia_mediana Preferencia para resolver `mediana`: `"exacta"`
#'   (por omisión) o `"aproximada_motor"`. La sonda prueba siempre primero una
#'   forma nativa exacta consolidada, luego una forma exacta por columna y deja
#'   las funciones nativas aproximadas para el final. Por eso esta opción
#'   describe la estrategia habilitada, no garantiza el método ejecutado. El
#'   método que efectivamente corrió está en `resumen_tabla$sql$metodo`, en la
#'   fila de `metrica = "mediana"` de cada columna, y es la única fuente por
#'   columna. `meta$estrategia_mediana` publica la resolución de la tabla:
#'   lo pedido (`estrategia_solicitada`), la forma que el motor aceptó para la
#'   tabla (`estrategia_resuelta`), su `estado` y su `motivo`. No es el método
#'   de cada columna: una columna que no puede usar esa forma —un `float8` de
#'   PostgreSQL, que la deja por la lectura exacta, o una columna con
#'   extremos— corre por otra (`dos_consultas` en la tabla completa, la CTE de
#'   ventanas en la muestra) y lo declara en su fila de `resumen_tabla$sql`,
#'   aunque `meta$estrategia_mediana` siga nombrando la consolidada. El `estado`
#'   de `meta$estrategia_mediana` describe la forma, no la fila: en
#'   `universo = "muestra_motor"` la fila de cada columna queda `estimado`.
#'   Las columnas `estrategia_solicitada`, `estrategia_resuelta` y
#'   `estado_estrategia` de `resumen_tabla$sql` son las de `n_distintos`
#'   (`meta$estrategia_distintos`), repetidas en todas las filas: en la fila de
#'   la mediana no describen la mediana. Una mediana resuelta por una forma
#'   exacta queda
#'   `estado = "calculado"` y `error_esperado = "no_aplica"`, aunque se haya
#'   pedido `"aproximada_motor"`; sólo una aproximación ejecutada queda
#'   `estado = "estimado"`. `universo = "muestra_motor"` combinado con
#'   `"aproximada_motor"` se rechaza temprano.
#' @param metricas Selección explícita de grupos de métricas: `"validos"`,
#'   `"distintos"`, `"moda"`, `"basicos"`, `"mediana"` y `"desvio"`. El
#'   valor por omisión solicita las seis. `c("validos", "basicos", "desvio")`
#'   omite distintos, moda y mediana, y `"validos"` sólo cuenta los no nulos.
#' @param estrategia_distintos Procedencia explícita para `n_distintos`:
#'   `"exacta"` (por omisión) emite `COUNT(DISTINCT)`; `"aproximada_motor"`
#'   usa una función nativa aceptada por el motor y deja la métrica en
#'   `no_disponible` si no existe; `"catalogo"` lee
#'   `pg_stats.n_distinct` en PostgreSQL y publica el resultado como
#'   `estimado_catalogo`, nunca como medición, cuando
#'   `universo = "tabla_completa"`. En `muestra_motor` queda `no_disponible`,
#'   porque el catálogo describe la relación entera y la corrida mide un
#'   subconjunto; y
#'   `"omitida"` no emite ninguna consulta. No hay repliegue automático entre
#'   estrategias. El resultado publica `estrategia_solicitada`,
#'   `estrategia_resuelta` y `estado` en `meta$estrategia_distintos`, y las dos
#'   primeras también en `resumen_tabla$sql`. En `pg_stats`, un valor positivo
#'   es el conteo estimado y uno negativo es una fracción de las filas. Cuando la
#'   relación tiene descendientes se elige `inherited = TRUE`, porque esa fila
#'   describe lo que lee una consulta sin `ONLY`; una relación sin hijas usa su
#'   única fila propia. Las fracciones se convierten con la suma de
#'   `pg_class.reltuples` de la jerarquía. Si no hay una fila utilizable —por
#'   ejemplo, antes de `ANALYZE`— o hay ambigüedad, la métrica queda
#'   `no_disponible`, no en cero.
#' @param max_consultas Presupuesto declarado de consultas. Al agotarse, las
#'   métricas restantes quedan en `no_disponible` con ese motivo. Cuenta toda
#'   sentencia que el perfilado manda al motor —la preparación, las lecturas de
#'   catálogo, el recorrido por bloques y, por el spool de la muestra del
#'   motor, la preparación que la corrida repite para publicar su plan—, la
#'   misma cuenta de [plan_perfilado_dbi()] y de
#'   `resumen_tabla$meta$consultas$emitidas`. No cuentan las sentencias de la
#'   guarda de transacción (`SAVEPOINT` y, en SQL Server, la pregunta por la
#'   transacción abierta antes de cada consulta), ni las lecturas de
#'   `pg_stat_statements` de `instrumentar`, ni las que algunos controladores
#'   mandan para contestar `DBI::dbGetInfo()` o `DBI::dbIsValid()`: duckdb 1.1
#'   pregunta su versión y manda `SELECT 1`, una o dos veces por corrida. La
#'   preparación y el recorrido por
#'   bloques se cuentan pero no se omiten: sin ellos no hay perfil. Con
#'   `max_consultas = attr(plan, "total_maximo")` ninguna métrica queda afuera
#'   por el presupuesto.
#' @param tamano_lote Cantidad máxima de columnas por consulta consolidada.
#'   Se conserva por compatibilidad y, si se informa, fija el tamaño de las dos
#'   familias. Para control separado, usar `tamano_lote_planos` y
#'   `tamano_lote_distintos`.
#' @param tamano_lote_planos Cantidad máxima de columnas por consulta de
#'   agregados planos. En SQL Server y en columnas `float8` de PostgreSQL, el
#'   desvío conserva su cálculo centrado en una segunda pasada del mismo tamaño.
#'   El valor por omisión es 20.
#' @param tamano_lote_distintos Cantidad máxima de columnas por consulta de
#'   cardinalidades exactas. El valor por omisión es 2, un supuesto del código
#'   medido sobre un PostgreSQL de referencia: el motor hace una sola pasada por
#'   la tabla para todos los conteos de una consulta, así que un lote de uno
#'   cuesta por columna bastante más que uno de dos; uno de dos cuesta por
#'   columna casi lo mismo que uno de cuatro y derrama menos, y los lotes
#'   mayores derraman más porque los conteos compiten por `work_mem`. Una sola
#'   cardinalidad todavía puede forzar un agregado pesado y derramar mucho más
#'   que un lote plano.
#' @param dialecto Capacidad de acotar filas: `"auto"` la sondea, y
#'   `"limit"`, `"top"`, `"fetch_first"`, `"rownum"` o `"portable"` la
#'   declaran sin sondeo.
#' @param incluir_valores Si publica valores de celda. Con `FALSE` no se emiten
#'   las consultas de moda, extremos y mediana, y se limpian esos campos en el
#'   resumen, la muestra, los bloques, la cobertura y los motivos; también se
#'   retiran ejemplos de patrones, familias de acumuladores y cualquier muestra
#'   cruda. El mensaje de un error del motor, que cita la celda que lo provocó,
#'   se publica sin sus literales, como con `proteger_datos_personales = TRUE`.
#'   Los conteos, proporciones y agregados que no son valores de celda
#'   pueden seguir publicándose. La elección queda en
#'   `resumen_tabla$meta$incluir_valores` y `perfil_muestra$meta`.
#' @param politica_costo Política optativa para las métricas caras. El valor por
#'   omisión, `"todas"`, conserva moda y mediana para todas las columnas
#'   solicitadas. `"por_cardinalidad"` resuelve primero las fuentes
#'   estructurales y mide valores válidos y distintos sólo cuando hace falta y
#'   la estrategia lo permite. Luego omite, por columna, sólo la moda cuando la
#'   proporción de distintos alcanza `umbral_cardinalidad`; la mediana se
#'   conserva porque las mediciones disponibles muestran que su costo depende de
#'   las filas y no de la cardinalidad. Los únicos valores aceptados son
#'   `"todas"` y `"por_cardinalidad"`; no hay alias históricos.
#' @param umbral_cardinalidad Proporción entre valores distintos y válidos que
#'   activa la omisión de la moda con `politica_costo = "por_cardinalidad"`. El
#'   valor por omisión es `0.5` sólo cuando esa política se pide explícitamente;
#'   se puede mover en cada llamada. Este argumento no gobierna la mediana:
#'   `meta$decisiones_costo` explica la decisión de cada métrica por separado.
#'   Para pedir todas las métricas use `politica_costo = "todas"`.
#' @param avisar_costo_distintos Si es `TRUE`, avisa, después de medir el primer
#'   lote y antes del segundo, cuando la proyección del costo de
#'   `COUNT(DISTINCT)` alcanza `umbral_segundos_aviso_distintos`. Por omisión es
#'   `TRUE`. Este aviso no depende de `interactive()`: también llega en guiones
#'   porque el costo se paga en el servidor y puede durar decenas de segundos.
#' @param umbral_segundos_aviso_distintos Segundos estimados a partir de los
#'   cuales se emite el aviso del costo de `COUNT(DISTINCT)`, después del primer
#'   lote. Por omisión es `30`, el umbral histórico; `Inf` lo desactiva
#'   explícitamente. Con un solo lote no se publica una proyección porque el
#'   costo ya se pagó. El valor no cambia la proyección ni la medición que se
#'   publica.
#' @param avisar_costo_moda Si es `TRUE`, avisa antes de ejecutar las modas
#'   pendientes cuando su proyección alcanza `umbral_segundos_aviso_moda`. Por
#'   omisión es `TRUE`. La tasa se mide con modas anteriores de esta corrida;
#'   si falta cardinalidad, se declara en la proyección y no se supone.
#' @param umbral_segundos_aviso_moda Segundos estimados a partir de los cuales
#'   se emite el aviso de la moda. Por omisión es `30`; `Inf` lo desactiva
#'   explícitamente. El valor no cambia la medición ni la proyección publicada.
#' @param avisar_costo_mediana Si es `TRUE`, avisa antes de ejecutar las
#'   medianas pendientes cuando su proyección alcanza
#'   `umbral_segundos_aviso_mediana`. Por omisión es `TRUE`. La proyección sigue
#'   las filas, no la cardinalidad.
#' @param umbral_segundos_aviso_mediana Segundos estimados a partir de los cuales
#'   se emite el aviso de la mediana. Por omisión es `30`; `Inf` lo desactiva
#'   explícitamente. Cuando no existe una primera medición local, una sola
#'   mediana total usa la referencia de banco declarada de 68 ms por millón de
#'   filas de otra corrida. Si la consulta inicial que obtuvo las filas fue
#'   medida y da una cota mayor, se publica como cota de lectura, no como
#'   medición de mediana.
#' @param avisar_derrame_estimado Si es `TRUE`, avisa cuando un lote de
#'   `COUNT(DISTINCT)` supera la memoria efectiva y su tamaño estimado alcanza
#'   `umbral_bytes_aviso_derrame_estimado`. Por omisión es `TRUE`. Este aviso
#'   sólo puede aparecer cuando PostgreSQL permite estimar el hash.
#' @param umbral_bytes_aviso_derrame_estimado Tamaño estimado del hash, en
#'   bytes, a partir del cual se avisa un derrame potencial entre los lotes que
#'   ya superan la memoria efectiva. Por omisión es `0`, que conserva el aviso
#'   para cualquier lote que la supere; `Inf` lo desactiva explícitamente. El
#'   valor no cambia la estimación ni la medición posterior del derrame.
#' @param bloque_muestra Qué bloques se solicitan: `"con_muestra"` (por
#'   omisión) calcula también `perfil_muestra`, o `"solo_agregados"` omite su
#'   lectura y devuelve sólo los agregados SQL. La decisión vale para los dos
#'   universos: con `muestra_motor`, los agregados siguen usando la relación
#'   muestreada, pero no se abre el spool ni se leen filas; la corrida publica
#'   el estado `no_solicitado` y `meta$bloques$filas_vistas = 0`. La segunda
#'   opción no cambia el alcance de esos agregados: eso lo decide `universo`.
#' @param columnas_opcionales Nombres de columnas que sólo son aplicables a
#'   parte de las filas. Esta política se aplica al `perfil_muestra`; el
#'   resumen SQL no la traduce y lo declara en `resumen_tabla$cobertura`. Los
#'   dos bloques cuentan `n_faltantes` sobre universos distintos, así que la
#'   corroboración no lo compara: ver «Lo que el motor guarda distinto que R».
#' @param aplicabilidad Lista nombrada de fórmulas de un solo lado, con una
#'   regla por columna. Se reenvía al `perfil_muestra`; el resumen SQL no la
#'   traduce y lo declara en `resumen_tabla$cobertura`, y la corroboración no
#'   compara lo que la regla cambia.
#' @param sentinelas_numericos Vector completo de valores numéricos que se
#'   declaran como faltantes en el `perfil_muestra`. Se normaliza como un
#'   conjunto numérico, por lo que el orden, el tipo entero o doble y los
#'   duplicados no cambian el resultado. El resumen SQL no los excluye de sus
#'   agregados y lo declara en `resumen_tabla$cobertura`; la corroboración no
#'   compara las métricas de magnitud de una columna de la que la muestra
#'   excluyó alguno. En una columna `real`, una representacion float32 del
#'   centinela fraccionario se alinea antes de perfilar la muestra; la
#'   corroboración reconoce esa representacion como el mismo centinela.
#'
#'   Rige la misma reserva que en [perfilar()]: un valor de la lista **por
#'   omisión** que aparece una sola vez y dentro del rango de los demás no se
#'   señala. Declarar el valor lo vuelve a contar.
#' @param instrumentar Si se cronometra cada consulta y las etapas grandes de R
#'   y, en PostgreSQL, se intenta atribuir el uso de bloques temporales de los
#'   `COUNT(DISTINCT)` exactos mediante `pg_stat_statements`.
#'   Por omisión es `TRUE`; agrega `duracion_ms`, `cpu_ms`,
#'   `n_filas_resultado`, `bytes_resultado_r`, `consulta_id`, `etapa` y `nivel`
#'   a `resumen_tabla$sql`, y el resumen `resumen_tabla$tiempos`. Con `FALSE` se
#'   conserva el mismo plan, la misma cantidad y el mismo orden de consultas,
#'   pero los campos medibles quedan en `NA`. `id_consulta` **no** depende de
#'   esta opcion: no es una medicion sino un hecho estructural sobre que
#'   consulta produjo cada metrica, y se publica igual con `FALSE`. Las
#'   duraciones usan `Sys.time()` y el CPU del cliente usa la suma de
#'   `proc.time()[c("user.self", "sys.self")]`. `cpu_ms` es cero cuando el
#'   proceso no consumió CPU; `NA` significa que no se pudo medir. Los
#'   intervalos que el reloj no puede resolver no se publican como cero.
#'   En PostgreSQL, la atribución del derrame lee `pg_stat_statements` dos
#'   veces —antes y después—, limitado al usuario y la base de la conexión, y
#'   atribuye solo las consultas cuyas llamadas crecieron en esa ventana; una
#'   entrada que el catálogo repite —la misma consulta de otro usuario o
#'   anidada— no se atribuye. Medido con unas 4.900 filas en el catálogo:
#'   sobre una tabla de 23 filas, 0,3 s con `TRUE` contra 0,15 s con `FALSE`.
#' @param ... Argumentos enviados a [perfilar()] para analizar la muestra.
#'   `columnas_codigo` vale además en `resumen_tabla`: `media`, `mediana` y
#'   `desvio` de una columna declarada quedan en `NA` y
#'   `resumen_tabla$cobertura` lo declara con estado `no_aplica`. Sus nombres se
#'   validan contra las columnas de la tabla aunque no haya muestra. Un nombre
#'   abreviado vale lo mismo que el entero, como lo completa R al llamar a
#'   [perfilar()]: `proteger = FALSE` es `proteger_datos_personales = FALSE`
#'   también para `resumen_tabla`. La bandera, `fecha` y los nombres se validan
#'   al entrar, también con `bloque_muestra = "solo_agregados"`: un nombre que
#'   [perfilar()] no tiene es un error, no un fallo parcial. Los demás valores
#'   los valida [perfilar()] al perfilar la muestra —sin muestra no se
#'   validan—, y uno inválido deja `perfil_muestra = NULL` con el error de
#'   [perfilar()] como motivo, legible también con la protección: un error que
#'   se repite sobre la muestra sin filas no cita ninguna celda.
#'
#' @return Objeto de clase `perfil_dbi` con dos componentes: `resumen_tabla`, de
#'   alcance completo o muestreado según `universo`, y `perfil_muestra`, un objeto
#'   `perfil` cuyo `meta$origen_dbi` declara tabla, conexión, SQL y alcance.
#'   `perfil_muestra` es `NULL` si la muestra no se pudo obtener o si se pidió
#'   `bloque_muestra = "solo_agregados"`; `resumen_tabla$cobertura` distingue
#'   esos casos con `no_disponible` y `no_solicitado`, respectivamente.
#'   Cuando `universo = "muestra_motor"` y no se solicitó el bloque, la metadata
#'   además declara `meta$materializacion$estado = "no_solicitado"` y
#'   `meta$bloques$filas_vistas = 0`: las filas no se materializaron y luego se
#'   descartaron.
#'   `resumen_tabla$meta$clave` conserva siempre la respuesta del catálogo de la
#'   clave primaria: `columnas`, `fuente`, `motivo`, `garantia` y `estado`.
#'   `garantia` puede ser `garantizada`, `declarada_no_garantizada`,
#'   `desconocida` o `no_declarada`; `estado` conserva, cuando el motor los
#'   expone, `visible`, `restriccion_diferible`,
#'   `universo_incluye_descendientes` e `indice_no_unico`. Una consulta fallida
#'   queda diferenciada de una clave no declarada.
#'   En `muestra_motor`, `resumen_tabla$tiempos` incluye materialización,
#'   lectura del spool y perfilado local; `perfil_muestra$meta$bytes_muestra`
#'   conserva los bytes del spool. `meta$muestreo$reintentos` y
#'   `meta$muestreo$metodo_inicial` describen la recuperación de una muestra
#'   corta. En `muestra_motor` o bajo `bloque_filas`, las columnas binarias de
#'   motores compatibles se representan como
#'   `largo:md5` durante la lectura y el perfil publica sus largos originales;
#'   el contenido no se conserva.
#' @export
#' @seealso [plan_perfilado_dbi()], [perfilar()]
#'
#' @examples
#' if (requireNamespace("DBI", quietly = TRUE) &&
#'     requireNamespace("RSQLite", quietly = TRUE)) {
#'   con <- DBI::dbConnect(RSQLite::SQLite(), ":memory:")
#'   DBI::dbWriteTable(con, "ejemplo", data.frame(id = 1:10, valor = 11:20))
#'   resultado <- perfilar_dbi(con, "ejemplo", muestra = 5, orden_muestra = "id")
#'   DBI::dbDisconnect(con)
#' }
perfilar_dbi <- function(conexion, tabla,
                         universo = c("tabla_completa", "muestra_motor"),
                         muestra_motor = NULL, muestra = Inf,
                         orden_muestra = NULL,
                         metricas = .METRICAS_DBI,
                         estrategia_distintos = "exacta",
                         estrategia_mediana = c("exacta", "aproximada_motor"),
                         politica_costo = c("todas", "por_cardinalidad"),
                         bloque_muestra = c("con_muestra", "solo_agregados"),
                         max_consultas = Inf,
                         dialecto = "auto", incluir_valores = TRUE,
                         tamano_lote = NULL,
                         tamano_lote_planos = .TAMANO_LOTE_PLANOS_DBI,
                         tamano_lote_distintos = .TAMANO_LOTE_DISTINTOS_DBI,
                         instrumentar = TRUE,
                         umbral_cardinalidad = .UMBRAL_CARDINALIDAD_COSTO_DBI,
                         avisar_costo_distintos = TRUE,
                         umbral_segundos_aviso_distintos =
                           .UMBRAL_SEGUNDOS_AVISO_DISTINTOS_DBI,
                         avisar_costo_moda = TRUE,
                         umbral_segundos_aviso_moda =
                           .UMBRAL_SEGUNDOS_AVISO_MODA_DBI,
                         avisar_costo_mediana = TRUE,
                         umbral_segundos_aviso_mediana =
                           .UMBRAL_SEGUNDOS_AVISO_MEDIANA_DBI,
                         avisar_derrame_estimado = TRUE,
                         umbral_bytes_aviso_derrame_estimado =
                           .UMBRAL_BYTES_AVISO_DERRAME_ESTIMADO_DBI,
                         max_celdas_muestra = .MAX_CELDAS_MUESTRA,
                         max_bytes_muestra = .MAX_BYTES_MUESTRA,
                         bloque_filas = NULL,
                         max_bytes_procesamiento = .MAX_BYTES_MUESTRA,
                         max_bytes_materializacion = .MAX_BYTES_MUESTRA,
                         columnas_opcionales = character(),
                         aplicabilidad = NULL,
                         sentinelas_numericos = c(-9, -99, -999, -9999, 999),
                         ...) {
  captura_argumentos <- .capturar_argumentos_perfilar_dbi(
    match.call(expand.dots = TRUE), environment(), list(...)
  )
  argumentos_originales <- captura_argumentos$argumentos
  argumentos_declarados <- captura_argumentos$declarados
  .fijar_numerica_c()  # LC_NUMERIC en "C" mientras lee de la conexion
  .fijar_senas_conexion_dbi(conexion)
  # Lo que el controlador entrego en latin1 ANTES de esta tabla -otra tabla de
  # la misma coleccion-: se declara solo lo de esta. Ver
  # `.texto_del_controlador_dbi()`.
  texto_previo <- .texto_anotado_dbi(conexion)
  # El nombre normalizado es el que viaja a todo lo que sigue, no solo a la
  # comprobacion de existencia (ver `.nombre_para_conexion_dbi()`).
  tabla <- .nombre_para_conexion_dbi(tabla)
  argumentos_muestra <- .argumentos_para_perfilar(captura_argumentos$puntos)
  .argumento_dbi(.validar_argumentos_para_perfilar(
    argumentos_muestra, propios = .ARGUMENTOS_PROPIOS_DBI
  ))
  # Sin proteccion, el mensaje del motor se publica entero: antes de la primera
  # lectura, y hasta la salida. Ver `.protege_mensaje_motor()`.
  .fijar_proteccion_motor(
    .protege_argumentos(argumentos_muestra), incluir_valores = incluir_valores
  )
  argumentos_muestra$columnas_opcionales <- columnas_opcionales
  argumentos_muestra$aplicabilidad <- aplicabilidad
  argumentos_muestra$sentinelas_numericos <- sentinelas_numericos
  # Estos nombres pueden terminar en consultas de la muestra o en metadatos;
  # se validan antes de preparar la tabla, para que ningun controlador reciba
  # bytes no representables aunque la tabla sea accesible.
  for (argumento in c(
    "columnas_opcionales", "columnas_codigo", "columnas_sin_ceros",
    "columnas_no_negativas", "columnas_personales"
  )) {
    .validar_nombres_argumento_dbi(
      conexion, argumentos_muestra[[argumento]], argumento
    )
  }
  if (is.list(argumentos_muestra$aplicabilidad) &&
      length(names(argumentos_muestra$aplicabilidad))) {
    .validar_nombres_argumento_dbi(
      conexion, names(argumentos_muestra$aplicabilidad), "aplicabilidad"
    )
  }
  bloque_filas <- .validar_bloque_filas_dbi(bloque_filas)
  max_celdas_muestra <- .argumento_dbi(.validar_limite_duplicados(
    max_celdas_muestra, "max_celdas_muestra"
  ))
  max_bytes_muestra <- .argumento_dbi(.validar_limite_duplicados(
    max_bytes_muestra, "max_bytes_muestra"
  ))
  max_bytes_procesamiento <- .validar_presupuesto_bytes_dbi(
    max_bytes_procesamiento, "max_bytes_procesamiento"
  )
  max_bytes_materializacion <- .validar_presupuesto_bytes_dbi(
    max_bytes_materializacion, "max_bytes_materializacion"
  )
  avisar_costo_distintos <- .validar_interruptor_aviso_dbi(
    avisar_costo_distintos, "avisar_costo_distintos"
  )
  umbral_segundos_aviso_distintos <- .validar_umbral_aviso_dbi(
    umbral_segundos_aviso_distintos, "umbral_segundos_aviso_distintos"
  )
  avisar_costo_moda <- .validar_interruptor_aviso_dbi(
    avisar_costo_moda, "avisar_costo_moda"
  )
  umbral_segundos_aviso_moda <- .validar_umbral_aviso_dbi(
    umbral_segundos_aviso_moda, "umbral_segundos_aviso_moda"
  )
  avisar_costo_mediana <- .validar_interruptor_aviso_dbi(
    avisar_costo_mediana, "avisar_costo_mediana"
  )
  umbral_segundos_aviso_mediana <- .validar_umbral_aviso_dbi(
    umbral_segundos_aviso_mediana, "umbral_segundos_aviso_mediana"
  )
  avisar_derrame_estimado <- .validar_interruptor_aviso_dbi(
    avisar_derrame_estimado, "avisar_derrame_estimado"
  )
  umbral_bytes_aviso_derrame_estimado <- .validar_umbral_aviso_dbi(
    umbral_bytes_aviso_derrame_estimado,
    "umbral_bytes_aviso_derrame_estimado"
  )
  preparacion <- .preparar_dbi(
    conexion = conexion, tabla = tabla, universo = universo,
    muestra_motor = muestra_motor, muestra = muestra,
    orden_muestra = orden_muestra,
    estrategia_mediana = estrategia_mediana, metricas = metricas,
    max_consultas = max_consultas, dialecto = dialecto,
    tamano_lote = tamano_lote,
    tamano_lote_planos = tamano_lote_planos,
    tamano_lote_distintos = tamano_lote_distintos,
    bloque_muestra = bloque_muestra, instrumentar = instrumentar, contar = FALSE,
    contar_muestreo = TRUE,
    incluir_valores = incluir_valores,
    estrategia_distintos = estrategia_distintos,
    politica_costo = politica_costo,
    umbral_cardinalidad = umbral_cardinalidad,
    max_bytes_procesamiento = max_bytes_procesamiento,
    max_bytes_materializacion = max_bytes_materializacion
  )
  # `columnas_codigo` viaja en `...` a `perfilar()` del `perfil_muestra`, y
  # se valida ACA contra las columnas de la tabla: con `bloque_muestra =
  # "solo_agregados"` no hay muestra, y un nombre mal escrito pasaba sin error.
  columnas_codigo <- .normalizar_columnas_codigo(
    argumentos_muestra[["columnas_codigo"]], preparacion$campos
  )
  # Los nombres de la tabla y de sus columnas son lo unico de la consulta que
  # el mensaje de un error del motor puede citar en claro: ver
  # `.sin_literales_motor()`.
  identificadores_previos <- .sumar_identificadores_motor(c(
    .texto_tabla_dbi(tabla), preparacion$campos
  ))
  on.exit(.fijar_identificadores_motor(identificadores_previos), add = TRUE)
  centros_previos <- .activar_centros_motor()
  on.exit(.fijar_centros_motor(centros_previos), add = TRUE)
  trazador <- .trazador_tiempos_dbi(preparacion$instrumentar)
  aviso_costo_agregados <- .aviso_costo_agregados_dbi(
    conexion, tabla, preparacion
  )
  if (!is.null(aviso_costo_agregados)) {
    .avisar_dbi(
      "lupa_aviso_costo_dbi",
      paste0(
        "El perfilado de agregados sobre la tabla completa puede ser costoso: ",
        .entero_sql_dbi(aviso_costo_agregados$filas),
        if (aviso_costo_agregados$filas == 1L) " fila estimada. Para reducir la lectura, usar `" else
          " filas estimadas. Para reducir la lectura, usar `",
        aviso_costo_agregados$sugerencia, "`."
      ),
      datos = aviso_costo_agregados
    )
  }
  if (identical(preparacion$universo, "muestra_motor") &&
      .solicita_muestra_dbi(preparacion$bloque_muestra)) {
    resultado <- .perfil_muestra_spool_dbi(
      conexion = conexion, tabla = tabla, preparacion = preparacion,
      incluir_valores = incluir_valores, bloque_filas = bloque_filas,
      max_bytes_procesamiento = max_bytes_procesamiento,
      max_bytes_materializacion = max_bytes_materializacion,
      argumentos = argumentos_muestra, trazador = trazador,
      max_celdas_muestra = max_celdas_muestra,
      max_bytes_muestra = max_bytes_muestra
    )
    # El camino del spool devuelve antes de construir el plan de agregados que
    # usa el camino SQL. Publicar el mismo plan evita que la corrida quede sin
    # la evidencia que permite contrastarla con `plan_perfilado_dbi()`.
    plan_corrida <- plan_perfilado_dbi(
      conexion = conexion, tabla = tabla,
      universo = preparacion$universo, muestra_motor = muestra_motor,
      muestra = muestra, orden_muestra = orden_muestra,
      metricas = metricas, estrategia_distintos = estrategia_distintos,
      estrategia_mediana = estrategia_mediana,
      politica_costo = politica_costo, bloque_muestra = bloque_muestra,
      max_consultas = max_consultas, dialecto = dialecto,
      incluir_valores = incluir_valores, tamano_lote = tamano_lote,
      tamano_lote_planos = tamano_lote_planos,
      tamano_lote_distintos = tamano_lote_distintos,
      instrumentar = instrumentar,
      umbral_cardinalidad = umbral_cardinalidad,
      max_celdas_muestra = max_celdas_muestra,
      max_bytes_muestra = max_bytes_muestra,
      bloque_filas = bloque_filas,
      max_bytes_procesamiento = max_bytes_procesamiento,
      max_bytes_materializacion = max_bytes_materializacion
    )
    resultado$resumen_tabla$meta$plan <- plan_corrida
    # Armar ese plan vuelve a preparar la tabla, y esas consultas viajan al
    # motor: se cuentan con las demas y el plan las anuncia
    # (ver `.plan_spool_dbi()`).
    .contar_dbi(
      preparacion$presupuesto,
      attr(plan_corrida, "consultas_emitidas", exact = TRUE) %||% 0
    )
    if (is.list(resultado$resumen_tabla$meta$consultas) &&
        !is.null(preparacion$presupuesto)) {
      resultado$resumen_tabla$meta$consultas$emitidas <-
        preparacion$presupuesto$usadas
    }
    resultado <- .declarar_afirmados_sin_valor_dbi(resultado, preparacion)
    # El spool ya materializo los datos y aplica estas guardas antes de la
    # corroboracion; se repite aqui para cubrir un adaptador que devuelva un
    # resultado armado por una via de respaldo.
    resultado <- .aplicar_guardas_salida_muestra_dbi(
      resultado, incluir_valores = incluir_valores
    )
    resultado <- .declarar_enmascaradas_dbi(resultado, preparacion)
    resultado <- .agregar_cobertura_corroboracion_dbi(
      resultado, columnas_codigo = columnas_codigo,
      columnas_opcionales = columnas_opcionales, aplicabilidad = aplicabilidad,
      sentinelas_numericos = sentinelas_numericos
    )
    resultado <- .agregar_cobertura_politicas_muestra_dbi(
      resultado, aplicabilidad = aplicabilidad,
      columnas_opcionales = columnas_opcionales,
      sentinelas_numericos = sentinelas_numericos,
      columnas_codigo = columnas_codigo,
      lectura_convertida = preparacion$lectura_convertida,
      cobertura_texto = .cobertura_texto_controlador_dbi(
        conexion, tabla, preparacion$campos, preparacion$tipos,
        .texto_anotado_desde_dbi(conexion, texto_previo)
      )
    )
    resultado <- .aplicar_guardas_salida_muestra_dbi(
      resultado, incluir_valores = incluir_valores
    )
    if (!is.null(resultado$resumen_tabla)) {
      orden_publico <- .orden_muestra_publica_dbi(
        preparacion$orden_muestra,
        resultado$resumen_tabla$meta$muestreo
      )
      resultado$resumen_tabla$meta$orden_muestra <- orden_publico
      if (!is.null(resultado$resumen_tabla$meta$muestreo)) {
        resultado$resumen_tabla$meta$muestreo$orden_muestra_aplicado <-
          orden_publico$aplicado
        resultado$resumen_tabla$meta$muestreo$motivo_orden_muestra <-
          orden_publico$motivo
      }
    }
    return(resultado)
  }
  preparacion$presupuesto$avisar_derrame_estimado <- avisar_derrame_estimado
  preparacion$presupuesto$umbral_bytes_aviso_derrame_estimado <-
    umbral_bytes_aviso_derrame_estimado
  if (!is.null(bloque_filas)) {
    resultado <- .perfilar_dbi_bloques(
      conexion = conexion, tabla = tabla, preparacion = preparacion,
      metricas = preparacion$metricas_ejecucion,
      incluir_valores = incluir_valores, bloque_filas = bloque_filas,
      max_celdas_muestra = max_celdas_muestra,
      max_bytes_muestra = max_bytes_muestra,
      argumentos = argumentos_muestra,
      argumentos_originales = argumentos_originales,
      argumentos_declarados = argumentos_declarados,
      max_bytes_procesamiento = max_bytes_procesamiento,
      metricas_publicas = preparacion$metricas
    )
    if (isTRUE(attr(resultado, "epilogo_aplicado_dbi", exact = TRUE))) {
      attr(resultado, "epilogo_aplicado_dbi") <- NULL
      return(resultado)
    }
    # Un controlador sin lectura incremental demostrada -DuckDB, o uno que no
    # esta en la matriz- deja todas las metricas `no_disponible`, a proposito:
    # no se cae en `dbGetQuery()`. Pero el motivo quedaba solo en la cobertura y
    # en `meta$fuente_bloques`, y el perfil vacio llegaba sin una condicion.
    resultado <- .declarar_afirmados_sin_valor_dbi(resultado, preparacion)
    fuente_bloques <- resultado$resumen_tabla$meta$fuente_bloques
    if (is.list(fuente_bloques) && isFALSE(fuente_bloques$disponible)) {
      .avisar_muestra_motor_dbi(
        paste0(
          "La lectura por bloques no est\u00e1 disponible con este controlador (",
          fuente_bloques$motivo, "): las m\u00e9tricas quedan `no_disponible`. ",
          "Sin `bloque_filas`, el resumen se calcula en el motor con agregados."
        ),
        datos = list(motivo = fuente_bloques$motivo)
      )
    }
    resultado <- .aplicar_guardas_salida_muestra_dbi(
      resultado, incluir_valores = incluir_valores
    )
    resultado <- .declarar_enmascaradas_dbi(resultado, preparacion)
    resultado <- .agregar_cobertura_corroboracion_dbi(
      resultado, columnas_codigo = columnas_codigo,
      columnas_opcionales = columnas_opcionales, aplicabilidad = aplicabilidad,
      sentinelas_numericos = sentinelas_numericos
    )
    return(.agregar_cobertura_politicas_muestra_dbi(
      resultado, aplicabilidad = aplicabilidad,
      columnas_opcionales = columnas_opcionales,
      sentinelas_numericos = sentinelas_numericos,
      columnas_codigo = columnas_codigo,
      lectura_convertida = preparacion$lectura_convertida,
      cobertura_texto = .cobertura_texto_controlador_dbi(
        conexion, tabla, preparacion$campos, preparacion$tipos,
        .texto_anotado_desde_dbi(conexion, texto_previo)
      )
    ))
  }
  presupuesto <- preparacion$presupuesto
  presupuesto$avisar_costo_distintos <- avisar_costo_distintos
  presupuesto$umbral_segundos_aviso_distintos <-
    umbral_segundos_aviso_distintos
  presupuesto$avisar_costo_moda <- avisar_costo_moda
  presupuesto$umbral_segundos_aviso_moda <- umbral_segundos_aviso_moda
  presupuesto$avisar_costo_mediana <- avisar_costo_mediana
  presupuesto$umbral_segundos_aviso_mediana <- umbral_segundos_aviso_mediana
  presupuesto$avisar_derrame_estimado <- avisar_derrame_estimado
  presupuesto$umbral_bytes_aviso_derrame_estimado <-
    umbral_bytes_aviso_derrame_estimado
  info_conexion <- .info_conexion_dbi(conexion)
  es_numerico <- vapply(seq_along(preparacion$campos), function(i) {
    .es_numerico_dbi(
      .atributo_columna_dbi(
        preparacion$prototipo, preparacion$campos[[i]], i
      ),
      .atributo_columna_dbi(
        preparacion$tipos, preparacion$campos[[i]], i
      ) %||% NA_character_
    )
  }, logical(1L))
  names(es_numerico) <- preparacion$campos
  tope_muestra <- .tope_muestra_plan_dbi(
    preparacion$muestra, length(preparacion$campos),
    max_celdas_muestra, max_bytes_muestra
  )
  # El mismo plan que `plan_perfilado_dbi()` (ver `.plan_sql_dbi()`), con las
  # consultas que esta corrida ya pago en lugar de las previstas. La estimacion
  # del aviso de costo ya esta en `presupuesto$usadas`; se separa para que la
  # forma del plan sea la del previo.
  aviso_catalogo <- .consultas_catalogo_aviso_dbi(conexion, tabla, preparacion)
  plan <- .plan_sql_dbi(
    conexion, preparacion, es_numerico, incluir_valores, tope_muestra,
    emitidas = presupuesto$usadas - aviso_catalogo +
      .prueba_cte_mediana_plan_dbi(
        conexion, preparacion, es_numerico, incluir_valores
      ),
    catalogo_aviso = aviso_catalogo
  )
  # Las consultas obligatorias que faltan -verificacion de orden y, cuando se
  # pidio, muestra- se reservan para que el presupuesto no se las coma.
  presupuesto$reserva <- if (.solicita_muestra_dbi(preparacion$bloque_muestra)) {
    (if (length(preparacion$orden_sql)) 2 else 1) +
      if (isTRUE(tope_muestra$requiere_sonda_bytes)) 1 else 0
  } else {
    0
  }
  # El plan ya dice cuantas consultas se van a emitir, asi que la barra avanza
  # contra un total conocido y no contra una estimacion. Se abre en el marco de
  # esta funcion para que viva lo que dure el perfilado y se cierre sola.
    .abrir_progreso_dbi(
    presupuesto, sum(plan$n_consultas_max), environment()
  )

  fuente_muestreada <- NULL
  muestreo_meta <- preparacion$muestreo
  reintentos_muestreo_sql <- 0L
  metodo_inicial_sql <- NA_character_
  metodo_reintento_sql <- NA_character_
  filas_obtenidas_muestreo_sql <- NA_real_
  motivo_filas_obtenidas_muestreo_sql <- NA_character_
  motivo_fuente_muestreada_sql <- NA_character_
  motivo_reintento_sql <- NA_character_
  muestreo_publico <- if (is.null(preparacion$muestreo)) {
    NULL
  } else {
    .publicar_muestreo_dbi(preparacion$muestreo, n_total = preparacion$n_total)
  }
  # `NEWID()` es un respaldo de la fuente muestreada, no una puerta para
  # ejecutar primero un ordenamiento completo y decidir despues si costaba
  # demasiado. `n_total` se conto arriba para los caminos aleatorios; la
  # politica queda en el presupuesto para que estrategia, fila y metadata
  # compartan exactamente la misma decision.
  if (identical(preparacion$universo, "muestra_motor") &&
      !is.null(preparacion$muestreo) &&
      identical(preparacion$muestreo$candidato$nombre, "random_limit") &&
      any(vapply(
        preparacion$muestreo$candidato$funciones,
        function(funcion) identical(funcion$nombre, "newid"),
        logical(1L)
      )) &&
      "mediana" %in% preparacion$metricas_ejecucion &&
      isTRUE(incluir_valores) && any(preparacion$es_numerico)) {
    pendientes_newid <- sum(preparacion$es_numerico)
    guardia_newid <- .evaluar_guardia_newid_dbi(
      preparacion$n_total, preparacion$muestra_motor, pendientes_newid
    )
    presupuesto$guardia_newid <- guardia_newid
    if (!isTRUE(guardia_newid$aceptado)) {
      if (isTRUE(avisar_costo_mediana)) {
        cli::cli_alert_warning(.cli_literal(.marcar_para_exhibir(paste0(
          "Muestra muestreada no disponible: ", guardia_newid$motivo,
          ". Proyecci\u00f3n NEWID: ",
          if (is.finite(guardia_newid$proyeccion_newid_ms)) {
            formatC(guardia_newid$proyeccion_newid_ms,
                    format = "f", digits = 1)
          } else "sin dato",
          " ms; n_total = ", .entero_sql_dbi(guardia_newid$n_total),
          ", fracci\u00f3n = ", formatC(guardia_newid$fraccion,
                                    format = "f", digits = 3), "."
        ))))
      }
      preparacion$muestreo$disponible <- FALSE
      preparacion$muestreo$motivo <- guardia_newid$motivo
      muestreo_publico <- .publicar_muestreo_dbi(
        preparacion$muestreo, n_total = preparacion$n_total
      )
    }
  }
  tabla_metricas_sql <- preparacion$tabla_sql
  # Si alguna columna se lee convertida -`money` y `real` de PostgreSQL, ver
  # `.lectura_convertida_dbi()`-, los agregados se calculan sobre esa misma
  # lectura y no sobre el valor crudo: el resumen SQL y la muestra describen el
  # mismo dato. Bajo `muestra_motor` la subconsulta muestreada ya proyecta la
  # lectura convertida.
  if (NROW(preparacion$lectura_convertida)) {
    tabla_metricas_sql <- paste0(
      "(SELECT ", paste(preparacion$campos_sql_proyeccion, collapse = ", "),
      " FROM ", preparacion$tabla_sql, ")",
      preparacion$dialecto$alias_tabla("lupa_lectura")
    )
  }
  if (identical(preparacion$universo, "muestra_motor") &&
      !is.null(preparacion$muestreo) &&
      isTRUE(preparacion$muestreo$disponible)) {
    captura_fuente <- .capturar_fuente_muestreada_dbi(
      preparacion$tabla_sql, preparacion$campos_sql_proyeccion,
      preparacion$muestra_motor,
      preparacion$n_total, preparacion$dialecto, preparacion$muestreo
    )
    fuente_muestreada <- captura_fuente$fuente
    if (is.null(fuente_muestreada)) {
      motivo_fuente_muestreada_sql <- captura_fuente$motivo
      if (length(motivo_fuente_muestreada_sql) != 1L ||
          is.na(motivo_fuente_muestreada_sql) ||
          !nzchar(motivo_fuente_muestreada_sql)) {
        motivo_fuente_muestreada_sql <-
          "capacidad_no_aceptada:fuente_muestreada"
      }
      preparacion$muestreo$disponible <- FALSE
      preparacion$muestreo$motivo <- motivo_fuente_muestreada_sql
      motivo_filas_obtenidas_muestreo_sql <- preparacion$muestreo$motivo
      muestreo_publico <- .publicar_muestreo_dbi(
        preparacion$muestreo, n_total = preparacion$n_total
      )
    } else {
      motivo_filas_obtenidas_muestreo_sql <- NA_character_
      tabla_metricas_sql <- paste0(
        "(", fuente_muestreada$sql, ")",
        preparacion$dialecto$alias_tabla("lupa_muestra")
      )
      muestreo_meta <- c(
        preparacion$muestreo,
        list(
          metodo = fuente_muestreada$metodo,
          descripcion = fuente_muestreada$descripcion,
          fraccion = fuente_muestreada$fraccion,
          tamano_muestra = fuente_muestreada$filas_solicitadas,
          sql = fuente_muestreada$sql
        )
      )
      muestreo_publico <- .publicar_muestreo_dbi(
        preparacion$muestreo, fuente_muestreada, preparacion$n_total
      )
      metodo_inicial_sql <- fuente_muestreada$metodo
    }
  }
  # La fuente contiene `TABLESAMPLE`, por lo que contarla aqui y volver a
  # referirla mas abajo no cuenta las mismas filas: cada sentencia puede
  # obtener otra muestra. El `COUNT(*)` que acompana al primer agregado es
  # la medicion que decide si hace falta reintentar y que se publica; el
  # reintento, si corresponde, se arma despues de esa medicion y vuelve a
  # ejecutar el agregado sobre su propia fuente.
  muestra_corta_sql <- FALSE
  if (identical(preparacion$universo, "muestra_motor") &&
      !is.null(preparacion$muestreo) &&
      !isTRUE(preparacion$muestreo$disponible)) {
    # Mantener una relacion vacia permite que el resumen conserve su forma y
    # el conteo del universo, pero evita que un rechazo de capacidad vuelva a
    # caer accidentalmente sobre `tabla_sql` completa.
    tabla_metricas_sql <- paste0(
      "(SELECT ", paste(preparacion$campos_sql_proyeccion, collapse = ", "),
      " FROM ", preparacion$tabla_sql, " WHERE 1 = 0)",
      preparacion$dialecto$alias_tabla("lupa_muestra")
    )
  }

  campos_consolidados <- preparacion$campos
  # `tabla_metricas_sql` ya contiene la proyeccion convertida cuando hubo una
  # lectura especial. Sus columnas conservan los nombres originales; volver a
  # usar la expresion de lectura aqui aplicaria `float8send()` sobre el NUMERIC
  # ya materializado y hace fallar el fetch de los agregados.
  campos_sql_consolidados <- if (NROW(preparacion$lectura_convertida)) {
    vapply(preparacion$campos, function(campo) {
      .citar_identificador_dbi(conexion, campo)
    }, character(1L), USE.NAMES = FALSE)
  } else {
    preparacion$campos_sql
  }
  es_numerico_consolidados <- preparacion$es_numerico
  motivos_resumen <- preparacion$esquema$motivos
  cobertura_aislamiento_muestra <- .cobertura_dbi_vacia()
  if (identical(preparacion$universo, "muestra_motor") &&
      identical(preparacion$bloque_muestra, "solo_agregados") &&
      !is.null(fuente_muestreada)) {
    sondear_muestra <- function(indices) {
      captura <- .capturar_fuente_muestreada_dbi(
        preparacion$tabla_sql, preparacion$campos_sql_proyeccion[indices],
        preparacion$muestra_motor, preparacion$n_total, preparacion$dialecto,
        preparacion$muestreo
      )
      fuente <- captura$fuente
      if (is.null(fuente) && length(captura$motivo) == 1L &&
          !is.na(captura$motivo) && nzchar(captura$motivo)) {
        motivo_fuente_muestreada_sql <<- captura$motivo
      }
      if (is.null(fuente)) return(FALSE)
      consulta <- .consultar_dbi(
        conexion, fuente$sql, preparacion$presupuesto, filas = fuente$filas,
        etapa = "sonda_lectura_muestra"
      )
      isTRUE(consulta$ok)
    }
    consulta_muestra <- .consultar_dbi(
      conexion, fuente_muestreada$sql, preparacion$presupuesto,
      filas = fuente_muestreada$filas, etapa = "lectura_muestra"
    )
    if (!isTRUE(consulta_muestra$ok) && length(preparacion$campos) > 1L) {
      hay_saldo_muestra <- function() {
        is.null(preparacion$presupuesto) ||
          .saldo_dbi(preparacion$presupuesto) >= 1
      }
      saldo_muestra <- if (is.null(preparacion$presupuesto)) Inf else
        .saldo_dbi(preparacion$presupuesto)
      tope_muestra <- min(
        2L * length(preparacion$campos), .TOPE_SONDAS_DESCARTE_DBI,
        max(0, floor(saldo_muestra / 2))
      )
      aislamiento_muestra <- .aislar_ilegibles_dbi(
        sondear_muestra, hay_saldo_muestra, length(preparacion$campos),
        tope_muestra
      )
      culpables_muestra <- aislamiento_muestra$culpables
      if (length(culpables_muestra) &&
          length(culpables_muestra) < length(preparacion$campos)) {
        quedan_muestra <- setdiff(seq_along(preparacion$campos), culpables_muestra)
        captura_fuente_legible <- .capturar_fuente_muestreada_dbi(
          preparacion$tabla_sql,
          preparacion$campos_sql_proyeccion[quedan_muestra],
          preparacion$muestra_motor, preparacion$n_total, preparacion$dialecto,
          preparacion$muestreo
        )
        fuente_legible <- captura_fuente_legible$fuente
        if (is.null(fuente_legible) &&
            length(captura_fuente_legible$motivo) == 1L &&
            !is.na(captura_fuente_legible$motivo) &&
            nzchar(captura_fuente_legible$motivo)) {
          motivo_fuente_muestreada_sql <- captura_fuente_legible$motivo
        }
        if (!is.null(fuente_legible)) {
          campos_consolidados <- preparacion$campos[quedan_muestra]
          campos_sql_consolidados <- if (NROW(preparacion$lectura_convertida)) {
            vapply(preparacion$campos[quedan_muestra], function(campo) {
              .citar_identificador_dbi(conexion, campo)
            }, character(1L), USE.NAMES = FALSE)
          } else {
            preparacion$campos_sql[quedan_muestra]
          }
          es_numerico_consolidados <- preparacion$es_numerico[quedan_muestra]
          motivos_aislados <- paste(
            "La lectura de la muestra fall\u00f3; la columna se aisl\u00f3 por descarte",
            "sobre las mismas filas y se dej\u00f3 fuera de los agregados."
          )
          motivos_resumen[preparacion$campos[culpables_muestra]] <-
            motivos_aislados
          tabla_metricas_sql <- paste0(
            "(", fuente_legible$sql, ")",
            preparacion$dialecto$alias_tabla("lupa_muestra_legible")
          )
          cobertura_aislamiento_muestra <- .registro_cobertura_dbi(
            "resumen_tabla", paste(preparacion$campos[culpables_muestra], collapse = ", "),
            "alcance_distinto",
            paste(
              motivos_aislados, "La muestra queda disponible para las dem\u00e1s",
              "columnas; `n` sigue describiendo el universo declarado."
            ),
            "Corregir la vista para incluir la columna; mientras tanto, sus m\u00e9tricas quedan no disponibles."
          )
        }
      }
    }
  }

  campos_todos <- unique(c(preparacion$campos, preparacion$esquema$ilegibles))
  consultas_antes_resumen <- presupuesto$usadas
  ejecutar_resumen <- function(fuente_sql, fuente, muestreo) {
    .resumen_tabla_dbi(
      conexion, tabla, preparacion$tabla_sql, campos_todos,
      preparacion$prototipo, preparacion$n_total, preparacion$sql_conteo,
      info_conexion, dialecto = preparacion$dialecto,
      metricas = preparacion$metricas, presupuesto = presupuesto,
      metricas_ejecucion = preparacion$metricas_ejecucion,
      incluir_valores = incluir_valores, tipos_declarados = preparacion$tipos,
      tipos_motor = preparacion$esquema$tipos_motor,
      motivos_ilegibles = motivos_resumen,
      universo = preparacion$universo,
      estrategia_mediana = preparacion$estrategia_mediana,
      tabla_metricas_sql = fuente_sql,
      muestreo = muestreo, aproximaciones = preparacion$aproximaciones,
      tamano_muestra = if (is.null(fuente)) NA_real_ else
        fuente$filas_solicitadas,
      fraccion_muestra = if (is.null(fuente)) NA_real_ else
        fuente$fraccion,
      campos_consolidados = campos_consolidados,
      campos_sql_consolidados = campos_sql_consolidados,
      es_numerico_consolidados = es_numerico_consolidados,
      infinitos_como_numeric = preparacion$infinitos_como_numeric,
      columnas_float8_numeric = preparacion$columnas_float8_numeric,
      tamano_lote_planos = preparacion$tamano_lote_planos,
      tamano_lote_distintos = preparacion$tamano_lote_distintos,
      conteo = preparacion$conteo,
      moda_guardian = preparacion$moda_guardian,
      mediana_consolidada = preparacion$mediana_consolidada,
      mediana_escalar = preparacion$mediana_escalar,
      mediana_cte_ventana = preparacion$mediana_cte_ventana,
      mediana_cte_ventana_motivo = preparacion$mediana_cte_ventana_motivo,
      fuentes_cardinalidad_costo = preparacion$fuentes_cardinalidad_costo,
      estrategia_distintos = preparacion$estrategia_distintos,
      politica_costo = preparacion$politica_costo
    )
  }
  resumen <- ejecutar_resumen(tabla_metricas_sql, fuente_muestreada,
                              muestreo_publico)

  # La primera consulta de agregados lleva `COUNT(*) AS n_total_consulta`.
  # Usar ese denominador evita contar una segunda evaluacion de TABLESAMPLE.
  # Si esa misma consulta revela una muestra corta, se decide el reintento
  # ahora y se vuelve a ejecutar el resumen completo sobre la fuente elegida.
  if (identical(preparacion$universo, "muestra_motor") &&
      identical(preparacion$bloque_muestra, "solo_agregados") &&
      !is.null(fuente_muestreada)) {
    filas_del_resumen <- function(objeto) {
      valor <- suppressWarnings(as.numeric(
        objeto$meta$filas_obtenidas_muestra
      ))
      if (length(valor) == 1L && is.finite(valor)) valor else NA_real_
    }
    # Lo efectivo es lo pedido acotado por el total de la tabla. Las formas de
    # cantidad fija -`RESERVOIR (n ROWS)` de DuckDB, el orden pseudoaleatorio
    # con limite- no cuentan la tabla antes, porque no lo necesitan para
    # escribirse, y con el total desconocido lo efectivo era lo pedido: mil
    # filas de una tabla de cincuenta salian "cortas", se reintentaba y se
    # avisaba una degradacion sobre una muestra que es la tabla entera. En
    # DuckDB el reintento ademas fallaba y dejaba toda la tabla
    # `no_disponible`. Pero esta misma consulta ya trajo el total de la tabla
    # (`resumen$meta$filas`, el que gobierna todo desde abajo): se usa ese.
    total_muestreo <- if (is.finite(.numero_dbi(preparacion$n_total))) {
      .numero_dbi(preparacion$n_total)
    } else {
      .numero_dbi(resumen$meta$filas)
    }
    pedido_muestreo <- min(
      as.numeric(preparacion$muestra_motor),
      if (is.finite(total_muestreo)) total_muestreo else
        as.numeric(preparacion$muestra_motor)
    )
    filas_obtenidas_muestreo_sql <- filas_del_resumen(resumen)
    motivo_filas_obtenidas_muestreo_sql <- if (
      is.finite(filas_obtenidas_muestreo_sql)
    ) NA_character_ else "No se pudo contar la muestra en el agregado."
    muestra_corta_sql <- pedido_muestreo > 0 &&
      is.finite(filas_obtenidas_muestreo_sql) &&
      filas_obtenidas_muestreo_sql < pedido_muestreo / 2
    if (isTRUE(muestra_corta_sql) && grepl(
      "^tablesample_", as.character(fuente_muestreada$metodo)
    )) {
      candidatos <- .candidatos_muestreo_dbi(
        conexion, preparacion$dialecto,
        tipo_objeto = preparacion$tipo_objeto
      )
      objetivo_reintento <- min(
        as.numeric(preparacion$muestra_motor) * 2,
        if (is.finite(preparacion$n_total)) preparacion$n_total else
          as.numeric(preparacion$muestra_motor) * 2
      )
      decision <- .alternativa_muestreo_reintento_dbi(
        candidatos, fuente_muestreada$metodo,
        .senas_conexion_dbi(conexion), preparacion$n_total,
        objetivo_reintento, 1L
      )
      alternativa <- decision$candidato
      motivo_reintento_sql <- decision$motivo
      if (!is.null(alternativa)) {
        metodo_reintento_sql <- alternativa$nombre
        resolucion_reintento <- preparacion$muestreo
        resolucion_reintento$candidato <- alternativa
        captura_reintento <- .capturar_fuente_muestreada_dbi(
          preparacion$tabla_sql, preparacion$campos_sql_proyeccion,
          objetivo_reintento, preparacion$n_total, preparacion$dialecto,
          resolucion_reintento
        )
        fuente_reintento <- captura_reintento$fuente
        if (is.null(fuente_reintento) &&
            length(captura_reintento$motivo) == 1L &&
            !is.na(captura_reintento$motivo) &&
            nzchar(captura_reintento$motivo)) {
          motivo_reintento_sql <- captura_reintento$motivo
        }
        if (!is.null(fuente_reintento)) {
          limite_reintento <- min(
            as.numeric(preparacion$muestra_motor),
            if (is.finite(preparacion$n_total)) preparacion$n_total else
              as.numeric(preparacion$muestra_motor)
          )
          envoltura_reintento <- paste0(
            "SELECT * FROM (", fuente_reintento$sql, ")",
            preparacion$dialecto$alias_tabla("lupa_reintento")
          )
          acotada_reintento <- preparacion$dialecto$limitar(
            envoltura_reintento, limite_reintento, 0
          )
          if (!is.null(acotada_reintento)) {
            fuente_reintento$sql <- acotada_reintento
            fuente_reintento$filas_solicitadas <- limite_reintento
            fuente_reintento$filas_pedidas <- limite_reintento
          }
          reintentos_muestreo_sql <- 1L
          fuente_muestreada <- fuente_reintento
          tabla_metricas_sql <- paste0(
            "(", fuente_muestreada$sql, ")",
            preparacion$dialecto$alias_tabla("lupa_muestra")
          )
          muestreo_publico <- .publicar_muestreo_dbi(
            resolucion_reintento, fuente_reintento,
            preparacion$n_total
          )
          muestreo_meta <- c(
            resolucion_reintento,
            list(
              metodo = fuente_reintento$metodo,
              descripcion = fuente_reintento$descripcion,
              fraccion = fuente_reintento$fraccion,
              tamano_muestra = fuente_reintento$filas_solicitadas,
              sql = fuente_reintento$sql
            )
          )
          resumen <- ejecutar_resumen(
            tabla_metricas_sql, fuente_muestreada, muestreo_publico
          )
          filas_obtenidas_muestreo_sql <- filas_del_resumen(resumen)
          motivo_filas_obtenidas_muestreo_sql <- if (
            is.finite(filas_obtenidas_muestreo_sql)
          ) NA_character_ else "No se pudo contar la muestra en el agregado."
          muestra_corta_sql <- pedido_muestreo > 0 &&
            is.finite(filas_obtenidas_muestreo_sql) &&
            filas_obtenidas_muestreo_sql < pedido_muestreo / 2
        }
      }
    }
  }
  if (identical(preparacion$universo, "muestra_motor") &&
      is.null(fuente_muestreada) && !is.null(muestreo_publico) &&
      !is.finite(filas_obtenidas_muestreo_sql) &&
      (is.na(motivo_filas_obtenidas_muestreo_sql) ||
       !nzchar(motivo_filas_obtenidas_muestreo_sql))) {
    motivo_filas_obtenidas_muestreo_sql <- if (
      !is.null(preparacion$muestreo) &&
      length(preparacion$muestreo$motivo) == 1L &&
      !is.na(preparacion$muestreo$motivo)
    ) as.character(preparacion$muestreo$motivo) else {
      "No se pudo construir la fuente de la muestra."
    }
    muestreo_publico$motivo_filas_obtenidas <-
      motivo_filas_obtenidas_muestreo_sql
  }
  if (length(motivo_fuente_muestreada_sql) == 1L &&
      !is.na(motivo_fuente_muestreada_sql) &&
      nzchar(motivo_fuente_muestreada_sql) &&
      (is.na(motivo_reintento_sql) || !nzchar(motivo_reintento_sql))) {
    motivo_reintento_sql <- motivo_fuente_muestreada_sql
  }
  if (is.null(fuente_muestreada) &&
      length(motivo_fuente_muestreada_sql) == 1L &&
      !is.na(motivo_fuente_muestreada_sql) &&
      nzchar(motivo_fuente_muestreada_sql)) {
    motivo_filas_obtenidas_muestreo_sql <- motivo_fuente_muestreada_sql
    if (!is.null(muestreo_publico)) {
      muestreo_publico$motivo_filas_obtenidas <-
        motivo_filas_obtenidas_muestreo_sql
    }
  }
  if (identical(preparacion$universo, "muestra_motor") &&
      identical(preparacion$bloque_muestra, "solo_agregados") &&
      !is.null(muestreo_publico)) {
    muestreo_publico$reintentos <- reintentos_muestreo_sql
    muestreo_publico$metodo_inicial <- metodo_inicial_sql
    muestreo_publico$metodo_reintento <- metodo_reintento_sql
    muestreo_publico$motivo_reintento <- motivo_reintento_sql
    muestreo_publico$filas_obtenidas <- filas_obtenidas_muestreo_sql
    muestreo_publico$motivo_filas_obtenidas <-
      motivo_filas_obtenidas_muestreo_sql
    muestreo_publico$fraccion_solicitada <-
      .fraccion_solicitada_muestreo_dbi(
        preparacion$muestra_motor, preparacion$n_total
      )
    muestreo_publico$fraccion <- .fraccion_muestreo_dbi(
      filas_obtenidas_muestreo_sql, preparacion$n_total
    )
  }
  if (nrow(cobertura_aislamiento_muestra)) {
    resumen$cobertura <- rbind(
      resumen$cobertura, cobertura_aislamiento_muestra
    )
    rownames(resumen$cobertura) <- NULL
  }
  derrame <- .publicar_derrame_dbi(presupuesto)
  resumen$sql <- .adjuntar_derrame_sql_dbi(
    resumen$sql, presupuesto$derrame
  )
  resumen$meta$derrame <- derrame
  resumen$meta$estimacion_derrame_moda <- presupuesto$estimacion_derrame_moda
  resumen$meta$estimacion_derrame_mediana <- presupuesto$estimacion_derrame_mediana
  resumen$meta$costo_distintos <- presupuesto$proyeccion_distintos
  resumen$meta$costo_moda <- presupuesto$proyeccion_moda
  resumen$meta$costo_mediana <- presupuesto$proyeccion_mediana
  if (identical(preparacion$politica_costo$nombre, "por_cardinalidad")) {
    plan <- .plan_sql_dbi(
      conexion, preparacion, es_numerico, incluir_valores,
      tope_muestra, emitidas = consultas_antes_resumen,
      catalogo_aviso = aviso_catalogo,
      decisiones_costo_resueltas = resumen$meta$decisiones_costo
    )
  }
  attr(plan, "moda_guardian") <- .publicar_moda_guardian_dbi(
    preparacion$moda_guardian_resolucion
  )
  attr(plan, "estimacion_derrame") <- preparacion$estimacion_derrame
  attr(plan, "estimacion_derrame_moda") <- preparacion$estimacion_derrame_moda
  attr(plan, "estimacion_derrame_mediana") <- preparacion$estimacion_derrame_mediana
  # En la corrida el conteo sale de la primera consulta de agregados. Desde
  # aca es el total que gobierna el denominador, la muestra y toda la metadata;
  # no se conserva el valor desconocido de la preparacion.
  preparacion$n_total <- resumen$meta$filas
  if (identical(preparacion$universo, "muestra_motor")) {
    if (!is.null(fuente_muestreada)) {
      fuente_muestreada$filas_solicitadas <- min(
        as.numeric(fuente_muestreada$filas_solicitadas),
        .numero_dbi(preparacion$n_total)
      )
      fuente_muestreada$fraccion <- .fraccion_muestreo_dbi(
        fuente_muestreada$filas_solicitadas, preparacion$n_total
      )
      muestreo_meta <- c(
        preparacion$muestreo,
        list(
          metodo = fuente_muestreada$metodo,
          descripcion = fuente_muestreada$descripcion,
          fraccion = fuente_muestreada$fraccion,
          tamano_muestra = fuente_muestreada$filas_solicitadas,
          sql = fuente_muestreada$sql
        )
      )
      if (identical(preparacion$bloque_muestra, "solo_agregados") &&
          reintentos_muestreo_sql > 0L && !is.null(muestreo_publico)) {
        # El reintento ya publico sus dos metodos y sus filas. La republicacion
        # con `preparacion$muestreo` perdia esos campos y volvia a dejar las
        # filas obtenidas en cero despues de armar el resumen.
        muestreo_publico$universo <- preparacion$n_total
        muestreo_publico$sql <- fuente_muestreada$sql
        muestreo_publico$tamano_muestra <- fuente_muestreada$filas_solicitadas
        muestreo_publico$filas_solicitadas <- fuente_muestreada$filas_solicitadas
        muestreo_publico$filas_pedidas <- fuente_muestreada$filas_pedidas
        muestreo_publico$filas_obtenidas <- filas_obtenidas_muestreo_sql
        muestreo_publico$motivo_filas_obtenidas <-
          motivo_filas_obtenidas_muestreo_sql
        muestreo_publico$fraccion <- .fraccion_muestreo_dbi(
          filas_obtenidas_muestreo_sql, preparacion$n_total
        )
      } else {
        muestreo_publico <- .publicar_muestreo_dbi(
          preparacion$muestreo, fuente_muestreada, preparacion$n_total
        )
      }
      if (identical(preparacion$bloque_muestra, "solo_agregados") &&
          !is.null(muestreo_publico)) {
        muestreo_publico$reintentos <- reintentos_muestreo_sql
        muestreo_publico$metodo_inicial <- metodo_inicial_sql
        muestreo_publico$metodo_reintento <- metodo_reintento_sql
        muestreo_publico$motivo_reintento <- motivo_reintento_sql
        muestreo_publico$filas_obtenidas <- filas_obtenidas_muestreo_sql
        muestreo_publico$motivo_filas_obtenidas <-
          motivo_filas_obtenidas_muestreo_sql
        muestreo_publico$fraccion_solicitada <-
          .fraccion_solicitada_muestreo_dbi(
            preparacion$muestra_motor, preparacion$n_total
          )
        muestreo_publico$fraccion <- .fraccion_muestreo_dbi(
          filas_obtenidas_muestreo_sql, preparacion$n_total
        )
      }
    } else {
      muestreo_publico <- .publicar_muestreo_dbi(
        if (is.null(preparacion$muestreo)) {
          list(disponible = FALSE, candidato = NULL, sondas = character(),
               motivo = "No se resolvi\u00f3 una capacidad de muestreo del motor.")
        } else preparacion$muestreo,
        n_total = preparacion$n_total
      )
      if (identical(preparacion$bloque_muestra, "solo_agregados") &&
          !is.null(muestreo_publico)) {
        muestreo_publico$reintentos <- reintentos_muestreo_sql
        muestreo_publico$metodo_inicial <- metodo_inicial_sql
        muestreo_publico$metodo_reintento <- metodo_reintento_sql
        muestreo_publico$motivo_reintento <- motivo_reintento_sql
        muestreo_publico$filas_obtenidas <- filas_obtenidas_muestreo_sql
        muestreo_publico$motivo_filas_obtenidas <-
          motivo_filas_obtenidas_muestreo_sql
        muestreo_publico$fraccion_solicitada <-
          .fraccion_solicitada_muestreo_dbi(
            preparacion$muestra_motor, preparacion$n_total
          )
        muestreo_publico$fraccion <- .fraccion_muestreo_dbi(
          filas_obtenidas_muestreo_sql, preparacion$n_total
        )
      }
    }
  }
  resumen$meta$sql_esquema <- preparacion$esquema$sql
  resumen$meta$universo <- preparacion$universo
  resumen$meta$estrategia_mediana <- .publicar_estrategia_mediana_dbi(
    preparacion
  )
  resumen$meta$metricas <- preparacion$metricas
  resumen$meta$metricas_ejecucion <- preparacion$metricas_ejecucion
  resumen$meta$politica_costo <- preparacion$politica_costo
  resumen$meta$estrategia_distintos <- .publicar_estrategia_distintos_dbi(
    preparacion$estrategia_distintos
  )
  resumen$meta$fuente_cardinalidad_costo <-
    preparacion$fuentes_cardinalidad_costo
  resumen$meta$moda_guardian <- .publicar_moda_guardian_dbi(
    preparacion$moda_guardian_resolucion
  )
  resumen$meta$mediana_consolidada <-
    preparacion$mediana_consolidada_resolucion
  resumen$meta$mediana_escalar <-
    .publicar_mediana_escalar_dbi(preparacion$mediana_escalar_resolucion)
  # La salida del catalogo sigue la misma ruta `meta$clave` que la salida en
  # memoria. Se conserva completa para no perder fuente, motivo ni estados.
  resumen$meta$clave <- preparacion$catalogo_cardinalidad
  resumen$meta$incluir_valores <- incluir_valores
  resumen$meta$max_celdas_muestra <- max_celdas_muestra
  resumen$meta$max_bytes_muestra <- max_bytes_muestra
  resumen$meta$tamano_lote <- preparacion$tamano_lote
  resumen$meta$tamano_lote_funciono <- presupuesto$tamano_lote_funciono
  resumen$meta$tamano_lote_planos <- preparacion$tamano_lote_planos
  resumen$meta$tamano_lote_distintos <- preparacion$tamano_lote_distintos
  resumen$meta$tamano_lote_planos_funciono <-
    presupuesto$tamano_lote_planos_funciono
  resumen$meta$tamano_lote_distintos_funciono <-
    presupuesto$tamano_lote_distintos_funciono
  resumen$meta$instrumentacion <- list(
    activa = isTRUE(preparacion$instrumentar),
    unidad_duracion = "ms",
    reloj = "Sys.time()",
    cpu = "proc.time()[['user.self']] + proc.time()[['sys.self']]",
    unidad_cpu = "ms",
    precision = paste(
      "La precisi\u00f3n efectiva es la de la plataforma; los intervalos que el",
      "reloj no puede resolver quedan en NA y nunca se publican como cero.",
      "El CPU queda en NA si proc.time() no pudo leerse."
    ),
    apagable = TRUE
  )
  attr(plan, "muestra") <- if (.solicita_muestra_dbi(
    preparacion$bloque_muestra
  )) preparacion$muestra else NA_real_
  if (identical(preparacion$bloque_muestra, "solo_agregados")) {
    attr(plan, "bloque_muestra") <- preparacion$bloque_muestra
  }
  resumen$meta$plan <- plan
  if (identical(preparacion$universo, "muestra_motor") &&
      !.solicita_muestra_dbi(preparacion$bloque_muestra)) {
    # La muestra del motor sigue gobernando los agregados SQL, pero el bloque
    # de filas no se pidio: no hay seleccion para materializar ni filas vistas
    # por el cliente. El estado explicito evita confundir "no solicitado" con
    # un spool que se abrio y luego se descarto.
    resumen$meta$materializacion <- list(
      pagado = FALSE, estado = "no_solicitado", externo = FALSE,
      n_filas = 0, bytes = 0, checksum = NA_character_,
      motivo = paste(
        "No se materializ\u00f3 la muestra: `bloque_muestra = \"solo_agregados\"`",
        "solicit\u00f3 \u00fanicamente los agregados SQL."
      )
    )
    resumen$meta$bloques <- list(
      solicitados = 0L, recorridos = 0L, filas_vistas = 0,
      fetches = 0L, materializacion = "no_solicitado"
    )
  }
  resumen$meta$dialecto <- list(
    nombre = preparacion$dialecto$nombre,
    descripcion = preparacion$dialecto$descripcion,
    motivo = preparacion$resolucion$motivo,
    declarado = preparacion$resolucion$declarado,
    sondas = preparacion$resolucion$sondas
  )
  if (identical(preparacion$estrategia_mediana, "aproximada_motor")) {
    resumen$meta$aproximaciones <- lapply(
      preparacion$aproximaciones_resolucion, .publicar_aproximacion_dbi
    )
  }
  cobertura <- .cobertura_dbi_vacia()
  cobertura <- rbind(
    cobertura,
    .cobertura_cambio_entre_consultas_dbi(
      resumen$columnas, resumen$sql
    )
  )
  if (nrow(cobertura_aislamiento_muestra)) {
    cobertura <- rbind(cobertura, cobertura_aislamiento_muestra)
  }
  if (identical(preparacion$universo, "muestra_motor") &&
      identical(preparacion$bloque_muestra, "solo_agregados") &&
      (reintentos_muestreo_sql > 0L || muestra_corta_sql)) {
    filas_cobertura <- filas_obtenidas_muestreo_sql
    estado_muestreo <- if (isTRUE(muestra_corta_sql)) "degradado" else "medido"
    motivo_muestreo <- if (isTRUE(muestra_corta_sql)) {
      paste0(
        "La muestra final contiene ", .entero_sql_dbi(filas_cobertura),
        if (filas_cobertura == 1L) " fila y qued\u00f3 por debajo de la mitad de lo pedido." else
          " filas y qued\u00f3 por debajo de la mitad de lo pedido."
      )
    } else {
      paste0(
        "La muestra inicial fue corta y el reintent\u00f3 con `",
        as.character(muestreo_publico$metodo), "` alcanz\u00f3 el tama\u00f1o pedido."
      )
    }
    cobertura <- rbind(cobertura, .registro_cobertura_dbi(
      "resumen_tabla", .texto_tabla_dbi(tabla), estado_muestreo,
      motivo_muestreo,
      "Revisar `meta$muestreo` para los m\u00e9todos y filas de cada intento.",
      muestreo_publico$sql
    ))
  }
  if (identical(preparacion$universo, "muestra_motor")) {
    if (!is.null(muestreo_publico) &&
        length(resumen$meta$filas_obtenidas_muestra) == 1L &&
        is.finite(resumen$meta$filas_obtenidas_muestra) &&
        (is.null(muestreo_publico$filas_obtenidas) ||
         is.na(muestreo_publico$filas_obtenidas))) {
      muestreo_publico$filas_obtenidas <-
        resumen$meta$filas_obtenidas_muestra
      muestreo_publico$motivo_filas_obtenidas <- NA_character_
    }
    if (is.null(fuente_muestreada) && !is.null(muestreo_publico) &&
        length(motivo_fuente_muestreada_sql) == 1L &&
        !is.na(motivo_fuente_muestreada_sql) &&
        nzchar(motivo_fuente_muestreada_sql)) {
      muestreo_publico$motivo_filas_obtenidas <-
        motivo_fuente_muestreada_sql
    }
    resumen$meta$muestreo <- muestreo_publico
    resumen$meta$orden_muestra <- .orden_muestra_publica_dbi(
      preparacion$orden_muestra, resumen$meta$muestreo
    )
    if (!is.null(presupuesto$guardia_newid) &&
        !is.null(resumen$meta$muestreo)) {
      resumen$meta$muestreo$politica_newid <- presupuesto$guardia_newid
    }
    if (is.null(fuente_muestreada)) {
      cobertura <- rbind(cobertura, .registro_cobertura_dbi(
        "resumen_tabla", .texto_tabla_dbi(tabla), "no_disponible",
        if (is.null(preparacion$muestreo)) {
          "No se pudo resolver una capacidad de muestreo del motor."
        } else {
          preparacion$muestreo$motivo
        },
        paste(
          "El universo `muestra_motor` no reemplaza la estimaci\u00f3n por un c\u00e1lculo",
          "sobre la tabla completa. Usar `universo = \"tabla_completa\"` o un",
          "adaptador compatible."
        ),
        NA_character_
      ))
    }
  }
  # Un conteo por encima de 2^53 no sobrevive al doble. Se declara en vez de
  # afirmar una exactitud que no hay.
  resumen$meta$conteo_exacto <- .conteo_exacto_dbi(preparacion$n_total)

  if (length(preparacion$esquema$ilegibles)) {
    cobertura <- rbind(cobertura, .cobertura_ilegibles_dbi(preparacion$esquema))
  }
  if (!preparacion$lista_campos$origen %in% c("dbListFields", "catalogo")) {
    cobertura <- rbind(cobertura, .registro_cobertura_dbi(
      "resumen_tabla", .texto_tabla_dbi(tabla), "degradado",
      preparacion$lista_campos$motivo,
      "No hace falta hacer nada: los nombres se obtuvieron por otra v\u00eda.",
      NA_character_
    ))
  }

  presupuesto$reserva <- 0
  bloque <- if (.solicita_muestra_dbi(preparacion$bloque_muestra)) {
    .bloque_muestra_dbi(
      conexion, tabla, preparacion$tabla_sql, preparacion$campos,
      preparacion$campos_sql_proyeccion, preparacion$muestra,
      if (identical(preparacion$universo, "muestra_motor")) {
        preparacion$muestra_motor
      } else {
        preparacion$muestra
      },
      preparacion$orden_muestra,
      preparacion$orden_sql, preparacion$dialecto, preparacion$n_total,
      presupuesto, info_conexion, argumentos_muestra,
      muestreo = muestreo_meta, prototipo = preparacion$prototipo,
      tipos_declarados = preparacion$tipos, trazador = trazador,
      tipos_motor = preparacion$esquema$tipos_motor,
      max_celdas_muestra = max_celdas_muestra,
      max_bytes_muestra = max_bytes_muestra,
      enmascaradas = preparacion$enmascaradas
    )
  } else {
    .registrar_etapa_dbi(
      trazador, "lectura_muestra", estado = "no_solicitado"
    )
    .registrar_etapa_dbi(
      trazador, "perfilado_muestra", estado = "no_solicitado"
    )
    list(
      perfil = NULL,
      cobertura = .registro_cobertura_dbi(
        "perfil_muestra", .texto_tabla_dbi(tabla), "no_solicitado",
        paste(
          "No se solicit\u00f3 el perfil de muestra: este resultado contiene",
          "\u00fanicamente los agregados SQL de la configuraci\u00f3n elegida."
        ),
        paste(
          "Para obtener diagn\u00f3sticos sobre valores y hallazgos por fila, volver",
          "a perfilar con `bloque_muestra = \"con_muestra\"`."
        )
      ),
      muestreo = NULL
    )
  }
  if (!is.null(muestreo_publico) && !is.null(bloque$muestreo)) {
    if (is.null(fuente_muestreada) &&
        length(motivo_fuente_muestreada_sql) == 1L &&
        !is.na(motivo_fuente_muestreada_sql) &&
        nzchar(motivo_fuente_muestreada_sql)) {
      bloque$muestreo$motivo_filas_obtenidas <-
        motivo_fuente_muestreada_sql
    }
    muestreo_publico <- .publicar_muestreo_dbi(
      preparacion$muestreo, fuente_muestreada, preparacion$n_total,
      muestreo_meta = bloque$muestreo
    )
  }
  if (identical(preparacion$universo, "muestra_motor")) {
    if (!is.null(muestreo_publico) &&
        length(resumen$meta$filas_obtenidas_muestra) == 1L &&
        is.finite(resumen$meta$filas_obtenidas_muestra) &&
        (is.null(muestreo_publico$filas_obtenidas) ||
         is.na(muestreo_publico$filas_obtenidas))) {
      muestreo_publico$filas_obtenidas <-
        resumen$meta$filas_obtenidas_muestra
      muestreo_publico$motivo_filas_obtenidas <- NA_character_
    }
    resumen$meta$muestreo <- muestreo_publico
    resumen$meta$orden_muestra <- .orden_muestra_publica_dbi(
      preparacion$orden_muestra, resumen$meta$muestreo
    )
    if (!is.null(presupuesto$guardia_newid) &&
        !is.null(resumen$meta$muestreo)) {
      resumen$meta$muestreo$politica_newid <- presupuesto$guardia_newid
    }
  }
  cobertura <- rbind(cobertura, bloque$cobertura)
  resumen$tiempos <- .resumen_tiempos_dbi(trazador)
  if (isTRUE(presupuesto$agotado)) {
    cobertura <- rbind(cobertura, .registro_cobertura_dbi(
      "resumen_tabla", .texto_tabla_dbi(tabla), "presupuesto_agotado",
      .motivo_presupuesto_dbi(presupuesto),
      paste0(
        "Subir `max_consultas` o reducir el trabajo con `universo`, `metricas` o la estrategia elegida. ",
        "El plan previo est\u00e1 en `meta$plan` y en plan_perfilado_dbi()."
      ),
      NA_character_
    ))
  }
  rownames(cobertura) <- NULL
  resumen$meta$consultas <- list(
    emitidas = presupuesto$usadas,
    presupuesto = presupuesto$max,
    agotado = isTRUE(presupuesto$agotado),
    fallas = .publicar_fallas_consultas_dbi(presupuesto),
    sondas_fallidas = .publicar_fallas_sondas_dbi(presupuesto)
  )
  fallas_consultas <- resumen$meta$consultas$fallas
  if (is.data.frame(fallas_consultas) && nrow(fallas_consultas)) {
    cobertura <- rbind(cobertura, .registro_cobertura_dbi(
      "resumen_tabla", .texto_tabla_dbi(tabla), "degradado",
      paste0(
        "Fallaron ", nrow(fallas_consultas),
        if (nrow(fallas_consultas) == 1L) " consulta solicitada; revisar" else " consultas solicitadas; revisar",
        " `resumen_tabla$meta$consultas$fallas`."
      ),
      "Revisar el motivo del motor, reducir el alcance o usar `muestra_motor`.",
      NA_character_
    ))
  }
  rownames(cobertura) <- NULL
  resumen$cobertura <- cobertura

  argumentos <- argumentos_muestra
  proteger <- .protege_argumentos(argumentos)
  if (proteger) {
    # La misma funcion que la via por bloques: ver
    # `.proteger_salida_muestra_dbi()`.
    protegido <- .proteger_salida_muestra_dbi(
      resumen, bloque, conexion, preparacion, presupuesto
    )
    resumen <- protegido$resumen
    bloque$perfil <- protegido$perfil
  } else {
    resumen$meta$proteccion_personal <- list(
      aplicada = FALSE, base = "desactivada por el usuario",
      columnas = character()
    )
  }
  # Aca, y ademas en `.sellar_perfil_dbi()`. No es redundancia ociosa: la
  # corroboracion cruza este bloque contra el perfil de la muestra, que ya paso
  # por `perfilar()` y por lo tanto ya callo la moda inexistente. Si la regla se
  # aplicara solo al sellar, la corroboracion compararia el valor crudo de un
  # lado contra el NA del otro y declararia una divergencia que el resultado
  # final desmiente. Va despues de proteger, para no pisar el marcador.
  resumen$columnas <- .callar_moda_sin_empate(resumen$columnas)
  resumen$literales <- NULL

  if (is.null(bloque$perfil) && any(bloque$cobertura$estado == "no_disponible")) {
    motivos <- bloque$cobertura$motivo[
      bloque$cobertura$estado == "no_disponible"
    ]
    .avisar_muestra_motor_dbi(paste0(
      "El resumen SQL se calcul\u00f3 y se devuelve, pero la muestra no: ",
      paste(motivos, collapse = " "),
      " Ver `resumen_tabla$cobertura`."
    ), conserva_clase_vieja = TRUE)
  }

  if (is.data.frame(fallas_consultas) && nrow(fallas_consultas)) {
    .avisar_muestra_motor_dbi(
      paste0(
        "Una o m\u00e1s consultas solicitadas no estuvieron disponibles (",
        nrow(fallas_consultas), "). El detalle queda en",
        " `resumen_tabla$meta$consultas$fallas`."
      ),
      datos = list(fallas = fallas_consultas)
    )
  }
  if (identical(preparacion$universo, "muestra_motor") &&
      identical(preparacion$bloque_muestra, "solo_agregados") &&
      isTRUE(muestra_corta_sql)) {
    .avisar_muestra_motor_dbi(
      paste0(
        "La muestra del motor se degrad\u00f3: se obtuvieron ",
        .entero_sql_dbi(filas_obtenidas_muestreo_sql), " de menos de la mitad",
        " de las filas pedidas. El detalle queda en `meta$muestreo`."
      ),
      datos = list(
        filas_pedidas = preparacion$muestra_motor,
        filas_obtenidas = filas_obtenidas_muestreo_sql,
        reintentos = reintentos_muestreo_sql,
        metodo = muestreo_publico$metodo
      )
    )
  }

  if (isTRUE(derrame$disponible) && derrame$consultas_con_derrame > 0) {
    .avisar_dbi("lupa_aviso_derrame_dbi", paste0(
      "Se observ\u00f3 derrame real en ", derrame$consultas_con_derrame,
      if (derrame$consultas_con_derrame == 1L) " consulta exacta de distintos, moda o mediana: " else
        " consultas exactas de distintos, moda o mediana: ",
      derrame$bloques_temporales_leidos,
      if (derrame$bloques_temporales_leidos == 1L) " bloque temporal le\u00eddo y " else " bloques temporales le\u00eddos y ",
      derrame$bloques_temporales_escritos,
      if (derrame$bloques_temporales_escritos == 1L) " escrito. Fuente: `" else " escritos. Fuente: `", derrame$fuente,
      "`. El detalle queda en `resumen_tabla$sql`."
    ))
  }

  estructura <- list(resumen_tabla = resumen, perfil_muestra = bloque$perfil)
  estructura <- .declarar_afirmados_sin_valor_dbi(estructura, preparacion)
  estructura <- .declarar_enmascaradas_dbi(estructura, preparacion)
  estructura <- .agregar_cobertura_corroboracion_dbi(
    estructura, columnas_codigo = columnas_codigo,
    columnas_opcionales = columnas_opcionales, aplicabilidad = aplicabilidad,
    sentinelas_numericos = sentinelas_numericos
  )
  estructura <- .agregar_cobertura_politicas_muestra_dbi(
    estructura, aplicabilidad = aplicabilidad,
    columnas_opcionales = columnas_opcionales,
    sentinelas_numericos = sentinelas_numericos,
    columnas_codigo = columnas_codigo,
    lectura_convertida = preparacion$lectura_convertida,
    cobertura_texto = .cobertura_texto_controlador_dbi(
      conexion, tabla, preparacion$campos, preparacion$tipos,
      .texto_anotado_desde_dbi(conexion, texto_previo)
    )
  )
    estructura <- .aplicar_guardas_salida_muestra_dbi(
      estructura, incluir_valores = incluir_valores
    )
  estructura <- .sellar_perfil_dbi(estructura)
  estructura
}

.texto_clave_dbi <- function(clave) {
  if (!is.list(clave) || is.null(clave$garantia)) return(NULL)
  columnas <- if (length(clave$columnas)) {
    paste0("`", paste(as.character(clave$columnas), collapse = "`, `"), "`")
  } else {
    "ninguna"
  }
  fuente <- if (length(clave$fuente) && !is.na(clave$fuente[[1L]])) {
    paste0(" (fuente `", as.character(clave$fuente[[1L]]), "`)")
  } else {
    ""
  }
  estado <- clave$estado
  visible <- if (is.list(estado) && length(estado$visible)) {
    estado$visible[[1L]]
  } else {
    NA
  }
  motivo <- if (length(clave$motivo) && !all(is.na(clave$motivo))) {
    paste(as.character(clave$motivo), collapse = " ")
  } else {
    ""
  }
  if (is.na(visible)) {
    texto <- "no se pudo preguntar al cat\u00e1logo"
    if (nzchar(motivo)) texto <- paste0(texto, ": ", motivo)
  } else if (identical(visible, FALSE)) {
    texto <- "el cat\u00e1logo no deja ver la clave"
  } else if (identical(clave$garantia, "no_declarada")) {
    texto <- "no declara clave"
  } else {
    texto <- paste0("garant\u00eda `", as.character(clave$garantia), "` en ", columnas)
  }
  detalles <- character()
  if (is.list(estado) && isTRUE(estado$restriccion_diferible)) {
    detalles <- c(detalles, "restricci\u00f3n diferible")
  }
  if (is.list(estado) && isTRUE(estado$universo_incluye_descendientes)) {
    detalles <- c(detalles, "universo con descendientes")
  }
  if (is.list(estado) && isTRUE(estado$indice_no_unico)) {
    detalles <- c(detalles, "\u00edndice no \u00fanico")
  }
  if (length(detalles)) {
    texto <- paste0(texto, " (", paste(detalles, collapse = "; "), ")")
  }
  paste0("Clave primaria: ", texto, fuente, ".")
}

# Columnas cuya consulta de valores fue parte de la corrida. La estimacion
# debe describir el mismo subconjunto que el aviso emitido antes de consultar.
.columnas_estimacion_derrame_publicadas_dbi <- function(x, familia, estimacion) {
  if (is.null(estimacion) || !is.data.frame(estimacion$columnas) ||
      !nrow(estimacion$columnas)) return(character())
  sql <- x$resumen_tabla$sql
  nombre <- familia
  if (!is.data.frame(sql) || !all(c("columna", "metrica", "estado") %in% names(sql))) {
    return(character())
  }
  estados_omitidos <- c("no_solicitado", "omitido_por_costo",
                        "omitido_por_privacidad")
  ejecutadas <- unique(as.character(sql$columna[
    sql$metrica == nombre & !(sql$estado %in% estados_omitidos)
  ]))
  columnas_estimacion <- as.character(estimacion$columnas$columna)
  columnas_estimacion[
    !is.na(.indice_nombre(columnas_estimacion, ejecutadas))
  ]
}

#' @export
print.perfil_dbi <- function(x, ...) {
  original <- x
  x <- .marcar_objeto_para_exhibir(x)
  meta <- x$resumen_tabla$meta
  alcance <- if (identical(meta$alcance, "tabla_muestreada") ||
                 identical(meta$alcance_texto, "tabla_muestreada") ||
                 (is.list(meta$alcance) &&
                  identical(meta$alcance$universo_id, "muestra_motor"))) {
    "tabla muestreada"
  } else {
    "tabla completa"
  }
  cli::cli_text("Perfil DBI de {.strong {meta$tabla}}")
  n_columnas <- nrow(x$resumen_tabla$columnas)
  n_filas <- suppressWarnings(as.numeric(meta$filas))
  palabra_filas <- if (isTRUE(n_filas == 1)) "fila" else "filas"
  cli::cli_text(
    "Resumen de {alcance}: {n_columnas} columna{?s} sobre {meta$filas} {palabra_filas}"
  )
  texto_clave <- .texto_clave_dbi(meta$clave)
  if (!is.null(texto_clave)) cli::cli_text(.cli_literal(texto_clave))
  estados <- table(.factor_por_bytes(x$resumen_tabla$sql$estado))
  if (length(estados)) {
    detalle <- paste0(names(estados), " ", as.integer(estados), collapse = ", ")
    cli::cli_text("M\u00e9tricas: {detalle}")
  }
  if (!is.null(meta$consultas)) {
    cli::cli_text(
      "Consultas emitidas: {meta$consultas$emitidas} (dialecto {meta$dialecto$nombre})"
    )
  }
  estimacion <- meta$estimacion_derrame
  if (!is.null(estimacion) && !identical(estimacion$estado, "no_solicitado")) {
    if (identical(estimacion$estado, "estimado") ||
        identical(estimacion$estado, "parcial")) {
      detalle_estimacion <- if (identical(estimacion$estado, "parcial")) {
        paste("parcial;", estimacion$motivo)
      } else if (isTRUE(estimacion$supera_memoria)) {
        paste(
          "el tama\u00f1o estimado supera el l\u00edmite efectivo para hash de",
          estimacion$memoria_efectiva
        )
      } else {
        paste(
          "el tama\u00f1o estimado no supera el l\u00edmite efectivo para hash de",
          estimacion$memoria_efectiva,
          "; esto no demuestra que no haya derrame"
        )
      }
      cli::cli_text(.cli_literal(paste0(
        "Derrame estimado (no medido): ", detalle_estimacion,
        ". Fuente: `", estimacion$fuente, "`."
      )))
    } else {
      cli::cli_text(.cli_literal(paste0(
        "Derrame estimado: no se pudo estimar (", estimacion$motivo, ")."
      )))
    }
  }
  for (familia in c("moda", "mediana")) {
    nombre <- paste0("estimacion_derrame_", familia)
    estimacion_familia <- meta[[nombre]]
    if (is.null(estimacion_familia) ||
        identical(estimacion_familia$estado, "no_solicitado")) next
    columnas_estimadas <- .columnas_estimacion_derrame_publicadas_dbi(
      x, familia, estimacion_familia
    )
    if (!length(columnas_estimadas)) next
    estimacion_familia <- .filtrar_estimacion_derrame_dbi(
      estimacion_familia, columnas_estimadas
    )
    limite <- .limite_decision_derrame_dbi(estimacion_familia, familia)
    detalle <- if (isTRUE(estimacion_familia$supera_memoria)) {
      paste("supera el l\u00edmite de decisi\u00f3n", limite)
    } else if (identical(estimacion_familia$estado, "estimado")) {
      paste("no supera el l\u00edmite de decisi\u00f3n", limite)
    } else estimacion_familia$motivo
    cli::cli_text(.cli_literal(paste0(
      "Derrame estimado de ", familia, " (no medido): ", detalle,
      ". M\u00e9todo/forma: ", estimacion_familia$metodo, "/",
      estimacion_familia$forma, ". Fuente: `", estimacion_familia$fuente, "`."
    )))
  }
  derrame <- meta$derrame
  if (!is.null(derrame) && !identical(derrame$estado, "no_solicitado")) {
    if (isTRUE(derrame$disponible)) {
      cli::cli_text(
        "Derrame medido: {derrame$consultas_con_derrame} consulta{?s}, ",
        "{derrame$bloques_temporales_leidos} bloque{?s} temporal{?es} le\u00eddo{?s}, ",
        "{derrame$bloques_temporales_escritos} escrito{?s}."
      )
    } else {
      cli::cli_text(
        "Derrame: no disponible ({derrame$motivo})."
      )
    }
  }
  estado_muestra <- .estado_bloque_muestra_dbi(x)
  if (identical(estado_muestra, "no_solicitado")) {
    cli::cli_text(
      "Perfil de muestra: no solicitado; el motivo est\u00e1 en `resumen_tabla$cobertura`."
    )
  } else if (is.null(x$perfil_muestra)) {
    cli::cli_text(
      "Perfil de muestra: no disponible; el motivo est\u00e1 en `resumen_tabla$cobertura`."
    )
  } else {
    muestreo <- x$perfil_muestra$meta$origen_dbi$muestreo
    filas_muestra <- suppressWarnings(as.numeric(muestreo$filas_obtenidas))
    if (length(filas_muestra) == 1L && is.finite(filas_muestra)) {
      cli::cli_text(
        "Perfil de muestra: {muestreo$filas_obtenidas} fila{?s}, reproducible: {muestreo$reproducible}"
      )
    } else {
      # Sin un conteo no hay cantidad que pluralizar: con `NA`, cli aborta.
      cli::cli_text(
        "Perfil de muestra: sin conteo de filas; el motivo est\u00e1 en `resumen_tabla$cobertura`. ",
        "Reproducible: {muestreo$reproducible}"
      )
    }
  }
  n_cobertura <- if (is.null(x$resumen_tabla$cobertura)) {
    0L
  } else {
    nrow(x$resumen_tabla$cobertura)
  }
  if (n_cobertura) {
    cli::cli_text(
      "Cobertura de m\u00e9tricas SQL: {n_cobertura} anotaci{?\u00f3n/ones} en `resumen_tabla$cobertura`"
    )
  }
  # El objeto tiene DOS coberturas y esta impresion solo nombraba una. La otra
  # -que diagnosticos no se evaluaron sobre la muestra- es la que contesta "y
  # de lo demas, se miro todo?", y quedaba invisible: `cobertura()` sobre un
  # perfil DBI devuelve la de metricas SQL, asi que ni el accesor ni la
  # impresion la mostraban. Un perfil con tres diagnosticos sin evaluar se leia
  # como un perfil sin silencios.
  diagnosticos_muestra <- if (is.null(x$perfil_muestra)) {
    NULL
  } else {
    x$perfil_muestra$cobertura_diagnosticos
  }
  if (inherits(diagnosticos_muestra, "data.frame") &&
      nrow(diagnosticos_muestra)) {
    n_diagnosticos <- nrow(diagnosticos_muestra)
    cli::cli_text(
      "Diagn\u00f3sticos no evaluados sobre la muestra: {n_diagnosticos}, ",
      "en `perfil_muestra$cobertura_diagnosticos`"
    )
  }
  proteccion <- meta$proteccion_personal
  if (!is.null(proteccion) && isTRUE(proteccion$aplicada)) {
    n_protegidas <- length(proteccion$columnas)
    cli::cli_text(
      "Protecci\u00f3n de datos personales aplicada a {n_protegidas} columna{?/s}."
    )
  }
  aproximaciones <- meta$aproximaciones
  if (length(aproximaciones)) {
    aplicada <- vapply(
      aproximaciones, function(a) isTRUE(a$disponible), logical(1L)
    )
    if (any(aplicada)) {
      detalle <- paste(
        paste0(
          names(aproximaciones)[aplicada], " por ",
          vapply(aproximaciones[aplicada], function(a) a$metodo, character(1L))
        ),
        collapse = " y "
      )
      cli::cli_text(
        "Aproximaciones aplicadas: {detalle}. El error esperado y las sondas ",
        "est\u00e1n en `resumen_tabla$meta$aproximaciones`."
      )
    }
    if (any(!aplicada)) {
      sin_aproximar <- paste(
        names(aproximaciones)[!aplicada], collapse = " y "
      )
      cierre <- if (sum(!aplicada) > 1L) {
        "las m\u00e9tricas se midieron exactas."
      } else {
        "la m\u00e9trica se midi\u00f3 exacta."
      }
      cli::cli_text(
        "Sin aproximaci\u00f3n para {sin_aproximar}: el motor no la ",
        "acept\u00f3 y {cierre}"
      )
    }
  }
  cli::cli_text(
    "No se imprime ning\u00fan valor de celda: est\u00e1n en `resumen_tabla$columnas`."
  )
  invisible(original)
}
